/*
 * Raspberry Pi 4 Model B - MLX91219 Current Sensor via ADS1115
 *
 * Wiring:
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   ADS1115 SDA  -> GPIO2 (I2C bus 1)
 *   ADS1115 SCL  -> GPIO3 (I2C bus 1)
 *   ADS1115 AIN0 -> MLX91219 V_OUT
 *   ADS1115 VDD  -> 3.3V
 *   ADS1115 GND  -> GND
 *
 * Build: gcc -Wall -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/*
 * Config register bit fields (16-bit, big-endian on the wire):
 *   Bit 15    OS       = 1 (begin single conversion)
 *   Bits 14:12 MUX    = 100 (AIN0 single-ended)
 *   Bits 11:9  PGA    = 001 (±4.096V)
 *   Bit  8     MODE   = 1 (single-shot)
 *   Bits 7:5   DR     = 100 (128 SPS)
 *   Bit  4     COMP_MODE = 0
 *   Bits 3:1   COMP_POL  = 00
 *   Bit  0     COMP_LAT  = 0
 */
#define ADS1115_CONFIG_BASE 0x8483

/* Sensitivity of MLX91219 at 5 V supply: 40 mV/A */
#define MLX91219_SENSITIVITY_MV_PER_A  40.0f

/* PGA ±4.096V full-scale range: 1 bit = 125 µV */
#define ADS1115_PGA_4096_LSB_UV  125.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData expects the register address followed by
 * the data bytes, so we pack the 16-bit value big-endian.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadI2CBlockData returns the data as a string; we reassemble
 * it big-endian.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and wait for completion.
 * Returns the signed 16-bit ADC code, or 0 on error.
 */
static int16_t ads1115_read_ain0(int handle)
{
    uint16_t config = ADS1115_CONFIG_BASE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0)
        return 0;

    /*
     * Wait for conversion to complete.
     * At 128 SPS the conversion takes ~7.8 ms; poll every 10 ms.
     */
    for (int i = 0; i < 10; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) < 0)
            return 0;
        if (cfg & 0x8000)
            break;
        gpioDelay(10000); /* 10 ms */
    }

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) < 0)
        return 0;

    return (int16_t)raw;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) - sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the default config register */
    uint16_t cfg_check;
    if (ads1115_read_reg(g_i2c_handle, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "Error: ADS1115 not responding at address 0x%02X\n", I2C_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 Current Monitor\n");
    printf("ADS1115 at I2C 0x%02X, AIN0 single-ended, PGA ±4.096V, 128 SPS\n", I2C_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t adc_code = ads1115_read_ain0(g_i2c_handle);

        if (adc_code == 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(500000);
            continue;
        }

        /* Convert raw ADC code to voltage (PGA ±4.096V) */
        float voltage_uv = (float)adc_code * ADS1115_PGA_4096_LSB_UV;
        float voltage_v = voltage_uv / 1000000.0f;

        /*
         * MLX91219 output is mid-supply at zero current.
         * Current = (voltage_v - V_mid) / sensitivity_mV_per_A
         */
        float current_a = (voltage_v - 2.5f) / (MLX91219_SENSITIVITY_MV_PER_A / 1000.0f);

        printf("Current: %.3f A\n", current_a);

        gpioDelay(500000); /* 500 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

