#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_BASE 0x8000  /* AIN0 single-ended, +/-4.096V, 128 SPS, single-shot */
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define TEMPERATURE_THRESHOLD 60.0
#define DEBOUNCE_MS 50
#define BUZZER_DURATION_MS 2000
#define POLL_INTERVAL_US 100000
#define ADC_CONV_TIME_US 9000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t flame_event = 0;
static volatile uint32_t last_flame_tick = 0;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void flame_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {  /* falling edge: flame detected (KY-026 digital output LOW) */
        uint32_t elapsed = tick - last_flame_tick;
        if (elapsed > DEBOUNCE_MS * 1000) {
            flame_event = 1;
            last_flame_tick = tick;
        }
    }
}

static int read_temperature(double *temperature) {
    char config[3];
    char reg = ADS1115_CONFIG_REG;
    char conv_reg = ADS1115_CONVERSION_REG;
    char conv_buf[2];
    int16_t raw;

    config[0] = ADS1115_CONFIG_REG;
    config[1] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_CQUE_NONE) & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config register.\n");
        return -1;
    }

    gpioDelay(ADC_CONV_TIME_US);

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to select ADS1115 conversion register.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, conv_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion register.\n");
        return -1;
    }

    raw = (int16_t)((conv_buf[0] << 8) | conv_buf[1]);
    /* ±4.096V range: 1 bit = 125 µV; raw is signed 16-bit */
    double voltage = raw * 0.000125;
    *temperature = (voltage / 3.3) * 60.0 + 20.0;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open fire_log.txt for appending.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_callback) != 0) {
        fprintf(stderr, "Error: Failed to register ISR for flame sensor.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");
    log_message("System started.");

    while (running) {
        if (flame_event) {
            double temperature = 0.0;
            int temp_ok = read_temperature(&temperature);

            if (temp_ok == 0) {
                if (temperature > TEMPERATURE_THRESHOLD) {
                    char msg[128];
                    snprintf(msg, sizeof(msg),
                             "Flame and temperature exceeded threshold! Flame detected, Temperature: %.2f°C",
                             temperature);
                    log_message(msg);
                    gpioWrite(BUZZER_PIN, 1);
                    gpioDelay(BUZZER_DURATION_MS * 1000);
                    gpioWrite(BUZZER_PIN, 0);
                } else {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Flame detected! Temperature: %.2f°C", temperature);
                    log_message(msg);
                }
            } else {
                log_message("Error reading temperature sensor.");
            }
            flame_event = 0;
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFunc(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL);
    log_message("System stopped.");
    cleanup();
    return 0;
}

