/*
 * MLX91219 Current Sensor Monitor with Fan Control
 *
 * Hardware:
 *   - Raspberry Pi 5 (SPI0 CE0 = GPIO8, GPIO18 = fan control)
 *   - MCP3008 10-bit ADC on SPI0 (channel 0, VREF = 3.3 V)
 *   - Melexis MLX91219 analog output connected to MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lgpiod
 *
 * Run:
 *   ./current_monitor [-s sensitivity_mV_per_A] [-t threshold_A]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define FAN_GPIO_LINE   18
#define GPIO_CHIP_NAME  "gpiochip4"   /* Pi 5 GPIO chip name */
#define GPIO_CHIP_NAME_FALLBACK "gpiochip0"

#define LOG_FILE        "current_log.txt"
#define SAMPLE_INTERVAL_SEC 1

#define ADC_VREF        3.3f
#define ADC_MAX         1023.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read MCP3008 single-ended channel (0-7).
 * Returns 0-1023 on success, -1 on error.
 */
static int mcp3008_read(int spi_fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI command (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
