#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/*
 * MICS-4514 calibration parameters (example values).
 * Replace with actual calibration data from the datasheet.
 */
#define CO_OFFSET 100.0
#define CO_SCALE 0.01
#define CO_MIN_PPM 0.0
#define CO_MAX_PPM 1000.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Simulate reading a 16-bit ADC value for the CO element.
 * In a real deployment, this would be replaced with a proper I2C ADC read.
 */
static int read_co_adc(int handle, int *adc_value) {
    /*
     * In a real deployment, this would be an I2C read from an ADS1115
     * configured for single-ended channel 0. For this example, we return
     * a random 16-bit value to simulate the sensor's output.
     */
    *adc_value = rand() & 0xFFFF;
    return 0;
}

static double calculate_co_ppm(int adc_value) {
    double resistance = (double)adc_value;
    double ppm = CO_OFFSET + CO_SCALE * resistance;

    if (ppm < CO_MIN_PPM) ppm = CO_MIN_PPM;
    if (ppm > CO_MAX_PPM) ppm = CO_MAX_PPM;

    return ppm;
}

static int log_co_data(double ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));

    while (running) {
        int adc_value = 0;

        if (read_co_adc(i2c_handle, &adc_value) != 0) {
            fprintf(stderr, "Error reading CO sensor data\n");
        } else {
            double ppm = calculate_co_ppm(adc_value);
            if (log_co_data(ppm) != 0) {
                fprintf(stderr, "Error logging CO data\n");
            }
        }

        /*
         * Sleep in 1-second increments to allow signal handler to interrupt
         * promptly.
         */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

