static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4 (single-ended + channel)
     * tx[2] = 0x00 (don't care)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits)
