#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL 5

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int *co_value, int *no2_value) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    *co_value = (buf[0] << 8) | buf[1];
    *no2_value = (buf[2] << 8) | buf[3];
    return 0;
}

static float calculate_co_ppm(int co_value, int no2_value) {
    (void)no2_value;
    return (float)co_value * 0.1;
}

static void log_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
}

static void check_co_threshold(float co_ppm) {
    if (co_ppm > CO_THRESHOLD) {
        FILE *fp = fopen(ALERT_FILE, "a");
        if (fp == NULL) {
            perror("Error opening alert log file");
            return;
        }
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO level exceeded threshold: %.2f PPM\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
        fclose(fp);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO Monitoring System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int co_value, no2_value;
        if (read_sensor_data(&co_value, &no2_value) == 0) {
            float co_ppm = calculate_co_ppm(co_value, no2_value);
            log_data(co_ppm);
            check_co_threshold(co_ppm);
            printf("CO: %.2f PPM\n", co_ppm);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", READ_INTERVAL);
        }
        sleep(READ_INTERVAL);
    }

    cleanup();
    printf("CO Monitoring System stopped.\n");
    return 0;
}

