#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "audio_log.txt"

/* IMP23ABSU sensitivity: -38 dBV/Pa (38000 Pa/V).
   Reference pressure: 20e-6 Pa. */
#define SENSITIVITY_DBV_PER_PA -38.0
#define REFERENCE_PRESSURE 20e-6

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 16-bit signed value from an I2C device register.
   Returns 0 on success, -1 on error. */
static int read_i2c_word(int handle, int reg, int16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Convert raw 16-bit signed value to dB. */
static double raw_to_db(int16_t raw) {
    double voltage = (double)raw / 32768.0; /* 16-bit signed full-scale */
    double pressure = voltage * 1000.0 / pow(10.0, SENSITIVITY_DBV_PER_PA / 20.0);
    return 20.0 * log10(pressure / REFERENCE_PRESSURE);
}

static void log_data(double db1, double db2, double avg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, db1, db2, avg);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C for mic1 (addr 0x%02X): %d\n", MIC1_ADDR, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C for mic2 (addr 0x%02X): %d\n", MIC2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int16_t raw1 = 0, raw2 = 0;
        double db1 = -999.0, db2 = -999.0;
        double avg = -999.0;

        if (read_i2c_word(i2c_handle1, 0, &raw1) == 0) {
            db1 = raw_to_db(raw1);
        } else {
            fprintf(stderr, "Error reading mic1\n");
        }

        if (read_i2c_word(i2c_handle2, 0, &raw2) == 0) {
            db2 = raw_to_db(raw2);
        } else {
            fprintf(stderr, "Error reading mic2\n");
        }

        if (db1 > -999.0 && db2 > -999.0) {
            avg = (db1 + db2) / 2.0;
        }

        log_data(db1, db2, avg);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

