#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MIC1_ADC_CHANNEL 0
#define MIC2_ADC_CHANNEL 1
#define LED_GPIO 27
#define THRESHOLD 0.7f
#define NUM_SAMPLES 100
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define LED_ON_TIME_US 500000   // 500 ms
#define CSV_FILE "audio_events.csv"

// Global variables
int spi_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float calculate_rms(int *data, int num_samples);
void control_led(int state);
void log_data(float mic1_rms, float mic2_rms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01;                                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;                 // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                                  // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate RMS value from ADC data
float calculate_rms(int *data, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double normalized_value = (double)data[i] / 1023.0; // Normalize to 0-1
        sum_of_squares += pow(normalized_value, 2);
    }
    return (float)sqrt(sum_of_squares / num_samples);
}

