    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int mic1_data[NUM_SAMPLES];
        int mic2_data[NUM_SAMPLES];

        // Sample audio data from both microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_data[i] = read_adc(MIC1_ADC_CHANNEL);
            mic2_data[i] = read_adc(MIC2_ADC_CHANNEL);
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        // Calculate RMS values
        float mic1_rms = calculate_rms(mic1_data, NUM_SAMPLES);
        float mic2_rms = calculate_rms(mic2_data, NUM_SAMPLES);

        // Log data to CSV file
        log_data(mic1_rms, mic2_rms);

        // Check threshold and control LED
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            control_led(1); // Turn LED on
            gpioDelay(LED_ON_TIME_US);
            control_led(0); // Turn LED off
