#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define CURRENT_THRESHOLD 50.0 // Amperes
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SUPPLY_VOLTAGE 5.0
#define SENSOR_V_MIN 0.5
#define SENSOR_V_MAX 4.5
#define SENSOR_A_MAX 100.0

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: Single-shot, A0, PGA 4.096V, 128 SPS, Disable comparator
#define ADS1115_CONFIG_BASE 0x8000 | (0x4000) | (0x0000) | (0x0080) | (0x0003)

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer;

// Function prototypes
int initialize_i2c();
int16_t read_ads1115_raw(int handle);
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit value from ADS1115
int16_t read_ads1115_raw(int handle) {
    char config_buf[3];
    char read_buf[2];
    int16_t raw_value;

    // Write config to start a single conversion
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    config_buf[2] = ADS1115_CONFIG_BASE & 0xFF;

    if (i2cWriteDevice(handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return -1;
    }

    // Wait for conversion (128 SPS -> ~7.8ms, wait 10ms to be safe)
    gpioDelay(10000);

    // Read conversion result
    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONVERSION, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion\n");
        return -1;
    }

    raw_value = (int16_t)((read_buf[0] << 8) | read_buf[1]);
    return raw_value;
}

// Convert raw ADC value to current (Amperes)
float convert_to_current(int16_t raw_value) {
    // ADS1115: 16-bit signed, PGA 4.096V -> 1 bit = 0.125mV
    // For 4.096V range, 1 bit = 0.125mV = 0.000125V
    // Sensor output: 0.5V to 4.5V for 0A to 100A
    // V_out = 0.5 + (current/100) * (4.5 - 0.5)
    // current = (V_out - 0.5) * 100 / (4.5 - 0.5)
    float voltage = (raw_value * 0.000125f) * SUPPLY_VOLTAGE;
    float current = (voltage - SENSOR_V_MIN) * SENSOR_A_MAX / (SENSOR_V_MAX - SENSOR_V_MIN);
    return current;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of values in circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&current_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        int16_t raw_value = read_ads1115_raw(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Add to buffer
        add_to_buffer(&current_buffer, current);

        // Calculate average
        float average_current = calculate_average(&current_buffer);

        // Control LED
        control_led(average_current);

        // Print current and average
        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        // Delay to achieve desired sample rate
        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    // Cleanup
    cleanup();
    return 0;
}

