#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define MAX_READ_FAILS 10

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open the log file once and write a header row.                      */
/* ------------------------------------------------------------------ */
static int open_log_file(void)
{
    g_log_file = fopen(LOG_FILE, "w");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
        perror("fprintf(header)");
        fclose(g_log_file);
        g_log_file = NULL;
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush(header)");
        fclose(g_log_file);
        g_log_file = NULL;
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the MLX90817.                */
/* Returns 0 on success (stores value in *out), -1 on error.           */
/* ------------------------------------------------------------------ */
static int read_pressure_raw(uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr,
                "I2C read error: reg=0x%02X, pigpio rc=%d\n",
                PRESSURE_REG, rc);
        return -1;
    }

    /* MLX90817 sends MSB first */
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit value to kPa.                                    */
/* ------------------------------------------------------------------ */
static float convert_to_kPa(uint16_t raw)
{
    return ((float)raw / 65535.0f) * 500.0f;
}

/* ------------------------------------------------------------------ */
/* Write one CSV row with an ISO 8601 UTC timestamp.                   */
/* ------------------------------------------------------------------ */
static int log_pressure(float pressure_kPa)
{
    time_t     now;
    struct tm  utc;
    char       ts[32];

    now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }
    if (gmtime_r(&now, &utc) == NULL) {
        perror("gmtime_r()");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        perror("fprintf(data)");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush(data)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int  read_failures = 0;
    int  rc;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr,
                "i2cOpen(bus=%d, addr=0x%02X) failed: pigpio rc=%d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- log file ---- */
    if (open_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90817 pressure logger started. Logging to %s every 1 s.\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        uint16_t raw;

        if (read_pressure_raw(&raw) != 0) {
            read_failures++;
            if (read_failures >= MAX_READ_FAILS) {
                fprintf(stderr,
                        "Too many consecutive read failures (%d). "
                        "Sensor may be absent or bus error.\n",
                        read_failures);
                break;
            }
            gpioDelay(SAMPLE_US);
            continue;
        }
        read_failures = 0;

        float pressure_kPa = convert_to_kPa(raw);

        if (log_pressure(pressure_kPa) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

