/*
 * MLX90834 Pressure & Temperature Monitor (Raspberry Pi 4 Model B)
 *
 * The MLX90834 is a SENT-only MEMS pressure sensor with no native I2C
 * interface.  This program reads its analog pressure output (AIN0) and
 * temperature (AIN1) via an ADS1115 ADC bridge at I2C address 0x48.
 *
 * Wiring:
 *   MLX90834 VDD  -> 3.3V (Pin 1)
 *   MLX90834 GND  -> GND  (Pin 9)
 *   MLX90834 OUT  -> ADS1115 AIN0
 *   MLX90834 VCC  -> 3.3V (Pin 1)
 *   MLX90834 NTC  -> ADS1115 AIN1
 *   ADS1115 VDD   -> 3.3V (Pin 1)
 *   ADS1115 GND   -> GND  (Pin 9)
 *   ADS1115 SDA   -> GPIO2 (Pin 3)
 *   ADS1115 SCL   -> GPIO3 (Pin 5)
 *   ADS1115 ADDR  -> GND  (address 0x48)
 *   LED anode     -> GPIO17 (Pin 11) via 330 ohm resistor
 *   LED cathode   -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o mlx90834 mlx90834.c -lpigpio -lrt
 * Run:   sudo ./mlx90834
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config register bit fields */
#define ADS1115_CFG_OS_BEGIN  (1u << 15)
#define ADS1115_CFG_MUX_AIN0  (0x4u << 12)   /* AIN0 single-ended */
#define ADS1115_CFG_MUX_AIN1  (0x5u << 12)   /* AIN1 single-ended */
#define ADS1115_CFG_PGA_6144  (0x0u << 9)    /* ±6.144 V (FSR) */
#define ADS1115_CFG_MODE_SS   (0x0u << 8)    /* Single-shot */
#define ADS1115_CFG_DR_128    (0x4u << 5)    /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x3u << 0)    /* Disable comparator */

#define LED_GPIO              17
#define PRESSURE_THRESHOLD    105.0f        /* kPa */
#define SAMPLE_PERIOD_US      1000000       /* 1 second */
#define MAX_RETRIES           3

/*
 * MLX90834 transfer function (linear approximation):
 *   pressure (kPa) = (voltage (V) - 0.0) / 0.00125 * 400.0
 *   voltage (V)    = (pressure (kPa) / 400.0) * 0.00125 + 0.0
 *
 * ADS1115 at ±6.144 V range:
 *   raw = voltage * 32768 / 6.144
 *   voltage = raw * 6.144 / 32768
 */
#define PRESSURE_SCALE        0.00125f      /* V/kPa */
#define PRESSURE_OFFSET       0.0f
#define ADS1115_FSR_6144      6.144f
#define ADS1115_MAX_RAW       32767.0f

/*
 * Simplified NTC transfer function (linear approximation):
 *   temp (°C) = (voltage (V) - 1.0) / 0.005 * 100.0
 *   voltage (V) = (temp (°C) / 100.0) * 0.005 + 1.0
 */
#define TEMP_SCALE            0.005f        /* V/°C */
#define TEMP_OFFSET           1.0f

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static int  ads1115_write_config(uint16_t config);
static int  ads1115_read_conversion(uint16_t *raw);
static int  read_pressure(float *pressure);
static int  read_temperature(float *temperature);
static void control_led(float pressure);
static void cleanup(void);

/* ------------------------------- Handlers --------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* --------------------------- ADS1115 helpers ------------------------------ */
static int ads1115_write_config(uint16_t config)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)((config >> 8) & 0xFF);
    buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (config) failed\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(uint16_t *raw)
{
    char buf[2];

    if (i2cReadI2CBlockData(g_i2c_handle, ADS1115_REG_CONV, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData (conversion) failed\n");
        return -1;
    }
    *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* --------------------------- Pressure / Temperature ----------------------- */
static int read_pressure(float *pressure)
{
    uint16_t raw = 0;
    int retries = MAX_RETRIES;

    while (retries-- > 0) {
        if (ads1115_write_config(ADS1115_CFG_OS_BEGIN |
                                 ADS1115_CFG_MUX_AIN0 |
                                 ADS1115_CFG_PGA_6144 |
                                 ADS1115_CFG_MODE_SS |
                                 ADS1115_CFG_DR_128 |
                                 ADS1115_CFG_CQUE_NONE) != 0) {
            gpioDelay(10000);
            continue;
        }

        /* Wait for conversion to complete (~8 ms at 128 SPS) */
        gpioDelay(10000);

        if (ads1115_read_conversion(&raw) != 0) {
            gpioDelay(10000);
            continue;
        }

        float voltage = ((float)raw / ADS1115_MAX_RAW) * ADS1115_FSR_6144;
        *pressure = (voltage - PRESSURE_OFFSET) / PRESSURE_SCALE * 400.0f;
        return 0;
    }

    fprintf(stderr, "[ERROR] Pressure read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static int read_temperature(float *temperature)
{
    uint16_t raw = 0;
    int retries = MAX_RETRIES;

    while (retries-- > 0) {
        if (ads1115_write_config(ADS1115_CFG_OS_BEGIN |
                                 ADS1115_CFG_MUX_AIN1 |
                                 ADS1115_CFG_PGA_6144 |
                                 ADS1115_CFG_MODE_SS |
                                 ADS1115_CFG_DR_128 |
                                 ADS1115_CFG_CQUE_NONE) != 0) {
            gpioDelay(10000);
            continue;
        }

        gpioDelay(10000);

        if (ads1115_read_conversion(&raw) != 0) {
            gpioDelay(10000);
            continue;
        }

        float voltage = ((float)raw / ADS1115_MAX_RAW) * ADS1115_FSR_6144;
        *temperature = (voltage - TEMP_OFFSET) / TEMP_SCALE * 100.0f;
        return 0;
    }

    fprintf(stderr, "[ERROR] Temperature read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* --------------------------------- LED control ---------------------------- */
static void control_led(float pressure)
{
    gpioWrite(LED_GPIO, (pressure > PRESSURE_THRESHOLD) ? 1 : 0);
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d) — sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(LED) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure & Temperature Monitor\n");
    printf("Pressure threshold: %.1f kPa | LED on GPIO%d\n",
           PRESSURE_THRESHOLD, LED_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        float pressure = 0.0f;
        float temperature = 0.0f;

        if (read_pressure(&pressure) != 0) {
            fprintf(stderr, "[WARN] Skipping sample due to pressure read failure\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "[WARN] Skipping sample due to temperature read failure\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        control_led(pressure);

        printf("Pressure: %7.2f kPa | Temperature: %5.2f °C | LED: %s\n",
               pressure, temperature,
               (pressure > PRESSURE_THRESHOLD) ? "ON" : "OFF");

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

