#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define CURRENT_THRESHOLD 10.0    /* Amperes */
#define SHUTDOWN_GPIO  27         /* GPIO27 - motor shutdown output */
#define SAMPLE_US      100000     /* 100 ms */
#define LOG_FILE       "current_log.txt"

/* MLX91209 constants (example values - adjust per datasheet) */
#define VCC_REF        3.3
#define ZERO_CURRENT_V (VCC_REF / 2.0)
#define SENSITIVITY_V_PER_A 0.066
#define ADC_MAX        1023.0

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 single-ended channel (0-7).          */
/* Returns 0-1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2-D0=channel, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
