#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* mode 0, active-low CE */
#define ADC_CHANNEL    0        /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023     /* 10-bit ADC */
#define METHANE_MAX    5000.0   /* PPM */
#define THRESHOLD_PPM  1000.0
#define LOG_FILE       "methane_log.txt"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 *
 * MCP3008 SPI command (3 bytes):
 *   tx[0] = 0x01                       start bit
 *   tx[1] = (0x08 | channel) << 4      single-ended + channel, upper nibble
 *   tx[2] = 0x00                       dummy for clocking data out
 * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_ppm(int adc_value)
{
    return ((double)adc_value / (double)ADC_MAX) * METHANE_MAX;
}

static void log_reading(double ppm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s, %.2f PPM\n", ts, ppm);
    fclose(fp);
}

static void check_alarm(double ppm)
{
    if (ppm > THRESHOLD_PPM) {
        fprintf(stderr, "ALARM: Methane concentration %.2f PPM exceeds threshold %.2f PPM\n",
                ppm, THRESHOLD_PPM);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Methane monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            /* SPI error already reported; skip this sample */
            gpioDelay(SAMPLE_US);
            continue;
        }

        double ppm = adc_to_ppm(adc);
        log_reading(ppm);
        check_alarm(ppm);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

