#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000 // AIN0 single-ended, +/-4.096V, 128 SPS, continuous
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define VREF 4.096
#define ADC_MAX 32767.0
#define SENSITIVITY 0.1 // V/kPa
#define OFFSET 0.5 // V at 0 kPa
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int16_t read_adc();
float convert_to_voltage(int16_t raw_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Initialize I2C and configure ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }

    // Configure ADS1115: AIN0 single-ended, +/-4.096V, 128 SPS, continuous
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_CQUE_NONE;
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int16_t read_adc() {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error setting ADS1115 conversion register\n");
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion\n");
        return -1;
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value) {
    return ((float)raw_value / ADC_MAX) * VREF;
}

// Convert voltage to pressure (kPa)
float convert_to_pressure(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Log pressure reading with ISO-8601 timestamp
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw_value = read_adc();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = convert_to_voltage(raw_value);
        float pressure = convert_to_pressure(voltage);

        if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure\n");
            }
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

