#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"
#define BETA 3950.0
#define R0 10000.0
#define VCC 5.0
#define VOUT_OFFSET 0.824
#define VOUT_SLOPE 0.0315

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_humidity(int adc_value) {
    float voltage = (adc_value / 4095.0) * VCC;
    return (voltage - VOUT_OFFSET) / VOUT_SLOPE;
}

static float calculate_temperature(int adc_value) {
    float voltage = (adc_value / 4095.0) * VCC;
    if (voltage <= 0.0) return -999.0;
    float ro = (R0 * (VCC - voltage)) / voltage;
    float tk = 1.0 / (1.0 / 298.15 - (1.0 / BETA) * log(ro / R0));
    return tk - 273.15;
}

static void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

static void send_email_alert(float humidity) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\n"
             "Humidity exceeded threshold!\n"
             "Timestamp: %s\n"
             "Humidity: %.2f%%\" | ssmtp %s",
             timestamp, humidity, EMAIL_RECIPIENT);

    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("popen failed");
        return;
    }
    pclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            sleep(1);
            continue;
        }

        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        if (humidity < 0.0 || humidity > 100.0 || temperature < -50.0 || temperature > 150.0) {
            fprintf(stderr, "Invalid sensor readings (humidity=%.2f, temp=%.2f), skipping\n", humidity, temperature);
            sleep(1);
            continue;
        }

        log_data(humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);
        sleep(5);
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

