 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> ADXL335 X-axis
 *   MCP3008 CH1  -> ADXL335 Y-axis
 *   MCP3008 CH2  -> ADXL335 Z-axis
 *   ADXL335 VDD  -> 3.3V
 *   ADXL335 GND  -> GND
 *   ADXL335 XOUT -> MCP3008 CH0
 *   ADXL335 YOUT -> MCP3008 CH1
 *   ADXL335 ZOUT -> MCP3008 CH2
 *
 * Build: gcc -Wall -Wextra -O2 -o impact_detector impact_detector.c -lpigpio -lrt
 * Run:   sudo ./impact_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                         */
#define SPI_SPEED      1000000    /* 1 MHz                                    */
#define SPI_FLAGS      0          /* Mode 0, active-low CS, 8-bit words        */

#define ADC_CHANNELS   3          /* X, Y, Z                                  */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC                               */

#define VREF           3.3f       /* MCP3008 reference voltage (V)            */
#define ADC_RESOLUTION (VREF / (ADC_MAX_VALUE + 1.0f)) /* 0.00322 V/count      */

/* ADXL335 parameters (3.3V supply) */
#define ADXL335_0G_V   1.65f      /* 0g output voltage (V)                    */
#define ADXL335_SENS   0.300f     /* 300 mV/g                                 */

#define IMPACT_THRESHOLD_G 2.0f   /* Impact detection threshold (g)           */
#define SAMPLE_RATE_HZ     100    /* Sampling rate (Hz)                       */
#define SAMPLE_PERIOD_US   (1000000 / SAMPLE_RATE_HZ) /* 10000 us            */

#define LOG_FILE_NAME  "impact_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static int      spi_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_adc(int channel);
static float voltage_to_g(float voltage);
static void log_data(int x, int y, int z, float x_g, float y_g, float z_g);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 * Returns the 10-bit ADC value (0-1023), or -1 on error.
 *
 * MCP3008 SPI protocol (Mode 0, MSB-first):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   Byte 2: 0x00                       (don't care, clocked out for data)
 * Response:
 *   rx[0] = don't care
 *   rx[1] = [null bit][b9 b8] in lower 2 bits
 *   rx[2] = b7..b0
 */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    /* Assert CS (active-low) */
    gpioWrite(SPI_CHANNEL, 0);

    int ret = spiXfer(spi_handle, tx, rx, 3);

    /* Deassert CS */
    gpioWrite(SPI_CHANNEL, 1);

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    /* Extract 10-bit result: lower 2 bits of rx[1] + rx[2] */
    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return value;
}

/* Convert ADC voltage to acceleration in g. */
static float voltage_to_g(float voltage)
{
    return (voltage - ADXL335_0G_V) / ADXL335_SENS;
}

/* Log one sample line to the CSV file. */
static void log_data(int x, int y, int z, float x_g, float y_g, float z_g)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f,%.3f,%.3f\n",
            timestamp, x, y, z, x_g, y_g, z_g);
    fflush(log_file);
}

/* Signal handler for graceful shutdown. */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Release all resources. */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_ADC,Y_ADC,Z_ADC,X_g,Y_g,Z_g\n");
        fflush(log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* Main sampling loop */
    while (!terminate) {
        int x = read_adc(0);
        int y = read_adc(1);
        int z = read_adc(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error - skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Validate ADC range */
        if (x > ADC_MAX_VALUE || y > ADC_MAX_VALUE || z > ADC_MAX_VALUE) {
            fprintf(stderr, "ADC value out of range (X=%d Y=%d Z=%d)\n", x, y, z);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float x_v = x * ADC_RESOLUTION;
        float y_v = y * ADC_RESOLUTION;
        float z_v = z * ADC_RESOLUTION;

        float x_g = voltage_to_g(x_v);
        float y_g = voltage_to_g(y_v);
        float z_g = voltage_to_g(z_v);

        log_data(x, y, z, x_g, y_g, z_g);

        /* Impact detection */
        if (fabsf(x_g) > IMPACT_THRESHOLD_G ||
            fabsf(y_g) > IMPACT_THRESHOLD_G ||
            fabsf(z_g) > IMPACT_THRESHOLD_G) {
            printf("IMPACT DETECTED! X=%.3f Y=%.3f Z=%.3f g\n", x_g, y_g, z_g);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

