/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   Si1172 SDA -> GPIO2 (pin 3)
 *   Si1172 SCL -> GPIO3 (pin 5)
 *   Si1172 VDD -> 3.3 V
 *   Si1172 GND -> GND
 *
 * Logs to biometric_log.csv once per second.
 *
 * NOTE: The Si1172 requires a proprietary algorithm to convert raw PPG
 *       photoplethysmography samples to HR/SpO2. This program logs the
 *       raw 16-bit IR and RED ADC values as proxy values for HR and SpO2.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1172_ADDR    0x49          /* Si1172 default 7-bit I2C address */

/* Si1172 register addresses */
#define SI1172_REG_HW_KEY      0x07
#define SI1172_REG_COMMAND     0xC0
#define SI1172_REG_FIFO_DATA   0xC1   /* 4 bytes: IR_LSB, IR_MSB, RED_LSB, RED_MSB */

/* Si1172 command codes */
#define SI1172_CMD_RESET       0x01
#define SI1172_CMD_ALS_FORCE   0x06

/* Error codes for the log file */
#define ERR_NONE              0
#define ERR_I2C_READ          1
#define ERR_SENSOR_ABSENT     2

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1172 register                            */
/* ------------------------------------------------------------------ */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1172 register                           */
/* ------------------------------------------------------------------ */
static int si1172_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 4 bytes from the Si1172 FIFO (IR LSB, IR MSB, RED LSB, RED MSB) */
/* ------------------------------------------------------------------ */
static int si1172_read_fifo(int handle, uint16_t *ir_raw, uint16_t *red_raw)
{
    char buf[4];

    int rc = i2cReadI2CBlockData(handle, SI1172_REG_FIFO_DATA, buf, 4);
    if (rc != 4) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(FIFO) returned %d (expected 4)\n", rc);
        return -1;
    }

    *ir_raw  = (uint16_t)((uint8_t)buf[1] << 8 | (uint8_t)buf[0]);
    *red_raw = (uint16_t)((uint8_t)buf[3] << 8 | (uint8_t)buf[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1172 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1172_init(int handle)
{
    /*
     * Proprietary initialization sequence for Si1172.
     * The exact sequence depends on the specific variant; this is a
     * representative placeholder that may need adjustments.
     */
    if (si1172_write_reg(handle, SI1172_REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Reset the device */
    if (si1172_write_reg(handle, SI1172_REG_COMMAND, SI1172_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000);  /* 10 ms settle after reset */

    /*
     * Configure measurement parameters (placeholder values).
     * A real implementation requires the Si1172 datasheet-specified
     * configuration registers and parameter tuning.
     */
    if (si1172_write_reg(handle, 0x08, 0x0A) < 0) return -1;
    if (si1172_write_reg(handle, 0x09, 0x0B) < 0) return -1;
    if (si1172_write_reg(handle, 0x0A, 0x0C) < 0) return -1;
    if (si1172_write_reg(handle, 0x0B, 0x0D) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a forced ALS measurement and read the FIFO result           */
/* ------------------------------------------------------------------ */
static int si1172_read_data(int handle, uint16_t *ir_raw, uint16_t *red_raw)
{
    /* Trigger a forced ALS measurement */
    if (si1172_write_reg(handle, SI1172_REG_COMMAND, SI1172_CMD_ALS_FORCE) < 0)
        return -1;

    /* Wait for the measurement to complete (datasheet: ~10 ms typical) */
    gpioDelay(15000);

    /* Read the 4-byte FIFO block */
    return si1172_read_fifo(handle, ir_raw, red_raw);
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, time_t timestamp,
                     uint16_t ir_raw, uint16_t red_raw, int error_code)
{
    /*
     * HR and SpO2 are computed via the Si1172 proprietary algorithm.
     * Logging the raw IR and RED ADC values as proxy values.
     */
    fprintf(fp, "%ld,%u,%u,%d\n", (long)timestamp, ir_raw, red_raw, error_code);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus to the Si1172 */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1172_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1172_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1172 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file */
    g_log_file = fopen("biometric_log.csv", "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.csv for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write the CSV header if the file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr_bpm,spo2_pct,error_code\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stdout, "Si1172 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        time_t now = time(NULL);
        uint16_t ir_raw = 0, red_raw = 0;
        int error_code = ERR_NONE;

        if (si1172_read_data(g_i2c_handle, &ir_raw, &red_raw) < 0) {
            error_code = ERR_I2C_READ;
            fprintf(stderr, "[WARN] I2C read error at %ld\n", (long)now);
        }

        log_data(g_log_file, now, ir_raw, red_raw, error_code);
        sleep(1);
    }

    fprintf(stdout, "\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

