#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1
#define SAMPLE_RATE 100
#define GAIN_ARG "--gain"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int parse_gain(int argc, char *argv[], float *gain) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], GAIN_ARG) == 0 && i + 1 < argc) {
            char *endptr;
            float val = strtof(argv[i + 1], &endptr);
            if (*endptr != '\0' || val <= 0.0f) {
                fprintf(stderr, "Error: Invalid gain value: %s\n", argv[i + 1]);
                return -1;
            }
            *gain = val;
            return 0;
        }
    }
    return -1;
}

int main(int argc, char *argv[]) {
    float gain = 1.0f;

    if (parse_gain(argc, argv, &gain) != 0) {
        fprintf(stderr, "Usage: %s [--gain <value>]\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

