    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
