#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_temperature(float *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%f", temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (*temp < -40.0 || *temp > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", *temp);
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

static float compensate_voltage(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

static void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n",
            timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        fclose(log_file);
        return 1;
    }
    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature = 25.0;
        if (read_temperature(&temperature) < 0) {
            fprintf(stderr, "Using default temperature 25.0\n");
        }

        int raw_adc = -1;
        int retries = 0;
        while (retries < MAX_RETRIES && program_running) {
            if (read_mcp3008(0, &raw_adc) == 0) {
                if (raw_adc >= 0 && raw_adc <= 1023) break;
                fprintf(stderr, "ADC value out of range: %d\n", raw_adc);
            }
            retries++;
            usleep(10000);
        }
        if (retries >= MAX_RETRIES || !program_running) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            gpiod_line_set_value(buzzer_line, 0);
            continue;
        }

        float voltage = adc_to_voltage(raw_adc);
        float compensated_voltage = compensate_voltage(voltage, temperature);
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        if (flame_detected) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

