#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define LED_GPIO       17
#define WATER_LEVEL_THRESHOLD_HIGH  75.0f
#define WATER_LEVEL_THRESHOLD_LOW   70.0f
#define SAMPLE_INTERVAL_US  5000000  /* 5 seconds */
#define POLL_DELAY_US       100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_json_file = NULL;
static int  g_led_state  = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 single-ended channel                 */
/* Returns 0-1023 on success, -1 on SPI transfer error                 */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       start bit
     *   tx[1] = 0x80 | (channel << 4)      SGL/DIFF=1, D2 D1 D0 = channel
     *   tx[2] = 0x00                       padding
     * Result: bits 9..0 in ((rx[1] & 0x03) << 8) | rx[2]
     */
    unsigned char tx[3] = { 0x01,
                            (unsigned char)(0x80 | (channel << 4)),
                            0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Convert 10-bit ADC value to water-level percentage                  */
/* ------------------------------------------------------------------ */
static float adc_to_percentage(int adc_value)
{
    return (float)adc_value / 1023.0f * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Append a JSON entry to the open file; keeps valid JSON even if      */
/* interrupted mid-program (array starts with '[', ends with ']').     */
/* ------------------------------------------------------------------ */
static void log_water_level(float percentage)
{
    if (g_json_file == NULL)
        return;

    /* Write the opening '[' only if the file is empty (new file) */
    long pos = ftell(g_json_file);
    if (pos == 0) {
        fprintf(g_json_file, "[\n");
    } else {
        /* Not first entry — prepend a comma */
        fprintf(g_json_file, ",\n");
    }

    /* Timestamp with milliseconds */
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;

    fprintf(g_json_file,
            "  {\"timestamp\": \"%s.%03ldZ\", \"water_level\": %.2f}\n",
            timestamp, ms, percentage);
    fflush(g_json_file);
}

/* ------------------------------------------------------------------ */
/* Hysteresis-driven LED control                                       */
/* ------------------------------------------------------------------ */
static void control_led(float percentage)
{
    if (percentage > WATER_LEVEL_THRESHOLD_HIGH && g_led_state == 0) {
        if (gpioWrite(LED_GPIO, 1) == 0) {
            g_led_state = 1;
            printf("Water level above threshold (%.2f%%) — LED ON\n",
                   percentage);
        } else {
            fprintf(stderr, "Failed to set LED GPIO %d HIGH\n", LED_GPIO);
        }
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && g_led_state == 1) {
        if (gpioWrite(LED_GPIO, 0) == 0) {
            g_led_state = 0;
            printf("Water level below threshold (%.2f%%) — LED OFF\n",
                   percentage);
        } else {
            fprintf(stderr, "Failed to set LED GPIO %d LOW\n", LED_GPIO);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call multiple times                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led_state == 1) {
        gpioWrite(LED_GPIO, 0);
        g_led_state = 0;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_json_file != NULL) {
        /* Close with a closing ']' only if we wrote any entries */
        long pos = ftell(g_json_file);
        if (pos > 2) {
            fseek(g_json_file, -2, SEEK_CUR);
            fprintf(g_json_file, "\n]\n");
        } else {
            fprintf(g_json_file, "]\n");
        }
        fclose(g_json_file);
        g_json_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);
    g_led_state = 0;

    /* ---- SPI open ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n",
                pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- JSON file (append) ---- */
    g_json_file = fopen("water_levels.json", "a");
    if (g_json_file == NULL) {
        perror("Failed to open water_levels.json");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error already reported; skip this sample */
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float percentage = adc_to_percentage(adc_value);
        printf("Water level: %.2f%%\n", percentage);

        log_water_level(percentage);
        control_led(percentage);

        /* Sleep in small increments so signals are caught promptly */
        int remaining = SAMPLE_INTERVAL_US;
        while (remaining > 0 && g_running) {
            int chunk = (remaining > POLL_DELAY_US)
                        ? POLL_DELAY_US
                        : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

