#define DEFAULT_LOG_FREQUENCY 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "msmtprc"

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int raw_value, int min_raw, int max_raw) {
    if (raw_value < 0) return -1.0f;
    if (raw_value <= min_raw) return 0.0f;
    if (raw_value >= max_raw) return 100.0f;
    return ((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0f;
}

static void log_data(float moisture_percent) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open plant_data.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Error: localtime failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percent);
    fclose(fp);
}

static void send_email_alert(float moisture_percent, const char *recipient, const char *config_file) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Alert\n\nPlant moisture level is below threshold. Current moisture: %.2f%%\" | msmtp -C %s %s",
             moisture_percent, config_file, recipient);

    FILE *fp = popen(command, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not execute msmtp command\n");
        return;
    }

