    if (min_raw >= max_raw) {
        fprintf(stderr, "Error: min_raw (%d) must be less than max_raw (%d)\n", min_raw, max_raw);
        return 1;
    }
    if (moisture_threshold < 0 || moisture_threshold > 100) {
        fprintf(stderr, "Error: moisture_threshold must be between 0 and 100\n");
        return 1;
    }
    if (log_frequency <= 0) {
        fprintf(stderr, "Error: log_frequency must be positive\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d)\n", spi_channel);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw_value = read_mcp3008(adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float moisture_percent = calculate_moisture(raw_value, min_raw, max_raw);
            if (moisture_percent < 0.0f) {
                fprintf(stderr, "Error: Invalid moisture calculation\n");
            } else {
                log_data(moisture_percent);
                printf("Moisture: %.2f%%\n", moisture_percent);

                if (moisture_percent < moisture_threshold) {
