    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO-8601 timestamp                            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int adc_value, float moisture)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n", ts, adc_value, moisture) < 0) {
        fprintf(stderr, "fprintf() to log failed\n");
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int sample_interval = SAMPLE_PERIOD;
    if (argc > 1) {
        int v = atoi(argv[1]);
        if (v > 0) {
            sample_interval = v;
        } else {
            fprintf(stderr, "Warning: invalid sample interval '%s', using default %d s\n",
                    argv[1], SAMPLE_PERIOD);
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open SPI ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
    }

    printf("Soil moisture monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* ---- main loop ---- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Warning: SPI read error — skipping sample\n");
        } else {
            float moisture = calculate_moisture(adc_value);
            log_data(g_log_file, adc_value, moisture);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc_value, moisture);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < sample_interval * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

