#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/*
 * Raspberry Pi 4 Model B - MLX90823 Pressure Sensor Reader
 *
 * Hardware Connections:
 *   MLX90823 VOUT -> MCP3008 CH0
 *   MCP3008 VDD  -> 3.3V
 *   MCP3008 VREF -> 3.3V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *
 * SPI Configuration:
 *   Bus 0, Channel 0, 1 MHz, Mode 0
 *
 * Pressure Conversion:
 *   MLX90823 outputs 0.5V to 4.5V for 0.1 bar to 1.5 bar span.
 *   10-bit ADC (0-1023) maps to 0-3.3V.
 *   Pressure (kPa) = ((voltage - 0.5V) / (4.5V - 0.5V)) * (150 kPa - 10 kPa) + 10 kPa
 */

#define SPI_BUS          0
#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0        /* Mode 0, active-low CE */

#define ADC_CHANNEL      0
#define ADC_MAX_VALUE    1023
#define VREF             3.3f

#define MIN_PRESSURE_KPA 10.0f
#define MAX_PRESSURE_KPA 150.0f
#define MIN_VOLTAGE      0.5f
#define MAX_VOLTAGE      4.5f

#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 10-bit value from MCP3008 via SPI */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01 (Start bit)
     *   Byte 1: (0x08 | channel) << 4  (Single-ended mode + channel select)
     *   Byte 2: 0x00 (Don't care, clocked out for data)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in lower nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* Convert ADC value to voltage */
static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)ADC_MAX_VALUE) * VREF;
}

/* Convert voltage to pressure (kPa) */
static float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Warning: Voltage %.3fV out of sensor range [%.1f, %.1f]V\n",
                voltage, MIN_VOLTAGE, MAX_VOLTAGE);
        return -1.0f;
    }
    return ((voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE)) *
           (MAX_PRESSURE_KPA - MIN_PRESSURE_KPA) + MIN_PRESSURE_KPA;
}

/* Log pressure reading with ISO-8601 timestamp */
static void log_pressure(float pressure_kpa) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kpa);
    fflush(stdout);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI0 CE0, 1 MHz, MCP3008 CH0\n");
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Error: Max consecutive SPI errors (%d) reached. Aborting.\n",
                        MAX_CONSECUTIVE_ERRORS);
                break;
            }
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        consecutive_errors = 0;

        float voltage = adc_to_voltage(adc_value);

        /* Sensor-absent / fault detection: stuck at rail */
        if (voltage < 0.01f) {
            fprintf(stderr, "Warning: Sensor may be absent or disconnected (VOUT near 0V)\n");
        } else if (voltage > (VREF - 0.01f)) {
            fprintf(stderr, "Warning: Sensor may be absent or disconnected (VOUT near VREF)\n");
        }

        float pressure = voltage_to_pressure(voltage);
        if (pressure < 0.0f) {
            fprintf(stderr, "Warning: Voltage %.3fV out of valid sensor range\n", voltage);
        } else {
            log_pressure(pressure);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

