    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI0 CE0, 1 MHz, MCP3008 CH0\n");
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Error: Max consecutive SPI errors (%d) reached. Aborting.\n",
                        MAX_CONSECUTIVE_ERRORS);
                break;
            }
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        consecutive_errors = 0;

        float voltage = adc_to_voltage(adc_value);

        /* Sensor-absent / fault detection: stuck at rail */
        if (voltage < 0.01f) {
            fprintf(stderr, "Warning: Sensor may be absent or disconnected (VOUT near 0V)\n");
        } else if (voltage > (VREF - 0.01f)) {
            fprintf(stderr, "Warning: Sensor may be absent or disconnected (VOUT near VREF)\n");
        }

        float pressure = voltage_to_pressure(voltage);
        if (pressure < 0.0f) {
            fprintf(stderr, "Warning: Voltage %.3fV out of valid sensor range\n", voltage);
        } else {
            log_pressure(pressure);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

