    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < MIN_ADC_VALUE) adc_value = MIN_ADC_VALUE;
    if (adc_value > MAX_ADC_VALUE) adc_value = MAX_ADC_VALUE;
    return ((float)(adc_value - MIN_ADC_VALUE) / (float)(MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0f;
}

static void log_moisture_level(float moisture_level) {
    time_t rawtime;
