        }

        float moisture_level = calculate_moisture_percentage(adc_value);
        log_moisture_level(moisture_level);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    close(spi_fd);
    return 0;
}

