#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  /* 1 MHz */
#define SPI_MODE 0
#define PUMP_GPIO 17
#define MOISTURE_CHANNEL 0
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL_MS 5000
#define BUFFER_SIZE 20

/* Global state */
static int spi_handle = -1;
static volatile sig_atomic_t pump_state = 0;
static volatile sig_atomic_t running = 1;

/* Circular buffer entry */
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

/* Circular buffer */
static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count = 0;

/* Function prototypes */
static int read_mcp3008(int channel);
static void control_pump(int moisture_level);
static void log_data(int moisture_level, int pump_state);
static void print_log_buffer(void);
static void timer_callback(void *user_data);
static void signal_handler(int signal);

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (don't care, clocks out low 2 bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx_buf[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buf[3] = { 0 };

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

/*
 * Control the water pump based on hysteresis thresholds.
 * Only changes GPIO and logs on state change to avoid spamming.
 */
static void control_pump(int moisture_level) {
    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Pump ON (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to write GPIO %d high\n", PUMP_GPIO);
        }
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            printf("Pump OFF (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to write GPIO %d low\n", PUMP_GPIO);
        }
    }
}

/* Add a log entry to the circular buffer */
static void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    log_buffer[buffer_head].timestamp = now;
    log_buffer[buffer_head].moisture_level = moisture_level;
    log_buffer[buffer_head].pump_state = pump_state;

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* Print the current contents of the circular buffer */
static void print_log_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_head;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(ts_str, "UNKNOWN", sizeof(ts_str));
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               ts_str,
               log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

/* pigpio timer callback: reads sensor, controls pump, logs, prints */
static void timer_callback(void *user_data) {
    (void)user_data;

    int moisture_level = read_mcp3008(MOISTURE_CHANNEL);
    if (moisture_level < 0) {
        fprintf(stderr, "Sensor read failed; skipping cycle\n");
        return;
    }

    control_pump(moisture_level);
    log_data(moisture_level, pump_state);
    print_log_buffer();
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d low\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, mode %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start a 5-second timer */
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop: sleep until signal received */
    while (running) {
        sleep(1);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);  /* Disable timer */
    gpioWrite(PUMP_GPIO, 0);               /* Ensure pump is off */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

