    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start a 5-second timer */
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop: sleep until signal received */
    while (running) {
        sleep(1);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);  /* Disable timer */
    gpioWrite(PUMP_GPIO, 0);               /* Ensure pump is off */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

