#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVERFLOW_CTR 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x07
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100

#define SAMPLE_INTERVAL_US 1000000
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_WINDOW_US (SAMPLE_WINDOW_MS * 1000)

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_burst(uint8_t reg, uint8_t *buf, int len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C burst read failed: reg=0x%02X, expected=%d, got=%d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id = 0;
    if (read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read Part ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (write_reg(REG_MODE_CONFIG, 0x40) != 0) return -1;
    gpioDelay(10000);

    if (write_reg(REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (write_reg(REG_INTR_STATUS_1, 0xFF) != 0) return -1;
    if (write_reg(REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (write_reg(REG_OVERFLOW_CTR, 0x00) != 0) return -1;
    if (write_reg(REG_FIFO_RD_PTR, 0x00) != 0) return -1;

    if (write_reg(REG_MODE_CONFIG, 0x03) != 0) return -1;
    if (write_reg(REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (write_reg(REG_LED1_PA, 0x24) != 0) return -1;
    if (write_reg(REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_fifo_sample(uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (read_burst(REG_FIFO_DATA, buf, 6) != 0) return -1;

    *red = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static int detect_peaks(const uint32_t *ir, int n, int *peak_idx) {
    if (n < 2) return 0;
    int count = 0;
    for (int i = 1; i < n - 1; i++) {
        if (ir[i] > ir[i - 1] && ir[i] > ir[i + 1]) {
            peak_idx[count++] = i;
            if (count >= 2) break;
        }
    }
    return count;
}

static int calculate_hr(const uint32_t *ir, int n) {
    int peak_idx[2];
    int peaks = detect_peaks(ir, n, peak_idx);
    if (peaks < 2) return -1;
    int diff_us = (peak_idx[1] - peak_idx[0]) * 1000;
    if (diff_us <= 0) return -1;
    int bpm = 60000000 / diff_us;
    return bpm;
}

static int calculate_spo2(uint32_t red_avg, uint32_t ir_avg, uint32_t red_max, uint32_t ir_max) {
    if (ir_max == 0 || red_max == 0) return -1;
    double ratio = (double)red_max / (double)ir_max;
    double spo2 = 110.0 - 25.0 * ratio;
    if (spo2 < 0.0) spo2 = 0.0;
    if (spo2 > 100.0) spo2 = 100.0;
    return (int)(spo2 + 0.5);
}

static void log_event(const char *msg) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        perror("fopen health_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

