    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t ir_buf[SAMPLE_WINDOW_MS];
    int idx = 0;
    uint32_t red_avg = 0, ir_avg = 0, red_max = 0, ir_max = 0;
    int ir_valid = 0;

    while (running) {
        uint32_t red, ir;
        if (read_fifo_sample(&red, &ir) == 0) {
            ir_buf[idx] = ir;
            idx++;
            if (idx >= SAMPLE_WINDOW_MS) idx = 0;

            if (idx == SAMPLE_WINDOW_MS) {
                uint32_t sum_red = 0, sum_ir = 0;
                for (int i = 0; i < SAMPLE_WINDOW_MS; i++) {
                    sum_red += ir_buf[i];
                    sum_ir += ir_buf[i];
                }
                red_avg = sum_red / SAMPLE_WINDOW_MS;
                ir_avg = sum_ir / SAMPLE_WINDOW_MS;

                uint32_t max_red = 0, max_ir = 0;
                for (int i = 0; i < SAMPLE_WINDOW_MS; i++) {
                    if (ir_buf[i] > max_ir) max_ir = ir_buf[i];
                }
                red_max = max_red;
                ir_max = max_ir;
                ir_valid = 1;
            }

            if (ir_valid && idx == 0) {
                int hr = calculate_hr(ir_buf, SAMPLE_WINDOW_MS);
                int spo2 = calculate_spo2(red_avg, ir_avg, red_max, ir_max);

                if (hr >= 0 && hr > HR_THRESHOLD) {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "HR above threshold: %d BPM", hr);
                    log_event(msg);
                }
                if (spo2 >= 0 && spo2 < SPO2_THRESHOLD) {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "SpO2 below threshold: %d%%", spo2);
                    log_event(msg);
                }
            }
        } else {
            fprintf(stderr, "FIFO read error\n");
            log_event("FIFO read error");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

