#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_CONV   0x00
#define ADS1115_CONFIG 0x01

#define RELAY_PIN      17
#define REED_PIN       27

#define LOG_FILE       "/var/log/door_events.log"
#define POLL_MS        200
#define RELAY_MS       3000
#define BASELINE_SAMPLES 10
#define BASELINE_MS    50

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, msg);
    fclose(fp);
}

/* Write 16-bit big-endian value to ADS1115 register. */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    struct i2c_msg msg = { .addr = ADS1115_ADDR, .flags = 0, .len = 3, .buf = buf };
    struct i2c_rdwr_ioctl_data data = { .msgs = &msg, .nmsgs = 1 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    return 0;
}

/* Read 16-bit big-endian value from ADS1115 register. */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out) {
    uint8_t wbuf[1] = { reg };
    uint8_t rbuf[2];
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0, .len = 1, .buf = wbuf },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD, .len = 2, .buf = rbuf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

/* Read raw ADC count from ADS1115 channel 0 (single-ended). */
static int ads1115_read_raw(int fd, int16_t *raw) {
    uint16_t cfg = 0x8000 | (0x4000) | (0x0000) | (0x0300) | (0x0080) | (0x0003);
    if (ads1115_write_reg(fd, ADS1115_CONFIG, cfg) < 0) return -1;
    msleep(10);
    uint16_t val;
    if (ads1115_read_reg(fd, ADS1115_CONV, &val) < 0) return -1;
    *raw = (int16_t)val;
    return 0;
}

/* Calibrate baseline: average of BASELINE_SAMPLES readings. */
static int calibrate_baseline(int fd, int *baseline) {
    long sum = 0;
    for (int i = 0; i < BASELINE_SAMPLES; i++) {
        int16_t raw;
        if (ads1115_read_raw(fd, &raw) < 0) {
            fprintf(stderr, "ADS1115 baseline read failed: %s\n", strerror(errno));
            return -1;
        }
        sum += raw;
        msleep(BASELINE_MS);
    }
    *baseline = (int)(sum / BASELINE_SAMPLES);
    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    struct gpiod_line *reed  = gpiod_chip_get_line(chip, REED_PIN);
    if (!relay || !reed) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(relay, "door_relay", 0) < 0) {
        perror("relay request_output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(reed, "door_reed") < 0) {
        perror("reed request_input");
        gpiod_line_release(relay);
        gpiod_chip_close(chip);
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c");
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }

    int baseline = 0;
    if (calibrate_baseline(fd, &baseline) < 0) {
        fprintf(stderr, "Calibration failed; aborting.\n");
        close(fd);
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }
    int threshold = (int)(baseline * 0.8);
    printf("Baseline=%d  Threshold=%d\n", baseline, threshold);

    while (running) {
        int16_t raw;
        if (ads1115_read_raw(fd, &raw) < 0) {
            log_event("Sensor read error");
            msleep(POLL_MS);
            continue;
        }

        if (raw < threshold) {
            printf("Distance below threshold (%d < %d)\n", raw, threshold);
            log_event("Distance below threshold");

            if (gpiod_line_set_value(relay, 1) < 0) {
                perror("relay set high");
            } else {
                log_event("Relay energized");
            }
            msleep(RELAY_MS);
            if (gpiod_line_set_value(relay, 0) < 0) {
                perror("relay set low");
            } else {
                log_event("Relay de-energized");
            }

            int val = gpiod_line_get_value(reed);
            if (val < 0) {
                perror("reed read");
                log_event("Reed read error");
            } else {
                log_event(val == 0 ? "Door opened" : "Door not opened");
            }
        }
        msleep(POLL_MS);
    }

    /* Cleanup */
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_line_release(reed);
    gpiod_chip_close(chip);
    close(fd);
    log_event("Shutdown");
    return 0;
}

