#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define DRY_RAW 200
#define WET_RAW 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60
#define LOG_FILE "irrigation.log"
#define SPI_RETRIES 3

static int spi_handle = -1;
static int pump_state = 0;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int interval = DEFAULT_INTERVAL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, SPI_RETRIES, ret);
        gpioDelay(100000);
    }
    return -1;
}

static int map_moisture(int raw) {
    if (raw < DRY_RAW) return 0;
    if (raw > WET_RAW) return 100;
    return (int)(((long)(raw - DRY_RAW) * 100) / (WET_RAW - DRY_RAW));
}

static void control_pump(int state) {
    if (state == pump_state) return;
    if (gpioWrite(PUMP_GPIO, state) < 0) {
        log_message("Failed to write pump GPIO");
        return;
    }
    pump_state = state;
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", state ? "ON" : "OFF");
    log_message(msg);
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_s] [-s interval_s]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (duration < 0) {
        fprintf(stderr, "Duration must be >= 0\n");
        return EXIT_FAILURE;
    }
    if (interval < 0) {
        fprintf(stderr, "Interval must be >= 0\n");
        return EXIT_FAILURE;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);
    pump_state = 0;
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_message("Irrigation system started");
    while (running) {
        int raw = read_mcp3008(MCP3008_CHANNEL);
        if (raw < 0) {
            log_message("SPI read failed after retries; skipping cycle");
            gpioDelay(interval * 1000000);
            continue;
        }
        int moisture = map_moisture(raw);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture: %d%% (raw=%d)", moisture, raw);
        log_message(msg);
        if (moisture < threshold) {
            log_message("Moisture below threshold; activating pump");
            control_pump(1);
            for (int i = 0; i < duration && running; i++) {
                gpioDelay(1000000);
            }
            control_pump(0);
        }
        for (int i = 0; i < interval && running; i++) {
            gpioDelay(1000000);
        }
    }
    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

