#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define CTRL_SINGLE_0  0x40   /* single-ended, channel 0, analog output off */
#define SAMPLE_US      100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *out)
{
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * PCF8591: the first write after power-on or reset returns the
     * result of the previous conversion.  Send the control byte
     * to prime the analog input, then discard the stale byte.
     */
    if (i2c_write_byte(fd, CTRL_SINGLE_0) < 0)
        goto cleanup;

    usleep(1000); /* let the first conversion settle */

    uint8_t dummy;
    if (i2c_read_byte(fd, &dummy) < 0)
        goto cleanup;

    printf("Monitoring PCF8591 AIN0 (0x%02X) on %s\n", PCF8591_ADDR, I2C_BUS);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        /* Re-issue the control byte to start a new conversion */
        if (i2c_write_byte(fd, CTRL_SINGLE_0) < 0)
            goto cleanup;

        usleep(1000); /* conversion time ~1 ms */

        uint8_t value;
        if (i2c_read_byte(fd, &value) < 0)
            goto cleanup;

        printf("AIN0: %3u\n", (unsigned)value);
        fflush(stdout);

        usleep(SAMPLE_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

