#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48
#define ADS1115_CONV   0x00
#define ADS1115_CONFIG 0x01

#define GPIO_SHUTDOWN  27
#define BUFFER_SIZE    10
#define THRESHOLD_GAUSS 500.0

#define VREF           3.3
#define ZERO_FIELD_V   2.5
#define SENSITIVITY_MV 1.4

#define SAMPLE_US      1000000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    double buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_ads1115(void) {
    uint16_t config = 0x8000 | (0x4000) | (0x0000) | (0x0080) | (0x0000) | (0x0000) | (0x0000);
    char buf[3];
    buf[0] = ADS1115_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) < 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config");
        return -1;
    }
    return 0;
}

static int read_ads1115(double *voltage) {
    char reg = ADS1115_CONV;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "Failed to set ADS1115 conversion register");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADS1115 conversion");
        return -1;
    }
    int16_t raw = (data[0] << 8) | data[1];
    *voltage = (raw * VREF) / 32768.0;
    return 0;
}

static double voltage_to_gauss(double v) {
    return (v - ZERO_FIELD_V) / (SENSITIVITY_MV / 1000.0);
}

static void cb_add(CircularBuffer *cb, double value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static double cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

int main(void) {
    openlog("hall_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d addr 0x%02X", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_ads1115() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);

    CircularBuffer cb = {0};
    bool shutdown_armed = false;

    while (running) {
        double voltage = 0.0;
        if (read_ads1115(&voltage) < 0) {
            gpioDelay(SAMPLE_US);
            continue;
        }
        if (voltage < 0.0 || voltage > VREF) {
            syslog(LOG_ERR, "Invalid voltage reading: %.3f V", voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        double gauss = voltage_to_gauss(voltage);
        cb_add(&cb, gauss);
        double avg = cb_average(&cb);

        time_t now = time(NULL);
        syslog(LOG_INFO, "%ld Voltage: %.3f V, Gauss: %.2f, Avg: %.2f", (long)now, voltage, gauss, avg);

        if (avg > THRESHOLD_GAUSS && !shutdown_armed) {
            syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauss", avg);
            gpioWrite(GPIO_SHUTDOWN, 1);
            shutdown_armed = true;
        }

        gpioDelay(SAMPLE_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    gpioWrite(GPIO_SHUTDOWN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

