#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

#define SPI_CHANNEL 0       /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0       /* Mode 0, active-low CE */
#define ADC_CHANNEL 0       /* MCP3008 CH0 */
#define SAMPLE_US   1000000 /* 1 second */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (don't-care)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/*
 * Map 10-bit ADC value (0-1023) to rainfall intensity (0-10).
 * YL-83 output: dry ~0 V, wet ~3.3 V.  Map dry->0, wet->10.
 */
static int map_to_intensity(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return (int)(((float)adc_value / 1023.0f) * 10.0f);
}

int main(void) {
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying next cycle.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        int intensity = map_to_intensity(adc_value);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("[%s] ADC: %4d  Intensity: %2d\n", ts, adc_value, intensity);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

