#define ADC_THRESHOLD_LOW 400
#define ADC_THRESHOLD_HIGH 700

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int adc_to_moisture(int adc) {
    if (adc < ADC_MIN || adc > ADC_MAX) return -1;
    return 100 - ((adc - ADC_MIN) * 100 / (ADC_MAX - ADC_MIN));
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d", PUMP_GPIO);
        return -1;
    }
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

