    (void)ud;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected");
        if (mosquitto_subscribe(m, NULL, MQTT_CONTROL_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to control topic");
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(rc));
    }
}

static void on_disconnect(struct mosquitto *m, void *ud, int rc) {
    (void)m; (void)ud;
    if (rc != MOSQ_ERR_SUCCESS) syslog(LOG_WARNING, "MQTT disconnected unexpectedly");
}

static void on_message(struct mosquitto *m, void *ud, const struct mosquitto_message *msg) {
    (void)m; (void)ud;
    if (!msg || !msg->payload || msg->payloadlen <= 0) return;
    char payload[32] = {0};
    int len = msg->payloadlen < (int)sizeof(payload) - 1 ? msg->payloadlen : (int)sizeof(payload) - 1;
