#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define VREF            3.3f
#define SAMPLE_DELAY_US 500000U

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0-7)\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then don't-care */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)(0x80 | (channel << 4)),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* rx[1] low nibble + rx[2] form the 10-bit result */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = spi_init(SPI_DEVICE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("MCP3008 channel 0 reader (VREF = %.1f V)\n", VREF);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int raw = read_mcp3008(fd, 0);
        if (raw < 0) {
            break;
        }

        float voltage = (float)raw * VREF / 1024.0f;
        printf("Raw: %4d  Voltage: %.3f V\n", raw, voltage);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    if (close(fd) < 0) {
        fprintf(stderr, "Warning: error closing SPI device: %s\n", strerror(errno));
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

