static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes total.
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  (single-ended mode + channel select)
     * Byte 2: 0x00 (don't care, clocked out to read 10-bit result)
     */
    char tx_buf[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buf[3] = { 0 };

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (returned %d)\n", channel, result);
        return -1;
    }

