#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(int noise_level, int duty_cycle1, int duty_cycle2) {
    FILE *fp = fopen("vibration_log.txt", "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Noise: %d, Motor1: %d, Motor2: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                noise_level, duty_cycle1, duty_cycle2);
    }
    fclose(fp);
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0 || gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pins as output\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){SPI_SPEED}) < 0) {
        perror("Failed to configure SPI");
        cleanup();
        return 1;
    }

    printf("Vibration control started. Press Ctrl+C to exit.\n");

    while (running) {
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "ADC read error, skipping iteration\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        int duty_cycle = 0;
        if (noise_level > NOISE_THRESHOLD) {
            duty_cycle = (int)(((float)(noise_level - NOISE_THRESHOLD) / (1023 - NOISE_THRESHOLD)) * PWM_RANGE);
            if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
            if (duty_cycle < 0) duty_cycle = 0;
        }

        if (gpioPWM(MOTOR1_PIN, duty_cycle) < 0 || gpioPWM(MOTOR2_PIN, duty_cycle) < 0) {
            fprintf(stderr, "PWM write error\n");
        }

        log_event(noise_level, duty_cycle, duty_cycle);
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

