#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x11
#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CHANNEL 0
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5
#define BH1750_CONV_TIME_MS 180

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_sound_level(int spi_fd) {
    int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
    if (adc_value < 0) return -1;

    float voltage = (adc_value / 1023.0f) * 3.3f;
    float sound_level_db = -40.0f + (voltage - 0.5f) * 60.0f;
    return (int)(sound_level_db * 10.0f);
}

static int read_light_level(int i2c_fd) {
    unsigned char cmd = BH1750_CONT_HIGH_RES_MODE;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to write BH1750 command");
        return -1;
    }

    usleep(BH1750_CONV_TIME_MS * 1000);

    unsigned char buf[2] = {0};
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read BH1750 data");
        return -1;
    }

    unsigned int raw = (buf[0] << 8) | buf[1];
    return (int)(raw / 1.2f);
}

static void log_data(FILE *fp, int sound_level, int light_level, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handlers");
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    unsigned int speed = 1000000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return 1;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        close(spi_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int sound_level = read_sound_level(spi_fd);
        int light_level = read_light_level(i2c_fd);
        int error_code = 0;

        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound level\n");
            sound_level = -1;
            error_code = 1;
        }
        if (light_level < 0) {
            fprintf(stderr, "Error reading light level\n");
            light_level = -1;
            error_code = 2;
        }

        log_data(fp, sound_level, light_level, error_code);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fclose(fp);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

