#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5
#define PWM_FREQ 100
#define PWM_RANGE 100

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then 10-bit result */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int set_valve_position(int position) {
    if (position < 0 || position > 100) {
        fprintf(stderr, "Invalid valve position %d\n", position);
        return -1;
    }
    if (gpioPWM(VALVE_GPIO, position) != 0) {
        fprintf(stderr, "gpioPWM failed for position %d\n", position);
        return -1;
    }
    return 0;
}

static int log_data(int s1, int s2, int s3, int avg, int pos) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s, S1=%d, S2=%d, S3=%d, Avg=%d, Pos=%d\n",
                ts, s1, s2, s3, avg, pos) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM to 0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_values[NUM_SENSORS];
        int valid_count = 0;
        int sum = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = read_mcp3008(i);
            if (v < 0) {
                fprintf(stderr, "Sensor %d read failed; skipping\n", i);
                continue;
            }
            sensor_values[valid_count++] = v;
            sum += v;
        }

        if (valid_count == 0) {
            fprintf(stderr, "All sensors failed; skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int avg_adc = sum / valid_count;

        /* Inverse mapping: dry soil (low ADC) -> high opening, wet -> low */
        int valve_position = 100 - (avg_adc * 100 / 1023);
        if (valve_position < 0) valve_position = 0;
        if (valve_position > 100) valve_position = 100;

        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Failed to set valve position\n");
        }

        if (log_data(sensor_values[0],
                     valid_count > 1 ? sensor_values[1] : -1,
                     valid_count > 2 ? sensor_values[2] : -1,
                     avg_adc, valve_position) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    /* Graceful shutdown */
    gpioPWM(VALVE_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();

    printf("Irrigation system stopped.\n");
    return EXIT_SUCCESS;
}

