#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_MODE 0          // SPI Mode 0
#define MCP3008_CHANNEL 0   // MCP3008 CH0
#define LOG_FILE "soil_data.txt"
#define READ_INTERVAL 5     // seconds
#define MAX_RETRIES 5

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void log_data(float moisture_level);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
