#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CONFIG_FILE "theremin_config.txt"
#define MIN_FREQ 220
#define MAX_FREQ 880
#define MIN_DISTANCE 20
#define MAX_DISTANCE 400
#define PWM_PERIOD_NS 10000000  // 10ms period (100Hz base)
#define PWM_DUTY_MAX 1000000000  // 100% duty cycle

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float read_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1.0;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1.0;

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > 30000) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > 30000) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    long long diff = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    return (float)diff / 58.0;
}

void set_pwm_duty(int freq, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int period_ns = 1000000000 / freq;
    int duty_ns = period_ns * duty_percent / 100;
    int fd = open("/sys/class/pwm/pwmchip0/pwm0/period", O_WRONLY);
    if (fd < 0) { perror("open period"); return; }
    dprintf(fd, "%d", period_ns);
    close(fd);
    fd = open("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", O_WRONLY);
    if (fd < 0) { perror("open duty"); return; }
    dprintf(fd, "%d", duty_ns);
    close(fd);
}

void save_config(int min_freq, int max_freq, int min_distance, int max_distance) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) { perror("save config"); return; }
    fprintf(fp, "%d %d %d %d\n", min_freq, max_freq, min_distance, max_distance);
    fclose(fp);
}

void load_config(int *min_freq, int *max_freq, int *min_distance, int *max_distance) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return;
    if (fscanf(fp, "%d %d %d %d", min_freq, max_freq, min_distance, max_distance) != 4) {
        fprintf(stderr, "Config file format error\n");
        fclose(fp);
        return;
    }
    fclose(fp);
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) { perror("chip open"); return 1; }
    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIG_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *pwm = gpiod_chip_get_line(chip, PWM_PIN);
    if (!trig || !echo || !pwm) { perror("get line"); gpiod_chip_close(chip); return 1; }
    if (gpiod_line_request_output(trig, "theremin", 0) < 0 ||
        gpiod_line_request_input(echo, "theremin") < 0 ||
        gpiod_line_request_output(pwm, "theremin", 0) < 0) {
        perror("request line");
        gpiod_chip_close(chip);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) { perror("spi open"); gpiod_chip_close(chip); return 1; }
    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){SPI_SPEED}) < 0) {
        perror("spi config");
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    int min_freq = MIN_FREQ, max_freq = MAX_FREQ, min_distance = MIN_DISTANCE, max_distance = MAX_DISTANCE;
    load_config(&min_freq, &max_freq, &min_distance, &max_distance);

    FILE *pwm_exported = fopen("/sys/class/pwm/pwmchip0/export", "w");
    if (!pwm_exported) { perror("export pwm"); } else {
        dprintf(fileno(pwm_exported), "0");
        fclose(pwm_exported);
        usleep(100000);
        FILE *pwm_enable = fopen("/sys/class/pwm/pwmchip0/pwm0/enable", "w");
        if (pwm_enable) { dprintf(fileno(pwm_enable), "1"); fclose(pwm_enable); }
    }

    signal(SIGINT, signal_handler);
    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = read_distance(trig, echo);
        if (distance < 0) {
            fprintf(stderr, "Distance read error\n");
            distance = 400.0;
        }
        int adc = read_mcp3008(spi_fd, 0);
        if (adc < 0) {
            fprintf(stderr, "ADC read error\n");
            adc = 1023;
        }
        float ldr_value = (float)adc / 1023.0;
        float freq = min_freq + (max_freq - min_freq) * (1.0 - ldr_value);
        int duty = (int)((distance - min_distance) / (max_distance - min_distance) * 100.0);
        if (duty < 0) duty = 0;
        if (duty > 100) duty = 100;
        set_pwm_duty((int)freq, duty);
        usleep(50000);
    }

    FILE *pwm_disable = fopen("/sys/class/pwm/pwmchip0/pwm0/enable", "w");
    if (pwm_disable) { dprintf(fileno(pwm_disable), "0"); fclose(pwm_disable); }
    save_config(min_freq, max_freq, min_distance, max_distance);
    close(spi_fd);
    gpiod_chip_close(chip);
    printf("Theremin stopped.\n");
    return 0;
}

