#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0          // SPI0 CE0
#define SPI_SPEED 1000000      // 1 MHz
#define SPI_FLAGS 0            // Mode 0, active low CS
#define PUMP_GPIO 18           // GPIO18 for relay control
#define MOISTURE_THRESHOLD 300 // 10-bit ADC value (0-1023)
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60     // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int sensor_value, int pump_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: SGL/DIFF=1 (single) + D2 D1 D0 (channel) + padding
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains bits 9-2, rx_buf[2] contains bits 1-0
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | spi_rx_buf[2];
    return adc_value;
}

// Function to control the water pump via relay
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log data to a file
void log_data(int sensor_value, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Sensor Value: %d, Pump State: %s\n",
            timestamp, sensor_value, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

