    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output and ensure it's off
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_mcp3008(0); // Read from channel 0
        if (sensor_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor value\n");
            log_data(-1, 0); // Log error with -1 sensor value
        } else {
            int pump_state = (sensor_value < MOISTURE_THRESHOLD) ? 1 : 0;
            control_pump(pump_state);
            log_data(sensor_value, pump_state);
            printf("Sensor Value: %d, Pump State: %s\n", sensor_value, pump_state ? "ON" : "OFF");
        }

        // Sleep for the sample interval, checking for shutdown signal
        for (int i = 0; i < SAMPLE_INTERVAL && program_running; i++) {
            sleep(1);
        }
    }

    // Cleanup
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

