#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Motor 1 GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIO pins
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Potentiometer ADC channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion profile parameters
#define ACCELERATION_TIME 1.0
#define HOLD_TIME 2.0
#define DECELERATION_TIME 1.0
#define LOOP_DELAY 5.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
int map_potentiometer_to_speed(int potentiometer_value);
void set_motor_speed(int enable_pin, int direction_pin, int speed);
void stop_motor(int enable_pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message for MCP3008 single-ended mode
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor using logarithmic mapping
int map_potentiometer_to_speed(int potentiometer_value) {
    if (potentiometer_value < 0 || potentiometer_value > 1023) {
        fprintf(stderr, "Error: Invalid potentiometer value %d\n", potentiometer_value);
        return -1;
    }

    // Logarithmic mapping for finer control at lower speeds
    double log_value = log10((double)potentiometer_value + 1.0);
    double normalized_log_value = log_value / log10(1024.0);
    int speed_factor = (int)(normalized_log_value * (MAX_SPEED - MIN_SPEED) + MIN_SPEED);

    // Clamp values to valid range
    if (speed_factor < MIN_SPEED) speed_factor = MIN_SPEED;
    if (speed_factor > MAX_SPEED) speed_factor = MAX_SPEED;

    return speed_factor;
}

// Function to set motor speed using PWM
void set_motor_speed(int enable_pin, int direction_pin, int speed) {
    if (speed < MIN_SPEED || speed > MAX_SPEED) {
        fprintf(stderr, "Error: Invalid speed %d\n", speed);
        return;
    }

    gpioWrite(enable_pin, 1); // Enable motor
    gpioPWM(enable_pin, speed); // Set PWM duty cycle
}

// Function to stop motor
void stop_motor(int enable_pin) {
    gpioWrite(enable_pin, 0); // Disable motor
    gpioPWM(enable_pin, 0); // Stop PWM
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_adc(POT1_CHANNEL);
        int pot2_value = read_adc(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values, retrying...\n");
            time_sleep(1.0);
            continue;
        }

        // Map potentiometer values to speed factors
        int speed1 = map_potentiometer_to_speed(pot1_value);
        int speed2 = map_potentiometer_to_speed(pot2_value);

        if (speed1 < 0 || speed2 < 0) {
            fprintf(stderr, "Error: Invalid potentiometer values, retrying...\n");
            time_sleep(1.0);
            continue;
        }

        // Set motor directions
        gpioWrite(MOTOR1_DIRECTION, 1); // Forward
        gpioWrite(MOTOR2_DIRECTION, 0); // Backward

        // Acceleration phase
        double time_elapsed = 0.0;
        while (time_elapsed < ACCELERATION_TIME && !terminate) {
            double t = time_elapsed / ACCELERATION_TIME;
            int speed1_scaled = (int)(speed1 * t * t);
            int speed2_scaled = (int)(speed2 * t * t);
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1_scaled);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2_scaled);
            time_sleep(0.01);
            time_elapsed += 0.01;
        }

        // Hold constant speed phase
        if (!terminate) {
            time_sleep(HOLD_TIME);
        }

        // Deceleration phase
        time_elapsed = 0.0;
        while (time_elapsed < DECELERATION_TIME && !terminate) {
            double t = 1.0 - time_elapsed / DECELERATION_TIME;
            int speed1_scaled = (int)(speed1 * t * t);
            int speed2_scaled = (int)(speed2 * t * t);
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1_scaled);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2_scaled);
            time_sleep(0.01);
            time_elapsed += 0.01;
        }

        // Stop motors
        stop_motor(MOTOR1_ENABLE);
        stop_motor(MOTOR2_ENABLE);

        // Pause before reversing direction
        if (!terminate) {
            time_sleep(LOOP_DELAY);
        }

        // Reverse direction
        gpioWrite(MOTOR1_DIRECTION, 0); // Backward
        gpioWrite(MOTOR2_DIRECTION, 1); // Forward

        // Acceleration phase
        time_elapsed = 0.0;
        while (time_elapsed < ACCELERATION_TIME && !terminate) {
            double t = time_elapsed / ACCELERATION_TIME;
            int speed1_scaled = (int)(speed1 * t * t);
            int speed2_scaled = (int)(speed2 * t * t);
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1_scaled);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2_scaled);
            time_sleep(0.01);
            time_elapsed += 0.01;
        }

        // Hold constant speed phase
        if (!terminate) {
            time_sleep(HOLD_TIME);
        }

        // Deceleration phase
        time_elapsed = 0.0;
        while (time_elapsed < DECELERATION_TIME && !terminate) {
            double t = 1.0 - time_elapsed / DECELERATION_TIME;
            int speed1_scaled = (int)(speed1 * t * t);
            int speed2_scaled = (int)(speed2 * t * t);
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1_scaled);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2_scaled);
            time_sleep(0.01);
            time_elapsed += 0.01;
        }

        // Stop motors
        stop_motor(MOTOR1_ENABLE);
        stop_motor(MOTOR2_ENABLE);

        // Pause before next cycle
        if (!terminate) {
            time_sleep(LOOP_DELAY);
        }
    }

    // Cleanup
    stop_motor(MOTOR1_ENABLE);
    stop_motor(MOTOR2_ENABLE);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

