            int speed1_scaled = (int)(speed1 * t * t);
            int speed2_scaled = (int)(speed2 * t * t);
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1_scaled);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2_scaled);
            time_sleep(0.01);
            time_elapsed += 0.01;
        }

        // Stop motors
        stop_motor(MOTOR1_ENABLE);
        stop_motor(MOTOR2_ENABLE);

        // Pause before reversing direction
        if (!terminate) {
            time_sleep(LOOP_DELAY);
        }

        // Reverse direction
        gpioWrite(MOTOR1_DIRECTION, 0); // Backward
        gpioWrite(MOTOR2_DIRECTION, 1); // Forward

        // Acceleration phase
        time_elapsed = 0.0;
        while (time_elapsed < ACCELERATION_TIME && !terminate) {
            double t = time_elapsed / ACCELERATION_TIME;
            int speed1_scaled = (int)(speed1 * t * t);
            int speed2_scaled = (int)(speed2 * t * t);
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1_scaled);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2_scaled);
            time_sleep(0.01);
            time_elapsed += 0.01;
        }

        // Hold constant speed phase
        if (!terminate) {
            time_sleep(HOLD_TIME);
        }

        // Deceleration phase
        time_elapsed = 0.0;
        while (time_elapsed < DECELERATION_TIME && !terminate) {
            double t = 1.0 - time_elapsed / DECELERATION_TIME;
            int speed1_scaled = (int)(speed1 * t * t);
            int speed2_scaled = (int)(speed2 * t * t);
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1_scaled);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2_scaled);
            time_sleep(0.01);
            time_elapsed += 0.01;
        }

        // Stop motors
        stop_motor(MOTOR1_ENABLE);
        stop_motor(MOTOR2_ENABLE);

        // Pause before next cycle
        if (!terminate) {
            time_sleep(LOOP_DELAY);
        }
    }

    // Cleanup
    stop_motor(MOTOR1_ENABLE);
    stop_motor(MOTOR2_ENABLE);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

