#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_US 10000
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_DURATION_S 5
#define NOISE_THRESHOLD_PERCENT 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise_level(int duration_s) {
    long sum = 0;
    int samples = 0;
    time_t start = time(NULL);

    while (time(NULL) - start < duration_s && running) {
        int val = read_adc(ADC_CHANNEL);
        if (val < 0) {
            fprintf(stderr, "ADC read error during calibration\n");
            return -1;
        }
        sum += val;
        samples++;
        usleep(100000);
    }

    if (samples == 0) {
        fprintf(stderr, "No samples collected during calibration\n");
        return -1;
    }

    return (int)(sum / samples);
}

static int is_above_threshold(int sound_level, int noise_level) {
    return sound_level > (noise_level + (noise_level * NOISE_THRESHOLD_PERCENT / 100));
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Calibrating ambient noise for %d seconds...\n", CALIBRATION_DURATION_S);
    int noise_level = calibrate_noise_level(CALIBRATION_DURATION_S);
    if (noise_level < 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Ambient noise level: %d\n", noise_level);

    printf("Monitoring sound levels... (Press Ctrl+C to exit)\n");

    while (running) {
        int sound_level = read_adc(ADC_CHANNEL);
        if (sound_level < 0) {
            fprintf(stderr, "ADC read error\n");
            break;
        }

        if (is_above_threshold(sound_level, noise_level)) {
            gpioWrite(LED_PIN, 1);
            usleep(DEBOUNCE_DELAY_US);
            gpioWrite(LED_PIN, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

