 * -1 on SPI transfer failure, -2 on CS line error.
 */
static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, int channel, int *adc_out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       start bit
     *   tx[1] = (0x08 | channel) << 4      SGL/DIFF=1, D2 D1 D0 = channel
     *   tx[2] = 0x00                       dummy for clocking data out
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    /* Manually control CS using libgpiod v2 */
    if (gpiod_line_set_value(cs_line, 0) < 0) {
