        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1); /* best-effort release */
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to set CS high: %s\n", strerror(errno));
        return -2;
    }

    *adc_out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
