#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MCP3008 SPI configuration
#define MCP3008_CS 8
#define MCP3008_CH0 0
#define MCP3008_CH1 1
#define MCP3008_CH2 2

// ADXL335 Sensitivity (300mV/g) and Zero-g Bias (1.5V)
#define ADXL335_SENSITIVITY 0.3f
#define ADXL335_ZERO_G_BIAS 1.5f

// Kalman filter parameters
#define KALMAN_Q 0.01f
#define KALMAN_R 0.1f

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    float P;
    float K;
    float x;
} kalman_filter_t;

kalman_filter_t kalman_x = {1.0f, 0.0f, 0.0f};
kalman_filter_t kalman_y = {1.0f, 0.0f, 0.0f};
kalman_filter_t kalman_z = {1.0f, 0.0f, 0.0f};

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_g(int adc_value);
float kalman_filter(float measurement, kalman_filter_t *filter);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01;                          // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;         // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                          // Don't care

    gpioWrite(MCP3008_CS, 0);                     // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1);                     // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transaction failed for channel %d (returned %d)\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to acceleration in g
float voltage_to_g(int adc_value) {
    float voltage = (float)adc_value * 3.3f / 1024.0f;
    return (voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
}

// Function to apply Kalman filter
float kalman_filter(float measurement, kalman_filter_t *filter) {
    filter->K = filter->P / (filter->P + KALMAN_R);
    filter->x = filter->x + filter->K * (measurement - filter->x);
    filter->P = (1.0f - filter->K) * filter->P + KALMAN_Q;
    return filter->x;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure MCP3008 CS pin as output and set high (deselected)
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1);

    // Open SPI channel (CE0, 1MHz, mode 0)
    spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 Kalman Filter Reader\n");
    printf("Reading X, Y, Z acceleration values at 10 Hz...\n");

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int adc_x = read_mcp3008(MCP3008_CH0);
        int adc_y = read_mcp3008(MCP3008_CH1);
        int adc_z = read_mcp3008(MCP3008_CH2);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert ADC values to acceleration in g
        float accel_x = voltage_to_g(adc_x);
        float accel_y = voltage_to_g(adc_y);
        float accel_z = voltage_to_g(adc_z);

        // Apply Kalman filter to each axis
        float filtered_x = kalman_filter(accel_x, &kalman_x);
        float filtered_y = kalman_filter(accel_y, &kalman_y);
        float filtered_z = kalman_filter(accel_z, &kalman_z);

        // Print filtered acceleration values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", filtered_x, filtered_y, filtered_z);

        // Delay for 100ms (10 Hz)
        gpioDelay(100000);
    }

    // Cleanup and exit
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
