#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define VCC 3.3
#define V_QUIESCENT (VCC / 2.0)
#define SENSITIVITY 0.025
#define MIN_FIELD -100.0
#define MAX_FIELD 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static double calculate_magnetic_field(int sensor_value) {
    double voltage = (sensor_value == 1) ? VCC : 0.0;
    return (voltage - V_QUIESCENT) / SENSITIVITY;
}

static int log_data(FILE *fp, double f1, double f2, double f3) {
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", f1, f2, f3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    line3 = gpiod_chip_get_line(chip, SENSOR3_PIN);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "drv5055_sensor1") < 0 ||
        gpiod_line_request_input(line2, "drv5055_sensor2") < 0 ||
        gpiod_line_request_input(line3, "drv5055_sensor3") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Starting DRV5055VA magnetic field logging. Press Ctrl+C to stop.\n");

    while (program_running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);
        int v3 = gpiod_line_get_value(line3);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            struct timespec ts = {0, SAMPLE_INTERVAL_MS * 1000000L};
            nanosleep(&ts, NULL);
            continue;
        }

        double f1 = calculate_magnetic_field(v1);
        double f2 = calculate_magnetic_field(v2);
        double f3 = calculate_magnetic_field(v3);

        if (log_data(fp, f1, f2, f3) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        if (f1 < MIN_FIELD || f1 > MAX_FIELD)
            fprintf(stderr, "Warning: Sensor 1 field out of range: %.2f mT\n", f1);
        if (f2 < MIN_FIELD || f2 > MAX_FIELD)
            fprintf(stderr, "Warning: Sensor 2 field out of range: %.2f mT\n", f2);
        if (f3 < MIN_FIELD || f3 > MAX_FIELD)
            fprintf(stderr, "Warning: Sensor 3 field out of range: %.2f mT\n", f3);

        struct timespec ts = {0, SAMPLE_INTERVAL_MS * 1000000L};
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

