#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER_ADDRESS "mqtt.eclipseprojects.io"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;
static int reconnect_delay = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void mqtt_connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
            mosquitto_disconnect(m);
        }
        reconnect_delay = 1;
    } else {
        log_error("MQTT connection failed");
    }
}

static void mqtt_disconnect_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        log_error("Unexpected MQTT disconnection");
    }
}

static void mqtt_message_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0 && message->payload != NULL) {
        char *payload = malloc(message->payloadlen + 1);
        if (!payload) {
            log_error("Memory allocation failed for MQTT payload");
            return;
        }
        memcpy(payload, message->payload, message->payloadlen);
        payload[message->payloadlen] = '\0';

        cJSON *json = cJSON_Parse(payload);
        free(payload);

        if (!json) {
            log_error("Invalid JSON received");
            return;
        }

        cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
        if (cJSON_IsBool(led_state_json)) {
            int led_state = cJSON_IsTrue(led_state_json) ? 1 : 0;
            if (gpioWrite(LED_GPIO, led_state) != 0) {
                log_error("Failed to write to GPIO");
            } else {
                printf("LED set to %s\n", led_state ? "ON" : "OFF");
            }
        } else {
            log_error("Invalid or missing led_state in JSON");
        }

        cJSON_Delete(json);
    } else {
        log_error("Empty MQTT message received");
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        mosq = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        log_error("Failed to initialize LED state");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start mosquitto loop");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        sleep(1);
        if (!mosquitto_connected(mosq)) {
            log_error("Not connected to MQTT broker. Attempting reconnection...");
            mosquitto_loop_stop(mosq, false);
            mosquitto_disconnect(mosq);
            rc = mosquitto_reconnect(mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_error("Reconnection failed. Retrying in 1 second...");
                sleep(1);
                reconnect_delay = 1;
            } else {
                reconnect_delay = 1;
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

