#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define ADC_RESOLUTION 1024.0f
#define LM35_MV_PER_C 10.0f
#define VREF 3.3f

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / ADC_RESOLUTION;
    return voltage * 1000.0f / LM35_MV_PER_C;
}

static void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

static int write_circular_buffer(const float *buffer, int size, const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }
    size_t written = fwrite(buffer, sizeof(float), size, fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Error writing to file: wrote %zu of %d floats\n", written, size);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int read_failures = 0;
    while (!terminate) {
        int adc_value = 0;
        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) != 0) {
            read_failures++;
            if (read_failures > 5) {
                fprintf(stderr, "Too many consecutive SPI failures, exiting\n");
                break;
            }
            sleep(5);
            continue;
        }
        read_failures = 0;
        float temperature = adc_to_celsius(adc_value);
        temperature_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        log_temperature(temperature);
        if (write_circular_buffer(temperature_buffer, BUFFER_SIZE, LOG_FILE) != 0) {
            fprintf(stderr, "Warning: failed to write circular buffer to file\n");
        }
        sleep(5);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

