#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define MCP4725_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Function prototypes */
static int read_mcp3008(int channel);
static float adc_to_celsius(int adc_value);
static float celsius_to_dac_voltage(float celsius);
static int set_dac_voltage(float voltage);
static void log_data(int adc_value, float celsius, float dac_voltage);
static void cleanup(void);
static void signal_handler(int sig);

/* Read a single-ended channel from MCP3008 (0-7) via SPI */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> single-ended + channel select
     * Byte 2: 0x00 (don't care, clocked out to read data)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            /* rx[1] low nibble + rx[2] form the 10-bit result */
            int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

/* Convert ADC value (0-1023) to Celsius (TMP36: 10 mV/°C, Vref = 3.3 V) */
static float adc_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0f) * 3.3f;
    return (voltage - 0.5f) * 100.0f;
}

/* Map Celsius to DAC voltage (0-3.3 V) */
static float celsius_to_dac_voltage(float celsius) {
    if (celsius < 0.0f) celsius = 0.0f;
    if (celsius > 50.0f) celsius = 50.0f;
    return (celsius / 50.0f) * 3.3f;
}

/* Set DAC voltage via MCP4725 (12-bit, 0-4095 -> 0-3.3 V) */
static int set_dac_voltage(float voltage) {
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > 3.3f) voltage = 3.3f;

    int dac_value = (int)((voltage / 3.3f) * 4095.0f);
    if (dac_value < 0) dac_value = 0;
    if (dac_value > 4095) dac_value = 4095;

    /* MCP4725 I2C protocol: 2 bytes
     * Byte 0: 0x40 | (dac_value >> 8)  -> write command + MSB
     * Byte 1: dac_value & 0xFF         -> LSB
     */
    char buf[2];
    buf[0] = (char)(0x40 | ((dac_value >> 8) & 0x0F));
    buf[1] = (char)(dac_value & 0xFF);

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = i2cWriteDevice(i2c_handle, buf, 2);
        if (ret == 0) return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(10000);
    }
    return -1;
}

/* Log one data record */
static void log_data(int adc_value, float celsius, float dac_voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n",
            ts, adc_value, celsius, dac_voltage);
    fflush(log_file);

    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n",
           ts, adc_value, celsius, dac_voltage);
}

/* Release all resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float celsius = adc_to_celsius(adc_value);
        float dac_voltage = celsius_to_dac_voltage(celsius);

        if (set_dac_voltage(dac_voltage) != 0) {
            fprintf(stderr, "Failed to set DAC voltage after %d retries.\n", MAX_RETRIES);
        }

        log_data(adc_value, celsius, dac_voltage);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

