#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "relay_sequencer"

// BCM GPIO pins for the four relays
const int relay_pins[] = {17, 22, 23, 24};
const int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4] = {NULL};
static volatile sig_atomic_t keep_running = 1;

// Signal handler: deactivate all relays and release GPIO lines
void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    int ret;
    int i;

    // Open the default gpiochip (gpiochip0 on RPi 3B+)
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Request each GPIO line as output, initially LOW
    for (i = 0; i < num_relays; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", relay_pins[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], CONSUMER, 0);
        if (ret < 0) {
            perror("Failed to request output");
            goto cleanup;
        }
    }

    // Install signal handlers for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Relay sequencer started. Press Ctrl+C to stop.\n");

    // Main loop: cycle through relays, activate for 1s, deactivate, delay 1s
    while (keep_running) {
        for (i = 0; i < num_relays && keep_running; i++) {
            // Activate relay (active-high)
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
                perror("Failed to set relay HIGH");
                goto cleanup;
            }
            printf("Relay %d ON\n", i + 1);
            sleep(1);

            // Deactivate relay
            ret = gpiod_line_set_value(lines[i], 0);
            if (ret < 0) {
                perror("Failed to set relay LOW");
                goto cleanup;
            }
            printf("Relay %d OFF\n", i + 1);
            sleep(1);
        }
    }

cleanup:
    // Deactivate all relays before releasing
    for (i = 0; i < num_relays; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Relay sequencer stopped.\n");
    return EXIT_SUCCESS;
}

