#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor driver pins (L298N) */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* Rain sensor ADC channel (MCP3008 single-ended) */
#define RAIN_ADC_CHANNEL 0

/* Rain threshold (0-10) */
#define RAIN_THRESHOLD 5

/* Motor run duration in seconds */
#define MOTOR_RUN_DURATION 3

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 1000000

/* PWM range and duty cycle */
#define PWM_RANGE 255
#define PWM_DUTY  150

/* Log file path */
#define LOG_FILE "rain_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer resource cleanup             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 single-ended channel                 */
/* Returns 0-1023 on success, -1 on SPI transfer failure               */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = {
        0x01,                                       /* start bit */
        (unsigned char)((0x08 | channel) << 4),     /* single-ended + channel */
        0x00                                        /* dummy for clocking data out */
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + all of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value (0-1023) to rain level (0-10)                     */
/* Sensor output is higher when dry, so ADC 1023 -> rain 0,            */
/* ADC 0 -> rain 10.                                                   */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    /* Invert: higher voltage (dry) -> higher rain level */
    return 10 - (adc_value * 10 / 1023);
}

/* ------------------------------------------------------------------ */
/* Drive motor: 1 = forward, 0 = reverse, -1 = stop                     */
/* ------------------------------------------------------------------ */
static void motor_drive(int direction)
{
    int in1, in2, pwm;

    switch (direction) {
    case 1:  /* forward */
        in1 = 1; in2 = 0; pwm = PWM_DUTY;
        break;
    case 0:  /* reverse */
        in1 = 0; in2 = 1; pwm = PWM_DUTY;
        break;
    default: /* stop */
        in1 = 0; in2 = 0; pwm = 0;
        break;
    }

    gpioWrite(MOTOR_IN1, in1);
    gpioWrite(MOTOR_IN2, in2);
    gpioPWM(MOTOR_ENA, pwm);
}

/* ------------------------------------------------------------------ */
/* Log rain reading with timestamp                                     */
/* ------------------------------------------------------------------ */
static void log_rain_reading(int rain_level)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motor first for safety */
    motor_drive(-1);

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor driver pins as outputs */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure motor is stopped at startup */
    motor_drive(-1);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int adc_value = read_mcp3008(RAIN_ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed — skipping cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int rain_level = adc_to_rain_level(adc_value);

        log_rain_reading(rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            printf("Rain detected (level %d) — closing window\n", rain_level);
            motor_drive(1);  /* forward */
            gpioDelay(MOTOR_RUN_DURATION * 1000000);
            motor_drive(-1); /* stop */
        } else {
            printf("No rain (level %d) — opening window\n", rain_level);
            motor_drive(0);  /* reverse */
            gpioDelay(MOTOR_RUN_DURATION * 1000000);
            motor_drive(-1); /* stop */
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

