#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN      26
#define LED_PIN      16
#define THRESHOLD    700   /* ~2.31 V on a 3.3 V Pi with 10-bit ADC */
#define DEBOUNCE_MS  50
#define LED_ON_MS    500
#define SAMPLE_US    1000  /* 1 kHz sampling */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a single 10-bit sample from the bit-banged ADC on MIC_PIN.
 * Returns 0..1023 on success, -1 on timeout, -2 on pin error.
 */
static int read_adc(int pin) {
    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", pin);
        return -2;
    }

    /* MAX9814 data-out is open-drain; pull-up to 3.3 V */
    if (gpioSetPullUpDown(pin, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", pin);
        return -2;
    }

    /*
     * Sample the falling edge of the MAX9814 output to capture the
     * 10-bit timecode.  We sample at 1 kHz, so a 10-bit conversion
     * takes ~10 us.  We wait for the pin to go low, then sample 10 bits.
     */
    uint32_t timeout = gpioTick() + 10000; /* 10 ms */
    while (gpioRead(pin) == 1) {
        if (gpioTick() > timeout) return -1;
    }

    int value = 0;
    for (int i = 0; i < 10; i++) {
        value <<= 1;
        timeout = gpioTick() + 1000; /* 1 ms per bit */
        while (gpioRead(pin) == 0) {
            if (gpioTick() > timeout) return -1;
        }
        value |= gpioRead(pin);
    }
    return value;
}

static void trigger_led(int pin) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Warning: failed to turn LED on\n");
        return;
    }
    gpioDelay(LED_ON_MS * 1000);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn LED off\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");

    uint32_t last_trigger = 0;

    while (running) {
        int adc = read_adc(MIC_PIN);
        if (adc < 0) {
            if (adc == -1) {
                fprintf(stderr, "Warning: ADC timeout (sensor absent or bus error)\n");
            }
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (adc > THRESHOLD) {
            uint32_t now = gpioTick();
            if (now - last_trigger > DEBOUNCE_MS * 1000) {
                trigger_led(LED_PIN);
                last_trigger = now;

                time_t rawtime;
                time(&rawtime);
                struct tm *timeinfo = localtime(&rawtime);
                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("[%s] Clap detected!\n", timestamp);
                fflush(stdout);
            }
        }

        gpioDelay(SAMPLE_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

