#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define PROXIMITY_THRESHOLD_MM 200.0
#define VOLTAGE_A 26.0
#define VOLTAGE_B -6.0
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_to_file(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", value) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_from_file(const char *path, char *buf, size_t buf_size) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (!fgets(buf, (int)buf_size, fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_export(int pin) {
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    return write_to_file("/sys/class/gpio/export", pin_str);
}

static int gpio_unexport(int pin) {
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    return write_to_file("/sys/class/gpio/unexport", pin_str);
}

static int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    return write_to_file(path, direction);
}

static int gpio_read_value(int pin) {
    char path[64];
    char value_str[4];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    if (read_from_file(path, value_str, sizeof(value_str)) != 0) {
        return -1;
    }
    return (value_str[0] == '1') ? 1 : 0;
}

static float calculate_distance(int gpio_value) {
    float voltage = (gpio_value == 1) ? 3.3f : 0.0f;
    return VOLTAGE_A / voltage + VOLTAGE_B;
}

static int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static void check_proximity(float distance) {
    if (distance < PROXIMITY_THRESHOLD_MM) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }
    printf("GPIO %d exported\n", GPIO_PIN);

    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }
    printf("GPIO %d set to input mode\n", GPIO_PIN);

    while (running) {
        int gpio_value = gpio_read_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Error reading GPIO %d, retrying in %d seconds...\n", GPIO_PIN, POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        float distance = calculate_distance(gpio_value);
        printf("Distance: %.2f mm\n", distance);

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        check_proximity(distance);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpio_unexport(GPIO_PIN);
    printf("GPIO %d unexported\n", GPIO_PIN);
    return 0;
}

