int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }
    printf("GPIO %d exported\n", GPIO_PIN);

    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }
    printf("GPIO %d set to input mode\n", GPIO_PIN);

    while (running) {
        int gpio_value = gpio_read_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Error reading GPIO %d, retrying in %d seconds...\n", GPIO_PIN, POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        float distance = calculate_distance(gpio_value);
        printf("Distance: %.2f mm\n", distance);

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        check_proximity(distance);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpio_unexport(GPIO_PIN);
    printf("GPIO %d unexported\n", GPIO_PIN);
    return 0;
}

