/*
 * DRV5055-A1 Hall-effect sensor reader via MCP3008 ADC on Raspberry Pi Zero W.
 *
 * Hardware:
 *   MCP3008 VDD/VREF -> Pi 3.3 V (physical pin 1)
 *   MCP3008 DOUT     -> GPIO 10 (physical pin 19)
 *   MCP3008 DIN      -> GPIO 9  (physical pin 21)
 *   MCP3008 CLK      -> GPIO 11 (physical pin 23)
 *   MCP3008 CS/SHDN  -> GPIO 8  (physical pin 24)
 *   DRV5055-A1 VOUT  -> MCP3008 CH0
 *   DRV5055-A1 VCC   -> 3.3 V
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_mcp3008 hall_mcp3008.c -lgpiod
 *
 * Run:
 *   ./hall_mcp3008
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        0

#define GPIO_CHIP       "gpiochip0"
#define CS_GPIO_LINE    8          /* GPIO 8 = physical pin 24 */

#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define VREF_MV         3300       /* 3.3 V reference in mV */

/* DRV5055-A1: 100 mV/mT, VCC/2 quiescent = 1650 mV */
#define SENSITIVITY_MV_MT  100.0f
#define QUIESCENT_MV       1650.0f

#define SAMPLE_INTERVAL_US 500000U /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (adc_out set), -1 on error.
 */
static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line,
                        uint8_t channel, uint16_t *adc_out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }
    if (adc_out == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     *
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;          /* we manage CS manually */

    /* Assert CS (active low) */
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    /* Small settle delay so the ADC clock sees the CS low */
    usleep(1);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);  /* release CS on error */
        return -1;
    }

    /* Deassert CS */
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    *adc_out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

static int log_data(FILE *fp, time_t timestamp, float magnetic_field_mt)
{
    if (fprintf(fp, "%ld,%.2f\n", (long)timestamp, magnetic_field_mt) < 0) {
        fprintf(stderr, "Failed to write log entry: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    log_fp = fopen("magnetic_log.txt", "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open magnetic_log.txt: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request CS line --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (cs_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure CS is deasserted (high) at start */
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to initialize CS line high: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("DRV5055-A1 Hall sensor via MCP3008 started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(spi_fd, cs_line, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Convert ADC counts to voltage in mV */
        float voltage_mv = (float)adc_value * VREF_MV / (float)ADC_MAX_VALUE;

        /* DRV5055-A1: B (mT) = (Vout - Vquiescent) / sensitivity */
        float magnetic_field_mt = (voltage_mv - QUIESCENT_MV) / SENSITIVITY_MV_MT;

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "time() failed: %s\n", strerror(errno));
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(log_fp, now, magnetic_field_mt) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

