#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 21
#define THRESHOLD_MT 10.0
#define VCC 3.3
#define SENSITIVITY_MV_PER_MT (1.65)  /* 3.3 V, 2.5 V/mT */
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1 on error. */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI command: start bit, single-ended + channel, then dummy */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_voltage(int adc) {
    return (double)adc * VCC / 1023.0;
}

static double voltage_to_field_mt(double v) {
    double mid = VCC / 2.0;
    return (v - mid) * 1000.0 / SENSITIVITY_MV_PER_MT;
}

static void log_field(double field_mt) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Field: %.2f mT\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, field_mt);
    }
    fclose(fp);
}

static void control_led(double field_mt) {
    gpioWrite(LED_GPIO, (field_mt > THRESHOLD_MT) ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double v = adc_to_voltage(adc);
        double field = voltage_to_field_mt(v);

        log_field(field);
        control_led(field);

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Graceful cleanup */
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

