#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W — MLX91211 current sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD/VREF -> Pi 5V (pin 2 or 4)
 *   MCP3008 AGND/DGND -> Pi GND (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> Pi GPIO8  (CE0,  pin 24)
 *   MCP3008 CH0  -> MLX91211 AOUT (analog output, pin 1)
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * MLX91211 output is ratiometric: 2.5 V (VDD/2) at zero current,
 * 5.0 V (VDD) at full-scale +50 A.  We linearly interpolate between
 * those points.
 */

#define SPI_CHANNEL      0          /* SPI0 CE0 (hardware SPI)          */
#define SPI_SPEED        1000000    /* 1 MHz                            */
#define SPI_FLAGS        0          /* mode 0, active-low CE            */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0   */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC                       */
#define ADC_VREF         5.0        /* MCP3008 VREF tied to 5V          */
#define MLX_VZERO        2.5        /* MLX91211 output at zero current  */
#define MLX_VFULLSCALE   5.0        /* MLX91211 output at full-scale    */
#define CURRENT_FULLSCALE 50.0      /* Amperes at full-scale             */
#define LOG_FILE         "current_log.txt"
#define SAMPLE_PERIOD_US 100000     /* 100 ms                           */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out), -1 on SPI transfer error.
 */
static int read_mcp3008(int spi_handle, int channel, int *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = 0x80 | (channel << 4)      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
     */
    unsigned char tx[3] = { 0x01,
                            (unsigned char)(0x80 | (channel << 4)),
                            0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/*
 * Convert raw ADC code to current (Amperes).
 * Returns 0 on success, -1 if voltage is outside the valid range.
 */
static int raw_to_current(int raw, double *current)
{
    double voltage = ((double)raw / (double)ADC_MAX_VALUE) * ADC_VREF;

    if (voltage < 0.0 || voltage > ADC_VREF) {
        fprintf(stderr, "Voltage out of range: %.4f V (raw=%d)\n", voltage, raw);
        return -1;
    }

    /* Linear interpolation between VZERO and VFULLSCALE */
    *current = (voltage - MLX_VZERO) * (CURRENT_FULLSCALE / (MLX_VFULLSCALE - MLX_VZERO));
    return 0;
}

static void log_current(FILE *fp, double current)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    fflush(fp);
}

int main(void)
{
    int spi_handle = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        goto cleanup_gpio;
    }

    /* --- Open log file for appending --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        goto cleanup_spi;
    }

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        goto cleanup_all;
    }

    printf("MLX91211 current monitor started.  Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int raw = 0;

        if (read_mcp3008(spi_handle, ADC_CHANNEL, &raw) != 0) {
            /* SPI error — skip this sample, keep running */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double current;
        if (raw_to_current(raw, &current) != 0) {
            /* Voltage out of range — skip this sample */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_current(fp, current);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        fclose(fp);
    }
cleanup_spi:
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

