#define SENSOR2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a GPIO line with simple debouncing.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_debounced(struct gpiod_line *line) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line\n");
            return -1;
        }
        sum += val;
        if (i < DEBOUNCE_SAMPLES - 1) {
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }
    }
    return (sum >= (DEBOUNCE_SAMPLES / 2) + 1) ? 1 : 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip4 on Raspberry Pi 5) */
    chip = gpiod_chip_open_by_number(4);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line (sensor 1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line (sensor 2)");
        goto cleanup;
    }

    /* Request both lines as inputs */
    if (gpiod_line_request_input(line1, "b5w-db01") < 0) {
        perror("gpiod_line_request_input (sensor 1)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-db01") < 0) {
        perror("gpiod_line_request_input (sensor 2)");
        goto cleanup;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Monitoring Omron B5W-DB01 sensors on GPIO%d and GPIO%d...\n",
           SENSOR1_PIN, SENSOR2_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_debounced(line1);
        int s2 = read_debounced(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor data, exiting.\n");
            goto cleanup;
        }

        printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

