#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define PIR_PIN 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_US 50000
#define IMAGE_DIR "/home/pi/security_cam"
#define FILENAME_MAX_LEN 256

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return S_ISDIR(st.st_mode) ? 0 : -1;
    }
    if (mkdir(path, 0755) != 0) {
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork failed: %m");
        return -1;
    }
    if (pid == 0) {
        char *argv[] = {"libcamera-still", "-o", (char *)filename, "--width",
                        "1280", "--height", "720", "--nopreview", NULL};
        execvp("libcamera-still", argv);
        syslog(LOG_ERR, "execvp libcamera-still failed: %m");
        _exit(127);
    }
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid failed: %m");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "libcamera-still failed (status=%d)", status);
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting motion detector on BCM GPIO%d", PIR_PIN);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(IMAGE_DIR) != 0) {
        syslog(LOG_ERR, "Cannot create or access directory %s", IMAGE_DIR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(PIR_PIN);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring started. Initial state: %s", last_state ? "motion" : "idle");

    while (running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed: %m");
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            int confirmed = gpioRead(PIR_PIN);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead (debounce) failed: %m");
                break;
            }
            if (confirmed == current_state) {
                if (current_state == 1) {
                    syslog(LOG_INFO, "Motion detected!");

                    time_t rawtime;
                    struct tm timeinfo;
                    char timestamp[32];
                    time(&rawtime);
                    localtime_r(&rawtime, &timeinfo);
                    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &timeinfo);

                    char filename[FILENAME_MAX_LEN];
                    int n = snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", IMAGE_DIR, timestamp);
                    if (n < 0 || (size_t)n >= sizeof(filename)) {
                        syslog(LOG_ERR, "Filename too long");
                    } else {
                        if (capture_image(filename) == 0) {
                            syslog(LOG_INFO, "Image captured: %s", filename);
                        } else {
                            syslog(LOG_ERR, "Failed to capture image");
                        }
                    }
                }
                last_state = current_state;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down.");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

