#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define VIDEO_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define MAX_PAYLOAD 65000
#define HEADER_SIZE 16
#define FRAME_SIZE (WIDTH * HEIGHT * 2)

typedef struct {
    unsigned int frame_index;
    unsigned int fragment_index;
    unsigned int total_fragments;
    unsigned int payload_size;
} fragment_header_t;

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static volatile sig_atomic_t running = 1;
static int video_fd = -1;
static int sockfd = -1;
static buffer_t buffers[NUM_BUFFERS];
static unsigned int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    if (xioctl(video_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        goto fail_close;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        goto fail_close;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        goto fail_close;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(video_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        goto fail_close;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Error: format YUYV not supported\n");
        goto fail_close;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        goto fail_close;
    }

    if (req.count < 1) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        goto fail_close;
    }

    for (i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            goto fail_unmap;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            buffers[i].start = NULL;
            goto fail_unmap;
        }
    }

    buffer_count = req.count;
    return 0;

fail_unmap:
    for (i = 0; i < buffer_count; i++) {
        if (buffers[i].start && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
            buffers[i].start = NULL;
        }
    }
fail_close:
    close(video_fd);
    video_fd = -1;
    return -1;
}

static int start_streaming(void) {
    unsigned int i;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    for (i = 0; i < buffer_count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    if (xioctl(video_fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }
    return 0;
}

static int stop_streaming(void) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (video_fd >= 0) {
        if (xioctl(video_fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("Error stopping stream");
            return -1;
        }
    }
    return 0;
}

static void cleanup(void) {
    unsigned int i;
    if (video_fd >= 0) {
        stop_streaming();
        close(video_fd);
        video_fd = -1;
    }
    for (i = 0; i < buffer_count; i++) {
        if (buffers[i].start && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
            buffers[i].start = NULL;
        }
    }
    buffer_count = 0;
    if (sockfd >= 0) {
        close(sockfd);
        sockfd = -1;
    }
}

static int send_fragment(const unsigned char *data, unsigned int data_len,
                         const struct sockaddr_in *server_addr,
                         unsigned int frame_index, unsigned int frag_index,
                         unsigned int total_frags) {
    fragment_header_t header;
    unsigned char *packet = malloc(MAX_PAYLOAD);
    if (!packet) {
        perror("malloc failed");
        return -1;
    }

    header.frame_index = frame_index;
    header.fragment_index = frag_index;
    header.total_fragments = total_frags;
    header.payload_size = data_len;

    memcpy(packet, &header, HEADER_SIZE);
    memcpy(packet + HEADER_SIZE, data, data_len);

    ssize_t sent = sendto(sockfd, packet, HEADER_SIZE + data_len, 0,
                          (const struct sockaddr *)server_addr, sizeof(*server_addr));
    free(packet);

    if (sent < 0) {
        perror("sendto failed");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    struct v4l2_buffer buf;
    struct sockaddr_in server_addr;
    unsigned int frame_index = 0;
    unsigned int frag_index = 0;
    unsigned int total_frags = 0;
    unsigned char *frame_data = NULL;
    size_t frame_data_len = 0;
    size_t frame_data_alloc = 0;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    if (init_camera() < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    if (start_streaming() < 0) {
        fprintf(stderr, "Streaming initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(atoi(argv[2]));
    if (inet_pton(AF_INET, argv[1], &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", argv[1]);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Streaming video to %s:%s\n", argv[1], argv[2]);

    while (running) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(video_fd, &fds);

        tv.tv_sec = 1;
        tv.tv_usec = 0;

        r = select(video_fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) continue;
            perror("select failed");
            break;
        }
        if (r == 0) continue;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF failed");
            break;
        }

        if (buf.index >= buffer_count) {
            fprintf(stderr, "Invalid buffer index: %u\n", buf.index);
            break;
        }

        if (frame_data_alloc < buf.bytesused) {
            size_t new_alloc = buf.bytesused;
            if (new_alloc < FRAME_SIZE) new_alloc = FRAME_SIZE;
            unsigned char *new_data = realloc(frame_data, new_alloc);
            if (!new_data) {
                perror("realloc failed");
                break;
            }
            frame_data = new_data;
            frame_data_alloc = new_alloc;
        }

        memcpy(frame_data, buffers[buf.index].start, buf.bytesused);
        frame_data_len = buf.bytesused;

        if (xioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF failed");
            break;
        }

        total_frags = (frame_data_len + MAX_PAYLOAD - HEADER_SIZE - 1) / (MAX_PAYLOAD - HEADER_SIZE);
        if (total_frags == 0) total_frags = 1;

        for (frag_index = 0; frag_index < total_frags; frag_index++) {
            size_t frag_len = frame_data_len - frag_index * (MAX_PAYLOAD - HEADER_SIZE);
            if (frag_len > MAX_PAYLOAD - HEADER_SIZE) frag_len = MAX_PAYLOAD - HEADER_SIZE;
            if (send_fragment(frame_data + frag_index * (MAX_PAYLOAD - HEADER_SIZE),
                              (unsigned int)frag_len, &server_addr,
                              frame_index, frag_index, total_frags) < 0) {
                fprintf(stderr, "Failed to send fragment %u of %u\n", frag_index, total_frags);
                break;
            }
        }

        frame_index++;
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

