/*
 * Pan-tilt camera control using two servos and four push buttons.
 *
 * Hardware (Raspberry Pi 40-pin header):
 *   Pan  servo signal -> GPIO4 (pin 7)
 *   Tilt servo signal -> GPIO5 (pin 29)
 *   Tilt up button    -> GPIO6 (pin 31, active-low, internal pull-up)
 *   Tilt down button  -> GPIO7 (pin 22, active-low, internal pull-up)
 *   Pan  left  button -> GPIO8 (pin 27, active-low, internal pull-up)
 *   Pan  right button -> GPIO9 (pin 18, active-low, internal pull-up)
 *
 * Servo pulse width range: 1 ms (min) to 2 ms (max) -> duty 50-100/1000
 * Software PWM: 50 Hz period (20 ms), 1000-step resolution
 *
 * Build: gcc -O2 -Wall -Wextra -o pan_tilt pan_tilt.c -lgpiod
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define CHIP_NAME       "gpiochip4"   /* BCM2711 GPIO controller on Pi 5 */
#define PAN_PIN         4
#define TILT_PIN        5
#define TILT_UP_PIN     6
#define TILT_DOWN_PIN   7
#define PAN_LEFT_PIN    8
#define PAN_RIGHT_PIN   9

#define PWM_PERIOD_US   20000         /* 50 Hz */
#define PWM_STEPS       1000
#define MIN_DUTY        50            /* 1 ms */
#define MAX_DUTY        100           /* 2 ms */
#define MID_DUTY        75            /* 1.5 ms */
#define STEP_SIZE       5
#define POLL_MS         50

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Software PWM helpers ---- */

static void pwm_write(struct gpiod_line *line, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_STEPS) duty = PWM_STEPS;

    int on_us  = (duty * PWM_PERIOD_US) / PWM_STEPS;
    int off_us = PWM_PERIOD_US - on_us;

    if (on_us > 0) {
        if (gpiod_line_set_value(line, 1) < 0)
            perror("gpiod_line_set_value(1)");
        usleep(on_us);
    }
    if (off_us > 0) {
        if (gpiod_line_set_value(line, 0) < 0)
            perror("gpiod_line_set_value(0)");
        usleep(off_us);
    }
}

static void servo_set_duty(struct gpiod_line *line, int *position, int direction)
{
    *position += direction * STEP_SIZE;
    if (*position < MIN_DUTY) *position = MIN_DUTY;
    if (*position > MAX_DUTY) *position = MAX_DUTY;
    pwm_write(line, *position);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL;
    struct gpiod_line *up_line = NULL, *down_line = NULL;
    struct gpiod_line *left_line = NULL, *right_line = NULL;
    int pan_duty = MID_DUTY, tilt_duty = MID_DUTY;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    pan_line   = gpiod_chip_get_line(chip, PAN_PIN);
    tilt_line  = gpiod_chip_get_line(chip, TILT_PIN);
    up_line    = gpiod_chip_get_line(chip, TILT_UP_PIN);
    down_line  = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    left_line  = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    right_line = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_line || !tilt_line || !up_line || !down_line ||
        !left_line || !right_line) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines ---- */
    if (gpiod_line_request_output(pan_line, "pan_servo", 0) < 0) {
        perror("request pan output");
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0) {
        perror("request tilt output");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(up_line, "tilt_up",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request tilt_up input");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(down_line, "tilt_down",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request tilt_down input");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(left_line, "pan_left",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request pan_left input");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(right_line, "pan_right",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request pan_right input");
        goto cleanup;
    }

    /* ---- Start both servos at mid-position ---- */
    pwm_write(pan_line, pan_duty);
    pwm_write(tilt_line, tilt_duty);

    printf("Pan-tilt control started. Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int v;

        v = gpiod_line_get_value(up_line);
        if (v == 0) servo_set_duty(tilt_line, &tilt_duty,  1);

        v = gpiod_line_get_value(down_line);
        if (v == 0) servo_set_duty(tilt_line, &tilt_duty, -1);

        v = gpiod_line_get_value(left_line);
        if (v == 0) servo_set_duty(pan_line,   &pan_duty,  1);

        v = gpiod_line_get_value(right_line);
        if (v == 0) servo_set_duty(pan_line,   &pan_duty, -1);

        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines and close chip ---- */
    if (pan_line)   gpiod_line_release(pan_line);
    if (tilt_line)  gpiod_line_release(tilt_line);
    if (up_line)    gpiod_line_release(up_line);
    if (down_line)  gpiod_line_release(down_line);
    if (left_line)  gpiod_line_release(left_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip)       gpiod_chip_close(chip);

    return ret;
}

