#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75
#define NUM_BUFFERS 4

static volatile sig_atomic_t stop_flag = 0;

static void sigint_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, buffer_t *buffers, unsigned int *n_buffers) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(*fd);
        return -1;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "Warning: driver adjusted size to %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(*fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    *n_buffers = req.count;
    for (i = 0; i < *n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(*fd);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(*fd);
            return -1;
        }
    }

    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, buffer_t *buffers, unsigned int n_buffers, unsigned char **frame_data, unsigned int *frame_size) {
    fd_set fds;
    struct timeval tv;
    int r;
    struct v4l2_buffer buf;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("Error during select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Error: select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "Error: Invalid buffer index\n");
        return -1;
    }

    *frame_data = (unsigned char *)buffers[buf.index].start;
    *frame_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

static void cleanup_camera(int fd, buffer_t *buffers, unsigned int n_buffers) {
    unsigned int i;
    for (i = 0; i < n_buffers; i++) {
        if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }
    if (fd >= 0) {
        close(fd);
    }
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j += 2) {
            int y0 = yuyv[i * width * 2 + j * 2];
            int u = yuyv[i * width * 2 + j * 2 + 1] - 128;
            int y1 = yuyv[i * width * 2 + (j + 1) * 2];
            int v = yuyv[i * width * 2 + (j + 1) * 2 + 1] - 128;

            int r0 = y0 + 1.402 * v;
            int g0 = y0 - 0.34414 * u - 0.71414 * v;
            int b0 = y0 + 1.772 * u;
            int r1 = y1 + 1.402 * v;
            int g1 = y1 - 0.34414 * u - 0.71414 * v;
            int b1 = y1 + 1.772 * u;

            if (r0 < 0) r0 = 0; if (r0 > 255) r0 = 255;
            if (g0 < 0) g0 = 0; if (g0 > 255) g0 = 255;
            if (b0 < 0) b0 = 0; if (b0 > 255) b0 = 255;
            if (r1 < 0) r1 = 0; if (r1 > 255) r1 = 255;
            if (g1 < 0) g1 = 0; if (g1 > 255) g1 = 255;
            if (b1 < 0) b1 = 0; if (b1 > 255) b1 = 255;

            rgb[i * width * 3 + j * 3] = (unsigned char)r0;
            rgb[i * width * 3 + j * 3 + 1] = (unsigned char)g0;
            rgb[i * width * 3 + j * 3 + 2] = (unsigned char)b0;
            rgb[i * width * 3 + (j + 1) * 3] = (unsigned char)r1;
            rgb[i * width * 3 + (j + 1) * 3 + 1] = (unsigned char)g1;
            rgb[i * width * 3 + (j + 1) * 3 + 2] = (unsigned char)b1;
        }
    }
}

static void blur_image(const unsigned char *input, unsigned char *output, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int r_sum = 0, g_sum = 0, b_sum = 0;
            int count = 0;
            for (int k = -BLUR_RADIUS; k <= BLUR_RADIUS; k++) {
                for (int l = -BLUR_RADIUS; l <= BLUR_RADIUS; l++) {
                    int x = j + k;
                    int y = i + l;
                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        int idx = y * width * 3 + x * 3;
                        r_sum += input[idx];
                        g_sum += input[idx + 1];
                        b_sum += input[idx + 2];
                        count++;
                    }
                }
            }
            int idx = i * width * 3 + j * 3;
            output[idx] = (unsigned char)(r_sum / count);
            output[idx + 1] = (unsigned char)(g_sum / count);
            output[idx + 2] = (unsigned char)(b_sum / count);
        }
    }
}

static int save_jpeg(const unsigned char *image, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = NULL;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    outfile = fopen(filename, "wb");
    if (!outfile) {
        perror("Error opening output file");
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)(image + cinfo.next_scanline * row_stride);
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main(void) {
    int fd = -1;
    buffer_t buffers[NUM_BUFFERS];
    unsigned int n_buffers = 0;
    unsigned char *frame_data = NULL;
    unsigned int frame_size = 0;
    unsigned char *rgb_image = NULL;
    unsigned char *blurred_image = NULL;
    char filename[64];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (init_camera(&fd, buffers, &n_buffers) != 0) {
        fprintf(stderr, "Failed to initialize camera.\n");
        return 1;
    }

    if (start_streaming(fd) != 0) {
        fprintf(stderr, "Failed to start streaming.\n");
        cleanup_camera(fd, buffers, n_buffers);
        return 1;
    }

    if (capture_frame(fd, buffers, n_buffers, &frame_data, &frame_size) != 0) {
        fprintf(stderr, "Failed to capture frame.\n");
        stop_streaming(fd);
        cleanup_camera(fd, buffers, n_buffers);
        return 1;
    }

    if (stop_streaming(fd) != 0) {
        fprintf(stderr, "Failed to stop streaming.\n");
        cleanup_camera(fd, buffers, n_buffers);
        return 1;
    }

    rgb_image = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!rgb_image) {
        perror("Error allocating RGB image");
        cleanup_camera(fd, buffers, n_buffers);
        return 1;
    }

    blurred_image = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!blurred_image) {
        perror("Error allocating blurred image");
        free(rgb_image);
        cleanup_camera(fd, buffers, n_buffers);
        return 1;
    }

    yuyv_to_rgb24(frame_data, rgb_image, IMAGE_WIDTH, IMAGE_HEIGHT);
    blur_image(rgb_image, blurred_image, IMAGE_WIDTH, IMAGE_HEIGHT);

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (save_jpeg(blurred_image, IMAGE_WIDTH, IMAGE_HEIGHT, filename) != 0) {
        fprintf(stderr, "Failed to save JPEG.\n");
    } else {
        printf("Saved blurred image to %s\n", filename);
    }

    free(rgb_image);
    free(blurred_image);
    cleanup_camera(fd, buffers, n_buffers);
    return 0;
}

