/*
 * V4L2 camera capabilities query for Raspberry Pi.
 *
 * Queries a CSI camera at /dev/video0 for supported resolutions,
 * frame rates, and autofocus capability.  Uses the V4L2 API.
 *
 * Build:  gcc -O2 -Wall -Wextra -o v4l2_query v4l2_query.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_fourcc(unsigned int pixelformat)
{
    printf("    %c%c%c%c",
           (char)(pixelformat & 0xFF),
           (char)((pixelformat >> 8) & 0xFF),
           (char)((pixelformat >> 16) & 0xFF),
           (char)((pixelformat >> 24) & 0xFF));
}

static void print_res(unsigned int width, unsigned int height)
{
    printf("    %ux%u", width, height);
}

static void print_fps(unsigned int numerator, unsigned int denominator)
{
    if (denominator == 0)
        printf("    ? fps");
    else
        printf("    %u/%u fps", numerator, denominator);
}

static int query_capabilities(int fd, struct v4l2_capability *cap)
{
    memset(cap, 0, sizeof(*cap));
    cap->capability = V4L2_CAP_DEVICE_CAPS;

    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int query_controls(int fd)
{
    struct v4l2_queryctrl qctrl;

    memset(&qctrl, 0, sizeof(qctrl));
    qctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &qctrl) < 0) {
        if (errno == EINVAL) {
            printf("  Autofocus: No autofocus control available.\n");
            return 0;
        }
        fprintf(stderr, "VIDIOC_QUERYCTRL failed: %s\n", strerror(errno));
        return -1;
    }

    printf("  Autofocus: ");
    if (qctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("Disabled\n");
    } else if (qctrl.type == V4L2_CTRL_TYPE_BOOLEAN) {
        printf("Supported (boolean)\n");
    } else {
        printf("Supported (type %u)\n", qctrl.type);
    }
    return 0;
}

static int enumerate_frame_sizes(int fd)
{
    struct v4l2_frmsizeenum frmsize;
    int ret = 0;

    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV;

    printf("  Frame sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        switch (frmsize.type) {
        case V4L2_FRMSIZE_TYPE_DISCRETE:
            print_fourcc(frmsize.pixel_format);
            print_res(frmsize.discrete.width, frmsize.discrete.height);
            printf("\n");
            break;
        case V4L2_FRMSIZE_TYPE_STEPWISE:
            print_fourcc(frmsize.pixel_format);
            printf("  stepwise: %ux%u - %ux%u, step %ux%u\n",
                   frmsize.stepwise.min_width, frmsize.stepwise.min_height,
                   frmsize.stepwise.max_width, frmsize.stepwise.max_height,
                   frmsize.stepwise.step_width, frmsize.stepwise.step_height);
            break;
        case V4L2_FRMSIZE_TYPE_CONTINUOUS:
            print_fourcc(frmsize.pixel_format);
            printf("  continuous: %ux%u - %ux%u\n",
                   frmsize.stepwise.min_width, frmsize.stepwise.min_height,
                   frmsize.stepwise.max_width, frmsize.stepwise.max_height);
            break;
        default:
            print_fourcc(frmsize.pixel_format);
            printf("  unknown type %u\n", frmsize.type);
            break;
        }
        frmsize.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
        ret = -1;
    }
    return ret;
}

static int enumerate_frame_rates(int fd)
{
    struct v4l2_frmivalenum frmival;
    int ret = 0;

    memset(&frmival, 0, sizeof(frmival));
    frmival.pixel_format = V4L2_PIX_FMT_YUYV;
    frmival.width = 640;
    frmival.height = 480;

    printf("  Frame rates:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        print_res(frmival.width, frmival.height);
        switch (frmival.type) {
        case V4L2_FRMIVAL_TYPE_DISCRETE:
            print_fps(frmival.discrete.numerator, frmival.discrete.denominator);
            printf("\n");
            break;
        case V4L2_FRMIVAL_TYPE_STEPWISE:
            printf("  stepwise: ");
            print_fps(frmival.stepwise.min.numerator, frmival.stepwise.min.denominator);
            printf(" - ");
            print_fps(frmival.stepwise.max.numerator, frmival.stepwise.max.denominator);
            printf(", step ");
            print_fps(frmival.stepwise.step.numerator, frmival.stepwise.step.denominator);
            printf("\n");
            break;
        case V4L2_FRMIVAL_TYPE_CONTINUOUS:
            printf("  continuous: ");
            print_fps(frmival.stepwise.min.numerator, frmival.stepwise.min.denominator);
            printf(" - ");
            print_fps(frmival.stepwise.max.numerator, frmival.stepwise.max.denominator);
            printf("\n");
            break;
        default:
            printf("  unknown type %u\n", frmival.type);
            break;
        }
        frmival.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
        ret = -1;
    }
    return ret;
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    int rc = EXIT_SUCCESS;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (query_capabilities(fd, &cap) < 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (!(cap.capability & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture.\n", DEVICE_NAME);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (!(cap.capability & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O.\n", DEVICE_NAME);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Camera capabilities for %s:\n", DEVICE_NAME);
    printf("  Driver: %s\n", cap.driver);
    printf("  Card:   %s\n", cap.card);
    printf("  Bus:    %s\n", cap.bus_info);

    if (enumerate_frame_sizes(fd) < 0)
        rc = EXIT_FAILURE;

    if (enumerate_frame_rates(fd) < 0)
        rc = EXIT_FAILURE;

    if (query_controls(fd) < 0)
        rc = EXIT_FAILURE;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

