        case V4L2_FRMIVAL_TYPE_STEPWISE:
            printf("  stepwise: ");
            print_fps(frmival.stepwise.min.numerator, frmival.stepwise.min.denominator);
            printf(" - ");
            print_fps(frmival.stepwise.max.numerator, frmival.stepwise.max.denominator);
            printf(", step ");
            print_fps(frmival.stepwise.step.numerator, frmival.stepwise.step.denominator);
            printf("\n");
            break;
        case V4L2_FRMIVAL_TYPE_CONTINUOUS:
            printf("  continuous: ");
            print_fps(frmival.stepwise.min.numerator, frmival.stepwise.min.denominator);
            printf(" - ");
            print_fps(frmival.stepwise.max.numerator, frmival.stepwise.max.denominator);
            printf("\n");
            break;
        default:
            printf("  unknown type %u\n", frmival.type);
            break;
        }
        frmival.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
        ret = -1;
    }
    return ret;
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    int rc = EXIT_SUCCESS;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (query_capabilities(fd, &cap) < 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (!(cap.capability & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture.\n", DEVICE_NAME);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (!(cap.capability & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O.\n", DEVICE_NAME);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Camera capabilities for %s:\n", DEVICE_NAME);
    printf("  Driver: %s\n", cap.driver);
    printf("  Card:   %s\n", cap.card);
    printf("  Bus:    %s\n", cap.bus_info);

    if (enumerate_frame_sizes(fd) < 0)
        rc = EXIT_FAILURE;

    if (enumerate_frame_rates(fd) < 0)
        rc = EXIT_FAILURE;

    if (query_controls(fd) < 0)
        rc = EXIT_FAILURE;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

