#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE  1000
#define SERVO_MAX_PULSE  2000
#define SERVO_CENTER     1500
#define STEP_SIZE        10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int clamp_pulse(int pulse) {
    if (pulse < SERVO_MIN_PULSE) return SERVO_MIN_PULSE;
    if (pulse > SERVO_MAX_PULSE) return SERVO_MAX_PULSE;
    return pulse;
}

int main(void) {
    int pan_pulse  = SERVO_CENTER;
    int tilt_pulse = SERVO_CENTER;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    gpioServo(PAN_SERVO_PIN, pan_pulse);
    gpioServo(TILT_SERVO_PIN, tilt_pulse);

    printf("Pan-tilt control started.\n");
    printf("Pan servo: GPIO%d | Tilt servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Buttons (active-low): UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Servos centered at %d us. Press Ctrl+C to exit.\n", SERVO_CENTER);

    while (g_running) {
        if (!gpioRead(UP_BUTTON_PIN)) {
            tilt_pulse = clamp_pulse(tilt_pulse + STEP_SIZE);
            gpioServo(TILT_SERVO_PIN, tilt_pulse);
        }
        if (!gpioRead(DOWN_BUTTON_PIN)) {
            tilt_pulse = clamp_pulse(tilt_pulse - STEP_SIZE);
            gpioServo(TILT_SERVO_PIN, tilt_pulse);
        }
        if (!gpioRead(LEFT_BUTTON_PIN)) {
            pan_pulse = clamp_pulse(pan_pulse - STEP_SIZE);
            gpioServo(PAN_SERVO_PIN, pan_pulse);
        }
        if (!gpioRead(RIGHT_BUTTON_PIN)) {
            pan_pulse = clamp_pulse(pan_pulse + STEP_SIZE);
            gpioServo(PAN_SERVO_PIN, pan_pulse);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

