#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 2000
#define POLL_INTERVAL_US 100000
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512
#define MAX_URL_LEN 256

static volatile sig_atomic_t g_running = 1;
static const char *g_server_ip = NULL;
static int g_server_port = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        if (errno == EEXIST) return 0;
        fprintf(stderr, "Error creating directory '%s': %s\n", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(char *filename, size_t filename_len) {
    if (ensure_capture_dir() != 0) return -1;

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &timeinfo);

    snprintf(filename, filename_len, "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);

    char command[512];
    int n = snprintf(command, sizeof(command),
                     "libcamera-still -o %s --width %d --height %d --quality %d --nopreview",
                     filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY);
    if (n < 0 || (size_t)n >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }

    int ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Error executing libcamera-still: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "libcamera-still failed (exit status %d)\n", WEXITSTATUS(ret));
        return -1;
    }
    return 0;
}

static int format_json(const char *filename, int motion_status, int gpio_pin, char *json_str, size_t json_str_len) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    int n = snprintf(json_str, json_str_len,
                     "{\"filename\": \"%s\", \"timestamp\": \"%s.%06ldZ\", \"motion_status\": %d, \"gpio_pin\": %d}",
                     filename, timestamp, ts.tv_nsec / 1000, motion_status, gpio_pin);
    if (n < 0 || (size_t)n >= json_str_len) {
        fprintf(stderr, "Error: JSON buffer too small\n");
        return -1;
    }
    return 0;
}

static int send_data(const char *json_str) {
    char url[MAX_URL_LEN];
    int n = snprintf(url, sizeof(url), "http://%s:%d/upload", g_server_ip, g_server_port);
    if (n < 0 || (size_t)n >= sizeof(url)) {
        fprintf(stderr, "Error: URL buffer too small\n");
        return -1;
    }

    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_str);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code < 200 || http_code >= 300) {
        fprintf(stderr, "Error: HTTP response code %ld\n", http_code);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    g_server_ip = argv[1];
    g_server_port = atoi(argv[2]);
    if (g_server_port <= 0 || g_server_port > 65535) {
        fprintf(stderr, "Error: Invalid port number\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (g_running) {
        int motion = gpioRead(PIR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", PIR_GPIO);
            break;
        }

        if (motion == 1) {
            char filename[MAX_FILENAME_LEN];
            if (capture_image(filename, sizeof(filename)) == 0) {
                char json_str[MAX_JSON_LEN];
                if (format_json(filename, motion, PIR_GPIO, json_str, sizeof(json_str)) == 0) {
                    if (send_data(json_str) != 0) {
                        fprintf(stderr, "Warning: Failed to send data to server\n");
                    }
                }
            } else {
                fprintf(stderr, "Warning: Failed to capture image\n");
            }

            gpioDelay(DEBOUNCE_MS * 1000);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    curl_global_cleanup();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

