    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (g_running) {
        int motion = gpioRead(PIR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", PIR_GPIO);
            break;
        }

        if (motion == 1) {
            char filename[MAX_FILENAME_LEN];
            if (capture_image(filename, sizeof(filename)) == 0) {
                char json_str[MAX_JSON_LEN];
                if (format_json(filename, motion, PIR_GPIO, json_str, sizeof(json_str)) == 0) {
                    if (send_data(json_str) != 0) {
                        fprintf(stderr, "Warning: Failed to send data to server\n");
                    }
                }
            } else {
                fprintf(stderr, "Warning: Failed to capture image\n");
            }

            gpioDelay(DEBOUNCE_MS * 1000);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    curl_global_cleanup();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

