/*
 * PIR-triggered camera capture for Raspberry Pi Zero W.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor data pin -> BCM GPIO17 (physical pin 11)
 *   - Raspberry Pi Camera Module v2 (I2C bus 1, address 0x10)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motion_capture motion_capture.c -lgpiod
 *
 * Run:
 *   sudo ./motion_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define PIR_GPIO_LINE       17
#define IMAGE_DIR           "/home/pi/images"
#define LOG_FILE            "/home/pi/motion_capture.log"
#define DEBOUNCE_MS         50
#define POLL_TIMEOUT_MS     1000
#define LIBCAMERA_TIMEOUT_MS 2000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

static int generate_timestamped_filename(char *buf, size_t buflen)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm))
        return -1;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0)
        return -1;
    int ms = (int)(ts.tv_nsec / 1000000);
    if (snprintf(buf, buflen, "%04d%02d%02d_%02d%02d%02d_%03d.jpg",
                 tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec, ms) >= (int)buflen)
        return -1;
    return 0;
}

static int capture_image(const char *filename)
{
    char command[512];
    if (snprintf(command, sizeof(command),
                 "libcamera-still -o '%s' --width 640 --height 480 -q 85 --timeout %d --nopreview",
                 filename, LIBCAMERA_TIMEOUT_MS) >= (int)sizeof(command)) {
        log_event("Command buffer overflow");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        log_event("system() failed to launch libcamera-still");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        char msg[256];
        snprintf(msg, sizeof(msg), "libcamera-still failed (raw=%d, exit=%d)",
                 status, WIFEXITED(status) ? WEXITSTATUS(status) : -1);
        log_event(msg);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_event("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        log_event("Failed to get GPIO17 line");
        goto cleanup;
    }

    /* Request falling-edge events with 50 ms debounce. */
    if (gpiod_line_request_falling_edge_events_flags(pir_line, "pir-motion",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_falling_edge_events_flags");
        log_event("Failed to request falling-edge events on GPIO17");
        goto cleanup;
    }

    log_event("Motion capture service started");

    while (g_running) {
        struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
        int ev = gpiod_line_event_wait(pir_line, &ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            log_event("Error waiting for PIR event");
            break;
        }
        if (ev == 0)
            continue; /* timeout, no event */

        /* Debounce: wait 50 ms and re-check the line. */
        struct timespec debounce = { 0, DEBOUNCE_MS * 1000000L };
        nanosleep(&debounce, NULL);
        if (gpiod_line_get_value(pir_line) == 0)
            continue; /* line still high after debounce */

        char filename[128];
        if (generate_timestamped_filename(filename, sizeof(filename)) != 0) {
            log_event("Failed to generate timestamped filename");
            continue;
        }

        char fullpath[256];
        if (snprintf(fullpath, sizeof(fullpath), "%s/%s", IMAGE_DIR, filename) >= (int)sizeof(fullpath)) {
            log_event("Image path too long");
            continue;
        }

        if (capture_image(fullpath) == 0) {
            char msg[300];
            snprintf(msg, sizeof(msg), "Image captured: %s", fullpath);
            log_event(msg);
        } else {
            log_event("Image capture failed");
        }
    }

    log_event("Motion capture service stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (pir_line)
        gpiod_line_release(pir_line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

