code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_W 200
#define CROP_H 150
#define OUTPUT_FILE "cropped.yuv"
#define SELECT_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT ||
        fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Warning: device negotiated %ux%u %c%c%c%c\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height,
                (fmt.fmt.pix.pixelformat >> 0) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 8) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 16) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 24) & 0xFF);
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = SELECT_TIMEOUT_SEC;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            if (stop_flag) {
                fprintf(stderr, "Interrupted by signal\n");
                goto cleanup;
            }
            perror("select (EINTR)");
            goto cleanup;
        }
        perror("select");
        goto cleanup;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout: no frame captured\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused < (unsigned int)(CROP_W * CROP_H * 2)) {
        fprintf(stderr, "Frame too small: %u bytes, need %d\n",
                buf.bytesused, CROP_W * CROP_H * 2);
        goto cleanup;
    }

    fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        perror("fopen(" OUTPUT_FILE ")");
        goto cleanup;
    }

    unsigned char *src = (unsigned char *)buffer;
    unsigned char *dst = malloc(CROP_W * CROP_H * 2);
    if (!dst) {
        perror("malloc");
        goto cleanup;
    }

    for (int y = 0; y < CROP_H; y++) {
        int src_row = (CROP_Y + y) * WIDTH * 2;
        int dst_row = y * CROP_W * 2;
        memcpy(dst + dst_row, src + src_row + CROP_X * 2, CROP_W * 2);
    }

    size_t written = fwrite(dst, 1, CROP_W * CROP_H * 2, fp);
    if (written != (size_t)(CROP_W * CROP_H * 2)) {
        perror("fwrite");
        free(dst);
        goto cleanup;
    }

    free(dst);
    printf("Cropped %dx%d frame saved to %s\n", CROP_W, CROP_H, OUTPUT_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (buffer && buffer != MAP_FAILED) munmap(buffer, buf.length);
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    return ret;
}

