#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define NEUTRAL_ANGLE 90
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define PWM_FREQUENCY 50
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) / (MAX_ANGLE - MIN_ANGLE);
}

int set_servo_angle(int gpio, int angle) {
    int pw = angle_to_pulse_width(angle);
    if (pw < 0) return -1;
    if (gpioPWM(gpio, pw) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

void cleanup(void) {
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    if (set_servo_angle(PAN_GPIO, pan_angle) != 0 ||
        set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
        cleanup();
        return 1;
    }

    signal(SIGINT, handle_signal);

    printf("Pan-Tilt Control (GPIO %d = pan, GPIO %d = tilt)\n", PAN_GPIO, TILT_GPIO);
    printf("Arrow keys: up=tilt+5, down=tilt-5, left=pan-5, right=pan+5\n");
    printf("Press 'q' to quit.\n");

    while (keep_running) {
        int c = getchar();
        if (c == EOF) break;

        switch (c) {
            case 'A':
                if (tilt_angle + 5 <= MAX_ANGLE) {
                    tilt_angle += 5;
                    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                        cleanup();
                        return 1;
                    }
                } else {
                    fprintf(stderr, "Warning: tilt at max (%d), not moving\n", MAX_ANGLE);
                }
                break;
            case 'B':
                if (tilt_angle - 5 >= MIN_ANGLE) {
                    tilt_angle -= 5;
                    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                        cleanup();
                        return 1;
                    }
                } else {
                    fprintf(stderr, "Warning: tilt at min (%d), not moving\n", MIN_ANGLE);
                }
                break;
            case 'C':
                if (pan_angle + 5 <= MAX_ANGLE) {
                    pan_angle += 5;
                    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                        cleanup();
                        return 1;
                    }
                } else {
                    fprintf(stderr, "Warning: pan at max (%d), not moving\n", MAX_ANGLE);
                }
                break;
            case 'D':
                if (pan_angle - 5 >= MIN_ANGLE) {
                    pan_angle -= 5;
                    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                        cleanup();
                        return 1;
                    }
                } else {
                    fprintf(stderr, "Warning: pan at min (%d), not moving\n", MIN_ANGLE);
                }
                break;
            case 'q':
                keep_running = 0;
                break;
            default:
                break;
        }

        usleep(DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

