        if (ssd1306_command(font5x7[c - 32][i]) < 0) return -1;
    }
    return 0;
}

static int ssd1306_draw_string(int x, int y, const char *str) {
    while (*str) {
        if (ssd1306_draw_char(x, y, *str) < 0) return -1;
        x += 6;
        str++;
    }
    return 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open CPU temperature file\n");
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Failed to read CPU temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int read_cpu_usage(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open /proc/stat\n");
        return -1;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error: Failed to parse /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    static unsigned long long prev_idle = 0, prev_total = 0;
    unsigned long long idle = idle + iowait;
    unsigned long long total = user + nice + system + idle + irq + softirq + steal;
    int usage = 0;
    if (prev_total != 0) {
        unsigned long long totald = total - prev_total;
        unsigned long long idled = idle - prev_idle;
        if (totald > 0) {
            usage = (int)((100ULL * (totald - idled)) / totald);
        }
    }
    prev_idle = idle;
    prev_total = total;
    return usage;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, SSD1306_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    if (ssd1306_init() < 0) {
        fprintf(stderr, "Error: SSD1306 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (ssd1306_clear() < 0) {
        fprintf(stderr, "Error: SSD1306 clear failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        int temp = read_cpu_temp();
        int usage = read_cpu_usage();
        char temp_str[32], usage_str[32];
        if (temp < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: ERR");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %d.%02dC", temp / 1000, (temp % 1000) / 10);
        }
        if (usage < 0) {
            snprintf(usage_str, sizeof(usage_str), "Usage: ERR");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", usage);
        }
        if (ssd1306_clear() < 0) break;
        if (ssd1306_draw_string(0, 0, temp_str) < 0) break;
        if (ssd1306_draw_string(0, 16, usage_str) < 0) break;
        sleep(1);
    }
    ssd1306_clear();
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

