#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_SEC 1
#define LCD_UPDATE_INTERVAL_SEC 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_send_byte(int handle, uint8_t val, uint8_t rs) {
    uint8_t high = val & 0xF0;
    uint8_t low = (val << 4) & 0xF0;
    uint8_t en = 0x04;
    uint8_t e_high = en | 0x04;
    uint8_t e_low = (en << 4) | 0x04;

    if (i2cWriteByteData(handle, 0x00, high | rs) < 0) return;
    gpioDelay(1);
    if (i2cWriteByteData(handle, 0x00, e_high | rs) < 0) return;
    gpioDelay(1);
    if (i2cWriteByteData(handle, 0x00, high | rs) < 0) return;
    gpioDelay(1);

    if (i2cWriteByteData(handle, 0x00, low | rs) < 0) return;
    gpioDelay(1);
    if (i2cWriteByteData(handle, 0x00, e_low | rs) < 0) return;
    gpioDelay(1);
    if (i2cWriteByteData(handle, 0x00, low | rs) < 0) return;
    gpioDelay(1);
}

static void lcd_command(int handle, uint8_t cmd) {
    lcd_send_byte(handle, cmd, 0x00);
    if (cmd == 0x01 || cmd == 0x02) gpioDelay(2000);
}

static void lcd_data(int handle, uint8_t data) {
    lcd_send_byte(handle, data, 0x01);
}

static void lcd_string(int handle, const char *str) {
    while (*str) {
        lcd_data(handle, (uint8_t)*str++);
    }
}

static void lcd_clear(int handle) {
    lcd_command(handle, 0x01);
}

static void lcd_set_cursor(int handle, int col, int row) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_command(handle, addr);
}

static void lcd_init(int handle) {
    gpioDelay(50000);
    lcd_send_byte(handle, 0x33, 0x00);
    lcd_send_byte(handle, 0x32, 0x00);
    lcd_command(handle, 0x28);
    lcd_command(handle, 0x0C);
    lcd_command(handle, 0x06);
    lcd_command(handle, 0x01);
    gpioDelay(2000);
}

static void display_lcd(int handle, float flow_rate, float volume) {
    char line1[17];
    char line2[17];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
    snprintf(line2, sizeof(line2), "Vol: %.2f L", volume);

    lcd_clear(handle);
    lcd_set_cursor(handle, 0, 0);
    lcd_string(handle, line1);
    lcd_set_cursor(handle, 0, 1);
    lcd_string(handle, line2);
}

static void log_flow_rate(float flow_rate, float volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Flow Rate: %.2f L/min, Volume: %.2f L\n", timestamp, flow_rate, volume);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, LCD_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init(i2c_handle);

    uint32_t last_tick = gpioTick();
    uint32_t last_lcd_update = last_tick;
    float volume = 0.0f;
    int pulse_count = 0;

    while (running) {
        uint32_t current_tick = gpioTick();
        uint32_t elapsed_us = current_tick - last_tick;

        if (elapsed_us >= (uint32_t)(SAMPLE_INTERVAL_SEC * 1000000)) {
            float time_sec = (float)elapsed_us / 1000000.0f;
            float flow_rate = (pulse_count / PULSES_PER_LITER) / time_sec * 60.0f;
            volume += (float)pulse_count / PULSES_PER_LITER;
            pulse_count = 0;

            log_flow_rate(flow_rate, volume);

            if ((current_tick - last_lcd_update) >= (uint32_t)(LCD_UPDATE_INTERVAL_SEC * 1000000)) {
                display_lcd(i2c_handle, flow_rate, volume);
                last_lcd_update = current_tick;
            }

            last_tick = current_tick;
        }

        if (gpioRead(FLOW_SENSOR_GPIO) == 1) {
            pulse_count++;
            gpioDelay(1000);
        }

        gpioDelay(1000);
    }

    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        lcd_string(i2c_handle, "Shutting down...");
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

