code:
/*
 * Raspberry Pi 4 Model B — Wind Monitor
 *
 * Hardware:
 *   - 16x2 LCD via PCF8574 I2C backpack at 0x27 on /dev/i2c-1
 *   - Anemometer on GPIO17 (rising edge = 1 pulse per second)
 *   - Wind vane on MCP3008 channel 0 (SPI0/CE0, 1 MHz, mode 0)
 *
 * Build:
 *   gcc -O2 -Wall -o wind_monitor wind_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define ANEMOMETER_GPIO       17
#define I2C_BUS               1
#define LCD_ADDR              0x27
#define SPI_CHANNEL           0          /* /dev/spidev0.0 (CE0) */
#define SPI_SPEED             1000000    /* 1 MHz */
#define SPI_FLAGS             0          /* mode 0, active-low CE */
#define MCP3008_CHANNEL       0          /* wind vane ADC channel */
#define SAMPLE_PERIOD_US      500000     /* 500 ms */
#define WIND_SPEED_PER_PULSE  0.5        /* m/s per pulse */
#define MAX_CONSECUTIVE_ERRORS 10

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static int g_i2c_handle = -1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  lcd_init(void);
static void lcd_clear(void);
static void lcd_print(int row, int col, const char *msg);
static int  read_mcp3008(int channel);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Anemometer ISR ---------------------------- */
static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

/* ----------------------------- LCD helpers ------------------------------- */
static int lcd_init(void)
{
    /*
     * PCF8574 I2C LCD control:
     *   0x00 = backlight off, cursor off, blink off, 4-bit mode
     *   0x01 = clear display
     *   0x06 = entry mode: increment, no shift
     *   0x0C = display on, cursor off, blink off
     */
    unsigned char init_cmds[][3] = {
        {0x00, 0x00, 0x00},
        {0x01, 0x00, 0x00},
        {0x06, 0x00, 0x00},
        {0x0C, 0x00, 0x00}
    };
    for (size_t i = 0; i < sizeof(init_cmds) / sizeof(init_cmds[0]); i++) {
        if (i2cWriteDevice(g_i2c_handle, (char *)init_cmds[i], 3) < 0) {
            fprintf(stderr, "LCD init failed (cmd %zu): %s\n", i, strerror(errno));
            return -1;
        }
        gpioDelay(2000); /* 2 ms settle */
    }
    return 0;
}

static void lcd_clear(void)
{
    unsigned char cmd[3] = {0x01, 0x00, 0x00};
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 3) < 0) {
        fprintf(stderr, "LCD clear failed: %s\n", strerror(errno));
    }
    gpioDelay(2000);
}

static void lcd_print(int row, int col, const char *msg)
{
    unsigned char cmd[3];
    if (row == 0) {
        cmd[0] = 0x80 | (col & 0x3F);
    } else {
        cmd[0] = 0xC0 | (col & 0x3F);
    }
    cmd[1] = 0x00;
    cmd[2] = 0x00;

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 3) < 0) {
        fprintf(stderr, "LCD set cursor failed: %s\n", strerror(errno));
        return;
    }

    size_t len = strlen(msg);
    if (len > 16) len = 16;
    unsigned char buf[19];
    buf[0] = 0x40;
    for (size_t i = 0; i < len; i++) buf[1 + i] = (unsigned char)msg[i];
    for (size_t i = len; i < 16; i++) buf[1 + i] = ' ';
    buf[17] = 0x00;
    buf[18] = 0x00;

    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 19) < 0) {
        fprintf(stderr, "LCD write failed: %s\n", strerror(errno));
    }
}

/* ----------------------------- MCP3008 ----------------------------------- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C LCD --- */
    g_i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, LCD_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init() < 0) {
        fprintf(stderr, "LCD init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- SPI MCP3008 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Anemometer ISR --- */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Wind monitor running. Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int pulses = g_pulse_count;
        g_pulse_count = 0;

        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many ADC errors, aborting.\n");
                break;
            }
            lcd_clear();
            lcd_print(0, 0, "ADC ERROR");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        /* Detect sensor-absent / fault conditions (ADC stuck at rail) */
        if (adc == 0 || adc == 1023) {
            fprintf(stderr, "Warning: ADC at rail (%d) — sensor absent or wiring fault\n", adc);
        }

        /* Wind speed: pulses * 0.5 m/s per pulse over 500 ms window */
        float wind_speed = (float)pulses * WIND_SPEED_PER_PULSE;

        /* Wind direction: 0-1023 mapped to 0-359 degrees */
        int wind_direction = (int)(((float)adc / 1023.0f) * 360.0f);

        char line1[17];
        char line2[17];
        snprintf(line1, sizeof(line1), "Spd: %.1f m/s", wind_speed);
        snprintf(line2, sizeof(line2), "Dir: %3d deg", wind_direction);

        lcd_clear();
        lcd_print(0, 0, line1);
        lcd_print(1, 0, line2);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    lcd_clear();
    lcd_print(0, 0, "Shutting down");
    lcd_print(1, 0, "Goodbye");

    cleanup();
    return EXIT_SUCCESS;
}

