#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_row(struct gpiod_line *lines[NUM_ROWS], int row, int val) {
    if (gpiod_line_set_value(lines[row], val) < 0) {
        perror("gpiod_line_set_value (row)");
        exit(EXIT_FAILURE);
    }
}

static void set_col(struct gpiod_line *lines[NUM_COLS], int col, int val) {
    if (gpiod_line_set_value(lines[col], val) < 0) {
        perror("gpiod_line_set_value (col)");
        exit(EXIT_FAILURE);
    }
}

static void scan_display(struct gpiod_line *row_lines[NUM_ROWS],
                         struct gpiod_line *col_lines[NUM_COLS]) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            set_row(row_lines, row, 1);
            set_col(col_lines, col, 0);
            usleep(SCAN_DELAY_US);
            set_row(row_lines, row, 0);
            set_col(col_lines, col, 1);
        }
    }
}

static void wave_left_to_right(struct gpiod_line *row_lines[NUM_ROWS],
                               struct gpiod_line *col_lines[NUM_COLS]) {
    for (int col = 0; col < NUM_COLS; col++) {
        for (int row = 0; row < NUM_ROWS; row++) {
            set_row(row_lines, row, 1);
            set_col(col_lines, col, 0);
            usleep(SCAN_DELAY_US);
            set_row(row_lines, row, 0);
            set_col(col_lines, col, 1);
        }
    }
}

static void wave_right_to_left(struct gpiod_line *row_lines[NUM_ROWS],
                               struct gpiod_line *col_lines[NUM_COLS]) {
    for (int col = NUM_COLS - 1; col >= 0; col--) {
        for (int row = 0; row < NUM_ROWS; row++) {
            set_row(row_lines, row, 1);
            set_col(col_lines, col, 0);
            usleep(SCAN_DELAY_US);
            set_row(row_lines, row, 0);
            set_col(col_lines, col, 1);
        }
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *row_lines[NUM_ROWS];
    struct gpiod_line *col_lines[NUM_COLS];
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request col line %u as output\n", col_pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        wave_left_to_right(row_lines, col_lines);
        if (!running) break;
        wave_right_to_left(row_lines, col_lines);
        if (!running) break;
        scan_display(row_lines, col_lines);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) gpiod_line_release(col_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

