#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 8
#define DELAY_MS 150

// Row pins (anodes) connected to GPIO2, 3, 4, 17, 27, 22, 10, 9
const unsigned int row_pins[NUM_PINS] = {2, 3, 4, 17, 27, 22, 10, 9};
// Column pins (cathodes) connected to GPIO14, 15, 18, 23, 24, 25, 8, 7
const unsigned int col_pins[NUM_PINS] = {14, 15, 18, 23, 24, 25, 8, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_PINS];
static struct gpiod_line *col_lines[NUM_PINS];
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request row lines as outputs, initially LOW (anodes off)
    for (int i = 0; i < NUM_PINS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    // Request column lines as outputs, initially HIGH (cathodes off for common anode)
    for (int i = 0; i < NUM_PINS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get column line %u\n", col_pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request column line %u as output\n", col_pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    // Clear matrix: all column cathodes HIGH (off), all row anodes LOW (off)
    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_set_value(col_lines[i], 1);
        gpiod_line_set_value(row_lines[i], 0);
    }

    while (keep_running) {
        // Scan columns from left to right
        for (int col = 0; col < NUM_PINS; col++) {
            // Clear matrix: all column cathodes HIGH, all row anodes LOW
            for (int i = 0; i < NUM_PINS; i++) {
                gpiod_line_set_value(col_lines[i], 1);
                gpiod_line_set_value(row_lines[i], 0);
            }
            // Light up the current column: cathode LOW, all anodes HIGH
            gpiod_line_set_value(col_lines[col], 0);
            for (int i = 0; i < NUM_PINS; i++) {
                gpiod_line_set_value(row_lines[i], 1);
            }
            usleep(DELAY_MS * 1000);
        }
    }

    // Cleanup
    release_resources();
    return EXIT_SUCCESS;
}

