 *   VL53L3CX GND -> GND
 *
 * I2C: Bus 1, Address 0x29
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download and
 *       complex initialization sequence. This program stubs the
 *       proprietary steps with comments and uses the standard ST
 *       Ultra Lite Driver (ULD) I2C register map for communication.
 *       For production, use the ST official VL53L3CX API or ULD.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L3CX_ADDR  0x29

/* Standard ULD I2C register addresses (16-bit, big-endian on wire) */
#define VL53L3CX_REG_SOFT_RESET          0x0003
#define VL53L3CX_REG_MODEL_ID            0x0001
#define VL53L3CX_REG_SYSTEM_START        0x0000
#define VL53L3CX_REG_RESULT_STATUS       0x0089
#define VL53L3CX_REG_RESULT_DISTANCE     0x0096
#define VL53L3CX_REG_RESULT_TARGET_STATUS 0x0097

#define EXPECTED_MODEL_ID 0xEA
#define MAX_TARGETS       4
#define POLL_DELAY_US     10000  /* 10 ms */
#define LOOP_DELAY_US     100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed for reg 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, (char *)data, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_init(int handle)
{
    uint8_t model_id = 0;

    /* Read model ID to verify sensor presence */
    if (i2c_read_reg16(handle, VL53L3CX_REG_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "[ERROR] Cannot read model ID - sensor may be absent or bus error\n");
        return -1;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "[ERROR] Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
