    if (i2c_write_reg16(handle, VL53L3CX_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SYSTEM_START, 0x01) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance data                                                  */
/* ------------------------------------------------------------------ */
static int vl53l3cx_read_data(int handle, uint16_t *distances, uint8_t *statuses,
                              uint8_t *num_targets)
{
    uint8_t status = 0;
    uint8_t data[MAX_TARGETS * 2];
    uint8_t status_data[MAX_TARGETS];

    /* Poll for new data */
    if (i2c_read_reg16(handle, VL53L3CX_REG_RESULT_STATUS, &status, 1) != 0)
        return -1;

    if ((status & 0x01) == 0) {
