    /* Read distance data for all targets */
    if (i2c_read_reg16(handle, VL53L3CX_REG_RESULT_DISTANCE, data,
                       MAX_TARGETS * 2) != 0)
        return -1;

    /* Read target status */
    if (i2c_read_reg16(handle, VL53L3CX_REG_RESULT_TARGET_STATUS, status_data,
                       MAX_TARGETS) != 0)
