    *num_targets = MAX_TARGETS;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data with ISO-8601 timestamp                                    */
/* ------------------------------------------------------------------ */
static void log_data(const uint16_t *distances, const uint8_t *statuses,
                     uint8_t num_targets)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Number of Targets: %u\n", timestamp, num_targets);
    for (int i = 0; i < num_targets; i++) {
