    uint8_t  statuses[MAX_TARGETS];
    uint8_t  num_targets = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, VL53L3CX_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l3cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L3CX initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L3CX initialized. Reading distance data every 100 ms...\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        if (vl53l3cx_read_data(g_i2c_handle, distances, statuses, &num_targets) == 0) {
            log_data(distances, statuses, num_targets);
        } else {
            fprintf(stderr, "[WARN] Failed to read sensor data\n");
        }
