                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int si1145_init(int handle)
{
    uint8_t part_id;
    if (i2c_read_reg(handle, SI1145_REG_PART_ID, &part_id) != 0)
        return -1;
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_reg(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) != 0)
        return -1;

