            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value led ON");
                break;
            }
            usleep(100000); /* 100 ms */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value led OFF");
                break;
            }
            if (log_event(LOG_FILE) < 0) {
                fprintf(stderr, "Failed to log event.\n");
            }
        }

        prev_sensor_value = sensor_value;
        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

