static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg_low, uint16_t *value) {
    int rc = i2cReadWordData(handle, reg_low);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed: reg=0x%02X rc=%d\n", reg_low, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int si1145_init(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_byte(handle, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    if (i2c_write_byte(handle, SI1145_REG_HW_KEY, 0x17) != 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_CH_LIST, 0x03) != 0) return -1;
    return 0;
