    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at addr 0x%02X: %d\n", SI1145_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("biometric_data.log", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        if (si1145_force_measurement(g_i2c_handle) != 0) {
            fprintf(stderr, "Measurement trigger failed\n");
            sleep(1);
            continue;
        }
        gpioDelay(100000);

        uint16_t proximity = 0, ambient_light = 0;
        if (si1145_read_proximity(g_i2c_handle, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            continue;
        }
        if (si1145_read_ambient_light(g_i2c_handle, &ambient_light) != 0) {
            fprintf(stderr, "Failed to read ambient light data\n");
            continue;
        }
        log_data(g_log_file, proximity, ambient_light);
        sleep(1);
    }

    fclose(g_log_file);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

