        if (ret < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n",
                    strerror(errno));
            gpiod_edge_event_buffer_free(buf);
            return -2;
        }

        for (int i = 0; i < ret; i++) {
            ev = gpiod_edge_event_buffer_get_event(buf, i);
            if (!ev) continue;

            if (gpiod_edge_event_get_event_type(ev) ==
                GPIOD_EDGE_EVENT_RISING_EDGE) {
                rising = 1;
                rise_ns = gpiod_edge_event_get_ts_sec(ev) * 1000000000L
                        + gpiod_edge_event_get_ts_nsec(ev);
            } else if (rising &&
                       gpiod_edge_event_get_event_type(ev) ==
                       GPIOD_EDGE_EVENT_FALLING_EDGE) {
                fall_ns = gpiod_edge_event_get_ts_sec(ev) * 1000000000L
                        + gpiod_edge_event_get_ts_nsec(ev);
                gpiod_edge_event_buffer_free(buf);
                return fall_ns - rise_ns;
            }
        }
    }
}

static float calculate_distance(long pulse_ns)
{
    if (pulse_ns < 0) return -1.0f;
    return (float)pulse_ns / 1000000000.0f * SPEED_OF_SOUND / 2.0f;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "request_output(trig) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "request_input(echo) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Allow sensor to settle */
    usleep(100000);

    while (g_running) {
        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "set_value(trig,1) failed: %s\n", strerror(errno));
            log_line(log_fp, "Error: failed to set trigger high");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "set_value(trig,0) failed: %s\n", strerror(errno));
            log_line(log_fp, "Error: failed to set trigger low");
            goto cleanup;
        }

        long pulse_ns = measure_echo_ns(echo);

        if (pulse_ns == -1) {
            log_line(log_fp, "Timeout: no echo received (sensor absent or "
                             "out of range)");
        } else if (pulse_ns == -2) {
            log_line(log_fp, "Error: libgpiod read/wait failure");
        } else {
            float dist = calculate_distance(pulse_ns);
            if (dist < MIN_DISTANCE_CM || dist > MAX_DISTANCE_CM) {
                log_line(log_fp, "Warning: distance out of range "
                                 "(sensor faulty or object too close/far)");
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Distance: %.2f cm", dist);
                log_line(log_fp, msg);
                if (dist < WATER_THRESHOLD) {
                    log_line(log_fp, "Time to water the plant!");
                }
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

