#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_I2C_ADDR 0x39
#define APDS9960_ID_REG 0x92
#define APDS9960_ENABLE_REG 0x80
#define APDS9960_ATIME_REG 0x81
#define APDS9960_WTIME_REG 0x83
#define APDS9960_PPULSE_REG 0x8E
#define APDS9960_CONTROL_REG 0xF1
#define APDS9960_CONFIG2_REG 0x90
#define APDS9960_CDATAL_REG 0x96
#define APDS9960_PDATA_REG 0x9C

#define APDS9960_ID 0xAB
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define I2C_BUS 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int init_apds9960(void) {
    if (write_reg(APDS9960_ENABLE_REG, 0x00) < 0) return -1;
    if (write_reg(APDS9960_ATIME_REG, 0xDB) < 0) return -1;
    if (write_reg(APDS9960_WTIME_REG, 0xF6) < 0) return -1;
    if (write_reg(APDS9960_PPULSE_REG, 0x87) < 0) return -1;
    if (write_reg(APDS9960_CONTROL_REG, 0x03) < 0) return -1;
    if (write_reg(APDS9960_CONFIG2_REG, 0x01) < 0) return -1;
    if (write_reg(APDS9960_ENABLE_REG, 0x03) < 0) return -1;
    return 0;
}

static int read_proximity(uint8_t *prox) {
    int val = i2cReadByteData(i2c_handle, APDS9960_PDATA_REG);
    if (val < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    *prox = (uint8_t)val;
    return 0;
}

static int read_color(uint16_t *r, uint16_t *g, uint16_t *b) {
    char buf[8];
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_CDATAL_REG, buf, 8) != 8) {
        fprintf(stderr, "Error reading color data\n");
        return -1;
    }
    *r = (uint16_t)((buf[1] << 8) | buf[0]);
    *g = (uint16_t)((buf[3] << 8) | buf[2]);
    *b = (uint16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(uint16_t r, uint16_t g, uint16_t b, uint8_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, r, g, b, prox);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int id = i2cReadByteData(i2c_handle, APDS9960_ID_REG);
    if (id != APDS9960_ID) {
        fprintf(stderr, "APDS9960 not found (ID: 0x%02X, expected 0x%02X)\n", id, APDS9960_ID);
        cleanup();
        return 1;
    }

    if (init_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t r, g, b;
    uint8_t prox;

    while (!terminate) {
        if (read_proximity(&prox) == 0 && read_color(&r, &g, &b) == 0) {
            if (prox > PROXIMITY_THRESHOLD) {
                log_data(r, g, b, prox);
            }
        } else {
            fprintf(stderr, "I2C communication error, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1;
                break;
            }
            if (init_apds9960() < 0) {
                fprintf(stderr, "APDS9960 re-initialization failed\n");
                terminate = 1;
                break;
            }
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

