/*
 * Si1182-A-GMR Heart Rate Monitor for Raspberry Pi 5
 * Uses the Linux i2c-dev kernel interface (no wiringPi).
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (pin 3, I2C1 SDA)
 *   Si1182 SCL  -> GPIO3 (pin 5, I2C1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o heartrate heartrate.c
 * Run:    ./heartrate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- Si1182-A-GMR constants (from datasheet) ---- */
#define SI1182_I2C_ADDR        0x5A
#define SI1182_REG_PART_ID     0x00
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_COMMAND     0x47
#define SI1182_REG_PS_DATA0    0x24
#define SI1182_REG_PS_DATA1    0x25

#define SI1182_PART_ID_EXPECTED 0x82
#define SI1182_CMD_RESET        0x01
#define SI1182_CMD_START        0x02

#define I2C_BUS                "/dev/i2c-1"
#define CSV_FILENAME           "heartrate.csv"
#define SAMPLE_PERIOD_MS       100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv    = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register via SMBus block-write helper.         */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value)
{
    union i2c_smbus_data data;
    data.byte = value;

    struct i2c_smbus_ioctl_data args;
    args.read_write = I2C_SMBUS_WRITE;
    args.command    = reg;
    args.size       = I2C_SMBUS_BYTE_DATA;
    args.data       = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register via SMBus block-read helper.         */
/* Returns 0 on success and stores value in *out, -1 on error.        */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;

    args.read_write = I2C_SMBUS_READ;
    args.command    = reg;
    args.size       = I2C_SMBUS_BYTE_DATA;
    args.data       = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = data.byte;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian proximity value.                       */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int si1182_read_proximity(int fd, uint16_t *prox)
{
    uint8_t lo, hi;

    if (si1182_read_reg(fd, SI1182_REG_PS_DATA0, &lo) < 0)
        return -1;
    if (si1182_read_reg(fd, SI1182_REG_PS_DATA1, &hi) < 0)
        return -1;

    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Placeholder BPM calculation from proximity data.                    */
/* ------------------------------------------------------------------ */
static int calculate_bpm(uint16_t prox)
{
    /*
     * A real heart-rate monitor would use a proper spectral analysis
     * of the proximity signal to detect peaks and compute BPM.
     * This placeholder scales the raw value linearly for demonstration.
     */
    return (int)(prox / 100);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Set slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify part ID ---- */
    uint8_t part_id = 0;
    if (si1182_read_reg(g_i2c_fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor not present or bus error.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr,
                "PART_ID mismatch: got 0x%02X, expected 0x%02X "
                "(Si1182 part identifier).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /* ---- Configure measurement rate ---- */
    if (si1182_write_reg(g_i2c_fd, SI1182_REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Failed to set MEAS_RATE0.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Issue reset and start command ---- */
    if (si1182_write_reg(g_i2c_fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0) {
        fprintf(stderr, "Failed to send reset command.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(10000); /* 10 ms settle after reset */

    if (si1182_write_reg(g_i2c_fd, SI1182_REG_COMMAND, SI1182_CMD_START) < 0) {
        fprintf(stderr, "Failed to start measurements.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open CSV file ---- */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,bpm\n");
        fflush(g_csv);
    }

    printf("Logging heart rate to %s every %d ms. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_PERIOD_MS);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t prox = 0;
        if (si1182_read_proximity(g_i2c_fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read error, skipping sample.\n");
        } else {
            int bpm = calculate_bpm(prox);

            /* ISO-8601 timestamp */
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *tm_info = localtime_r(&now, &tm_buf);
            char ts[32];
            if (tm_info)
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info);
            else
                snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");

            fprintf(g_csv, "%s,%d\n", ts, bpm);
            fflush(g_csv);
            printf("%s  BPM: %d  (prox=0x%04X)\n", ts, bpm, prox);
        }

        /* Sleep in 10 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_MS / 10 && g_running; i++)
            usleep(10000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

