#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define TRIGGER_PIN    17
#define LOG_FILE       "distance_log.txt"
#define MEAS_TIMEOUT_MS 100

/* VL53L0X register addresses */
#define REG_SYSRANGE_START          0x00
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0B
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS     0x14

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write one byte to a 16-bit register address (big-endian on wire). */
static int vl53l0x_write_reg(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Read N bytes starting at a 16-bit register address. */
static int vl53l0x_read_block(int handle, uint16_t reg, uint8_t *buf, int len) {
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed at reg 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "I2C read failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a single byte from a 16-bit register address. */
static int vl53l0x_read_byte(int handle, uint16_t reg, uint8_t *value) {
    return vl53l0x_read_block(handle, reg, value, 1);
}

/* Trigger a single measurement and return distance in mm, or -1 on error. */
static int vl53l0x_read_distance(int handle) {
    uint8_t status;
    uint8_t data[14];
    int distance = -1;

    /* Start a single-shot range measurement. */
    if (vl53l0x_write_reg(handle, REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    /* Poll RESULT_INTERRUPT_STATUS bit 0 until it sets or timeout. */
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        if (vl53l0x_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
        if (i == MEAS_TIMEOUT_MS - 1) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    /* Read 14-byte result block starting at RESULT_RANGE_STATUS. */
    if (vl53l0x_read_block(handle, REG_RESULT_RANGE_STATUS, data, 14) != 0) {
        return -1;
    }

    /* Distance is in bytes 10-11 (16-bit, little-endian). */
    distance = (data[10] << 8) | data[11];

    /* Clear the interrupt so the next measurement can signal. */
    if (vl53l0x_write_reg(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return distance;
}

static int log_distance(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    int distance;

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x29. */
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", VL53L0X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading the model ID register (0x010F). */
    uint8_t model_id = 0;
    if (vl53l0x_read_byte(i2c_handle, 0x010F, &model_id) != 0) {
        fprintf(stderr, "VL53L0X not detected at 0x%02X\n", VL53L0X_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0xEA)\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as input with pull-up. */
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    /* Open log file in append mode. */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance logger started. Press Ctrl+C to exit.\n");

    /* Main loop: wait for falling edge on trigger pin. */
    while (running) {
        if (gpioRead(TRIGGER_PIN) == 0) {
            gpioDelay(50000); /* 50 ms debounce */
            if (gpioRead(TRIGGER_PIN) == 0) {
                distance = vl53l0x_read_distance(i2c_handle);
                if (distance >= 0) {
                    if (log_distance(log_file, distance) != 0) {
                        fprintf(stderr, "Logging failed\n");
                    }
                } else {
                    fprintf(stderr, "Distance read failed\n");
                }
                /* Wait for rising edge before next trigger. */
                while (running && gpioRead(TRIGGER_PIN) == 0) {
                    gpioDelay(10000);
                }
            }
        }
        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Cleanup on exit. */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

