    /* Open log file in append mode. */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance logger started. Press Ctrl+C to exit.\n");

    /* Main loop: wait for falling edge on trigger pin. */
    while (running) {
        if (gpioRead(TRIGGER_PIN) == 0) {
            gpioDelay(50000); /* 50 ms debounce */
            if (gpioRead(TRIGGER_PIN) == 0) {
                distance = vl53l0x_read_distance(i2c_handle);
                if (distance >= 0) {
                    if (log_distance(log_file, distance) != 0) {
                        fprintf(stderr, "Logging failed\n");
                    }
                } else {
                    fprintf(stderr, "Distance read failed\n");
                }
                /* Wait for rising edge before next trigger. */
                while (running && gpioRead(TRIGGER_PIN) == 0) {
                    gpioDelay(10000);
                }
            }
        }
        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Cleanup on exit. */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

