#define TRIGGER_DELAY  50000   /* microseconds (50 ms) */
#define SAMPLE_PERIOD  200000  /* microseconds (200 ms) */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanups run.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file and stdout.                */
/* ------------------------------------------------------------------ */
static void log_distance(int distance_mm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s, %d\n", timestamp, distance_mm);
        fflush(g_log_file);
    }
    printf("%s, %d\n", timestamp, distance_mm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian distance from the CH101.                   */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, int *distance_mm)
{
    char buf[2];

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: failed to read 2 bytes\n");
        return -1;
    }

    *distance_mm = ((int)(buf[0] & 0xFF) << 8) | (int)(buf[1] & 0xFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources in reverse order of acquisition.             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int distance_mm;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, CH101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CH101 distance measurement started. Press Ctrl-C to stop.\n");

    /* ---- main sampling loop ---- */
    while (g_running) {
        /* Trigger a measurement */
        if (i2cWriteByte(g_i2c_handle, TRIGGER_CMD) != 0) {
            fprintf(stderr, "I2C write error: failed to send trigger command\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        /* Wait for the sensor to complete the measurement */
        gpioDelay(TRIGGER_DELAY);

        /* Read the 16-bit distance result */
        if (read_distance(g_i2c_handle, &distance_mm) == 0) {
            log_distance(distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance; will retry next cycle\n");
        }

        /* Wait before the next sample */
        gpioDelay(SAMPLE_PERIOD);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

