#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0f
#define LOG_FILE "distance_log.txt"
#define I2C_BUS 1
#define POLL_INTERVAL_US 100000

/* ICU-20201 register addresses (16-bit registers, big-endian on the bus) */
#define REG_PRODUCT_ID 0x0000
#define REG_DISTANCE_MSB 0x0008
#define REG_DISTANCE_LSB 0x0009
#define REG_STATUS 0x000A
#define REG_CONFIG 0x000B

#define EXPECTED_PRODUCT_ID 0x2020

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit big-endian value to a 16-bit register address */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit big-endian value from a 16-bit register address */
static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;
    *value = ((uint16_t)(data_buf[0] & 0xFF) << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int init_sensor(void) {
    uint16_t product_id = 0;
    if (i2c_read_reg16(i2c_handle, REG_PRODUCT_ID, &product_id) < 0) {
        fprintf(stderr, "Error: Failed to read product ID from I2C device.\n");
        return -1;
    }
    if (product_id != EXPECTED_PRODUCT_ID) {
        fprintf(stderr, "Error: Unexpected product ID 0x%04X (expected 0x%04X). Sensor not present?\n",
                product_id, EXPECTED_PRODUCT_ID);
        return -1;
    }
    printf("ICU-20201 detected (Product ID: 0x%04X).\n", product_id);

    /* Configure: enable measurement, set range to 100 cm (bits 0-1 = 00) */
    if (i2c_write_reg16(i2c_handle, REG_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Error: Failed to configure ICU-20201.\n");
        return -1;
    }
    return 0;
}

static int read_distance(float *distance_cm) {
    uint16_t status = 0;
    uint16_t msb = 0, lsb = 0;

    /* Poll status register until data ready (bit 0 == 1) */
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg16(i2c_handle, REG_STATUS, &status) < 0) {
            fprintf(stderr, "Error: Failed to read status register.\n");
            return -1;
        }
        if (status & 0x0001) break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x0001)) {
        fprintf(stderr, "Error: Data not ready after timeout.\n");
        return -1;
    }

    if (i2c_read_reg16(i2c_handle, REG_DISTANCE_MSB, &msb) < 0) {
        fprintf(stderr, "Error: Failed to read distance MSB.\n");
        return -1;
    }
    if (i2c_read_reg16(i2c_handle, REG_DISTANCE_LSB, &lsb) < 0) {
        fprintf(stderr, "Error: Failed to read distance LSB.\n");
        return -1;
    }

    uint16_t raw = (msb << 8) | lsb;
    *distance_cm = (float)raw * 0.01f;
    return 0;
}

static void log_distance(float distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s, %.2f\n", timestamp, distance_cm);
    fclose(fp);
}

static void control_led(float distance_cm) {
    gpioWrite(LED_GPIO, (distance_cm < DISTANCE_THRESHOLD) ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device on bus %d at address 0x%02X.\n", I2C_BUS, ICU20201_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d as output.\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    while (running) {
        float distance_cm = 0.0f;
        if (read_distance(&distance_cm) == 0) {
            log_distance(distance_cm);
            control_led(distance_cm);
            printf("Distance: %.2f cm\n", distance_cm);
        } else {
            fprintf(stderr, "Warning: Read error, retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

