#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ICU20201_ADDR 0x6A
#define ICU20201_WHO_AM_I 0x01
#define ICU20201_WHO_AM_I_VAL 0x20
#define ICU20201_DISTANCE_MSB 0x40
#define ICU20201_DISTANCE_LSB 0x41
#define ICU20201_CONFIG_REG 0x02
#define ICU20201_CONFIG_VAL 0x00
#define LED_GPIO 17
#define LOG_FILE "tof_log.txt"
#define POLL_DELAY_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(void) {
    int who = i2cReadByteData(i2c_handle, ICU20201_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: I2C read failed for WHO_AM_I (pigpio error %d)\n", who);
        return -1;
    }
    if (who != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, ICU20201_WHO_AM_I_VAL);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ICU20201_CONFIG_REG, ICU20201_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register\n");
        return -1;
    }
    return 0;
}

static int read_distance(int *distance_mm) {
    int msb = i2cReadByteData(i2c_handle, ICU20201_DISTANCE_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(i2c_handle, ICU20201_DISTANCE_LSB);
    if (lsb < 0) return -1;
    *distance_mm = (msb << 8) | lsb;
    return 0;
}

static void log_data(int distance_mm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int threshold = 100;
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold. Using default 100 mm.\n");
            threshold = 100;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (pigpio error %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance measurement. Threshold: %d mm. Press Ctrl+C to exit.\n", threshold);

    while (running) {
        int distance_mm;
        if (read_distance(&distance_mm) == 0) {
            log_data(distance_mm);
            if (distance_mm < threshold) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

