#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x50
#define LOG_FILE       "intrusion_log.txt"
#define THRESHOLD_MM   1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_MS 100
#define MEASURE_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        if (n < 0) perror("I2C read failed");
        else fprintf(stderr, "I2C read short: %zd/%zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t buf[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0) return -1;
    msleep(MEASURE_DELAY_MS);
    if (i2c_read_data(fd, buf, sizeof(buf)) < 0) return -1;

    if (buf[0] != 0x50) {
        fprintf(stderr, "Unexpected header byte: 0x%02X\n", buf[0]);
        return -1;
    }

    *distance_mm = (buf[11] << 8) | buf[12];
    return 0;
}

static int log_intrusion(FILE *fp, int distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (!localtime_r(&t, &tm)) {
        perror("localtime_r failed");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s - Intrusion detected! Distance: %d mm\n", ts, distance_mm) < 0) {
        perror("fprintf failed");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Failed to open log file");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int sum = 0;
        int valid = 0;
        int intrusion = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            int dist;
            if (read_distance(g_i2c_fd, &dist) == 0) {
                sum += dist;
                valid++;
                if (dist < THRESHOLD_MM) intrusion = 1;
            } else {
                fprintf(stderr, "Sensor read error at sample %d\n", i);
            }
            msleep(SAMPLE_DELAY_MS / NUM_SAMPLES);
        }

        if (valid > 0) {
            int avg = sum / valid;
            if (intrusion) {
                printf("Intrusion detected! Average distance: %d mm\n", avg);
                if (log_intrusion(g_log_fp, avg) < 0) {
                    fprintf(stderr, "Failed to log intrusion event\n");
                }
            } else {
                printf("No intrusion. Average distance: %d mm\n", avg);
            }
        } else {
            fprintf(stderr, "No valid samples in cycle\n");
        }

        msleep(SAMPLE_DELAY_MS);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
    return EXIT_SUCCESS;
}

