#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29

/* VL53L0X register addresses */
#define REG_IDENTIFICATION_MODEL_ID       0xC0
#define REG_SYSRANGE_START                0x00
#define REG_RESULT_INTERRUPT_STATUS       0x13
#define REG_RESULT_RANGE_STATUS           0x14
#define REG_SYSTEM_INTERRUPT_CLEAR        0x0B

#define EXPECTED_MODEL_ID                 0xEE
#define MEAS_TIMEOUT_MS                   100
#define LOOP_DELAY_US                     500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a 16-bit-indexed register (pigpio uses 16-bit
 * addresses, so i2cWriteByteData sends the high byte then low byte). */
static int vl53l0x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed at reg 0x%02X: %s\n",
                reg, strerror(errno));
    }
    return rc;
}

/* Read a single byte from a 16-bit-indexed register. */
static int vl53l0x_read_byte(int handle, uint16_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed at reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* Read a 16-bit little-endian value from a 16-bit-indexed register. */
static int vl53l0x_read_word(int handle, uint16_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed at reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* pigpio returns data as (msb << 8) | lsb */
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    if (vl53l0x_read_byte(handle, REG_IDENTIFICATION_MODEL_ID, &model_id) < 0)
        return -1;

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr,
                "Unexpected model ID 0x%02X (expected 0x%02X). "
                "Sensor not present or wrong address.\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm)
{
    /* Start a single-shot measurement */
    if (vl53l0x_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS until bit 0 is set (measurement ready) */
    uint8_t status = 0;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        if (vl53l0x_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Measurement timeout (no interrupt within %d ms).\n",
                MEAS_TIMEOUT_MS);
        return -1;
    }

    /* Read 16-bit distance (little-endian) */
    if (vl53l0x_read_word(handle, REG_RESULT_RANGE_STATUS, distance_mm) < 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal */
    if (vl53l0x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("%s ", buf);
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        goto cleanup_gpio;
    }

    if (vl53l0x_init(handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        goto cleanup_i2c;
    }

    printf("Starting distance readings every 500 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance = 0;

        if (vl53l0x_read_distance(handle, &distance) == 0) {
            print_timestamp();
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: distance read failed, retrying...\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(10000); /* 10 ms */
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0)
        i2cClose(handle);
cleanup_gpio:
    gpioTerminate();
    return rc;
}

