/*
 * Si1182 Proximity Reader for Raspberry Pi 3 Model B+
 * Library: pigpio (I2C bus 1, address 0x39)
 *
 * Build:  gcc -O2 -Wall -o si1182_prox si1182_prox.c -lpigpio -lrt
 * Run:    sudo ./si1182_prox
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182 constants (verified against datasheet) ---- */
#define SI1182_ADDR        0x39          /* 7-bit I2C address */
#define SI1182_REG_HW_KEY  0x07          /* mandatory write to enable */
#define SI1182_HW_KEY_VAL  0x17          /* required value */
#define SI1182_REG_CONFIG  0x18          /* proximity mode config */
#define SI1182_REG_IRQ_STS 0x25          /* IRQ status register */
#define SI1182_REG_PS1_LSB 0x2A          /* proximity result LSB */
#define SI1182_REG_PS1_MSB 0x2B          /* proximity result MSB */

#define I2C_BUS            1             /* /dev/i2c-1 on RPi 3B+ */
#define POLL_DELAY_US      500000        /* 500 ms */
#define MAX_READ_RETRIES   100           /* timeout waiting for data-ready */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.    */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.   */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182: write HW_KEY, then CONFIG to enable prox mode. */
static int si1182_init(int handle)
{
    if (reg_write(handle, SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) != 0)
        return -1;

    /*
     * CONFIG = 0x01 enables proximity mode.
     * Bits [7:6] = 00 (proximity), [5:4] = 00 (ALS off), [3:2] = 00 (UV off),
     * [1:0] = 00 (no interrupt).
     */
    if (reg_write(handle, SI1182_REG_CONFIG, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Wait for the data-ready bit (bit 0 of IRQ_STS) to clear.             */
static int wait_data_ready(int handle)
{
    uint8_t sts;
    for (int i = 0; i < MAX_READ_RETRIES; ++i) {
        if (reg_read(handle, SI1182_REG_IRQ_STS, &sts) != 0)
            return -1;
        if ((sts & 0x01) == 0)
            return 0;
        gpioDelay(1000);  /* 1 ms */
    }
    fprintf(stderr, "[WARN] Data-ready timeout (IRQ_STS never cleared)\n");
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit proximity result.                                   */
static int read_proximity(int handle, uint16_t *prox)
{
    uint8_t lsb, msb;

    if (wait_data_ready(handle) != 0)
        return -1;

    if (reg_read(handle, SI1182_REG_PS1_LSB, &lsb) != 0)
        return -1;
    if (reg_read(handle, SI1182_REG_PS1_MSB, &msb) != 0)
        return -1;

    *prox = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at address 0x39 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1182_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor presence with a dummy read --- */
    uint8_t dummy;
    if (reg_read(g_i2c_handle, SI1182_REG_HW_KEY, &dummy) != 0) {
        fprintf(stderr, "[FATAL] No ACK from Si1182 at 0x%02X — sensor absent or wiring fault\n",
                SI1182_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (si1182_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1182 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, SI1182_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        uint16_t prox;
        if (read_proximity(g_i2c_handle, &prox) == 0) {
            printf("Proximity: %u\n", prox);
        } else {
            fprintf(stderr, "[WARN] Read failed; continuing.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

