/*
 * MLX75030 Time-of-Flight distance reader for Raspberry Pi 4 Model B.
 *
 * Uses the Linux I2C userland API (i2c-dev / ioctl SMBus commands)
 * instead of wiringPi, so it builds on any Linux distro with i2c-dev.
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75030 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030 mlx75030.c
 * Run:    ./mlx75030
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C          /* default 7-bit I2C address */
#define DISTANCE_REG   0x00          /* 16-bit distance register (LE) */
#define SAMPLE_PERIOD  500000        /* 500 ms in microseconds */
#define MM_PER_COUNT   0.125         /* raw count -> mm scaling factor */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and set the slave address.                          */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    /* Verify the device is present by reading its status register. */
    uint8_t reg = DISTANCE_REG;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Sensor absent at 0x%02X (no ACK): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register (low byte first, high byte).   */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_distance_reg(int fd, uint16_t *out)
{
    uint8_t reg = DISTANCE_REG;
    uint8_t buf[2];

    /* Write the register pointer. */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read two bytes (low byte first, then high byte). */
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            fprintf(stderr, "read(reg 0x%02X): %s\n", reg, strerror(errno));
        else
            fprintf(stderr, "read(reg 0x%02X): short read (%zd bytes)\n",
                    reg, n);
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int fd;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    printf("MLX75030 distance reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t raw;

        if (read_distance_reg(fd, &raw) == 0) {
            double distance_mm = (double)raw * MM_PER_COUNT;
            printf("Distance: %.2f mm\n", distance_mm);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        /* Sleep 500 ms, but wake early on signal. */
        struct timespec ts = { 0, SAMPLE_PERIOD * 1000 };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running)
            ;
    }

    printf("\nExiting cleanly.\n");
    if (close(fd) < 0)
        perror("close");

    return EXIT_SUCCESS;
}

