/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   HC-SR04 VCC -> 5V (Pin 2 or 4)
 *   HC-SR04 GND -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kOhm resistor (protection)
 *
 * NOTE: HC-SR04 operates at 5V; Raspberry Pi GPIO is 3.3V tolerant.
 *       Use a voltage divider or level shifter for safe operation.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 microseconds trigger pulse */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait          */
#define MAX_PULSE_US     38000       /* ~343 cm round trip max        */
#define SAMPLE_PERIOD_US 1000000     /* 1 second between samples      */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns current time as a formatted string (thread-safe).           */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* Send a 10 us trigger pulse.                                         */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, PI_LOW);
}

/* ------------------------------------------------------------------ */
/* Measure echo pulse width in microseconds.                           */
/* Returns pulse duration in microseconds, or -1 on timeout/error.     */
static long measure_echo_pulse(void)
{
    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;  /* timeout waiting for echo start */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;  /* timeout waiting for echo end */
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/* ------------------------------------------------------------------ */
/* Convert pulse duration (us) to distance (cm).                       */
/* Returns distance in cm, or -1.0 on invalid pulse.                  */
static float calculate_distance(long pulse_us)
{
    if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
        return -1.0f;
    }
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    char timestamp[32];

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioDelay(50000);  /* 50 ms settle time */

    printf("HC-SR04 Ultrasonic Distance Sensor (pigpio)\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d | Sample period: 1 s\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        trigger_sensor();

        long pulse_us = measure_echo_pulse();
        if (pulse_us < 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            fprintf(stderr, "[%s] Error: echo pulse measurement failed.\n", timestamp);
        } else {
            float distance = calculate_distance(pulse_us);
            if (distance < 0.0f) {
                get_timestamp(timestamp, sizeof(timestamp));
                fprintf(stderr, "[%s] Error: invalid pulse duration (%ld us).\n",
                        timestamp, pulse_us);
            } else {
                get_timestamp(timestamp, sizeof(timestamp));
                printf("[%s] Distance: %.2f cm (pulse: %ld us)\n",
                       timestamp, distance, pulse_us);
            }
        }

        /* Sleep 1 second between samples (interruptible by signals) */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms slices */
        }
    }

    /* Cleanup */
    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

