#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define NUM_RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486f
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE (NUM_RANGE_BINS * 2)
#define FRAME_SIZE (MAGIC_WORD_SIZE + RANGE_PROFILE_SIZE)
#define LOG_FILE "intrusion_log.csv"

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t terminate = 0;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int init_gpio(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    return 0;
}

static int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime failed");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s,%.3f\n", timestamp, distance) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void trigger_alert(int pin) {
    gpioWrite(pin, 1);
    sleep(2);
    gpioWrite(pin, 0);
}

static int find_target(const uint8_t *data, float *distance) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        uint16_t raw = (uint16_t)(data[i * 2] | (data[i * 2 + 1] << 8));
        if (raw > 0) {
            *distance = (float)i * RANGE_RESOLUTION;
            return 1;
        }
    }
    return 0;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("Error reading from UART");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return 1;
    }

    if (init_gpio(GPIO_LED) < 0) {
        close(uart_fd);
        return 1;
    }

    uint8_t frame_buf[FRAME_SIZE];
    uint8_t magic_buf[MAGIC_WORD_SIZE];
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_exact(uart_fd, magic_buf, MAGIC_WORD_SIZE) != 0) {
            if (++consecutive_errors > 10) {
                fprintf(stderr, "Too many consecutive UART errors, aborting.\n");
                break;
            }
            continue;
        }
        consecutive_errors = 0;

        if (memcmp(magic_buf, MAGIC_WORD, MAGIC_WORD_SIZE) != 0) {
            continue;
        }

        if (read_exact(uart_fd, frame_buf, RANGE_PROFILE_SIZE) != 0) {
            continue;
        }

        float distance;
        if (find_target(frame_buf, &distance)) {
            if (distance <= DISTANCE_THRESHOLD) {
                printf("Intrusion detected! Distance: %.3f meters\n", distance);
                trigger_alert(GPIO_LED);
                if (log_intrusion(distance) != 0) {
                    fprintf(stderr, "Failed to log intrusion.\n");
                }
            }
        }
    }

    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

