#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_fp, const char *event) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    fflush(log_fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");
    log_event(log_fp, "Program started");

    int prev_state = -1;

    while (program_running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read sensor: %s\n", strerror(errno));
            log_event(log_fp, "Error reading sensor");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int obstacle_detected = (val == 0);

        if (obstacle_detected) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Failed to activate buzzer: %s\n", strerror(errno));
                log_event(log_fp, "Error activating buzzer");
            }
        } else {
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Failed to deactivate buzzer: %s\n", strerror(errno));
                log_event(log_fp, "Error deactivating buzzer");
            }
        }

        if (obstacle_detected != prev_state) {
            if (obstacle_detected) {
                printf("Obstacle detected!\n");
                log_event(log_fp, "Obstacle detected");
            } else {
                printf("Obstacle cleared.\n");
                log_event(log_fp, "Obstacle cleared");
            }
            prev_state = obstacle_detected;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    log_event(log_fp, "Program stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    return ret;
}

