/*
 * Raspberry Pi 4 Model B - TDK Chirp ICU-20201 Ultrasonic ToF Sensor
 * Library: pigpio (modern API, no wiringPi)
 * Bus: I2C bus 1, Address: 0x69 (default)
 * Alert: GPIO 17 (BCM), active-low alert
 * Log: distance_log.txt (ISO 8601 timestamps)
 *
 * Build: gcc -Wall -Wextra -O2 -o icu20201 icu20201.c -lpigpio -lrt
 * Run:   sudo ./icu20201
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ICU20201_ADDR        0x69          /* default I2C address            */
#define DISTANCE_REG_HIGH    0x31          /* high byte of distance result   */
#define DISTANCE_REG_LOW     0x32          /* low  byte of distance result   */
#define ALERT_GPIO           17            /* BCM pin for active-low alert    */
#define DISTANCE_THRESHOLD   10.0f         /* cm                             */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between samples         */
#define LOG_FILE             "distance_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_terminate = 0;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  initialize_i2c(void);
static int  read_distance(float *distance_cm);
static void log_distance(float distance_cm);
static void trigger_alert(void);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------ I2C init --------------------------------- */
static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, ICU20201_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- Read distance ------------------------------- */
/*
 * Returns 0 on success and stores distance in cm; -1 on I2C error.
 * The ICU-20201 returns a 16-bit distance value in register 0x31 (high)
 * and 0x32 (low).  The unit is typically cm, but the exact scale factor
 * depends on the specific ICU variant; this implementation treats the
 * raw 16-bit value as distance in cm.
 */
static int read_distance(float *distance_cm)
{
    int hi, lo;

    hi = i2cReadByteData(g_i2c_handle, DISTANCE_REG_HIGH);
    if (hi < 0) {
        fprintf(stderr, "[ERROR] I2C read high byte failed: %d\n", hi);
        return -1;
    }

    lo = i2cReadByteData(g_i2c_handle, DISTANCE_REG_LOW);
    if (lo < 0) {
        fprintf(stderr, "[ERROR] I2C read low byte failed: %d\n", lo);
        return -1;
    }

    uint16_t raw = ((uint16_t)(hi & 0xFF) << 8) | (uint16_t)(lo & 0xFF);
    *distance_cm = (float)raw;
    return 0;
}

/* ------------------------------ Log data --------------------------------- */
static void log_distance(float distance_cm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[WARN] time() failed; logging without timestamp\n");
        fprintf(g_log_file, "%.2f cm\n", distance_cm);
    } else {
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        if (t == NULL) {
            fprintf(stderr, "[WARN] localtime_r failed\n");
            fprintf(g_log_file, "%.2f cm\n", distance_cm);
        } else {
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
            fprintf(g_log_file, "%s, %.2f cm\n", ts, distance_cm);
        }
    }
    fflush(g_log_file);
}

/* ------------------------------ Alert GPIO ------------------------------- */
static void trigger_alert(void)
{
    /* Active-low alert: drive LOW when below threshold */
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(LOW) on GPIO %d failed\n", ALERT_GPIO);
    }
    gpioDelay(500000);  /* 500 ms pulse */
    if (gpioWrite(ALERT_GPIO, 1) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(HIGH) on GPIO %d failed\n", ALERT_GPIO);
    }
}

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init --- */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALERT_GPIO, 1) < 0) {  /* start with alert off (HIGH) */
        fprintf(stderr, "[FATAL] gpioWrite(%d, HIGH) failed\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signal handling\n");
    }

    printf("ICU-20201 distance monitor started.  Threshold: %.1f cm  GPIO%d alert.\n",
           DISTANCE_THRESHOLD, ALERT_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (!g_terminate) {
        float distance;

        if (read_distance(&distance) != 0) {
            fprintf(stderr, "[ERROR] I2C read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            printf("[ALERT] Distance %.2f cm < %.1f cm threshold -> alert\n",
                   distance, DISTANCE_THRESHOLD);
            trigger_alert();
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

