/*
 * Parking assistance system using STMicroelectronics VL53L1X ToF sensor.
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (I2C via /dev/i2c-1, address 0x29)
 *
 * Build:  gcc -O2 -Wall -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:    sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X register addresses (16-bit, big-endian on the bus) ---- */
#define VL53L1X_DEFAULT_ADDR          0x29
#define VL53L1X_REG_MODEL_ID          0x010F
#define VL53L1X_REG_SOFT_RESET        0x0000
#define VL53L1X_REG_SYSRANGE_START    0x0000
#define VL53L1X_REG_RESULT_INT_STATUS 0x0013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0078
#define VL53L1X_REG_SYSTEM_INT_CLEAR  0x0014
#define VL53L1X_REG_SYSTEM_MODE_START 0x0007

#define VL53L1X_MODEL_ID              0xEA
#define VL53L1X_SOFT_RESET_VALUE      0x00
#define VL53L1X_SYSRANGE_START_CONT   0x01

#define I2C_BUS                       1
#define LOG_FILE                      "distance_log.csv"
#define POLL_TIMEOUT_MS               100
#define LOOP_DELAY_US                 100000   /* 100 ms */

/* ---- Parking guidance thresholds (mm) ---- */
#define STOP_THRESHOLD_MM             300
#define APPROACH_THRESHOLD_MM         600
#define SLOW_THRESHOLD_MM             1200

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers (16-bit register addressing)                  */
/* ------------------------------------------------------------------ */

/* Write one byte to a 16-bit register address. */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read one byte from a 16-bit register address. */
static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    char data;

    addr[0] = (char)(reg >> 8);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, &data, 1) != 1)
        return -1;

    *out = (uint8_t)data;
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit register address. */
static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *out)
{
    uint8_t hi, lo;
    if (vl53l1x_read_byte(handle, reg, &hi) < 0)
        return -1;
    if (vl53l1x_read_byte(handle, reg + 1, &lo) < 0)
        return -1;
    *out = ((uint16_t)hi << 8) | (uint16_t)lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X sensor operations                                           */
/* ------------------------------------------------------------------ */

static int vl53l1x_init(int handle)
{
    uint8_t model_id;

    /* Verify sensor identity. */
    if (vl53l1x_read_byte(handle, VL53L1X_REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    /* Software reset. */
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VALUE) < 0) {
        fprintf(stderr, "Error: failed to write soft-reset register.\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    /* Start continuous back-to-back ranging. */
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SYSTEM_MODE_START,
                           VL53L1X_SYSRANGE_START_CONT) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    return 0;
}

/*
 * Poll the SYSRANGE__START register until it self-clears (bit 0 = 0).
 * Returns 0 on success, -1 on timeout or I2C error.
 */
static int vl53l1x_wait_for_data_ready(int handle)
{
    uint8_t status;
    int elapsed = 0;

    while (elapsed < POLL_TIMEOUT_MS) {
        if (vl53l1x_read_byte(handle, VL53L1X_REG_SYSRANGE_START, &status) < 0)
            return -1;
        if ((status & 0x01) == 0)
            return 0;
        gpioDelay(1000); /* 1 ms */
        elapsed++;
    }
    return -1;
}

/*
 * Read a distance sample.
 * Returns 0 on success and stores distance in *distance_mm.
 * Returns -1 on timeout, I2C error, or no data ready.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t int_status;

    /* Check if data is ready. */
    if (vl53l1x_read_byte(handle, VL53L1X_REG_RESULT_INT_STATUS, &int_status) < 0)
        return -1;

    if ((int_status & 0x01) == 0) {
        /* No new data yet. */
        return -1;
    }

    /* Read 16-bit distance (big-endian) from RESULT__RANGE_STATUS + 10. */
    if (vl53l1x_read_word(handle, VL53L1X_REG_RESULT_RANGE_STATUS, distance_mm) < 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal. */
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SYSTEM_INT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Parking guidance                                                     */
/* ------------------------------------------------------------------ */
static void print_parking_guidance(uint16_t distance_mm)
{
    if (distance_mm < STOP_THRESHOLD_MM)
        printf("STOP\n");
    else if (distance_mm < APPROACH_THRESHOLD_MM)
        printf("APPROACH\n");
    else if (distance_mm < SLOW_THRESHOLD_MM)
        printf("SLOW\n");
    else
        printf("CLEAR\n");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, distance_mm) < 0)
        return -1;
    if (fflush(fp) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the VL53L1X default address. */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_DEFAULT_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the VL53L1X sensor. */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode). Write header if the file is new. */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Determine whether the file is empty so we can write a header. */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    /* Main loop. */
    while (g_running) {
        uint16_t distance_mm = 0;

        /* Wait for the next measurement to be ready. */
        if (vl53l1x_wait_for_data_ready(g_i2c_handle) < 0) {
            fprintf(stderr, "Warning: data-ready timeout, skipping cycle.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Read and log the distance. */
        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) < 0) {
            fprintf(stderr, "Warning: distance read failed, skipping cycle.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (log_data(g_log_file, distance_mm) < 0) {
            fprintf(stderr, "Warning: failed to write to log file.\n");
        }

        print_parking_guidance(distance_mm);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

