/*
 * CH201 ultrasonic ToF sensor reader with LED blink frequency proportional
 * to distance.  Uses pigpio for I2C and GPIO on a Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   CH201 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   CH201 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   CH201 VDD  -> 3.3 V
 *   CH201 GND  -> GND
 *   LED anode  -> GPIO 18 (via 330 ohm resistor to GND)
 *
 * Build:  gcc -O2 -Wall -o ch201_blink ch201_blink.c -lpigpio -lrt
 * Run:    sudo ./ch201_blink
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- CH201 constants (from datasheet / pigpio i2cReadWordData wrappers) ---- */
#define CH201_I2C_ADDR        0x45
#define CH201_REG_PRODUCT_ID  0x00
#define CH201_REG_DISTANCE    0x08
#define CH201_REG_CONFIG      0x0A
#define CH201_REG_SOFT_RESET  0x0B

#define CH201_PRODUCT_ID      0x00
#define CH201_SOFT_RESET_VAL  0x00

/* ---- Application constants ---- */
#define I2C_BUS              1
#define LED_GPIO             18
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define RETRY_DELAY_US       10000    /* 10 ms */
#define MAX_RETRIES          3
#define DIST_MIN_MM          50
#define DIST_MAX_MM          500
#define FREQ_MIN_HZ          10
#define FREQ_MAX_HZ          1

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit-addressed register.                      */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int ch201_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a 16-bit-addressed register.                     */
/* Returns 0 on success and stores value in *out, -1 on failure.       */
/* ------------------------------------------------------------------ */
static int ch201_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadByteData(reg=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit distance register (big-endian).                     */
/* Returns 0 on success and stores distance in *out_mm, -1 on failure. */
/* ------------------------------------------------------------------ */
static int ch201_read_distance(int handle, uint16_t *out_mm)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadWordData(handle, CH201_REG_DISTANCE);
        if (rc >= 0) {
            *out_mm = (uint16_t)rc;   /* pigpio returns little-endian word */
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadWordData(reg=0x%02X) failed (rc=%d), attempt %d/%d\n",
                CH201_REG_DISTANCE, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialise the CH201: soft-reset, verify product ID, configure.     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int ch201_init(int handle)
{
    if (ch201_write_reg(handle, CH201_REG_SOFT_RESET, CH201_SOFT_RESET_VAL) != 0) {
        fprintf(stderr, "[ERROR] Soft reset failed.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle after reset */

    uint8_t prod_id = 0;
    if (ch201_read_reg(handle, CH201_REG_PRODUCT_ID, &prod_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read product ID.\n");
        return -1;
    }
    if (prod_id != CH201_PRODUCT_ID) {
        fprintf(stderr, "[ERROR] Unexpected product ID 0x%02X (expected 0x%02X).\n",
                prod_id, CH201_PRODUCT_ID);
        return -1;
    }

    /*
     * Configure register (0x0A):
     *   bit 0 = 0  -> continuous mode
     *   bit 1 = 0  -> default range
     *   bit 2 = 0  -> default resolution
     *   ...
     * A value of 0x00 is a safe default for the CH201.
     */
    if (ch201_write_reg(handle, CH201_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "[ERROR] Failed to configure CH201.\n");
        return -1;
    }

    printf("[INFO] CH201 initialised (product ID 0x%02X).\n", prod_id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Map distance (mm) to blink frequency (Hz).                          */
/* ------------------------------------------------------------------ */
static int distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm <= DIST_MIN_MM)
        return FREQ_MIN_HZ;
    if (distance_mm >= DIST_MAX_MM)
        return FREQ_MAX_HZ;

    /* Linear interpolation: closer -> faster */
    int freq = FREQ_MIN_HZ -
               (int)((distance_mm - DIST_MIN_MM) *
                     (FREQ_MIN_HZ - FREQ_MAX_HZ) /
                     (DIST_MAX_MM - DIST_MIN_MM));
    return freq;
}

/* ------------------------------------------------------------------ */
/* Blink LED at the given frequency for one full sample period.        */
/* Returns elapsed microseconds.                                      */
/* ------------------------------------------------------------------ */
static uint32_t blink_led(int gpio, int frequency_hz)
{
    if (frequency_hz <= 0)
        frequency_hz = 1;

    uint32_t half_period_us = 5000000 / (uint32_t)frequency_hz;
    uint32_t elapsed = 0;

    while (elapsed < SAMPLE_PERIOD_US && g_running) {
        gpioWrite(gpio, 1);
        uint32_t on_start = gpioTick();
        gpioDelay(half_period_us);
        elapsed += (gpioTick() - on_start);
        if (elapsed >= SAMPLE_PERIOD_US)
            break;

        gpioWrite(gpio, 0);
        uint32_t off_start = gpioTick();
        gpioDelay(half_period_us);
        elapsed += (gpioTick() - off_start);
    }
    return elapsed;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at CH201 address ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d).\n",
                I2C_BUS, CH201_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- Initialise sensor ---- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] CH201 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Starting distance sampling (period %d ms). Ctrl+C to stop.\n",
           SAMPLE_PERIOD_US / 1000);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t distance_mm = 0;
        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "[ERROR] Distance read failed; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int freq = distance_to_frequency(distance_mm);

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        printf("[%s] Distance: %5u mm  |  Blink Freq: %3d Hz\n",
               ts, distance_mm, freq);
        fflush(stdout);

        /* Blink LED for one full sample period */
        blink_led(LED_GPIO, freq);
    }

    /* ---- Cleanup ---- */
    printf("\n[INFO] Shutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

