#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS   50
#define POLL_MS       10
#define LOG_FILE      "proximity_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(FILE *fp, int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    FILE *log_fp = NULL;
    int prev1 = 1, prev2 = 1;
    uint32_t last_change1 = 0, last_change2 = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        goto cleanup_gpio;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        goto cleanup_gpio;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Monitoring TCRT5000 sensors on GPIO %d and %d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);

    while (running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", SENSOR_1_GPIO);
            break;
        }
        if (s2 < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", SENSOR_2_GPIO);
            break;
        }

        uint32_t now = gpioTick();

        if (s1 != prev1) {
            if (now - last_change1 >= DEBOUNCE_MS * 1000) {
                if (s1 == 0 && prev1 == 1) {
                    if (log_event(log_fp, 1, "DETECTED") != 0) break;
                } else if (s1 == 1 && prev1 == 0) {
                    if (log_event(log_fp, 1, "CLEARED") != 0) break;
                }
                prev1 = s1;
            }
            last_change1 = now;
        }

        if (s2 != prev2) {
            if (now - last_change2 >= DEBOUNCE_MS * 1000) {
                if (s2 == 0 && prev2 == 1) {
                    if (log_event(log_fp, 2, "DETECTED") != 0) break;
                } else if (s2 == 1 && prev2 == 0) {
                    if (log_event(log_fp, 2, "CLEARED") != 0) break;
                }
                prev2 = s2;
            }
            last_change2 = now;
        }

        gpioDelay(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }

cleanup_gpio:
    gpioTerminate();
    return ret;
}

