#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49

/* CH-101 register addresses */
#define REG_MEAS_TRIGGER  0x04
#define REG_MEAS_STATUS   0x06
#define REG_DIST_HIGH     0x08
#define REG_DIST_LOW      0x09

#define MEAS_TRIGGER_CMD  0x01
#define MEAS_STATUS_DR    0x01   /* data ready bit */
#define MEAS_STATUS_ERR   0x02   /* error bit */

#define LOG_FILE         "distance_log.csv"
#define SAMPLE_PERIOD_MS 500
#define MEAS_TIMEOUT_MS  50

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an 8-bit register.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian register pair (high at reg, low at reg+1).
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int i2c_read_reg16_be(int fd, uint8_t reg_high, uint16_t *out)
{
    uint8_t hi, lo;
    if (i2c_read_reg8(fd, reg_high, &hi) == -1)
        return -1;
    if (i2c_read_reg8(fd, (uint8_t)(reg_high + 1), &lo) == -1)
        return -1;
    *out = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */

/*
 * Trigger a single range measurement and wait for data-ready.
 * Returns 0 on success, -1 on error.
 */
static int ch101_trigger_and_wait(int fd)
{
    if (i2c_write_reg8(fd, REG_MEAS_TRIGGER, MEAS_TRIGGER_CMD) == -1)
        return -1;

    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 5) {
        uint8_t status;
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) == -1)
            return -1;
        if (status & MEAS_STATUS_ERR) {
            fprintf(stderr, "CH-101 measurement error (status=0x%02X)\n", status);
            return -1;
        }
        if (status & MEAS_STATUS_DR)
            return 0;
        usleep(5000);  /* 5 ms */
    }
    fprintf(stderr, "CH-101 measurement timeout after %d ms\n", MEAS_TIMEOUT_MS);
    return -1;
}

/*
 * Read the 16-bit distance in millimetres.
 * Returns 0 on success and stores the value in *distance_mm; -1 on error.
 */
static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    return i2c_read_reg16_be(fd, REG_DIST_HIGH, distance_mm);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(fp, "%s,%u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) == EOF)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,distance_mm\n") < 0 || fflush(g_log_fp) == EOF) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Smart Parking System started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        if (ch101_trigger_and_wait(g_i2c_fd) == -1) {
            fprintf(stderr, "Measurement failed; skipping sample.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        uint16_t distance_mm;
        if (ch101_read_distance(g_i2c_fd, &distance_mm) == -1) {
            fprintf(stderr, "Distance read failed; skipping sample.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        log_data(g_log_fp, distance_mm);
        printf("Distance: %u mm\n", distance_mm);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

