/*
 * VL53L5CX 8x8 zone grid distance reader for Raspberry Pi Zero W
 * Uses Linux i2c-dev kernel interface directly (no wiringPi).
 *
 * Wiring:
 *   VL53L5CX SDA -> GPIO2 (pin 3, I2C1 SDA)
 *   VL53L5CX SCL -> GPIO3 (pin 5, I2C1 SCL)
 *   VL53L5CX VDD -> 3.3 V
 *   VL53L5CX GND -> GND
 *
 * Build: gcc -O2 -Wall -o vl53l5cx_8x8 vl53l5cx_8x8.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L5CX_ADDR  0x29
#define NUM_ZONES      64          /* 8x8 grid */
#define POLL_MS        500

/* VL53L5CX register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET                 0x0003
#define REG_SYSTEM_START               0x0004
#define REG_SYSTEM_STATUS              0x0005
#define REG_RESULT_RANGE_STATUS        0x0089
#define REG_RESULT_DISTANCE_BASE       0x0096  /* 2 bytes per zone */

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a single byte value. */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%04X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from a 16-bit register address. */
static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *out)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read_reg8 write(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian value from a 16-bit register address. */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    uint8_t data[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "i2c_read_reg16 read(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Read all 64 distance values (2 bytes each) starting at REG_RESULT_DISTANCE_BASE. */
static int read_all_zones(int fd, uint16_t *distances)
{
    uint8_t addr[2];
    uint8_t data[NUM_ZONES * 2];

    addr[0] = (uint8_t)(REG_RESULT_DISTANCE_BASE >> 8);
    addr[1] = (uint8_t)(REG_RESULT_DISTANCE_BASE & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "read_all_zones write failed: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "read_all_zones read failed: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_ZONES; i++)
        distances[i] = ((uint16_t)data[i * 2] << 8) | data[i * 2 + 1];

    return 0;
}

/*
 * Initialize the VL53L5CX for 8x8 zone grid ranging.
 * Returns 0 on success, -1 on failure.
 */
static int init_sensor(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x00) < 0)
        return -1;
    usleep(10000);  /* 10 ms */

    /* Start ranging (bit 0 = 1) */
    if (i2c_write_reg8(fd, REG_SYSTEM_START, 0x01) < 0)
        return -1;
    usleep(10000);  /* 10 ms for first measurement */

    return 0;
}

static void print_zones(const uint16_t *distances)
{
    printf("--- 8x8 Zone Grid (64 zones) ---\n");
    for (int i = 0; i < NUM_ZONES; i++)
        printf("Zone %2d: %4u mm\n", i, distances[i]);
    printf("--------------------------------\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L5CX_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor(g_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    uint16_t distances[NUM_ZONES];

    while (g_running) {
        if (read_all_zones(g_fd, distances) < 0) {
            fprintf(stderr, "Failed to read zone data.\n");
            break;
        }
        print_zones(distances);
        usleep(POLL_MS * 1000);
    }

    /* Stop ranging */
    if (g_fd >= 0) {
        i2c_write_reg8(g_fd, REG_SYSTEM_START, 0x00);
        close(g_fd);
        g_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

