#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* MLX75030 I2C default address (7-bit) */
#define MLX75030_ADDR 0x4C

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* MLX75030 register addresses (16-bit, big-endian on the bus) */
#define MLX75030_REG_DISTANCE 0x0000
#define MLX75030_REG_STATUS   0x0002

/* Retry configuration */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000  /* 10 ms */

/* Sampling interval */
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register address                   */
/* ------------------------------------------------------------------ */
static int mlx_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 4);
        if (rc == 0)
