#define REG_RESULT_DISTANCE_H   0x0096
#define REG_RESULT_DISTANCE_L   0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address and a 16-bit value to the VL53L4CX.
 * pigpio's i2cWriteWordData sends (reg << 8) | (val & 0xFF), so we pass
 * (reg << 8) | val as the argument. */
static int vl53l4cx_write16(int handle, uint16_t reg, uint16_t val)
{
    int rc = i2cWriteWordData(handle, (reg << 8) | (val & 0xFF), val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed at reg 0x%04X (rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit register address.
 * pigpio's i2cReadWordData sends the register address, then reads 2 bytes. */
static int vl53l4cx_read16(int handle, uint16_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg << 8);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed at reg 0x%04X (rc=%d)\n", reg, rc);
        return -1;
    }
    /* pigpio returns the word as (low_byte << 8) | high_byte */
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

static int vl53l4cx_init(int handle)
{
    /* Soft reset: write 0x00 to register 0x7FFF */
    if (vl53l4cx_write16(handle, REG_SOFT_RESET, 0x0000) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Start ranging: write 0x00 to register 0x0009 */
    if (vl53l4cx_write16(handle, REG_SYSTEM_START, 0x0000) < 0)
        return -1;

    return 0;
}

static int vl53l4cx_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;

    /* Poll interrupt status register 0x0046 bit 0 */
    if (vl53l4cx_read16(handle, REG_INTERRUPT_STATUS, &status) < 0)
        return -1;

    if ((status & 0x0001) == 0) {
        /* No new data yet — skip this cycle */
        return 1;
