    uint16_t dist_h = 0, dist_l = 0;
    if (vl53l4cx_read16(handle, REG_RESULT_DISTANCE_H, &dist_h) < 0)
        return -1;
    if (vl53l4cx_read16(handle, REG_RESULT_DISTANCE_L, &dist_l) < 0)
        return -1;

    *distance_mm = (dist_h << 8) | dist_l;
    return 0;
