{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("Timestamp: %s.%06ld, Distance: %u mm\n",
           timestamp, ts.tv_nsec / 1000, distance_mm);
    fflush(stdout);
}

