{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, VL53L4CX_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l4cx_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L4CX ranging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l4cx_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            log_distance(distance);
        } else if (rc < 0) {
            fprintf(stderr, "I2C communication error — continuing\n");
        }
        /* rc == 1 means no new data yet, just skip */

        gpioDelay(500000); /* 500 ms */
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

