static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_sensor_initialized = false;

/* --------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void cleanup(void);
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_distance_mm(uint16_t *distance_out);
static void control_buzzer(bool on);
static void log_error(const char *msg);

/* ------------------------------ Main ----------------------------------- */

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", BUZZER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);  /* ensure buzzer is off at start */

    /* Initialize I2C and sensor */
    if (init_i2c() != 0) {
        log_error("I2C initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        log_error("Sensor initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X ready. Polling every %d ms. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_US / 1000);

    bool buzzer_on = false;

    while (g_running) {
        uint16_t distance = 0;
        int rc = read_distance_mm(&distance);

        if (rc == 0) {
            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                if (!buzzer_on) {
                    control_buzzer(true);
                    buzzer_on = true;
                }
            } else {
                if (buzzer_on) {
                    control_buzzer(false);
                    buzzer_on = false;
                }
