                g_i2c_handle = -1;
                g_sensor_initialized = false;
            }
            if (init_i2c() != 0) {
                log_error("I2C re-initialisation failed");
            } else if (init_sensor() != 0) {
                log_error("Sensor re-initialisation failed");
            }
        }

