    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Signal / Cleanup -------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
