 *
 * 1. Soft reset: write 0x00 to SOFT_RESET (0x0001).
 * 2. Re-apply default I2C address (0x29).
 * 3. Start continuous ranging: write 0x02 to SYSTEM__MODE_START (0x0007).
 *
 * The sensor is left in continuous ranging mode so that new measurements
 * are available immediately without needing a separate trigger.
 */
static int init_sensor(void)
{
