    if (i2cWriteByteData(g_i2c_handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset write failed.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle after reset */

    /* Re-apply default I2C address (required after reset) */
    if (i2cWriteByteData(g_i2c_handle, REG_I2C_SLAVE__DEVICE_ADDRESS,
                         VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: I2C address write failed.\n");
        return -1;
    }

    /* Start continuous ranging mode */
    if (i2cWriteByteData(g_i2c_handle, REG_SYSTEM__MODE_START, 0x02) < 0) {
        fprintf(stderr, "Error: mode start write failed.\n");
        return -1;
