    int high = i2cReadByteData(g_i2c_handle,
                              REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM + 1);
    if (high < 0) {
        fprintf(stderr, "Error: distance high byte read failed (rc=%d).\n", high);
        return -1;
