static void control_buzzer(bool on)
{
    if (gpioWrite(BUZZER_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "Warning: gpioWrite(%d) failed for buzzer.\n", on ? 1 : 0);
    }
}

/* --------------------------- Error Logging ------------------------------ */

static void log_error(const char *msg)
{
    fprintf(stderr, "Error: %s\n", msg);
}

