/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/*
 * Measure distance with a single HC-SR04 reading.
 * Returns distance in cm, or ERROR_DISTANCE_CM on timeout/error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return ERROR_DISTANCE_CM;
    }
    gpioDelay(5);  /* let line settle */

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return ERROR_DISTANCE_CM;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return ERROR_DISTANCE_CM;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: echo stuck low (timeout)\n");
            return ERROR_DISTANCE_CM;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if stuck high) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: echo stuck high (timeout)\n");
            return ERROR_DISTANCE_CM;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0) {
        fprintf(stderr, "Warning: zero pulse width\n");
        return ERROR_DISTANCE_CM;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 */
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

/*
 * Map distance to servo angle.
 *   2 cm  -> -90 deg
 * 400 cm  -> +90 deg
 * Clamps to [-90, +90].
 */
static int map_distance_to_angle(float distance_cm)
{
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    float frac = (distance_cm - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int angle = (int)((SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) * frac +
                      SERVO_MIN_PULSE_US);

    if (angle < SERVO_MIN_PULSE_US) angle = SERVO_MIN_PULSE_US;
    if (angle > SERVO_MAX_PULSE_US) angle = SERVO_MAX_PULSE_US;
    return angle;
}

/*
 * Set servo to given angle (pulse width in microseconds).
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(int angle_us)
{
    if (gpioServo(SERVO_PIN, angle_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d) failed\n", angle_us);
        return -1;
    }
    return 0;
}

/*
 * Append a timestamped reading to sensor_data.log.
 */
static void log_data(float distance_cm)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        perror("Error opening sensor_data.log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_cm);
    } else {
        fprintf(fp, "<time-error>, Distance: %.2f cm\n", distance_cm);
    }

    if (fclose(fp) != 0)
        perror("Warning: fclose(sensor_data.log)");
}

int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);

    /* ---- Main loop ---- */
    while (!g_terminate) {
        float distance = measure_distance();

        if (distance == ERROR_DISTANCE_CM) {
            /* Skip servo update and log on error */
            log_data(ERROR_DISTANCE_CM);
        } else {
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Warning: servo update failed\n");
            }
            log_data(distance);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    gpioServo(SERVO_PIN, 0);   /* stop servo pulses */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nTerminated gracefully.\n");
    return EXIT_SUCCESS;
}

