#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND 34300.0   /* cm/s */
#define MIN_DISTANCE   2.0       /* cm */
#define MAX_DISTANCE   400.0     /* cm */
#define THRESHOLD_CM   30.0      /* cm */
#define TIMEOUT_US     30000     /* 30 ms timeout for echo */
#define SAMPLE_PERIOD  100000    /* 100 ms between readings */

static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback for echo pulse timing                         */
/* ------------------------------------------------------------------ */
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_seen  = 0;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_seen  = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_seen = 1;
    }
}

/* ------------------------------------------------------------------ */
/* Send a 10 us HIGH trigger pulse                                     */
/* ------------------------------------------------------------------ */
static void send_trigger(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);                 /* 10 us HIGH pulse */
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Measure distance in cm; returns -1.0 on timeout / error            */
/* ------------------------------------------------------------------ */
static double measure_distance(void)
{
    start_tick = 0;
    end_tick   = 0;
    echo_seen  = 0;

    send_trigger();

    /* Wait for echo or timeout */
    uint32_t t0 = gpioTick();
    while (!echo_seen && (gpioTick() - t0) < TIMEOUT_US) {
        gpioDelay(100);            /* 100 us granularity */
    }

    if (!echo_seen) {
        return -1.0;               /* sensor absent or no echo */
    }

    /* Handle 32-bit tick wraparound */
    uint32_t pulse_us;
    if (end_tick >= start_tick) {
        pulse_us = end_tick - start_tick;
    } else {
