#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define SERVO_OPEN_US 1500
#define SERVO_CLOSE_US 1000
#define SERVO_RANGE 1000
#define LOG_FILE "gate_log.txt"
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_TOPIC "gate_control"
#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_INTERRUPT_CLEAR 0x008A
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0084
#define VL53L1X_REG_SYSTEM_THRESH_HIGH 0x008C
#define VL53L1X_REG_SYSTEM_THRESH_LOW 0x008E
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x008B
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x008F
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x008B
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x008A

static int i2c_handle = -1;
static MQTTClient client;
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, event);
    fflush(log_file);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, int len) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int init_vl53l1x(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_HIGH, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_LOW, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle) {
    uint8_t data[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) < 0) return -1;
    return (data[0] << 8) | data[1];
}

static void control_servo(int pin, int position) {
    if (position < 0) position = 0;
    if (position > SERVO_RANGE) position = SERVO_RANGE;
    int pulse_width = SERVO_CLOSE_US + (position * (SERVO_OPEN_US - SERVO_CLOSE_US)) / SERVO_RANGE;
    gpioServo(pin, pulse_width);
}

static void mqtt_message_arrived(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)context; (void)topicLen;
    char *payload = message->payload;
    if (strcmp(payload, "force_open") == 0) {
        control_servo(SERVO_PIN, 100);
        log_event("Gate forced open");
    } else if (strcmp(payload, "force_close") == 0) {
        control_servo(SERVO_PIN, 0);
        log_event("Gate forced closed");
    } else if (strcmp(payload, "status_request") == 0) {
        log_event("Status request received");
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    control_servo(SERVO_PIN, 0);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    if (MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT create failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        MQTTClient_destroy(&client);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    MQTTClient_subscribe(client, MQTT_TOPIC, 1);
    MQTTClient_setCallbacks(client, NULL, NULL, mqtt_message_arrived, NULL);
    int gate_open = 0;
    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "I2C read error\n");
            log_event("I2C read error");
            gpioDelay(1000000);
            continue;
        }
        if (distance < DISTANCE_THRESHOLD && !gate_open) {
            control_servo(SERVO_PIN, 100);
            log_event("Gate opened");
            gate_open = 1;
        } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
            control_servo(SERVO_PIN, 0);
            log_event("Gate closed");
            gate_open = 0;
        }
        gpioDelay(100000);
    }
    control_servo(SERVO_PIN, 0);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

