/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 * Library: pigpio
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16)
 *   ECHO -> GPIO 24 (physical pin 18) via voltage divider (5V -> 3.3V)
 *
 * NOTE: The HC-SR04 ECHO output is 5V.  The Raspberry Pi GPIO pins are
 * 3.3V tolerant.  Use a voltage divider or logic-level converter to
 * drive ECHO to 3.3V.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define SPEED_OF_SOUND   0.0343f   /* cm per microsecond */
#define MIN_PULSE_US     100       /* noise / timeout floor */
#define MAX_PULSE_US     30000     /* ~5 m round trip cap */
#define TRIGGER_PULSE_US 10
#define MEASURE_PERIOD_US 200000   /* 5 Hz */
#define ECHO_TIMEOUT_US  60000     /* 60 ms max wait for echo */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/*
 * pigpio tick is a 32-bit microsecond counter that wraps every
 * ~72 minutes.  This helper computes (b - a) modulo 2^32 so that
 * the result is always positive even across a wrap.
 */
static uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

/*
 * pigpio alert callback for ECHO.
 * level: 0 = falling edge, 1 = rising edge, 2 = watchdog timeout
 * tick:  microseconds since boot, wraps every ~72 minutes
 */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    static uint32_t rising_tick = 0;
    static uint32_t falling_tick = 0;
    static bool     have_rising = false;

    if (level == 1) {
        rising_tick = tick;
        have_rising = true;
    } else if (level == 0 && have_rising) {
        falling_tick = tick;
        uint32_t pulse_us = tick_diff(rising_tick, falling_tick);

        if (pulse_us >= MIN_PULSE_US && pulse_us <= MAX_PULSE_US) {
            float distance = (float)pulse_us * SPEED_OF_SOUND / 2.0f;

            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

            fprintf(stdout, "%s Distance: %.2f cm (pulse %u us)\n",
                    ts, distance, pulse_us);
            if (g_log_file) {
                fprintf(g_log_file, "%s Distance: %.2f cm (pulse %u us)\n",
                        ts, distance, pulse_us);
                fflush(g_log_file);
            }
        } else {
            fprintf(stderr,
                    "Warning: out-of-range pulse %u us (expected %d-%d us)\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        }

        have_rising = false;  /* ready for next cycle */
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: cannot set pull-down on ECHO_PIN %d.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Open log file --- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register alert callback --- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d.\n",
                ECHO_PIN);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, 5 Hz. Press Ctrl+C to exit.\n",
           TRIGGER_PIN, ECHO_PIN);

    /* --- Main measurement loop --- */
    while (g_running) {
        trigger_sensor();

        /* Wait for echo callback to process the current cycle.
         * If no echo is received within ECHO_TIMEOUT_US, log a timeout. */
        uint32_t elapsed = 0;
        while (g_running && elapsed < ECHO_TIMEOUT_US) {
            gpioDelay(1000);  /* 1 ms */
            elapsed += 1000;
        }

        if (g_running && elapsed >= ECHO_TIMEOUT_US) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

            fprintf(stderr, "%s Warning: echo timeout (no object detected)\n",
                    ts);
            if (g_log_file) {
                fprintf(g_log_file,
                        "%s Warning: echo timeout (no object detected)\n",
                        ts);
                fflush(g_log_file);
            }
        }

        /* Sleep remainder of the 200 ms period */
        gpioDelay(MEASURE_PERIOD_US - elapsed);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioSetAlertFunc(ECHO_PIN, NULL);  /* unregister callback */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    return EXIT_SUCCESS;
}

