#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X 16-bit register addresses */
#define VL53L1X_SOFT_RESET 0x0003
#define VL53L1X_SYSTEM_START 0x0000
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

/* Write a 16-bit register address and 1 byte of data to the VL53L1X */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), value };
    return i2cWriteI2CBlockData(handle, buf[0], (char *)&buf[1], 2);
}

/* Read N bytes starting from a 16-bit register address */
static int vl53l1x_read_block(int handle, uint16_t reg, uint8_t *data, uint8_t len) {
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (i2cWriteI2CBlockData(handle, addr[0], (char *)&addr[1], 1) < 0)
        return -1;
    return i2cReadI2CBlockData(handle, addr[0], (char *)data, len);
}

static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (vl53l1x_write_byte(handle, VL53L1X_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    if (vl53l1x_write_byte(handle, VL53L1X_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "VL53L1X soft reset release failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start ranging */
    if (vl53l1x_write_byte(handle, VL53L1X_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "VL53L1X start ranging failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int vl53l1x_read_distance_mm(int handle, int *distance_mm) {
    uint8_t status_buf[1];
    if (vl53l1x_read_block(handle, VL53L1X_RESULT_RANGE_STATUS, status_buf, 1) < 0)
        return -1;

    uint8_t status = status_buf[0];
    if ((status & 0x01) == 0) {
        /* Data not ready yet */
        return 1;
    }

    uint8_t dist_buf[2];
    if (vl53l1x_read_block(handle, VL53L1X_RESULT_DISTANCE, dist_buf, 2) < 0)
        return -1;

    *distance_mm = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void control_gate(int distance_mm) {
    if (distance_mm > 0 && distance_mm < DISTANCE_THRESHOLD_MM) {
        gpioWrite(GATE_OPEN_PIN, 1);
        gpioWrite(GATE_CLOSE_PIN, 0);
        log_event("Gate opened");
    } else {
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
        log_event("Gate closed");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        int distance_mm = -1;
        int rc = vl53l1x_read_distance_mm(i2c_handle, &distance_mm);

        if (rc == 0) {
            control_gate(distance_mm);
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error from VL53L1X\n");
            log_event("I2C read error");
        }
        /* rc == 1: data not ready, just wait */

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

