#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 24
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18

#define DISTANCE_THRESHOLD_1 100  /* mm (10 cm) */
#define DISTANCE_THRESHOLD_2 300  /* mm (30 cm) */

#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_MODE 0x0000
#define REG_RESULT_INT_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, uint32_t len) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int init_vl53l1x(int handle) {
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000); /* 1 ms */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    int retries = 5;
    int delay_ms = 10;

    while (retries > 0) {
        if (i2c_write_reg16(handle, REG_SYSTEM_MODE, 0x01) < 0) {
            retries--; gpioDelay(delay_ms * 1000); delay_ms *= 2; continue;
        }

        int timeout = 100;
        while (timeout > 0) {
            if (i2c_read_reg16(handle, REG_RESULT_INT_STATUS, &status, 1) < 0) {
                timeout--; gpioDelay(1000); continue;
            }
            if (status & 0x01) break;
            timeout--; gpioDelay(1000);
        }

        if (timeout == 0) {
            retries--; gpioDelay(delay_ms * 1000); delay_ms *= 2; continue;
        }

        uint8_t data[2];
        if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, data, 2) < 0) {
            retries--; gpioDelay(delay_ms * 1000); delay_ms *= 2; continue;
        }

        *distance = ((uint16_t)data[0] << 8) | data[1];
        return 0;
    }
    return -1;
}

static void control_motor(int forward, int backward) {
    gpioWrite(MOTOR_FORWARD_PIN, forward);
    gpioWrite(MOTOR_BACKWARD_PIN, backward);
}

static void stop_motor(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

static void trigger_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level == 1) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD_1) {
                control_motor(1, 0);
                printf("Motor: Forward\n");
            } else if (distance > DISTANCE_THRESHOLD_2) {
                control_motor(0, 1);
                printf("Motor: Backward\n");
            } else {
                stop_motor();
                printf("Motor: Stop\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance. Stopping motor.\n");
            stop_motor();
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    stop_motor();

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback) < 0) {
        fprintf(stderr, "Failed to set ISR for trigger pin\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance sensor control started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    gpioSetISRFunc(TRIGGER_PIN, RISING_EDGE, 0, NULL);
    stop_motor();
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

