#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define NUM_ELECTRODES 12
#define POLL_INTERVAL_MS 50

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_AUTO_CONFIG0 0x7B
#define MPR121_AUTO_CONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F
#define MPR121_SOFTRESET 0x80
#define MPR121_ELECONFIG0 0x5E

#define LED_PIN_1 17
#define LED_PIN_2 18
#define LED_PIN_3 27
#define LED_PIN_4 22

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL, NULL, NULL, NULL};
static int log_fd = -1;

static const int led_pins[4] = {LED_PIN_1, LED_PIN_2, LED_PIN_3, LED_PIN_4};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    uint8_t whoami = 0;
    if (i2c_read_reg8(fd, MPR121_ELECONFIG0, &whoami) < 0) return -1;
    if (whoami != 0x0C && whoami != 0x00) {
        fprintf(stderr, "MPR121 not responding (WHOAMI=0x%02X)\n", whoami);
        return -1;
    }

    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;

    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2c_write_reg8(fd, MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1;
        if (i2c_write_reg8(fd, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG1, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_USL, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_LSL, 0x82) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_TL, 0xB4) < 0) return -1;

    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x0C) < 0) return -1;
    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void set_led_pattern(int pattern) {
    for (int i = 0; i < 4; i++) {
        int val = (pattern >> (i * 2)) & 0x03;
        if (gpiod_line_set_value(led_lines[i], val) < 0) {
            fprintf(stderr, "Failed to set LED %d: %s\n", led_pins[i], strerror(errno));
        }
    }
}

static void log_event(const char *msg) {
    if (log_fd < 0) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    dprintf(log_fd, "[%s] %s\n", ts, msg);
    fsync(log_fd);
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fd = open("proximity_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(log_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "proximity_led", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    log_event("Proximity sensor initialized. Monitoring electrodes...");

    while (running) {
        uint16_t status = 0;
        if (read_touch_status(i2c_fd, &status) < 0) {
            log_event("I2C read error; retrying...");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int active_electrode = -1;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
