#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  30000   /* 30 ms */
#define MIN_CM      2.0f
#define MAX_CM      400.0f
#define SOUND_SPEED 0.0343f /* cm/us at 20 C */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* Wait for echo to reach the requested value, returning 0 on success, -1 on timeout. */
static int wait_for_echo(struct gpiod_line *echo, int value, long timeout_us)
{
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (program_running) {
        int v = gpiod_line_get_value(echo);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
