/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   TRIG -> GPIO17 (physical pin 11)
 *   ECHO -> GPIO18 (physical pin 12) via 1 kOhm/2 kOhm voltage divider
 *           (5 V echo -> 3.3 V Pi input)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN      17
#define ECHO_PIN      18

#define TRIGGER_US    10          /* 10 microsecond trigger pulse            */
#define SAMPLE_PERIOD 1000000     /* 1 second between measurements           */
#define ECHO_TIMEOUT  100000      /* 100 ms max echo wait                    */
#define MIN_PULSE_US  58          /* ~1 cm (28 mm) minimum valid pulse       */
#define MAX_PULSE_US  25000       /* ~4 m  (4032 mm) maximum valid pulse     */
#define SOUND_SPEED   343.0       /* m/s at ~20 C                            */
#define LOG_FILE      "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                            */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_new_data   = false;

static FILE *g_log = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo ISR callback                                                   */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_end_tick   = tick;
        g_echo_seen  = true;
        g_new_data   = true;
    }
    /* level == 2 (TIMEOUT) is ignored */
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Compute (b - a) modulo 2^32, handling 32-bit tick wraparound.
 * Returns the number of microseconds between two pigpio ticks.
 */
static uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

static void trigger_sensor(void)
{
    /* Ensure trigger starts low */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(5);

    /* 10 us trigger pulse */
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_US);
    gpioWrite(TRIG_PIN, 0);
}

static void log_distance(double distance_m)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log, "%s, Distance: %.2f m\n", timestamp, distance_m);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with trigger low */
    gpioWrite(TRIG_PIN, 0);

    /* ---- ISR registration ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, ECHO_TIMEOUT,
                         echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("Error opening log file");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, ECHO_TIMEOUT, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error setting up signal handlers");
        fclose(g_log);
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, ECHO_TIMEOUT, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: GPIO%d | ECHO: GPIO%d | Log: %s\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && g_running) {
            if (tick_diff(wait_start, gpioTick()) > ECHO_TIMEOUT) {
                break;
            }
            gpioDelay(100);  /* 100 us sleep to avoid busy-waiting */
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout (no object detected).\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        if (!g_new_data) {
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        uint32_t pulse_us = tick_diff(g_start_tick, g_end_tick);
        g_new_data = false;

        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: out-of-range pulse %u us (valid %u-%u us).\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
        double distance_m = (double)pulse_us * SOUND_SPEED / 2.0 / 1.0e6;
        log_distance(distance_m);

        gpioDelay(SAMPLE_PERIOD);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, ECHO_TIMEOUT, NULL, NULL);
    gpioWrite(TRIG_PIN, 0);
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

