                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
        double distance_m = (double)pulse_us * SOUND_SPEED / 2.0 / 1.0e6;
        log_distance(distance_m);

        gpioDelay(SAMPLE_PERIOD);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, ECHO_TIMEOUT, NULL, NULL);
    gpioWrite(TRIG_PIN, 0);
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

