#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define GATE_GPIO      24
#define DIST_THRESHOLD 20.0f   /* cm */
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses */
#define REG_MODEL_ID       0x010F
#define REG_RANGING_MODE   0x0021
#define REG_SYSTEM_START   0x0015
#define REG_RESULT_DIST_HI 0x0089
#define REG_RESULT_DIST_LO 0x008A

#define EXPECTED_MODEL_ID  0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_file) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "[%s] %s\n", ts, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                        */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint16_t reg, uint8_t val)
{
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)val };
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_byte(int handle, uint16_t reg, uint8_t *out)
{
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1)
        return -1;
    *out = (uint8_t)data[0];
    return 0;
}

static int i2c_read_word(int handle, uint16_t reg, uint16_t *out)
{
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X sensor                                                     */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;
    if (i2c_read_byte(handle, REG_MODEL_ID, &model_id) < 0) {
        log_event("Error: failed to read model ID register.");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        char msg[64];
        snprintf(msg, sizeof(msg),
                 "Error: unexpected model ID 0x%02X (expected 0x%02X).",
                 model_id, EXPECTED_MODEL_ID);
        log_event(msg);
        return -1;
    }

    /* Short ranging mode */
    if (i2c_write_byte(handle, REG_RANGING_MODE, 0x00) < 0) {
        log_event("Error: failed to set ranging mode.");
        return -1;
    }

    /* Start continuous ranging */
    if (i2c_write_byte(handle, REG_SYSTEM_START, 0x01) < 0) {
        log_event("Error: failed to start ranging.");
        return -1;
    }

    log_event("VL53L1X initialised successfully.");
    return 0;
}

static int vl53l1x_read_distance_cm(int handle, float *distance_cm)
{
    uint16_t raw = 0;
    if (i2c_read_word(handle, REG_RESULT_DIST_HI, &raw) < 0) {
        log_event("Error: failed to read distance register.");
        return -1;
    }
    *distance_cm = (float)raw / 10.0f;  /* mm -> cm */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gate control                                                       */
/* ------------------------------------------------------------------ */
static void gate_set(int state)
{
    if (gpioWrite(GATE_GPIO, state) < 0) {
        log_event("Error: failed to write GPIO24.");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Gate %s", state ? "OPEN" : "CLOSED");
    log_event(msg);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_event("Shutdown complete.");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("gate_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: i2cOpen failed (%d).", g_i2c_handle);
        log_event(msg);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure gate GPIO */
    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) < 0) {
        log_event("Error: failed to set GPIO24 as output.");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);  /* start closed */

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        log_event("Error: VL53L1X initialisation failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate control system started.");

    int gate_open = 0;

    while (g_running) {
        float distance = 0.0f;
        if (vl53l1x_read_distance_cm(g_i2c_handle, &distance) < 0) {
            /* I2C error already logged; keep gate in safe state */
            if (gate_open) {
                gate_set(0);
                gate_open = 0;
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
        log_event(msg);

        if (distance < DIST_THRESHOLD && !gate_open) {
            gate_set(1);
            gate_open = 1;
        } else if (distance >= DIST_THRESHOLD && gate_open) {
            gate_set(0);
            gate_open = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    if (gate_open)
        gate_set(0);
    cleanup();
    return EXIT_SUCCESS;
}

