        char msg[128];
        snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
        log_event(msg);

        if (distance < DIST_THRESHOLD && !gate_open) {
            gate_set(1);
            gate_open = 1;
        } else if (distance >= DIST_THRESHOLD && gate_open) {
            gate_set(0);
            gate_open = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    if (gate_open)
        gate_set(0);
    cleanup();
    return EXIT_SUCCESS;
}

