#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        18

#define SPEED_OF_SOUND   34300.0f   /* cm/s */
#define MIN_DISTANCE     2.0f       /* cm  */
#define MAX_DISTANCE     400.0f     /* cm  */
#define ECHO_TIMEOUT_US  30000      /* 30 ms */
#define SAMPLE_PERIOD_US 100000     /* 100 ms */
#define MOVING_AVG_SIZE  5
#define DEFAULT_SERVO_ANGLE 90

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_start = 0;
static volatile uint32_t     g_pulse_end   = 0;
static volatile int          g_echo_seen   = 0;

static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio callback thread)               */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_pulse_start = tick;
        g_echo_seen   = 0;
    } else if (level == 0) {
        g_pulse_end   = tick;
        g_echo_seen   = 1;
    }
}

/* ------------------------------------------------------------------ */
/* Measure distance with HC-SR04                                       */
/* Returns distance in cm, or -1.0 on timeout / out-of-range            */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    g_echo_seen = 0;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo with timeout */
    uint32_t start_wait = gpioTick();
    while (!g_echo_seen) {
        if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
            return -1.0f;  /* no echo received */
        }
        gpioDelay(100);
    }

    uint32_t pulse_width = g_pulse_end - g_pulse_start;  /* handles 32-bit wrap */
    float distance = (pulse_width / 1000000.0f) * SPEED_OF_SOUND / 2.0f;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0f;  /* out of valid range */
    }
    return distance;
}

/* ------------------------------------------------------------------ */
/* Moving average filter                                               */
/* ------------------------------------------------------------------ */
static float moving_average(float new_value, float *buffer, int size, int *index)
{
    buffer[*index] = new_value;
    *index = (*index + 1) % size;

    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / (float)size;
}

/* ------------------------------------------------------------------ */
/* Non-linear distance -> servo angle mapping                          */
/* ------------------------------------------------------------------ */
static int distance_to_angle(float distance)
{
    if (distance < 0.0f) {
        return DEFAULT_SERVO_ANGLE;
    }

    /* Logarithmic mapping: 2 cm -> 0 deg, 400 cm -> 180 deg */
    float log_min = log10f(MIN_DISTANCE);
    float log_max = log10f(MAX_DISTANCE);
    float log_d   = log10f(distance);

    float frac = (log_d - log_min) / (log_max - log_min);
    if (frac < 0.0f) frac = 0.0f;
    if (frac > 1.0f) frac = 1.0f;

    return (int)(frac * 180.0f);
}

/* ------------------------------------------------------------------ */
/* Servo angle -> pulse width                                          */
/* ------------------------------------------------------------------ */
static int angle_to_pulse_width(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;
    return 500 + (int)((float)angle * 2000.0f / 180.0f);
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                     */
/* ------------------------------------------------------------------ */
static void log_data(float distance, int servo_angle)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);  /* stop servo PWM */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);

    /* Register echo alert callback */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("distance_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open distance_log.csv\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "timestamp,distance_cm,servo_angle\n");
    fflush(g_log_file);

    /* Register signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Moving average buffer */
    float distance_buffer[MOVING_AVG_SIZE];
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        distance_buffer[i] = 0.0f;
    }
    int buffer_index = 0;

    /* Main loop */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: invalid reading, defaulting servo\n");
            log_data(-1.0f, DEFAULT_SERVO_ANGLE);
            if (gpioServo(SERVO_PIN, angle_to_pulse_width(DEFAULT_SERVO_ANGLE)) < 0) {
                fprintf(stderr, "Error: gpioServo failed\n");
            }
        } else {
            float avg_distance = moving_average(distance, distance_buffer,
                                                 MOVING_AVG_SIZE, &buffer_index);
            int angle = distance_to_angle(avg_distance);
            int pulse = angle_to_pulse_width(angle);

            if (gpioServo(SERVO_PIN, pulse) < 0) {
                fprintf(stderr, "Error: gpioServo failed\n");
            }
            log_data(avg_distance, angle);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

