/*
 * VL53L1X Time-of-Flight Distance Sensor - Warning LED
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Warning LED -> GPIO17 (with appropriate series resistor)
 *
 * Build:  gcc -Wall -O2 -o vl53l1x_warn vl53l1x_warn.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_warn
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define WARNING_LED_GPIO     17
#define DISTANCE_THRESHOLD   200          /* mm */
#define BUFFER_SIZE          10
#define SAMPLE_PERIOD_US     50000        /* 50 ms */

/* ---- VL53L1X register addresses (16-bit, big-endian on the bus) ---- */
#define VL53L1X_REG_SOFT_RESET                 0x0003
#define VL53L1X_REG_SYSTEM_MODE_START          0x0007
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR     0x000B
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS    0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS        0x0089
#define VL53L1X_REG_RESULT_DISTANCE            0x0096
#define VL53L1X_REG_SYSTEM_THRESH_HIGH         0x0014
#define VL53L1X_REG_SYSTEM_THRESH_LOW          0x0016
#define VL53L1X_REG_SYSTEM_CONFIG_RANGE        0x0018
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT    0x001E
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG    0x0014
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR     0x0015
#define VL53L1X_REG_SYSTEM_GROUPED_PARAM_HOLD  0x0017
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG        0x0031
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG     0x0030
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT    0x001E
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x000A
#define VL53L1X_REG_GPIO_HV_MUX_CTRL           0x0084
#define VL53L1X_REG_GPIO_TIO_HV_STATUS         0x0085
#define VL53L1X_REG_GPIO_TIO_HV_STATUS         0x0085
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS   0x0001

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_pigpio_inited = false;

/* ---- Circular buffer ---- */
typedef struct {
    int    data[BUFFER_SIZE];
    int    head;
    int    count;
} CircularBuffer;

static CircularBuffer g_buffer;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void buffer_init(CircularBuffer *cb);
static void buffer_add(CircularBuffer *cb, int value);
static int  buffer_get_latest(CircularBuffer *cb);
static int  read_distance(int handle);
static int  init_vl53l1x(int handle);
static void cleanup(void);

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void buffer_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, int value)
{
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static int buffer_get_latest(CircularBuffer *cb)
{
    if (cb->count == 0)
        return -1;
    int idx = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->data[idx];
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address + 8-bit value over I2C.             */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed (reg 0x%04X, val 0x%02X)\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read an 8-bit value from a 16-bit register address.                 */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed (reg 0x%04X)\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)out, 1) != 1) {
        fprintf(stderr, "I2C read failed (reg 0x%04X)\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register address.                 */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed (reg 0x%04X)\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read failed (reg 0x%04X)\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X sensor using the recommended ST sequence.    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_vl53l1x(int handle)
{
    uint8_t  id_low, id_high;
    uint16_t model_id;

    /* ---- Verify device identity ---- */
    if (vl53l1x_read_reg8(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, &id_low) != 0)
        return -1;
    if (vl53l1x_read_reg8(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS + 1, &id_high) != 0)
        return -1;
    model_id = ((uint16_t)id_high << 8) | id_low;
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID 0x%04X (expected 0xEA)\n", model_id);
        return -1;
    }

    /* ---- Soft reset ---- */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* ---- Clear any pending interrupts ---- */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    /* ---- Set GPIO interrupt polarity to active low ---- */
