        return -1;
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_THRESH_LOW, 0x00) != 0)
        return -1;

    /* ---- Set range configuration ---- */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x00) != 0)
        return -1;

    /* ---- Set sequence configuration ---- */
