        return -1;
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT + 1, 0x32) != 0)
        return -1;

    /* ---- Start ranging ---- */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

