        fprintf(stderr, "Error reading PROX_LOW: %d\n", low);
        return -1;
    }
    return (high << 8) | low;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    int prox = read_proximity(i2c_handle);
    if (prox >= 0) {
        pthread_mutex_lock(&data_mutex);
        proximity_value = prox;
        interrupt_flag = 1;
        pthread_mutex_unlock(&data_mutex);
    }
}

static void log_data(int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, (proximity <= threshold) ? "SAFE" : "ALERT");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    int i2c_address = SI1102_I2C_ADDR;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = (int)strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR\n");
        cleanup();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Proximity monitoring started. Threshold: %d\n", threshold);
    while (running) {
        pthread_mutex_lock(&data_mutex);
        if (interrupt_flag) {
            int prox = proximity_value;
            interrupt_flag = 0;
            pthread_mutex_unlock(&data_mutex);
            log_data(prox);
        } else {
            pthread_mutex_unlock(&data_mutex);
        }
        gpioDelay(100000);
    }
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

