#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SPEAKER_PIN 18

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 200.0
#define MIN_FREQUENCY   200.0
#define MAX_FREQUENCY   2000.0
#define DUTY_CYCLE      500000  /* 50% of 1,000,000 */
#define TRIGGER_US      10
#define TIMEOUT_US      200000  /* 200 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static double measure_distance(void) {
    /* Issue a 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Warning: Echo start timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > TIMEOUT_US) {
            fprintf(stderr, "Warning: Echo end timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    /* Speed of sound ~343 m/s => 0.0343 cm/us */
    return (double)pulse_us * 0.0343;
}

/*
 * Map distance (cm) to frequency (Hz).
 * Logarithmic scaling: f = 200 * exp(d / 50)
 */
static double distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    double freq = 200.0 * exp(distance / 50.0);
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    return freq;
}

/*
 * Set speaker PWM frequency and 50% duty cycle.
 * Returns 0 on success, -1 on error.
 */
static int set_frequency(double frequency) {
    if (frequency < 0.0) {
        fprintf(stderr, "Error: Invalid frequency %.2f Hz\n", frequency);
        return -1;
    }
    if (gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for %.2f Hz\n", frequency);
        return -1;
    }
    if (gpioPWM(SPEAKER_PIN, DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SPEAKER_PIN) failed\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); /* 100 ms settle */

    double current_frequency = MIN_FREQUENCY;
    if (set_frequency(current_frequency) < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance > 0.0) {
            current_frequency = distance_to_frequency(distance);
            if (set_frequency(current_frequency) < 0) {
                /* Non-fatal: keep previous tone */
            }
        }
        /* Else: keep previous frequency (timeout / out-of-range) */

        gpioDelay(50000); /* 50 ms loop period */
    }

    /* Clean shutdown */
    gpioPWM(SPEAKER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return 0;
}

