#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM 5.0f
#define MAX_DISTANCE_CM 50.0f
#define MIN_FREQUENCY   200
#define MAX_FREQUENCY   2000
#define TIMEOUT_US      100000   /* 100 ms */
#define LOOP_DELAY_US   10000    /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on GPIO error.
 */
static float measure_distance(void) {
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -2.0f;
    gpioDelay(2);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -2.0f;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -2.0f;

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) return -1.0f;
    }
    uint32_t pulse_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - pulse_start) > TIMEOUT_US) return -1.0f;
    }
    uint32_t pulse_end = gpioTick();

    uint32_t pulse_width = pulse_end - pulse_start;
    /* speed of sound ~343 m/s => 0.0343 cm/us */
    return (float)pulse_width * 0.0343f;
}

static int set_buzzer_frequency(int freq) {
    if (freq < 0) freq = 0;
    /* gpioHardwarePWM uses hardware PWM on GPIO18; freq 0 disables */
    return gpioHardwarePWM(BUZZER_PIN, freq, 500000);
}

static int map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    float frac = (MAX_DISTANCE_CM - distance) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int freq = MIN_FREQUENCY +
               (int)(frac * (MAX_FREQUENCY - MIN_FREQUENCY));
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    return freq;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable pull-down on echo pin to avoid floating when sensor is absent */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: could not set pull-down on GPIO%d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); /* 100 ms settle */

    float last_valid_distance = MAX_DISTANCE_CM;
    int last_valid_freq = map_distance_to_frequency(last_valid_distance);

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            if (distance == -1.0f) {
                fprintf(stderr, "Warning: echo timeout (sensor absent or out of range).\n");
            } else {
                fprintf(stderr, "Error: GPIO read/write failure.\n");
            }
            /* Reuse last valid frequency for continuity */
            if (set_buzzer_frequency(last_valid_freq) < 0) {
                fprintf(stderr, "Error: gpioHardwarePWM failed.\n");
            }
        } else {
            int freq = map_distance_to_frequency(distance);
            if (set_buzzer_frequency(freq) < 0) {
                fprintf(stderr, "Error: gpioHardwarePWM failed.\n");
            } else {
                last_valid_distance = distance;
                last_valid_freq = freq;
                printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, freq);
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    set_buzzer_frequency(0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

