#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND 29.1f   /* cm/us */
#define MIN_DISTANCE   2.0f    /* cm */
#define MAX_DISTANCE   400.0f  /* cm */
#define CLOSE_THRESHOLD 10.0f  /* cm */
#define TIMEOUT_US     50000   /* 50 ms */
#define LOOP_DELAY_US  500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static float measure_distance(void)
{
    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }
    gpioDelay(2);

    /* Send 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    /* Measure echo pulse width with timeout */
    uint32_t start_tick = gpioTick();
    uint32_t timeout_tick = start_tick + TIMEOUT_US;

    /* Wait for echo to go high */
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() > timeout_tick) {
            return -1.0f; /* timeout waiting for echo start */
        }
    }

    uint32_t echo_start = gpioTick();

    /* Wait for echo to go low */
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() > timeout_tick) {
