            printf("Invalid reading: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < CLOSE_THRESHOLD) {
                printf(" - Too close!");
            }
            printf("\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

