#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_PIN 8

#define REG_MEAS_TRIGGER 0x00
#define REG_MEAS_MODE 0x01
#define REG_RANGE 0x02
#define REG_DIST_LOW 0x0C
#define REG_DIST_HIGH 0x0D

#define MEAS_MODE_CONTINUOUS 0x01
#define RANGE_5M 0x00
#define TRIGGER_MEASURE 0x01

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg | 0x80), (char)value };
    char rx[2] = { 0, 0 };
    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(CS_PIN, 1);
    if (ret != 2) {
        fprintf(stderr, "SPI write error for reg 0x%02X: ret=%d\n", reg, ret);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2] = { 0, 0 };
    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(CS_PIN, 1);
    if (ret != 2) {
        fprintf(stderr, "SPI read error for reg 0x%02X: ret=%d\n", reg, ret);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int init_sensor(void) {
    if (spi_write_reg(REG_MEAS_MODE, MEAS_MODE_CONTINUOUS) != 0) return -1;
    if (spi_write_reg(REG_RANGE, RANGE_5M) != 0) return -1;
    if (spi_write_reg(REG_MEAS_TRIGGER, TRIGGER_MEASURE) != 0) return -1;
    return 0;
}

static int read_distance(uint16_t *distance_mm) {
    uint8_t low, high;
    if (spi_read_reg(REG_DIST_LOW, &low) != 0) return -1;
    if (spi_read_reg(REG_DIST_HIGH, &high) != 0) return -1;
    *distance_mm = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_distance(uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed (sensor absent or SPI bus error)\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open distance_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 distance measurement started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            if (distance >= 200 && distance <= 5000) {
                log_distance(distance);
                printf("Distance: %u mm\n", distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %u mm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

