static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA1, &hi) < 0)
        return -1;
    *als_visible = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_data(FILE *fp, uint16_t als_visible)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", ts, als_visible) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", SI1175_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    long pos = ftell(fp);
    if (pos == 0) {
        if (fprintf(fp, "timestamp,als_visible\n") < 0 || fflush(fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    printf("Si1175 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_visible;
        if (read_als_visible(fd, &als_visible) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            if (log_data(fp, als_visible) < 0) {
                fprintf(stderr, "Logging error; continuing.\n");
            } else {
                printf("ALS Visible: %u\n", als_visible);
            }
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    if (fclose(fp) != 0)
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    if (close(fd) < 0)
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
    return EXIT_SUCCESS;
}

