}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "Warning: I2C read of register 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0)
            return 0;
        fprintf(stderr, "Warning: I2C write to register 0x%02X failed (attempt %d/%d, rc=%d)\n",
