    if (read_register(handle, SI1120_REG_ALS_HB, &als_hb) != 0)
        return -1;
    if (read_register(handle, SI1120_REG_PS1_LB, &ps1_lb) != 0)
        return -1;
    if (read_register(handle, SI1120_REG_PS1_HB, &ps1_hb) != 0)
        return -1;

    *als = (uint16_t)((als_hb << 8) | als_lb);
    *ps1 = (uint16_t)((ps1_hb << 8) | ps1_lb);
    return 0;
}

