        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian register pair (low byte at reg, high at reg+1) */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_sensor(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read part ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Unexpected part ID 0x%02X (expected 0x82).\n", part_id);
        return -1;
    }
    printf("Si1182 detected (part ID 0x%02X).\n", part_id);

    /* Configure measurement rate: 0x07 = 1 sample per 100 ms */
    if (i2c_write_reg8(fd, REG_MEAS_RATE, 0x07) < 0) {
        fprintf(stderr, "Failed to set measurement rate.\n");
        return -1;
    }
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        uint16_t als_raw, ps_raw;
        if (i2c_read_reg16(g_i2c_fd, REG_ALS_DATA, &als_raw) < 0 ||
            i2c_read_reg16(g_i2c_fd, REG_PS_DATA, &ps_raw) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        float lux = (float)als_raw * 0.1f;
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        fprintf(g_log_fp, "%s,%.1f,%u\n", ts, lux, ps_raw);
        fflush(g_log_fp);
        printf("%s, Lux: %.1f, Proximity: %u\n", ts, lux, ps_raw);

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

