#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27
#define DISTANCE_THRESHOLD 20.0
#define SPEED_OF_SOUND 0.0343
#define TRIGGER_PULSE_US 10

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_state = 0;
static volatile int      running    = 1;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        end_tick = tick;
        echo_state = 2;
    }
}

static void trigger_pulse(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
    }
}

static double calculate_distance(uint32_t start, uint32_t end) {
    uint32_t diff = end - start;
    return (double)diff * SPEED_OF_SOUND / 2.0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(echo, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(buzzer, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(buzzer, 0) initial state failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_state = 0;
        start_tick = 0;
        end_tick   = 0;

        trigger_pulse();

        int timeout = 0;
        while (echo_state == 0 && running && timeout < 1000) {
            gpioDelay(1000);
            timeout++;
        }

        if (!running) break;

        if (echo_state == 0) {
            fprintf(stderr, "Warning: echo timeout (no response)\n");
        } else if (echo_state == 1) {
            fprintf(stderr, "Warning: echo incomplete (only rising edge)\n");
        } else {
            double distance = calculate_distance(start_tick, end_tick);
            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                if (gpioWrite(BUZZER_PIN, 1) != 0) {
                    fprintf(stderr, "Error: gpioWrite(buzzer, 1) failed\n");
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) != 0) {
                    fprintf(stderr, "Error: gpioWrite(buzzer, 0) failed\n");
                }
            }
        }

        gpioDelay(1000000);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

