    return (double)diff * SPEED_OF_SOUND / 2.0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(echo, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(buzzer, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(buzzer, 0) initial state failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_state = 0;
        start_tick = 0;
        end_tick   = 0;

        trigger_pulse();

        int timeout = 0;
        while (echo_state == 0 && running && timeout < 1000) {
            gpioDelay(1000);
            timeout++;
        }

        if (!running) break;

        if (echo_state == 0) {
            fprintf(stderr, "Warning: echo timeout (no response)\n");
        } else if (echo_state == 1) {
            fprintf(stderr, "Warning: echo incomplete (only rising edge)\n");
        } else {
            double distance = calculate_distance(start_tick, end_tick);
            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                if (gpioWrite(BUZZER_PIN, 1) != 0) {
                    fprintf(stderr, "Error: gpioWrite(buzzer, 1) failed\n");
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) != 0) {
                    fprintf(stderr, "Error: gpioWrite(buzzer, 0) failed\n");
                }
            }
        }

        gpioDelay(1000000);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

