#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 30000
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_MID_PULSE 1500
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 20.0
#define MID_DISTANCE 110.0

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

double measure_distance(void) {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        start_tick = gpioTick();
        if (++timeout > TIMEOUT_US) return -1.0;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (++timeout > TIMEOUT_US) return -1.0;
        gpioDelay(1);
    }

    uint32_t diff = end_tick - start_tick;
    return (diff * SPEED_OF_SOUND) / 2000000.0;
}

void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / 180;
    gpioServo(SERVO_PIN, pulse);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor error: timeout or out of range\n");
            gpioDelay(100000);
            continue;
        }

        if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
        if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;

        int angle = (int)(((distance - MIN_DISTANCE) / (MID_DISTANCE - MIN_DISTANCE)) * 90.0);
        if (angle < 0) angle = 0;
        if (angle > 90) angle = 90;

        set_servo_angle(angle);
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

