#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define MIN_DISTANCE_CM  20.0
#define MAX_DISTANCE_CM  200.0
#define MIN_ANGLE_DEG    0
#define MAX_ANGLE_DEG    180
#define SERVO_MIN_US     500
#define SERVO_MAX_US     2500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000
#define LOOP_DELAY_US    100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger low\n");
        return -1;
    }
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;

    trigger_sensor();

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_duration = end_tick - start_tick;
    return (double)pulse_duration * 0.0343 / 2.0;
}

static int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE_CM) return MIN_ANGLE_DEG;
    if (distance > MAX_DISTANCE_CM) return MAX_ANGLE_DEG;
    return (int)(((distance - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) *
                 (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
}

static int angle_to_pulse_us(int angle) {
    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;
    return SERVO_MIN_US +
           (int)(((double)(angle - MIN_ANGLE_DEG) /
                  (MAX_ANGLE_DEG - MIN_ANGLE_DEG)) *
                 (SERVO_MAX_US - SERVO_MIN_US));
}

static void set_servo_angle(int angle) {
    int pulse = angle_to_pulse_us(angle);
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "Warning: gpioServo failed for pulse %d\n", pulse);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Error: sensor timeout or out of range\n");
            set_servo_angle(MAX_ANGLE_DEG);
        } else {
            int angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

