#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI7005_ADDR        0x40
#define SI7005_TEMP_REG    0x01
#define SI7005_HUM_REG     0x02
#define SI7005_CONFIG_REG  0x03

#define I2C_BUS            1
#define SAMPLE_INTERVAL_S  2
#define CONFIG_DELAY_US    10000
#define READ_DELAY_US      10000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed\n", reg);
        return -1;
    }

    gpioDelay(READ_DELAY_US);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice(0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int configure_sensor(int handle) {
    /*
     * CONFIG register (0x03):
     *   Bit 0 = HEATER (0 = disable)
     *   Bit 1 = TEMP_EN (1 = enable internal temp sensor)
     *   Bit 2 = HUM_EN (1 = enable humidity sensor)
     *   Bits 3-7 = reserved / 0
     * Value = 0x06
     */
    if (i2cWriteByteData(handle, SI7005_CONFIG_REG, 0x06) < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(CONFIG) failed\n");
        return -1;
    }
    gpioDelay(CONFIG_DELAY_US);
    return 0;
}

static void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
    fflush(stdout);
}

int main(void) {
    int handle = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7005_ADDR, handle);
        goto cleanup_gpio;
    }

    if (configure_sensor(handle) < 0) {
        fprintf(stderr, "Error: sensor configuration failed\n");
        goto cleanup_i2c;
    }

    while (g_running) {
        uint16_t raw_temp = 0, raw_hum = 0;

        if (read_register(handle, SI7005_TEMP_REG, &raw_temp) < 0) {
            fprintf(stderr, "Warning: temperature read failed, re-opening I2C\n");
            i2cClose(handle);
            handle = -1;
            gpioDelay(100000);
            handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (handle < 0) {
                fprintf(stderr, "Error: re-open failed: %d\n", handle);
                goto cleanup_gpio;
            }
            if (configure_sensor(handle) < 0) {
                fprintf(stderr, "Error: re-config failed\n");
                goto cleanup_i2c;
            }
            continue;
        }

        if (read_register(handle, SI7005_HUM_REG, &raw_hum) < 0) {
            fprintf(stderr, "Warning: humidity read failed, re-opening I2C\n");
            i2cClose(handle);
            handle = -1;
            gpioDelay(100000);
            handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (handle < 0) {
                fprintf(stderr, "Error: re-open failed: %d\n", handle);
                goto cleanup_gpio;
            }
            if (configure_sensor(handle) < 0) {
                fprintf(stderr, "Error: re-config failed\n");
                goto cleanup_i2c;
            }
            continue;
        }

        float temperature = (175.72f * (float)raw_temp) / 65536.0f - 46.85f;
        float humidity    = (125.0f  * (float)raw_hum)  / 65536.0f - 6.0f;

        log_data(temperature, humidity);

        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0) {
        i2cClose(handle);
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

