#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPU-6050 register map (per Invensense MPU-6050 datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_SMPLRT_DIV  0x19
#define MPU6050_CONFIG      0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level register helpers ---- */
static int reg_write(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, val);
        return -1;
    }
    return 0;
}

static int reg_read(int handle, uint8_t reg, uint8_t *val)
{
    int b = i2cReadByteData(handle, reg);
    if (b < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *val = (uint8_t)b;
    return 0;
}

/* ---- Sensor configuration ---- */
static int configure_mpu6050(int handle)
{
    uint8_t who;

    /* Verify device identity */
    if (reg_read(handle, MPU6050_WHO_AM_I, &who) < 0)
        return -1;
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr,
                "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    printf("[INFO] MPU-6050 detected (WHO_AM_I = 0x%02X)\n", who);

    /* Reset device */
    if (reg_write(handle, MPU6050_PWR_MGMT_1, 0x80) < 0)
        return -1;
    gpioDelay(100000); /* 100 ms settle after reset */

    /* Wake up: clear sleep bit, use internal 8 MHz oscillator */
    if (reg_write(handle, MPU6050_PWR_MGMT_1, 0x00) < 0)
        return -1;
