    if (reg_write(handle, MPU6050_GYRO_CONFIG, 0x00) < 0)
        return -1;

    /* Accel: ±2 g (AFS_SEL = 0) */
    if (reg_write(handle, MPU6050_ACCEL_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

