#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define LOG_FILE "pressure_log.csv"
#define POLL_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 1000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SDP810_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    uint8_t cmd[2] = {0x36, 0x08};
    int ret = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (ret != 0) {
        fprintf(stderr, "Error sending start measurement command: %d\n", ret);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    uint8_t buffer[9];
    int ret = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (ret != 9) {
        fprintf(stderr, "Error reading sensor data: expected 9 bytes, got %d\n", ret);
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buffer[6], 2) != buffer[8]) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    int16_t scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (start_measurement() != 0) {
        cleanup();
        return 1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure, temperature;
    while (!terminate) {
        if (read_sensor_data(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

