/* CRC-8 polynomial 0x31, init 0xFF — Sensirion convention */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Trigger continuous measurement and read 6 bytes:
 *   [pressure_msb, pressure_lsb, pressure_crc,
 *    temp_msb,     temp_lsb,     temp_crc]
 * Returns 0 on success, -1 on failure.
 */
static int read_sdp31(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = { 0x21, 0x96 };
    uint8_t buf[6];
    int rc;

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(handle, (char *)cmd, 2);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d] i2cWriteDevice failed: %d\n", attempt, rc);
            gpioDelay(attempt * 1000); /* 1 ms, 2 ms, 3 ms backoff */
            continue;
        }

        gpioDelay(2000); /* 2 ms conversion time */

        rc = i2cReadDevice(handle, (char *)buf, 6);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d] i2cReadDevice failed: %d\n", attempt, rc);
            gpioDelay(attempt * 1000);
            continue;
        }
        if (rc != 6) {
            fprintf(stderr, "[attempt %d] short read: %d bytes\n", attempt, rc);
            gpioDelay(attempt * 1000);
            continue;
        }

        /* CRC validation */
        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] pressure CRC mismatch\n", attempt);
            gpioDelay(attempt * 1000);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[attempt %d] temperature CRC mismatch\n", attempt);
            gpioDelay(attempt * 1000);
            continue;
        }

        int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

        *pressure    = (float)raw_p / 60.0f;
        *temperature = (float)raw_t / 200.0f;
