        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", handle);
