                cmd, pigpio_error(rc));
        return -1;
    }

    /* No Hold Master mode: sensor holds the bus until data is ready. */
    gpioDelay(MEAS_TIMEOUT_MS * 1000);   /* microseconds */

    rc = i2cReadDevice(g_i2c_handle, data, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(0x%02X) failed: %s\n",
                cmd, pigpio_error(rc));
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "[ERROR] Short read for 0x%02X: got %d bytes\n",
                cmd, rc);
        return -1;
    }

    *raw_out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_temperature(float *temp_c)
{
    uint16_t raw;
    if (read_measurement(CMD_TEMP_NOHOLD, &raw) != 0)
        return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_humidity(float *rh)
{
    uint16_t raw;
    if (read_measurement(CMD_HUM_NOHOLD, &raw) != 0)
        return -1;
    *rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%RH\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temp_c, rh);
    } else {
        fprintf(fp, "(timestamp error), Temperature: %.2f C, Humidity: %.2f %%RH\n",
                temp_c, rh);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "[WARN] fclose(%s): %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Si7015 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_S);

    /* ---- main loop ---- */
    while (g_running) {
        float temp_c = 0.0f, rh = 0.0f;
        int   ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_temperature(&temp_c) == 0 &&
                read_humidity(&rh) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000);  /* 100 ms back-off */
        }

        if (ok) {
            log_data(temp_c, rh);
            printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temp_c, rh);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed after %d attempts; aborting.\n",
                    MAX_RETRIES);
            break;
        }

        /* Sleep SAMPLE_PERIOD_S but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; ++s)
            sleep(1);
    }

    /* ---- cleanup ---- */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

