#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_PERIOD  100000  /* microseconds (100 ms) */
#define MEAS_DELAY     45000   /* microseconds (45 ms)  */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a 16-bit command to the SDP800 ---- */
static int sdp800_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Read 9 bytes and validate CRC for each word ---- */
static int sdp800_read_measurement(int fd, float *pressure, float *temperature)
{
    uint8_t raw[9];
    ssize_t n = read(fd, raw, sizeof(raw));
    if (n != (ssize_t)sizeof(raw)) {
        fprintf(stderr, "I2C read failed: expected 9 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* CRC checks: [0-1]=pressure, [2-3]=temperature, [4-5]=scale */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "CRC mismatch on scale-factor word\n");
        return -1;
    }

    int16_t raw_p = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_t = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t scale = (int16_t)((raw[6] << 8) | raw[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_p / (float)scale;
    *temperature = (float)raw_t / 200.0f - 45.0f;
    return 0;
}

/* ---- Log one row ---- */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append; write header if empty) */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    long pos = ftell(g_log_fp);
    if (pos == 0) {
        fprintf(g_log_fp, "timestamp,pressure_pa,temperature_c\n");
        fflush(g_log_fp);
    }

    /* Start continuous measurement */
    if (sdp800_write_cmd(g_i2c_fd, 0x362F) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(MEAS_DELAY);

    printf("SDP800 monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;
        if (sdp800_read_measurement(g_i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(g_log_fp, pressure, temperature) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

