/*
 * Raspberry Pi 4 Model B – Si7021 humidity/temperature monitor with fan control.
 *
 * Hardware:
 *   Si7021 on I2C bus 1, address 0x40
 *   Cooling fan on GPIO18 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7021_fan si7021_fan.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for GPIO/I2C access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SI7021_ADDR          0x40
#define FAN_GPIO             18
#define TEMP_THRESHOLD_HIGH  28.0f   /* °C – turn fan ON above this */
#define TEMP_THRESHOLD_LOW   27.0f   /* °C – turn fan OFF below this */
#define BUFFER_SIZE          60
#define SAMPLE_INTERVAL_S    2       /* seconds between readings */
#define MEASURE_DELAY_US     10000   /* 10 ms conversion wait */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000   /* 10 ms between retries */

/* Si7021 commands (Hold Master mode) */
#define CMD_MEASURE_TEMP     0xE3
#define CMD_MEASURE_HUM      0xE5

/* ------------------------------- Types ----------------------------------- */
typedef struct {
    time_t timestamp;
    float  temperature;   /* °C */
    float  humidity;      /* %RH */
} SensorData;

/* --------------------------- Global state -------------------------------- */
static int                  i2c_handle = -1;
static SensorData           sensor_buffer[BUFFER_SIZE];
static int                  buffer_index = 0;
static volatile sig_atomic_t running = 1;

/* --------------------------- Prototypes ---------------------------------- */
static int  init_i2c(void);
static int  read_sensor_data(float *temperature, float *humidity);
static void add_to_buffer(float temperature, float humidity);
static void print_buffer_entry(int index);
static void control_fan(float temperature);
static void signal_handler(int sig);
static void cleanup(void);

/* --------------------------- I2C helpers --------------------------------- */

/*
 * Open the I2C bus and verify the Si7021 is present by reading its
 * WHO_AM_I register (0xFA / 0x0F).
 */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, SI7021_ADDR, i2c_handle);
        return -1;
    }

    /*
     * Read the Si7021 WHO_AM_I register pair (0xFA 0x0F).
     * A correct device responds with 0x15 (Si7021) or 0x20 (Si7020).
     */
    char who_cmd[2] = { 0xFA, 0x0F };
    char who_buf[2] = { 0 };

    if (i2cWriteDevice(i2c_handle, who_cmd, 2) != 0) {
        fprintf(stderr, "[WARN] WHO_AM_I write failed – sensor may be absent\n");
    } else {
        if (i2cReadDevice(i2c_handle, who_buf, 2) != 2) {
            fprintf(stderr, "[WARN] WHO_AM_I read failed – sensor may be absent\n");
        } else {
            uint8_t id = (uint8_t)who_buf[0];
            if (id != 0x15 && id != 0x20) {
                fprintf(stderr,
                        "[WARN] WHO_AM_I = 0x%02X – unexpected, continuing\n", id);
            }
        }
    }

    return 0;
}

/*
 * Trigger a Hold Master measurement and read the 2-byte result.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor_data(float *temperature, float *humidity)
{
    char cmd;
    char data[2];
    int  raw_temp, raw_hum;
    int  retries;

    /* --- Temperature --- */
    cmd = CMD_MEASURE_TEMP;
    retries = MAX_RETRIES;
    while (retries-- > 0) {
        if (i2cWriteDevice(i2c_handle, &cmd, 1) == 0) {
            gpioDelay(MEASURE_DELAY_US);
            if (i2cReadDevice(i2c_handle, data, 2) == 2) {
                raw_temp = ((int)(uint8_t)data[0] << 8) | (uint8_t)data[1];
                *temperature = (175.72f * (float)raw_temp / 65536.0f) - 46.85f;
                break;
            }
        }
        fprintf(stderr, "[WARN] Temperature read failed (attempt %d/%d)\n",
                MAX_RETRIES - retries, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    if (retries < 0) {
        fprintf(stderr, "[ERROR] Temperature read failed after %d retries\n",
                MAX_RETRIES);
        return -1;
    }

    /* --- Humidity --- */
    cmd = CMD_MEASURE_HUM;
    retries = MAX_RETRIES;
    while (retries-- > 0) {
        if (i2cWriteDevice(i2c_handle, &cmd, 1) == 0) {
            gpioDelay(MEASURE_DELAY_US);
            if (i2cReadDevice(i2c_handle, data, 2) == 2) {
                raw_hum = ((int)(uint8_t)data[0] << 8) | (uint8_t)data[1];
                *humidity = (125.0f * (float)raw_hum / 65536.0f) - 6.0f;
                break;
            }
        }
        fprintf(stderr, "[WARN] Humidity read failed (attempt %d/%d)\n",
                MAX_RETRIES - retries, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    if (retries < 0) {
        fprintf(stderr, "[ERROR] Humidity read failed after %d retries\n",
                MAX_RETRIES);
        return -1;
    }

    /* Clamp humidity to a physically realistic range */
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

/* --------------------------- Circular buffer ----------------------------- */
static void add_to_buffer(float temperature, float humidity)
{
    sensor_buffer[buffer_index].timestamp   = time(NULL);
    sensor_buffer[buffer_index].temperature = temperature;
    sensor_buffer[buffer_index].humidity    = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
