    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%RH\n",
           ts, sensor_buffer[index].temperature,
           sensor_buffer[index].humidity);
}

/* --------------------------- Fan control --------------------------------- */
static void control_fan(float temperature)
{
    static bool fan_on = false;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("[FAN] Turning fan ON  (T=%.2f °C)\n", temperature);
        } else {
            fprintf(stderr, "[FAN] Failed to set GPIO%d high\n", FAN_GPIO);
        }
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("[FAN] Turning fan OFF (T=%.2f °C)\n", temperature);
        } else {
            fprintf(stderr, "[FAN] Failed to set GPIO%d low\n", FAN_GPIO);
        }
    }
}

/* --------------------------- Signal / cleanup ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    /* Ensure fan is off before terminating pigpio */
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    float temperature, humidity;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
