    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialisation failed\n");
        gpioWrite(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitor started.  Threshold ON > %.1f °C, OFF < %.1f °C\n",
           TEMP_THRESHOLD_HIGH, TEMP_THRESHOLD_LOW);
    printf("Press Ctrl+C to exit.\n\n");

