#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 5000000  /* 5 seconds */
#define MEASUREMENT_DELAY_US 1000000 /* 1 second after start */

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC  0x3F86
#define CMD_GET_DATA_READY 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Send a 16-bit command to the SCD40 */
static int scd40_send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit response from the SCD40 */
static int scd40_read_response(uint16_t *resp) {
    uint8_t buf[2];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadDevice failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "Error: short read for response (got %d bytes)\n", rc);
        return -1;
    }
    *resp = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Read a 9-byte measurement block and verify CRCs */
static int scd40_read_measurement(uint16_t *co2, float *temp, float *rh) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadDevice failed for measurement (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 9) {
        fprintf(stderr, "Error: short read for measurement (got %d bytes)\n", rc);
        return -1;
    }

    /* Verify CRC for each 2-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on humidity word\n");
        return -1;
    }

    uint16_t raw_co2 = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_temp = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t raw_rh = ((uint16_t)buf[6] << 8) | buf[7];

    *co2 = raw_co2;
    *temp = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *rh = 100.0f * (float)raw_rh / 65535.0f;
    return 0;
}

static int scd40_start_periodic(void) {
    if (scd40_send_command(CMD_START_PERIODIC) != 0)
        return -1;
    gpioDelay(MEASUREMENT_DELAY_US);
    return 0;
}

static int scd40_stop_periodic(void) {
    return scd40_send_command(CMD_STOP_PERIODIC);
}

static int scd40_data_ready(int *ready) {
    if (scd40_send_command(CMD_GET_DATA_READY) != 0)
        return -1;
    uint16_t resp;
    if (scd40_read_response(&resp) != 0)
        return -1;
    *ready = (resp == 1);
    return 0;
}

static int log_data(uint16_t co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (scd40_start_periodic() != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SCD40 periodic measurement started. Logging to %s every 5 s.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = 0;
        if (scd40_data_ready(&ready) != 0) {
            fprintf(stderr, "Warning: data-ready check failed, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (ready) {
            uint16_t co2;
            float temp, rh;
            if (scd40_read_measurement(&co2, &temp, &rh) == 0) {
                printf("CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temp, rh);
                if (log_data(co2, temp, rh) != 0) {
                    fprintf(stderr, "Warning: failed to log data\n");
                }
            } else {
                fprintf(stderr, "Warning: measurement read failed, retrying...\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (scd40_stop_periodic() != 0) {
        fprintf(stderr, "Warning: failed to stop periodic measurement\n");
    }
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    if (log_file)
        fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

