#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL_SEC 5

#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_GET_DATA_READY 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    return i2cWriteDevice(i2c_handle, (char *)buf, 2);
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int scd40_start_periodic(void) {
    return i2c_write_cmd(CMD_START_PERIODIC);
}

static int scd40_stop_periodic(void) {
    return i2c_write_cmd(CMD_STOP_PERIODIC);
}

static int scd40_get_data_ready(bool *ready) {
    if (i2c_write_cmd(CMD_GET_DATA_READY) < 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[3];
    if (i2c_read_bytes(buf, 3) != 3)
        return -1;
    if (crc8(buf, 2) != buf[2])
        return -1;
    *ready = (buf[0] & 0x01) != 0;
    return 0;
}

static int scd40_read_measurement(sensor_data_t *data) {
    if (i2c_write_cmd(CMD_READ_MEASUREMENT) < 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[9];
    if (i2c_read_bytes(buf, 9) != 9)
        return -1;
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2])
            return -1;
    }
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (float)((buf[3] << 8) | buf[4]) / 100.0f;
    data->humidity = (float)((buf[6] << 8) | buf[7]) / 100.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d) {
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_print(const circular_buffer_t *buf) {
    printf("--- Circular Buffer Contents (%d entries) ---\n", buf->count);
    int start = (buf->count < BUFFER_SIZE) ? 0 : buf->head;
    for (int i = 0; i < buf->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%d] CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               idx, buf->data[idx].co2, buf->data[idx].temperature, buf->data[idx].humidity);
    }
    printf("---------------------------------------------\n");
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_stop_periodic();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr 0x%02X).\n", SCD40_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (scd40_start_periodic() < 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    buffer_init(&buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to stop.\n");

    while (running) {
        bool ready = false;
        if (scd40_get_data_ready(&ready) < 0) {
            fprintf(stderr, "Warning: Failed to read data-ready status.\n");
            sleep(1);
            continue;
        }
        if (!ready) {
            sleep(1);
            continue;
        }

        sensor_data_t data;
        if (scd40_read_measurement(&data) < 0) {
            fprintf(stderr, "Warning: Failed to read measurement data.\n");
            sleep(1);
            continue;
        }

        buffer_add(&buffer, data);
        buffer_print(&buffer);

        if (data.co2 > CO2_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               data.co2, data.temperature, data.humidity);

        for (int i = 0; i < MEASUREMENT_INTERVAL_SEC && running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

