/*
 * Busy-wait for a GPIO edge with microsecond-level timing.
 * Returns 0 on success, -1 on timeout.
 */
static int wait_for_edge(int gpio, int target_level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (running) {
        if (gpioRead(gpio) == target_level) return 0;
        if ((gpioTick() - start) >= timeout_us) return -1;
    }
    return -1;
}

/*
 * Measure one complete TMP05 cycle: high pulse width (TH) and total width (TL).
 * Returns 0 on success, -1 on timeout/error.
 */
static int measure_pulse(int gpio, uint32_t *th, uint32_t *tl) {
    uint32_t t_low, t_high;

    /* Wait for line to go low (start of cycle) */
    if (wait_for_edge(gpio, 0, EDGE_TIMEOUT_US) != 0) return -1;
    t_low = gpioTick();

    /* Wait for line to go high (end of low pulse) */
    if (wait_for_edge(gpio, 1, EDGE_TIMEOUT_US) != 0) return -1;
    t_high = gpioTick();

    /* Wait for line to go low (end of cycle) */
    if (wait_for_edge(gpio, 0, EDGE_TIMEOUT_US) != 0) return -1;
    uint32_t t_cycle = gpioTick();

    *th = t_high - t_low;
    *tl = t_cycle - t_low;
    return 0;
}

static float convert_to_celsius(uint32_t th, uint32_t tl) {
    if (tl == 0) return -999.0f;
    float ratio = (float)th / (float)tl;
    return 4215.0f - (2143.0f * ratio);
}

static void log_temperature(float temp) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (temp < -40.0f || temp > 150.0f) {
        fprintf(log_file, "%s, ERROR: Temperature out of range: %.2f C\n", timestamp, temp);
    } else {
        fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temp);
    }
    fflush(log_file);
}

static void log_error(const char *msg) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, msg);
    fflush(log_file);
}

int main(void) {
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);  /* TMP05 idles high */

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature logger started. Press Ctrl+C to stop.\n");

    while (running) {
        uint32_t th = 0, tl = 0;

        if (measure_pulse(GPIO_PIN, &th, &tl) != 0) {
            consecutive_errors++;
            log_error("Timeout waiting for TMP05 edge");
        } else if (tl == 0) {
            consecutive_errors++;
            log_error("TL == 0, division by zero prevented");
        } else {
            consecutive_errors = 0;
            float temp = convert_to_celsius(th, tl);
            log_temperature(temp);
        }

        if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
            log_error("SENSOR MALFUNCTION: 3 consecutive errors");
            consecutive_errors = 0;
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

