#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x24, 0x00
#define MEASUREMENT_DELAY_US 15000
#define LOG_INTERVAL_S 5
#define MAX_RETRIES 3
#define RETRY_DELAY_S 1
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH_REP};
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            retries++;
            if (retries < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            retries++;
            if (retries < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            if (retries < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        uint16_t t_raw = (buf[0] << 8) | buf[1];
        uint16_t h_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *humidity = 100.0f * (float)h_raw / 65535.0f;

        if (*temperature < -40.0f || *temperature > 125.0f ||
            *humidity < 0.0f || *humidity > 100.0f) {
            fprintf(stderr, "Out-of-range reading: T=%.2f H=%.2f (attempt %d)\n",
                    *temperature, *humidity, retries + 1);
            retries++;
            if (retries < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "SHT35 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void simulate_greenhouse_effect(float *temperature, float *humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    double elapsed = (utc->tm_hour * 3600.0 + utc->tm_min * 60.0 + utc->tm_sec) / 3600.0;
    *temperature += 2.0f * sinf(elapsed * M_PI * 2.0 / 1.0);
    *humidity += 5.0f * sinf(elapsed * M_PI * 2.0 / 1.0);
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (isnan(temperature) || isnan(humidity)) {
        fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    }
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", SHT35_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_sht35(&temperature, &humidity) == 0) {
            simulate_greenhouse_effect(&temperature, &humidity);
            log_data(temperature, humidity);
        } else {
            log_data(NAN, NAN);
        }
        sleep(LOG_INTERVAL_S);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

