#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define CONVERSION_TIME_MS 45
#define LOG_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sdp810(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, MEASURE_CMD_MSB, MEASURE_CMD_LSB) < 0)
        return -1;

    usleep(CONVERSION_TIME_MS * 1000);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, 9) < 0)
        return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor = (data[6] << 8) | data[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("airflow.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float pressure, temperature;
        if (read_sdp810(i2c_fd, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed, retrying...\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

