#define MEASURE_DELAY  15000   /* microseconds (15 ms) */
#define SAMPLE_INTERVAL 5      /* seconds */
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8, polynomial 0x31, initial value 0xFF (Sensirion spec) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Returns 0 on success, -1 on error. */
static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (uint8_t)(CMD_MEASURE >> 8), (uint8_t)(CMD_MEASURE & 0xFF) };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (command 0x2400).\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (expected 6 bytes).\n");
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    int needs_header = 0;
    FILE *check = fopen(filename, "r");
    if (!check) {
        needs_header = 1;
