    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

