/*
 * Greenhouse monitor using Si7021 on Raspberry Pi Zero W
 * Uses Linux i2c-dev (no wiringPi dependency).
 *
 * Wiring:
 *   Si7021 VDD  -> 3V3 (Pin 1)
 *   Si7021 GND  -> GND (Pin 9)
 *   Si7021 SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   Si7021 SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build: gcc -O2 -Wall -o greenhouse greenhouse.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40

#define CMD_MEASURE_HUMIDITY_NO_HOLD  0xF5
#define CMD_MEASURE_TEMP_NO_HOLD     0xF3
#define CMD_READ_PREV_TEMP_HUMIDITY  0xE0
#define CMD_RESET                    0xFE

#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Si7021: poly 0x31, init 0x00, no final XOR)                  */
/* ------------------------------------------------------------------ */
static uint8_t si7021_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset the sensor                                                    */
/* ------------------------------------------------------------------ */
static int si7021_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000);  /* datasheet: wait >= 15 ms after reset */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a measurement with no-hold command                             */
/* Returns raw 16-bit value or -1 on error.                            */
/* ------------------------------------------------------------------ */
static int si7021_read_measurement(int fd, uint8_t cmd, int *raw_out)
{
    uint8_t buf[3];

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    /* Poll for data-ready (No Hold Master mode) */
    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 5) {
        if (i2c_read_bytes(fd, buf, 3) == 0) {
            if (si7021_crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "CRC mismatch on cmd 0x%02X\n", cmd);
                return -1;
            }
            *raw_out = ((int)buf[0] << 8) | buf[1];
            return 0;
        }
        usleep(5000);
    }

    fprintf(stderr, "Timeout waiting for measurement 0x%02X\n", cmd);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Conversions                                                         */
/* ------------------------------------------------------------------ */
static float raw_to_celsius(int raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(int raw)
{
    return (125.0f * (float)raw / 65536.0f) - 6.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    } else {
        fprintf(fp, "ERROR,%.2f,%.2f\n", temp, rh);
    }

    fclose(fp);
}

static void log_error(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,ERROR\n", ts);
    } else {
        fprintf(fp, "ERROR,ERROR,ERROR\n");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Reset sensor to known state */
    if (si7021_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X. Check wiring.\n",
                SI7021_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int raw_h = 0, raw_t = 0;
        int ok = 1;

        /* Humidity first (no-hold) */
        if (si7021_read_measurement(g_i2c_fd, CMD_MEASURE_HUMIDITY_NO_HOLD, &raw_h) < 0) {
            ok = 0;
        }

        /* Temperature follows the previous humidity measurement */
        if (ok && si7021_read_measurement(g_i2c_fd, CMD_READ_PREV_TEMP_HUMIDITY, &raw_t) < 0) {
            ok = 0;
        }

        if (ok) {
            float temp = raw_to_celsius(raw_t);
            float rh   = raw_to_humidity(raw_h);

            /* Sanity range checks */
            if (temp < -40.0f || temp > 125.0f || rh < 0.0f || rh > 100.0f) {
                fprintf(stderr, "Out-of-range: T=%.2f C, RH=%.2f %%\n", temp, rh);
                log_error();
            } else {
                printf("T=%.2f C  RH=%.2f %%\n", temp, rh);
                log_data(temp, rh);
            }
        } else {
            fprintf(stderr, "Sensor read failed; resetting.\n");
            log_error();
            si7021_reset(g_i2c_fd);
        }

        /* Sleep but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    /* Cleanup */
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

