    return (125.0f * (float)raw / 65536.0f) - 6.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    } else {
        fprintf(fp, "ERROR,%.2f,%.2f\n", temp, rh);
    }

    fclose(fp);
}

static void log_error(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,ERROR\n", ts);
    } else {
        fprintf(fp, "ERROR,ERROR,ERROR\n");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Reset sensor to known state */
    if (si7021_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X. Check wiring.\n",
                SI7021_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int raw_h = 0, raw_t = 0;
        int ok = 1;

        /* Humidity first (no-hold) */
        if (si7021_read_measurement(g_i2c_fd, CMD_MEASURE_HUMIDITY_NO_HOLD, &raw_h) < 0) {
            ok = 0;
        }

        /* Temperature follows the previous humidity measurement */
        if (ok && si7021_read_measurement(g_i2c_fd, CMD_READ_PREV_TEMP_HUMIDITY, &raw_t) < 0) {
            ok = 0;
        }

        if (ok) {
            float temp = raw_to_celsius(raw_t);
            float rh   = raw_to_humidity(raw_h);

            /* Sanity range checks */
            if (temp < -40.0f || temp > 125.0f || rh < 0.0f || rh > 100.0f) {
                fprintf(stderr, "Out-of-range: T=%.2f C, RH=%.2f %%\n", temp, rh);
                log_error();
            } else {
                printf("T=%.2f C  RH=%.2f %%\n", temp, rh);
                log_data(temp, rh);
            }
        } else {
            fprintf(stderr, "Sensor read failed; resetting.\n");
            log_error();
            si7021_reset(g_i2c_fd);
        }

        /* Sleep but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    /* Cleanup */
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

