#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

/* Honeywell Zephyr HAFBLF0100A2AX5: 14-bit data, 1638 counts = 0 SLPM,
   14745 counts = 10 SLPM.  Status bits occupy the two MSBs. */
#define RAW_MIN 1638
#define RAW_MAX 14745
#define FLOW_MAX 10.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 2 bytes from the sensor and return the 14-bit flow value, or -1 on error. */
