#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR        0x5D
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0xB1
#define CTRL_REG1           0x10
#define PRESS_OUT_XL        0x28
#define PRESS_OUT_L         0x29
#define PRESS_OUT_H         0x2A
#define TEMP_OUT_L          0x2B
#define TEMP_OUT_H          0x2C
#define LOG_FILE            "environmental_data.txt"
#define SAMPLE_INTERVAL_US  1000000

static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
    if (log_file) {
        fprintf(log_file, "%s, ERROR: %s\n", ts, msg);
        fflush(log_file);
    }
}

static int init_lps33hw(void)
{
    int id = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (id < 0) {
        log_error("Failed to read WHO_AM_I register");
        return -1;
    }
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id, WHO_AM_I_VAL);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        log_error("Failed to write CTRL_REG1");
        return -1;
    }
    return 0;
}

static int read_pressure(double *pressure_hpa)
{
    int xl = i2cReadByteData(i2c_handle, PRESS_OUT_XL);
    int l  = i2cReadByteData(i2c_handle, PRESS_OUT_L);
    int h  = i2cReadByteData(i2c_handle, PRESS_OUT_H);
    if (xl < 0 || l < 0 || h < 0) {
        log_error("Failed to read pressure registers");
        return -1;
    }
    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | (int32_t)xl;
    if (raw & 0x800000) raw |= 0xFF000000;
    *pressure_hpa = (double)raw / 4096.0;
    return 0;
}

static int read_temperature(double *temp_c)
{
    int l = i2cReadByteData(i2c_handle, TEMP_OUT_L);
    int h = i2cReadByteData(i2c_handle, TEMP_OUT_H);
    if (l < 0 || h < 0) {
        log_error("Failed to read temperature registers");
        return -1;
    }
    int16_t raw = (int16_t)((h << 8) | l);
    *temp_c = 42.5 + (double)raw / 480.0;
    return 0;
}

static void log_data(double pressure, double temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            ts, pressure, temperature);
    fflush(log_file);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n",
                LPS33HW_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lps33hw() != 0) {
        fprintf(stderr, "LPS33HW initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        double pressure = 0.0, temperature = 0.0;
        int p_ok = read_pressure(&pressure);
        int t_ok = read_temperature(&temperature);

        if (p_ok == 0 && t_ok == 0) {
            log_data(pressure, temperature);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

