#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_SEC 2
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200

/* SCD30 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT  0x0104
#define CMD_GET_DATA_READY             0x0202
#define CMD_READ_MEASUREMENT           0x0300
#define CMD_SET_MEASUREMENT_INTERVAL   0x4600
#define CMD_SET_AMBIENT_PRESSURE       0x4D00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t scd30_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_cmd(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    return i2cWriteDevice(handle, (char *)buf, 2);
}

static int i2c_write_cmd_with_args(int handle, uint16_t cmd, uint16_t arg1, uint16_t arg2) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg1 >> 8);
    buf[3] = (uint8_t)(arg1 & 0xFF);
    buf[4] = scd30_crc8(&buf[2], 2);
    return i2cWriteDevice(handle, (char *)buf, 5);
}

static int i2c_read_bytes(int handle, uint8_t *buf, size_t len) {
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ---- SCD30 operations ---- */
static int scd30_start_periodic_measurement(int handle) {
    return i2c_write_cmd(handle, CMD_START_PERIODIC_MEASUREMENT);
}

static int scd30_stop_periodic_measurement(int handle) {
    return i2c_write_cmd(handle, CMD_STOP_PERIODIC_MEASUREMENT);
}

static int scd30_set_measurement_interval(int handle, uint16_t interval_sec) {
    return i2c_write_cmd_with_args(handle, CMD_SET_MEASUREMENT_INTERVAL, interval_sec, 0);
}

static int scd30_set_ambient_pressure(int handle, uint16_t pressure_pa) {
    return i2c_write_cmd_with_args(handle, CMD_SET_AMBIENT_PRESSURE, pressure_pa, 0);
}

static int scd30_get_data_ready(int handle, uint16_t *ready) {
    if (i2c_write_cmd(handle, CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing delay */
    uint8_t buf[3];
    if (i2c_read_bytes(handle, buf, 3) != 3)
        return -1;
    if (scd30_crc8(buf, 2) != buf[2])
        return -1;
    *ready = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int scd30_read_measurement(int handle, float *co2, float *temp, float *rh) {
    if (i2c_write_cmd(handle, CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[18];
    if (i2c_read_bytes(handle, buf, 18) != 18)
        return -1;
    /* Verify CRC for each 3-byte group: [MSB, LSB, CRC] */
    for (int i = 0; i < 6; i++) {
        if (scd30_crc8(&buf[i * 3], 2) != buf[i * 3 + 2])
            return -1;
    }
    uint16_t co2_raw  = (uint16_t)((buf[0]  << 8) | buf[1]);
    uint16_t temp_raw = (uint16_t)((buf[6]  << 8) | buf[7]);
    uint16_t rh_raw   = (uint16_t)((buf[12] << 8) | buf[13]);
    *co2  = (float)co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *rh   = (float)rh_raw   / 100.0f;
    return 0;
}

/* ---- Logging ---- */
static void log_data(float co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(g_log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(g_log_file);
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg);
    fflush(g_log_file);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
}

/* ---- Ventilation control ---- */
static void control_ventilation(float co2) {
    if (co2 < CO2_THRESHOLD_LOW) {
        printf("Ventilation: OFF\n");
    } else if (co2 < CO2_THRESHOLD_HIGH) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

/* ---- Signal handling ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        scd30_stop_periodic_measurement(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed. Exiting gracefully.\n");
        return 0;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (err=%d). Exiting gracefully.\n",
                I2C_BUS, SCD30_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 0;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 0;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Configure SCD30 */
    if (scd30_set_measurement_interval(g_i2c_handle, MEASUREMENT_INTERVAL_SEC) != 0) {
        log_error("Failed to set measurement interval");
        cleanup();
        return 0;
    }
    if (scd30_set_ambient_pressure(g_i2c_handle, 101325) != 0) {
        log_error("Failed to set ambient pressure");
        cleanup();
        return 0;
    }
    if (scd30_start_periodic_measurement(g_i2c_handle) != 0) {
        log_error("Failed to start periodic measurement");
        cleanup();
        return 0;
    }

    printf("SCD30 initialized. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, MEASUREMENT_INTERVAL_SEC);

    /* Main loop */
    while (g_running) {
        uint16_t ready = 0;
        if (scd30_get_data_ready(g_i2c_handle, &ready) != 0) {
            log_error("Failed to read data-ready flag");
            sleep(1);
            continue;
        }
        if (ready == 0) {
            sleep(1);
            continue;
        }

        float co2, temp, rh;
        if (scd30_read_measurement(g_i2c_handle, &co2, &temp, &rh) != 0) {
            log_error("Failed to read measurement data");
            sleep(1);
            continue;
        }

        log_data(co2, temp, rh);
        control_ventilation(co2);

        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

