#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define DEFAULT_INTERVAL_MS 1000
#define MEASUREMENT_CMD_LEN 2
#define READ_LEN 9
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sdp32_start_continuous(int handle) {
    uint8_t cmd[MEASUREMENT_CMD_LEN] = {0x36, 0x2F};
    int result = i2cWriteDevice(handle, (char *)cmd, MEASUREMENT_CMD_LEN);
    if (result != 0) {
        fprintf(stderr, "Error writing start-continuous command: %d\n", result);
        return -1;
    }
    return 0;
}

static int sdp32_read_data(int handle, float *pressure_pa) {
    uint8_t buffer[READ_LEN];
    int result = i2cReadDevice(handle, (char *)buffer, READ_LEN);
    if (result != READ_LEN) {
        fprintf(stderr, "Error reading data: expected %d bytes, got %d\n", READ_LEN, result);
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buffer[6], 2) != buffer[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    uint16_t scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    return 0;
}

static void log_data(float pressure_pa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Pressure: %.2f Pa\n", timestamp, pressure_pa);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval, using default %d ms\n", DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", SDP32_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (sdp32_start_continuous(i2c_handle) != 0) {
        fprintf(stderr, "Failed to start continuous measurement on SDP32\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure_pa;
    while (!terminate) {
        if (sdp32_read_data(i2c_handle, &pressure_pa) == 0) {
            log_data(pressure_pa);
        } else {
            fprintf(stderr, "Failed to read sensor data. Exiting.\n");
            break;
        }
        gpioDelay(interval_ms * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

