#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP810_ADDR        0x25
#define I2C_BUS            1
#define CMD_CONT_MEAS      0x3615
#define MEAS_DELAY_US      45000   /* 45 ms conversion time */
#define READ_LEN           9
#define SAMPLE_PERIOD_US   1000000 /* 1 s */

static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one continuous-measurement sample from the SDP810.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONT_MEAS >> 8) & 0xFF),
        (uint8_t)(CMD_CONT_MEAS & 0xFF)
    };
    uint8_t buf[READ_LEN];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write continuous-measurement command\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    int n = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "Error: expected %d bytes, got %d (sensor absent or bus error)\n",
                READ_LEN, n);
        return -1;
    }

    /* Validate CRC for each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -2;
        }
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor_pressure = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor_pressure == 0) {
        fprintf(stderr, "Error: invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor_pressure;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) — sensor may be absent at 0x%02X\n",
                g_i2c_handle, SDP810_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 continuous measurement started (addr 0x%02X, bus %d). Press Ctrl+C to stop.\n",
           SDP810_ADDR, I2C_BUS);

    while (!g_terminate) {
        float pressure, temperature;
        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);

        if (rc == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else if (rc == -2) {
            fprintf(stderr, "Warning: CRC mismatch — skipping sample\n");
        } else {
            fprintf(stderr, "Warning: I/O error — skipping sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nTerminated gracefully.\n");
    return EXIT_SUCCESS;
}

