#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define TEMP_REG            0x00
#define CONFIG_REG          0x02
#define I2C_BUS             "/dev/i2c-1"
#define SAMPLE_INTERVAL_S   5
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "i2c_read_reg16: read from 0x%02X failed (got %zd bytes): %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int configure_hdc1000(int fd) {
    /*
     * Configuration register (0x02):
     *   Bits 15-12 : reserved (0x0)
     *   Bit  11    : HEATER (0 = off)
     *   Bit  10    : reserved (0)
     *   Bit  9     : reserved (0)
     *   Bit  8     : reserved (0)
     *   Bit  7     : reserved (0)
     *   Bit  6     : reserved (0)
     *   Bit  5     : reserved (0)
     *   Bit  4     : reserved (0)
     *   Bit  3     : reserved (0)
     *   Bit  2     : reserved (0)
     *   Bit  1     : reserved (0)
     *   Bit  0     : MODE (0 = temperature + humidity, 1 = temperature only)
     *
     * Value 0x0000 enables combined measurement at 14-bit resolution.
     */
    if (i2c_write_reg8(fd, CONFIG_REG, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, CONFIG_REG + 1, 0x00) < 0)
        return -1;
    return 0;
}

static int read_hdc1000(int fd, float *temperature, float *humidity) {
    uint16_t raw_temp, raw_hum;

    if (i2c_read_reg16(fd, TEMP_REG, &raw_temp) < 0)
        return -1;
    if (i2c_read_reg16(fd, TEMP_REG + 2, &raw_hum) < 0)
        return -1;

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                HDC1000_ADDR, strerror(errno));
        goto cleanup;
    }

    if (configure_hdc1000(fd) < 0) {
        fprintf(stderr, "Failed to configure HDC1000 (sensor may be absent or bus error).\n");
        goto cleanup;
    }

    printf("HDC1000 initialized on %s (addr 0x%02X). Logging every %d s.\n",
           I2C_BUS, HDC1000_ADDR, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (read_hdc1000(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

