#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define CONVERSION_DELAY_US 10000
#define POLL_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command to Si7051: %d\n", result);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data from Si7051: %d\n", result);
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    return 0;
}

int main(void) {
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", SI7051_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in 5 seconds...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

