/*
 * MLX90833 Absolute Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MLX90833 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   MLX90833 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   MLX90833 VDD -> 3.3 V
 *   MLX90833 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o mlx90833 mlx90833.c -lpigpio -lrt
 * Run:   sudo ./mlx90833
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90833_ADDR  0x60          /* Manufacturer default 7-bit address */
#define SAMPLE_PERIOD  0.5           /* Seconds between readings */
#define MAX_RETRIES    3

/*
 * MLX90833 register map (16-bit addresses, big-endian on the bus).
 * The sensor returns a 16-bit pressure reading in register 0x0000.
 * The 16-bit temperature register is at 0x0002.
 */
#define REG_PRESSURE   0x0000
#define REG_TEMP       0x0002

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit register address to the sensor.
 * The MLX90833 expects the address as a 16-bit big-endian word.
 */
static int mlx_write_reg_addr(int handle, uint16_t reg)
{
    char buf[2];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian register value from the sensor.
 * First write the register address, then read 2 bytes.
 */
static int mlx_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char rx[2];

    if (mlx_write_reg_addr(handle, reg) != 0) {
        return -1;
    }

    /* Small delay so the sensor can prepare the response */
    gpioDelay(1000); /* 1 ms */

    if (i2cReadDevice(handle, rx, 2) != 2) {
        return -1;
    }

    *out = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                          */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, uint16_t *pressure, uint16_t *temperature)
{
    int ok = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (mlx_read_reg16(handle, REG_PRESSURE, pressure) == 0 &&
            mlx_read_reg16(handle, REG_TEMP, temperature) == 0) {
            ok = 1;
            break;
        }
        gpioDelay(10000); /* 10 ms back-off before retry */
    }

    return ok ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    char ts[32];

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, MLX90833_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] Failed to install signal handlers.\n");
    }

    printf("MLX90833 reader started. Bus=%d, Addr=0x%02X. Press Ctrl+C to stop.\n",
           I2C_BUS, MLX90833_ADDR);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        uint16_t pressure = 0, temperature = 0;

        if (read_sensor(g_i2c_handle, &pressure, &temperature) == 0) {
            get_timestamp(ts, sizeof(ts));
            printf("[%s] Pressure: 0x%04X, Temperature: 0x%04X\n",
                   ts, pressure, temperature);
        } else {
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "[%s] Sensor read failed (bus error or sensor absent).\n", ts);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    /* --- Cleanup ---------------------------------------------------- */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

