                (uint8_t)buf[2], (uint8_t)buf[3],
                (uint8_t)buf[4], (uint8_t)buf[5]);
        return -2;
    }

    /* Raw values are big-endian: [T_hi T_lo P_hi P_lo L_hi L_lo] */
    uint32_t raw_t = ((uint32_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint32_t raw_p = ((uint32_t)(uint8_t)buf[2] << 20)  /* 20-bit */
                   | ((uint32_t)(uint8_t)buf[3] << 12)
                   | ((uint32_t)(uint8_t)buf[4] << 4)
                   | ((uint32_t)(uint8_t)buf[5] >> 4);

    /* Datasheet compensation formulas */
    float t = (float)raw_t / 65536.0f;
    float p = (float)raw_p / 1048576.0f;  /* 2^20 */

    *temperature = (float)g_cal.c0 * 0.5f + (float)g_cal.c1 * t;
    *pressure    = (float)g_cal.c2 + (float)g_cal.c3 * p +
                   (float)g_cal.c0 * t * (1.0f + (float)g_cal.c1 * t);

    return 0;
}

