#define I2C_ADDR       0x63
#define CMD_READ_OTP   0x50   /* read 8 bytes from OTP calibration block */
#define CMD_MEASURE    0x40   /* high-precision measurement, ~7 ms */
#define MEASURE_DELAY  7000   /* microseconds */
#define SAMPLE_PERIOD  5      /* seconds between readings */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Calibration coefficients (read from OTP) ---- */
typedef struct {
    uint16_t c0, c1, c2, c3;
} icp_cal_t;

static icp_cal_t g_cal;
static bool      g_cal_valid = false;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 8 bytes of OTP calibration data from the sensor.               */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int read_calibration(int handle, icp_cal_t *cal)
{
    char buf[8];

    if (i2cWriteByte(handle, CMD_READ_OTP) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x50) failed\n");
        return -1;
    }
    gpioDelay(1000);  /* OTP read takes ~1 ms */

    int n = i2cReadDevice(handle, buf, sizeof buf);
    if (n != (int)sizeof buf) {
        fprintf(stderr, "[ERROR] i2cReadDevice(8) returned %d (expected %zu)\n",
                n, sizeof buf);
        return -1;
    }

    /* OTP bytes are big-endian: [c0_hi c0_lo c1_hi c1_lo c2_hi c2_lo c3_hi c3_lo] */
    cal->c0 = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    cal->c1 = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    cal->c2 = ((uint16_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5];
    cal->c3 = ((uint16_t)(uint8_t)buf[6] << 8) | (uint8_t)buf[7];

    /* Sanity-check: c0 should be non-zero for a real sensor */
    if (cal->c0 == 0) {
        fprintf(stderr, "[WARN] Calibration c0 is zero – sensor may be absent\n");
        return -1;
    }

    printf("[INFO] Calibration: c0=%u c1=%u c2=%u c3=%u\n",
           cal->c0, cal->c1, cal->c2, cal->c3);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a high-precision measurement and read 6 bytes.              */
/* Returns 0 on success, -1 on I2C error, -2 on sensor-absent data.    */
