#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "pressure_log.txt"
#define MEAS_DELAY_MS  45
#define SAMPLE_MS      1000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_open(const char *bus, uint8_t addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

static int sdp800_start_continuous(int fd) {
    uint8_t cmd[2] = { 0x36, 0x2F };
    if (write(fd, cmd, 2) != 2) {
        perror("write continuous-measurement command");
        return -1;
    }
    return 0;
}

static int sdp800_read_measurement(int fd, float *pressure, float *temperature) {
    uint8_t buf[9];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            perror("read measurement");
        else
            fprintf(stderr, "short read: %zd bytes\n", n);
        return -1;
    }

    /* Validate CRCs for each 2-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_p / 60.0f;   /* Pa  */
    *temperature = (float)raw_t / 200.0f;  /* C   */
    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = i2c_open(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0)
        return EXIT_FAILURE;

