    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = i2c_open(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0)
        return EXIT_FAILURE;

    if (sdp800_start_continuous(i2c_fd) < 0) {
