#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "airflow_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MEASURE_DELAY  8000       /* microseconds (8 ms) for SDP800 */
#define MAX_RETRIES    3

/* SDP800 continuous measurement command (MSB, LSB) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the SDP800.                                    */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.          */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, float *pressure_pa)
{
    uint8_t buf[3];
    int rc;

    /* Trigger continuous measurement */
    rc = i2cWriteDevice(handle, (char *)CMD_CONT_MEAS, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (trigger): %s\n", strerror(errno));
        return -1;
    }

    /* Wait for the measurement to complete */
    gpioDelay(MEASURE_DELAY);

    /* Read 3 bytes: MSB, LSB, CRC */
    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice: %s\n", strerror(errno));
        return -1;
    }
    if (rc != 3) {
        fprintf(stderr, "[ERROR] Short read: got %d bytes, expected 3\n", rc);
        return -1;
    }

    /* Verify CRC-8 of the two data bytes */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    /* Raw 16-bit signed value */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);

    /* Convert to Pa: raw / 60.0 (per SDP800 datasheet) */
    *pressure_pa = (float)raw / 60.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV log.                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure)
{
    int need_header = 0;

    /* Check whether the file exists so we can write a header */
    if (access(filename, F_OK) != 0) {
        if (errno != ENOENT) {
            fprintf(stderr, "[ERROR] access(%s): %s\n", filename, strerror(errno));
            return -1;
        }
        need_header = 1;
    }

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    if (need_header) {
        if (fprintf(fp, "timestamp,pressure_pa\n") < 0) {
            fprintf(stderr, "[ERROR] writing header: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "[ERROR] localtime_r: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "[ERROR] writing data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "[ERROR] fclose(%s): %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x25 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction: %s\n", strerror(errno));
    }

    printf("SDP800 airflow logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float pressure = 0.0f;
        int rc = read_sdp800(g_i2c_handle, &pressure);

        if (rc == 0) {
            consecutive_errors = 0;
            if (log_data(LOG_FILE, pressure) == 0) {
                printf("Pressure: %.2f Pa\n", pressure);
            } else {
                fprintf(stderr, "[ERROR] Failed to log data.\n");
            }
        } else if (rc == -2) {
            /* CRC mismatch: log the error but keep running */
            fprintf(stderr, "[WARN] CRC mismatch, skipping sample.\n");
            consecutive_errors++;
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "[ERROR] %d consecutive CRC failures. "
                                "Sensor may be absent or bus error.\n",
                        consecutive_errors);
            }
        } else {
            /* I2C error: log the error and back off briefly */
            fprintf(stderr, "[WARN] I2C read error, retrying in 1 s...\n");
            consecutive_errors++;
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "[ERROR] %d consecutive I2C failures. "
                                "Sensor may be absent or bus error.\n",
                        consecutive_errors);
            }
            sleep(1);
            continue;
        }

        /* Sleep for the sample period, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

