#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define SAMPLE_INTERVAL_US 5000000
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);

    long file_size = 0;
    FILE *check_fp = fopen(LOG_FILE, "r");
    if (check_fp) {
        fseek(check_fp, 0, SEEK_END);
        file_size = ftell(check_fp);
        fclose(check_fp);
    }

    if (file_size > LOG_FILE_SIZE_LIMIT) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
            fclose(fp);
        } else {
            perror("Error truncating log file");
            return -1;
        }
    }
    return 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    char buf[4];
    int result;

    result = i2cWriteByte(handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing trigger byte: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading 4 bytes from sensor: %d\n", result);
        return -1;
    }

    if ((buf[0] & 0xC0) != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", buf[0]);
        return -1;
    }

    unsigned int raw_humidity = ((unsigned int)(buf[0] & 0x3F) << 8) | (unsigned char)buf[1];
    unsigned int raw_temperature = ((unsigned int)buf[2] << 6) | ((unsigned int)buf[3] >> 2);

    *humidity = (float)raw_humidity * 100.0f / 16383.0f;
    *temperature = (float)raw_temperature * 165.0f / 16383.0f - 40.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", HIH6130_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;
    char timestamp[32];

    while (running) {
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            if (log_data(timestamp, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

