#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define MIN_NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define MAX_TIMEOUT_TICKS 10000
#define SCALE 0.1
#define OFFSET 0.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_nibble(int gpio, int *nibble_out) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == 0) {
        if ((gpioTick() - start) > MAX_TIMEOUT_TICKS * TICK_US) return -1;
    }
    start = gpioTick();
    while (gpioRead(gpio) == 1) {
        if ((gpioTick() - start) > MAX_TIMEOUT_TICKS * TICK_US) return -1;
    }
    uint32_t width = gpioTick() - start;
    if (width < MIN_NIBBLE_TICKS || width > MAX_NIBBLE_TICKS) return -2;
    *nibble_out = (width - 12) / 12;
    return 0;
}

static int read_sent_frame(int gpio, int *raw_out) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == 1) {
        if ((gpioTick() - start) > MAX_TIMEOUT_TICKS * TICK_US) return -1;
    }
    start = gpioTick();
    while (gpioRead(gpio) == 0) {
        if ((gpioTick() - start) > MAX_TIMEOUT_TICKS * TICK_US) return -1;
    }
    uint32_t sync_width = gpioTick() - start;
    if (sync_width < SYNC_TICKS * 0.8 || sync_width > SYNC_TICKS * 1.2) return -2;
    int status, d0, d1, d2, checksum;
    if (read_sent_nibble(gpio, &status) != 0) return -3;
    if (read_sent_nibble(gpio, &d0) != 0) return -3;
    if (read_sent_nibble(gpio, &d1) != 0) return -3;
    if (read_sent_nibble(gpio, &d2) != 0) return -3;
    if (read_sent_nibble(gpio, &checksum) != 0) return -3;
    int calc = (status + d0 + d1 + d2) & 0x0F;
    if (calc != checksum) return -4;
    *raw_out = (status << 8) | (d0 << 4) | d2;
    return 0;
}

static double convert_to_pressure(int raw) {
    return (double)raw * SCALE + OFFSET;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(SENT_GPIO, PI_INPUT);
    while (running) {
        int raw;
        int rc = read_sent_frame(SENT_GPIO, &raw);
        if (rc == 0) {
            double p = convert_to_pressure(raw);
            log_pressure(p);
            printf("Pressure: %.2f Pa\n", p);
        } else {
            fprintf(stderr, "SENT read error: %d\n", rc);
        }
        gpioDelay(100000);
    }
    gpioTerminate();
    return 0;
}

