/*
 * TMP117 Temperature Logger for Raspberry Pi 4 Model B
 * Library: pigpio (I2C via /dev/i2c-1)
 * Sensor:  Texas Instruments TMP117 (default I2C address 0x48)
 *
 * Reads temperature every 5 s, stores readings in a 100-entry
 * circular buffer in memory and persists the entire buffer to
 * temperature_log.dat on every sample and on exit.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp117_logger tmp117_logger.c -lpigpio -lrt
 * Run:    sudo ./tmp117_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1          /* /dev/i2c-1 on RPi 4              */
#define TMP117_ADDR          0x48       /* TMP117 default I2C address      */
#define TMP117_REG_TEMP      0x00       /* Temperature result register     */
#define TEMP_LSB_VALUE       0.0078125  /* TMP117: 1/128 °C per LSB        */
#define BUFFER_SIZE          100        /* Circular buffer depth           */
#define SAMPLE_INTERVAL_S    5          /* Seconds between samples         */
#define LOG_FILE             "temperature_log.dat"

/* ------------------------------- Globals --------------------------------- */
static int                  i2c_handle = -1;
static volatile sig_atomic_t running    = 1;

/* Circular buffer in memory */
typedef struct {
    float  data[BUFFER_SIZE];
    int    head;          /* next write slot */
    int    count;         /* valid entries   */
} CircularBuffer;

static CircularBuffer temp_buffer = { {0.0f}, 0, 0 };

/* --------------------------- Function prototypes -------------------------- */
static int  init_i2c(void);
static int  read_temperature(float *temp_out);
static void add_to_buffer(float temperature);
static void flush_buffer_to_file(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- I2C init --------------------------------- */
static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, TMP117_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* --------------------------- Read temperature ----------------------------- */
/*
 * TMP117 temperature register (0x00) is 2 bytes, big-endian, signed 16-bit.
 * Resolution: 1/128 °C per LSB.
 */
static int read_temperature(float *temp_out)
{
    char buf[2];
    int  bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, TMP117_REG_TEMP, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData returned %d: %s\n",
                bytes_read, bytes_read < 0 ? strerror(errno) : "short read");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                            (uint16_t)(uint8_t)buf[1]);
    *temp_out = (float)raw * TEMP_LSB_VALUE;
    return 0;
}

/* --------------------------- Circular buffer ------------------------------ */
static void add_to_buffer(float temperature)
{
    temp_buffer.data[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE)
        temp_buffer.count++;
}

/* --------------------------- Persist to file ------------------------------ */
static void flush_buffer_to_file(void)
{
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    size_t n = (size_t)temp_buffer.count;
    size_t written = fwrite(temp_buffer.data, sizeof(float), n, fp);
    if (written != n) {
        fprintf(stderr, "[ERROR] fwrite wrote %zu of %zu floats: %s\n",
                written, n, strerror(errno));
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "[WARN] fclose: %s\n", strerror(errno));
}

/* --------------------------- Signal handling ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;          /* let main loop exit cleanly */
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0)
        return EXIT_FAILURE;

    printf("TMP117 logger started. Sampling every %d s. Press Ctrl-C to stop.\n",
           SAMPLE_INTERVAL_S);

    while (running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            flush_buffer_to_file();
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "[WARN] Temperature read failed; will retry next cycle.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    flush_buffer_to_file();
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

