static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit big-endian register from the Si7202 */
static int read_register16(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static int read_sensor_data(int handle, float *magnetic_field, float *temperature) {
    int16_t raw_mag, raw_temp;

    if (read_register16(handle, SI7202_REG_MAG, &raw_mag) < 0) {
        return -1;
    }
    if (read_register16(handle, SI7202_REG_TEMP, &raw_temp) < 0) {
        return -1;
    }

    *magnetic_field = (float)raw_mag * 0.1f;
    *temperature = (float)raw_temp * 0.01f - 25.0f;
    return 0;
}

static int log_data(FILE *fp, float magnetic_field, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, magnetic_field, temperature) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

