        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        fflush(log_file);
    }

    while (running) {
        ret = read_sensor_data(i2c_handle, &magnetic_field, &temperature);
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor data; logging NaN values.\n");
            if (log_data(log_file, NAN, NAN) < 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        } else {
            if (log_data(log_file, magnetic_field, temperature) < 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

