#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define STALE_READ_THRESHOLD 2

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(unsigned char *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading I2C data: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    return 0;
}

static float convert_flow_rate(unsigned int raw_flow) {
    return ((float)raw_flow / 16384.0f - 0.1f) / 0.8f * 25.0f;
}

static float convert_temperature(unsigned int raw_temp) {
    return ((float)raw_temp / 4096.0f - 0.1f) / 0.8f * 80.0f - 40.0f;
}

static void log_data(float flow_rate, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Flow Rate: %.2f SLPM, Temperature: %.2f C\n", timestamp, flow_rate, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

