    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    unsigned char data[4];
    int consecutive_errors = 0;
    int stale_reads = 0;

    while (!terminate) {
        if (read_sensor_data(data) == 0) {
            consecutive_errors = 0;
            unsigned int raw_flow = ((unsigned int)data[0] << 8) | data[1];
            unsigned int raw_temp = ((unsigned int)data[2] << 8) | data[3];
            raw_flow &= 0x3FFF;
            raw_temp &= 0x0FFF;

            if (stale_reads < STALE_READ_THRESHOLD) {
                stale_reads++;
                fprintf(stderr, "Stale read %d, skipping\n", stale_reads);
                gpioDelay(SAMPLE_INTERVAL_US);
                continue;
            }

            float flow_rate = convert_flow_rate(raw_flow);
            float temperature = convert_temperature(raw_temp);
            log_data(flow_rate, temperature);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error %d\n", consecutive_errors);
            log_error("I2C read error");
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive errors, re-initializing I2C\n");
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "I2C re-initialization failed, exiting\n");
                    break;
                }
                consecutive_errors = 0;
                stale_reads = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

