#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define READ_INTERVAL_SEC 2
#define MAX_RETRIES 3
#define TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg, int status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,ERROR,%s,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg, status);
    }
    fclose(fp);
}

static void log_reading(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,OK,%.1f,%.1f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    }
    fclose(fp);
}

/*
 * Wait for the line to reach the requested level, returning the elapsed
 * microseconds or -1 on timeout.  level: 0 or 1.
 */
static long wait_level(int gpio, int level, long timeout_us) {
    long start = gpioTick();
    while (gpioRead(gpio) != level) {
        if (gpioTick() - start > timeout_us) return -1;
    }
    return gpioTick() - start;
}

/*
 * Measure the duration of the next high pulse on the line, returning the
 * value in microseconds or -1 on timeout.
 */
static long measure_high_pulse(int gpio, long timeout_us) {
    long start = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start > timeout_us) return -1;
    }
    long low_start = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - low_start > timeout_us) return -1;
    }
    return gpioTick() - low_start;
}

/*
 * Read 40 bits from the DHT11.  Returns 0 on success, -1 on timeout,
 * -2 on checksum error, -3 on sensor-absent (line stuck low).
 */
static int read_dht11(int gpio, float *temp, float *hum) {
    uint8_t data[5] = {0, 0, 0, 0, 0};

    /* --- Start signal: pull low for >= 18 ms, then high --- */
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(20000); /* 20 ms (>= 18 ms) */
    gpioWrite(gpio, 1);
    gpioDelay(30);    /* 30 us high before switching to input */

    gpioSetMode(gpio, PI_INPUT);

    /* --- Sensor response: ~80 us low + ~80 us high --- */
    if (wait_level(gpio, 0, TIMEOUT_US) < 0) {
        log_error("DHT11: response low timeout", -1);
        return -1;
    }
    if (wait_level(gpio, 1, TIMEOUT_US) < 0) {
        log_error("DHT11: response high timeout", -2);
        return -1;
    }
    if (wait_level(gpio, 0, TIMEOUT_US) < 0) {
        log_error("DHT11: response low timeout (2)", -3);
        return -1;
    }

    /* --- Read 40 data bits --- */
    for (int i = 0; i < 40; i++) {
        /* Each bit begins with ~50 us low */
        if (wait_level(gpio, 1, TIMEOUT_US) < 0) {
            log_error("DHT11: bit low timeout", -4);
            return -1;
        }
        /* High-pulse duration determines bit value: ~26-28 us = '0', ~70 us = '1' */
        long high_us = measure_high_pulse(gpio, TIMEOUT_US);
        if (high_us < 0) {
            log_error("DHT11: bit high timeout", -5);
            return -1;
        }
        data[i / 8] <<= 1;
        if (high_us > 50) data[i / 8] |= 1;
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
    if (checksum != data[4]) {
        log_error("DHT11: checksum mismatch", -6);
        return -2;
    }

    /* DHT11 integer-only: humidity = byte0, temperature = byte2 */
    *hum = (float)data[0];
    *temp = (float)data[2];
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temp, hum;
    int rc;

    while (running) {
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            rc = read_dht11(DHT11_GPIO, &temp, &hum);
            if (rc == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) gpioDelay(1000000); /* 1 s between retries */
        }

        if (ok) {
            log_reading(temp, hum);
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            log_error("DHT11: all retries failed", -7);
            fprintf(stderr, "DHT11 read failed after %d attempts\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

