#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT31_ADDR        0x44
#define I2C_BUS           1
#define LOG_FILE          "sht31d_data.log"
#define MEAS_CMD_MSB      0x2C
#define MEAS_CMD_LSB      0x06
#define MEAS_DELAY_US     20000   /* 20 ms — covers SHT31-D conversion time */
#define SAMPLE_INTERVAL   5       /* seconds */
#define MAX_RETRIES       3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (polynomial 0x31, init 0xFF, no final XOR) per SHT31-D datasheet ---- */
static uint8_t sht31_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature and humidity from the SHT31-D.
 * Returns 0 on success, -1 on persistent failure.
 */
static int read_sht31d(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = { MEAS_CMD_MSB, MEAS_CMD_LSB };
    uint8_t buf[6];
    int     rc;

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        /* Issue single-shot measurement command */
        rc = i2cWriteDevice(handle, (char *)cmd, 2);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d/%d] i2cWriteDevice failed: %d\n",
                    attempt, MAX_RETRIES, rc);
            gpioDelay(1000000 / MAX_RETRIES);   /* back off briefly */
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        /* Read 6 bytes: T_MSB T_LSB T_CRC  RH_MSB RH_LSB RH_CRC */
        rc = i2cReadDevice(handle, (char *)buf, 6);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d/%d] i2cReadDevice failed: %d\n",
                    attempt, MAX_RETRIES, rc);
            gpioDelay(1000000 / MAX_RETRIES);
            continue;
        }
        if (rc != 6) {
            fprintf(stderr, "[attempt %d/%d] short read: got %d bytes, expected 6\n",
                    attempt, MAX_RETRIES, rc);
            gpioDelay(1000000 / MAX_RETRIES);
            continue;
        }

        /* Validate CRCs */
        if (sht31_crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[attempt %d/%d] temperature CRC mismatch\n",
                    attempt, MAX_RETRIES);
            gpioDelay(1000000 / MAX_RETRIES);
            continue;
        }
        if (sht31_crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[attempt %d/%d] humidity CRC mismatch\n",
                    attempt, MAX_RETRIES);
            gpioDelay(1000000 / MAX_RETRIES);
            continue;
        }

        uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s,ERROR,%s\n", timestamp, message);
    fflush(fp);
}

int main(void)
{
    float temperature, humidity;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, SHT31_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,temperature_c,humidity_pct\n");

    printf("SHT31-D greenhouse logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (read_sht31d(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(g_log_file, temperature, humidity);
            printf("T=%.2f C  H=%.2f %%\n", temperature, humidity);
        } else {
            log_error(g_log_file, "sensor read failed after retries");
            fprintf(stderr, "Sensor read failed after %d retries.\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    if (g_log_file)
        fclose(g_log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

