#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65

#define DEVICE_ID_REG 0x00
#define EXPECTED_DEVICE_ID 0x2A

#define RED_CHANNEL_REG 0x64
#define GREEN_CHANNEL_REG 0x66
#define BLUE_CHANNEL_REG 0x68

#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int read_16bit_le(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading 16-bit register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_16bit_le(handle, RED_CHANNEL_REG, red) != 0) return -1;
    if (read_16bit_le(handle, GREEN_CHANNEL_REG, green) != 0) return -1;
    if (read_16bit_le(handle, BLUE_CHANNEL_REG, blue) != 0) return -1;
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    if (red == 0 && green == 0 && blue == 0) return 0.0f;
    float r = (float)red / 65535.0f;
    float g = (float)green / 65535.0f;
    float b = (float)blue / 65535.0f;
    float x = (-0.1461497f) + (0.2047092f) * r + (0.0334108f) * g + (-0.0166090f) * b;
    float y = (-0.0385286f) + (0.1326716f) * r + (0.0238428f) * g + (-0.0109138f) * b;
    if (x == 0.0f && y == 0.0f) return 0.0f;
    float z = 1.0f - x - y;
    float cct = 449.0f * (float)pow(x, 3) + 3525.0f * (float)pow(x, 2) * y + 6823.31f * x * (float)pow(y, 2) + 5520.23f * (float)pow(y, 3);
    return cct;
}

static void log_data(float cct1, float cct2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    float avg = (cct1 + cct2) / 2.0f;
    fprintf(log_file, "%s,%.2f\n", timestamp, avg);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1 at 0x%02X: %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2 at 0x%02X: %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    uint8_t id1 = 0, id2 = 0;
    if (read_register(i2c_handle1, DEVICE_ID_REG, &id1) != 0 || id1 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Sensor 1 (0x%02X) not detected or wrong ID: 0x%02X\n", SENSOR1_ADDR, id1);
        cleanup();
        return 1;
    }
    if (read_register(i2c_handle2, DEVICE_ID_REG, &id2) != 0 || id2 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Sensor 2 (0x%02X) not detected or wrong ID: 0x%02X\n", SENSOR2_ADDR, id2);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t red1 = 0, green1 = 0, blue1 = 0;
        uint16_t red2 = 0, green2 = 0, blue2 = 0;
        int ret1 = read_sensor_data(i2c_handle1, &red1, &green1, &blue1);
        int ret2 = read_sensor_data(i2c_handle2, &red2, &green2, &blue2);

        if (ret1 == 0 && ret2 == 0) {
            float cct1 = calculate_cct(red1, green1, blue1);
            float cct2 = calculate_cct(red2, green2, blue2);
            log_data(cct1, cct2);
