#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 2

/* MLX90824 transfer function constants */
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN_KPA 0.0f
#define P_MAX_KPA 800.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

static void log_error(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    if (g_log_file) {
        fprintf(g_log_file, "%s ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
}

static int read_register16(int handle, uint16_t reg, uint16_t *out) {
    char cmd[2];
    char data[2];
    int rc;

    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    rc = i2cWriteDevice(handle, cmd, 2);
    if (rc < 0) {
        return -1;
    }

    rc = i2cReadDevice(handle, data, 2);
    if (rc < 0) {
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static float convert_pressure(uint16_t raw) {
    return ((float)raw - (float)OUTPUT_MIN) *
           (P_MAX_KPA - P_MIN_KPA) /
           ((float)OUTPUT_MAX - (float)OUTPUT_MIN) + P_MIN_KPA;
}

static float convert_temperature(uint16_t raw) {
    return (float)raw * 0.01f - 40.0f;
}

static void log_data(float pressure, float temperature) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n",
            ts, pressure, temperature);
    fflush(g_log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint16_t raw_pressure = 0;
        uint16_t raw_temperature = 0;
        int p_ok = 0, t_ok = 0;

        if (read_register16(g_i2c_handle, PRESSURE_REG, &raw_pressure) == 0) {
            p_ok = 1;
        } else {
            log_error("Failed to read pressure register");
        }

        if (read_register16(g_i2c_handle, TEMPERATURE_REG, &raw_temperature) == 0) {
            t_ok = 1;
        } else {
            log_error("Failed to read temperature register");
        }

        if (p_ok && t_ok) {
            float pressure = convert_pressure(raw_pressure);
            float temperature = convert_temperature(raw_temperature);
            log_data(pressure, temperature);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* Clean resource release on all exit paths */
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

