#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_HIGH      28.0f
#define TEMP_LOW       26.0f
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Circular buffer */
typedef struct {
    float buf[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, float val)
{
    cb->buf[cb->head] = val;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_avg(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buf[i];
    return sum / (float)cb->count;
}

/* LM75B: 9-bit signed, 0.5 °C resolution, D9..D1 = bits 7..1, D0 = 0 */
static int read_temperature(int handle, float *out)
{
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %d\n", raw);
        return -1;
    }
    /* pigpio returns little-endian word; swap bytes for big-endian LM75B */
    uint16_t swapped = (uint16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));
    /* Bits D9..D1 = temperature MSB..LSB; D0 = 0 */
    int16_t signed_val = (int16_t)(swapped >> 1);
    *out = (float)signed_val * 0.5f;
    return 0;
}

static int control_fan(int gpio, float avg)
{
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "GPIO read error on pin %d\n", gpio);
        return -1;
    }
    if (avg > TEMP_HIGH && level == 0) {
        if (gpioWrite(gpio, 1) < 0) {
            fprintf(stderr, "GPIO write error on pin %d\n", gpio);
            return -1;
        }
        printf("Fan ON  (avg %.2f °C)\n", avg);
    } else if (avg < TEMP_LOW && level == 1) {
        if (gpioWrite(gpio, 0) < 0) {
            fprintf(stderr, "GPIO write error on pin %d\n", gpio);
            return -1;
        }
        printf("Fan OFF (avg %.2f °C)\n", avg);
    }
    return 0;
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);  /* Fan off at startup */

    CircularBuffer temp_buf;
    cb_init(&temp_buf);

    printf("LM75B fan controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            cb_push(&temp_buf, temperature);
            float avg = cb_avg(&temp_buf);
            printf("Temp: %.2f °C, Avg: %.2f °C\n", temperature, avg);
            if (control_fan(FAN_GPIO, avg) != 0)
                fprintf(stderr, "Fan control error\n");
        } else {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
        }
        gpioDelay(SAMPLE_US);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

