static int control_fan(int gpio, float avg)
{
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "GPIO read error on pin %d\n", gpio);
        return -1;
    }
    if (avg > TEMP_HIGH && level == 0) {
        if (gpioWrite(gpio, 1) < 0) {
            fprintf(stderr, "GPIO write error on pin %d\n", gpio);
            return -1;
        }
        printf("Fan ON  (avg %.2f °C)\n", avg);
    } else if (avg < TEMP_LOW && level == 1) {
        if (gpioWrite(gpio, 0) < 0) {
            fprintf(stderr, "GPIO write error on pin %d\n", gpio);
            return -1;
        }
        printf("Fan OFF (avg %.2f °C)\n", avg);
    }
    return 0;
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);  /* Fan off at startup */

    CircularBuffer temp_buf;
    cb_init(&temp_buf);

    printf("LM75B fan controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            cb_push(&temp_buf, temperature);
            float avg = cb_avg(&temp_buf);
            printf("Temp: %.2f °C, Avg: %.2f °C\n", temperature, avg);
            if (control_fan(FAN_GPIO, avg) != 0)
                fprintf(stderr, "Fan control error\n");
        } else {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
        }
        gpioDelay(SAMPLE_US);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

