#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "airflow.log"
#define PRESSURE_THRESHOLD 5.0f
#define MEAS_DELAY_US  45000   /* 45 ms for first measurement */
#define LOOP_DELAY_US  1000000 /* 1 s between samples */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Sensirion CRC-8 (poly 0x31, init 0xFF) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read one 9-byte measurement frame ----
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = { 0x36, 0x2F }; /* continuous-measurement, no averaging */
    uint8_t buf[9];
    int16_t raw_p, raw_t;

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] I2C read failed (sensor absent or bus error)\n");
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -2;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -2;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Status CRC mismatch\n");
        return -2;
    }

    raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    raw_t = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_p / 60.0f;   /* Pa  */
    *temperature = (float)raw_t / 200.0f;  /* °C  */
    return 0;
}

/* ---- Log one data row ---- */
static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    float pressure, temperature;
    int   rc;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 HVAC airflow monitor started. Logging to %s\n", LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        rc = read_sdp810(g_i2c_handle, &pressure, &temperature);

        if (rc == 0) {
            log_data(g_log_file, pressure, temperature);
            if (pressure > PRESSURE_THRESHOLD)
                fprintf(stderr,
                        "[WARN] Pressure %.2f Pa exceeds threshold %.1f Pa\n",
                        pressure, PRESSURE_THRESHOLD);
        } else if (rc == -1) {
            /* I/O error: attempt recovery by re-opening the bus */
            fprintf(stderr, "[WARN] I2C bus error; re-opening...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000); /* 100 ms back-off */
            g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (g_i2c_handle < 0)
                fprintf(stderr, "[ERROR] Re-open failed (handle=%d)\n", g_i2c_handle);
        }
        /* rc == -2 (CRC) is already reported; skip logging */

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

