/*
 * STTS2004 temperature monitor with hysteresis LED control.
 *
 * Board : Raspberry Pi 3 Model B+
 * I2C   : /dev/i2c-1, slave address 0x4A (ADDR pin tied to GND)
 * LED   : GPIO 17 (BCM), active-high
 *
 * Build : gcc -O2 -Wall -Wextra -o stts2004_mon stts2004_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define STTS2004_ADDR    0x4A
#define STTS2004_REG_TEMP 0x00
#define LED_GPIO         17
#define TEMP_HIGH        28.0f
#define TEMP_LOW         27.0f
#define POLL_INTERVAL_S  1
#define MAX_CONSEC_ERRORS 10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit temperature register (0x00) from the STTS2004.
 * Returns 0 on success and stores the raw 16-bit value in *out;
 * returns -1 on I2C error.
 */
static int read_temperature_raw(int fd, uint16_t *out)
{
    uint8_t reg = STTS2004_REG_TEMP;
    ssize_t w = write(fd, &reg, 1);
    if (w < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (w != 1) {
        fprintf(stderr, "I2C write (reg select) short: %zd bytes\n", w);
        return -1;
    }

    uint8_t buf[2];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r < 0) {
        fprintf(stderr, "I2C read (temp data) failed: %s\n", strerror(errno));
        return -1;
    }
    if (r != 2) {
        fprintf(stderr, "I2C read short: got %zd of 2 bytes\n", r);
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float raw_to_celsius(uint16_t raw)
{
    /* 16-bit data, 4 MSBs unused, 12-bit temperature code */
    uint16_t code = raw >> 4;
    return (float)code * 0.0625f;
}

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0)
        goto cleanup;

    /* --- I2C setup --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- GPIO setup (libgpiod) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "stts2004-mon", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("STTS2004 monitor started.  I2C=0x%02X  LED=GPIO%d  TH=%.1f  TL=%.1f\n",
           STTS2004_ADDR, LED_GPIO, TEMP_HIGH, TEMP_LOW);
    fflush(stdout);

    int consec_errors = 0;
    bool led_on = false;

    while (g_running) {
        uint16_t raw;
        if (read_temperature_raw(fd, &raw) < 0) {
            if (++consec_errors >= MAX_CONSEC_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                goto cleanup;
            }
            sleep(POLL_INTERVAL_S);
            continue;
        }
        consec_errors = 0;

        float temp = raw_to_celsius(raw);
        printf("Temperature: %.2f C\n", temp);
        fflush(stdout);

        if (temp > TEMP_HIGH && !led_on) {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "LED set high failed: %s\n", strerror(errno));
            } else {
                led_on = true;
                printf("  -> LED ON (above %.1f C)\n", TEMP_HIGH);
            }
        } else if (temp < TEMP_LOW && led_on) {
            if (gpiod_line_set_value(led, 0) < 0) {
                fprintf(stderr, "LED set low failed: %s\n", strerror(errno));
            } else {
                led_on = false;
                printf("  -> LED OFF (below %.1f C)\n", TEMP_LOW);
            }
        }

        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);   /* best-effort LED off */
        gpiod_line_release(led);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (fd >= 0)
        close(fd);

    printf("\nExiting cleanly.\n");
    return ret;
}

