/*
 * Si7021 temperature/humidity logger for Raspberry Pi 4 Model B
 * Uses pigpio for I2C on bus 1 (GPIO 2/3) at address 0x40.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_log si7021_log.c -lpigpio -lrt
 * Run:    sudo ./si7021_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between samples */
#define MAX_RETRIES    3
#define MEASURE_DELAY  20000       /* microseconds (20 ms) */

/* Si7021 commands (no register addressing; single-byte command + 2-byte read) */
#define CMD_MEASURE_RH_NO_HOLD   0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_PREV_TEMP       0xE0
#define CMD_READ_ID_1            0xFA
#define CMD_READ_ID_2            0x0F

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_line(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,%s\n", ts, msg);
        fflush(fp);
        fclose(fp);
    }
    printf("%s,%s\n", ts, msg);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fflush(fp);
        fclose(fp);
    }
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */

/*
 * Send a single-byte command to the Si7021.
 * Returns 0 on success, -1 on failure.
 */
static int si7021_send_cmd(uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    int rc = i2cWriteDevice(g_i2c_handle, buf, 1);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the Si7021.
 * Returns 0 on success, -1 on failure.
 */
static int si7021_read_bytes(char *buf, int len)
{
    int rc = i2cReadDevice(g_i2c_handle, buf, len);
    if (rc != len) {
        fprintf(stderr, "i2cReadDevice expected %d, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from the Si7021 after issuing a command.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int si7021_read_measurement(uint8_t cmd, uint16_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (si7021_send_cmd(cmd) != 0) {
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASURE_DELAY);   /* wait for conversion */

        char buf[2];
        if (si7021_read_bytes(buf, 2) != 0) {
            gpioDelay(10000);
            continue;
        }

        *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        return 0;
    }
    return -1;
}

/*
 * Read the 8-byte electronic ID (FA 0F) to confirm the sensor is present.
 * Returns 0 on success, -1 on failure.
 */
static int si7021_read_id(uint8_t id[8])
{
    if (si7021_send_cmd(CMD_READ_ID_1) != 0)
        return -1;
    gpioDelay(10000);

    char buf[8];
    if (si7021_read_bytes(buf, 8) != 0)
        return -1;

    memcpy(id, buf, 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Conversions                                                         */
/* ------------------------------------------------------------------ */
static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- verify sensor presence via electronic ID --- */
    uint8_t id[8];
    if (si7021_read_id(id) != 0) {
        log_error("Si7021 not detected (no ACK or ID read failed)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Si7021 detected. Electronic ID: ");
    for (int i = 0; i < 8; i++)
        printf("%02X", id[i]);
    printf("\n");

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    while (g_running) {
        uint16_t raw_rh = 0, raw_temp = 0;
        int ok = 1;

        if (si7021_read_measurement(CMD_MEASURE_RH_NO_HOLD, &raw_rh) != 0) {
            log_error("Failed to read relative humidity");
            ok = 0;
        }

        if (ok && si7021_read_measurement(CMD_READ_PREV_TEMP, &raw_temp) != 0) {
            log_error("Failed to read temperature (previous RH measurement)");
            ok = 0;
        }

        if (ok) {
            float temp_c = raw_to_celsius(raw_temp);
            float rh     = raw_to_humidity(raw_rh);
            char line[128];
            snprintf(line, sizeof(line), "%.2f,%.2f", temp_c, rh);
            log_line(line);
        }

        /* sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    /* --- cleanup --- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

