    char buf[8];
    if (si7021_read_bytes(buf, 8) != 0)
        return -1;

    memcpy(id, buf, 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Conversions                                                         */
/* ------------------------------------------------------------------ */
static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- verify sensor presence via electronic ID --- */
    uint8_t id[8];
    if (si7021_read_id(id) != 0) {
        log_error("Si7021 not detected (no ACK or ID read failed)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Si7021 detected. Electronic ID: ");
    for (int i = 0; i < 8; i++)
        printf("%02X", id[i]);
    printf("\n");

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    while (g_running) {
        uint16_t raw_rh = 0, raw_temp = 0;
        int ok = 1;

        if (si7021_read_measurement(CMD_MEASURE_RH_NO_HOLD, &raw_rh) != 0) {
            log_error("Failed to read relative humidity");
            ok = 0;
        }

        if (ok && si7021_read_measurement(CMD_READ_PREV_TEMP, &raw_temp) != 0) {
            log_error("Failed to read temperature (previous RH measurement)");
            ok = 0;
        }

        if (ok) {
            float temp_c = raw_to_celsius(raw_temp);
            float rh     = raw_to_humidity(raw_rh);
            char line[128];
            snprintf(line, sizeof(line), "%.2f,%.2f", temp_c, rh);
            log_line(line);
        }

        /* sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    /* --- cleanup --- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

