#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define TEMP_REG 0x00
#define CONFIG_REG 0x02
#define I2C_BUS 1
#define LOG_FILE "enviro_log.txt"
#define CONVERSION_DELAY_US 20000
#define SAMPLE_INTERVAL_US 5000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hdc1080(void) {
    /*
     * Configuration register (0x02):
     *   Bit 15: HEATER = 0 (heater off)
     *   Bit 14: mode = 0 (temperature and humidity measurement)
     *   Bits 13-12: TRES = 00 (14-bit)
     *   Bits 11-10: HRES = 00 (14-bit)
     *   Bit 9: mode = 0 (temperature then humidity)
     *   Bit 8: mode = 0 (continuous mode)
     *   Bits 7-4: TRES_T = 0000 (14-bit)
     *   Bits 3-0: HRES_T = 0000 (14-bit)
     * Result: 0x0000
     */
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x00;
    config[2] = 0x00;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 configuration register.\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(float *temperature, float *humidity) {
    char reg = TEMP_REG;
    char data[4];
    uint16_t raw_temp, raw_humidity;

    /* Point to the temperature register */
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set HDC1080 pointer register.\n");
        return -1;
    }

    /* Wait for conversion to complete (14-bit temp + 14-bit humidity = ~20 ms) */
    gpioDelay(CONVERSION_DELAY_US);

    /* Read 4 bytes: 2 bytes temperature + 2 bytes humidity */
    if (i2cReadDevice(i2c_handle, data, 4) != 4) {
        fprintf(stderr, "Error: Failed to read HDC1080 data.\n");
        return -1;
    }

    raw_temp = ((uint16_t)data[0] << 8) | (uint8_t)data[1];
    raw_humidity = ((uint16_t)data[2] << 8) | (uint8_t)data[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %d at address 0x%02X.\n", I2C_BUS, HDC1080_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hdc1080() != 0) {
        fprintf(stderr, "Error: HDC1080 initialization failed. Check wiring and sensor presence.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HDC1080 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_hdc1080(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

