/*
 * STS40 greenhouse temperature monitor — Raspberry Pi Zero W
 * Uses the Linux I2C ioctl interface (no wiringPi).
 *
 * Wiring:
 *   STS40 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   STS40 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   STS40 VDD  -> 3.3 V
 *   STS40 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o sts40_monitor sts40_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x44
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define CONV_DELAY_MS  10         /* STS40 conversion time */

/* Single-shot, high repeatability, clock stretching disabled */
static const uint8_t MEASURE_CMD[2] = { 0x2C, 0xE0 };

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;          /* let main loop exit cleanly */
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Send the 2-byte measurement command.
 * Returns 0 on success, -1 on error.
 */
static int sts40_send_cmd(int fd, const uint8_t cmd[2])
{
    ssize_t n = write(fd, cmd, sizeof(cmd));
    if (n != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "write(measure cmd): %s (wrote %zd bytes)\n",
                n < 0 ? strerror(errno) : "short write", n);
        return -1;
    }
    return 0;
}

/*
 * Read 3 bytes: MSB, LSB, CRC8.
 * Returns 0 on success, -1 on error.
 */
static int sts40_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "read(data): %s (got %zd bytes)\n",
                n < 0 ? strerror(errno) : "short read", n);
        return -1;
    }
    return 0;
}

/*
 * Convert raw ticks to Celsius.
 * Formula: T = -45 + 175 * raw / 65535
 */
static float raw_to_celsius(uint16_t raw)
{
    return -45.0f + 175.0f * (float)raw / 65535.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_temperature(FILE *fp, float temp_c)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(fp, "%s, %.2f\n", ts, temp_c) < 0)
        perror("fprintf(log)");
    else
        fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, STS40_ADDR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s at addr 0x%02X\n",
                I2C_BUS, STS40_ADDR);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("STS40 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t data[3];

        if (sts40_send_cmd(g_i2c_fd, MEASURE_CMD) < 0) {
            fprintf(stderr, "Measurement command failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        usleep(CONV_DELAY_MS * 1000);   /* 10 ms conversion wait */

        if (sts40_read_data(g_i2c_fd, data, sizeof(data)) < 0) {
            fprintf(stderr, "Read failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CRC mismatch (calc=0x%02X, recv=0x%02X).\n",
                    crc8(data, 2), data[2]);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        float temp_c = raw_to_celsius(raw);

        log_temperature(g_log_fp, temp_c);
        printf("Temperature: %.2f C\n", temp_c);

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

