#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define CIRCULAR_BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define LOG_INTERVAL_SEC 60
#define READ_INTERVAL_SEC 5
#define START_MEAS_CMD 0x21B1
#define STOP_MEAS_CMD 0x3F86
#define READ_MEAS_CMD 0xE000
#define MEAS_DELAY_US 1000000

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t log_thread;
static int log_thread_created = 0;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    }
    fprintf(stderr, "%s\n", message);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    uint8_t buf[9];
    if (i2cWriteDevice(i2c_handle, (char *)(uint8_t[]){0xE0, 0x00}, 2) != 0) {
        log_error("I2C write read command failed");
        return -1;
    }
    gpioDelay(2000);
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        log_error("I2C read measurement failed");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CRC mismatch on CO2");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("CRC mismatch on temperature");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("CRC mismatch on humidity");
        return -1;
    }
    *co2 = (buf[0] << 8) | buf[1];
    uint16_t t_raw = (buf[3] << 8) | buf[4];
    uint16_t h_raw = (buf[6] << 8) | buf[7];
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (buf->count == CIRCULAR_BUFFER_SIZE)
        buf->tail = (buf->tail + 1) % CIRCULAR_BUFFER_SIZE;
    else
        buf->count++;
    pthread_mutex_unlock(&buf->mutex);
}

static void *log_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_SEC);
        if (!running) break;
        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        int start = buffer.tail;
        pthread_mutex_unlock(&buffer.mutex);
        if (count == 0) continue;
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[256];
        snprintf(filename, sizeof(filename), "%s%d-%02d-%02d_%02d-%02d-%02d.csv",
                 LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);
        FILE *fp = fopen(filename, "w");
        if (!fp) {
            log_error("Failed to open log file");
            continue;
        }
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
        for (int i = 0; i < count; i++) {
            int idx = (start + i) % CIRCULAR_BUFFER_SIZE;
            fprintf(fp, "%ld,%u,%.2f,%.2f\n",
                    (long)buffer.data[idx].timestamp,
                    buffer.data[idx].co2,
                    buffer.data[idx].temperature,
                    buffer.data[idx].humidity);
        }
        fclose(fp);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_thread_created) {
        pthread_join(log_thread, NULL);
        log_thread_created = 0;
    }
    pthread_mutex_destroy(&buffer.mutex);
    if (i2c_handle >= 0) {
        write_command(STOP_MEAS_CMD);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }
    buffer_init(&buffer);
    if (write_command(START_MEAS_CMD) != 0) {
        log_error("Failed to start periodic measurement");
        cleanup();
        return 1;
    }
    gpioDelay(MEAS_DELAY_US);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (pthread_create(&log_thread, NULL, log_thread_func, NULL) != 0) {
        log_error("Failed to create log thread");
        cleanup();
        return 1;
    }
    log_thread_created = 1;
    while (running) {
        uint16_t co2;
        float temp, hum;
        if (read_measurement(&co2, &temp, &hum) == 0) {
            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temp;
            data.humidity = hum;
            buffer_add(&buffer, data);
        }
        sleep(READ_INTERVAL_SEC);
    }
    cleanup();
    return 0;
}

