#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_REG 0x05
#define MEAS_REG 0x00
#define MEAS_CMD 0x00
#define DATA_LEN 6
#define SAMPLE_INTERVAL_US 5000000
#define MEAS_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c2;
    uint16_t c3;
} icp10110_calib_t;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_calibration(int handle, icp10110_calib_t *cal) {
    char buf[4];
    if (i2cReadI2CBlockData(handle, CALIB_REG, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read calibration coefficients\n");
        return -1;
    }
    cal->c0 = (uint16_t)((buf[0] << 8) | buf[1]);
    cal->c1 = (uint16_t)((buf[2] << 8) | buf[3]);
    if (i2cReadI2CBlockData(handle, CALIB_REG + 2, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read calibration coefficients (part 2)\n");
        return -1;
    }
    cal->c2 = (uint16_t)((buf[0] << 8) | buf[1]);
    cal->c3 = (uint16_t)((buf[2] << 8) | buf[3]);
    return 0;
}

static int read_sensor_data(int handle, const icp10110_calib_t *cal,
                            float *pressure, float *temperature) {
    char cmd = MEAS_CMD;
    if (i2cWriteI2CBlockData(handle, MEAS_REG, &cmd, 1) != 1) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    char data[DATA_LEN];
    if (i2cReadI2CBlockData(handle, MEAS_REG, data, DATA_LEN) != DATA_LEN) {
        fprintf(stderr, "Error: Failed to read measurement data\n");
        return -1;
    }

    uint32_t raw_p = ((uint32_t)(data[0] & 0x0F) << 16) |
                     ((uint32_t)data[1] << 8) |
                     ((uint32_t)data[2]);
    uint32_t raw_t = ((uint32_t)(data[3] & 0x0F) << 16) |
                     ((uint32_t)data[4] << 8) |
                     ((uint32_t)data[5]);

    float t = (float)raw_t / 65536.0f * 100.0f - 50.0f;
    *temperature = t;

    float p = (float)raw_p / 65536.0f;
    float p_comp = cal->c0 + cal->c1 * p + cal->c2 * p * p + cal->c3 * p * p * p;
    *pressure = p_comp * 100.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ICP10110_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char who_am_i;
    if (i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if ((uint8_t)who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                (uint8_t)who_am_i, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    icp10110_calib_t cal;
    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Weather station started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float pressure, temperature;
        if (read_sensor_data(i2c_handle, &cal, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
            printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

