/*
 * ICP-10125 barometric pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Uses the standard Linux I2C interface (open(), ioctl(), read(), write())
 * and libgpiod for the warning LED.
 *
 * Wiring:
 *   ICP-10125 SDA -> GPIO 2 (BCM)
 *   ICP-10125 SCL -> GPIO 3 (BCM)
 *   ICP-10125 VDD -> 3.3 V
 *   ICP-10125 GND -> GND
 *   LED anode    -> GPIO 17 (BCM) through ~330 ohm resistor
 *   LED cathode  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10125 icp10125.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63

#define REG_OTP_COEFF  0x66
#define REG_MEAS_CMD   0x4011
#define REG_MEAS_DATA  0x4012

#define HIGH_ALTITUDE_THRESHOLD_PA 95000.0f
#define POLL_INTERVAL_MS           1000
#define MEAS_DELAY_MS              20

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * CRC-8 polynomial 0x31, init 0x00, as used by the ICP-10125.
 */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read N bytes from a 16-bit register address.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read (reg 0x%02X, want %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Write a 16-bit command to the sensor.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = {
        (uint8_t)(cmd >> 8),
        (uint8_t)(cmd & 0xFF)
    };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (cmd 0x%04X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read the 4 calibration coefficients from OTP.
 * Returns 0 on success, -1 on error.
 */
static int read_calibration(int fd, uint16_t cal[4])
{
    uint8_t buf[8];
    if (i2c_read_reg(fd, REG_OTP_COEFF, buf, sizeof(buf)) != 0)
        return -1;

    for (int i = 0; i < 4; i++)
        cal[i] = (uint16_t)((buf[i * 2] << 8) | buf[i * 2 + 1]);

    /* Sanity-check: coefficients should be non-zero */
    if (cal[0] == 0 || cal[1] == 0 || cal[2] == 0 || cal[3] == 0) {
        fprintf(stderr, "Calibration coefficients are all zero — sensor not present?\n");
        return -1;
    }
    return 0;
}

/*
 * Trigger a high-accuracy measurement and read the 6-byte result.
 * Returns 0 on success, -1 on error.
 */
static int read_measurement(int fd, uint32_t *raw_p, uint32_t *raw_t)
{
    if (i2c_write_cmd(fd, REG_MEAS_CMD) != 0)
        return -1;

    sleep_ms(MEAS_DELAY_MS);

    uint8_t buf[6];
    if (i2c_read_reg(fd, REG_MEAS_DATA, buf, sizeof(buf)) != 0)
        return -1;

    /* Verify CRC on the first 5 bytes */
    if (crc8(buf, 5) != buf[5]) {
        fprintf(stderr, "CRC mismatch on measurement data\n");
        return -1;
    }

    *raw_p = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *raw_t = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

/*
 * Convert raw sensor data to Pascals and Celsius using the
 * official InvenSense ICP-10125 conversion formulas.
 */
static void convert(uint32_t raw_p, uint32_t raw_t,
                    const uint16_t cal[4],
                    float *pressure_pa, float *temp_c)
{
    /*
     * Scaling factors for the 16-bit OTP coefficients.
     * The datasheet defines S_P and S_T as 16-bit values, but the
     * conversion formulas use 32-bit values scaled by 2^16.
     */
    const uint32_t S_P = (uint32_t)cal[0] << 16;
    const uint32_t S_T = (uint32_t)cal[1] << 16;
    const uint32_t B_P = (uint32_t)cal[2] << 16;
    const uint32_t B_T = (uint32_t)cal[3] << 16;

    /* Temperature in Celsius */
    float T = (float)raw_t / S_T - 40.0f;

    /* Pressure in Pa */
    float P = (float)raw_p / S_P;
    P = P - (B_P / 1000000.0f) * (T - 40.0f);

    *pressure_pa = P;
    *temp_c      = T;
}

int main(void)
{
    struct sigaction sa = {
        .sa_handler = sigint_handler,
        .sa_flags   = 0
    };
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- I2C setup --- */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- GPIO setup (libgpiod) --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to the first chip if gpiochip4 is unavailable */
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, 17);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line 17: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO 17 as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- Read calibration coefficients --- */
    uint16_t cal[4];
    if (read_calibration(i2c_fd, cal) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients.\n");
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Calibration coefficients: %u %u %u %u\n",
           cal[0], cal[1], cal[2], cal[3]);

    /* --- Main loop --- */
    while (g_running) {
        uint32_t raw_p = 0, raw_t = 0;

        if (read_measurement(i2c_fd, &raw_p, &raw_t) != 0) {
            fprintf(stderr, "Measurement read failed — continuing.\n");
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }

        float pressure_pa, temp_c;
        convert(raw_p, raw_t, cal, &pressure_pa, &temp_c);

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
               pressure_pa, temp_c);

        bool high_alt = (pressure_pa < HIGH_ALTITUDE_THRESHOLD_PA);
        int  blink_ms = high_alt ? 100 : 500;

        for (int i = 0; i < 10 && g_running; i++) {
            if (gpiod_line_set_value(led, 1) < 0)
                break;
            sleep_ms(blink_ms);
            if (!g_running) break;
            if (gpiod_line_set_value(led, 0) < 0)
                break;
            sleep_ms(blink_ms);
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    /* --- Cleanup --- */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

