#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x5A
#define FAN_GPIO       18
#define AMBIENT_REG    0x06
#define OBJECT_REG     0x07
#define TEMP_HIGH      30.0f
#define TEMP_LOW       28.0f
#define LOG_FILE       "temperature_log.txt"
#define READ_RETRIES   3
#define RETRY_DELAY_US 10000
#define SAMPLE_US      2000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *temp_out) {
    char buf[2];
    int retries = READ_RETRIES;

    while (retries-- > 0) {
        if (i2cWriteByte(handle, reg) < 0) {
            fprintf(stderr, "I2C write reg 0x%02X failed (ret=%d)\n", reg, retries);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(5000);
        if (i2cReadDevice(handle, buf, 2) == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *temp_out = (float)raw * 0.02f - 273.15f;
            return 0;
        }
        fprintf(stderr, "I2C read reg 0x%02X failed (ret=%d)\n", reg, retries);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ambient, object);
    }
    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (object %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to set fan GPIO high\n");
        }
    } else if (object_temp < TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
