#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    char cmd = MEASURE_CMD;
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, &cmd, 1) != 0) {
            fprintf(stderr, "Error writing measurement command (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, buf, 6) != 6) {
            fprintf(stderr, "Error reading sensor data (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }

        unsigned int raw_t = (buf[0] << 8) | buf[1];
        unsigned int raw_rh = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_rh / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1;
}

void handle_client(int client_fd) {
    float temperature, humidity;
    char response[256];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char time_buf[80];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
        snprintf(response, sizeof(response),
                 "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n"
                 "<html><head><title>SHT40 Data</title></head><body>"
                 "<h1>SHT40 Data</h1>"
                 "<p>Temperature: %.2f &deg;C</p>"
                 "<p>Humidity: %.2f %%</p>"
                 "<p>Last updated: %s</p>"
                 "</body></html>",
                 temperature, humidity, time_buf);
    } else {
        snprintf(response, sizeof(response),
                 "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n"
                 "<html><head><title>Error</title></head><body>"
                 "<h1>Error</h1>"
                 "<p>Failed to read sensor data.</p>"
                 "</body></html>");
    }

    send(client_fd, response, strlen(response), 0);
    close(client_fd);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("Accept failed");
            continue;
        }

        handle_client(client_fd);
    }

    printf("\nShutting down...\n");
    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

