#include <pigpio.h>

#define HDC2010_ADDR 0x40
#define I2C_BUS 1

#define REG_TEMP_LOW  0x00
#define REG_TEMP_HIGH 0x01
#define REG_HUM_LOW   0x02
#define REG_HUM_HIGH  0x03
#define REG_MEAS_CFG  0x0E
#define REG_CONFIG    0x0F

#define MEAS_TRIGGER  0x01
#define MEAS_DONE_BIT 0x01

#define POLL_TIMEOUT_MS 500
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int trigger_measurement(int handle) {
    return write_register(handle, REG_MEAS_CFG, MEAS_TRIGGER);
}

static int wait_for_measurement(int handle) {
    uint8_t cfg;
    int elapsed = 0;
    while (elapsed < POLL_TIMEOUT_MS) {
        if (read_register(handle, REG_MEAS_CFG, &cfg) < 0) {
            return -1;
        }
        if ((cfg & MEAS_DONE_BIT) == 0) {
            return 0;
        }
        gpioDelay(1000);
        elapsed += 10;
    }
    fprintf(stderr, "Measurement timeout\n");
    return -1;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t low, high;
    if (read_register(handle, REG_TEMP_LOW, &low) < 0) return -1;
    if (read_register(handle, REG_TEMP_HIGH, &high) < 0) return -1;
    uint16_t raw = ((uint16_t)high << 8) | low;
    *temperature = ((float)raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int read_humidity(int handle, float *humidity) {
    uint8_t low, high;
    if (read_register(handle, REG_HUM_LOW, &low) < 0) return -1;
    if (read_register(handle, REG_HUM_HIGH, &high) < 0) return -1;
    uint16_t raw = ((uint16_t)high << 8) | low;
    *humidity = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    int handle = -1;
    int ret = 1;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", HDC2010_ADDR, handle);
        goto cleanup;
    }

    if (write_register(handle, REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring HDC2010 (heater disabled, 14-bit)\n");
        goto cleanup;
    }

    while (running) {
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (trigger_measurement(handle) < 0) {
                gpioDelay(100000);
                continue;
            }
            if (wait_for_measurement(handle) < 0) {
                gpioDelay(100000);
                continue;
            }
            float temperature, humidity;
            if (read_temperature(handle, &temperature) < 0) {
                gpioDelay(100000);
                continue;
            }
            if (read_humidity(handle, &humidity) < 0) {
                gpioDelay(100000);
                continue;
            }
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
            success = 1;
            break;
        }
        if (!success && running) {
            fprintf(stderr, "Failed to read sensor after %d attempts\n", MAX_RETRIES);
        }
        for (int i = 0; i < 5 && running; i++) {
            gpioDelay(1000000);
        }
    }

    ret = 0;

cleanup:
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();
    return ret;
}

