#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP800_ADDR        0x25
#define I2C_BUS            1
#define MEASURE_CMD_MSB    0x36
#define MEASURE_CMD_LSB    0x2F
#define MEASUREMENT_DELAY  45000   /* microseconds (45 ms) */
#define LOOP_DELAY         500000  /* microseconds (500 ms) */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t cmd[2] = { MEASURE_CMD_MSB, MEASURE_CMD_LSB };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from sensor\n");
        return -1;
    }

    /* Verify CRC for pressure word (bytes 0-1, CRC byte 2) */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }

    /* Verify CRC for temperature word (bytes 3-4, CRC byte 5) */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", handle);
        goto cleanup_gpio;
    }

    printf("SDP800-500Pa reader started (I2C bus %d, addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_BUS, SDP800_ADDR);

    while (running) {
        int16_t pressure = 0, temperature = 0;

        if (read_sdp800(handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
        } else {
            fprintf(stderr, "Warning: read failed, will retry next cycle\n");
        }

        gpioDelay(LOOP_DELAY);
    }

    rc = EXIT_SUCCESS;

    if (handle >= 0)
        i2cClose(handle);

cleanup_gpio:
    gpioTerminate();
    return rc;
}

