#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define GPIO_CHIP "gpiochip0"
#define GPIO_RELAY 17
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"

#define P 0.1
#define I 0.01
#define D 0.001

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spidev");
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI mode");
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI bits");
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI speed");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }
    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip); chip = NULL; return -1;
    }
    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        perror("gpiod_line_request_output");
        relay_line = NULL;
        gpiod_chip_close(chip); chip = NULL; return -1;
    }
    return 0;
}

static int read_thermocouple(int *temp_c) {
    uint8_t tx[2] = {0, 0};
    uint8_t rx[2] = {0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer");
        return -1;
    }
    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    if (raw & 0x0004) {
        fprintf(stderr, "Thermocouple open circuit or shorted\n");
        return -1;
    }
    int16_t temp_raw = (int16_t)(raw & 0x0FFF);
    *temp_c = temp_raw * 0.25;
    return 0;
}

static void set_relay_duty(float duty) {
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;
    int val = (duty > 0.5f) ? 1 : 0;
    if (gpiod_line_set_value(relay_line, val) < 0) {
        perror("gpiod_line_set_value");
    }
}

static int load_profile(const char *filename, float *profile, int max_len) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("fopen profile");
        return -1;
    }
    int i = 0;
    while (i < max_len) {
        float t, temp;
        if (fscanf(fp, "%f,%f", &t, &temp) != 2) break;
        profile[i++] = temp;
    }
    fclose(fp);
    return i;
}

static void log_data(float temp, float target, float pid_out) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, target, pid_out);
    fflush(log_fp);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }
    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        cleanup();
        return 1;
    }
    fprintf(log_fp, "Timestamp,Temperature,Target,PID_Output\n");

    float profile[1000];
    int profile_len = load_profile(PROFILE_FILE, profile, sizeof(profile) / sizeof(profile[0]));
    if (profile_len <= 0) {
