        return 1;
    }
    fprintf(log_fp, "Timestamp,Temperature,Target,PID_Output\n");

    float profile[1000];
    int profile_len = load_profile(PROFILE_FILE, profile, sizeof(profile) / sizeof(profile[0]));
    if (profile_len <= 0) {
        fprintf(stderr, "Failed to load profile\n");
        cleanup();
        return 1;
    }

    float prev_error = 0.0f, integral = 0.0f;
    int profile_idx = 0;

    while (running) {
        float target = profile[profile_idx];
        int temp_c;
        if (read_thermocouple(&temp_c) < 0) {
            fprintf(stderr, "Sensor read error, using last target\n");
            temp_c = (int)target;
        }
        float error = (float)temp_c - target;
        integral += error;
        if (integral > 100.0f) integral = 100.0f;
        if (integral < -100.0f) integral = -100.0f;
        float derivative = error - prev_error;
        float pid_out = P * error + I * integral + D * derivative;
        if (pid_out < 0.0f) pid_out = 0.0f;
        if (pid_out > 1.0f) pid_out = 1.0f;
        set_relay_duty(pid_out);
        log_data((float)temp_c, target, pid_out);
        prev_error = error;

        if (profile_idx < profile_len - 1 && (float)temp_c >= target) {
            profile_idx++;
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

