#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <stdint.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define SERVER_ADDRESS "api.example.com"
#define SERVER_PORT 80
#define HTTP_REQUEST_SIZE 256
#define JSON_BUFFER_SIZE 128
#define READ_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_humidity(int fd, float *humidity) {
    uint8_t cmd[2] = {0xE5, 0x00};
    if (write(fd, cmd, 2) != 2) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    usleep(50000);

    uint8_t buf[6];
    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        syslog(LOG_ERR, "I2C read failed: expected 6 bytes, got %zd", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "Temperature CRC mismatch");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        syslog(LOG_ERR, "Humidity CRC mismatch");
        return -1;
    }

    uint16_t raw_humidity = (buf[3] << 8) | buf[4];
    *humidity = -6.0f + 125.0f * (float)raw_humidity / 65536.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static int post_data(const char *json_data) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct hostent *server = gethostbyname(SERVER_ADDRESS);
    if (!server) {
        syslog(LOG_ERR, "DNS lookup failed for %s", SERVER_ADDRESS);
        close(sockfd);
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);
    memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connect failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char request[HTTP_REQUEST_SIZE];
    int req_len = snprintf(request, sizeof(request),
        "POST /humidity HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        SERVER_ADDRESS, strlen(json_data), json_data);

    if (req_len >= (int)sizeof(request)) {
        syslog(LOG_ERR, "HTTP request buffer overflow");
        close(sockfd);
        return -1;
    }

    if (write(sockfd, request, req_len) != req_len) {
        syslog(LOG_ERR, "HTTP write failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char response[256];
    ssize_t resp_len = read(sockfd, response, sizeof(response) - 1);
    if (resp_len > 0) {
        response[resp_len] = '\0';
        syslog(LOG_INFO, "HTTP response: %s", response);
    } else {
        syslog(LOG_WARNING, "No HTTP response received");
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_DEVICE, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Starting humidity monitoring (interval: %d s)", READ_INTERVAL);

    while (running) {
        float humidity;
        if (read_humidity(fd, &humidity) == 0) {
            char json_data[JSON_BUFFER_SIZE];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);
            if (post_data(json_data) == 0) {
                syslog(LOG_INFO, "Humidity: %.2f%%, POST successful", humidity);
            } else {
                syslog(LOG_ERR, "Failed to POST humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from HTU21D");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    close(fd);
    closelog();
    return 0;
}

