#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_DATA_REG 0xF7
#define BMP280_CALIB_REG 0x88
#define BMP280_CALIB_LEN 24
#define BMP280_FORCED_MODE 0x01
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0
#define LOG_FILE "pressure_log.txt"
#define I2C_BUS 1
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) return -1;
    return 0;
}

static int bmp280_init(void) {
    uint8_t id;
    if (i2c_read_block(i2c_handle, BMP280_CHIP_ID_REG, &id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X).\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(i2c_handle, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(2000);
    uint8_t calib_buf[BMP280_CALIB_LEN];
    if (i2c_read_block(i2c_handle, BMP280_CALIB_REG, calib_buf, BMP280_CALIB_LEN) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }
    calib.dig_T1 = (uint16_t)(calib_buf[0] | (calib_buf[1] << 8));
    calib.dig_T2 = (int16_t)(calib_buf[2] | (calib_buf[3] << 8));
    calib.dig_T3 = (int16_t)(calib_buf[4] | (calib_buf[5] << 8));
    calib.dig_P1 = (uint16_t)(calib_buf[6] | (calib_buf[7] << 8));
    calib.dig_P2 = (int16_t)(calib_buf[8] | (calib_buf[9] << 8));
    calib.dig_P3 = (int16_t)(calib_buf[10] | (calib_buf[11] << 8));
    calib.dig_P4 = (int16_t)(calib_buf[12] | (calib_buf[13] << 8));
    calib.dig_P5 = (int16_t)(calib_buf[14] | (calib_buf[15] << 8));
    calib.dig_P6 = (int16_t)(calib_buf[16] | (calib_buf[17] << 8));
    calib.dig_P7 = (int16_t)(calib_buf[18] | (calib_buf[19] << 8));
    calib.dig_P8 = (int16_t)(calib_buf[20] | (calib_buf[21] << 8));
    calib.dig_P9 = (int16_t)(calib_buf[22] | (calib_buf[23] << 8));
    if (i2c_write_byte(i2c_handle, BMP280_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set config register.\n");
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int32_t *raw_temp, int32_t *raw_press) {
    if (i2c_write_byte(i2c_handle, BMP280_CTRL_MEAS_REG, BMP280_FORCED_MODE) < 0) return -1;
    gpioDelay(CONVERSION_DELAY_US);
    uint8_t data[6];
    if (i2c_read_block(i2c_handle, BMP280_DATA_REG, data, 6) < 0) return -1;
    *raw_press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) *
                 ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_press) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;
    return p / 100.0;
}

static void log_pressure_breach(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s Pressure: %.2f hPa\n", ts, pressure);
    fclose(fp);
}

static int open_i2c_bus(void) {
    i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %d at addr 0x%02X.\n", I2C_BUS, BMP280_I2C_ADDR);
        return -1;
    }
    return 0;
}

static void close_i2c_bus(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (open_i2c_bus() < 0) {
        gpioTerminate();
        return 1;
    }
    if (bmp280_init() < 0) {
        close_i2c_bus();
        gpioTerminate();
        return 1;
    }
    printf("BMP280 initialized. Monitoring pressure...\n");
    while (running) {
        int32_t raw_temp, raw_press;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !success) {
            if (bmp280_read_raw(&raw_temp, &raw_press) == 0) {
                success = 1;
            } else {
                fprintf(stderr, "Error: I2C read failed (attempt %d/%d).\n", retries + 1, MAX_RETRIES);
                close_i2c_bus();
                gpioDelay(100000);
                if (open_i2c_bus() < 0) {
                    retries++;
                    continue;
                }
                if (bmp280_init() < 0) {
                    retries++;
                    continue;
                }
                retries++;
            }
        }
        if (success) {
            double temp = bmp280_compensate_temp(raw_temp);
            double press = bmp280_compensate_press(raw_press);
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp, press);
            if (press > PRESSURE_HIGH_THRESHOLD || press < PRESSURE_LOW_THRESHOLD) {
                log_pressure_breach(press);
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    close_i2c_bus();
    gpioTerminate();
    return 0;
}

