/*
 * logger.c — Raspberry Pi 4B combined TMP117/AHT20/PIR logger
 *
 * Build: gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 * Run:   ./logger   (user must be in the 'i2c' group or have root)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEV        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_CHIP       "gpiochip4"
#define PIR_OFFSET     17
#define SAMPLE_SEC     1
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* TMP117 (I2C 0x48, reg 0x00, 16-bit big-endian, LSB = 0.0078125 °C) */
/* ------------------------------------------------------------------ */
static int tmp117_read(int fd, float *temp_c)
{
    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) != 1)
        return -1;

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_c = (float)raw * 0.0078125f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* AHT20 (I2C 0x38)
 *   Init:        0xBE 0x08 0x00
 *   Measure:     0xAC 0x33 0x00
 *   Response:    7 bytes, data[0] bit7 = busy, 20-bit temp, 20-bit humidity
 * ------------------------------------------------------------------ */
static int aht20_read(int fd, float *temp_c, float *rh)
{
    static const uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    static const uint8_t meas_cmd[3] = {0xAC, 0x33, 0x00};

    if (write(fd, init_cmd, 3) != 3)
        return -1;
    usleep(10000);

    if (write(fd, meas_cmd, 3) != 3)
        return -1;
    usleep(20000);

    uint8_t buf[7];
    ssize_t n = read(fd, buf, 7);
    if (n != 7)
        return -1;

    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy\n");
        return -1;
    }

    uint32_t t_raw = ((uint32_t)(buf[1] & 0x0F) << 16) |
                     ((uint32_t)buf[2] << 8) |
                     (uint32_t)buf[3];
    uint32_t h_raw = ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];

    *temp_c = 25.0f + (float)t_raw / 1048576.0f * 175.0f;
    *rh    = (float)h_raw / 1048576.0f * 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* libgpiod for PIR on GPIO 17 (gpiochip4)                             */
/* ------------------------------------------------------------------ */
static int pir_read(struct gpiod_line *line)
{
    int v = gpiod_line_get_value(line);
    if (v < 0)
        return -1;
    return v;
}

/* ------------------------------------------------------------------ */
/* CSV helpers                                                         */
/* ------------------------------------------------------------------ */
static void timestamp_str(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

static void new_log_file(char *path, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(path, len, "%Y-%m-%d.csv", &tmv);
}

static int file_exists(const char *path)
{
    return access(path, F_OK) == 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(uint8_t addr)
{
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_DEV ")");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_probe(uint8_t addr)
{
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0)
        return -1;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        close(fd);
        return -1;
    }
    /* Write a zero-length command to check ACK */
    if (write(fd, NULL, 0) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- libgpiod PIR setup ---- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }
    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_OFFSET);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(pir_line, "pir-logger") < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* ---- I2C sensors ---- */
    int tmp117_fd = i2c_open(TMP117_ADDR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "TMP117 not available at 0x%02X\n", TMP117_ADDR);
        tmp117_fd = -1;
    }

    int aht20_fd = i2c_open(AHT20_ADDR);
    if (aht20_fd < 0) {
        fprintf(stderr, "AHT20 not available at 0x%02X\n", AHT20_ADDR);
        aht20_fd = -1;
    }

    /* ---- Log file ---- */
    char log_path[64];
    new_log_file(log_path, sizeof(log_path));
    FILE *log_fp = fopen(log_path, "a");
    if (!log_fp) {
        perror("fopen log");
        goto cleanup;
    }
    if (!file_exists(log_path))
        fprintf(log_fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");

    printf("Logging to %s (Ctrl-C to stop)\n", log_path);

    /* ---- Main loop ---- */
    while (g_running) {
        char ts[32];
        timestamp_str(ts, sizeof(ts));

        float temp_c = 0.0f, rh = 0.0f;
        int tmp_ok = 0, aht_ok = 0, pir_ok = 0;
        int pir_v = 0;

        /* TMP117 */
        if (tmp117_fd >= 0) {
            for (int r = 0; r < MAX_RETRIES; r++) {
                if (tmp117_read(tmp117_fd, &temp_c) == 0) {
                    tmp_ok = 1;
                    break;
                }
                usleep(RETRY_DELAY_US);
            }
        }

        /* AHT20 */
        if (aht20_fd >= 0) {
            for (int r = 0; r < MAX_RETRIES; r++) {
                if (aht20_read(aht20_fd, &temp_c, &rh) == 0) {
                    aht_ok = 1;
                    break;
                }
                usleep(RETRY_DELAY_US);
            }
        }

