/*
 * Rain-activated window controller for Raspberry Pi 5.
 *
 * Hardware:
 *   - YL-83 rain sensor  -> GPIO17 (active-low digital output)
 *   - L298N motor driver -> ENA=GPIO22, IN1=GPIO23, IN2=GPIO24
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lgpiod
 *
 * Run:
 *   sudo ./rain_window
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN  17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

#define POLL_INTERVAL_SEC  2
#define MOTOR_RUN_SEC      5

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    time_t now = time(NULL);
    char ts[32];
    struct tm tmv;

    if (localtime_r(&now, &tmv) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static int motor_set(struct gpiod_line *ena, struct gpiod_line *in1,
                     struct gpiod_line *in2, int en, int d1, int d2)
{
    if (gpiod_line_set_value(ena, en) < 0) {
        perror("gpiod_line_set_value(ENA)");
        return -1;
    }
    if (gpiod_line_set_value(in1, d1) < 0) {
        perror("gpiod_line_set_value(IN1)");
        return -1;
    }
    if (gpiod_line_set_value(in2, d2) < 0) {
        perror("gpiod_line_set_value(IN2)");
        return -1;
    }
    return 0;
}

static int motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                      struct gpiod_line *in2)
{
    return motor_set(ena, in1, in2, 0, 0, 0);
}

static int motor_run_forward(struct gpiod_line *ena, struct gpiod_line *in1,
                             struct gpiod_line *in2)
{
    return motor_set(ena, in1, in2, 1, 1, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /* Open the default GPIO chip (gpiochip4 on Raspberry Pi 5). */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        /* Fall back to gpiochip0 on older Pi models. */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (rain_line == NULL || ena_line == NULL ||
        in1_line == NULL || in2_line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request rain sensor line as input. */
    if (gpiod_line_request_input(rain_line, "rain_window") < 0) {
        perror("gpiod_line_request_input(rain)");
        goto cleanup;
    }

    /* Request motor control lines as outputs, initial value LOW. */
    if (gpiod_line_request_output(ena_line, "rain_window", 0) < 0) {
        perror("gpiod_line_request_output(ENA)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "rain_window", 0) < 0) {
        perror("gpiod_line_request_output(IN1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "rain_window", 0) < 0) {
        perror("gpiod_line_request_output(IN2)");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started.");

    while (g_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            perror("gpiod_line_get_value(rain)");
            break;
        }

        /* YL-83 is active-low: 0 => rain detected. */
        if (val == 0) {
            log_event("Rain detected! Closing window.");

            if (motor_run_forward(ena_line, in1_line, in2_line) < 0) {
                log_event("Failed to start motor.");
                break;
            }

            /* Run for MOTOR_RUN_SEC seconds, checking for shutdown. */
            for (int i = 0; i < MOTOR_RUN_SEC && g_running; i++) {
                sleep(1);
            }

            if (motor_stop(ena_line, in1_line, in2_line) < 0) {
                log_event("Failed to stop motor.");
                break;
            }
            log_event("Window closed.");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    log_event("Shutting down.");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure motor is stopped before releasing lines. */
    if (ena_line != NULL && in1_line != NULL && in2_line != NULL) {
        (void)motor_stop(ena_line, in1_line, in2_line);
    }

    if (rain_line != NULL) gpiod_line_release(rain_line);
    if (ena_line  != NULL) gpiod_line_release(ena_line);
    if (in1_line  != NULL) gpiod_line_release(in1_line);
    if (in2_line  != NULL) gpiod_line_release(in2_line);
    if (chip      != NULL) gpiod_chip_close(chip);

    return ret;
}

