#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on SIGINT / SIGTERM             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the 1-line /proc/stat "cpu" line and return the total          */
/* CPU-time delta between two calls.  Returns -1.0 on error.           */
/* ------------------------------------------------------------------ */
static double read_cpu_time(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen(\"/proc/stat\")");
        return -1.0;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int rc = fscanf(fp,
                    "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                    &user, &nice, &system, &idle, &iowait, &irq, &softirq,
                    &steal, &guest, &guest_nice);
    fclose(fp);

    if (rc != 10) {
        fprintf(stderr, "fscanf failed on /proc/stat\n");
        return -1.0;
    }

    return (double)(user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice);
}

/* ------------------------------------------------------------------ */
/* Compute the CPU load as a fraction in [0.0, 1.0].                   */
/* ------------------------------------------------------------------ */
static double calculate_cpu_load(double now_total, double prev_total)
{
    if (prev_total < 0.0 || now_total < 0.0)
        return 0.0;

    double total_delta = now_total - prev_total;
    if (total_delta <= 0.0)
        return 0.0;

    /*
     * The "idle" field in /proc/stat is the time the CPU spent idle
     * *after* servicing interrupts.  So the busy time is the total minus
     * idle.
     */
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen(\"/proc/stat\")");
        return 0.0;
    }

    unsigned long long idle;
    int rc = fscanf(fp, "cpu  %*llu %*llu %*llu %llu %*llu %*llu %*llu %*llu %*llu %*llu", &idle);
    fclose(fp);

    if (rc != 1) {
        fprintf(stderr, "fscanf failed on /proc/stat (idle)\n");
        return 0.0;
    }

    double idle_delta = (now_total - idle) - (prev_total - idle);
    if (idle_delta < 0.0)
        idle_delta = 0.0;

    double busy_delta = total_delta - idle_delta;
    if (busy_delta < 0.0)
        busy_delta = 0.0;

    return busy_delta / total_delta;
}

/* ------------------------------------------------------------------ */
/* Map load (0.0–1.0) onto RGB values for a common-anode LED.          */
/* ------------------------------------------------------------------ */
static void map_load_to_color(double load, int *r, int *g, int *b)
{
    if (load < 0.0) load = 0.0;
    if (load > 1.0) load = 1.0;

    if (load < 0.5) {
        /* Green -> Yellow */
        *r = (int)(load * 2.0 * 255.0);
        *g = 255;
        *b = 0;
    } else {
        /* Yellow -> Red */
        *r = 255;
        *g = (int)((1.0 - (load - 0.5) * 2.0) * 255.0);
        *b = 0;
    }

    if (*r < 0) *r = 0;
    if (*g < 0) *g = 0;
    if (*b < 0) *b = 0;
    if (*r > 255) *r = 255;
    if (*g > 255) *g = 255;
    if (*b > 255) *b = 255;
}

/* ------------------------------------------------------------------ */
/* Set a common-anode LED's color using pigpio hardware PWM.           */
/* ------------------------------------------------------------------ */
static void set_led_color(int r, int g, int b)
{
    /*
     * Common-anode LED: higher PWM duty cycle means the cathode is
     * more negatively biased and the LED appears brighter.  So we
     * invert the raw RGB values before writing them.
     */
    int ir = 255 - r;
    int ig = 255 - g;
    int ib = 255 - b;

    if (gpioPWM(RED_PIN,   ir) < 0)
        fprintf(stderr, "gpioPWM(RED)   failed\n");
    if (gpioPWM(GREEN_PIN, ig) < 0)
        fprintf(stderr, "gpioPWM(GREEN) failed\n");
    if (gpioPWM(BLUE_PIN,  ib) < 0)
        fprintf(stderr, "gpioPWM(BLUE)  failed\n");
}

/* ------------------------------------------------------------------ */
/* Turn the LED off (common-anode: drive all channels to full off).    */
/* ------------------------------------------------------------------ */
static void led_off(void)
{
    gpioPWM(RED_PIN,   255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN,  255);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- PWM range ---- */
    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Ensure LED is off at start ---- */
    led_off();

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initial sample ---- */
    double prev_total = read_cpu_time();
    if (prev_total < 0.0) {
        fprintf(stderr, "Initial CPU time read failed\n");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        double now_total = read_cpu_time();
        if (now_total < 0.0) {
            fprintf(stderr, "CPU time read failed; retrying\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        double load = calculate_cpu_load(now_total, prev_total);
        prev_total = now_total;

        int r, g, b;
        map_load_to_color(load, &r, &g, &b);
        set_led_color(r, g, b);

        usleep(SAMPLE_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

