        fprintf(stderr, "Failed to read chip ID\n");
        cleanup();
        return 1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        cleanup();
