        if (read_bmp280_data(i2c_handle, &temperature, &pressure) == 0) {
            char json_data[256];
            snprintf(json_data, sizeof(json_data), "{\"temperature\":%.2f,\"pressure\":%.2f}", temperature, pressure);
            if (send_udp_data(json_data) < 0) {
                fprintf(stderr, "Failed to send UDP data: %s\n", strerror(errno));
            } else {
                printf("Sent: %s\n", json_data);
            }
        } else {
            fprintf(stderr, "Failed to read BMP280 data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

