#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   500000
#define FAN_GPIO    18
#define PWM_FREQ    1000
#define PWM_RANGE   255
#define BUFFER_SIZE 20
#define SAMPLE_US   1000000

#define TEMP_MIN 25.0
#define TEMP_MAX 60.0

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      spi_handle   = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_max31855(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: spiXfer returned %d: %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X)\n", raw);
        if (raw & 0x00000001) fprintf(stderr, "  Open circuit\n");
        if (raw & 0x00000002) fprintf(stderr, "  Short to GND\n");
        if (raw & 0x00000004) fprintf(stderr, "  Short to VCC\n");
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_fan_speed(float temperature) {
    if (temperature < TEMP_MIN) return 0;
    if (temperature >= TEMP_MAX) return PWM_RANGE;

    if (temperature < 40.0f) {
        return (int)((temperature - TEMP_MIN) / (40.0f - TEMP_MIN) * 50.0f);
    }
    return (int)((temperature - 40.0f) / (TEMP_MAX - 40.0f) * 150.0f) + 50;
}

static void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp   = now;
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle  = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&log_buffer[idx].timestamp);
        if (tm) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        } else {
            snprintf(ts, sizeof(ts), "---");
        }
        printf("[%s] Temp: %.2f C, Duty: %d\n",
               ts, log_buffer[idx].temperature, log_buffer[idx].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioPWM initial stop failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(&temperature) == 0) {
            int duty = calculate_fan_speed(temperature);
            if (gpioPWM(FAN_GPIO, duty) != 0) {
                fprintf(stderr, "Error: gpioPWM set failed for duty %d\n", duty);
            }
            log_data(temperature, duty);
            printf("Temp: %.2f C, Duty: %d\n", temperature, duty);
        } else {
            fprintf(stderr, "Skipping fan update due to sensor error.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    print_log_buffer();
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

