    uint8_t regs[7] = {BMP180_REG_AC1, BMP180_REG_AC2, BMP180_REG_AC3,
                       BMP180_REG_B1, BMP180_REG_B2, BMP180_REG_MB,
                       BMP180_REG_MC};
