        uint8_t buf[2];
        if (i2cReadI2CBlockData(i2c_handle, regs[i], (char *)buf, 2) != 2) {
            fprintf(stderr, "Error reading calibration data at reg 0x%02X\n", regs[i]);
            return -1;
