#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define CS_LINE 8
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

#define MAX31865_CONFIG_VBIAS 0x80
#define MAX31865_CONFIG_3WIRE 0x00
#define MAX31865_CONFIG_FAULT 0x01

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error: Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};

    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }

    *value = rx[1];
    return 0;
}

static int write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = {0};

    return spi_transfer(tx, rx, 2);
}

static int init_max31865(void) {
    uint8_t config = MAX31865_CONFIG_VBIAS | MAX31865_CONFIG_3WIRE | MAX31865_CONFIG_FAULT;

    if (write_register(MAX31865_CONFIG_REG, config) < 0) {
        fprintf(stderr, "Error: Failed to write MAX31865 config register\n");
        return -1;
    }

    usleep(10000);

    uint8_t val = 0;
    if (read_register(MAX31865_CONFIG_REG, &val) < 0) {
        fprintf(stderr, "Error: Failed to read back MAX31865 config register\n");
        return -1;
    }

    if (val != config) {
        fprintf(stderr, "Error: MAX31865 config verification failed (0x%02X != 0x%02X)\n", val, config);
        return -1;
    }

    return 0;
}

static int read_rtd_data(uint16_t *rtd_raw) {
    uint8_t msb = 0, lsb = 0;

    if (read_register(MAX31865_RTD_MSB_REG, &msb) < 0) {
        return -1;
    }
    if (read_register(MAX31865_RTD_LSB_REG, &lsb) < 0) {
        return -1;
    }

    *rtd_raw = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_fault_status(uint8_t *fault) {
    return read_register(MAX31865_FAULT_REG, fault);
}

static float calculate_temperature(uint16_t rtd_raw) {
    float rtd_resistance = (float)rtd_raw * 0.4365f;
    float a = 3.9083e-3f;
    float b = -5.775e-7f;
    float c = 1.675e-7f;
    float d = -1.124e-10f;
    float e = 1.015e-13f;

    float rtd_temp = a + b * rtd_resistance + c * rtd_resistance * rtd_resistance +
                     d * rtd_resistance * rtd_resistance * rtd_resistance +
                     e * rtd_resistance * rtd_resistance * rtd_resistance * rtd_resistance;

    return rtd_temp;
}

static void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: Failed to set signal handlers");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        perror("Error: Failed to open gpiochip0");
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE);
    if (cs_line == NULL) {
        perror("Error: Failed to get CS line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "max31865_cs", 1) < 0) {
        perror("Error: Failed to request CS line as output");
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error: Failed to open SPI device");
        cleanup();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error: Failed to configure SPI");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    if (init_max31865() < 0) {
        fprintf(stderr, "Error: MAX31865 initialization failed\n");
        log_error("MAX31865 initialization failed");
        cleanup();
        return 1;
    }

    printf("MAX31865 initialized. Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL);

    while (running) {
        uint16_t rtd_raw = 0;
        uint8_t fault = 0;
        int rtd_ok = 0;
        int fault_ok = 0;

        if (read_rtd_data(&rtd_raw) == 0) {
            rtd_ok = 1;
        } else {
            fprintf(stderr, "Error: Failed to read RTD data\n");
            log_error("SPI read error (RTD)");
        }

        if (read_fault_status(&fault) == 0) {
            fault_ok = 1;
        } else {
            fprintf(stderr, "Error: Failed to read fault status\n");
            log_error("SPI read error (fault)");
        }

        if (rtd_ok && fault_ok) {
            if (fault & 0x01) {
                fprintf(stderr, "Warning: MAX31865 fault detected (0x%02X)\n", fault);
                log_error("MAX31865 fault detected");
            } else {
                float temperature = calculate_temperature(rtd_raw);
                log_data(temperature);
                printf("Temperature: %.2f C\n", temperature);
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

