#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"
#define BME280_CHIP_ID 0x60

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

static volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    uint16_t dig_T1; int16_t dig_T2; int16_t dig_T3;
    uint16_t dig_P1; int16_t dig_P2; int16_t dig_P3;
    int16_t dig_P4; int16_t dig_P5; int16_t dig_P6;
    int16_t dig_P7; int16_t dig_P8; int16_t dig_P9;
    uint8_t dig_H1; int16_t dig_H2; uint8_t dig_H3;
    int16_t dig_H4; int16_t dig_H5; int8_t dig_H6;
} bme280_calib_data;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration_data(int fd, bme280_calib_data *cal) {
    uint8_t buf[26];
    if (i2c_read_reg(fd, BME280_REG_CALIB_00, buf, 26) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    cal->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    cal->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    cal->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    cal->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    cal->dig_H1 = buf[25];

    uint8_t h_buf[7];
    if (i2c_read_reg(fd, BME280_REG_CALIB_26, h_buf, 7) < 0) return -1;
    cal->dig_H2 = (int16_t)(h_buf[0] | (h_buf[1] << 8));
    cal->dig_H3 = h_buf[2];
    cal->dig_H4 = (int16_t)((h_buf[3] << 4) | (h_buf[4] & 0x0F));
    cal->dig_H5 = (int16_t)((h_buf[5] << 4) | (h_buf[4] >> 4));
    cal->dig_H6 = (int8_t)h_buf[6];
    return 0;
}

static int32_t t_fine;

static int32_t compensate_temperature(int32_t adc_T, const bme280_calib_data *cal) {
    int32_t var1 = ((((adc_T >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    int32_t var2 = (((((adc_T >> 4) - ((int32_t)cal->dig_T1)) * ((adc_T >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
