static uint32_t compensate_pressure(int32_t adc_P, const bme280_calib_data *cal) {
    int32_t var1 = (t_fine >> 1) - 64000;
    int32_t var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)cal->dig_P6);
    var2 = var2 + ((var1 * ((int32_t)cal->dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)cal->dig_P4) << 16);
    var1 = (((((var1 >> 2) * (var1 >> 2)) >> 13) * ((int32_t)cal->dig_P3)) >> 3) + ((((var1 * ((int32_t)cal->dig_P2)) >> 1) >> 1));
    var1 = (((32768 + var1) * ((int32_t)cal->dig_P1)) >> 15);
    if (var1 == 0) return 0;
    uint32_t p = (((uint32_t)(((1048576 - adc_P) - (var2 >> 12))) * 3125) / (uint32_t)var1);
    var1 = (((int32_t)cal->dig_P9) * (int32_t)((p >> 3) * (p >> 3))) >> 13;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)cal->dig_P8)) >> 13;
