static int read_bme280_data(int fd, const bme280_calib_data *cal, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_reg(fd, BME280_REG_DATA, data, 8) < 0) return -1;
    int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t adc_H = (data[6] << 8) | data[7];
    int32_t t = compensate_temperature(adc_T, cal);
    uint32_t p = compensate_pressure(adc_P, cal);
    uint32_t h = compensate_humidity(adc_H, cal);
    *temp = t / 100.0f;
    *press = p / 256.0f / 100.0f;
    *hum = h / 1024.0f;
    return 0;
}

int main() {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read_reg(fd, BME280_REG_ID, &chip_id, 1) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present.\n", chip_id, BME280_CHIP_ID);
        close(fd);
        return 1;
    }

    bme280_calib_data cal;
    if (read_calibration_data(fd, &cal) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(2000);

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error setting humidity oversampling: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error setting config register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error setting ctrl_meas register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }

    while (running) {
        uint8_t status;
        int timeout = 0;
        do {
            if (i2c_read_reg(fd, BME280_REG_STATUS, &status, 1) < 0) {
                fprintf(stderr, "Error reading status register: %s\n", strerror(errno));
                break;
            }
            usleep(2000);
            timeout++;
        } while ((status & 0x08) && timeout < 50 && running);

        if (!running) break;
        if (timeout >= 50) {
            fprintf(stderr, "Error: Data conversion timeout.\n");
            continue;
        }

        float temp, hum, press;
        if (read_bme280_data(fd, &cal, &temp, &hum, &press) < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temp, hum, press);
        fflush(fp);
        printf("%s,%.2f,%.2f,%.2f\n", timestamp, temp, hum, press);

        for (int i = 0; i < 50 && running; i++) {
            usleep(100000);
        }
    }

    fclose(fp);
    close(fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

