#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 50
#define ALERT_THRESHOLD 5.0f
#define OSS 0

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_START 0xAA

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

typedef struct {
    float pressure;
    time_t timestamp;
} PressureData;

static PressureData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int16_t *s16[7] = {&ac1, &ac2, &ac3, (int16_t *)&b1, (int16_t *)&b2, &mb, &mc};
    uint16_t *u16[2] = {&ac4, &ac5};
    int regs[9] = {0xAA, 0xAC, 0xAE, 0xB0, 0xB2, 0xB4, 0xB6, 0xB8, 0xBA};

    for (int i = 0; i < 7; i++) {
        int hi = i2cReadByteData(i2c_handle, regs[i]);
        int lo = i2cReadByteData(i2c_handle, regs[i] + 1);
        if (hi < 0 || lo < 0) {
            fprintf(stderr, "Error reading calibration data at reg 0x%02X\n", regs[i]);
            return -1;
        }
        *s16[i] = (int16_t)((hi << 8) | lo);
    }
    for (int i = 0; i < 2; i++) {
        int hi = i2cReadByteData(i2c_handle, regs[7 + i]);
        int lo = i2cReadByteData(i2c_handle, regs[7 + i] + 1);
        if (hi < 0 || lo < 0) {
            fprintf(stderr, "Error reading calibration data at reg 0x%02X\n", regs[7 + i]);
            return -1;
        }
        *u16[i] = (uint16_t)((hi << 8) | lo);
    }
    if (md == 0) {
        fprintf(stderr, "Calibration data invalid (md=0)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int hi = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lo = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (hi < 0 || lo < 0) return -1;
    *ut = (int32_t)((hi << 8) | lo);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 2);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << OSS) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void add_to_buffer(float pressure) {
    circular_buffer[buffer_index].pressure = pressure;
    circular_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static float calculate_average_pressure(void) {
    float sum = 0.0f;
    int count = 0;
    time_t now = time(NULL);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (circular_buffer[i].timestamp > 0 && (now - circular_buffer[i].timestamp) <= 60) {
            sum += circular_buffer[i].pressure;
            count++;
        }
    }
    if (count == 0) return 0.0f;
    return sum / count;
}

static void check_pressure_alert(float current_pressure, float average_pressure) {
    if (average_pressure == 0.0f) return;
    float diff = current_pressure - average_pressure;
    if (diff > ALERT_THRESHOLD || diff < -ALERT_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(1000000);
        gpioWrite(ALERT_GPIO, 0);
        printf("ALERT: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa\n", current_pressure, average_pressure);
    }
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    add_to_buffer(pressure);
    float avg = calculate_average_pressure();
    check_pressure_alert(pressure, avg);
    printf("Pressure: %.2f hPa, Average: %.2f hPa\n", pressure, avg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error setting timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 pressure monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100000);
    }
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

