    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (double)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    if (!running) return;
    int32_t ut, up;
    if (read_raw_temp(i2c_handle, &ut) < 0) {
