#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int calculate_duty(int temp_milli) {
    if (temp_milli < 0) return 0;
    double temp_c = temp_milli / 1000.0;
    if (temp_c <= TEMP_MIN) return 0;
    if (temp_c >= TEMP_MAX) return PWM_RANGE;
    return (int)(((temp_c - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * PWM_RANGE);
}

static void log_data(int temp_milli, int duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    double temp_c = temp_milli < 0 ? -1.0 : temp_milli / 1000.0;
    if (log_fp) {
        fprintf(log_fp, "%s, Temp: %.2f C, Duty: %d\n", ts, temp_c, duty);
        fflush(log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        gpioTerminate();
        return 1;
    }

    while (running) {
        int temp_milli = read_cpu_temp();
        int duty = calculate_duty(temp_milli);
        gpioPWM(FAN_GPIO, duty);
        log_data(temp_milli, duty);
        sleep(POLL_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return 0;
}

