#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define LM75_TEMP_REG  0x00
#define LED_PIN        18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    float sum;
    pthread_mutex_t lock;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    cb->sum = 0.0f;
    pthread_mutex_init(&cb->lock, NULL);
}

static void cb_add(CircularBuffer *cb, float value) {
    pthread_mutex_lock(&cb->lock);
    cb->sum -= cb->buffer[cb->head];
    cb->buffer[cb->head] = value;
    cb->sum += value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->lock);
}

static float cb_average(CircularBuffer *cb) {
    float avg = 0.0f;
    pthread_mutex_lock(&cb->lock);
    if (cb->count > 0) avg = cb->sum / (float)cb->count;
    pthread_mutex_unlock(&cb->lock);
    return avg;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out = raw;
    return 0;
}

static int i2c_open(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", LM75_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static void *data_thread(void *arg) {
    CircularBuffer *cb = (CircularBuffer *)arg;
    int fd = i2c_open();
    if (fd < 0) {
        fprintf(stderr, "Initial I2C open failed; will retry.\n");
        pthread_exit(NULL);
    }
    while (running) {
        int16_t raw;
        if (i2c_read_reg16(fd, LM75_TEMP_REG, &raw) == 0) {
            float temp = (float)raw / 256.0f;
            cb_add(cb, temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            close(fd);
            fd = i2c_open();
            if (fd < 0) {
                fprintf(stderr, "Re-init failed; retrying next cycle.\n");
            }
        }
        sleep(POLL_INTERVAL);
    }
    close(fd);
    pthread_exit(NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    CircularBuffer cb;
    pthread_t tid;
    int ret = 1;

    cb_init(&cb);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        goto cleanup;
    }
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (pthread_create(&tid, NULL, data_thread, &cb) != 0) {
        fprintf(stderr, "pthread_create: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        float avg = cb_average(&cb);
        printf("Running Average: %.2f C\n", avg);
        if (avg > TEMP_THRESHOLD) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }
        sleep(POLL_INTERVAL);
    }

    ret = 0;

cleanup:
    running = 0;
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    pthread_mutex_destroy(&cb.lock);
    return ret;
}

