        if (i2c_read_reg16(fd, LM75_TEMP_REG, &raw) == 0) {
            float temp = (float)raw / 256.0f;
            cb_add(cb, temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            close(fd);
            fd = i2c_open();
            if (fd < 0) {
                fprintf(stderr, "Re-init failed; retrying next cycle.\n");
            }
        }
        sleep(POLL_INTERVAL);
    }
    close(fd);
    pthread_exit(NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    CircularBuffer cb;
    pthread_t tid;
    int ret = 1;

    cb_init(&cb);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        goto cleanup;
    }
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (pthread_create(&tid, NULL, data_thread, &cb) != 0) {
        fprintf(stderr, "pthread_create: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        float avg = cb_average(&cb);
        printf("Running Average: %.2f C\n", avg);
        if (avg > TEMP_THRESHOLD) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }
        sleep(POLL_INTERVAL);
    }

    ret = 0;

cleanup:
    running = 0;
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    pthread_mutex_destroy(&cb.lock);
    return ret;
}

