#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define MAX_RTD_RESISTANCE 100.0
#define R_REF 430.0
#define A 0.0039083
#define B -0.0000005775
#define FAILSAFE_TEMP 80.0
#define CONFIG_FILE "config.json"

#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    double target_temperature;
    double Kp;
    double Ki;
    double Kd;
} Config;

static Config config = {25.0, 1.0, 0.1, 0.01};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = {(char)(reg & 0x7F), (char)value};
    char rx[2] = {0, 0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = {(char)(reg | 0x80), 0x00};
    char rx[2] = {0, 0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int max31865_init(void) {
    if (spi_write_reg(MAX31865_CONFIG_REG, 0xC1) != 0) {
        fprintf(stderr, "MAX31865 init failed\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int max31865_read_rtd_code(uint16_t *code) {
    uint8_t msb, lsb;
    if (spi_read_reg(MAX31865_RTD_MSB_REG, &msb) != 0) return -1;
    if (spi_read_reg(MAX31865_RTD_LSB_REG, &lsb) != 0) return -1;
    *code = ((uint16_t)(msb & 0xFF) << 8) | (uint16_t)(lsb & 0xFF);
    return 0;
}

static int max31865_check_fault(void) {
    uint8_t fault;
    if (spi_read_reg(MAX31865_FAULT_REG, &fault) != 0) return -1;
    if (fault & 0x01) { fprintf(stderr, "MAX31865 fault: open circuit\n"); return -1; }
    if (fault & 0x02) { fprintf(stderr, "MAX31865 fault: short to GND\n"); return -1; }
    if (fault & 0x04) { fprintf(stderr, "MAX31865 fault: short to VCC\n"); return -1; }
    if (fault & 0x08) { fprintf(stderr, "MAX31865 fault: over-voltage\n"); return -1; }
    if (fault & 0x10) { fprintf(stderr, "MAX31865 fault: under-voltage\n"); return -1; }
    return 0;
}

static double rtd_code_to_temperature(uint16_t code) {
    double rtd_resistance = ((double)code / 32768.0) * R_REF;
    if (rtd_resistance <= 0.0) return 0.0;
    double t = (rtd_resistance - MAX_RTD_RESISTANCE) / (A * MAX_RTD_RESISTANCE + B * MAX_RTD_RESISTANCE * MAX_RTD_RESISTANCE);
    if (t < 0.0) return 0.0;
    return t;
}

static int load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: config file %s not found, using defaults\n", filename);
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, "target_temperature")) {
            sscanf(line, "\"target_temperature\": %lf", &config.target_temperature);
        } else if (strstr(line, "Kp")) {
            sscanf(line, "\"Kp\": %lf", &config.Kp);
        } else if (strstr(line, "Ki")) {
            sscanf(line, "\"Ki\": %lf", &config.Ki);
        } else if (strstr(line, "Kd")) {
            sscanf(line, "\"Kd\": %lf", &config.Kd);
        }
    }
    fclose(fp);
    printf("Config loaded: target=%.2f Kp=%.3f Ki=%.3f Kd=%.3f\n",
           config.target_temperature, config.Kp, config.Ki, config.Kd);
    return 0;
}

static void set_heater_pwm(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty);
}

static void cleanup(void) {
    set_heater_pwm(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_pwm(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (max31865_init() != 0) {
        fprintf(stderr, "MAX31865 init failed\n");
        cleanup();
        return 1;
    }

    load_config(CONFIG_FILE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double integral = 0.0;
    double prev_error = 0.0;

    while (running) {
        uint16_t rtd_code = 0;
        if (max31865_read_rtd_code(&rtd_code) != 0) {
            fprintf(stderr, "SPI read error\n");
            set_heater_pwm(0);
            break;
        }

        if (max31865_check_fault() != 0) {
            set_heater_pwm(0);
            break;
        }

        double temperature = rtd_code_to_temperature(rtd_code);
        if (temperature > FAILSAFE_TEMP) {
            fprintf(stderr, "FAILSAFE: temperature %.2f > %.1f\n", temperature, FAILSAFE_TEMP);
            set_heater_pwm(0);
            break;
        }

        double error = config.target_temperature - temperature;
        integral += error;
        double derivative = error - prev_error;
        double output = config.Kp * error + config.Ki * integral + config.Kd * derivative;

        if (output < 0) output = 0;
        if (output > PWM_RANGE) output = PWM_RANGE;

        set_heater_pwm((int)output);
        prev_error = error;

        printf("T=%.2f target=%.2f duty=%.1f%%\n", temperature, config.target_temperature, output / PWM_RANGE * 100.0);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

