#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x74
#define BMP180_CMD_PRESSURE2 0xB4

#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int i = 0; i < 3; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        if (errno == EINTR) continue;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int i = 0; i < 3; i++) {
        if (write(fd, &reg, 1) == 1 && read(fd, buf, len) == len) return 0;
        if (errno == EINTR) continue;
        usleep(10000);
    }
    return -1;
}

static int read_calibration(int fd, bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2c_read_reg(fd, 0xAA, buf, 22) != 0) return -1;
    cal->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_reg(fd, BMP180_REG_MSB, buf, 2) != 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0) != 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_reg(fd, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> 8;
    return 0;
}

static int calc_temp(int32_t ut, const bmp180_cal_t *c, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    return (b5 + 8) >> 4;
}

static int calc_pressure(int32_t up, int32_t b5, const bmp180_cal_t *c) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)c->ac1 * 4 + x3) << 3) / 4;
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_breach(float temp, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Temp: %.2f C, Pressure: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c"); return 1; }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(fd, &cal) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data.\n");
        close(fd);
        return 1;
    }

    while (running) {
        int32_t ut, up, b5;
        if (read_raw_temp(fd, &ut) != 0 || read_raw_pressure(fd, &up) != 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        int32_t temp_c = calc_temp(ut, &cal, &b5);
        int32_t pressure_pa = calc_pressure(up, b5, &cal);

        float temp_f = temp_c / 10.0f;
        float pressure_hpa = pressure_pa / 100.0f;

        if (temp_f > TEMP_THRESHOLD || pressure_hpa < PRESSURE_THRESHOLD) {
            log_breach(temp_f, pressure_hpa);
        }

        sleep(1);
    }

    close(fd);
    return 0;
}

