/*
 * BMP180 pressure/temperature monitor with fan control.
 *
 * Board:  Raspberry Pi 4 Model B
 * I2C:    /dev/i2c-1, BMP180 @ 0x77
 * Fan:    GPIO18 (active-high)
 *
 * Build:  gcc -O2 -Wall -o bmp180_fan bmp180_fan.c -lpigpio -lrt
 * Run:    sudo ./bmp180_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants --------------------------------------------------- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_WORDS        11
#define BMP180_OSS              0
#define BMP180_TEMP_CMD         0x2E
#define BMP180_PRESS_CMD        (0x34 + (BMP180_OSS << 6))
#define BMP180_TEMP_MSB_DELAY   5   /* ms */
#define BMP180_PRESS_MSB_DELAY  5   /* ms */

/* ---- Fan / timing ------------------------------------------------------- */
#define FAN_GPIO                18
#define TEMP_THRESHOLD          30.0f
#define SAMPLE_PERIOD_US        500000  /* 500 ms */
#define BUFFER_SIZE             60
#define TIMER_ID                0

/* ---- Data structures ---------------------------------------------------- */
typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_fan_state  = 0;
static circular_buffer_t g_buffer;

/* BMP180 calibration coefficients (read once at init) */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* ---- Prototypes --------------------------------------------------------- */
static void signal_handler(int sig);
static void timer_callback(void *userdata);
static int  read_calibration(void);
static int  read_raw_temperature(int32_t *ut);
static int  read_raw_pressure(int32_t *up);
static float calculate_temperature(int32_t ut, int32_t *b5_out);
static float calculate_pressure(int32_t up, int32_t b5);
static void buffer_add(time_t ts, float temp, float press);
static void fan_set(int on);
static void cleanup(void);

/* ========================================================================= */
int main(void)
{
    /* --- pigpio init ------------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------------- */
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO setup --------------------------------------------------- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(FAN_GPIO) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    fan_set(0);

    /* --- Calibration ------------------------------------------------------ */
    if (read_calibration() != 0) {
        fprintf(stderr, "Error: BMP180 calibration read failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Circular buffer -------------------------------------------------- */
    g_buffer.head  = 0;
    g_buffer.count = 0;

    /* --- Signal handlers -------------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Timer start ------------------------------------------------------ */
    if (gpioSetTimerFuncEx(TIMER_ID, SAMPLE_PERIOD_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitoring started. Sampling every 500 ms. Ctrl+C to exit.\n");
    return EXIT_SUCCESS;
}

/* ========================================================================= */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ========================================================================= */
static void timer_callback(void *userdata)
{
    (void)userdata;

    int32_t ut = 0, up = 0, b5 = 0;
    float   temp = 0.0f, press = 0.0f;
    bool    ok = true;

    /* --- Temperature ------------------------------------------------------ */
    if (read_raw_temperature(&ut) != 0) {
        ok = false;
    } else {
        temp = calculate_temperature(ut, &b5);
    }

    /* --- Pressure --------------------------------------------------------- */
    if (ok && read_raw_pressure(&up) != 0) {
        ok = false;
    } else if (ok) {
        press = calculate_pressure(up, b5);
    }

    /* --- Buffer ----------------------------------------------------------- */
    if (ok) {
        buffer_add(time(NULL), temp, press);
    }

    /* --- Fan control ------------------------------------------------------ */
    if (ok && temp > TEMP_THRESHOLD) {
        fan_set(1);
    } else {
        fan_set(0);
    }
}

/* ========================================================================= */
static int read_calibration(void)
{
    uint8_t buf[BMP180_CAL_WORDS * 2];

    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_CAL_START,
                           (char *)buf, sizeof(buf)) != (int)sizeof(buf)) {
        fprintf(stderr, "Error: failed to read BMP180 calibration block.\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    /* Sanity: AC1 should never be 0 or 0xFFFF on a real BMP180 */
    if (ac1 == 0 || ac1 == (int16_t)0xFFFF) {
        fprintf(stderr, "Error: calibration data looks invalid (AC1=0x%04X).\n",
                (unsigned)(uint16_t)ac1);
        return -1;
    }
    return 0;
}

/* ========================================================================= */
static int read_raw_temperature(int32_t *ut)
{
    uint8_t cmd = BMP180_TEMP_CMD;
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWrite(temp cmd) failed.\n");
        return -1;
    }
    gpioDelay(BMP180_TEMP_MSB_DELAY * 1000);

    uint8_t buf[2];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: i2cRead(temp data) failed.\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ========================================================================= */
static int read_raw_pressure(int32_t *up)
{
    uint8_t cmd = BMP180_PRESS_CMD;
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWrite(press cmd) failed.\n");
        return -1;
    }
    gpioDelay(BMP180_PRESS_MSB_DELAY * 1000);

    uint8_t buf[3];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: i2cRead(press data) failed.\n");
        return -1;
    }
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

/* ========================================================================= */
static float calculate_temperature(int32_t ut, int32_t *b5_out)
{
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    return ((b5 + 8) >> 4) / 10.0f;
}

/* ========================================================================= */
static float calculate_pressure(int32_t up, int32_t b5)
{
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

/* ========================================================================= */
static void buffer_add(time_t ts, float temp, float press)
{
    sensor_data_t *d = &g_buffer.data[g_buffer.head];
    d->timestamp  = ts;
    d->temperature = temp;
    d->pressure    = press;
    g_buffer.head = (g_buffer.head + 1) % BUFFER_SIZE;
    if (g_buffer.count < BUFFER_SIZE) g_buffer.count++;
}

/* ========================================================================= */
static void fan_set(int on)
{
    if (on != g_fan_state) {
        if (gpioWrite(FAN_GPIO, on ? 1 : 0) < 0) {
            fprintf(stderr, "Warning: gpioWrite(FAN) failed.\n");
        } else {
            g_fan_state = on;
            printf("Fan %s\n", on ? "ON" : "OFF");
        }
    }
}

/* ========================================================================= */
static void cleanup(void)
{
    /* Stop timer first so no callback fires during teardown */
    gpioSetTimerFuncEx(TIMER_ID, 0, NULL, NULL);

    fan_set(0);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

