    c->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    c->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    c->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    c->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    c->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    c->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    c->mb = (int16_t)((buf[16] << 8) | buf[17]);
    c->mc = (int16_t)((buf[18] << 8) | buf[19]);
    c->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    uint8_t cmd = BMP180_CMD_PRESSURE0;
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, cmd) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 3) != 3) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - 0);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5, const bmp180_cal_t *c) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 0) + 2) >> 2);
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(int32_t pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %ld Pa\n", ts, (long)pressure);
    fclose(fp);
}

static void toggle_logging(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    static uint32_t last_tick = 0;
    if (tick - last_tick < DEBOUNCE_US) return;
    last_tick = tick;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_TOGGLE, PI_INPUT);
    gpioSetPullUpDown(GPIO_TOGGLE, PI_PUD_UP);
    if (gpioSetAlertFuncEx(GPIO_TOGGLE, toggle_logging, NULL) != 0) {
        fprintf(stderr, "Error: Could not set alert function on GPIO %d\n", GPIO_TOGGLE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 pressure logger started. Press GPIO27 to toggle logging.\n");

    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                int32_t b5 = compute_b5(ut, &cal);
                int32_t pressure = compute_pressure(up, b5, &cal);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Error: I2C read failure, skipping log entry\n");
            }
        }
        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(GPIO_TOGGLE, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

