#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define MAX_DUTY_CYCLE 80
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;
static double target_temperature = 25.0;
static double kp = 2.0;
static double ki = 0.5;
static double integral = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_thermocouple(double *temperature) {
    unsigned char data[4] = {0};
    int ret = spiRead(spi_handle, (char *)data, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", ret);
        return -1;
    }
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 fault: open circuit\n");
        return -1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 fault: short to GND\n");
        return -1;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -1;
    }
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    raw >>= 2;
    *temperature = raw * 0.25;
    return 0;
}

static int calculate_duty_cycle(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
