#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE  255

#define TEMP_LOW   40000   /* 40 °C in m°C */
#define TEMP_MED   60000   /* 60 °C in m°C */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read CPU temperature in millidegrees Celsius from the sysfs thermal zone.
 * Returns 0 on success and stores the value in *temp_out; returns -1 on error.
 */
static int read_cpu_temp(int *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    *temp_out = temp;
    return 0;
}

/*
 * Map temperature in m°C to RGB values for a common-anode LED.
 * Common-anode: duty 255 = fully off, duty 0 = fully on.
 * So we invert the desired brightness: brightness -> (PWM_RANGE - brightness).
 */
static void temp_to_rgb(int temp_m, int *r, int *g, int *b)
{
    int brightness = 255;

    if (temp_m < TEMP_LOW) {
        *r = 0;
        *g = 0;
        *b = brightness;
    } else if (temp_m < TEMP_MED) {
        *r = 0;
        *g = brightness;
        *b = 0;
    } else {
        *r = brightness;
        *g = 0;
        *b = 0;
    }
}

/*
 * Set RGB channels with common-anode inversion.
 * pigpio gpioPWM duty range is 0-255; for a common-anode LED,
 * a desired brightness of N means PWM duty = 255 - N.
 */
static void set_rgb(int r, int g, int b)
{
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

/*
 * Turn off all channels (common-anode: duty 255 = off).
 */
static void rgb_off(void)
{
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pins */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range for all three channels */
    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with all channels off */
    rgb_off();

    /* Main loop */
    while (g_running) {
        int temp_m;
        if (read_cpu_temp(&temp_m) != 0) {
            /* Skip this cycle; keep LED at last valid state */
            gpioDelay(500000);
            continue;
        }

        int r, g, b;
        temp_to_rgb(temp_m, &r, &g, &b);
        set_rgb(r, g, b);

        printf("Temperature: %d m°C -> R=%d G=%d B=%d\n",
               temp_m, r, g, b);
        fflush(stdout);

        gpioDelay(500000); /* 0.5 seconds */
    }

    /* Clean shutdown */
    rgb_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

