#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define DHT22_TIMEOUT 1000000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

typedef struct {
    float temperature;
    float humidity;
    int error_code;
} DHT22Data;

typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

static int read_dht22(int gpio, DHT22Data *data) {
    data->temperature = -1000.0;
    data->humidity = -1000.0;
    data->error_code = 0;

    int bits[40] = {0};
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000);
    gpioWrite(gpio, 1);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        if (++timeout > DHT22_TIMEOUT) {
            data->error_code = 1;
            return -1;
        }
        gpioDelay(1);
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        if (++timeout > DHT22_TIMEOUT) {
            data->error_code = 2;
            return -1;
        }
        gpioDelay(1);
    }

    timeout = 0;
    while (gpioRead(gpio) == 1) {
        if (++timeout > DHT22_TIMEOUT) {
            data->error_code = 3;
            return -1;
        }
        gpioDelay(1);
    }

    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            if (++timeout > DHT22_TIMEOUT) {
                data->error_code = 4;
                return -1;
            }
            gpioDelay(1);
        }

        timeout = 0;
        while (gpioRead(gpio) == 1) {
            if (++timeout > DHT22_TIMEOUT) {
                data->error_code = 5;
                return -1;
            }
            gpioDelay(1);
        }

        bits[i] = timeout;
    }

    int humidity_int = 0, humidity_dec = 0, temp_int = 0, temp_dec = 0, checksum = 0;
    for (i = 0; i < 16; i++) {
        if (bits[i] > 40) humidity_int |= (1 << (15 - i));
        if (bits[i + 16] > 40) humidity_dec |= (1 << (15 - i));
    }

    for (i = 0; i < 16; i++) {
        if (bits[i + 32] > 40) temp_int |= (1 << (15 - i));
        if (bits[i + 48] > 40) temp_dec |= (1 << (15 - i));
    }

    checksum = (humidity_int + humidity_dec + temp_int + temp_dec) & 0xFF;

    if (checksum != (bits[16] + bits[17] + bits[18] + bits[19] + bits[32] + bits[33] + bits[34] + bits[35] + bits[48] + bits[49] + bits[50] + bits[51]) & 0xFF) {
        data->error_code = 6;
        return -1;
    }

    data->humidity = (float)humidity_int + (float)humidity_dec / 10.0;
    data->temperature = (float)temp_int + (float)temp_dec / 10.0;
    data->error_code = 0;
    return 0;
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;
    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if (!ptr) return 0;
    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;
    return realsize;
}

static int send_data(const char *url, float temperature, float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }

    char json_data[256];
    snprintf(json_data, sizeof(json_data), "{\"temperature\":%.1f,\"humidity\":%.1f}", temperature, humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);

    MemoryStruct chunk = {malloc(1), 0};
    if (!chunk.memory) {
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }
    chunk.memory[0] = '\0';
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

    CURLcode res = curl_easy_perform(curl);

    int ret = 0;
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        ret = -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    free(chunk.memory);
    return ret;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    curl_global_init(CURL_GLOBAL_DEFAULT);

    DHT22Data dht22_data;
    int retries = 0;
    int success = 0;

    while (retries < MAX_RETRIES && !terminate) {
        if (read_dht22(DHT22_GPIO, &dht22_data) == 0) {
            if (dht22_data.temperature > -999.0 && dht22_data.humidity > -999.0) {
                if (send_data(SERVER_URL, dht22_data.temperature, dht22_data.humidity) == 0) {
                    success = 1;
                    break;
                } else {
                    fprintf(stderr, "Failed to send data to server\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data (error code: %d)\n", dht22_data.error_code);
        }
        retries++;
        if (retries < MAX_RETRIES) gpioDelay(1000000);
    }

    if (!success) {
        fprintf(stderr, "Failed to read and send data after %d retries\n", MAX_RETRIES);
    }

    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

