#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define OSS 3
#define BUTTON_GPIO 4
#define DEBOUNCE_US 200000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    int rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1); if (rc < 0) return -1; ac1 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2); if (rc < 0) return -1; ac2 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3); if (rc < 0) return -1; ac3 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4); if (rc < 0) return -1; ac4 = (uint16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5); if (rc < 0) return -1; ac5 = (uint16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6); if (rc < 0) return -1; ac6 = (uint16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);  if (rc < 0) return -1; b1  = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);  if (rc < 0) return -1; b2  = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);  if (rc < 0) return -1; mb  = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);  if (rc < 0) return -1; mc  = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);  if (rc < 0) return -1; md  = (int16_t)rc;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int32_t msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int32_t lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(26000);
    int32_t msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int32_t lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int32_t xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static double calculate_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p / 100.0;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    static uint32_t last_tick = 0;
    if (tick - last_tick < DEBOUNCE_US) return;
    last_tick = tick;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 ready. Press button on GPIO4 to toggle logging. Ctrl+C to exit.\n");
    while (running) {
        int32_t ut, up;
        if (read_raw_temperature(&ut) < 0) {
            fprintf(stderr, "Temperature read error\n");
        } else if (read_raw_pressure(&up) < 0) {
            fprintf(stderr, "Pressure read error\n");
        } else {
            int32_t b5 = compute_b5(ut);
            double pressure = calculate_pressure(up, b5);
            if (logging_enabled) {
                log_pressure(pressure);
            } else {
                printf("Logging disabled. Pressure: %.2f hPa\n", pressure);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

