    running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

/*
 * Read DHT22 humidity via pigpio.
 * Returns 0 on success, -1 on failure.
 * Humidity is returned in *humidity_out.
 */
static int read_dht22_humidity(int gpio_pin, float *humidity_out) {
    int data[5] = {0, 0, 0, 0, 0};
    int last_state = PI_HIGH;
    int bit_count = 0;
    int i;

    /* Send start signal: pull low for >= 1 ms, then high for 20-40 us, then release */
    if (gpioSetMode(gpio_pin, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set GPIO mode to output");
        return -1;
    }
    if (gpioWrite(gpio_pin, PI_LOW) < 0) {
        log_message(LOG_ERR, "Failed to write GPIO low");
        return -1;
    }
    gpioDelay(2000); /* 2 ms low (>= 1 ms required) */
    if (gpioWrite(gpio_pin, PI_HIGH) < 0) {
        log_message(LOG_ERR, "Failed to write GPIO high");
        return -1;
    }
    gpioDelay(30); /* 30 us high */
    if (gpioSetMode(gpio_pin, PI_INPUT) < 0) {
        log_message(LOG_ERR, "Failed to set GPIO mode to input");
        return -1;
    }

    /* Wait for sensor response: low then high */
    int timeout = 0;
    while (gpioRead(gpio_pin) == PI_HIGH) {
        if (++timeout > 100) {
            log_message(LOG_ERR, "DHT22 response timeout (stuck high)");
            return -1;
        }
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(gpio_pin) == PI_LOW) {
        if (++timeout > 100) {
            log_message(LOG_ERR, "DHT22 response timeout (stuck low)");
            return -1;
        }
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(gpio_pin) == PI_HIGH) {
        if (++timeout > 100) {
            log_message(LOG_ERR, "DHT22 response timeout (stuck high)");
            return -1;
        }
        gpioDelay(1);
    }

    /* Read 40 bits */
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio_pin) == PI_LOW) {
            if (++timeout > 100) {
                log_message(LOG_ERR, "DHT22 bit timeout (stuck low)");
                return -1;
            }
            gpioDelay(1);
        }
        gpioDelay(40); /* Wait for > 30 us high to classify as '1' */
        if (gpioRead(gpio_pin) == PI_HIGH) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
        timeout = 0;
        while (gpioRead(gpio_pin) == PI_HIGH) {
            if (++timeout > 100) {
                log_message(LOG_ERR, "DHT22 bit timeout (stuck high)");
                return -1;
            }
            gpioDelay(1);
        }
    }

