                        sleep(2);
                    }
                }
            }
            if (!success) {
                log_message(LOG_ERR, "Failed to post humidity after retries");
            }
        } else {
            log_message(LOG_ERR, "Failed to read humidity after retries");
        }

        if (running) {
            sleep(READ_INTERVAL);
        }
    }

    log_message(LOG_INFO, "Shutting down");
    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

