#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_PATH   "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE_PATH  "/var/log/fan_control.log"
#define POLL_INTERVAL  5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_int_file(const char *path, int *out) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%d", out) != 1) {
        fprintf(stderr, "Error reading %s\n", path);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int write_int_file(const char *path, int value) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for write: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", value) < 0) {
        fprintf(stderr, "Error writing to %s\n", path);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int set_fan_speed(int speed) {
    if (write_int_file(FAN_STATE_PATH, speed) != 0) {
        return -1;
    }
    return 0;
}

static int determine_fan_speed(int cpu_temp_milli) {
    int temp_c = cpu_temp_milli / 1000;
    if (temp_c < 45) return 0;
    if (temp_c < 55) return 1;
    if (temp_c < 65) return 2;
    return 3;
}

static void log_fan_speed(int speed) {
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE_PATH, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Fan speed set to: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, speed);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int max_state = -1;
    if (read_int_file(FAN_MAX_PATH, &max_state) != 0) {
        fprintf(stderr, "Failed to read max_state. Exiting.\n");
        return EXIT_FAILURE;
    }
    if (max_state < 0) {
        fprintf(stderr, "Invalid max_state value: %d. Exiting.\n", max_state);
        return EXIT_FAILURE;
    }

    int current_speed = -1;
    int retry_count = 0;

    while (running) {
        int cpu_temp = 0;
        if (read_int_file(CPU_TEMP_PATH, &cpu_temp) != 0) {
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            sleep(1);
            continue;
        }
        retry_count = 0;

        int desired_speed = determine_fan_speed(cpu_temp);
        if (desired_speed > max_state) {
            desired_speed = max_state;
        }

        if (desired_speed != current_speed) {
            if (set_fan_speed(desired_speed) == 0) {
                current_speed = desired_speed;
                log_fan_speed(current_speed);
            } else {
                fprintf(stderr, "Failed to set fan speed.\n");
            }
        }

        sleep(POLL_INTERVAL);
    }

    if (current_speed != 0) {
        if (set_fan_speed(0) == 0) {
            log_fan_speed(0);
        }
    }

    return EXIT_SUCCESS;
}

