    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int max_state = -1;
    if (read_int_file(FAN_MAX_PATH, &max_state) != 0) {
        fprintf(stderr, "Failed to read max_state. Exiting.\n");
        return EXIT_FAILURE;
    }
    if (max_state < 0) {
        fprintf(stderr, "Invalid max_state value: %d. Exiting.\n", max_state);
        return EXIT_FAILURE;
    }

    int current_speed = -1;
    int retry_count = 0;

    while (running) {
        int cpu_temp = 0;
        if (read_int_file(CPU_TEMP_PATH, &cpu_temp) != 0) {
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            sleep(1);
            continue;
        }
        retry_count = 0;

        int desired_speed = determine_fan_speed(cpu_temp);
        if (desired_speed > max_state) {
            desired_speed = max_state;
        }

        if (desired_speed != current_speed) {
            if (set_fan_speed(desired_speed) == 0) {
                current_speed = desired_speed;
                log_fan_speed(current_speed);
            } else {
                fprintf(stderr, "Failed to set fan speed.\n");
            }
        }

        sleep(POLL_INTERVAL);
    }

    if (current_speed != 0) {
        if (set_fan_speed(0) == 0) {
            log_fan_speed(0);
        }
    }

    return EXIT_SUCCESS;
}

