#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define FAILSAFE_HIGH 100.0
#define FAILSAFE_LOW 0.0
#define LOG_FILE "heater_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static void log_data(double temp, int duty, double pid_out) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] Temp: %.2f, Duty: %d, PID: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, duty, pid_out);
    fclose(fp);
}

static int read_max31855(double *temp) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        log_message("SPI transfer failed");
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        if (raw & 0x00000004) log_message("MAX31855 fault: Open circuit");
        if (raw & 0x00000002) log_message("MAX31855 fault: Short to GND");
        if (raw & 0x00000001) log_message("MAX31855 fault: Short to VCC");
        return -1;
    }
    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temp = thermocouple_raw * 0.25;
    return 0;
}

static int set_heater(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(HEATER_GPIO, duty) < 0) {
        log_message("gpioPWM failed");
        return -1;
    }
    return 0;
}

static double pid_control(double setpoint, double actual) {
    double error = setpoint - actual;
    integral += error;
    if (integral > 1000.0) integral = 1000.0;
    if (integral < -1000.0) integral = -1000.0;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

static void cleanup(void) {
    set_heater(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_message("Program started");
    while (running) {
        double temp;
        if (read_max31855(&temp) != 0) {
            set_heater(0);
            log_message("Thermocouple read error, heater disabled");
            sleep(1);
            continue;
        }
        if (temp > FAILSAFE_HIGH || temp < FAILSAFE_LOW) {
            set_heater(0);
            log_message("Failsafe triggered, heater disabled");
            sleep(1);
            continue;
        }
        double pid_out = pid_control(TARGET_TEMPERATURE, temp);
        int duty = (int)pid_out;
        if (set_heater(duty) != 0) {
            log_message("Heater set failed");
        }
        log_data(temp, duty, pid_out);
        sleep(1);
    }
    log_message("Program exiting");
    cleanup();
    return 0;
}

