#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQ 25000
#define PWM_RANGE 100
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int calculate_duty_cycle(int temp_milli) {
    if (temp_milli < 0) return 0;
    float temp_c = (float)temp_milli / 1000.0f;
    if (temp_c <= 40.0f) return 0;
    if (temp_c >= 70.0f) return 100;
    return (int)((temp_c - 40.0f) / 30.0f * 100.0f);
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int pwm_value = (duty_cycle * PWM_RANGE) / 100;
    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "gpioPWM failed for duty cycle %d\n", duty_cycle);
        return -1;
    }
    return 0;
}

static int log_data(float temp_c, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s,%.2f,%d\n", timestamp, temp_c, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: could not set exact PWM frequency\n");
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: could not set exact PWM range\n");
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("fopen log for write");
            gpioTerminate();
            return 1;
        }
        fprintf(fp, "Timestamp,Temperature (C),PWM Duty Cycle (%%)\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_milli = read_temperature();
        if (temp_milli < 0) {
            fprintf(stderr, "Temperature read failed, retrying...\n");
            sleep(POLL_INTERVAL);
            continue;
        }
        float temp_c = (float)temp_milli / 1000.0f;
        int duty_cycle = calculate_duty_cycle(temp_milli);
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }
        if (log_data(temp_c, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }
        printf("Temp: %.2f C, Duty: %d%%\n", temp_c, duty_cycle);
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    return 0;
}

