#define SLF3S_ADDR_ALT 0x09
#define SLF3S_CONT_MEAS_CMD 0x3608
#define FLOW_SCALE_FACTOR 0.01f
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    char cmd[2] = { (SLF3S_CONT_MEAS_CMD >> 8) & 0xFF, SLF3S_CONT_MEAS_CMD & 0xFF };
    char buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (handle %d), retry %d\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(2000);

        if (i2cReadDevice(handle, buf, 3) != 3) {
            fprintf(stderr, "I2C read failed (handle %d), retry %d\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
            fprintf(stderr, "CRC mismatch (handle %d), retry %d\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        int16_t raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
        *flow_rate = (float)raw * FLOW_SCALE_FACTOR;
        return 0;
    }

    return -1;
}

