    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting dual SLF3S-1300F flow monitoring. Press Ctrl+C to stop.\n");

    while (running) {
