#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define PULSES_PER_REVOLUTION 360
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (fprintf(log_file, "%s, %.2f\n", timestamp, angle) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void encoder_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;

    if (level != 1) return;

    static int state = 0;
    static float angle = 0.0f;

    int a = gpioRead(SENSOR_A_PIN);
    int b = gpioRead(SENSOR_B_PIN);

    if (a < 0 || b < 0) {
        fprintf(stderr, "Error reading encoder pins.\n");
        return;
    }

    int new_state = (a << 1) | b;

    if (new_state != state) {
        if (new_state == 0 && state == 3) {
            angle += 1.0f;
        } else if (new_state == 3 && state == 0) {
            angle -= 1.0f;
        } else {
            if (new_state > state) {
                angle += 1.0f;
            } else {
                angle -= 1.0f;
            }
        }

        state = new_state;
        log_data(angle * (360.0f / PULSES_PER_REVOLUTION));
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_A_PIN, encoder_callback, NULL) != 0 ||
        gpioSetAlertFuncEx(SENSOR_B_PIN, encoder_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nCleaning up...\n");
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

