code:
/*
 * ADPD144RI Red/IR Photometric Sensor Reader for Raspberry Pi 3 Model B+
 * Uses libgpiod for GPIO and Linux I2C character-device interface.
 *
 * Wiring:
 *   ADPD144RI SDA -> GPIO 2 (I2C bus 1 SDA)
 *   ADPD144RI SCL -> GPIO 3 (I2C bus 1 SCL)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED anode    -> GPIO 17 (1 kΩ series resistor to GND)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG  0x60
#define LED_GPIO       17
#define IR_THRESHOLD   2000
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, sizeof(reg)) != (ssize_t)sizeof(reg)) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd bytes (%s)\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor init                                                         */
/* ------------------------------------------------------------------ */

static int sensor_init(int fd)
{
    /*
     * Minimal ADPD144RI initialization: enable FIFO and set sample
     * rate.  A full production driver would configure the LED drive
     * currents, LED currents, and the FIFO threshold.
     */
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) return -1;   /* FIFO_EN */
    if (i2c_write_reg8(fd, 0x01, 0x01) < 0) return -1;   /* SAMPLE_RATE */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm)) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01 00:00:00");
    }
    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Open I2C bus ---- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- Sensor presence check ---- */
    if (i2c_write_reg8(fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "ADPD144RI not responding at 0x%02X\n", ADPD144RI_ADDR);
        goto cleanup;
    }

    if (sensor_init(fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        goto cleanup;
    }

    /* ---- Open log file ---- */
    log_fp = fopen("adpd144ri_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }
    led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "adpd144ri-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        goto cleanup;
    }

    printf("ADPD144RI reader started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t red = 0, ir = 0;

        if (i2c_read_reg16(fd, FIFO_DATA_REG, &red) < 0 ||
            i2c_read_reg16(fd, FIFO_DATA_REG + 1, &ir) < 0) {
            fprintf(stderr, "Read error — continuing\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        log_data(log_fp, red, ir);

        if (ir > IR_THRESHOLD) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    if (fd >= 0) close(fd);
    return ret;
}

