#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1.0

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Error: Mutex initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    if (gpioSetISRFunc(GPIO_PIN, RISING_EDGE, 0, pulse_callback) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioSetISRFunc(GPIO_PIN, RISING_EDGE, 0, NULL);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handler\n");
        fclose(log_file);
        gpioSetISRFunc(GPIO_PIN, RISING_EDGE, 0, NULL);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        time_sleep(SAMPLE_INTERVAL_SEC);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = (double)pulses / SAMPLE_INTERVAL_SEC * 60.0;
        log_rpm(rpm);
    }

    printf("\nShutting down...\n");

    gpioSetISRFunc(GPIO_PIN, RISING_EDGE, 0, NULL);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

