#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define EXPECTED_PART_ID 0x00
#define RED_DATA_REG 0x04
#define IR_DATA_REG 0x06
#define LED_GPIO_LINE 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)val, (uint8_t)(val >> 8)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    uint16_t part_id;
    if (i2c_read_reg16(i2c_fd, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID (sensor absent or bus error)\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%04X (expected 0x%04X)\n", part_id, EXPECTED_PART_ID);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *ir) {
    if (i2c_read_reg16(i2c_fd, RED_DATA_REG, red) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, IR_DATA_REG, ir) < 0) return -1;
    return 0;
}

static void log_data(uint16_t red, uint16_t ir) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%u,%u\n", ts, red, ir);
    fflush(log_file);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("fopen log");
        cleanup();
        return 1;
    }
    fprintf(log_file, "# timestamp,red,ir\n");
    fflush(log_file);

    while (running) {
        uint16_t red, ir;
        if (read_sensor_data(&red, &ir) < 0) {
            fprintf(stderr, "Sensor read error\n");
        } else {
            log_data(red, ir);
            if (ir > IR_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

