#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_INPUT_PIN 17
#define GPIO_OUTPUT_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_audio_event(FILE *log_file, int level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s LEVEL %d\n", timestamp, level) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *input_line = NULL;
    struct gpiod_line *output_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    input_line = gpiod_chip_get_line(chip, GPIO_INPUT_PIN);
    if (input_line == NULL) {
        fprintf(stderr, "Error: Failed to get input line %d: %s\n", GPIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    output_line = gpiod_chip_get_line(chip, GPIO_OUTPUT_PIN);
    if (output_line == NULL) {
        fprintf(stderr, "Error: Failed to get output line %d: %s\n", GPIO_OUTPUT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(input_line, "audio_logger") < 0) {
        fprintf(stderr, "Error: Failed to request input line %d: %s\n", GPIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(output_line, "audio_logger", 0) < 0) {
        fprintf(stderr, "Error: Failed to request output line %d: %s\n", GPIO_OUTPUT_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Audio logger started. Sampling GPIO %d for rising edges. Press Ctrl+C to exit.\n", GPIO_INPUT_PIN);

    int prev_value = gpiod_line_get_value(input_line);
    if (prev_value < 0) {
        fprintf(stderr, "Error: Failed to read initial input value: %s\n", strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int current_value = gpiod_line_get_value(input_line);
        if (current_value < 0) {
            fprintf(stderr, "Error: Failed to read input value: %s\n", strerror(errno));
            break;
        }

        if (current_value == 1 && prev_value == 0) {
            if (log_audio_event(log_file, 1) < 0) {
                fprintf(stderr, "Warning: Failed to log audio event.\n");
            }
        }

        prev_value = current_value;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (input_line != NULL) {
        gpiod_line_release(input_line);
    }
    if (output_line != NULL) {
        gpiod_line_release(output_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
        }
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nAudio logger stopped.\n");
    }

    return ret;
}

