#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define START_MEASUREMENT_CMD 0x3608
#define READ_INTERVAL_MS 1000
#define FLOW_SCALE_FACTOR 1000.0f
#define LOG_FILE_NAME "flow_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int initialize_sensor(void) {
    uint8_t cmd[2] = {
        (uint8_t)((START_MEASUREMENT_CMD >> 8) & 0xFF),
        (uint8_t)(START_MEASUREMENT_CMD & 0xFF)
    };
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing start measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buffer[3];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: expected 3 bytes, got %d\n", result);
        return -1;
    }

    if (sensirion_crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    *flow_rate = (float)raw_flow / FLOW_SCALE_FACTOR;
    return 0;
}

static int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (!terminate) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate\n");
            }
        } else {
            fprintf(stderr, "Error reading flow rate, retrying...\n");
        }
        gpioDelay(READ_INTERVAL_MS * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

