    *tvoc = ((uint16_t)buf[1] << 8) | buf[2];
    *eco2 = ((uint16_t)buf[5] << 8) | buf[6];
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0f - (float)tvoc / 10.0f - ((float)eco2 - 400.0f) / 50.0f;
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

static void log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log_file, "%s,%.2f,%u,%u\n", ts, iaq, tvoc, eco2);
    fflush(g_log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(g_log_file, "# timestamp,iaq,tvoc_ppb,eco2_ppm\n");
    fflush(g_log_file);

    uint8_t state[SENSOR_STATE_LEN];
    uint16_t tvoc, eco2;
    float iaq;

    while (g_running) {
        if (read_sensor_state(state, SENSOR_STATE_LEN) == 0) {
            if (parse_sensor_data(state, &tvoc, &eco2) == 0) {
                iaq = calculate_iaq(tvoc, eco2);
                log_data(iaq, tvoc, eco2);
                printf("IAQ: %.2f, TVOC: %u ppb, eCO2: %u ppm\n", iaq, tvoc, eco2);
            } else {
                fprintf(stderr, "Failed to parse sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor state\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
    }
    gpioTerminate();
    return 0;
}

