/*
 * TTP223B capacitive touch sensor monitor using libgpiod v1 API.
 *
 * Board : Raspberry Pi 5
 * Sensor: SainSmart TTP223B (active-high, digital output)
 * Wiring: Sensor VCC -> 3.3 V, GND -> GND, OUT -> GPIO17 (physical pin 11)
 *
 * Behavior:
 *   - Polls the line every 100 ms.
 *   - When the sensor is continuously touched for > 5 s, prints an
 *     intrusion alert once per touch event.
 *   - Resets the timer on release so the alert is retriggered on
 *     the next sustained touch.
 *   - Exits cleanly on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp223_tamper ttp223_tamper.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_MS 100
#define TAMPER_THRESHOLD_S 5
#define CONSUMER_NAME     "ttp223_tamper"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, CONSUMER_NAME) < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B on GPIO%d (chip %s). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);
    fflush(stdout);

    bool touched = false;
    struct timespec touch_start;
    bool alert_printed = false;

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        bool now_touched = (val == 1);

        if (now_touched && !touched) {
            /* Entering a new touch event */
            touched = true;
            clock_gettime(CLOCK_MONOTONIC, &touch_start);
            alert_printed = false;
        } else if (touched && !now_touched) {
            /* Touch released */
            touched = false;
            alert_printed = false;
        } else if (touched && now_touched) {
            /* Sustained touch — check threshold */
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed =
                (now.tv_sec  - touch_start.tv_sec)  +
                (now.tv_nsec - touch_start.tv_nsec) / 1e9;

            if (elapsed >= TAMPER_THRESHOLD_S && !alert_printed) {
                printf("[ALERT] Sustained touch on GPIO%d for %.0f s — intrusion detected!\n",
                       GPIO_LINE_OFFSET, elapsed);
                fflush(stdout);
                alert_printed = true;
            }
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);
    return ret;
}

