#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define PCM_DEVICE "/dev/snd/pcmC0D0c"
#define PCM_RATE 48000
#define PCM_CHANNELS 2
#define PCM_FORMAT 1  // SND_PCM_FORMAT_S16_LE
#define PCM_PERIOD_SIZE 1024
#define PCM_PERIODS 4
#define SAMPLE_SIZE 4
#define OUTPUT_FILE "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int pcm_open(const char *device, int rate, int channels, int format) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PCM device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, SND_PCM_IOCTL_RESET) < 0) {
        fprintf(stderr, "Failed to reset PCM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SND_PCM_IOCTL_SET_ACCESS, &format) < 0) {
        fprintf(stderr, "Failed to set access: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SND_PCM_IOCTL_SET_SAMPLE_BITS, &rate) < 0) {
        fprintf(stderr, "Failed to set sample rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SND_PCM_IOCTL_SET_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Failed to set channels: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SND_PCM_IOCTL_SET_RATE, &rate) < 0) {
        fprintf(stderr, "Failed to set rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SND_PCM_IOCTL_SET_PERIOD_SIZE, &PCM_PERIOD_SIZE) < 0) {
        fprintf(stderr, "Failed to set period size: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SND_PCM_IOCTL_SET_PERIODS, &PCM_PERIODS) < 0) {
        fprintf(stderr, "Failed to set periods: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SND_PCM_IOCTL_PREPARE) < 0) {
        fprintf(stderr, "Failed to prepare PCM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int pcm_read(int fd, uint8_t *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read < 0) {
        fprintf(stderr, "Failed to read from PCM: %s\n", strerror(errno));
        return -1;
    }
    if (bytes_read == 0) {
        fprintf(stderr, "Unexpected EOF on PCM device.\n");
        return -1;
    }
    return (int)bytes_read;
}

static int pcm_close(int fd) {
    if (fd >= 0) {
        if (ioctl(fd, SND_PCM_IOCTL_DRAIN) < 0) {
            fprintf(stderr, "Failed to drain PCM: %s\n", strerror(errno));
            return -1;
        }
        if (close(fd) < 0) {
            fprintf(stderr, "Failed to close PCM: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int pcm_fd = -1;
    FILE *output_file = NULL;
    uint8_t *buffer = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "inmp441-lr", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    pcm_fd = pcm_open(PCM_DEVICE, PCM_RATE, PCM_CHANNELS, PCM_FORMAT);
    if (pcm_fd < 0) {
        goto cleanup;
    }

    output_file = fopen(OUTPUT_FILE, "wb");
    if (!output_file) {
        fprintf(stderr, "Failed to open output file %s: %s\n", OUTPUT_FILE, strerror(errno));
        goto cleanup;
    }

    buffer = malloc(PCM_PERIOD_SIZE * SAMPLE_SIZE);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting audio capture. Press Ctrl+C to stop.\n");

    while (running) {
        int bytes_read = pcm_read(pcm_fd, buffer, PCM_PERIOD_SIZE * SAMPLE_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from PCM.\n");
            goto cleanup;
        }

        // Extract 24-bit data and convert to 16-bit PCM
        for (int i = 0; i < bytes_read; i += 4) {
            // INMP441 outputs 24-bit left-justified in 32-bit frames
            // Extract the 24-bit value and right-shift to get 16-bit PCM
            int32_t sample = (int32_t)((buffer[i] << 24) | (buffer[i+1] << 16) | (buffer[i+2] << 8) | buffer[i+3]);
            int16_t pcm_sample = (int16_t)(sample >> 8); // Right-shift to get 16-bit value
            fwrite(&pcm_sample, sizeof(int16_t), 1, output_file);
        }

        fflush(output_file);
    }

    printf("\nCapture stopped.\n");
    ret = 0;

cleanup:
    if (output_file) {
        fclose(output_file);
    }
    if (buffer) {
        free(buffer);
    }
    if (pcm_fd >= 0) {
        pcm_close(pcm_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

