#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define POLL_INTERVAL_US 50000
#define DEBOUNCE_US 50000
#define FLAME_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);
    gpioPWM(FAN_PIN, 0);
    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d.\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return value;
}

static void control_fan(int flame_detected, int flame_duration_ms) {
    if (flame_detected) {
        int duty_cycle = 0;
        if (flame_duration_ms > 0 && flame_duration_ms < 1000) {
            duty_cycle = (int)((float)flame_duration_ms / 1000.0 * 80.0);
        }
        if (duty_cycle > 80) duty_cycle = 80;
        if (duty_cycle < 0) duty_cycle = 0;
        gpioPWM(FAN_PIN, duty_cycle);
    } else {
        gpioPWM(FAN_PIN, 0);
    }
}

static void cleanup(void) {
    gpioPWM(FAN_PIN, 0);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        log_event("System shutdown.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    log_event("System started.");

    int flame_detected = 0;
    int flame_start_tick = 0;
    int last_flame_state = -1;
    int debounce_count = 0;
    int debounce_threshold = 5;
    int sensor_timeout_count = 0;

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            sensor_timeout_count++;
            if (sensor_timeout_count > 10) {
                fprintf(stderr, "Error: Sensor read timeout.\n");
                log_event("Sensor read timeout.");
                break;
            }
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        sensor_timeout_count = 0;

        if (sensor_value != last_flame_state) {
            debounce_count++;
            if (debounce_count >= debounce_threshold) {
                if (sensor_value == 0) {
                    if (!flame_detected) {
                        flame_detected = 1;
                        flame_start_tick = gpioTick();
                        log_event("Flame detected.");
                    }
                } else {
                    if (flame_detected) {
                        flame_detected = 0;
                        int duration = (gpioTick() - flame_start_tick) / 1000;
                        char msg[128];
                        snprintf(msg, sizeof(msg), "Flame ended. Duration: %d ms", duration);
                        log_event(msg);
                    }
                }
                last_flame_state = sensor_value;
                debounce_count = 0;
            }
        } else {
            debounce_count = 0;
        }

        if (flame_detected) {
            int flame_duration = (gpioTick() - flame_start_tick) / 1000;
            control_fan(1, flame_duration);
            if (flame_duration > (FLAME_TIMEOUT_S * 1000)) {
                fprintf(stderr, "Warning: Flame duration exceeded timeout.\n");
                log_event("Warning: Flame duration exceeded timeout.");
                flame_detected = 0;
            }
        } else {
            control_fan(0, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

