#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define DATA_READY_TIMEOUT_US 1000000
#define HEATMAP_DATA_SIZE 32768
#define LOG_FILE_NAME "radar_data.log"
#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint32_t magic_number;
    uint64_t timestamp;
    float start_frequency;
    float end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
    float frame_period;
} __attribute__((packed)) log_header_t;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
    uint8_t data[HEATMAP_DATA_SIZE];
} __attribute__((packed)) log_frame_t;

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint64_t get_timestamp_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static int write_log_header(FILE *f) {
    log_header_t header;
    memset(&header, 0, sizeof(header));
    header.magic_number = MAGIC_NUMBER;
    header.timestamp = get_timestamp_us();
    header.start_frequency = 77.0f;
    header.end_frequency = 79.0f;
    header.num_chirps = 64;
    header.num_samples = 256;
    header.frame_period = 0.1f;
    if (fwrite(&header, sizeof(header), 1, f) != 1) {
        perror("fwrite header");
        return -1;
    }
    return 0;
}

static int write_log_frame(FILE *f, const log_frame_t *frame) {
    if (fwrite(frame, sizeof(*frame), 1, f) != 1) {
        perror("fwrite frame");
        return -1;
    }
    return 0;
}

static int read_heatmap_data(uint8_t *data, size_t data_size) {
    char tx_buf[HEATMAP_DATA_SIZE];
    char rx_buf[HEATMAP_DATA_SIZE];
    memset(tx_buf, 0, sizeof(tx_buf));
    int bytes_transferred = spiXfer(spi_handle, tx_buf, rx_buf, (int)data_size);
    if (bytes_transferred != (int)data_size) {
        fprintf(stderr, "SPI transfer failed: expected %zu, got %d\n", data_size, bytes_transferred);
        return -1;
    }
    memcpy(data, rx_buf, data_size);
    return 0;
}

static int wait_for_data_ready(void) {
    uint64_t start = get_timestamp_us();
    while (!terminate) {
        if (gpioRead(DATA_READY_PIN) == 1) {
            return 0;
        }
        if (get_timestamp_us() - start > DATA_READY_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            return -1;
        }
        gpioDelay(1000);
    }
    return -1;
}

static int request_frame(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1;
    }
    gpioDelay(100);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set data ready pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize trigger pin\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "wb");
    if (log_file == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_log_header(log_file) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t *heatmap_data = malloc(HEATMAP_DATA_SIZE);
    if (heatmap_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint32_t frame_number = 0;
    while (!terminate) {
        if (request_frame() != 0) {
            fprintf(stderr, "Frame request failed\n");
            break;
        }
        if (wait_for_data_ready() != 0) {
            fprintf(stderr, "Data ready timeout\n");
            break;
        }
        if (read_heatmap_data(heatmap_data, HEATMAP_DATA_SIZE) != 0) {
            fprintf(stderr, "Heatmap read failed\n");
            break;
        }

        log_frame_t frame;
        memset(&frame, 0, sizeof(frame));
        frame.timestamp = get_timestamp_us();
        frame.frame_number = frame_number;
        memcpy(frame.data, heatmap_data, HEATMAP_DATA_SIZE);

        if (write_log_frame(log_file, &frame) != 0) {
            fprintf(stderr, "Frame write failed\n");
            break;
        }

        frame_number++;
        fflush(log_file);
    }

    free(heatmap_data);
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

