    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t *heatmap_data = malloc(HEATMAP_DATA_SIZE);
    if (heatmap_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint32_t frame_number = 0;
    while (!terminate) {
        if (request_frame() != 0) {
            fprintf(stderr, "Frame request failed\n");
            break;
        }
        if (wait_for_data_ready() != 0) {
            fprintf(stderr, "Data ready timeout\n");
            break;
        }
        if (read_heatmap_data(heatmap_data, HEATMAP_DATA_SIZE) != 0) {
            fprintf(stderr, "Heatmap read failed\n");
            break;
        }

        log_frame_t frame;
        memset(&frame, 0, sizeof(frame));
        frame.timestamp = get_timestamp_us();
        frame.frame_number = frame_number;
        memcpy(frame.data, heatmap_data, HEATMAP_DATA_SIZE);

        if (write_log_frame(log_file, &frame) != 0) {
            fprintf(stderr, "Frame write failed\n");
            break;
        }

        frame_number++;
        fflush(log_file);
    }

    free(heatmap_data);
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

