#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

/* TTP226 OUT1..OUT8 -> BCM GPIO 2..9 */
static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = channel_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", pin);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed.\n", pin);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void log_touch_data(int elapsed_ms)
{
    printf("[+%d ms] ", elapsed_ms);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int state = gpioRead(channel_pins[i]);
        printf("CH%d=%d ", i + 1, state);
    }
    printf("\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (!terminate) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000L +
                          (now.tv_nsec - start.tv_nsec) / 1000000L;

        log_touch_data((int)elapsed_ms);
        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

