/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: libgpiod (modern GPIO API; replaces deprecated wiringPi)
 *
 * Wiring (TTP226 OUT -> RPi GPIO):
 *   CH1 -> GPIO2  (pin 3)
 *   CH2 -> GPIO3  (pin 5)
 *   CH3 -> GPIO4  (pin 7)
 *   CH4 -> GPIO17 (pin 11)
 *   CH5 -> GPIO27 (pin 13)
 *   CH6 -> GPIO22 (pin 15)
 *   CH7 -> GPIO10 (pin 19)
 *   CH8 -> GPIO9  (pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

/* GPIO numbers (BCM numbering) for the TTP226 channels */
static const unsigned int gpio_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Print an ISO-8601 timestamp to stdout.                              */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    printf("%s,", buf);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_acquired[NUM_CHANNELS] = {0};
    int ret = EXIT_FAILURE;

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open the default gpiochip (gpiochip0 on RPi 4) ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* ---- Acquire each GPIO line as an input ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        /* Request the line as input with bias disabled. */
        if (gpiod_line_request_input_flags(lines[i], "ttp226-reader",
                                            GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE) < 0) {
            fprintf(stderr, "gpiod_line_request_input_flags(%u) failed: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
        line_acquired[i] = 1;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("Timestamp,CH1,CH2,CH3,CH4,CH5,CH6,CH7,CH8\n");
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (program_running) {
        print_timestamp();

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(%u) failed: %s\n",
                        gpio_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("%d", val);
            if (i < NUM_CHANNELS - 1) {
                printf(",");
            }
        }
        printf("\n");
        fflush(stdout);

        /* Sleep for POLL_INTERVAL_MS, but wake early on signal. */
        struct timespec ts = {
            .tv_sec  = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        nanosleep(&ts, NULL);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release all acquired lines ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (line_acquired[i] && lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

