#include <time.h>
#include <signal.h>
#include <unistd.h>

#define TILT_SENSOR_GPIO 4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_tilt_state(int tilt_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (tilt_state == 0) {
        printf("[%s] Tilted\n", timestamp);
    } else if (tilt_state == 1) {
        printf("[%s] Not Tilted\n", timestamp);
    } else {
        printf("[%s] Invalid tilt state: %d\n", timestamp, tilt_state);
    }
    fflush(stdout);
}

int main(void)
{
    int last_tilt_state = -1;
    int current_tilt_state;
    int init_result;

    /* Install SIGINT handler for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", init_result);
        return EXIT_FAILURE;
    }

    /* Configure GPIO 4 as input with internal pull-up */
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           TILT_SENSOR_GPIO);
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        current_tilt_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_tilt_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d)\n",
                    TILT_SENSOR_GPIO, current_tilt_state);
            break;
        }

        if (current_tilt_state != last_tilt_state) {
            log_tilt_state(current_tilt_state);
            last_tilt_state = current_tilt_state;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

