#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define SI1145_REG_PARTID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEASRATE0 0x08
#define SI1145_REG_MEASRATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX0 0x2C
#define SI1145_REG_UVINDEX1 0x2D
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_CHLIST 0x01

#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_RESET 0x01

#define SI1145_PARTID 0x45
#define SI1145_HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_low, uint16_t *val) {
    uint8_t lo, hi;
    if (read_reg(reg_low, &lo) < 0) return -1;
    if (read_reg(reg_low + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id;
    if (read_reg(SI1145_REG_PARTID, &part_id) < 0) return -1;
    if (part_id != SI1145_PARTID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PARTID);
        return -1;
    }
    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_reg(SI1145_REG_MEASRATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_MEASRATE1, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_CHLIST, 0x03) < 0) return -1;
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_sensor_data(float *uv_index, uint16_t *als_visible) {
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    gpioDelay(10000);
    uint16_t uv_raw, als_raw;
    if (read_word(SI1145_REG_UVINDEX0, &uv_raw) < 0) return -1;
    if (read_word(SI1145_REG_ALS_VIS_DATA0, &als_raw) < 0) return -1;
    *uv_index = (float)uv_raw / 100.0f;
    *als_visible = als_raw;
    return 0;
}

static void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float uv_index;
    uint16_t als_visible;
    while (!terminate) {
        if (read_sensor_data(&uv_index, &als_visible) == 0) {
            printf("UV Index: %.2f, Visible ALS: %u\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(1000000);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

