#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define GPIO_CHIP      "gpiochip4"
#define ALARM_PIN      17
#define FLOW_THRESHOLD 0.5f
#define SCALE_FACTOR   0.036f
#define LOG_FILE       "flow_log.txt"
#define READ_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t addr, uint16_t cmd) {
    uint8_t buf[3] = { 0x08, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "write cmd 0x%04X at 0x%02X: %s\n", cmd, addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t addr, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "read from 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, uint8_t addr, float *flow_out) {
    uint8_t buf[9];
    if (i2c_read_data(fd, addr, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data from 0x%02X\n", addr);
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature data from 0x%02X\n", addr);
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on scale factor data from 0x%02X\n", addr);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * SCALE_FACTOR;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *alarm = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm) {
        fprintf(stderr, "gpiod_chip_get_line %d: %s\n", ALARM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(alarm, "flow_alarm", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_cmd(i2c_fd, SENSOR1_ADDR, 0x3608) < 0 ||
        i2c_write_cmd(i2c_fd, SENSOR2_ADDR, 0x3608) < 0) {
        fprintf(stderr, "Sensor init failed\n");
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    usleep(100000);

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "fopen %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(i2c_fd, SENSOR1_ADDR, &f1);
        int ok2 = read_flow_rate(i2c_fd, SENSOR2_ADDR, &f2);

        if (ok1 == 0 && ok2 == 0) {
            float avg = (f1 + f2) / 2.0f;
            fprintf(log, "%.2f\n", avg);
            fflush(log);
            gpiod_line_set_value(alarm, avg < FLOW_THRESHOLD ? 1 : 0);
        } else {
            fprintf(stderr, "Sensor read error (s1=%d s2=%d)\n", ok1, ok2);
        }

        sleep(READ_INTERVAL);
    }

    gpiod_line_set_value(alarm, 0);
    gpiod_line_release(alarm);
    gpiod_chip_close(chip);
    fclose(log);
    close(i2c_fd);
    return 0;
}

