#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL_US 50000

typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

static SensorData data_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_data(int reading) {
    time(&data_buffer[buffer_index].timestamp);
    data_buffer[buffer_index].reading = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&data_buffer[idx].timestamp);
        if (tm_info != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("Timestamp: %s, Reading: %d\n", time_str, data_buffer[idx].reading);
    }
    printf("--- End of Buffer Contents ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    printf("Obstacle detection started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        int reading = gpioRead(GPIO_PIN);
        if (reading == 0) {
            log_data(reading);
            printf("Obstacle detected!\n");
        }
        usleep(POLL_INTERVAL_US);
    }

    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

