/*
 * fan_health.c — Raspberry Pi 5 (64-bit Bookworm)
 * Omron D7S vibration sensor over I2C (/dev/i2c-1, address 0x55)
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 * Run:    ./fan_health
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (7-bit I2C address 0x55) ---- */
#define D7S_ADDR             0x55
#define I2C_DEV              "/dev/i2c-1"
#define CSV_FILE             "fan_health.csv"
#define SAMPLE_PERIOD_MS     500
#define ACCEL_SCALE_G_PER_LSB 0.0009765625f   /* g/LSB (1/1024 g) */

/* D7S register addresses */
#define REG_OPERATING_STATUS 0x1B
#define REG_MODE_CONTROL     0x1D
#define REG_X_LSB            0x2A
#define REG_X_MSB            0x2B
#define REG_Y_LSB            0x2C
#define REG_Y_MSB            0x2D
#define REG_Z_LSB            0x2E
#define REG_Z_MSB            0x2F

/* MODE_CONTROL (0x1D) bit layout */
#define MODE_CONTROL_ACTIVE  0x10   /* bit 4: active mode */

/* Operating-status (0x1B) bit 0: 1 = operating */
#define OPERATING_STATUS_OK  0x01

