#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN     25

#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO %d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (rc=%d).\n", pin, v);
        return -1;
    }
    return v;
}

static int write_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on GPIO %d (state=%d).\n", LED_PIN, state);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — turn LED off for safety and exit */
            write_led(0);
            break;
        }

        /* KY-032 is active-LOW: 0 => obstacle detected */
        int obstacle = (s1 == 0 || s2 == 0);

        if (write_led(obstacle) != 0) {
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nObstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

