/*
 * TMAG5170-Q1 3D Hall-Effect Sensor Logger for Raspberry Pi 4 Model B
 * Library: pigpio (I2C bus 1, address 0x0E)
 *
 * Build: gcc -O2 -Wall -o mag_logger mag_logger.c -lpigpio -lrt
 * Run:   sudo ./mag_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TMAG5170-Q1 I2C constants ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x0E          /* A0=A1=0 */
#define REG_DEVICE_ID  0x00
#define EXPECTED_ID    0x8D

/* Configuration registers */
#define REG_CONFIG_1   0x01
#define REG_CONFIG_2   0x02
#define REG_CONFIG_3   0x03
#define REG_CONFIG_4   0x04

/* Data registers (16-bit two's-complement) */
#define REG_X_MSB      0x08
#define REG_X_LSB      0x09
#define REG_Y_MSB      0x0A
#define REG_Y_LSB      0x0B
#define REG_Z_MSB      0x0C
#define REG_Z_LSB      0x0D

/* ---- Conversion constants (50 mT range) ---- */
#define SCALE_50MT     0.000001f     /* 1 LSB = 1 pT = 0.000001 mT */

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TMAG5170 register.                              */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int reg_write(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TMAG5170 register.                             */
/* Returns 0 on success and stores value in *out, -1 on error.        */
/* ------------------------------------------------------------------ */
static int reg_read(uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit two's-complement value from two consecutive registers.*/
/* Returns 0 on success and stores value in *out, -1 on error.        */
/* ------------------------------------------------------------------ */
static int reg_read16(uint8_t msb_reg, int16_t *out)
{
    uint8_t msb, lsb;
    if (reg_read(msb_reg, &msb) < 0)
        return -1;
    if (reg_read(msb_reg + 1, &lsb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TMAG5170: verify device ID, configure for 50 mT range.*/
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int sensor_init(void)
{
    uint8_t id;

    /* Verify device identity */
    if (reg_read(REG_DEVICE_ID, &id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (id != EXPECTED_ID) {
        fprintf(stderr, "[ERROR] Unexpected DEVICE_ID: 0x%02X (expected 0x%02X).\n",
                id, EXPECTED_ID);
        return -1;
    }
    printf("[INFO] TMAG5170 detected (DEVICE_ID=0x%02X).\n", id);

    /*
     * CONFIG_1 (0x01):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_1, 0x00) < 0)
        return -1;

    /*
     * CONFIG_2 (0x02):
     *   [15:14] RANGE = 00 (50 mT)
     *   [13:12] OPER_MODE = 00 (continuous)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_2, 0x00) < 0)
        return -1;

    /*
     * CONFIG_3 (0x03):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_3, 0x00) < 0)
        return -1;

    /*
     * CONFIG_4 (0x04):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_4, 0x00) < 0)
        return -1;

    /*
     * CONFIG_5 (0x05):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_5, 0x00) < 0)
        return -1;

    /*
     * CONFIG_6 (0x06):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_6, 0x00) < 0)
        return -1;

    /*
     * CONFIG_7 (0x07):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_7, 0x00) < 0)
        return -1;

    /*
     * CONFIG_8 (0x08):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_8, 0x00) < 0)
        return -1;

    /*
     * CONFIG_9 (0x09):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_9, 0x00) < 0)
        return -1;

    /*
     * CONFIG_10 (0x0A):
     *   [15:14] OPER_MODE = 00 (continuous)
     *   [13:12] OPER_STATE = 00 (normal)
     *   [11:10] SLEEP_TIME = 00 (100 ms)
     *   [9:8]   AVG_SAMPLES = 00 (1 sample)
     *   [7:6]   AVG_TIME = 00 (1 sample)
     *   [5:4]   OSR = 00 (default)
     *   [3:2]   SLEEP_AVG = 00 (no sleep averaging)
     *   [1:0]   RESERVED = 00
     * Value = 0x00
     */
    if (reg_write(REG_CONFIG_10, 0x00) < 0)
        return -1;

    printf("[INFO] Sensor configured for 50 mT range, continuous mode.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X, Y, Z magnetic field readings in mT.                        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_magnetic_data(float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (reg_read16(REG_X_MSB, &raw_x) < 0)
        return -1;
    if (reg_read16(REG_Y_MSB, &raw_y) < 0)
        return -1;
    if (reg_read16(REG_Z_MSB, &raw_z) < 0)
        return -1;

    *x = (float)raw_x * SCALE_50MT;
    *y = (float)raw_y * SCALE_50MT;
    *z = (float)raw_z * SCALE_50MT;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a CSV row with an ISO-8601 timestamp.                        */
/* ------------------------------------------------------------------ */
static void log_data(float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed.\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed.\n");
        return;
    }
    if (fflush(log_file) != 0)
        fprintf(stderr, "[WARN] fflush failed on log file.\n");
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (sensor_init() < 0) {
        fprintf(stderr, "[FATAL] Sensor initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open magnetic_log.csv for appending.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_mt,y_mt,z_mt\n");
        fflush(log_file);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction failed; Ctrl+C will not clean up.\n");
    }

    printf("[INFO] Logging magnetic data to magnetic_log.csv (Ctrl+C to stop).\n");

    /* ---- Main loop ---- */
    while (!terminate) {
        float x, y, z;

        if (read_magnetic_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "[WARN] read_magnetic_data failed; continuing.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* ---- Cleanup ---- */
    printf("\n[INFO] Shutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

