/* ------------------------------------------------------------------ */
/* Write one byte to a TMAG5170 register.                              */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int reg_write(uint8_t reg, uint8_t value)
