#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_GPIO 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", SENSOR_GPIO);
        return -1;
    }
    return value;
}

static int reinit_gpio(void) {
    gpioTerminate();
    for (int attempt = 0; attempt < MAX_REINIT_ATTEMPTS; attempt++) {
        fprintf(stderr, "Re-initializing GPIO (attempt %d/%d)...\n", attempt + 1, MAX_REINIT_ATTEMPTS);
        if (init_gpio() == 0) {
            return 0;
        }
        gpioDelay(1000000);
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    int consecutive_errors = 0;

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error reading sensor (consecutive: %d/%d).\n", consecutive_errors, MAX_REINIT_ATTEMPTS);
            log_event("ERROR: Sensor read failure");

            if (consecutive_errors >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max consecutive errors reached. Attempting GPIO re-initialization...\n");
                if (reinit_gpio() != 0) {
                    fprintf(stderr, "GPIO re-initialization failed. Exiting.\n");
                    log_event("ERROR: GPIO re-initialization failed");
                    break;
                }
                consecutive_errors = 0;
            }
        } else {
            consecutive_errors = 0;

            if (sensor_value == 1) {
                printf("ALERT: Water detected!\n");
                log_event("ALERT: Water detected");
            }
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    gpioTerminate();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

