#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <stdatomic.h>

#define SENSOR_PIN 4          /* BCM GPIO 4, physical pin 7 */
#define LOG_FILE   "rpm_log.txt"
#define SAMPLE_SEC 1.0

static atomic_int pulse_count = 0;
static FILE *log_fp = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of SENSOR_PIN          */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;
    if (level == 1) {            /* rising edge */
        atomic_fetch_add(&pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* pigpio timer callback — fires every SAMPLE_SEC seconds             */
/* ------------------------------------------------------------------ */
static void timer_callback(void *userdata)
{
    (void)userdata;
    int pulses = atomic_exchange(&pulse_count, 0);
    float rpm = (float)pulses * 60.0f / SAMPLE_SEC;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp) {
        fprintf(log_fp, "%s %.2f\n", ts, rpm);
        fflush(log_fp);
    }
    printf("%s %.2f RPM\n", ts, rpm);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pin ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", SENSOR_PIN);
        goto fail;
    }
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", SENSOR_PIN);
        goto fail;
    }

    /* ---- register alert callback ---- */
    if (gpioSetAlertFunc(SENSOR_PIN, pulse_callback) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc failed for pin %d.\n", SENSOR_PIN);
        goto fail;
    }

    /* ---- register timer callback (1-second interval) ---- */
    if (gpioSetTimerFunc(0, (int)(SAMPLE_SEC * 1000.0), timer_callback) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFunc failed.\n");
        goto fail;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        goto fail;
    }

