        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", SENSOR_PIN);
        goto fail;
    }

    /* ---- register alert callback ---- */
    if (gpioSetAlertFunc(SENSOR_PIN, pulse_callback) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc failed for pin %d.\n", SENSOR_PIN);
        goto fail;
    }

    /* ---- register timer callback (1-second interval) ---- */
    if (gpioSetTimerFunc(0, (int)(SAMPLE_SEC * 1000.0), timer_callback) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFunc failed.\n");
        goto fail;
    }

