#include <pthread.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine:
 *   0 -> 1 -> 2 -> 3 -> 0 (CW)
 *   3 -> 2 -> 1 -> 0 -> 3 (CCW)
 */
static const int state_transitions[4][4] = {
    {0, 1, 3, 2},
    {2, 0, 1, 3},
    {3, 2, 0, 1},
    {1, 3, 2, 0}
};

static volatile int current_state = 0;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_rotation(const char *direction) {
    if (!log_file) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    long ms = ts.tv_nsec / 1000000;

    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ms, direction);
    fflush(log_file);
}

static void sensor_alert_cb(int gpio, int level, uint32_t tick) {
    (void)tick;

    if (level != 1) return; /* Only rising edge */

    int a = gpioRead(SENSOR_A_PIN);
    int b = gpioRead(SENSOR_B_PIN);

    if (a < 0 || b < 0) return;

    int new_state = state_transitions[current_state][(a << 1) | b];

    pthread_mutex_lock(&state_mutex);
    current_state = new_state;
    pthread_mutex_unlock(&state_mutex);

    if (new_state == 0 || new_state == 3) {
        log_rotation("CW");
    } else {
        log_rotation("CCW");
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
