        gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        goto cleanup;
    }

    if (gpioSetAlertFunc(SENSOR_A_PIN, sensor_alert_cb) != 0 ||
        gpioSetAlertFunc(SENSOR_B_PIN, sensor_alert_cb) != 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

cleanup:
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

