/*
 * TTP223B capacitive touch sensor -> LED control on Raspberry Pi 3 Model B+
 * Uses libgpiod line request API (modern GPIO character-device API).
 *
 * Wiring:
 *   TTP223B OUT  -> GPIO 23 (physical pin 16)
 *   LED anode    -> GPIO 18 (physical pin 12) via 330 ohm resistor
 *   LED cathode  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define TOUCH_PIN        23
#define LED_PIN          18
#define POLL_INTERVAL_US 50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting TTP223B touch-to-LED program...");

    if (install_signal_handlers() != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers.");
        goto cleanup;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open %s: %s", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* Get the touch sensor line (input) */
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (touch_line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get the LED line (output) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request touch line as input */
    if (gpiod_line_request_input(touch_line, "ttp223b-touch") < 0) {
        syslog(LOG_ERR, "Failed to request touch line as input: %s", strerror(errno));
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW (off) */
    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "GPIO initialized: touch=GPIO%d, LED=GPIO%d", TOUCH_PIN, LED_PIN);

    /* Main polling loop */
    while (g_running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            /* Brief pause to avoid log flooding on persistent read errors */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "Touch detected -> LED ON");
            }
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to turn LED off: %s", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off before releasing resources */
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    syslog(LOG_INFO, "Exiting.");
    closelog();
    return ret;
}

