#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_1 4
#define TOUCH_SENSOR_2 17
#define LED_1          27
#define LED_2          22
#define BUFFER_SIZE    100
#define POLL_DELAY_US  50000

typedef struct {
    int  sensor_pin;
    time_t timestamp;
    int  state;
} Event;

static Event event_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   overflow_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

static void add_event(int sensor_pin, int state) {
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp  = time(NULL);
    event_buffer[buffer_index].state      = state;

    buffer_index++;
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
        overflow_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Event Log (overflows=%d) ---\n", overflow_count);
    int start = (overflow_count > 0) ? 0 : buffer_index;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        if (event_buffer[idx].timestamp == 0) break;
        printf("  [%d] Sensor=%d Timestamp=%ld State=%d\n",
               idx, event_buffer[idx].sensor_pin,
               (long)event_buffer[idx].timestamp, event_buffer[idx].state);
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_SENSOR_1, PI_INPUT) != 0 ||
        safe_set_mode(TOUCH_SENSOR_2, PI_INPUT) != 0 ||
        safe_set_mode(LED_1,          PI_OUTPUT) != 0 ||
        safe_set_mode(LED_2,          PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(LED_1, 0) != 0 || safe_write(LED_2, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int prev1 = safe_read(TOUCH_SENSOR_1);
    int prev2 = safe_read(TOUCH_SENSOR_2);
    if (prev1 < 0 || prev2 < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int cur1 = safe_read(TOUCH_SENSOR_1);
        int cur2 = safe_read(TOUCH_SENSOR_2);
        if (cur1 < 0 || cur2 < 0) break;

        if (cur1 != prev1) {
            add_event(TOUCH_SENSOR_1, cur1);
            safe_write(LED_1, cur1);
            prev1 = cur1;
        }
        if (cur2 != prev2) {
            add_event(TOUCH_SENSOR_2, cur2);
            safe_write(LED_2, cur2);
            prev2 = cur2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    safe_write(LED_1, 0);
    safe_write(LED_2, 0);
    gpioTerminate();

    print_buffer();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

