#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 17 as input with internal pull-up */
    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read initial sensor state */
    int last_state = gpioRead(RAIN_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "gpioRead failed for GPIO %d\n", RAIN_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Determine initial logical state: LOW (0) = rain detected, HIGH (1) = dry */
    const char *initial_event = (last_state == 0) ? "Rain Detected" : "No Rain";
    if (log_event(initial_event) != 0) {
        fprintf(stderr, "Failed to log initial state\n");
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           RAIN_SENSOR_GPIO);

    /* Main polling loop */
    while (running) {
        int current_state = gpioRead(RAIN_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed for GPIO %d\n", RAIN_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            const char *event = (current_state == 0) ? "Rain Detected" : "No Rain";
            if (log_event(event) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

