#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO    27
#define THRESHOLD_SEC 2
#define POLL_US       100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    }
    fprintf(log_file, "%s - %s\n", ts, event);
    fflush(log_file);
}

static int read_sensor(int gpio) {
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio, pigpio_error(v));
        return -1;
    }
    return v;
}

static int set_alarm(int on) {
    int rc = gpioWrite(ALARM_GPIO, on ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n",
                ALARM_GPIO, on, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_alarm(0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(ALARM_GPIO,    PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_alarm(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("bridge_integrity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring tilt sensors on GPIO %d and %d. Alarm on GPIO %d.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO, ALARM_GPIO);
    printf("Threshold: %d seconds. Press Ctrl+C to exit.\n", THRESHOLD_SEC);

    int s1_high = 0, s2_high = 0;
    int alarm_active = 0;
    time_t s1_start = 0, s2_start = 0;

    while (running) {
        int v1 = read_sensor(SENSOR_1_GPIO);
        int v2 = read_sensor(SENSOR_2_GPIO);

        if (v1 < 0 || v2 < 0) {
            gpioDelay(POLL_US);
            continue;
        }

        if (v1 == 1 && !s1_high) {
            s1_high = 1;
            s1_start = time(NULL);
            log_event("Sensor 1 tilted");
        } else if (v1 == 0 && s1_high) {
            s1_high = 0;
            log_event("Sensor 1 normal");
        }

        if (v2 == 1 && !s2_high) {
            s2_high = 1;
            s2_start = time(NULL);
            log_event("Sensor 2 tilted");
        } else if (v2 == 0 && s2_high) {
            s2_high = 0;
            log_event("Sensor 2 normal");
        }

        if (s1_high && difftime(time(NULL), s1_start) >= THRESHOLD_SEC) {
            if (!alarm_active) {
                if (set_alarm(1) == 0) {
                    alarm_active = 1;
                    log_event("Alarm activated (Sensor 1 exceeded threshold)");
                }
            }
        } else if (s2_high && difftime(time(NULL), s2_start) >= THRESHOLD_SEC) {
            if (!alarm_active) {
                if (set_alarm(1) == 0) {
                    alarm_active = 1;
                    log_event("Alarm activated (Sensor 2 exceeded threshold)");
                }
            }
        } else if (alarm_active) {
            if (set_alarm(0) == 0) {
                alarm_active = 0;
                log_event("Alarm deactivated");
            }
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

