/*
 * Raspberry Pi 3 Model B+ — Omron D7S-A0011 seismic sensor monitor
 * Library : pigpio (modern, actively maintained)
 * Bus     : I2C-1 (SDA=GPIO2, SCL=GPIO3), 7-bit address 0x1D
 * LED     : GPIO 17 (active-high)
 * Log     : seismic_events.log  (ISO-8601 timestamps)
 *
 * Build   : gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run     : sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define D7S_I2C_ADDR         0x1D          /* Omron D7S-A0011 default 7-bit address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500.0f        /* arbitrary magnitude threshold */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LED_ON_DURATION_US   1000000       /* 1 s */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S register map (verified against datasheet) */
#define D7S_REG_CTRL1        0x1F          /* control register 1 */
#define D7S_REG_OUT_X_L      0x28          /* X-axis acceleration low byte */
#define D7S_REG_OUT_X_H      0x29          /* X-axis acceleration high byte */
#define D7S_REG_OUT_Y_L      0x2A          /* Y-axis acceleration low byte */
#define D7S_REG_OUT_Y_H      0x2B          /* Y-axis acceleration high byte */
#define D7S_REG_OUT_Z_L      0x2C          /* Z-axis acceleration low byte */
#define D7S_REG_OUT_Z_H      0x2D          /* Z-axis acceleration high byte */

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------- Sensor helpers ------------------------------ */
/*
 * Verify the sensor is present by reading back the default CTRL1 value
 * (0x00) after a power-on reset.  If the read returns a different value,
 * the sensor may already be configured; we tolerate that.
 */
static bool sensor_init(void)
{
    int ctrl1 = i2cReadByteData(i2c_handle, D7S_REG_CTRL1);
    if (ctrl1 < 0) {
        fprintf(stderr, "[ERROR] Failed to read CTRL1 register (pigpio rc=%d).\n", ctrl1);
        return false;
    }

    /* Clear power-down bit (bit 0) so the sensor starts measuring */
    if (ctrl1 & 0x01) {
        if (i2cWriteByteData(i2c_handle, D7S_REG_CTRL1, ctrl1 & ~0x01) < 0) {
            fprintf(stderr, "[ERROR] Failed to clear power-down bit in CTRL1.\n");
            return false;
        }
        gpioDelay(5000);  /* allow configuration to take effect */
    }
    return true;
}

/*
 * Read 6 bytes of acceleration data (X, Y, Z) in one I2C block read.
 * Returns true on success, false on persistent failure.
 */
static bool read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int  attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(i2c_handle, D7S_REG_OUT_X_L, buf, 6);
        if (rc == 6) {
            *x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
            *y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
            *z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);
            return true;
        }
        fprintf(stderr, "[WARN] I2C block read failed (rc=%d, attempt %d/%d).\n",
                rc, attempt + 1, MAX_RETRIES);
        gpioDelay(10000);  /* 10 ms back-off before retry */
    }
    return false;
}

/* Euclidean magnitude of (x, y, z) in integer units */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    return sqrtf((float)x * x + (float)y * y + (float)z * z);
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(float magnitude)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s  magnitude=%.2f\n", timestamp, magnitude);
    fflush(log_file);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    i2c_handle = i2cOpen(I2C_BUS, D7S_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (rc=%d). Check wiring and that i2c is enabled.\n",
                i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor presence / init --- */
    if (!sensor_init()) {
        fprintf(stderr, "[FATAL] D7S-A0011 not detected or init failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; Ctrl+C will not clean up.\n");
    }

    printf("Seismic monitor running.  Threshold=%.1f  LED=GPIO%d  Log=%s\n",
           VIBRATION_THRESHOLD, LED_GPIO, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (!terminate) {
        int16_t x, y, z;

        if (!read_acceleration(&x, &y, &z)) {
            fprintf(stderr, "[ERROR] Sensor read failed after %d retries; continuing.\n",
                    MAX_RETRIES);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > VIBRATION_THRESHOLD) {
            printf("[ALERT] Vibration magnitude: %.2f\n", magnitude);

            if (gpioWrite(LED_GPIO, 1) < 0) {
                fprintf(stderr, "[WARN] Failed to turn LED on.\n");
            }
            gpioDelay(LED_ON_DURATION_US);
            if (gpioWrite(LED_GPIO, 0) < 0) {
                fprintf(stderr, "[WARN] Failed to turn LED off.\n");
            }

            log_event(magnitude);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

