    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(GPIO %u): %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    syslog(LOG_INFO, "Monitoring started on GPIO pins: %u, %u, %u, %u, %u",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        prev_state[i] = gpiod_line_get_value(lines[i]);
        if (prev_state[i] < 0) {
            syslog(LOG_ERR, "Initial gpiod_line_get_value(GPIO %u): %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j < NUM_SENSORS; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int cur = gpiod_line_get_value(lines[i]);
            if (cur < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(GPIO %u): %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            /* Rising edge: no-flame -> flame */
            if (prev_state[i] == 1 && cur == 0) {
                usleep(DEBOUNCE_MS * 1000);
                int confirmed = gpiod_line_get_value(lines[i]);
                if (confirmed < 0) {
