                           sensor_pins[i], strerror(errno));
                    continue;
                }
                if (confirmed == 0) {
                    syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %u)",
                           i + 1, sensor_pins[i]);
                    if (log_event(i + 1, sensor_pins[i]) != 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d",
                               i + 1);
