#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define DEBOUNCE_MS 50
#define POLL_MS 50

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to touch_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state[NUM_CHANNELS];
    int current_state[NUM_CHANNELS];
    int debounce_count[NUM_CHANNELS];

    for (int i = 0; i < NUM_CHANNELS; i++) {
        last_state[i] = gpioRead(touch_pins[i]);
        if (last_state[i] < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", touch_pins[i]);
            gpioWrite(LED_PIN, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        current_state[i] = last_state[i];
        debounce_count[i] = 0;
    }

    int led_on = 0;

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int raw = gpioRead(touch_pins[i]);
            if (raw < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", touch_pins[i]);
                continue;
            }

            if (raw != last_state[i]) {
                debounce_count[i] = 0;
            }

            if (raw != current_state[i]) {
                debounce_count[i]++;
                if (debounce_count[i] * DEBOUNCE_MS >= 100) {
                    current_state[i] = raw;
                    if (current_state[i] == 1) {
                        if (log_touch_event(i + 1) != 0) {
                            fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                        }
                    }
                }
            }

            last_state[i] = raw;
        }

        int any_touched = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (current_state[i] == 1) {
                any_touched = 1;
                break;
            }
        }

        if (any_touched && !led_on) {
            if (gpioWrite(LED_PIN, 1) == 0) {
                led_on = 1;
            } else {
                fprintf(stderr, "Failed to turn on LED\n");
            }
        } else if (!any_touched && led_on) {
            if (gpioWrite(LED_PIN, 0) == 0) {
                led_on = 0;
            } else {
                fprintf(stderr, "Failed to turn off LED\n");
            }
        }

        gpioDelay(POLL_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

