#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR        0x44
#define REG_RESULT          0x00
#define REG_CONFIG          0x01
#define CONFIG_CONT_AUTO    0xC810  /* RN=1100 (auto), CT=100ms, M=1000 (continuous), OVF=0, CR=0, FL=0, L=0, POL=0, ME=0 */
#define I2C_BUS             1
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_S   1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit big-endian value to an 8-bit register (OPT3001 expects MSB first). */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[2];
    buf[0] = (char)(value >> 8);
    buf[1] = (char)(value & 0xFF);
    if (i2cWriteI2CBlockData(handle, reg, buf, 2) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from an 8-bit register. */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) < 0) {
        fprintf(stderr, "Error: i2cReadI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_lux(int handle, float *lux_out)
{
    uint16_t raw;
    if (opt3001_read_reg(handle, REG_RESULT, &raw) < 0)
        return -1;

    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
