        fprintf(stderr, "Error: Failed to configure OPT3001\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wait for the first conversion to complete (100 ms conversion time). */
    gpioDelay(100000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGINT) failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float lux;
        if (read_lux(g_i2c_handle, &lux) < 0) {
            fprintf(stderr, "Error: Failed to read lux value\n");
        } else {
            printf("Lux: %.2f\n", lux);
            if (log_data(lux) < 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
