#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int flame_detected) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Flame detected: %s\n", timestamp, flame_detected ? "YES" : "NO") < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set alert pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alert pin LOW\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
            log_event(-1);
        } else {
            int flame_detected = (sensor_value == 0);
            log_event(flame_detected);

            if (flame_detected) {
                if (gpioWrite(ALERT_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to set alert pin HIGH\n");
                }
                gpioDelay(ALERT_DURATION_US);
                if (gpioWrite(ALERT_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to set alert pin LOW\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

