/*
 * TTP223 capacitive touch sensor reader using libgpiod on Raspberry Pi 5.
 *
 * Wiring:
 *   TTP223 VCC  -> 3.3 V (pin 1)
 *   TTP223 GND  -> GND   (pin 6)
 *   TTP223 OUT  -> GPIO4 (pin 7)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_logger touch_logger.c -lgpiod
 *
 * Run:
 *   ./touch_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* RP1 GPIO controller on Pi 5 */
#define GPIO_LINE_OFFSET 4             /* GPIO4, physical pin 7 */
#define LOG_FILE         "touch_log.txt"
#define POLL_INTERVAL_US 50000         /* 50 ms debounce */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, const char *event)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* Request the line as input with pull-down bias */
    if (gpiod_line_request_input_flags(line, "ttp223-touch",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) != 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* Open the log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup_line;
    }

    printf("Monitoring TTP223 touch sensor on GPIO4. Press Ctrl+C to exit.\n");

    int prev_state = gpiod_line_get_value(line);
    if (prev_state < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value failed: %s\n",
                strerror(errno));
        goto cleanup_all;
    }

    while (g_running) {
        int cur_state = gpiod_line_get_value(line);
        if (cur_state < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            break;
        }

        if (cur_state != prev_state) {
            if (cur_state == 1) {
                log_event(fp, "Touch Detected");
            } else {
                log_event(fp, "Touch Released");
            }
            prev_state = cur_state;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        fclose(fp);
    }
cleanup_line:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

