#define SAMPLE_PERIOD  1.0
#define FLOW_SCALE     90.0f
#define MIN_FLOW_RATE  0.0f
#define MAX_FLOW_RATE  100.0f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one 3-byte frame from the SLF3S-1300F.
 * Returns 0 on success, -1 on I/O or CRC error.
 */
static int read_flow_rate(float *flow_rate, uint16_t *raw_flags)
{
    uint8_t buf[3];
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read failed (got %d bytes): %s\n",
                n, pigpio_error(n));
        return -1;
    }

    /* CRC covers the two data bytes */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate  = (float)raw / FLOW_SCALE;
    *raw_flags  = (uint16_t)(raw & 0x00FF);
    return 0;
}

static void log_data(float flow_rate, uint16_t raw_flags, const char *status)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(g_log_file);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement: command 0x3608 */
    uint8_t cmd[2] = { 0x36, 0x08 };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        cleanup();
        return EXIT_FAILURE;
    }
    time_sleep(0.002); /* first measurement is ready after ~2 ms */

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");

    printf("Monitoring coolant flow. Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow_rate = 0.0f;
        uint16_t raw_flags = 0;

        if (read_flow_rate(&flow_rate, &raw_flags) == 0) {
            if (flow_rate >= MIN_FLOW_RATE && flow_rate <= MAX_FLOW_RATE) {
                log_data(flow_rate, raw_flags, "OK");
                printf("Flow: %.2f ml/min, Flags: 0x%02X\n",
                       flow_rate, raw_flags);
            } else {
                log_data(flow_rate, raw_flags, "INVALID");
                fprintf(stderr, "Flow out of range: %.2f ml/min\n", flow_rate);
            }
        } else {
            log_data(0.0f, 0, "ERROR");
            fprintf(stderr, "Sensor read error; re-initializing I2C...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            time_sleep(0.01);
            g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Re-init failed: %s\n",
                        pigpio_error(g_i2c_handle));
                break;
            }
            i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
            time_sleep(0.002);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

