#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_LEFT   17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT  22
#define LOG_FILE    "path_log.csv"
#define POLL_MS     50

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    const unsigned int offsets[3] = {GPIO_LEFT, GPIO_MIDDLE, GPIO_RIGHT};
    const char *labels[3] = {"left", "middle", "right"};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO%u: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033-obstacle") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for GPIO%u: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        goto cleanup;
    }

    if (fprintf(fp, "timestamp,left,middle,right\n") < 0) {
        perror("fprintf header");
        goto cleanup;
    }
    fflush(fp);

    while (running) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        int vals[3];
        bool ok = true;
        for (int i = 0; i < 3; i++) {
            vals[i] = gpiod_line_get_value(lines[i]);
            if (vals[i] < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for GPIO%u: %s\n",
                        offsets[i], strerror(errno));
                ok = false;
                break;
            }
        }
        if (!ok) {
            break;
        }

        if (fprintf(fp, "%s,%d,%d,%d\n", ts, vals[0], vals[1], vals[2]) < 0) {
            perror("fprintf data");
            break;
        }
        fflush(fp);

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fflush(fp);
        fclose(fp);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

