        perror("gpiod_line_request_falling_edge_events");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO4 (falling edge). Press Ctrl+C to exit.\n");

    while (program_running) {
        ret = gpiod_line_event_wait(line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            continue;
        }
        struct tm *tm_info = localtime(&ts.tv_sec);
        if (!tm_info) {
            perror("localtime");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("ALERT: Flame detected at %s\n", timestamp);
        if (log_event(timestamp) != 0) {
            fprintf(stderr, "Warning: failed to log event.\n");
        }
    }

    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

