/*
 * Flame-detection safety system for Raspberry Pi 3 Model B+
 * Uses libgpiod (character-device API) instead of wiringPi.
 *
 * Hardware:
 *   KY-026 flame sensor  -> GPIO17 (physical pin 11), active-low
 *   Active buzzer        -> GPIO18 (physical pin 12)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_PIN    17
#define BUZZER_PIN   18
#define LOG_FILE     "alert_log.txt"
#define POLL_MS      500
#define BUZZER_MS    2000
#define SLICE_MS     100

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_event(FILE *log, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(log, "%s: %s\n", ts, msg) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    if (fflush(log) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

static void sleep_ms(unsigned ms)
{
    while (ms > 0 && g_running) {
        unsigned chunk = (ms > SLICE_MS) ? SLICE_MS : ms;
        usleep(chunk * 1000U);
        ms -= chunk;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL;
    struct gpiod_line *buzzer = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling ------------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file -------------------------------------------------- */
    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip ------------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    flame = gpiod_chip_get_line(chip, FLAME_PIN);
    if (!flame) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request flame line as input */
    if (gpiod_line_request_input(flame, "flame_alert") != 0) {
        fprintf(stderr, "gpiod_line_request_input(flame): %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request buzzer line as output, initial value LOW */
    if (gpiod_line_request_output(buzzer, "flame_alert", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(buzzer): %s\n", strerror(errno));
        goto cleanup;
    }

    log_event(log, "System started");
    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int prev_flame = gpiod_line_get_value(flame);
    if (prev_flame < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value(flame): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Main loop ------------------------------------------------------ */
    while (g_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame): %s\n", strerror(errno));
            break;
        }

        /* KY-026 digital output is active-low: LOW means flame detected */
        if (val == 0 && prev_flame != 0) {
            log_event(log, "Flame detected!");
            printf("Flame detected! Activating buzzer.\n");

            if (gpiod_line_set_value(buzzer, 1) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer, 1): %s\n", strerror(errno));
                break;
            }

            sleep_ms(BUZZER_MS);

            if (gpiod_line_set_value(buzzer, 0) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer, 0): %s\n", strerror(errno));
                break;
            }
        }

        prev_flame = val;
        sleep_ms(POLL_MS);
    }

    /* --- Graceful shutdown --------------------------------------------- */
    if (gpiod_line_set_value(buzzer, 0) != 0)
        fprintf(stderr, "Failed to turn off buzzer during shutdown: %s\n", strerror(errno));

    log_event(log, "System stopped");
    printf("System stopped.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (flame) gpiod_line_release(flame);
    if (buzzer) gpiod_line_release(buzzer);
    if (chip) gpiod_chip_close(chip);
    if (log) fclose(log);
    return ret;
}

