/*
 * TMAG5110A1 Hall-effect latch magnetic sensor monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (never wiringPi)
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4   (internal pull-up enabled)
 *   Sensor 2 OUT -> GPIO17  (internal pull-up enabled)
 *   Sensor 3 OUT -> GPIO27  (internal pull-up enabled)
 *
 * The TMAG5110A1 OUT pin is open-drain and pulls low when a
 * south-pole magnet is within the sensor's field.  When the
 * magnet leaves, the pin releases high (pulled by the internal
 * pull-up).  A logic level of 0 means magnet present, 1 means
 * magnet absent.
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US  100000          /* 100 ms */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

/*
 * Write an ISO-8601 timestamped event line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_event(const char *sensor_name, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        perror("localtime_r()");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_local) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s - Sensor: %s - Magnet: %s\n",
                ts, sensor_name, state ? "ABSENT" : "PRESENT") < 0) {
        perror("fprintf()");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        perror("fflush()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                        */
/* ------------------------------------------------------------------ */

/*
 * Read a sensor GPIO.
 * Returns 0 (magnet present), 1 (magnet absent), or -1 on error.
 */
static int read_sensor(int gpio)
{
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio, pigpio_error(level));
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                         */
/* ------------------------------------------------------------------ */

/*
 * Configure a GPIO as input with internal pull-up enabled.
 * Returns 0 on success, -1 on failure.
 */
static int setup_sensor_gpio(int gpio)
{
    if (gpioSetMode(gpio, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", gpio);
        return -1;
    }
    if (gpioSetPullUpDown(gpio, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", gpio);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    int gpios[] = { SENSOR_1_GPIO, SENSOR_2_GPIO, SENSOR_3_GPIO };
    const char *names[] = { "Sensor 1", "Sensor 2", "Sensor 3" };
    const int n_sensors = (int)(sizeof(gpios) / sizeof(gpios[0]));

    for (int i = 0; i < n_sensors; i++) {
        if (setup_sensor_gpio(gpios[i]) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    install_signal_handlers();

    /* ---- Initial state ---- */
    int prev[3];
    for (int i = 0; i < n_sensors; i++) {
        prev[i] = read_sensor(gpios[i]);
        if (prev[i] < 0) {
            fprintf(stderr, "Initial read failed for %s (GPIO %d)\n",
                    names[i], gpios[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* ---- Main loop ---- */
    while (g_running) {
        for (int i = 0; i < n_sensors; i++) {
            int cur = read_sensor(gpios[i]);
            if (cur < 0) {
                /* Error already reported; skip this sample. */
                continue;
            }

            if (cur != prev[i]) {
                if (log_event(names[i], cur) != 0) {
                    fprintf(stderr, "Failed to log event for %s\n", names[i]);
                }
                prev[i] = cur;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

