#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x4A
#define LOG_FILE       "heart_rate.csv"
#define SAMPLE_PERIOD  1.0
#define MOVING_AVG_WIN 5

/* Si1182-A-GM register addresses */
#define REG_PART_ID    0x00
#define REG_HW_REV     0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG_CONFIG  0x04
#define REG_ENABLE      0x01
#define REG_HR_DATA     0x2A

#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV  0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int verify_sensor(void)
{
    int part_id = i2cReadByteData(g_i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: I2C read failed for PART_ID (pigpio code %d).\n", part_id);
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: PART_ID mismatch (got 0x%02X, expected 0x%02X).\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }

    int hw_rev = i2cReadByteData(g_i2c_handle, REG_HW_REV);
    if (hw_rev < 0) {
        fprintf(stderr, "Error: I2C read failed for HW_REV (pigpio code %d).\n", hw_rev);
        return -1;
    }
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Error: HW_REV mismatch (got 0x%02X, expected 0x%02X).\n",
                hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    printf("Si1182-A-GM detected: PART_ID=0x%02X, HW_REV=0x%02X\n", part_id, hw_rev);
    return 0;
}

static int configure_sensor(void)
{
    /* LED current: 25 mA (0x19) */
    if (i2cWriteByteData(g_i2c_handle, REG_LED_CURRENT, 0x19) < 0) {
        fprintf(stderr, "Error: Failed to write LED_CURRENT register.\n");
        return -1;
    }

    /* Averaging: 16 samples (0x0F) */
    if (i2cWriteByteData(g_i2c_handle, REG_AVG_CONFIG, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to write AVG_CONFIG register.\n");
        return -1;
    }

    /* Enable: HR data output (0x01) */
