/*
 * KY-026 Flame Sensor Monitor (libgpiod)
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: Keyes KY-026 (digital output, active-low)
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (pin 1)
 *   KY-026 GND  -> GND   (pin 9)
 *   KY-026 DO   -> GPIO17 (BCM 17, physical pin 11)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define LOG_FILE         "flame_log.txt"
#define POLL_INTERVAL_US 100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
static void log_flame_event(FILE *log_fp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return;
    }

    printf("FLAME DETECTED\n");
    fflush(stdout);

    if (fprintf(log_fp, "%s FLAME DETECTED\n", timestamp) < 0)
        perror("fprintf to log file");
    else
        fflush(log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;
    int prev_value = 1;   /* assume no flame at startup (HIGH) */

    install_signal_handlers();

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as input with internal pull-up */
    if (gpiod_line_request_input_flags(line, "ky026-flame",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags");
        goto cleanup;
    }

    /* Open log file in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen log file");
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Read initial state */
    prev_value = gpiod_line_get_value(line);
    if (prev_value < 0) {
        perror("gpiod_line_get_value (initial)");
        goto cleanup;
    }

    /* Main polling loop */
    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            /* Brief pause before retrying to avoid tight error loop */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Detect falling edge: HIGH -> LOW (flame detected) */
        if (prev_value == 1 && value == 0) {
            log_flame_event(log_fp);
        }

        prev_value = value;
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL)
        fclose(log_fp);
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

