        fprintf(stderr, "gpiod_line_settings_new (display) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(display_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(display_settings, GPIOD_LINE_VALUE_INACTIVE);

