        fprintf(stderr, "gpiod_line_config_add_line_settings (display) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    display_req = gpiod_chip_request_lines(chip, NULL, display_cfg);
    if (!display_req) {
        fprintf(stderr, "gpiod_chip_request_lines (display) failed: %s\n", strerror(errno));
        goto cleanup;
    }

