/*
 * TTP226 8-channel capacitive touch sensor -> 8-bit binary counter display.
 *
 * Board:  Raspberry Pi Zero W
 * Library: libgpiod v2+ bulk/config API (no sysfs, no wiringPi, no deprecated
 *          libgpiod v1 simple API).
 *
 * Wiring:
 *   TTP226 OUT1..OUT8 -> GPIO 5, 6, 7, 8, 9, 10, 11, 12 (BCM)
 *   Display bit 0    -> GPIO 17
 *   Display bit 1    -> GPIO 24
 *   ...
 *   Display bit 7    -> GPIO 23
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_MS      10
#define STAB_MS      200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int display_pins[NUM_CHANNELS] = {17, 24, 23, 22, 21, 20, 19, 18};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void log_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm);
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
    } else {
        fprintf(fp, "(unknown time), Channel: %d, Counter: %d\n", channel, counter);
    }
    fclose(fp);
}

static void print_counter(int counter)
{
    printf("Touch on channel %d | Counter: %d\n", counter, counter);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *display_req = NULL;
    int prev_state[NUM_CHANNELS] = {0};
    int counter = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Request sensor lines as inputs ---- */
    struct gpiod_line_config *sensor_cfg = gpiod_line_config_new();
    if (!sensor_cfg) {
        fprintf(stderr, "gpiod_line_config_new (sensor) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_config_add_line_settings(sensor_cfg, sensor_pins, NUM_CHANNELS, NULL)) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (sensor) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct gpiod_line_settings *sensor_settings = gpiod_line_settings_new();
    if (!sensor_settings) {
        fprintf(stderr, "gpiod_line_settings_new (sensor) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(sensor_settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(sensor_settings, GPIOD_LINE_BIAS_PULL_DOWN);

    if (gpiod_line_config_add_line_settings(sensor_cfg, sensor_pins, NUM_CHANNELS, sensor_settings)) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (sensor direction) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    sensor_req = gpiod_chip_request_lines(chip, NULL, sensor_cfg);
    if (!sensor_req) {
        fprintf(stderr, "gpiod_chip_request_lines (sensor) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Request display lines as outputs ---- */
    struct gpiod_line_config *display_cfg = gpiod_line_config_new();
    if (!display_cfg) {
        fprintf(stderr, "gpiod_line_config_new (display) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct gpiod_line_settings *display_settings = gpiod_line_settings_new();
    if (!display_settings) {
        fprintf(stderr, "gpiod_line_settings_new (display) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(display_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(display_settings, GPIOD_LINE_VALUE_INACTIVE);

    if (gpiod_line_config_add_line_settings(display_cfg, display_pins, NUM_CHANNELS, display_settings)) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (display) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    display_req = gpiod_chip_request_lines(chip, NULL, display_cfg);
    if (!display_req) {
        fprintf(stderr, "gpiod_chip_request_lines (display) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Stabilize after line requests ---- */
    sleep_ms(STAB_MS);

    /* ---- Main poll loop ---- */
    while (g_running) {
        int values[NUM_CHANNELS];
        int read_ok = 1;

        if (gpiod_line_request_get_values(sensor_req, values) < 0) {
            fprintf(stderr, "gpiod_line_request_get_values failed: %s\n", strerror(errno));
            read_ok = 0;
        }

        if (read_ok) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                int val = values[i];
                if (val < 0) {
                    fprintf(stderr, "Sensor read error on channel %d: %s\n", i + 1, strerror(errno));
                    continue;
                }

                /* Rising edge: inactive -> touched */
                if (val == 1 && prev_state[i] == 0) {
                    counter = (counter + 1) & 0xFF;
                    log_event(i + 1, counter);
                    print_counter(counter);

                    /* Update display: bit b -> GPIO 17+b */
                    for (int b = 0; b < NUM_CHANNELS; b++) {
                        int bit = (counter >> b) & 1;
                        if (gpiod_line_request_set_value(display_req, display_pins[b],
                                                         bit ? GPIOD_LINE_VALUE_ACTIVE
                                                              : GPIOD_LINE_VALUE_INACTIVE) < 0) {
                            fprintf(stderr, "Display write failed on pin %u: %s\n",
                                    display_pins[b], strerror(errno));
                        }
                    }
                }
                prev_state[i] = val;
            }
        }

        sleep_ms(POLL_MS);
    }

    /* ---- Graceful shutdown: reset display and release ---- */
    if (display_req) {
        for (int b = 0; b < NUM_CHANNELS; b++)
            gpiod_line_request_set_value(display_req, display_pins[b], GPIOD_LINE_VALUE_INACTIVE);
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (sensor_req)  gpiod_line_request_release(sensor_req);
    if (display_req) gpiod_line_request_release(display_req);
    if (sensor_settings) gpiod_line_settings_free(sensor_settings);
    if (display_settings) gpiod_line_settings_free(display_settings);
    if (sensor_cfg)  gpiod_line_config_free(sensor_cfg);
    if (display_cfg) gpiod_line_config_free(display_cfg);
    if (chip)        gpiod_chip_close(chip);
    return ret;
