#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define POLL_INTERVAL_MS 100
#define CSV_FILENAME "tracking_log.csv"

static const unsigned int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_csv_header_if_new(FILE *fp) {
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            return -1;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033-tracking") != 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    if (write_csv_header_if_new(fp) != 0) {
        goto cleanup;
    }

    printf("Starting KY-033 tracking data logging to %s...\n", CSV_FILENAME);
    printf("Press Ctrl+C to stop.\n");

    while (program_running) {
        int values[NUM_SENSORS];
        int read_error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n", sensor_pins[i], strerror(errno));
                read_error = 1;
                values[i] = -1;
            } else {
                values[i] = val;
            }
        }

        if (read_error) {
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) == NULL) {
            fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
            fprintf(stderr, "strftime failed\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, values[0], values[1], values[2], values[3]) < 0) {
            fprintf(stderr, "Failed to write to CSV: %s\n", strerror(errno));
            goto cleanup;
        }

        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            goto cleanup;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

