#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN    22
#define LOG_FILE   "obstacle_log.csv"
#define POLL_MS    100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(buf, len, "1970-01-01 00:00:00");
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1 = NULL, *s2 = NULL, *led = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    s1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    s2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!s1 || !s2 || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(s1, "tcrt5000_s1") < 0) {
        perror("gpiod_line_request_input s1");
        goto cleanup;
    }
    if (gpiod_line_request_input(s2, "tcrt5000_s2") < 0) {
        perror("gpiod_line_request_input s2");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "tcrt5000_led", 0) < 0) {
        perror("gpiod_line_request_output led");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        goto cleanup;
    }

    fprintf(log_fp, "timestamp,sensor1,sensor2,led_state\n");
    fflush(log_fp);

    while (running) {
        int v1 = gpiod_line_get_value(s1);
        int v2 = gpiod_line_get_value(s2);
        if (v1 < 0 || v2 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int led_state = (v1 == 0 && v2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(log_fp, "%s,%d,%d,%d\n", ts, v1, v2, led_state);
        fflush(log_fp);

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_set_value(led, 0);
    if (s1) gpiod_line_release(s1);
    if (s2) gpiod_line_release(s2);
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

