#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125   /* 8 kHz sampling */
#define LED_ON_TIME_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld", buf, ts.tv_nsec / 1000000L);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is OFF at start */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO%d.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound peak detection started. Sampling GPIO%d, LED on GPIO%d.\n",
           MIC_GPIO, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int mic_value = gpioRead(MIC_GPIO);
        if (mic_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", MIC_GPIO);
            break;
        }

        if (mic_value == 1) {
            print_timestamp();
            printf(" Peak detected!\n");
            fflush(stdout);

            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error: failed to turn LED on GPIO%d ON.\n", LED_GPIO);
                break;
            }

            /* Keep LED on for 100 ms, checking for shutdown signal */
            uint32_t elapsed = 0;
            while (program_running && elapsed < LED_ON_TIME_US) {
                gpioDelay(1000);  /* 1 ms granularity */
                elapsed += 1000;
            }

            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED on GPIO%d OFF.\n", LED_GPIO);
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

