#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49
#define ALS_VIS_LSB 0x24
#define ALS_VIS_MSB 0x25
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_als_vis(int fd, uint16_t *als_vis) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, ALS_VIS_LSB, &lsb) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, ALS_VIS_MSB, &msb) < 0) {
        return -1;
    }
    *als_vis = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    uint8_t part_id;
    if (i2c_read_reg8(fd, 0x00, &part_id) < 0) {
        fprintf(stderr, "Error: Si1175 not detected at address 0x%02X (bus error or sensor absent)\n", SI1175_ADDR);
        goto cleanup;
    }
    printf("Si1175 detected, Part ID: 0x%02X\n", part_id);

    while (running) {
        uint16_t als_vis;
        if (read_als_vis(fd, &als_vis) < 0) {
            fprintf(stderr, "Error reading ALS_VIS registers: %s\n", strerror(errno));
            break;
        }
        printf("ALS_VIS: %u\n", als_vis);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

