/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod (v1.x API).
 *
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: TTP226 (8-channel, active-high outputs)
 * Wiring:
 *   TP1 -> BCM GPIO 5
 *   TP2 -> BCM GPIO 6
 *   TP3 -> BCM GPIO 13
 *   TP4 -> BCM GPIO 19
 *   TP5 -> BCM GPIO 26
 *   TP6 -> BCM GPIO 12
 *   TP7 -> BCM GPIO 16
 *   TP8 -> BCM GPIO 20
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int channel_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return;
    }
    printf("[%ld.%03lds] ", (long)ts.tv_sec, ts.tv_nsec / 1000000L);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    install_signal_handlers();

    /* Open the default gpiochip (gpiochip0 on RPi 3B+). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line and request it as input. */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line for BCM GPIO %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Failed to request BCM GPIO %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading BCM GPIO %u: %s\n",
                        channel_pins[i], strerror(errno));
                error = 1;
                break;
            }
            values[i] = val;
        }

        if (error)
            break;

        print_timestamp();
        for (int i = 0; i < NUM_CHANNELS; i++)
            printf("CH%d=%d ", i + 1, values[i]);
        printf("\n");
        fflush(stdout);

        struct timespec sleep_ts = {
            .tv_sec  = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

