            fprintf(stderr, "Failed to get line for BCM GPIO %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Failed to request BCM GPIO %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading BCM GPIO %u: %s\n",
                        channel_pins[i], strerror(errno));
                error = 1;
                break;
            }
            values[i] = val;
        }

        if (error)
            break;

        print_timestamp();
        for (int i = 0; i < NUM_CHANNELS; i++)
            printf("CH%d=%d ", i + 1, values[i]);
        printf("\n");
        fflush(stdout);

        struct timespec sleep_ts = {
            .tv_sec  = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

