#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DELAY_US (5000000 / FADE_STEPS)
#define FADE_DURATION_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int clamp_int(int v, int lo, int hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static void set_led_color(int r, int g, int b) {
    int ir = clamp_int(r, 0, 255);
    int ig = clamp_int(g, 0, 255);
    int ib = clamp_int(b, 0, 255);
    if (gpioPWM(RED_PIN,   PWM_RANGE - ir) != 0) syslog(LOG_ERR, "gpioPWM red failed");
    if (gpioPWM(GREEN_PIN, PWM_RANGE - ig) != 0) syslog(LOG_ERR, "gpioPWM green failed");
    if (gpioPWM(BLUE_PIN,  PWM_RANGE - ib) != 0) syslog(LOG_ERR, "gpioPWM blue failed");
}

static void turn_off_led(void) {
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
}

static void fade_to_color(int tr, int tg, int tb, int steps) {
    int cr = 0, cg = 0, cb = 0;
    int dr = tr - cr, dg = tg - cg, db = tb - cb;
    for (int i = 0; i < steps && g_running; i++) {
        int s = (float)i / (steps - 1);
        int nr = cr + (int)(dr * s);
        int ng = cg + (int)(dg * s);
        int nb = cb + (int)(db * s);
        set_led_color(nr, ng, nb);
        gpioDelay(FADE_DELAY_US);
    }
}

static void generate_random_hue(float *h, float *s, float *v) {
    *h = (float)rand() / RAND_MAX;
    *s = 1.0f;
    *v = 1.0f;
}

static void hue_to_rgb(float h, float s, float v, int *r, int *g, int *b) {
    if (s == 0.0f) {
        *r = *g = *b = (int)(v * 255.0f);
        return;
    }
    float hh = h * 6.0f;
    int   i  = (int)hh;
    float f  = hh - (float)i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - s * f);
    float t = v * (1.0f - s * (1.0f - f));
    switch (i % 6) {
        case 0: *r = (int)(v * 255.0f); *g = (int)(t * 255.0f); *b = (int)(p * 255.0f); break;
        case 1: *r = (int)(q * 255.0f); *g = (int)(v * 255.0f); *b = (int)(p * 255.0f); break;
        case 2: *r = (int)(p * 255.0f); *g = (int)(v * 255.0f); *b = (int)(t * 255.0f); break;
        case 3: *r = (int)(p * 255.0f); *g = (int)(q * 255.0f); *b = (int)(v * 255.0f); break;
        case 4: *r = (int)(t * 255.0f); *g = (int)(p * 255.0f); *b = (int)(v * 255.0f); break;
        case 5: *r = (int)(v * 255.0f); *g = (int)(p * 255.0f); *b = (int)(q * 255.0f); break;
    }
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction SIGINT failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction SIGTERM failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode RED_PIN failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode GREEN_PIN failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode BLUE_PIN failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "open /dev/urandom failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    unsigned int seed;
    ssize_t n = read(fd, &seed, sizeof(seed));
    close(fd);
    if (n != (ssize_t)sizeof(seed)) {
        syslog(LOG_ERR, "read /dev/urandom failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    srand((unsigned int)seed);

    float hue = 0.0f;
    float sat = 1.0f;
    float val = 1.0f;
    int   r, g, b;
    hue_to_rgb(hue, sat, val, &r, &g, &b);

    while (g_running) {
        fade_to_color(r, g, b, FADE_STEPS);
        if (!g_running) break;

        generate_random_hue(&hue, &sat, &val);
        hue_to_rgb(hue, sat, val, &r, &g, &b);

        for (int i = 0; i < FADE_DURATION_S && g_running; i++) {
            sleep(1);
        }
    }

    turn_off_led();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

