/*
 * TCS34725 color sensor reader with libgpiod LED control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: libgpiod (GPIO), Linux i2c-dev (I2C)
 *
 * Wiring:
 *   TCS34725 SDA -> GPIO2  (BCM 2, I2C bus 1)
 *   TCS34725 SCL -> GPIO3  (BCM 3, I2C bus 1)
 *   TCS34725 VDD -> 3V3
 *   TCS34725 GND -> GND
 *   LED anode   -> GPIO17 (BCM 17) through ~330 ohm resistor
 *   LED cathode -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tcs34725_led tcs34725_led.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ---- TCS34725 constants (datasheet) ---- */
#define TCS34725_I2C_ADDR        0x29
#define TCS34725_COMMAND_BIT     0x80

#define TCS34725_REG_ENABLE      0x00
#define TCS34725_REG_ATIME       0x01
#define TCS34725_REG_CONTROL     0x0F
#define TCS34725_REG_ID          0x12
#define TCS34725_REG_CDATA       0x14
#define TCS34725_REG_RDATA       0x16
#define TCS34725_REG_GDATA       0x18
#define TCS34725_REG_BDATA       0x1A

#define TCS34725_ENABLE_PON      0x01
#define TCS34725_ENABLE_AEN      0x02
#define TCS34725_ENABLE_PON_AEN  (TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN)

#define TCS34725_ID_VALUE        0x44

/* ---- Application constants ---- */
#define I2C_BUS_NAME             "/dev/i2c-1"
#define GPIO_CHIP_NAME           "gpiochip4"   /* BCM GPIO on Pi 4 */
#define GPIO_LED_OFFSET          17
#define RED_THRESHOLD            200
#define POLL_INTERVAL_MS         200
#define MAX_REINIT_ATTEMPTS      3

/* Per-channel calibration (example values — calibrate for your sensor) */
#define RED_GAIN   1.0f
#define RED_OFFSET 0.0f
#define GREEN_GAIN 1.0f
#define GREEN_OFFSET 0.0f
#define BLUE_GAIN  1.0f
#define BLUE_OFFSET 0.0f
#define CLEAR_GAIN 1.0f
#define CLEAR_OFFSET 0.0f

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int                   g_i2c_fd  = -1;
static struct gpiod_chip    *g_chip    = NULL;
static struct gpiod_line    *g_led_line = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Millisecond sleep that is interruptible by signals.                 */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!g_running)
            return;
    }
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register.                              */
static int tcs_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register.                             */
static int tcs_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (cmd) to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian channel register.                       */
static int tcs_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (cmd) to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 2 bytes from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TCS34725: power on, set integration time, gain,     */
/* verify ID, and enable RGBC.                                         */
static int tcs_init(int fd)
{
    uint8_t id = 0;

    /* Power on */
    if (tcs_write_reg(fd, TCS34725_REG_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    sleep_ms(3);

    /* Set integration time to ~154 ms (ATIME = 0x00) */
    if (tcs_write_reg(fd, TCS34725_REG_ATIME, 0x00) < 0)
        return -1;

    /* Set gain to 1x (CONTROL = 0x00) */
    if (tcs_write_reg(fd, TCS34725_REG_CONTROL, 0x00) < 0)
        return -1;

    /* Enable RGBC */
    if (tcs_write_reg(fd, TCS34725_REG_ENABLE, TCS34725_ENABLE_PON_AEN) < 0)
        return -1;
    sleep_ms(3);

    /* Verify sensor ID */
    if (tcs_read_reg(fd, TCS34725_REG_ID, &id) < 0)
        return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected sensor ID 0x%02X (expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four channels and apply calibration.                       */
static int tcs_read_all(int fd,
                        float *r, float *g, float *b, float *c)
{
    uint16_t cr, cg, cb, cc;

    if (tcs_read_word(fd, TCS34725_REG_CDATA, &cc) < 0) return -1;
    if (tcs_read_word(fd, TCS34725_REG_RDATA, &cr) < 0) return -1;
    if (tcs_read_word(fd, TCS34725_REG_GDATA, &cg) < 0) return -1;
    if (tcs_read_word(fd, TCS34725_REG_BDATA, &cb) < 0) return -1;

    *r = (float)cr * RED_GAIN   + RED_OFFSET;
    *g = (float)cg * GREEN_GAIN + GREEN_OFFSET;
    *b = (float)cb * BLUE_GAIN  + BLUE_OFFSET;
    *c = (float)cc * CLEAR_GAIN + CLEAR_OFFSET;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Power down the sensor */
        if (g_i2c_fd >= 0)
            tcs_write_reg(g_i2c_fd, TCS34725_REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
