#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define LED_GPIO 18
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_MEASURE_MS 180
#define NUM_LEDS 10
#define PWM_FREQ 800000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = BH1750_CONT_HIGH_RES;
    char buf[2];
    int ret;

    ret = i2cWriteDevice(handle, &cmd, 1);
    if (ret != 0) {
        fprintf(stderr, "BH1750 write error: %d\n", ret);
        return -1;
    }

    usleep(BH1750_MEASURE_MS * 1000);

    ret = i2cReadDevice(handle, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "BH1750 read error: %d\n", ret);
        return -1;
    }

    uint16_t raw = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_led_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    gpioPWM(gpio, brightness);
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 1000.0f) lux = 1000.0f;
    float norm = lux / 1000.0f;
    int brightness = (int)(255.0f * (1.0f - expf(-norm * 10.0f)));
    return brightness;
}

static void generate_ws2812b_wave(int num_leds, int *brightnesses, int *pulses) {
    int idx = 0;
    for (int i = 0; i < num_leds; i++) {
        int b = brightnesses[i];
        for (int j = 7; j >= 0; j--) {
            int bit = (b >> j) & 1;
            if (bit) {
                pulses[idx++] = 1;
                pulses[idx++] = 0;
            } else {
                pulses[idx++] = 0;
                pulses[idx++] = 1;
            }
        }
    }
}

static void send_ws2812b_strip(int num_leds, int *brightnesses) {
    int num_pulses = num_leds * 8 * 2;
    int *pulses = malloc(num_pulses * sizeof(int));
    if (!pulses) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    generate_ws2812b_wave(num_leds, brightnesses, pulses);

    gpioWaveClear();
    gpioPulse_t *wave_pulses = malloc(num_pulses * sizeof(gpioPulse_t));
    if (!wave_pulses) {
        fprintf(stderr, "Memory allocation failed\n");
        free(pulses);
        return;
    }

    for (int i = 0; i < num_pulses; i++) {
        wave_pulses[i].gpioOn = (1 << LED_GPIO);
        wave_pulses[i].gpioOff = 0;
        wave_pulses[i].usDelay = pulses[i];
    }

    gpioWaveAddGeneric(num_pulses, wave_pulses);
    int wave_id = gpioWaveCreate();
    free(wave_pulses);
    free(pulses);

    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
        while (gpioWaveTxBusy()) {
            usleep(100);
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Failed to create wave\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", BH1750_ADDR);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int led_brightnesses[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) led_brightnesses[i] = 0;

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_handle, &lux) != 0) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            usleep(1000000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        for (int i = 0; i < NUM_LEDS; i++) {
            led_brightnesses[i] = brightness;
        }

        send_ws2812b_strip(NUM_LEDS, led_brightnesses);
        usleep(100000);
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        led_brightnesses[i] = 0;
    }
    send_ws2812b_strip(NUM_LEDS, led_brightnesses);

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

