        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int led_brightnesses[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) led_brightnesses[i] = 0;

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_handle, &lux) != 0) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            usleep(1000000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        for (int i = 0; i < NUM_LEDS; i++) {
            led_brightnesses[i] = brightness;
        }

        send_ws2812b_strip(NUM_LEDS, led_brightnesses);
        usleep(100000);
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        led_brightnesses[i] = 0;
    }
    send_ws2812b_strip(NUM_LEDS, led_brightnesses);

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

