#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS 120

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define NUM_LEDS 32

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    if (i2c_write_cmd(fd, BH1750_CMD_OT_HRES) < 0) return -1;
    usleep(BH1750_CONV_MS * 1000);
    uint8_t buf[2];
    if (i2c_read_data(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 10.0f) lux = 10.0f;
    if (lux > 300.0f) lux = 300.0f;
    return (int)(((lux - 10.0f) / 290.0f) * 31.0f);
}

static int send_apa102_frame(int fd, int brightness) {
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t led_frame[4];
    led_frame[0] = 0xE0 | (brightness & 0x1F);
    led_frame[1] = 0x00;
    led_frame[2] = 0xFF;
    led_frame[3] = 0x00;
    uint8_t start_frame[8] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (write(fd, start_frame, sizeof(start_frame)) != (ssize_t)sizeof(start_frame)) {
        fprintf(stderr, "SPI start frame write failed: %s\n", strerror(errno));
        return -1;
    }
    for (int i = 0; i < NUM_LEDS; i++) {
        if (write(fd, led_frame, sizeof(led_frame)) != (ssize_t)sizeof(led_frame)) {
            fprintf(stderr, "SPI LED frame write failed: %s\n", strerror(errno));
            return -1;
        }
    }
    if (write(fd, end_frame, sizeof(end_frame)) != (ssize_t)sizeof(end_frame)) {
        fprintf(stderr, "SPI end frame write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        send_apa102_frame(spi_fd, 0);
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting BH1750 light sensor and APA102 LED control. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(1000000);
            continue;
        }
        int brightness = map_lux_to_brightness(lux);
        if (send_apa102_frame(spi_fd, brightness) < 0) {
            fprintf(stderr, "SPI write error, retrying...\n");
        }
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

