#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR_LOW  0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_H2 0x21
#define BH1750_CONV_MS   180

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define NUM_LEDS         10
#define NUM_SENSORS      3

#define FADE_STEPS       50
#define FADE_DELAY_MS    10
#define LOOP_DELAY_MS    100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[NUM_SENSORS];
static int g_spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int bh1750_read_lux(int handle) {
    if (handle < 0) return -1;

    if (i2cWriteByte(handle, BH1750_CMD_OT_H2) < 0) {
        fprintf(stderr, "BH1750 write error (handle %d)\n", handle);
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);

    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read error (handle %d, got %d bytes)\n", handle, n);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (int)(raw / 1.2);
}

static void apa102_set_global(uint8_t brightness) {
    if (g_spi_handle < 0) return;
    if (brightness > 31) brightness = 31;

    uint8_t buf[4 + NUM_LEDS * 4 + 4];
    int idx = 0;
    buf[idx++] = 0x00;
    buf[idx++] = 0x00;
    buf[idx++] = 0x00;
    buf[idx++] = 0xFF;
    for (int i = 0; i < NUM_LEDS; i++) {
        buf[idx++] = 0xE0 | (brightness & 0x1F);
        buf[idx++] = 0x00;
        buf[idx++] = 0x00;
        buf[idx++] = 0x00;
    }
    buf[idx++] = 0x00;
    buf[idx++] = 0x00;
    buf[idx++] = 0x00;
    buf[idx++] = 0xFF;

    if (spiWrite(g_spi_handle, (char *)buf, idx) < 0) {
        fprintf(stderr, "SPI write error\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) g_i2c_handles[i] = -1;

    g_i2c_handles[0] = i2cOpen(1, BH1750_ADDR_LOW, 0);
    if (g_i2c_handles[0] < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x%02X not found\n", BH1750_ADDR_LOW);
    }
    g_i2c_handles[1] = i2cOpen(1, BH1750_ADDR_HIGH, 0);
    if (g_i2c_handles[1] < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x%02X not found\n", BH1750_ADDR_HIGH);
    }
    g_i2c_handles[2] = -1;

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        for (int i = 0; i < NUM_SENSORS; i++) i2cClose(g_i2c_handles[i]);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int target_brightness = 15;
    int current_brightness = 15;

    while (g_running) {
        int valid = 0;
        int sum = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            int lux = bh1750_read_lux(g_i2c_handles[i]);
            if (lux >= 0) { sum += lux; valid++; }
        }

        int avg_lux = (valid > 0) ? (sum / valid) : 0;
        target_brightness = 31 - (int)((float)avg_lux / 1000.0f * 31.0f);
        if (target_brightness < 0) target_brightness = 0;
        if (target_brightness > 31) target_brightness = 31;

        int step_size = (target_brightness - current_brightness) / FADE_STEPS;
        if (step_size == 0) step_size = (target_brightness > current_brightness) ? 1 : -1;

        for (int i = 0; i < FADE_STEPS && g_running; i++) {
            current_brightness += step_size;
            if (current_brightness < 0) current_brightness = 0;
            if (current_brightness > 31) current_brightness = 31;
            apa102_set_global((uint8_t)current_brightness);
            gpioDelay(FADE_DELAY_MS * 1000);
        }

        if (!g_running) break;
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    apa102_set_global(0);
    spiClose(g_spi_handle);
    for (int i = 0; i < NUM_SENSORS; i++) i2cClose(g_i2c_handles[i]);
    gpioTerminate();
    return EXIT_SUCCESS;
}

