int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Initialize VEML7700 sensor
int init_veml7700(void) {
    uint8_t buf[3];
    buf[0] = VEML7700_CONFIG_REG;
    buf[1] = 0x00; // Integration time 100 ms, gain 1/8
    buf[2] = 0x00;
    if (write(i2c_fd, buf, 3) != 3) {
        fprintf(stderr, "Failed to write VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait 10 ms for configuration to take effect
    return 0;
}

// Read lux value from VEML7700 with retry logic
int read_veml7700_lux(float *lux) {
    uint8_t reg = VEML7700_ALS_DATA_REG;
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "Failed to write ALS register address: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        uint16_t raw = (buf[1] << 8) | buf[0];
        // lux = raw * 0.0288 (default settings: 100ms/100ms, gain 1/8)
        *lux = (float)raw * 0.0288f;
        return 0;
    }
    fprintf(stderr, "Failed to read VEML7700 after %d retries\n", MAX_RETRIES);
    return -1;
}

// Set LED brightness using libgpiod bit-banging (800 kHz)
int set_led_brightness(int brightness) {
    if (!line) return -1;

    // WS2812B timing: T0H = 0.4 us, T0L = 0.8 us, T1H = 0.8 us, T1L = 0.4 us
    // At 800 kHz, each bit is 1.25 us. Duty cycle = brightness / 255 * 1.25 us
    // We use a simple on/off approach for simplicity
    int on_time_us = (brightness * 1250) / 255; // Approximate on time in microseconds
    int off_time_us = 1250 - on_time_us;

    if (on_time_us > 0) {
        gpiod_line_set_value(line, 1);
        usleep(on_time_us);
    }
    if (off_time_us > 0) {
        gpiod_line_set_value(line, 0);
        usleep(off_time_us);
    }
    return 0;
