    if (init_veml7700() < 0) {
        cleanup();
        return 1;
    }

    printf("VEML7700 and WS2812B initialized. Running...\n");

    // Main loop
    while (keep_running) {
        float lux = 0.0f;
        if (read_veml7700_lux(&lux) == 0) {
            int brightness = map_lux_to_brightness(lux);
            if (set_led_brightness(brightness) == 0) {
