#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define POLL_INTERVAL_MS 50
#define SELF_TEST_DELAY_MS 100
#define SELF_TEST_REPEATS 5
#define SELF_TEST_BLINK_MS 500
#define ALARM_BUZZER_SHORT_MS 200
#define ALARM_BUZZER_LONG_MS 600
#define ALARM_BUZZER_REPEATS 3
#define ALARM_LED_BLINK_MS 100
#define ALARM_LED_CYCLES 5

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

static void cleanup_resources(void) {
    if (flame_line) {
        gpiod_line_release(flame_line);
        flame_line = NULL;
    }
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("Failed to get flame sensor line");
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("Failed to request flame sensor line as input");
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line as output");
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line as output");
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int val = gpiod_line_get_value(flame_line);
    if (val < 0) {
        perror("Failed to read flame sensor");
        return -1;
    }
    return val;
}

static int set_buzzer(int state) {
    if (gpiod_line_set_value(buzzer_line, state) < 0) {
        perror("Failed to set buzzer");
        return -1;
    }
    return 0;
}

static int set_led(int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        perror("Failed to set LED");
        return -1;
    }
    return 0;
}

static void self_test(void) {
    log_event("Starting self-test...");

    log_event("Blinking LED...");
    for (int i = 0; i < 2; i++) {
        if (set_led(1) < 0) return;
        usleep(SELF_TEST_BLINK_MS * 1000);
        if (set_led(0) < 0) return;
        usleep(SELF_TEST_BLINK_MS * 1000);
    }

    log_event("Reading flame sensor...");
    int fault = 0;
    for (int i = 0; i < SELF_TEST_REPEATS; i++) {
        int val = read_flame_sensor();
        if (val < 0) {
            fault = 1;
            break;
        }
        if (val == 0) {
            fault = 1;
            break;
        }
        usleep(SELF_TEST_DELAY_MS * 1000);
    }

    if (fault) {
        log_event("Self-test failed: flame sensor fault detected");
        log_event("Triggering alarm pattern...");
        for (int i = 0; i < ALARM_LED_CYCLES; i++) {
            if (set_led(1) < 0) return;
            usleep(ALARM_LED_BLINK_MS * 1000);
            if (set_led(0) < 0) return;
            usleep(ALARM_LED_BLINK_MS * 1000);
        }
        for (int i = 0; i < ALARM_BUZZER_REPEATS; i++) {
            if (set_buzzer(1) < 0) return;
            usleep(ALARM_BUZZER_SHORT_MS * 1000);
            if (set_buzzer(0) < 0) return;
            usleep(ALARM_BUZZER_SHORT_MS * 1000);
            if (set_buzzer(1) < 0) return;
            usleep(ALARM_BUZZER_LONG_MS * 1000);
            if (set_buzzer(0) < 0) return;
            usleep(ALARM_BUZZER_SHORT_MS * 1000);
        }
        log_event("Exiting due to self-test failure");
        cleanup_resources();
        exit(1);
    } else {
        log_event("Self-test passed");
    }
}

static void handle_flame_detection(void) {
    log_event("Flame detected!");
    if (set_buzzer(1) < 0) return;
    if (set_led(1) < 0) {
        set_buzzer(0);
        return;
    }
    log_event("Alarm activated");

    while (program_running) {
        int val = read_flame_sensor();
        if (val < 0) {
            log_event("Error reading flame sensor during alarm");
            break;
        }
        if (val == 1) {
            log_event("Flame gone!");
            break;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (set_buzzer(0) < 0) return;
    if (set_led(0) < 0) return;
    log_event("Alarm deactivated");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("GPIO initialization failed");
        cleanup_resources();
        return 1;
    }

    self_test();

    log_event("Entering main loop...");
    while (program_running) {
        int val = read_flame_sensor();
        if (val < 0) {
            log_event("Error reading flame sensor in main loop");
            break;
        }
        if (val == 0) {
            handle_flame_detection();
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("Exiting program");
    cleanup_resources();
    return 0;
}

