        return -1;
    }
    return 0;
}

static void self_test(void) {
    log_event("Starting self-test...");

    log_event("Blinking LED...");
    for (int i = 0; i < 2; i++) {
        if (set_led(1) < 0) return;
        usleep(SELF_TEST_BLINK_MS * 1000);
        if (set_led(0) < 0) return;
        usleep(SELF_TEST_BLINK_MS * 1000);
    }

    log_event("Reading flame sensor...");
    int fault = 0;
    for (int i = 0; i < SELF_TEST_REPEATS; i++) {
        int val = read_flame_sensor();
        if (val < 0) {
            fault = 1;
            break;
        }
        if (val == 0) {
            fault = 1;
            break;
        }
        usleep(SELF_TEST_DELAY_MS * 1000);
    }

    if (fault) {
        log_event("Self-test failed: flame sensor fault detected");
        log_event("Triggering alarm pattern...");
        for (int i = 0; i < ALARM_LED_CYCLES; i++) {
            if (set_led(1) < 0) return;
            usleep(ALARM_LED_BLINK_MS * 1000);
            if (set_led(0) < 0) return;
            usleep(ALARM_LED_BLINK_MS * 1000);
        }
        for (int i = 0; i < ALARM_BUZZER_REPEATS; i++) {
            if (set_buzzer(1) < 0) return;
            usleep(ALARM_BUZZER_SHORT_MS * 1000);
            if (set_buzzer(0) < 0) return;
            usleep(ALARM_BUZZER_SHORT_MS * 1000);
            if (set_buzzer(1) < 0) return;
            usleep(ALARM_BUZZER_LONG_MS * 1000);
            if (set_buzzer(0) < 0) return;
            usleep(ALARM_BUZZER_SHORT_MS * 1000);
        }
        log_event("Exiting due to self-test failure");
        cleanup_resources();
        exit(1);
    } else {
        log_event("Self-test passed");
    }
}

static void handle_flame_detection(void) {
    log_event("Flame detected!");
    if (set_buzzer(1) < 0) return;
    if (set_led(1) < 0) {
        set_buzzer(0);
        return;
    }
    log_event("Alarm activated");

    while (program_running) {
        int val = read_flame_sensor();
        if (val < 0) {
            log_event("Error reading flame sensor during alarm");
            break;
        }
        if (val == 1) {
            log_event("Flame gone!");
            break;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (set_buzzer(0) < 0) return;
    if (set_led(0) < 0) return;
    log_event("Alarm deactivated");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("GPIO initialization failed");
        cleanup_resources();
        return 1;
    }

    self_test();

    log_event("Entering main loop...");
    while (program_running) {
        int val = read_flame_sensor();
        if (val < 0) {
            log_event("Error reading flame sensor in main loop");
            break;
        }
        if (val == 0) {
            handle_flame_detection();
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("Exiting program");
    cleanup_resources();
    return 0;
}

