#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define BH1750_ADDR     0x23
#define BH1750_CMD_CONT_HRES 0x10
#define GPIO_LED        17
#define BUFFER_SIZE     60
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_export(int pin) {
    char path[64];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open export: %s\n", strerror(errno));
        return -1;
    }
    snprintf(path, sizeof(path), "%d", pin);
    if (write(fd, path, strlen(path)) < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char path[64];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(path, sizeof(path), "%d", pin);
    if (write(fd, path, strlen(path)) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open direction for GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "Failed to set direction for GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open value for GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    char val = (value ? '1' : '0');
    if (write(fd, &val, 1) < 0) {
        fprintf(stderr, "Failed to write GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static float calculate_average_lux(const float *buffer, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

static float map_lux_to_blink_rate(float avg_lux) {
    float rate = 0.5f + (avg_lux / 1000.0f) * 4.5f;
    if (rate < 0.5f) rate = 0.5f;
    if (rate > 5.0f) rate = 5.0f;
    return rate;
}

int main(void) {
    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;
    int i2c_fd = -1;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        lux_buffer[i] = 0.0f;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpio_export(GPIO_LED) < 0) {
        return EXIT_FAILURE;
    }
    usleep(100000);
    if (gpio_set_direction(GPIO_LED, "out") < 0) {
        gpio_unexport(GPIO_LED);
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        gpio_unexport(GPIO_LED);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        gpio_unexport(GPIO_LED);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_fd, BH1750_CMD_CONT_HRES) < 0) {
        fprintf(stderr, "Failed to initialize BH1750\n");
        close(i2c_fd);
        gpio_unexport(GPIO_LED);
        return EXIT_FAILURE;
    }

    usleep(180000);

    while (running) {
        uint8_t data[2];
        if (i2c_read_bytes(i2c_fd, data, 2) < 0) {
            fprintf(stderr, "Failed to read BH1750 data\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        float lux = (float)raw / 1.2f;

        lux_buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        float avg_lux = calculate_average_lux(lux_buffer, buffer_count);
        float blink_rate = map_lux_to_blink_rate(avg_lux);
        float half_period = 1.0f / (2.0f * blink_rate);

        if (gpio_write(GPIO_LED, 1) < 0) {
            fprintf(stderr, "Failed to turn LED on\n");
        }
        usleep((useconds_t)(half_period * 1000000.0f));

        if (gpio_write(GPIO_LED, 0) < 0) {
            fprintf(stderr, "Failed to turn LED off\n");
        }
        usleep((useconds_t)(half_period * 1000000.0f));

        printf("Lux: %.2f, Avg Lux: %.2f, Blink Rate: %.2f Hz\n", lux, avg_lux, blink_rate);
    }

    gpio_write(GPIO_LED, 0);
    gpio_unexport(GPIO_LED);
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

