#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);
}

int setup_gpio(void) {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return -1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("gpiod_chip_get_line");
        release_resources();
        return -1;
    }

    if (gpiod_line_request_output(data_line, "seven_seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven_seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven_seg", 0) < 0) {
        perror("gpiod_line_request_output");
        release_resources();
        return -1;
    }

    return 0;
}

void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        gpiod_line_set_value(data_line, bit);
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
    }
}

void display_digit(unsigned char digit) {
    // Segment patterns for digits 0-9 (common cathode, active high)
    // Order: a,b,c,d,e,f,g,dp (dp=0)
    static const unsigned char patterns[] = {
        0b01111110, // 0
        0b00001100, // 1
        0b10110110, // 2
        0b10011110, // 3
        0b11001100, // 4
        0b11011010, // 5
        0b11111010, // 6
        0b00001110, // 7
        0b11111110, // 8
        0b11011110  // 9
    };

    if (digit > 9) digit = 0;
    shift_out(patterns[digit]);
    gpiod_line_set_value(latch_line, 1);
    usleep(1);
    gpiod_line_set_value(latch_line, 0);
    usleep(1);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        display_digit(5);
        usleep(500000);
        if (!keep_running) break;
        display_digit(0);
        usleep(500000);
    }

    release_resources();
    return EXIT_SUCCESS;
}

