/*
 * Blink an LED on BCM GPIO17 while waiting for a button press on BCM GPIO18.
 *
 * Wiring (Raspberry Pi 40-pin header):
 *   LED anode  -> pin 11 (BCM 17)
 *   LED cathode -> pin 9  (common ground)
 *   Button     -> pin 12 (BCM 18) to GND
 *   (Internal pull-up enabled on button line.)
 *
 * Build:  gcc -o blink_button blink_button.c -lgpiod
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define LED_LINE_OFFSET  17   /* BCM 17, physical pin 11 */
#define BUTTON_LINE_OFFSET 18 /* BCM 18, physical pin 12 */
#define BLINK_PERIOD_MS  1000
#define POLL_TIMEOUT_MS  1000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    struct timespec ts;
    int ret;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* --- Get the LED line --- */
    led_line = gpiod_chip_get_line(chip, LED_LINE_OFFSET);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- Request LED line as output, initially low --- */
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- Get the button line --- */
    button_line = gpiod_chip_get_line(chip, BUTTON_LINE_OFFSET);
    if (!button_line) {
        perror("gpiod_chip_get_line(button)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- Request button line as input with internal pull-up and falling-edge events --- */
    ret = gpiod_line_request_falling_edge_events_flags(button_line,
            "blink_button",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events_flags");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Press the button (BCM GPIO18, pin 12) to stop blinking.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Blink loop --- */
    while (g_running) {
        int val = gpiod_line_get_value(led_line);
        if (val < 0) {
            perror("gpiod_line_get_value(LED)");
            break;
        }

        int new_val = (val == 0) ? 1 : 0;
        ret = gpiod_line_set_value(led_line, new_val);
        if (ret < 0) {
            perror("gpiod_line_set_value(LED)");
            break;
        }

        /* Wait up to POLL_TIMEOUT_MS for a button event */
        ts.tv_sec  = POLL_TIMEOUT_MS / 1000;
        ts.tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L;

        ret = gpiod_line_event_wait(button_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;  /* Interrupted by signal; check g_running */
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret > 0) {
            /* Event available — read it to clear the event queue */
            ret = gpiod_line_event_read(button_line, &event);
            if (ret < 0) {
                perror("gpiod_line_event_read");
                break;
            }

            /* Turn off LED and exit */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(LED, 0)");
            }
            printf("Button pressed! Stopping blinking.\n");
            fflush(stdout);
            break;
        }

        /* ret == 0: timeout, continue blinking */
        struct timespec sleep_ts;
        sleep_ts.tv_sec  = BLINK_PERIOD_MS / 1000;
        sleep_ts.tv_nsec = (BLINK_PERIOD_MS % 1000) * 1000000L;
        nanosleep(&sleep_ts, NULL);
    }

    /* --- Cleanup --- */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);   /* ensure LED is off */
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

