#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <stdint.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18
#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define PWM_STEPS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ns(long ns) {
    struct timespec req = {
        .tv_sec = ns / 1000000000L,
        .tv_nsec = ns % 1000000000L
    };
    while (clock_nanosleep(CLOCK_MONOTONIC, 0, &req, &req) == EINTR) {
        /* Retry if interrupted by signal */
    }
}

static void pwm_set_duty(struct gpiod_line *line, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_STEPS) duty = PWM_STEPS;

    long on_ns = (long)duty * PWM_PERIOD_NS / PWM_STEPS;
    long off_ns = PWM_PERIOD_NS - on_ns;

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting line high: %s\n", strerror(errno));
        return;
    }
    sleep_ns(on_ns);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting line low: %s\n", strerror(errno));
        return;
    }
    sleep_ns(off_ns);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (Raspberry Pi 5 uses gpiochip0) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    /* Get GPIO lines */
    red_line = gpiod_chip_get_line(chip, RED_PIN);
