#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADPD188BI I2C 7-bit address */
#define ADPD188BI_ADDR 0x39

/* ADPD188BI register addresses */
#define ADPD188BI_REG_MODE   0x0D
#define ADPD188BI_REG_ALS_LSB 0x64
#define ADPD188BI_REG_ALS_MSB 0x65
#define ADPD188BI_REG_RED_LSB 0x66
#define ADPD188BI_REG_RED_MSB 0x67
#define ADPD188BI_REG_GREEN_LSB 0x68
#define ADPD188BI_REG_GREEN_MSB 0x69
#define ADPD188BI_REG_BLUE_LSB 0x6A
#define ADPD188BI_REG_BLUE_MSB 0x6B

/* GPIO pin for LED (hardware PWM) */
#define LED_GPIO 18

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Retry delay after I2C error */
#define RETRY_DELAY_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADPD188BI register                        */
/* ------------------------------------------------------------------ */
static int adpd_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers     */
/* ------------------------------------------------------------------ */
static int adpd_read_reg16(int handle, uint8_t lsb_reg, uint16_t *out)
{
    int lsb = i2cReadByteData(handle, lsb_reg);
    if (lsb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                lsb_reg, strerror(errno));
        return -1;
    }
    int msb = i2cReadByteData(handle, lsb_reg + 1);
    if (msb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                lsb_reg + 1, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADPD188BI sensor                                     */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    /* Enter normal operation mode */
    if (adpd_write_reg(handle, ADPD188BI_REG_MODE, 0x01) < 0)
        return -1;

    /* Allow sensor to settle after mode change */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read ALS (ambient light) value                                      */
/* ------------------------------------------------------------------ */
static int read_als(int handle, uint16_t *als)
{
    return adpd_read_reg16(handle, ADPD188BI_REG_ALS_LSB, als);
}

/* ------------------------------------------------------------------ */
/* Read color (RGB) values                                             */
/* ------------------------------------------------------------------ */
static int read_color(int handle, uint16_t *red, uint16_t *green, uint16_t *blue)
{
    if (adpd_read_reg16(handle, ADPD188BI_REG_RED_LSB, red) < 0)   return -1;
    if (adpd_read_reg16(handle, ADPD188BI_REG_GREEN_LSB, green) < 0) return -1;
    if (adpd_read_reg16(handle, ADPD188BI_REG_BLUE_LSB, blue) < 0)  return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Map ALS value to PWM duty cycle (0-255)                             */
/* ------------------------------------------------------------------ */
static uint8_t map_als_to_pwm(uint16_t als)
{
    /* Linear mapping: 0 -> 0, 65535 -> 255 */
    return (uint8_t)(als >> 8);
}

/* ------------------------------------------------------------------ */
/* Log a reading to the CSV file                                       */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Turn off LED before terminating pigpio */
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO for hardware PWM */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, 1000); /* 1 kHz */
    gpioPWM(LED_GPIO, 0);                /* start with LED off */

    /* Open I2C bus to ADPD188BI */
    g_i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, ADPD188BI_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file */
    g_log_file = fopen("color_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open color_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t als = 0, red = 0, green = 0, blue = 0;

        if (read_als(g_i2c_handle, &als) < 0 ||
            read_color(g_i2c_handle, &red, &green, &blue) < 0) {
            fprintf(stderr, "[WARN] I2C read error, retrying in %d ms...\n",
                    RETRY_DELAY_US / 1000);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint8_t pwm_value = map_als_to_pwm(als);
        gpioPWM(LED_GPIO, pwm_value);

        log_data(g_log_file, als, red, green, blue);

        printf("ALS: %u, R: %u, G: %u, B: %u, PWM: %u\n",
               als, red, green, blue, pwm_value);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

