#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDRESS 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_CTRL_REG1   0x2A
#define FXOS8700_OUT_X_MSB   0x01

/* Expected device ID */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* Impact threshold: 2g in m/s^2 */
#define IMPACT_THRESHOLD_MS2 19.62

/* Sensitivity for ±2g range: 4096 counts per g */
#define SENSITIVITY_2G 4096.0

/* Sample period in microseconds (50 ms) */
#define SAMPLE_PERIOD_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an FXOS8700CQ register; abort on failure            */
/* ------------------------------------------------------------------ */
static int fxos_write_byte(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an FXOS8700CQ register                             */
/* ------------------------------------------------------------------ */
static int fxos_read_byte(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (6 bytes) and convert to m/s^2                   */
/* ------------------------------------------------------------------ */
static int read_acceleration(float *x, float *y, float *z)
{
    char buffer[6];

    int rc = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading acceleration block (rc=%d)\n", rc);
        return -1;
    }

    /* 14-bit left-justified data: shift right by 2 */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    int16_t raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    int16_t raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Convert to m/s^2: 4096 counts/g for ±2g range, 9.81 m/s^2/g */
    *x = (float)raw_x * 9.81f / SENSITIVITY_2G;
    *y = (float)raw_y * 9.81f / SENSITIVITY_2G;
    *z = (float)raw_z * 9.81f / SENSITIVITY_2G;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log impact data to file                                             */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for appending\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Initialize FXOS8700CQ: standby -> configure -> active               */
/* ------------------------------------------------------------------ */
static int initialize_fxos8700(void)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (fxos_read_byte(FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit (bit 0 of CTRL_REG1) */
    if (fxos_write_byte(FXOS8700_CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Failed to set standby mode\n");
        return -1;
    }

    /* Configure: ±2g range (XYZ_DATA_CFG = 0x00) */
    if (fxos_write_byte(FXOS8700_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Failed to set ±2g range\n");
        return -1;
    }

    /* Activate: active mode (bit 0 set), 200 Hz ODR -> 0x01 */
    if (fxos_write_byte(FXOS8700_CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Failed to set active mode\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (rc=%d)\n",
                FXOS8700_ADDRESS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_fxos8700() != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("FXOS8700CQ impact detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            float magnitude = sqrtf(x * x + y * y + z * z);

            if (magnitude > IMPACT_THRESHOLD_MS2) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2 (x=%.3f, y=%.3f, z=%.3f)\n",
                       magnitude, x, y, z);
            }
        } else {
            /* Transient read error: log and continue */
            fprintf(stderr, "Read error, continuing...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

