/*
 * GY-50 L3G4200D gyroscope logger for Raspberry Pi Zero W
 * Uses Linux i2c-dev ioctl interface (/dev/i2c-1).
 *
 * Wiring:
 *   GY-50 VCC  -> Pi 3V3 (pin 1)
 *   GY-50 GND  -> Pi GND (pin 9)
 *   GY-50 SCL  -> Pi GPIO3 / SCL1 (pin 5)
 *   GY-50 SDA  -> Pi GPIO2 / SDA1 (pin 3)
 *   GY-50 SA0  -> high (I2C address 0x69)
 *
 * Build:  gcc -O2 -Wall -o gyro_log gyro_log.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28

#define CTRL1_VAL      0x0F   /* normal mode, XYZ axes, 100 Hz ODR */
#define CTRL4_VAL      0x00   /* FS = +/-250 dps, continuous update */

#define SENSITIVITY    0.00875f   /* dps/LSB at +/-250 dps */
#define THRESHOLD_DPS  50.0f
#define SAMPLE_PERIOD_US 50000   /* 20 Hz */
#define CAL_SAMPLES    100

static volatile sig_atomic_t g_running = 1;
static int  g_fd = -1;
static FILE *g_log = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Set MSB = 0 to enable auto-increment for multi-byte reads */
    uint8_t cmd = reg | 0x80;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read_block write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block read(0x%02X, %zu) failed: got %zd (%s)\n",
                reg, len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ---- Gyroscope ---- */
typedef struct {
    float x, y, z;
} gyro_data_t;

static int gyro_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, CTRL1_VAL) < 0)
        return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, CTRL4_VAL) < 0)
        return -1;
    usleep(5000);  /* allow registers to settle */
    return 0;
}

static int gyro_read(int fd, gyro_data_t *out)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, OUT_X_L, raw, sizeof(raw)) < 0)
        return -1;

    int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

    out->x = (float)x * SENSITIVITY;
    out->y = (float)y * SENSITIVITY;
    out->z = (float)z * SENSITIVITY;
    return 0;
}

/* ---- Calibration ---- */
static int gyro_calibrate(int fd, gyro_data_t *cal)
{
    gyro_data_t sum = {0, 0, 0};
    int ok = 0;

    for (int i = 0; i < CAL_SAMPLES && g_running; i++) {
        gyro_data_t d;
        if (gyro_read(fd, &d) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return -1;
        }
        sum.x += d.x;
        sum.y += d.y;
        sum.z += d.z;
        ok++;
        usleep(10000);  /* 10 ms between samples */
    }
    if (ok == 0) {
        fprintf(stderr, "Calibration: no valid samples\n");
        return -1;
    }
    cal->x = sum.x / ok;
    cal->y = sum.y / ok;
    cal->z = sum.z / ok;
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *f, gyro_data_t cal, gyro_data_t raw)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv))
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");

    fprintf(f, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            ts, raw.x, raw.y, raw.z, cal.x, cal.y, cal.z);
    fflush(f);
}

static void check_threshold(gyro_data_t cal)
{
    if (cal.x > THRESHOLD_DPS || cal.x < -THRESHOLD_DPS ||
        cal.y > THRESHOLD_DPS || cal.y < -THRESHOLD_DPS ||
        cal.z > THRESHOLD_DPS || cal.z < -THRESHOLD_DPS) {
        fprintf(stderr,
                "WARNING: Gyroscope threshold exceeded (X=%.2f, Y=%.2f, Z=%.2f dps)\n",
                cal.x, cal.y, cal.z);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                GYRO_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gyro_init(g_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gyro_data_t cal;
    if (gyro_calibrate(g_fd, &cal) < 0) {
        fprintf(stderr, "Gyroscope calibration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Calibration complete: X=%.3f Y=%.3f Z=%.3f dps\n",
           cal.x, cal.y, cal.z);

    g_log = fopen("gyro_log.txt", "a");
    if (!g_log) {
        fprintf(stderr, "fopen(gyro_log.txt) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log, "# timestamp,raw_x,raw_y,raw_z,cal_x,cal_y,cal_z\n");
    fflush(g_log);

    while (g_running) {
        gyro_data_t raw;
        if (gyro_read(g_fd, &raw) < 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        gyro_data_t cal_out = {
            raw.x - cal.x,
            raw.y - cal.y,
            raw.z - cal.z
        };

        log_data(g_log, cal_out, raw);
        check_threshold(cal_out);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

