/*
 * ADXL345 accelerometer reader for Raspberry Pi 4 Model B
 * Library: pigpio (I2C + GPIO)
 * Bus: I2C-1, Address: 0x53
 * LED: GPIO17 (active-high)
 * Log: accel_log.txt  (timestamp,x,y,z)
 * Sample rate: 10 Hz
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDR        0x53
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_BW_RATE     0x2C

#define ADXL345_DEVID_VAL   0xE5

/* ---- Application constants ---- */
#define LED_GPIO            17
#define ACCEL_THRESHOLD_G   2.0f
#define SAMPLE_PERIOD_US    100000  /* 100 ms -> 10 Hz */
#define SCALE_FACTOR_G      0.0039f /* ±2g, full-resolution: 3.9 mg/LSB */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; abort on failure.            */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, val);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; abort on failure.           */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 consecutive bytes starting at DATAX0 (X-axis LSB first).    */
/* ------------------------------------------------------------------ */
static int adxl_read_xyz(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(0x%02X,6) failed\n",
                ADXL345_DATAX0);
        return -1;
    }

    *x = (int16_t)((uint8_t)buf[1] << 8 | (uint8_t)buf[0]);
    *y = (int16_t)((uint8_t)buf[3] << 8 | (uint8_t)buf[2]);
    *z = (int16_t)((uint8_t)buf[5] << 8 | (uint8_t)buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure ADXL345: full-resolution, ±2g, normal power, 100 Hz ODR.   */
/* ------------------------------------------------------------------ */
static int adxl_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (adxl_read_reg(handle, ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "[ERROR] DEVID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby first (clear measure bit) so configuration writes take effect */
    if (adxl_write_reg(handle, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* Data format: full resolution (bit 3), ±2g (bits 1:0 = 00) */
    if (adxl_write_reg(handle, ADXL345_DATA_FORMAT, 0x08) < 0)
        return -1;

    /* Output data rate: 100 Hz (0x0B) */
    if (adxl_write_reg(handle, ADXL345_BW_RATE, 0x0B) < 0)
        return -1;

    /* Enable measure bit (0x08 | 0x08 = 0x10) */
    if (adxl_write_reg(handle, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADXL345 counts to g.                                    */
/* ------------------------------------------------------------------ */
static void raw_to_g(int16_t x, int16_t y, int16_t z,
                     float *gx, float *gy, float *gz)
{
    *gx = (float)x * SCALE_FACTOR_G;
    *gy = (float)y * SCALE_FACTOR_G;
    *gz = (float)z * SCALE_FACTOR_G;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line: timestamp,x,y,z                                */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, float gx, float gy, float gz)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, gx, gy, gz) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw_x, raw_y, raw_z;
    float   gx, gy, gz;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (adxl_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen("accel_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open accel_log.txt for append\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (adxl_read_xyz(g_i2c_handle, &raw_x, &raw_y, &raw_z) < 0) {
            /* I2C error: turn LED off, wait and retry */
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        raw_to_g(raw_x, raw_y, raw_z, &gx, &gy, &gz);

        if (log_sample(g_log_file, gx, gy, gz) < 0) {
            /* Log write failed; keep running but do not illuminate LED */
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* LED on if any axis exceeds threshold */
        int exceed = (fabsf(gx) > ACCEL_THRESHOLD_G ||
                      fabsf(gy) > ACCEL_THRESHOLD_G ||
                      fabsf(gz) > ACCEL_THRESHOLD_G);
        gpioWrite(LED_GPIO, exceed ? 1 : 0);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

