#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define CTRL_REG1_A      0x20
#define OUT_X_L_A        0x28
#define MR_REG_M         0x02
#define OUT_X_H_M        0x03

/* Sensitivity: +/- 2g range => 1 mg/LSB => 0.001 g/LSB */
#define ACCEL_SCALE 0.001f

/* Sensitivity: +/- 1.3 Gauss range => 1.5 mGauss/LSB => 0.0015 g/LSB */
#define MAG_SCALE 0.0015f

#define LOG_FILE "compass_log.txt"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read 6 bytes from the accelerometer (auto-increment). */
static int read_accelerometer(int handle, float *x, float *y, float *z)
{
    char buf[6];

    if (i2cWriteByteData(handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: failed to configure accelerometer\n");
        return -1;
    }

    if (i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

/* Read 6 bytes from the magnetometer. */
static int read_magnetometer(int handle, float *x, float *y, float *z)
{
    char buf[6];

    if (i2cWriteByteData(handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error: failed to configure magnetometer\n");
        return -1;
    }

    if (i2cReadI2CBlockData(handle, OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read magnetometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;
    return 0;
}

/* Tilt-compensated heading in degrees. */
static float calculate_heading(float ax, float ay, float az,
                                float mx, float my, float mz)
{
    float roll  = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));

    float cr = cosf(roll);
    float sr = sinf(roll);
    float cp = cosf(pitch);
    float sp = sinf(pitch);

    float xh = mx * cp + mz * sp;
    float yh = mx * sp * sr + my * cr - mz * cp * sr;

    float heading = atan2f(yh, xh) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

static void log_data(float heading, float ax, float ay, float az,
                      float mx, float my, float mz)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading(deg),Accel_X(g),Accel_Y(g),Accel_Z(g),Mag_X(G),Mag_Y(G),Mag_Z(G)\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int accel_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C for accelerometer (handle %d)\n", accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int mag_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C for magnetometer (handle %d)\n", mag_handle);
        i2cClose(accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC Compass logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_accelerometer(accel_handle, &ax, &ay, &az) != 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (read_magnetometer(mag_handle, &mx, &my, &mz) != 0) {
            fprintf(stderr, "Warning: magnetometer read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float heading = calculate_heading(ax, ay, az, mx, my, mz);
        log_data(heading, ax, ay, az, mx, my, mz);
        printf("Heading: %.2f deg | Accel: %.4f %.4f %.4f g | Mag: %.4f %.4f %.4f G\n",
               heading, ax, ay, az, mx, my, mz);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

