        fprintf(stderr, "Error: failed to open I2C for magnetometer (handle %d)\n", mag_handle);
        i2cClose(accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC Compass logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_accelerometer(accel_handle, &ax, &ay, &az) != 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (read_magnetometer(mag_handle, &mx, &my, &mz) != 0) {
            fprintf(stderr, "Warning: magnetometer read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float heading = calculate_heading(ax, ay, az, mx, my, mz);
        log_data(heading, ax, ay, az, mx, my, mz);
        printf("Heading: %.2f deg | Accel: %.4f %.4f %.4f g | Mag: %.4f %.4f %.4f G\n",
               heading, ax, ay, az, mx, my, mz);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

