#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL6180X_ADDR 0x29
#define DISTANCE_THRESHOLD 100
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 100000

/* VL6180X register addresses */
#define REG_IDENTIFICATION_MODEL_ID 0x000
#define REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define REG_SYSRANGE_START 0x018
#define REG_RESULT_RANGE_STATUS 0x04d
#define REG_RESULT_RANGE_VAL 0x062

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address and 8-bit value via pigpio I2C. */
static int vl6180x_write_reg(uint8_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

/* Read an 8-bit value from a 16-bit register address. */
static int vl6180x_read_reg(uint8_t reg, uint8_t *value) {
    char addr_buf[2];
    char data_buf[1];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, addr_buf, 2) < 0) return -1;
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) return -1;
    *value = (uint8_t)data_buf[0];
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit register address. */
static int vl6180x_read_reg16(uint8_t reg, uint16_t *value) {
    char addr_buf[2];
    char data_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, addr_buf, 2) < 0) return -1;
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Mandatory initialization sequence for VL6180X. */
static int vl6180x_init(void) {
    uint8_t model_id = 0;
    uint16_t fresh_reset = 0;

    /* Read and verify model ID (should be 0xB4 for VL6180X). */
    if (vl6180x_read_reg(REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xB4) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xB4). Sensor not present?\n", model_id);
        return -1;
    }

    /* Read fresh-out-of-reset status. */
    if (vl6180x_read_reg16(REG_SYSTEM_FRESH_OUT_OF_RESET, &fresh_reset) < 0) {
        fprintf(stderr, "Error: Failed to read fresh-out-of-reset register.\n");
        return -1;
    }

    /* Mandatory initialization sequence. */
    if (vl6180x_write_reg(0x0207, 0x01) < 0) return -1;
    if (vl6180x_write_reg(0x0208, 0x01) < 0) return -1;
    if (vl6180x_write_reg(0x0096, 0x00) < 0) return -1;
    if (vl6180x_write_reg(0x0097, 0xFD) < 0) return -1;
    if (vl6180x_write_reg(0x00E3, 0x00) < 0) return -1;
    if (vl6180x_write_reg(0x00E4, 0x04) < 0) return -1;
    if (vl6180x_write_reg(0x00E5, 0x02) < 0) return -1;
    if (vl6180x_write_reg(0x00E6, 0x01) < 0) return -1;
    if (vl6180x_write_reg(0x00E7, 0x03) < 0) return -1;
    if (vl6180x_write_reg(0x00F5, 0x02) < 0) return -1;
    if (vl6180x_write_reg(0x00D9, 0x05) < 0) return -1;
    if (vl6180x_write_reg(0x00DB, 0xCE) < 0) return -1;
    if (vl6180x_write_reg(0x00DC, 0x03) < 0) return -1;
    if (vl6180x_write_reg(0x00DD, 0xF8) < 0) return -1;
    if (vl6180x_write_reg(0x009F, 0x00) < 0) return -1;
    if (vl6180x_write_reg(0x00A3, 0x3C) < 0) return -1;
    if (vl6180x_write_reg(0x00B7, 0x00) < 0) return -1;
    if (vl6180x_write_reg(0x00BB, 0x3C) < 0) return -1;
    if (vl6180x_write_reg(0x00B2, 0x09) < 0) return -1;
    if (vl6180x_write_reg(0x00CA, 0x09) < 0) return -1;
    if (vl6180x_write_reg(0x0198, 0x01) < 0) return -1;
    if (vl6180x_write_reg(0x01B0, 0x17) < 0) return -1;
    if (vl6180x_write_reg(0x01AD, 0x00) < 0) return -1;
    if (vl6180x_write_reg(0x00FF, 0x05) < 0) return -1;
    if (vl6180x_write_reg(0x0100, 0x05) < 0) return -1;
    if (vl6180x_write_reg(0x0199, 0x05) < 0) return -1;
    if (vl6180x_write_reg(0x01A6, 0x1B) < 0) return -1;
    if (vl6180x_write_reg(0x01AC, 0x3E) < 0) return -1;
    if (vl6180x_write_reg(0x01A7, 0x1F) < 0) return -1;
    if (vl6180x_write_reg(0x0030, 0x00) < 0) return -1;

    /* Clear fresh-out-of-reset bit to indicate initialization complete. */
    if (vl6180x_write_reg(0x016, 0x00) < 0) return -1;

    return 0;
}

/* Read distance in mm. Returns -1 on error, -2 on range error. */
static int vl6180x_read_distance(void) {
    uint8_t status = 0;
    uint16_t range = 0;

    /* Start a single-shot range measurement. */
    if (vl6180x_write_reg(REG_SYSRANGE_START, 0x01) < 0) return -1;

    /* Wait for measurement to complete (poll status register). */
    for (int i = 0; i < 100; i++) {
        if (vl6180x_read_reg(REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
        if ((status & 0x01) != 0) break;
        gpioDelay(1000); /* 1 ms */
    }

    if ((status & 0x01) == 0) {
        fprintf(stderr, "Error: Timeout waiting for range measurement.\n");
        return -1;
    }

    /* Check for errors. */
    if (status & 0x0F) {
        fprintf(stderr, "Error: Range status 0x%02X indicates error.\n", status);
        return -2;
    }

    /* Read the range value. */
    if (vl6180x_read_reg16(REG_RESULT_RANGE_VAL, &range) < 0) return -1;

    return (int)range;
}

static void log_data(int distance, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d mm, Status: %s\n", timestamp, distance, status);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL6180X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl6180x_init() < 0) {
        fprintf(stderr, "Error: VL6180X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL6180X proximity door opener started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = vl6180x_read_distance();

        if (distance < 0) {
            fprintf(stderr, "Error reading distance. Attempting re-initialization...\n");
            log_data(-1, "ERROR");
            vl6180x_init();
            gpioDelay(1000000);
            continue;
        }

        const char *status = (distance < DISTANCE_THRESHOLD) ? "DOOR_OPEN" : "DOOR_CLOSED";
        log_data(distance, status);
        printf("Distance: %d mm, Status: %s\n", distance, status);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

