#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_VAL 0x80
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_VAL) < 0) {
        fprintf(stderr, "Error writing control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_audio_sample(int handle, int16_t *sample) {
    int raw = i2cReadWordData(handle, DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading audio sample: %s\n", strerror(errno));
        return -1;
    }
    *sample = (int16_t)raw;
    return 0;
}

static int log_data(FILE *fp, const struct timespec *ts, int16_t s1, int16_t s2, int32_t tdoa) {
    if (fprintf(fp, "%ld,%ld,%d,%d,%d\n", ts->tv_sec, ts->tv_nsec, s1, s2, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) < 0 || init_sensor(i2c_handle2) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int16_t sample1 = 0, sample2 = 0;
        struct timespec ts;

        if (read_audio_sample(i2c_handle1, &sample1) < 0 ||
            read_audio_sample(i2c_handle2, &sample2) < 0) {
            fprintf(stderr, "Error reading audio samples, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            gpioDelay(SAMPLE_INTERVAL_US);
