#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses (8-bit, MSB=0 for read) */
#define REG_X_GYRO   0x04
#define REG_Y_GYRO   0x06
#define REG_Z_GYRO   0x08
#define REG_X_ACCEL  0x0A
#define REG_Y_ACCEL  0x0C
#define REG_Z_ACCEL  0x0E

/* SPI configuration: channel 0 (CE0 / GPIO8), 1 MHz, mode 3 (CPOL=1, CPHA=1) */
#define SPI_CHANNEL  0
#define SPI_SPEED    1000000
#define SPI_FLAGS    0b11000000000  /* CPOL=1 (bit 10), CPHA=1 (bit 9), aux SPI off (bit 8) */

/* Sensitivities (from datasheet) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

#define SAMPLE_PERIOD_US  100000  /* 100 ms */
#define STALL_US          40      /* microseconds between request and data read */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *csv_file = NULL;

typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data_t;

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit register from the ADIS16488A.
 * The ADIS16488A sends data on the rising edge of the clock, so a dummy
 * read (0x0000) is required after the address phase to get the data.
 * Returns 0 on success, -1 on SPI error.
 */
static int read_register(uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    int ret;

    /* Phase 1: send read request for the requested register */
    tx[0] = (char)(reg << 1);   /* MSB = 0 for read */
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write (request) failed for register 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Stall to let the ADIS16488A prepare the response */
    gpioDelay(STALL_US);

    /* Phase 2: dummy read to capture the register data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read (data) failed for register 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    *value = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_imu_data(imu_data_t *data) {
    int16_t raw;

    if (read_register(REG_X_GYRO, &raw) != 0) return -1;
    data->gyro_x = (float)raw * GYRO_SENSITIVITY;

    if (read_register(REG_Y_GYRO, &raw) != 0) return -1;
    data->gyro_y = (float)raw * GYRO_SENSITIVITY;

    if (read_register(REG_Z_GYRO, &raw) != 0) return -1;
    data->gyro_z = (float)raw * GYRO_SENSITIVITY;

    if (read_register(REG_X_ACCEL, &raw) != 0) return -1;
    data->accel_x = (float)raw * ACCEL_SENSITIVITY;

    if (read_register(REG_Y_ACCEL, &raw) != 0) return -1;
    data->accel_y = (float)raw * ACCEL_SENSITIVITY;

    if (read_register(REG_Z_ACCEL, &raw) != 0) return -1;
    data->accel_z = (float)raw * ACCEL_SENSITIVITY;

    return 0;
}

static void log_data(const imu_data_t *data) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    fprintf(csv_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp,
            data->gyro_x, data->gyro_y, data->gyro_z,
            data->accel_x, data->accel_y, data->accel_z);
    fflush(csv_file);
}

int main(void) {
    imu_data_t imu_data;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    csv_file = fopen("imu_data.csv", "w");
    if (csv_file == NULL) {
        perror("fopen imu_data.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(csv_file);

    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (read_imu_data(&imu_data) == 0) {
            log_data(&imu_data);
        } else {
            fprintf(stderr, "Failed to read IMU data; skipping sample\n");
        }

        /* Non-blocking delay: check running flag every 10 ms */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(10000);
        }
    }

    return EXIT_SUCCESS;
}

