/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * Reads gyroscope and accelerometer data over SPI using spidev and libgpiod
 * for the chip-select line (GPIO8).  Uses the ADIS16448 single-register
 * read protocol: send the 8-bit register address with bit 7 set (0x80)
 * in the first 16-bit cycle, then read the 16-bit data response in the
 * second cycle.
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM)
 *   ADIS16448 SCLK-> GPIO11 (BCM)
 *   ADIS16448 DOUT-> GPIO9  (BCM)
 *   ADIS16448 DIN -> GPIO10 (BCM)
 *   ADIS16448 VDD-> 3.3 V
 *   ADIS16448 GND-> GND
 *
 * Build:
 *   gcc -O2 -Wall -o adis16448 adis16448.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <gpiod.h>

/* ---- ADIS16448 register addresses ---- */
#define ADIS16448_XGYRO_OUT 0x04
#define ADIS16448_YGYRO_OUT 0x06
#define ADIS16448_ZGYRO_OUT 0x08
#define ADIS16448_XACCL_OUT 0x0A
#define ADIS16448_YACCL_OUT 0x0C
#define ADIS16448_ZACCL_OUT 0x0E

/* ---- SPI / GPIO configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_3

#define GPIO_CHIP_NAME  "gpiochip4"  /* BCM GPIO bank on Pi 4 */
#define CS_LINE_OFFSET  8           /* GPIO8 = chip-select */

/* ---- Scaling factors (from ADIS16448 datasheet) ---- */
#define GYRO_SCALE  0.02f   /* degrees/second per LSB */
#define ACCEL_SCALE 0.00025f /* g per LSB */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_cs_line = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/*
 * Perform a single-register read of the ADIS16448.
 *
 * Protocol (32-bit transfer, MSB first):
 *   tx[0] = 0x00 (dummy for clocking data out)
 *   tx[1] = 0x00 (dummy)
 *   tx[2] = 0x80 | (reg << 1)  (read command: bit7=1, bit6-0 = reg)
 *   tx[3] = 0x00 (dummy)
 *
 * Response (rx[2] and rx[3] hold the 16-bit data):
 *   rx[2] = [D15..D8]
 *   rx[3] = [D7..D0]
 */
static int adis_read_register(uint8_t reg, int16_t *out)
{
    uint8_t tx[4] = {0, 0, (uint8_t)(0x80 | (reg << 1)), 0};
    uint8_t rx[4] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 4,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[2] << 8) | rx[3]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                CS_LINE_OFFSET, strerror(errno));
        return -1;
    }

