#define Z_GYRO_OUT  0x08
#define X_ACCL_OUT  0x0A
#define Y_ACCL_OUT  0x0C
#define Z_ACCL_OUT  0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* Scaling factors */
#define GYRO_SCALE  0.05f    /* deg/sec per LSB */
#define ACCL_SCALE  0.00025f /* g per LSB */

/* Stall time for ADIS16448 two-cycle SPI read (microseconds) */
#define STALL_TIME_US 40

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit register from the ADIS16448.
 * The ADIS16448 requires a two-cycle SPI read:
 *   1. Send read command (reg | 0x8000) in first 16-bit transfer.
 *   2. Wait at least 40 us for data to be ready.
 *   3. Send dummy 0x0000 in second 16-bit transfer to clock out the data.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_register(uint8_t reg, int16_t *value) {
    char tx_cmd[2] = { (char)((reg | 0x80) << 8), 0x00 };
    char rx_cmd[2] = { 0 };
    char tx_dummy[2] = { 0x00, 0x00 };
    char rx_dummy[2] = { 0 };

    /* First transfer: send read command, receive dummy */
    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for command 0x%02X\n", reg);
        return -1;
    }

    /* Stall time per datasheet */
    gpioDelay(STALL_TIME_US);

    /* Second transfer: send dummy, receive data */
    if (spiXfer(spi_handle, tx_dummy, rx_dummy, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for data 0x%02X\n", reg);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(rx_dummy[0] & 0xFF) << 8) |
                       (uint16_t)(rx_dummy[1] & 0xFF));
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU Reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accl_x, accl_y, accl_z;

        if (read_register(X_GYRO_OUT, &gyro_x) != 0 ||
            read_register(Y_GYRO_OUT, &gyro_y) != 0 ||
            read_register(Z_GYRO_OUT, &gyro_z) != 0 ||
            read_register(X_ACCL_OUT, &accl_x) != 0 ||
            read_register(Y_ACCL_OUT, &accl_y) != 0 ||
            read_register(Z_ACCL_OUT, &accl_z) != 0) {
            fprintf(stderr, "Error reading IMU data. Retrying...\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        float gyro_x_dps = (float)gyro_x * GYRO_SCALE;
        float gyro_y_dps = (float)gyro_y * GYRO_SCALE;
        float gyro_z_dps = (float)gyro_z * GYRO_SCALE;
        float accl_x_g  = (float)accl_x * ACCL_SCALE;
        float accl_y_g  = (float)accl_y * ACCL_SCALE;
        float accl_z_g  = (float)accl_z * ACCL_SCALE;

        printf("Gyro: X=%7.2f deg/s, Y=%7.2f deg/s, Z=%7.2f deg/s | "
               "Accel: X=%7.4f g, Y=%7.4f g, Z=%7.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps,
               accl_x_g, accl_y_g, accl_z_g);

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

