#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* Impact threshold in g (full-resolution mode, +-2g range) */
#define IMPACT_THRESHOLD 2.5f

/* Scale factor: 256 LSB/g for full-resolution mode, +-2g range */
#define SCALE_FACTOR 256.0f

/* GPIO pin for the red LED */
#define LED_PIN 17

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* LED on-time in microseconds (500 ms) */
#define LED_ON_TIME_US 500000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADXL345 register                          */
/* ------------------------------------------------------------------ */
static int adxl345_write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (value 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADXL345 register                         */
/* ------------------------------------------------------------------ */
static int adxl345_read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z)                         */
/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int handle,
                                      int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];

    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6);
    if (rc < 0) {
        fprintf(stderr, "Error reading acceleration data: %s\n",
                pigpio_error(rc));
        return -1;
    }
    if (rc != 6) {
        fprintf(stderr, "Short read: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    /* ADXL345 outputs little-endian: DATAX0 = LSB, DATAX1 = MSB */
    *x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Calculate total acceleration magnitude in g                         */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    float fx = (float)x / SCALE_FACTOR;
    float fy = (float)y / SCALE_FACTOR;
    float fz = (float)z / SCALE_FACTOR;
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

/* ------------------------------------------------------------------ */
/* Log an impact event to file                                         */
/* ------------------------------------------------------------------ */
static void log_impact(float magnitude, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file,
            "%s - Impact: magnitude=%.2fg, X=%d, Y=%d, Z=%d\n",
            timestamp, magnitude, x, y, z);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put ADXL345 into standby mode before closing */
        (void)i2cWriteByteData(g_i2c_handle, ADXL345_POWER_CTL, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Ensure LED is off */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address 0x53 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, ADXL345_ADDRESS, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device ID */
    uint8_t devid = 0;
    if (adxl345_read_register(g_i2c_handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read ADXL345 device ID - sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr,
                "Device ID mismatch: expected 0x%02X, got 0x%02X\n",
                ADXL345_DEVID_VALUE, devid);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure ADXL345: full resolution, +-2g range, right-justified */
    if (adxl345_write_register(g_i2c_handle, ADXL345_DATA_FORMAT, 0x08) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable measurement mode (clear standby bit) */
    if (adxl345_write_register(g_i2c_handle, ADXL345_POWER_CTL, 0x08) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open log file in append mode */
    g_log_file = fopen("impact_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening impact_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int16_t x, y, z;

        if (adxl345_read_acceleration(g_i2c_handle, &x, &y, &z) != 0) {
            /* Bus error: wait briefly and retry */
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > IMPACT_THRESHOLD) {
            printf("Impact detected! Magnitude: %.2fg\n", magnitude);

            /* Activate LED for 500 ms */
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_PIN, 0);

            /* Log the impact event */
            log_impact(magnitude, x, y, z);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

