    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int16_t x, y, z;

        if (adxl345_read_acceleration(g_i2c_handle, &x, &y, &z) != 0) {
