        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mma8451_init(int fd) {
    uint8_t who;
    if (i2c_read(fd, WHO_AM_I, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write(fd, CTRL_REG1, 0x01) < 0) return -1;
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_MSB, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ry = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t rz = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)rx / SCALE_FACTOR;
    *y = (float)ry / SCALE_FACTOR;
    *z = (float)rz / SCALE_FACTOR;
    return 0;
}

static bool detect_impact(float x, float y, float z) {
    return (fabsf(x) > THRESHOLD_G || fabsf(y) > THRESHOLD_G || fabsf(z) > THRESHOLD_G);
}

static void log_impact(FILE *fp) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Impact detected\n", ts);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, MMA8451_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MMA8451_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mma8451_init(fd) < 0) {
        fprintf(stderr, "MMA8451 initialization failed\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "mma8451_led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    FILE *log_fp = fopen("impact_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open impact_log.txt: %s\n", strerror(errno));
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    printf("MMA8451 impact monitor running. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_accel(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            usleep(POLL_MS * 1000);
            continue;
        }
        if (detect_impact(x, y, z)) {
            printf("Impact detected!\n");
            gpiod_line_set_value(led, 1);
            log_impact(log_fp);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led, 0);
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(fd);
    return 0;
}

