#include <linux/i2c-dev.h>

#define TMAG5273_ADDR 0x35
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "magnetic_field_log.csv"

#define REG_X_RESULT 0x10
#define REG_Y_RESULT 0x11
#define REG_Z_RESULT 0x12

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes, %s\n", reg, n, strerror(errno));
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", TMAG5273_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    long fsize = ftell(log_fp);
    if (fsize == 0) {
        if (fprintf(log_fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(log_fp);
            log_fp = NULL;
            close(i2c_fd);
            i2c_fd = -1;
            return 1;
        }
        fflush(log_fp);
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;
        int err = 0;

        if (i2c_read_reg16(i2c_fd, REG_X_RESULT, &x) != 0) err = 1;
        if (i2c_read_reg16(i2c_fd, REG_Y_RESULT, &y) != 0) err = 1;
        if (i2c_read_reg16(i2c_fd, REG_Z_RESULT, &z) != 0) err = 1;

        if (err) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            if (log_data(log_fp, x, y, z) != 0) {
                fprintf(stderr, "Log write error; continuing.\n");
            }
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    return 0;
}

