code:
/*
 * freefall_detect.c — Raspberry Pi 4 Model B
 *
 * Reads an ADXL345 accelerometer on /dev/i2c-1 at address 0x53,
 * monitors falling-edge events on GPIO17 (INT1), and logs
 * timestamped X/Y/Z acceleration data to freefall_log.csv
 * only during freefall events.
 *
 * Build:  gcc -O2 -Wall -Wextra -o freefall_detect freefall_detect.c \
 *               -lgpiod -lm
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   ADXL345 INT1 -> GPIO17 (pin 11)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <poll.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_DEVID          0x00
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_INT_ENABLE     0x2E
#define ADXL345_INT_MAP        0x2F
#define ADXL345_INT_SOURCE     0x30
#define ADXL345_DATAX0         0x32
#define ADXL345_THRESH_FF      0x0A
#define ADXL345_TIME_FF        0x20

#define ADXL345_DEVID_EXPECTED 0xE5

/* ---- GPIO / interrupt ---- */
#define GPIO_CHIP_NAME         "gpiochip4"   /* BCM GPIO bank on Pi 4 */
#define GPIO_INT_LINE          17            /* BCM 17, physical pin 11 */
#define INTERRUPT_EDGE         "falling"

/* ---- Logging ---- */
#define LOG_FILE_NAME          "freefall_log.csv"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int                   g_i2c_fd  = -1;
static struct gpiod_chip    *g_chip    = NULL;
static struct gpiod_line    *g_line    = NULL;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 setup                                                       */
/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby: clear measure bit, then set to standby */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* Freefall: THRESH_FF ~300 mg, TIME_FF ~100 ms */
    if (i2c_write_reg8(fd, ADXL345_THRESH_FF, 0x07) < 0)
        return -1;
    if (i2c_write_reg8(fd, ADXL345_TIME_FF, 0x0A) < 0)
        return -1;

    /* Clear any pending interrupts */
    uint8_t dummy = 0;
    if (i2c_read_reg8(fd, ADXL345_INT_SOURCE, &dummy) < 0)
        return -1;

    /* Map freefall interrupt to INT1 (bit 0 = 0) */
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) < 0)
        return -1;

    /* Enable freefall interrupt (bit 2) */
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, 0x04) < 0)
        return -1;

    /* Enter measurement mode */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

static void adxl345_disable_interrupts(int fd)
{
    (void)i2c_write_reg8(fd, ADXL345_INT_ENABLE, 0x00);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    long pos = ftell(g_log_fp);
    if (pos == 0)
        fprintf(g_log_fp, "timestamp,x,y,z\n");
    return 0;
}

static void log_data(int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s.%03ld,%d,%d,%d\n",
            tbuf, ts.tv_nsec / 1000000L, x, y, z);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        adxl345_disable_interrupts(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request falling-edge event on GPIO17 */
