    }
    g_line = gpiod_chip_get_line(g_chip, GPIO_INT_LINE);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_INT_LINE, strerror(errno));
        cleanup();
