    }
    if (gpiod_line_request_falling_edge_events(g_line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Cannot request falling-edge events on GPIO%d: %s\n",
                GPIO_INT_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (log_open() < 0) {
