#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_A 0x28
#define OUTX_H_A 0x29
#define OUTY_L_A 0x2A
#define OUTY_H_A 0x2B
#define OUTZ_L_A 0x2C
#define OUTZ_H_A 0x2D

#define ACCEL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define WINDOW_SEC 1.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int read_regs(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int init_lsm6dsr(void) {
    uint8_t who_am_i = 0;
    if (read_regs(WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X). Sensor absent?\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (write_reg(CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL1_XL.\n");
        return -1;
    }
    if (write_reg(CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL2_G.\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[12];
    if (read_regs(OUTX_L_G, buf, 12) < 0) return -1;
    data->gyro_x = (float)((int16_t)((buf[1] << 8) | buf[0])) / 16.0f;
    data->gyro_y = (float)((int16_t)((buf[3] << 8) | buf[2])) / 16.0f;
    data->gyro_z = (float)((int16_t)((buf[5] << 8) | buf[4])) / 16.0f;
    data->accel_x = (float)((int16_t)((buf[7] << 8) | buf[6])) / 1000.0f;
    data->accel_y = (float)((int16_t)((buf[9] << 8) | buf[8])) / 1000.0f;
    data->accel_z = (float)((int16_t)((buf[11] << 8) | buf[10])) / 1000.0f;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static int detect_fall(const sensor_data_t *data, int *state, double *start_time) {
    double now = time_time();
    float mag = sqrtf(data->accel_x * data->accel_x +
                      data->accel_y * data->accel_y +
                      data->accel_z * data->accel_z);
    switch (*state) {
        case 0:
            if (mag < ACCEL_THRESHOLD) {
                *start_time = now;
                *state = 1;
            }
            break;
        case 1:
            if ((now - *start_time) > WINDOW_SEC) {
                if (mag > IMPACT_THRESHOLD) {
                    *state = 2;
                    return 1;
                } else {
                    *state = 0;
                }
            } else if (mag > ACCEL_THRESHOLD) {
                *state = 0;
            }
            break;
        case 2:
            if (mag > ACCEL_THRESHOLD) {
                *state = 0;
            }
            break;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "Error: LSM6DSR initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    int state = 0;
    double start_time = 0.0;
    sensor_data_t data;
    while (!terminate) {
        if (read_sensor_data(&data) == 0) {
            log_data(&data);
            if (detect_fall(&data, &state, &start_time)) {
                printf("Fall detected!\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed, retrying...\n");
        }
        time_sleep(0.01);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

