/*
 * ADIS16266 Gyroscope SPI Reader for Raspberry Pi 3 Model B+
 * Library: pigpio (SPI channel 0, CE0/GPIO8, 1 MHz, mode 3)
 *
 * Reads X_GYRO_OUT (0x14) every 10 ms, scales to deg/sec,
 * and logs to gyro_log.csv.
 *
 * Build: gcc -Wall -Wextra -O2 -o gyro_log gyro_log.c -lpigpio -lrt
 * Run:   sudo ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16266 register map (16-bit addresses, 16-bit data) ---- */
#define ADIS16266_X_GYRO_OUT   0x04
#define ADIS16266_WHO_AM_I     0x02
#define ADIS16266_WHO_AM_I_VAL 0x3F5A  /* expected default ID */

/* ---- SPI configuration ---- */
#define SPI_CHANNEL 0          /* CE0 / GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0x0003     /* mode 3: CPOL=1, CPHA=1 */

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 10000  /* 10 ms */

/* ---- Globals for cleanup ---- */
static int  spi_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266.                          */
/* Returns 0 on success, -1 on SPI error.                              */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, uint16_t *value)
{
    char tx[2], rx[2];
    int  ret;

    /* Phase 1: send read command (register address | 0x80) */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read command transfer failed (reg 0x%02X, ret=%d)\n",
                reg, ret);
        return -1;
    }

    /* Small delay so the device has time to latch the address */
    gpioDelay(20);  /* 20 us */

    /* Phase 2: dummy transaction to clock out the data */
    tx[0] = 0x00;
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data read transfer failed (reg 0x%02X, ret=%d)\n",
                reg, ret);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register to the ADIS16266.                           */
/* Returns 0 on success, -1 on SPI error.                              */
/* ------------------------------------------------------------------ */
static int write_register(uint8_t reg, uint16_t value)
{
    char tx[2], rx[2];
    int  ret;

    tx[0] = (char)(reg & 0x7F);   /* bit 7 = 0 for write */
    tx[1] = (char)(value >> 8);

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write transfer failed (reg 0x%02X, ret=%d)\n",
                reg, ret);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t who_am_i = 0;
    uint16_t raw;
    double   rate_deg_sec;
    struct timespec ts;
    struct tm tm_info;
    char     timestamp[32];

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open SPI ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, flags 0x%02X): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify device identity ---- */
    if (read_register(ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, ADIS16266_WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);

    /* ---- Open log file once ---- */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("fopen(gyro_log.csv)");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,X_GYRO_OUT_deg_sec\n");
    fflush(log_file);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main sampling loop ---- */
    while (!terminate) {
        if (read_register(ADIS16266_X_GYRO_OUT, &raw) != 0) {
            fprintf(stderr, "SPI read error — continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Scale: 0.0305 deg/sec per LSB (per datasheet) */
        rate_deg_sec = (double)raw * 0.0305;

        /* Timestamp */
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            continue;
        }
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        snprintf(timestamp + strlen(timestamp),
                 sizeof(timestamp) - strlen(timestamp),
                 ".%03ld", ts.tv_nsec / 1000000);

        /* CSV row */
        if (fprintf(log_file, "%s,%.4f\n", timestamp, rate_deg_sec) < 0) {
            perror("fprintf");
        } else {
            fflush(log_file);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

