#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28

/* Expected chip ID */
#define WHO_AM_I_VAL 0xD3

/* CTRL_REG1: normal mode, XYZ axes enabled */
#define CTRL_REG1_VAL 0x0F

/* CTRL_REG4: full-scale +/-250 dps */
#define CTRL_REG4_VAL 0x00

/* Sensitivity for +/-250 dps: 8.75 mdps/LSB = 0.00875 dps/LSB */
#define SENSITIVITY 0.00875f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Retry parameters for initialization */
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 1000

/* Global resources for signal-safe cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a register, retrying on failure */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result, retries = I2C_RETRIES;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C write to reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, I2C_RETRIES - retries + 1, I2C_RETRIES, result);
        retries--;
        if (retries > 0) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Error: Failed to write register 0x%02X after %d retries.\n", reg, I2C_RETRIES);
    return -1;
}

/* Read a byte from a register, retrying on failure */
static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result, retries = I2C_RETRIES;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "Warning: I2C read from reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, I2C_RETRIES - retries + 1, I2C_RETRIES, result);
        retries--;
        if (retries > 0) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Error: Failed to read register 0x%02X after %d retries.\n", reg, I2C_RETRIES);
    return -1;
}

/* Initialize the L3G4200D gyroscope */
static int initialize_gyro(int handle) {
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (read_register(handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Configure CTRL_REG1: normal mode, all axes enabled */
    if (write_register(handle, CTRL_REG1, CTRL_REG1_VAL) != 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG1.\n");
        return -1;
    }

    /* Configure CTRL_REG4: +/-250 dps full-scale */
    if (write_register(handle, CTRL_REG4, CTRL_REG4_VAL) != 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* Read all 6 data bytes in one block read */
static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int result, retries = I2C_RETRIES;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
        if (result == 6) {
            /* L3G4200D outputs little-endian: low byte first, high byte second */
            int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
            int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
            int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

            *x = (float)raw_x * SENSITIVITY;
            *y = (float)raw_y * SENSITIVITY;
            *z = (float)raw_z * SENSITIVITY;
            return 0;
        }
        fprintf(stderr, "Warning: I2C block read failed (attempt %d/%d): %d\n",
                I2C_RETRIES - retries + 1, I2C_RETRIES, result);
        retries--;
        if (retries > 0) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Error: Failed to read gyro data after %d retries.\n", I2C_RETRIES);
    return -1;
}

/* Log a sample with nanosecond timestamp */
static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%.4f,%.4f,%.4f\n",
            (long)ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(fp);
}

int main(void) {
    float x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, GYRO_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (initialize_gyro(i2c_handle) != 0) {
        fprintf(stderr, "Error: Gyroscope initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open gyro_log.csv for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Warning: Skipping sample due to read error.\n");
        }
