#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* SIGINT handler — async-signal-safe: just flip the flag */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Return a static buffer with the current local time as YYYY-MM-DD HH:MM:SS */
static const char *get_timestamp(void) {
    static char buf[20];
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, sizeof(buf), "1970-01-01 00:00:00");
        return buf;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, sizeof(buf), "1970-01-01 00:00:00");
        return buf;
    }
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    return buf;
}

/*
 * Read the KY-026 digital output.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value == PI_BAD_GPIO) {
        return -1;
    }
    return value;
}

/*
 * Append a timestamped event line to the log file and flush.
 * Returns 0 on success, -1 on error.
 */
static int log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s - %s\n", get_timestamp(), message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as input with internal pull-up */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: could not open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);

    while (program_running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == -1) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", FLAME_SENSOR_GPIO);
            if (log_event("Error: failed to read flame sensor") != 0) {
                fprintf(stderr, "Error: failed to log sensor read error.\n");
            }
        } else {
            const char *status = (sensor_value == 0) ? "YES" : "NO";
            if (log_event(status) != 0) {
                fprintf(stderr, "Error: failed to log flame event.\n");
            }
            if (sensor_value == 0) {
                printf("FLAME DETECTED!\n");
            }
        }

        /* Sleep 500 ms; gpioDelay is microseconds */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

