#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x53
#define ACCEL_REG_XLSB 0x28
#define ACCEL_REG_XMSB 0x29
#define ACCEL_REG_YLSB 0x2A
#define ACCEL_REG_YMSB 0x2B
#define ACCEL_REG_ZLSB 0x2C
#define ACCEL_REG_ZMSB 0x2D
#define SAMPLE_MS      100
#define LOG_FILE       "vibration_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg8(fd, ACCEL_REG_XLSB, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_XMSB, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_YLSB, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_YMSB, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_ZLSB, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_ZMSB, &zh) < 0) return -1;

    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static void log_data(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z)
{
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    fseek(g_log, 0, SEEK_END);
    if (ftell(g_log) == 0)
        fprintf(g_log, "Timestamp,X,Y,Z\n");

    printf("Structural Integrity Monitoring System started.\n");
    printf("I2C bus: %s, address: 0x%02X, log: %s\n", I2C_BUS, I2C_ADDR, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x, y, z;
        char ts[32];

        if (read_acceleration(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        get_timestamp(ts, sizeof(ts));
        log_data(g_log, ts, x, y, z);
        printf("%s  X=%6d  Y=%6d  Z=%6d\n", ts, x, y, z);

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

