#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MMA8452Q register addresses */
#define MMA8452Q_REG_STATUS      0x00
#define MMA8452Q_REG_OUT_X_MSB   0x01
#define MMA8452Q_REG_OUT_X_LSB   0x02
#define MMA8452Q_REG_OUT_Y_MSB   0x03
#define MMA8452Q_REG_OUT_Y_LSB   0x04
#define MMA8452Q_REG_OUT_Z_MSB   0x05
#define MMA8452Q_REG_OUT_Z_LSB   0x06
#define MMA8452Q_REG_WHO_AM_I    0x0D
#define MMA8452Q_REG_CTRL_REG1   0x2A

#define MMA8452Q_WHO_AM_I_VAL    0x2A
#define I2C_BUS                 "/dev/i2c-1"
#define I2C_ADDR                0x1D
#define LOG_FILE                "fall_log.txt"
#define TILT_THRESHOLD_DEG      45.0
#define LOOP_DELAY_MS           10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg(fd, MMA8452Q_REG_WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MMA8452Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode, 100 Hz data rate, no FIFO */
    if (i2c_write_reg(fd, MMA8452Q_REG_CTRL_REG1, 0x00) != 0)
        return -1;
    usleep(1000);

    /* Active mode, 100 Hz data rate */
    if (i2c_write_reg(fd, MMA8452Q_REG_CTRL_REG1, 0x01) != 0)
        return -1;
    usleep(1000);

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, MMA8452Q_REG_OUT_X_MSB, buf, 6) != 0)
        return -1;

    /* 12-bit left-justified: shift right by 4 to get signed 12-bit value */
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z)
{
    double mag_yz = sqrt((double)y * y + (double)z * z);
    if (mag_yz < 1e-6)
        return 0.0;
    return atan2((double)x, mag_yz) * 180.0 / M_PI;
}

static void log_fall_event(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%d, Y=%d, Z=%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mma8452q(g_i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MMA8452Q ready. Monitoring tilt (threshold %.1f deg)...\n",
           TILT_THRESHOLD_DEG);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        double angle = calculate_tilt_angle(x, y, z);
        if (fabs(angle) > TILT_THRESHOLD_DEG) {
            log_fall_event(g_log_fp, x, y, z);
            printf("Fall detected! Tilt angle: %.2f deg\n", angle);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

