/*
 * LIS3MDL Triple-Axis Magnetometer logger for Raspberry Pi 3 Model B+
 * Uses Linux i2c-dev ioctl interface (no wiringPi dependency).
 *
 * Wiring:
 *   LIS3MDL SDA -> GPIO2 (pin 3, I2C1 SDA)
 *   LIS3MDL SCL -> GPIO3 (pin 5, I2C1 SCL)
 *   LIS3MDL VDD -> 3.3 V
 *   LIS3MDL GND -> GND
 *
 * Build: gcc -O2 -Wall -o mag_logger mag_logger.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3MDL constants ---- */
#define LIS3MDL_ADDR        0x1E
#define LIS3MDL_WHO_AM_I    0x0F
#define LIS3MDL_WHO_AM_I_VAL 0x3D
#define LIS3MDL_CTRL_REG1   0x20
#define LIS3MDL_CTRL_REG2   0x21
#define LIS3MDL_CTRL_REG3   0x22
#define LIS3MDL_CTRL_REG4   0x23
#define LIS3MDL_OUT_X_L     0x28
#define LIS3MDL_OUT_X_H     0x29
#define LIS3MDL_OUT_Y_L     0x2A
#define LIS3MDL_OUT_Y_H     0x2B
#define LIS3MDL_OUT_Z_L     0x2C
#define LIS3MDL_OUT_Z_H     0x2D

/* ---- Calibration (example values; calibrate for your specific sensor) ---- */
#define X_OFFSET 0.0f
#define Y_OFFSET 0.0f
#define Z_OFFSET 0.0f
#define X_SCALE  1.0f
#define Y_SCALE  1.0f
#define Z_SCALE  1.0f

/* ---- Threshold (milliGauss) ---- */
#define THRESHOLD_MG 800.0f

/* ---- Sensitivity: +-4 gauss -> 0.146 mG/LSB ---- */
#define SENSITIVITY_MG_LSB 0.146f

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers using Linux i2c-dev ioctl ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst read(0x%02X, %zu) failed: got %zd (%s)\n",
                reg, len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */
static int init_lis3mdl(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, LIS3MDL_WHO_AM_I, &who) < 0)
        return -1;
    if (who != LIS3MDL_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3MDL_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: temp sensor enabled, ODR=80 Hz, continuous mode */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG1, 0x70) < 0)
        return -1;

    /* CTRL_REG2: reset to default */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG2, 0x00) < 0)
        return -1;

    /* CTRL_REG3: continuous-conversion mode, no interrupts */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG3, 0x00) < 0)
        return -1;

    /* CTRL_REG4: Z-axis high-performance mode, ultra-high performance */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG4, 0x0C) < 0)
        return -1;

    return 0;
}

/* ---- Read and convert magnetic data ---- */
static int read_magnetometer(int fd, float *x_mg, float *y_mg, float *z_mg)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, LIS3MDL_OUT_X_L, raw, sizeof(raw)) < 0)
        return -1;

    int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

    *x_mg = ((float)x - X_OFFSET) * X_SCALE * SENSITIVITY_MG_LSB;
    *y_mg = ((float)y - Y_OFFSET) * Y_SCALE * SENSITIVITY_MG_LSB;
    *z_mg = ((float)z - Z_OFFSET) * Z_SCALE * SENSITIVITY_MG_LSB;
    return 0;
}

/* ---- Logging ---- */
static int log_data(FILE *fp, float x, float y, float z)
{
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Threshold alert ---- */
static void check_threshold(float x, float y, float z)
{
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > THRESHOLD_MG)
        fprintf(stderr, "*** METAL DETECTED: |B|=%.2f mG ***\n", mag);
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    int init_ok = 0;
    for (int attempt = 0; attempt < 3 && g_running; attempt++) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Sensor init attempt %d/3 failed; retrying in 1 s...\n",
                attempt + 1);
        sleep(1);
    }
    if (!init_ok) {
        fprintf(stderr, "Sensor init failed after 3 attempts.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen magnetic_log.txt failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    struct timespec sleep_ts = { .tv_sec = 0, .tv_nsec = 100 * 1000 * 1000 }; /* 10 Hz */

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error; re-initializing sensor...\n");
            if (init_lis3mdl(g_i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed; exiting.\n");
                break;
            }
            continue;
        }

        if (log_data(g_log_fp, x, y, z) < 0) {
            fprintf(stderr, "Logging failed; exiting.\n");
            break;
        }

        check_threshold(x, y, z);
        nanosleep(&sleep_ts, NULL);
    }

    /* Cleanup */
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

