#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_DEVID_AD   0x00
#define ADXL354B_REG_PARTID     0x01
#define ADXL354B_REG_XDATA_L    0x08
#define ADXL354B_REG_YDATA_L    0x0B
#define ADXL354B_REG_ZDATA_L    0x0E
#define ADXL354B_REG_STATUS     0x04
#define ADXL354B_REG_POWER_CTL  0x2D
#define ADXL354B_REG_RESET      0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    0

// ADXL354B Sensitivity for +-2g range
#define ADXL354B_SENSITIVITY 0.0000039f // 3.9 microg/LSB = 0.0000039 g/LSB

// Global Variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, uint8_t len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int read_acceleration_data(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);
int initialize_adxl354b(int handle);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, uint8_t len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    tx_buf[0] = reg | 0x80; // Set read bit (bit 7)
    memset(tx_buf + 1, 0, len);

    int result = spiXfer(handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "SPI read error: expected %d bytes, got %d\n", len + 1, result);
        return -1;
    }
    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = reg & 0x7F; // Clear read bit (bit 7)
    tx_buf[1] = data;

    int result = spiWrite(handle, tx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: expected 2 bytes, got %d\n", result);
        return -1;
    }
    return 0;
}

// Read Acceleration Data Function
int read_acceleration_data(int handle, float *x, float *y, float *z) {
    uint8_t x_data[3];
    uint8_t y_data[3];
    uint8_t z_data[3];

    if (spi_read_register(handle, ADXL354B_REG_XDATA_L, x_data, 3) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_YDATA_L, y_data, 3) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_ZDATA_L, z_data, 3) != 0) return -1;

    // Combine the 3 bytes into a 20-bit signed value
    int32_t x_raw = ((int32_t)x_data[0] << 12) | ((int32_t)x_data[1] << 4) | ((int32_t)x_data[2] >> 4);
    int32_t y_raw = ((int32_t)y_data[0] << 12) | ((int32_t)y_data[1] << 4) | ((int32_t)y_data[2] >> 4);
    int32_t z_raw = ((int32_t)z_data[0] << 12) | ((int32_t)z_data[1] << 4) | ((int32_t)z_data[2] >> 4);

    // Sign extend the 20-bit value to 32-bit
    if (x_raw & 0x80000) x_raw |= 0xFFF00000;
    if (y_raw & 0x80000) y_raw |= 0xFFF00000;
    if (z_raw & 0x80000) z_raw |= 0xFFF00000;

    *x = (float)x_raw * ADXL354B_SENSITIVITY;
    *y = (float)y_raw * ADXL354B_SENSITIVITY;
    *z = (float)z_raw * ADXL354B_SENSITIVITY;

    return 0;
}

// Log Data Function
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.6f g, Y: %.6f g, Z: %.6f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp);
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize ADXL354B Function
int initialize_adxl354b(int handle) {
    uint8_t partid;
    int retries = 3;

    // Check Part ID
    while (retries > 0) {
        if (spi_read_register(handle, ADXL354B_REG_PARTID, &partid, 1) == 0) {
            if (partid == 0x1D) {
                printf("ADXL354B detected (PARTID=0x%02X)\n", partid);
                break;
            } else {
                fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x1D)\n", partid);
                return -1;
            }
        } else {
            fprintf(stderr, "Failed to read PARTID, retrying...\n");
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read PARTID after retries\n");
        return -1;
    }

    // Reset the device
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1ms for reset to complete

    // Clear RUN bit to enter standby mode
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to set standby mode\n");
        return -1;
    }

    // Wait for STABLE bit to clear (indicates sensor is ready)
    uint8_t status;
    retries = 100;
    do {
        if (spi_read_register(handle, ADXL354B_REG_STATUS, &status, 1) != 0) {
            fprintf(stderr, "Failed to read STATUS\n");
            return -1;
        }
        if (status & 0x01) { // STABLE bit
            break;
        }
        gpioDelay(1000); // 1ms
    } while (--retries > 0);

    if (retries == 0) {
        fprintf(stderr, "Sensor not stable after initialization\n");
        return -1;
    }

    // Set RUN bit to start measurement
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x01) != 0) {
        fprintf(stderr, "Failed to start measurement\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (initialize_adxl354b(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    int consecutive_errors = 0;

    // Main loop
    while (!terminate) {
        if (read_acceleration_data(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading acceleration data (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, attempting re-initialization\n");
                if (initialize_adxl354b(spi_handle) != 0) {
                    fprintf(stderr, "Re-initialization failed, exiting\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();

    return 0;
}

