#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses */
#define X_GYRO_REG   0x04
#define Y_GYRO_REG   0x06
#define Z_GYRO_REG   0x08
#define X_ACCL_REG   0x0A
#define Y_ACCL_REG   0x0C
#define Z_ACCL_REG   0x0E

/* SPI Configuration */
#define SPI_CHANNEL  0
#define SPI_BAUD     1000000  /* 1 MHz */
#define SPI_FLAGS    0x00000003  /* Mode 3: active-high CE, MSB first */

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE   0.05f   /* deg/sec per LSB */
#define ACCL_SCALE   0.0025f /* g per LSB */

/* Sampling interval (microseconds) */
#define SAMPLE_US    10000   /* 10 ms -> ~100 Hz */

/* Global resources for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16362.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(int handle, uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    int ret;

    /* Phase 1: send read command (MSB set = read) */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;
    ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read command failed (reg 0x%02X, ret=%d)\n", reg, ret);
        return -1;
    }

    /* Small delay to allow conversion (datasheet: ~100 us) */
    gpioDelay(100);

    /* Phase 2: dummy address + read data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data read failed (reg 0x%02X, ret=%d)\n", reg, ret);
        return -1;
    }

    *value = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* Log a timestamped IMU reading to the CSV file */
static void log_data(FILE *fp, float gx, float gy, float gz,
                     float ax, float ay, float az) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    fprintf(fp, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, gx, gy, gz, ax, ay, az);
    fflush(fp);
}

int main(void) {
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;
    float gx, gy, gz, ax, ay, az;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    /* Main sampling loop */
    while (!terminate) {
        if (read_register(spi_handle, X_GYRO_REG, &raw_gx) != 0 ||
            read_register(spi_handle, Y_GYRO_REG, &raw_gy) != 0 ||
            read_register(spi_handle, Z_GYRO_REG, &raw_gz) != 0 ||
            read_register(spi_handle, X_ACCL_REG, &raw_ax) != 0 ||
            read_register(spi_handle, Y_ACCL_REG, &raw_ay) != 0 ||
            read_register(spi_handle, Z_ACCL_REG, &raw_az) != 0) {
            fprintf(stderr, "SPI read error, skipping sample\n");
        } else {
            gx = (float)raw_gx * GYRO_SCALE;
            gy = (float)raw_gy * GYRO_SCALE;
            gz = (float)raw_gz * GYRO_SCALE;
            ax = (float)raw_ax * ACCL_SCALE;
            ay = (float)raw_ay * ACCL_SCALE;
            az = (float)raw_az * ACCL_SCALE;
            log_data(log_file, gx, gy, gz, ax, ay, az);
        }
        gpioDelay(SAMPLE_US);
    }

    /* Cleanup */
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

