/*
 * KY-032 IR Obstacle Avoidance Sensor - Dual Collision Avoidance System
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod v2 (modern GPIO API)
 *
 * Wiring:
 *   KY-032 #1 OUT -> GPIO17 (BCM 17, physical pin 11)
 *   KY-032 #2 OUT -> GPIO27 (BCM 27, physical pin 13)
 *   KY-032 VCC    -> 3.3 V (physical pin 1)
 *   KY-032 GND    -> GND   (physical pin 9)
 *
 * The KY-032 output is active-low: 0 = obstacle detected, 1 = clear.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o ky032_avoid ky032_avoid.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_PIN_1      17
#define GPIO_PIN_2      27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_values values;
    unsigned int offsets[2];
    int ret;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    offsets[0] = GPIO_PIN_1;
    offsets[1] = GPIO_PIN_2;

    ret = gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request the lines --- */
    request = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (!request) {
        fprintf(stderr, "Failed to request GPIO lines %u and %u: %s\n",
                GPIO_PIN_1, GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    /* --- Bulk-read helper: request both lines together --- */
    gpiod_line_bulk_init(&lines);
    gpiod_line_bulk_add(&lines, gpiod_line_request_get_line(request, 0));
    gpiod_line_bulk_add(&lines, gpiod_line_request_get_line(request, 1));

    printf("KY-032 Dual Obstacle Avoidance System started.\n");
    printf("  Sensor 1: GPIO%u\n  Sensor 2: GPIO%u\n", GPIO_PIN_1, GPIO_PIN_2);
    printf("  Press Ctrl+C to exit.\n\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        ret = gpiod_line_request_get_values(&lines, &values);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_get_values failed: %s\n", strerror(errno));
            break;
        }

        int val1 = gpiod_line_values_get_value(&values, 0);
        int val2 = gpiod_line_values_get_value(&values, 1);

        print_timestamp();
        printf("Sensor 1: %s | Sensor 2: %s\n",
               val1 == 0 ? "OBSTACLE" : "clear",
               val2 == 0 ? "OBSTACLE" : "clear");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

cleanup:
    if (request)
        gpiod_line_request_release(request);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (chip)
        gpiod_chip_close(chip);

    return g_running ? EXIT_FAILURE : EXIT_SUCCESS;
}

