#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS 8

#define SCALE_FACTOR 0.02f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int adis16266_read_register(int fd, struct gpiod_line *cs_line, uint8_t address, int16_t *value) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    tx_buf[0] = address | 0x80;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to set CS low");
        return -1;
    }

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to set CS high");
        return -1;
    }

    *value = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
