/*
 * LSM6DSR accelerometer/gyroscope reader for Raspberry Pi 3 Model B+
 * Uses pigpio (modern API, no wiringPi).
 *
 * Wiring:
 *   LSM6DSR SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   LSM6DSR SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   LSM6DSR VDD  -> 3.3 V
 *   LSM6DSR GND  -> GND
 *   LSM6DSR SA0  -> GND  (7-bit I2C address 0x6B)
 *
 * Build:  gcc -O2 -Wall -o lsm6dsr lsm6dsr.c -lpigpio -lrt
 * Run:    sudo ./lsm6dsr
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM6DSR constants (from datasheet) ---- */
#define LSM6DSR_ADDR        0x6B   /* SA0 tied to GND */
#define LSM6DSR_WHO_AM_I    0x0F
#define LSM6DSR_WHO_AM_I_VAL 0x6B

#define LSM6DSR_CTRL1_XL    0x10   /* accelerometer control */
#define LSM6DSR_CTRL2_G     0x11   /* gyroscope control     */
#define LSM6DSR_OUTX_L_G    0x22   /* gyro X low byte (burst start) */
#define LSM6DSR_OUTX_L_XL   0x28   /* accel X low byte (burst start) */

/*
 * CTRL1_XL = 0x42  -> ODR_XL = 104 Hz, FS_XL = +-2g
 * CTRL2_G  = 0x42  -> ODR_G  = 104 Hz, FS_G  = +-250 dps
 */
#define CTRL1_XL_VAL 0x42
#define CTRL2_G_VAL  0x42

/* Sensitivities (datasheet: 1 LSB = 1/16384 g for accel, 1/32768 dps for gyro) */
#define ACCEL_SENSITIVITY 0.000061f   /* g/LSB at +-2g  */
#define GYRO_SENSITIVITY  0.00875f    /* dps/LSB at +-250 dps */

#define I2C_BUS 1
#define SAMPLE_PERIOD_US 100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an LSM6DSR register; returns 0 on success, -1 on error. */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an LSM6DSR register; returns 0 on success, -1 on error. */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Burst-read `len` bytes starting at `reg`; returns 0 on success, -1 on error. */
static int reg_burst_read(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;

    if (reg_read(handle, LSM6DSR_WHO_AM_I, &who_am_i) != 0)
        return -1;

    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    if (reg_write(handle, LSM6DSR_CTRL1_XL, CTRL1_XL_VAL) != 0)
        return -1;
    if (reg_write(handle, LSM6DSR_CTRL2_G, CTRL2_G_VAL) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] LSM6DSR initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("LSM6DSR ready. Sampling at 104 Hz. Press Ctrl+C to stop.\n");
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        uint8_t buf[12];   /* 6 gyro + 6 accel bytes */

        if (reg_burst_read(g_i2c_handle, LSM6DSR_OUTX_L_G, buf, sizeof(buf)) != 0) {
            /* Sensor may have been disconnected; stop cleanly. */
            break;
        }

        /* Gyroscope: X, Y, Z (each 16-bit little-endian) */
        int16_t gx = (int16_t)((buf[1]  << 8) | buf[0]);
        int16_t gy = (int16_t)((buf[3]  << 8) | buf[2]);
        int16_t gz = (int16_t)((buf[5]  << 8) | buf[4]);

        /* Accelerometer: X, Y, Z (each 16-bit little-endian) */
        int16_t ax = (int16_t)((buf[7]  << 8) | buf[6]);
        int16_t ay = (int16_t)((buf[9]  << 8) | buf[8]);
        int16_t az = (int16_t)((buf[11] << 8) | buf[10]);

        float gx_dps = gx * GYRO_SENSITIVITY;
        float gy_dps = gy * GYRO_SENSITIVITY;
        float gz_dps = gz * GYRO_SENSITIVITY;

        float ax_g = ax * ACCEL_SENSITIVITY;
        float ay_g = ay * ACCEL_SENSITIVITY;
        float az_g = az * ACCEL_SENSITIVITY;

        printf("Gyro: X=%7.2f dps, Y=%7.2f dps, Z=%7.2f dps  |  "
               "Accel: X=%7.3f g, Y=%7.3f g, Z=%7.3f g\n",
               gx_dps, gy_dps, gz_dps, ax_g, ay_g, az_g);
        fflush(stdout);

        /*
         * gpioDelay() is a pigpio microsecond sleep that returns early
         * on signal delivery, so we loop until the full 100 ms elapses.
         */
        uint32_t elapsed = 0;
        while (g_running && elapsed < SAMPLE_PERIOD_US) {
            uint32_t step = 10000;   /* 10 ms chunks */
            if (elapsed + step > SAMPLE_PERIOD_US)
                step = SAMPLE_PERIOD_US - elapsed;
            gpioDelay(step);
            elapsed += step;
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

