        uint8_t buf[12];   /* 6 gyro + 6 accel bytes */

        if (reg_burst_read(g_i2c_handle, LSM6DSR_OUTX_L_G, buf, sizeof(buf)) != 0) {
            /* Sensor may have been disconnected; stop cleanly. */
            break;
        }

        /* Gyroscope: X, Y, Z (each 16-bit little-endian) */
        int16_t gx = (int16_t)((buf[1]  << 8) | buf[0]);
        int16_t gy = (int16_t)((buf[3]  << 8) | buf[2]);
        int16_t gz = (int16_t)((buf[5]  << 8) | buf[4]);

        /* Accelerometer: X, Y, Z (each 16-bit little-endian) */
        int16_t ax = (int16_t)((buf[7]  << 8) | buf[6]);
        int16_t ay = (int16_t)((buf[9]  << 8) | buf[8]);
        int16_t az = (int16_t)((buf[11] << 8) | buf[10]);

        float gx_dps = gx * GYRO_SENSITIVITY;
        float gy_dps = gy * GYRO_SENSITIVITY;
        float gz_dps = gz * GYRO_SENSITIVITY;

        float ax_g = ax * ACCEL_SENSITIVITY;
        float ay_g = ay * ACCEL_SENSITIVITY;
        float az_g = az * ACCEL_SENSITIVITY;

        printf("Gyro: X=%7.2f dps, Y=%7.2f dps, Z=%7.2f dps  |  "
               "Accel: X=%7.3f g, Y=%7.3f g, Z=%7.3f g\n",
               gx_dps, gy_dps, gz_dps, ax_g, ay_g, az_g);
        fflush(stdout);

        /*
         * gpioDelay() is a pigpio microsecond sleep that returns early
         * on signal delivery, so we loop until the full 100 ms elapses.
         */
        uint32_t elapsed = 0;
        while (g_running && elapsed < SAMPLE_PERIOD_US) {
            uint32_t step = 10000;   /* 10 ms chunks */
            if (elapsed + step > SAMPLE_PERIOD_US)
                step = SAMPLE_PERIOD_US - elapsed;
            gpioDelay(step);
            elapsed += step;
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

