#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FXOS8700_ADDR        0x1D
#define FXOS8700_WHO_AM_I    0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1   0x2A
#define FXOS8700_CTRL_REG2   0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB   0x01

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, len %u): %d\n", reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C short read (reg 0x%02X): got %d, expected %u\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int init_fxos8700(int handle) {
    uint8_t whoami = 0;
    if (i2c_read_block(handle, FXOS8700_WHO_AM_I, &whoami, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (whoami != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", whoami, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x00) != 0) return -1;

    /* M_CTRL_REG1: hybrid mode, OSR=7 (best performance) */
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG1, 0x1F) != 0) return -1;

    /* M_CTRL_REG2: auto-increment for multi-byte reads */
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG2, 0x20) != 0) return -1;

    /* CTRL_REG2: no FIFO, no hybrid-auto-increment */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG2, 0x00) != 0) return -1;

    /* CTRL_REG1: active mode, 100 Hz ODR, 800 Hz accel, hybrid mode */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x15) != 0) return -1;

    return 0;
}

static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz) {
    uint8_t buf[12];
    if (i2c_read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    /* Accelerometer: 14-bit left-aligned, two's complement */
    *ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Magnetometer: 16-bit two's complement */
    *mx = (int16_t)((buf[6] << 8) | buf[7]);
    *my = (int16_t)((buf[8] << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700(handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging every 100 ms. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t ax, ay, az, mx, my, mz;
        if (read_sensor_data(handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d | Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

