#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_DATA_FORMAT 0x31
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define I2C_DEVICE "/dev/i2c-1"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int init_adxl345(int fd) {
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_byte(fd, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        return -1;
    }
    if (i2c_write_byte(fd, ADXL345_BW_RATE, 0x0A) < 0) {
        return -1;
    }
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x08) < 0) {
        return -1;
    }
    return 0;
}

int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_DATAX0, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *pitch, float *roll) {
    float x_g = (float)x / 4096.0;
    float y_g = (float)y / 4096.0;
    float z_g = (float)z / 4096.0;
    *pitch = atan2f(y_g, z_g) * 180.0f / M_PI;
    *roll = atan2f(-x_g, sqrtf(y_g * y_g + z_g * z_g)) * 180.0f / M_PI;
}

void log_tilt_event(float pitch, float roll) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Pitch: %.2f, Roll: %.2f\n", s, pitch, roll);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADXL345. Sensor may be absent.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized. Monitoring tilt events...\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float pitch, roll;
        calculate_tilt_angles(x, y, z, &pitch, &roll);

        if (fabsf(pitch) > TILT_THRESHOLD || fabsf(roll) > TILT_THRESHOLD) {
            log_tilt_event(pitch, roll);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

