/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Uses libgpiod (modern GPIO character-device API) to control two
 * 12V electromagnetic door locks via 5V active-HIGH relay modules
 * driven via TIP120 transistors on GPIO17 (Door A) and GPIO27 (Door B).
 *
 * Build:  gcc -Wall -Wextra -O2 -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_DOOR_A  17
#define GPIO_DOOR_B  27
#define CODE_LENGTH  6
#define UNLOCK_SECONDS 5
#define LOG_FILE     "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static int generate_code(char *code, size_t len)
{
    int val = (rand() % 899999) + 100000;
    if (snprintf(code, len, "%06d", val) < 0 ||
        snprintf(code, len, "%06d", val) >= (int)len) {
        return -1;
    }
    return 0;
}

static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%s\n", ts, code) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(gpiochip4): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, GPIO_DOOR_A);
    if (!line_a) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", GPIO_DOOR_A, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_DOOR_B);
    if (!line_b) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", GPIO_DOOR_B, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, default LOW (doors locked) */
    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(line %d): %s\n",
                GPIO_DOOR_A, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(line %d): %s\n",
                GPIO_DOOR_B, strerror(errno));
        goto cleanup;
    }

    srand((unsigned int)time(NULL));

    char code[CODE_LENGTH + 1];
    if (generate_code(code, sizeof(code)) != 0) {
        fprintf(stderr, "Failed to generate initial code\n");
        goto cleanup;
    }

    printf("Initial 6-digit code: %s\n", code);
    printf("Enter the code to unlock Door A (GPIO%d) for %d seconds.\n",
           GPIO_DOOR_A, UNLOCK_SECONDS);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        char input[CODE_LENGTH + 1];
        printf("Enter code: ");
        fflush(stdout);

        if (!fgets(input, sizeof(input), stdin)) {
            if (feof(stdin)) {
                printf("\nEOF on stdin, exiting.\n");
                break;
            }
            if (errno == EINTR) {
                clearerr(stdin);
                continue;
            }
            fprintf(stderr, "fgets error: %s\n", strerror(errno));
            break;
        }

        /* Remove trailing newline */
        input[strcspn(input, "\n")] = '\0';

        if (strlen(input) != CODE_LENGTH) {
            printf("Invalid input: code must be %d digits.\n", CODE_LENGTH);
            continue;
        }

        if (strcmp(input, code) == 0) {
            printf("Code accepted. Unlocking Door A for %d seconds...\n",
                   UNLOCK_SECONDS);

            /* Unlock Door A (HIGH = relay de-energized) */
            if (gpiod_line_set_value(line_a, 1) < 0) {
                fprintf(stderr, "Failed to set Door A HIGH: %s\n", strerror(errno));
                goto cleanup;
            }

            /* Sleep in 1-second increments so SIGINT is responsive */
            for (int i = 0; i < UNLOCK_SECONDS && g_running; i++) {
                sleep(1);
            }

            /* Re-lock Door A */
            if (gpiod_line_set_value(line_a, 0) < 0) {
                fprintf(stderr, "Failed to set Door A LOW: %s\n", strerror(errno));
                goto cleanup;
            }

            if (log_access(code) != 0) {
                fprintf(stderr, "Warning: access log write failed.\n");
            }

            if (generate_code(code, sizeof(code)) != 0) {
                fprintf(stderr, "Failed to generate new code\n");
                goto cleanup;
            }
            printf("New code: %s\n", code);
        } else {
            printf("Access denied.\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure both doors are locked on exit */
    if (line_a) {
        gpiod_line_set_value(line_a, 0);
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

