}

static int read_touch_data(uint16_t *data) {
    char buf[24];
    int rc = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 24);
    if (rc != 24) {
        fprintf(stderr, "I2C read failed: rc=%d\n", rc);
        return -1;
    }
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        data[i] = (uint16_t)((buf[2 * i + 1] << 8) | buf[2 * i]);
    }
    return 0;
}

static double calculate_frequency(const uint16_t *data) {
    uint16_t max_val = 0;
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (data[i] > max_val) max_val = data[i];
    }
    if (max_val == 0) return 0.0;
    double freq = MIN_FREQ + (double)max_val * (MAX_FREQ - MIN_FREQ) / 65535.0;
    return freq;
}

static void play_tone(double frequency) {
    if (frequency <= 0.0) {
        gpioPWM(PWM_GPIO, 0);
        return;
    }
    int freq_int = (int)frequency;
    if (freq_int < 1) freq_int = 1;
    if (freq_int > 1000000) freq_int = 1000000;
    gpioSetPWMfrequency(PWM_GPIO, freq_int);
    gpioPWM(PWM_GPIO, PWM_RANGE / 2);
}

static void log_frequency(double frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", ts, frequency);
    fclose(fp);
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        close(client_fd);
        return;
    }
    buffer[n] = '\0';
    printf("Received: %s\n", buffer);
    if (strstr(buffer, "MOTION_DETECTED:") && strstr(buffer, SHARED_SECRET)) {
        printf("Motion detected and secret key found. Playing tones...\n");
        uint16_t touch_data[NUM_ELECTRODES];
        time_t start = time(NULL);
        while (running && (time(NULL) - start) < PLAYBACK_DURATION_S) {
            if (read_touch_data(touch_data) == 0) {
                double freq = calculate_frequency(touch_data);
                play_tone(freq);
                log_frequency(freq);
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }
        gpioPWM(PWM_GPIO, 0);
        printf("Tones stopped.\n");
    } else {
        printf("Invalid message format.\n");
    }
    close(client_fd);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioPWM(PWM_GPIO, 0);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (running) perror("accept");
            continue;
        }
        handle_client(client_fd);
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (server_fd >= 0) close(server_fd);
    gpioTerminate();
    return 0;
}

