#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303_MAG_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_PERIOD_NS 10000000  // 10 ms period (100 Hz)
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int init_lsm303(int fd) {
    if (i2c_write_reg8(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1_M\n");
        return -1;
    }
    return 0;
}

int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt((double)x * x + (double)y * y + (double)z * z);
}

void set_led_brightness(double magnitude) {
    if (led_line) {
        int duty_ns = (int)((magnitude / 1000.0) * PWM_PERIOD_NS);
        if (duty_ns < 0) duty_ns = 0;
        if (duty_ns > PWM_PERIOD_NS) duty_ns = PWM_PERIOD_NS;
        gpiod_line_set_value(led_line, duty_ns > 0 ? 1 : 0);
    }
}

void log_data(FILE *file, int16_t x, int16_t y, int16_t z, double magnitude) {
    if (!file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(file, "%d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, magnitude);
    fflush(file);
}

void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (init_lsm303(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing LSM303DLHC\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening gpiochip0");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "lsm303_led", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("magnetometer_data.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000L};

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading magnetometer data\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        double magnitude = calculate_magnitude(x, y, z);
        set_led_brightness(magnitude);
        log_data(log_file, x, y, z, magnitude);

        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return 0;
}

