    /* INT1 duration: 0 = immediate */
    if (i2c_write_byte(fd, LSM303D_INT1_DURATION, 0x00) < 0) {
        fprintf(stderr, "Failed to write INT1_DURATION: %s\n", strerror(errno));
        return -1;
    }

    /* INT1_CFG: any-axis high-level interrupt (0x2A) */
    if (i2c_write_byte(fd, LSM303D_INT1_CFG, 0x2A) < 0) {
        fprintf(stderr, "Failed to write INT1_CFG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ---- Read acceleration (6-byte burst, auto-increment) ---- */
static int read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int n = i2c_read_block(fd, LSM303D_OUT_X_L_A | 0x80, buf, 6);
    if (n != 6) {
        if (n < 0)
            fprintf(stderr, "I2C block read error: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C block read short: got %d bytes\n", n);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_add(float x, float y, float z)
{
    g_buffer[g_head].x = x;
    g_buffer[g_head].y = y;
    g_buffer[g_head].z = z;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE)
        g_count++;
}

/* ---- Dump last 10 samples ---- */
static void dump_last_10(void)
{
    int start = (g_head - 10 + BUFFER_SIZE) % BUFFER_SIZE;
    int count = (g_count < 10) ? g_count : 10;
    int idx = start;

    printf("\n--- Last %d acceleration samples ---\n", count);
    for (int i = 0; i < count; i++) {
        printf("  [%2d]  X: %+.2f  Y: %+.2f  Z: %+.2f  mg\n",
               i, g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
        idx = (idx + 1) % BUFFER_SIZE;
    }
    fflush(stdout);
}

/* ---- GPIO interrupt event handler ---- */
static void int1_event_handler(void)
{
    /* Read INT1_SRC to clear the interrupt and determine event type */
    int src = i2c_read_byte(g_i2c_fd, LSM303D_INT1_SRC);
    if (src < 0) {
        fprintf(stderr, "Warning: INT1_SRC read failed: %s\n", strerror(errno));
        return;
    }

    if (src & 0x01) {
        /* INT1 triggered — dump last 10 samples */
        dump_last_10();
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_int1_line) {
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer */
        (void)i2c_write_byte(g_i2c_fd, LSM303D_CTRL_REG1_A, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize LSM303D */
    if (init_lsm303d(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, INT1_GPIO_LINE);
    if (!g_int1_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Request rising-edge events on INT1 */
    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d_int1") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D monitoring started.  INT1 on GPIO23 (BCM).  Ctrl-C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float x, y, z;

        if (read_accel(g_i2c_fd, &x, &y, &z) == 0) {
            buffer_add(x, y, z);
        }

        /* Check for pending GPIO events */
        struct timespec ts = { 0, POLL_DELAY_MS * 1000000L };
        int ev = gpiod_line_event_wait(g_int1_line, &ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (ev > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(g_int1_line, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE)
                    int1_event_handler();
            }
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

