/*
 * reciprocating_actuator.c
 *
 * Raspberry Pi 3 Model B+  |  libgpiod  |  no wiringPi
 *
 * Two 12 V DC push-pull solenoids driven via TIP120 transistors on:
 *   GPIO17 -> solenoid 1 (flyback diode to GND)
 *   GPIO27 -> solenoid 2 (flyback diode to GND)
 *
 * Alternating sequence (500 ms per transition):
 *   1 -> 0 -> 2 -> 0 -> 1 -> 0 -> ...
 *
 * Build:  gcc -O2 -Wall -Wextra -o reciprocating_actuator reciprocating_actuator.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define SOLENOID_1_PIN  17
#define SOLENOID_2_PIN  27
#define CHIP_NAME       "gpiochip0"
#define DELAY_MS        500

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000U;
    ts.tv_nsec = (long)(ms % 1000U) * 1000000L;
    while (nanosleep(&ts, &ts) != 0 && errno == EINTR) {
        /* retry after interruption */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (line1 == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                SOLENOID_1_PIN, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (line2 == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                SOLENOID_2_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "solenoid-1", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(line1): %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "solenoid-2", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(line2): %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Ensure both solenoids start de-energized */
    if (gpiod_line_set_value(line1, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(line1, 0): %s\n",
                strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(line2, 0): %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Reciprocating linear actuator started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        /* Solenoid 1 energize */
        if (gpiod_line_set_value(line1, 1) < 0) {
            fprintf(stderr, "gpiod_line_set_value(line1, 1): %s\n",
                    strerror(errno));
            goto cleanup;
        }
        sleep_ms(DELAY_MS);
        if (!g_running) break;

        /* Solenoid 1 de-energize, Solenoid 2 energize */
        if (gpiod_line_set_value(line1, 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value(line1, 0): %s\n",
                    strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "gpiod_line_set_value(line2, 1): %s\n",
                    strerror(errno));
            goto cleanup;
        }
        sleep_ms(DELAY_MS);
        if (!g_running) break;

        /* Solenoid 2 de-energize */
        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value(line2, 0): %s\n",
                    strerror(errno));
            goto cleanup;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Release both lines to the chip (sets them LOW) */
    if (line1 != NULL) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (rc == EXIT_SUCCESS)
        printf("\nClean shutdown complete.\n");
    return rc;
}

