#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27

#define UART_PORT_1 "/dev/serial0"
#define UART_PORT_2 "/dev/serial1"
#define BAUD_RATE   9600

#define EXPECTED_CODE "123456"
#define CODE_LENGTH   6
#define TIMEOUT_SEC   5
#define UNLOCK_SEC    2

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(LOCK_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK_1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK_2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK_1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW on init.\n", LOCK_1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK_2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW on init.\n", LOCK_2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_serial(const char *port, int baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", port, strerror(errno));
        return -1;
    }
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error: cannot clear O_NDELAY on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error: tcgetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error: tcsetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_code(int fd, char *code, int max_len, int timeout_sec) {
    char buf[256];
    size_t code_len = 0;
    time_t start = time(NULL);
    while (g_running) {
        ssize_t n = read(fd, buf, sizeof(buf) - 1);
        if (n > 0) {
            for (ssize_t i = 0; i < n; i++) {
                char c = buf[i];
                if (c >= '0' && c <= '9') {
                    if (code_len < (size_t)max_len) {
                        code[code_len++] = c;
                    }
                } else if (c == '\r' || c == '\n') {
                    if (code_len == (size_t)max_len) {
                        code[code_len] = '\0';
                        return 0;
                    }
                    code_len = 0;
                } else {
                    code_len = 0;
                }
            }
        } else if (n < 0 && errno != EAGAIN && errno != EWOULDBLOCK) {
            fprintf(stderr, "Warning: read error on fd %d: %s\n", fd, strerror(errno));
            return -1;
        }
        if (time(NULL) - start >= timeout_sec) {
            fprintf(stderr, "Warning: timeout waiting for code on fd %d\n", fd);
            return -1;
        }
        usleep(10000);
    }
    return -1;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK_1_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH (unlock)\n", LOCK_1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK_2_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH (unlock)\n", LOCK_2_GPIO);
        gpioWrite(LOCK_1_GPIO, 0);
        return -1;
    }
    printf("Doors unlocked for %d seconds.\n", UNLOCK_SEC);
    sleep(UNLOCK_SEC);
    if (gpioWrite(LOCK_1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW (re-lock)\n", LOCK_1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK_2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW (re-lock)\n", LOCK_2_GPIO);
        return -1;
    }
    printf("Doors re-locked.\n");
    return 0;
}

static void cleanup(int fd1, int fd2) {
    if (fd1 >= 0) close(fd1);
    if (fd2 >= 0) close(fd2);
    gpioWrite(LOCK_1_GPIO, 0);
    gpioWrite(LOCK_2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
