/*
 * door_strike.c — Raspberry Pi 4 Model B
 *
 * libgpiod-based PIR motion detector + relay strike controller.
 *
 * PIR sensor : HC-SR501 on GPIO4  (physical pin 7)
 * Relay      : 5V relay module on GPIO17 (physical pin 11)
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_strike door_strike.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN          4
#define RELAY_PIN        17
#define STRIKE_DURATION  1          /* seconds */
#define FAILSAFE_TIMEOUT 10         /* seconds */
#define POLL_INTERVAL_US 50000      /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
    if (priority == LOG_ERR)
        fprintf(stderr, "[ERROR] %s\n", msg);
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open log -------------------------------------------------- */
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Open gpiochip0 -------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_event(LOG_ERR, "Failed to open gpiochip0: ");
        syslog(LOG_ERR, "gpiod_chip_open_by_name: %s", strerror(errno));
        goto cleanup;
    }

    /* ---- Get lines ------------------------------------------------- */
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_event(LOG_ERR, "Failed to get PIR line (GPIO4): ");
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_event(LOG_ERR, "Failed to get relay line (GPIO17): ");
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines --------------------------------------------- */
    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        log_event(LOG_ERR, "Failed to request PIR line as input: ");
        syslog(LOG_ERR, "gpiod_line_request_input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        log_event(LOG_ERR, "Failed to request relay line as output: ");
        syslog(LOG_ERR, "gpiod_line_request_output: %s", strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "Door strike controller started (PIR=GPIO4, Relay=GPIO17)");

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            log_event(LOG_ERR, "Failed to read PIR sensor: ");
            syslog(LOG_ERR, "gpiod_line_get_value(PIR): %s", strerror(errno));
            sleep_ms(100);
            continue;
        }

        if (pir_val == 1) {
            log_event(LOG_INFO, "Motion detected — activating relay strike");

            if (gpiod_line_set_value(relay_line, 1) < 0) {
                log_event(LOG_ERR, "Failed to energize relay: ");
                syslog(LOG_ERR, "gpiod_line_set_value(relay, 1): %s", strerror(errno));
                break;
            }

            sleep_ms(STRIKE_DURATION * 1000);

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                log_event(LOG_ERR, "Failed to de-energize relay: ");
                syslog(LOG_ERR, "gpiod_line_set_value(relay, 0): %s", strerror(errno));
                break;
            }
            log_event(LOG_INFO, "Relay strike complete — relay de-energized");

            /* Failsafe: wait 10 s, check PIR, de-energize if still HIGH */
            unsigned int waited = 0;
            while (g_running && waited < FAILSAFE_TIMEOUT * 10) {
                sleep_ms(100);
                waited += 100;
                int v = gpiod_line_get_value(pir_line);
                if (v < 0) {
                    log_event(LOG_ERR, "PIR read error during failsafe: ");
                    syslog(LOG_ERR, "gpiod_line_get_value(PIR): %s", strerror(errno));
                    break;
                }
                if (v == 0)
                    break;
            }

            if (g_running) {
                int v = gpiod_line_get_value(pir_line);
                if (v < 0) {
                    log_event(LOG_ERR, "PIR read error during failsafe: ");
                    syslog(LOG_ERR, "gpiod_line_get_value(PIR): %s", strerror(errno));
                } else if (v == 1) {
                    log_event(LOG_WARNING,
                              "PIR still HIGH after 10 s — potential malfunction, de-energizing relay");
                    if (gpiod_line_set_value(relay_line, 0) < 0) {
                        log_event(LOG_ERR, "Failsafe de-energize failed: ");
                        syslog(LOG_ERR, "gpiod_line_set_value(relay, 0): %s", strerror(errno));
                    }
                }
            }
        }

        sleep_ms(POLL_INTERVAL_US / 1000);
    }

    log_event(LOG_INFO, "Shutting down — de-energizing relay and releasing GPIO");
    if (relay_line)
        gpiod_line_set_value(relay_line, 0);

    ret = EXIT_SUCCESS;

cleanup:
    if (pir_line)
        gpiod_line_release(pir_line);
    if (relay_line)
        gpiod_line_release(relay_line);
    if (chip)
        gpiod_chip_close(chip);
    closelog();
    return ret;
}

