#define RELAY_PAUSE_SEC    60    /* 1 minute   */
#define TIMER_INTERVAL_SEC 60    /* 1 minute   */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static int safe_set_mode(unsigned gpio, unsigned mode)
{
    if (gpioSetMode(gpio, mode) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%u, %u) failed", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) != 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed", gpio, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control (active-LOW: LOW = ON, HIGH = OFF)                    */
/* ------------------------------------------------------------------ */

static void relay_on(unsigned gpio)
{
    if (safe_write(gpio, 0) == 0)
        syslog(LOG_INFO, "Relay on GPIO%u turned ON", gpio);
}

static void relay_off(unsigned gpio)
{
    if (safe_write(gpio, 1) == 0)
        syslog(LOG_INFO, "Relay on GPIO%u turned OFF", gpio);
}

static void all_relays_off(void)
{
    relay_off(RELAY1);
    relay_off(RELAY2);
    relay_off(RELAY3);
    relay_off(RELAY4);
}

/* ------------------------------------------------------------------ */
/* Timer callback (fires every TIMER_INTERVAL_SEC)                    */
/* ------------------------------------------------------------------ */

/*
 * State machine:
 *   0 = idle / pause -> activate relay 1 for RELAY_ON_TIME_SEC
 *   1 = relay 1 active -> pause for RELAY_PAUSE_SEC
 *   2 = pause -> activate relay 2
 *   3 = relay 2 active -> pause
 *   4 = pause -> activate relay 3
 *   5 = relay 3 active -> pause
 *   6 = pause -> activate relay 4
 *   7 = relay 4 active -> pause
 *   8 = pause -> loop back to relay 1
 */
static volatile int g_timer_state = 0;
static volatile time_t g_next_fire = 0;

static void timer_callback(void *userdata)
{
    (void)userdata;

    time_t now = time(NULL);
    if (now < g_next_fire)
        return; /* not yet time */

    int state = g_timer_state;
    g_timer_state = (state + 1) % 9;

    switch (state) {
    case 0: /* idle -> relay 1 */
        relay_on(RELAY1);
        syslog(LOG_INFO, "Activating relay 1 (GPIO%u) for %d seconds",
               RELAY1, RELAY_ON_TIME_SEC);
        g_next_fire = now + RELAY_ON_TIME_SEC;
        break;

    case 1: /* relay 1 done -> pause */
        relay_off(RELAY1);
        syslog(LOG_INFO, "Deactivated relay 1 (GPIO%u)", RELAY1);
        g_next_fire = now + RELAY_PAUSE_SEC;
        break;

    case 2: /* pause -> relay 2 */
        relay_on(RELAY2);
        syslog(LOG_INFO, "Activating relay 2 (GPIO%u) for %d seconds",
               RELAY2, RELAY_ON_TIME_SEC);
        g_next_fire = now + RELAY_ON_TIME_SEC;
        break;

    case 3: /* relay 2 done -> pause */
        relay_off(RELAY2);
        syslog(LOG_INFO, "Deactivated relay 2 (GPIO%u)", RELAY2);
        g_next_fire = now + RELAY_PAUSE_SEC;
        break;

    case 4: /* pause -> relay 3 */
        relay_on(RELAY3);
        syslog(LOG_INFO, "Activating relay 3 (GPIO%u) for %d seconds",
               RELAY3, RELAY_ON_TIME_SEC);
        g_next_fire = now + RELAY_ON_TIME_SEC;
        break;

    case 5: /* relay 3 done -> pause */
        relay_off(RELAY3);
        syslog(LOG_INFO, "Deactivated relay 3 (GPIO%u)", RELAY3);
        g_next_fire = now + RELAY_PAUSE_SEC;
        break;

    case 6: /* pause -> relay 4 */
        relay_on(RELAY4);
        syslog(LOG_INFO, "Activating relay 4 (GPIO%u) for %d seconds",
               RELAY4, RELAY_ON_TIME_SEC);
        g_next_fire = now + RELAY_ON_TIME_SEC;
        break;

    case 7: /* relay 4 done -> pause */
        relay_off(RELAY4);
        syslog(LOG_INFO, "Deactivated relay 4 (GPIO%u)", RELAY4);
        g_next_fire = now + RELAY_PAUSE_SEC;
        break;

    case 8: /* pause -> loop back to relay 1 */
        syslog(LOG_INFO, "Looping back to relay 1");
        g_next_fire = now + 1;
        break;
    }
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    unsigned relays[] = {RELAY1, RELAY2, RELAY3, RELAY4};
    for (size_t i = 0; i < sizeof(relays) / sizeof(relays[0]); i++) {
        if (safe_set_mode(relays[i], PI_OUTPUT) != 0) {
            all_relays_off();
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
        if (safe_write(relays[i], 1) != 0) { /* start with relays OFF */
            all_relays_off();
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    /* ---- timer setup ---- */
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC * 1000,
                           timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "gpioSetTimerFuncEx(0, %d) failed",
               TIMER_INTERVAL_SEC * 1000);
        all_relays_off();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        all_relays_off();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started (relays ON for %d s, pause %d s)",
           RELAY_ON_TIME_SEC, RELAY_PAUSE_SEC);

    /* ---- main loop ---- */
    while (g_running)
        sleep(1);

    /* ---- shutdown ---- */
    syslog(LOG_INFO, "Shutting down irrigation system");
    all_relays_off();
    gpioSetTimerFuncEx(0, 0, NULL, NULL); /* cancel timer */
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

