typedef struct {
    float x, y, z;
} accel_data_t;

static accel_data_t accel_buffer[BUFFER_SIZE];
static int         buffer_index = 0;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t running = 1;
static int  i2c_fd   = -1;
static int  sysfs_fd = -1;
static timer_t timerid;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- MPU6050 init ---- */
static int init_mpu6050(int fd)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */

    /* Set accelerometer range to +/- 2g (AFS_SEL = 0) */
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read acceleration ---- */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_regs(fd, REG_ACCEL_XOUT_H, raw, 6) < 0)
        return -1;

    int16_t x_raw = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y_raw = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z_raw = (int16_t)((raw[4] << 8) | raw[5]);

    *x = (float)x_raw / ACCEL_SCALE;
    *y = (float)y_raw / ACCEL_SCALE;
    *z = (float)z_raw / ACCEL_SCALE;
    return 0;
}

/* ---- Circular buffer ---- */
static void add_to_buffer(float x, float y, float z)
{
    accel_buffer[buffer_index].x = x;
    accel_buffer[buffer_index].y = y;
    accel_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* ---- Sysfs setup ---- */
static int setup_sysfs(void)
{
    /* Create /sys/kernel/mpu6050_accel/latest */
    if (mkdir("/sys/kernel/mpu6050_accel", 0755) == -1 && errno != EEXIST) {
        fprintf(stderr, "mkdir /sys/kernel/mpu6050_accel failed: %s\n", strerror(errno));
        return -1;
    }
    const char *path = "/sys/kernel/mpu6050_accel/latest";
    sysfs_fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (sysfs_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static void write_sysfs(const accel_data_t *d)
{
    char buf[128];
    int len = snprintf(buf, sizeof(buf), "%.3f,%.3f,%.3f\n", d->x, d->y, d->z);
    if (len > 0) {
        if (write(sysfs_fd, buf, (size_t)len) != len)
            fprintf(stderr, "sysfs write failed: %s\n", strerror(errno));
    }
}

/* ---- Timer callback ---- */
static void timer_handler(int sig, siginfo_t *si, void *uc)
{
    (void)sig;
    (void)si;
    (void)uc;

    float x, y, z;
    if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
        add_to_buffer(x, y, z);
        write_sysfs(&accel_buffer[buffer_index]);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (sysfs_fd != -1) {
        close(sysfs_fd);
        sysfs_fd = -1;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    /* Disarm timer */
    struct sigevent ev;
    memset(&ev, 0, sizeof(ev));
    timer_delete(timerid);
}

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(MPU6050_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", MPU6050_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 init failed (sensor absent or bus error).\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Setup sysfs */
    if (setup_sysfs() < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Install timer: 100 Hz, per-process signal */
    struct sigevent tev;
    memset(&tev, 0, sizeof(tev));
    tev.sigev_notify = SIGEV_SIGNAL;
    tev.sigev_signo  = SIGRTMIN;
    tev.sigev_value.sival_ptr = &timerid;
    if (timer_create(CLOCK_MONOTONIC, &tev, &timerid) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa_timer;
    memset(&sa_timer, 0, sizeof(sa_timer));
    sa_timer.sa_sigaction = timer_handler;
    sigemptyset(&sa_timer.sa_mask);
    sa_timer.sa_flags = SA_RESTART;
    if (sigaction(SIGRTMIN, &sa_timer, NULL) < 0) {
        fprintf(stderr, "sigaction SIGRTMIN failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct itimerspec its;
    its.it_interval.tv_sec  = 0;
    its.it_interval.tv_nsec = 10000000L;  /* 10 ms = 100 Hz */
    its.it_value = its.it_interval;
    if (timer_settime(timerid, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU6050 reader running.  Latest data at /sys/kernel/mpu6050_accel/latest\n");
    printf("Press Ctrl+C to exit.\n");

    while (running)
        pause();

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

