#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"

static const int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int interval_seconds[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long get_monotonic_ms(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int line_offsets[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
        line_offsets[i] = relay_pins[i];
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request output on GPIO %d: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    long long next_toggle_ms[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        next_toggle_ms[i] = get_monotonic_ms() + (long long)interval_seconds[i] * 1000LL;
        if (next_toggle_ms[i] < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        long long now_ms = get_monotonic_ms();
        if (now_ms < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (now_ms >= next_toggle_ms[i]) {
                int current_val = gpiod_line_get_value(lines[i]);
                if (current_val < 0) {
                    fprintf(stderr, "Failed to read GPIO %d: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                if (gpiod_line_set_value(lines[i], !current_val) < 0) {
                    fprintf(stderr, "Failed to write GPIO %d: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                next_toggle_ms[i] = now_ms + (long long)interval_seconds[i] * 1000LL;
            }
        }
        usleep(10000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

