                if (log_alarm_event() < 0) {
                    fprintf(stderr, "Error logging alarm event\n");
                }
                last_trigger_tick = now;
            }
        }

        last_state = sound_level;
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

