#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75

// Expected WHO_AM_I value for MPU-6050
#define MPU6050_WHO_AM_I_VAL 0x68

// Gyroscope sensitivity for default +/- 250 dps range
#define GYRO_SENSITIVITY 131.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold in degrees/second
#define ANGULAR_VELOCITY_THRESHOLD 50.0f

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Function prototypes
int i2c_write_reg8(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value);
int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len);
int mpu6050_init(int fd);
int mpu6050_read_gyro(int fd, gyro_data_t *data);
void circular_buffer_init(circular_buffer_t *cb);
void circular_buffer_add(circular_buffer_t *cb, gyro_data_t data);
void callback_function(gyro_data_t data);
void signal_handler(int sig);

// I2C write function
int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function for 8-bit registers
int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C burst read function
int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for burst read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading burst data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    uint8_t who_am_i = 0;

    // Verify device identity
    if (i2c_read_reg8(fd, MPU6050_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "MPU-6050 not found. WHO_AM_I returned 0x%02X, expected 0x%02X\n", who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }

    // Configure sample rate divider (1 kHz / (1 + 7) = 125 Hz)
    if (i2c_write_reg8(fd, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        return -1;
    }

    // Configure DLPF (Digital Low Pass Filter)
    if (i2c_write_reg8(fd, MPU6050_CONFIG, 0x01) < 0) {
        return -1;
    }

    // Configure gyroscope full scale range (+/- 250 dps)
    if (i2c_write_reg8(fd, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        return -1;
    }

    // Configure accelerometer full scale range (+/- 2g)
    if (i2c_write_reg8(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int mpu6050_read_gyro(int fd, gyro_data_t *data) {
    uint8_t buf[6];

    // Read 6 bytes of gyroscope data starting from GYRO_XOUT_H
    if (i2c_read_burst(fd, MPU6050_GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    // Combine high and low bytes (big-endian)
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second
    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
    data->z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Circular buffer initialization function
void circular_buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Circular buffer add function
void circular_buffer_add(circular_buffer_t *cb, gyro_data_t data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Callback function
void callback_function(gyro_data_t data) {
    float magnitude = sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
        printf("Angular velocity threshold exceeded! Magnitude: %.2f dps\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    // Initialize circular buffer
    circular_buffer_t gyro_buffer;
    circular_buffer_init(&gyro_buffer);

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 initialized successfully.\n");

    // Main loop
    while (running) {
        gyro_data_t gyro_data;

        // Read gyroscope data
        if (mpu6050_read_gyro(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Add data to circular buffer
        circular_buffer_add(&gyro_buffer, gyro_data);

        // Callback function
        callback_function(gyro_data);

        // Print data
        printf("X: %.2f, Y: %.2f, Z: %.2f dps\n", gyro_data.x, gyro_data.y, gyro_data.z);

        usleep(10000); // 10ms delay
    }

    // Cleanup
    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

