/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 (9600 baud, TXD=GPIO14, RXD=GPIO15)
 * Logs JSON lines to co2_log.json and errors to co2_error.log
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lpigpio -lrt
 * Run:   sudo ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define READ_INTERVAL_S  5
#define READ_TIMEOUT_S   1
#define READ_RETRY_DELAY_US 10000   /* 10 ms between retries */
#define READ_CMD_LEN     9
#define RESP_LEN         9

static const uint8_t READ_CMD[READ_CMD_LEN] = {
    0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (g_err_fp) {
        fprintf(g_err_fp, "%s: %s\n", ts, msg);
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART helpers                                                        */
/* ------------------------------------------------------------------ */

static int init_uart(void)
{
    g_uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_fd < 0) {
        log_error("serOpen failed");
        return -1;
    }
    return 0;
}

static void close_uart(void)
{
    if (g_uart_fd >= 0) {
        serClose(g_uart_fd);
        g_uart_fd = -1;
    }
}

/*
 * Read exactly `len` bytes from the UART within `timeout_s` seconds.
 * Returns 0 on success, -1 on timeout or error.
 */
static int read_exact(uint8_t *buf, int len, int timeout_s)
{
    int total = 0;
    time_t start = time(NULL);

    while (total < len) {
        if (time(NULL) - start >= timeout_s) {
            log_error("UART read timeout");
            return -1;
        }

        int avail = serDataAvailable(g_uart_fd);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }

        if (avail > 0) {
            int to_read = (avail < len - total) ? avail : (len - total);
            int n = serRead(g_uart_fd, (char *)(buf + total), to_read);
            if (n < 0) {
                log_error("serRead failed");
                return -1;
            }
            total += n;
        } else {
            gpioDelay(READ_RETRY_DELAY_US);
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CO2 measurement                                                     */
/* ------------------------------------------------------------------ */

static int read_co2(int *co2_ppm)
{
    uint8_t resp[RESP_LEN];

    /* Send read command */
    if (serWrite(g_uart_fd, (char *)READ_CMD, READ_CMD_LEN) != READ_CMD_LEN) {
        log_error("serWrite command failed");
        return -1;
    }

    /* Wait for sensor to process (datasheet: 30–100 ms) */
    gpioDelay(100000); /* 100 ms */

    /* Read response */
    if (read_exact(resp, RESP_LEN, READ_TIMEOUT_S) != 0)
        return -1;

    /* Validate checksum: sum of bytes 1..7, then invert, add 1, must equal byte 8 */
    uint8_t checksum = 0;
    for (int i = 1; i < 8; i++)
        checksum += resp[i];
    checksum = (uint8_t)(0xFF - checksum + 1);
    if (checksum != resp[8]) {
        log_error("CO2 checksum mismatch");
        return -1;
    }

    *co2_ppm = (resp[2] << 8) | resp[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(int co2_ppm, int error)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_buf;
    struct tm *t = localtime_r(&ts.tv_sec, &tm_buf);
    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log_fp,
            "{\"timestamp\":\"%s.%06ldZ\",\"co2_ppm\":%d,\"error\":%d}\n",
            ts_str, ts.tv_nsec / 1000, co2_ppm, error);
    fflush(g_log_fp);

    printf("{\"timestamp\":\"%s.%06ldZ\",\"co2_ppm\":%d,\"error\":%d}\n",
           ts_str, ts.tv_nsec / 1000, co2_ppm, error);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    close_uart();
    if (g_log_fp)  { fclose(g_log_fp);  g_log_fp  = NULL; }
    if (g_err_fp)  { fclose(g_err_fp);  g_err_fp  = NULL; }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen error log");
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open UART */
    if (init_uart() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO2 monitor started. Logging to %s every %d s.\n",
           LOG_FILE, READ_INTERVAL_S);
    fflush(stdout);

    while (g_running) {
        int co2 = 0;
        int ok = (read_co2(&co2) == 0);

        log_data(ok ? co2 : 0, ok ? 0 : 1);

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

