#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000

#define X_OFFSET 100.0
#define Y_OFFSET -50.0

typedef struct {
    time_t timestamp;
    float heading;
} HeadingData;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static HeadingData heading_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hmc5883l(int handle) {
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y) {
    float x_comp = (float)x - X_OFFSET;
    float y_comp = (float)y - Y_OFFSET;
    float heading = atan2f(y_comp, x_comp) * 180.0f / M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

static void add_to_buffer(float heading) {
    time(&heading_buffer[buffer_index].timestamp);
    heading_buffer[buffer_index].heading = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void control_gpio(float heading) {
    float diff = fabsf(heading - TARGET_HEADING);
    if (diff > 180.0f) diff = 360.0f - diff;
    if (diff > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    float heading;

    while (running) {
        if (read_magnetometer(i2c_handle, &x, &y, &z) == 0) {
            heading = calculate_heading(x, y);
            add_to_buffer(heading);
            control_gpio(heading);
        } else {
            fprintf(stderr, "Read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

