/*
 * Smart Lighting System for Raspberry Pi 5
 * Relays: libgpiod (BCM 17, 27, 22)
 * Sensor: BH1750 on I2C bus 1, address 0x23
 * Log:    lighting_log.txt
 *
 * Build: gcc -O2 -Wall -o smart_light smart_light.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22

#define BH1750_ADDR        0x23
#define BH1750_CONT_HRES   0x10
#define BH1750_CONV_MS     120

#define LUX_THRESHOLD_1    50.0f
#define LUX_THRESHOLD_2    150.0f
#define LUX_THRESHOLD_3    300.0f

#define LOG_FILE "lighting_log.txt"
#define I2C_BUS  "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int bh1750_init(int fd)
{
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, &(uint8_t){BH1750_CONT_HRES}, 1) != 1) {
        fprintf(stderr, "BH1750 init write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);
    return 0;
}

static int bh1750_read(int fd, float *lux_out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "BH1750 read failed: %s\n",
                n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux, int r, int g, int b)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            lux, r, g, b);
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rl[3] = {NULL, NULL, NULL};
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        goto cleanup;
    }

    rl[0] = gpiod_chip_get_line(chip, RED_PIN);
    rl[1] = gpiod_chip_get_line(chip, GREEN_PIN);
    rl[2] = gpiod_chip_get_line(chip, BLUE_PIN);
    for (int i = 0; i < 3; i++) {
        if (!rl[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                    (i == 0) ? RED_PIN : (i == 1) ? GREEN_PIN : BLUE_PIN,
                    strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(rl[i], "smart_light", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n",
                    (i == 0) ? RED_PIN : (i == 1) ? GREEN_PIN : BLUE_PIN,
                    strerror(errno));
            goto cleanup;
        }
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; relays off, retrying...\n");
            for (int i = 0; i < 3; i++)
                gpiod_line_set_value(rl[i], 0);
            sleep(1);
            continue;
        }

        int r = 0, g = 0, b = 0;
        if (lux < LUX_THRESHOLD_1) r = 1;
        else if (lux < LUX_THRESHOLD_2) g = 1;
        else if (lux < LUX_THRESHOLD_3) { r = 1; g = 1; }
        else { r = 1; g = 1; b = 1; }

        for (int i = 0; i < 3; i++)
            gpiod_line_set_value(rl[i], (i == 0) ? r : (i == 1) ? g : b);

        log_data(log_fp, lux, r, g, b);
        sleep(1);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (rl[i]) {
            gpiod_line_set_value(rl[i], 0);
            gpiod_line_release(rl[i]);
        }
    }
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp) fclose(log_fp);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

