#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

#define DISTANCE_THRESHOLD 50.0
#define MIN_DISTANCE 10.0
#define MAX_DISTANCE 100.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_direction(int in1, int in2, int forward) {
    if (gpioWrite(in1, forward ? 1 : 0) < 0) return -1;
    if (gpioWrite(in2, forward ? 0 : 1) < 0) return -1;
    return 0;
}

static int set_motor_speed(int in2, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (gpioPWM(in2, speed) < 0) return -1;
    return 0;
}

static int map_distance_to_speed(float distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    return (int)(((MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE)) * PWM_RANGE);
}

static int control_motor(int in1, int in2, float distance) {
    int speed = map_distance_to_speed(distance);
    int forward = (distance < DISTANCE_THRESHOLD) ? 1 : 0;
    if (set_motor_direction(in1, in2, forward) < 0) return -1;
    if (set_motor_speed(in2, speed) < 0) return -1;
    return 0;
}

static void stop_motor(int in1, int in2) {
    gpioWrite(in1, 0);
    gpioWrite(in2, 0);
    gpioPWM(in2, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float distance_a = 60.0f;
        float distance_b = 70.0f;

        if (control_motor(MOTOR_A_IN1, MOTOR_A_IN2, distance_a) < 0) {
            fprintf(stderr, "Error: motor A control failed\n");
            break;
        }
        if (control_motor(MOTOR_B_IN3, MOTOR_B_IN4, distance_b) < 0) {
            fprintf(stderr, "Error: motor B control failed\n");
            break;
        }

        gpioDelay(100000);
    }

    stop_motor(MOTOR_A_IN1, MOTOR_A_IN2);
    stop_motor(MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();
    return EXIT_SUCCESS;
}

