#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_BUTTON_PIN 24
#define UNLOCK_BUTTON_PIN 23

#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22

#define STEPS_PER_REV 512
#define STEP_DELAY_US 2000

static volatile sig_atomic_t running = 1;

static const int step_sequence[4][2] = {
    {1, 0},
    {1, 1},
    {0, 1},
    {0, 0}
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void deenergize(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {IN1, IN2, IN3, IN4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to write GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void step_motor(int direction, int steps) {
    int current_step = 0;
    for (int i = 0; i < steps && running; ++i) {
        if (direction > 0) {
            current_step = i % 4;
        } else {
            current_step = (3 - (i % 4));
        }
        gpioWrite(IN1, step_sequence[current_step][0]);
        gpioWrite(IN2, step_sequence[current_step][1]);
        gpioWrite(IN3, step_sequence[current_step][0]);
        gpioWrite(IN4, step_sequence[current_step][1]);
        gpioDelay(STEP_DELAY_US);
    }
}

static void lock_door(void) {
    printf("Locking door...\n");
    fflush(stdout);
    step_motor(1, STEPS_PER_REV);
    printf("Door locked.\n");
    fflush(stdout);
}

static void unlock_door(void) {
    printf("Unlocking door...\n");
    fflush(stdout);
    step_motor(-1, STEPS_PER_REV);
    printf("Door unlocked.\n");
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int lock_pressed = 0;
    int unlock_pressed = 0;

    while (running) {
        int lock_state = gpioRead(LOCK_BUTTON_PIN);
        int unlock_state = gpioRead(UNLOCK_BUTTON_PIN);

        if (lock_state == 0 && !lock_pressed) {
            lock_pressed = 1;
            lock_door();
        } else if (lock_state == 1) {
            lock_pressed = 0;
        }

        if (unlock_state == 0 && !unlock_pressed) {
            unlock_pressed = 1;
            unlock_door();
        } else if (unlock_state == 1) {
            unlock_pressed = 0;
        }

        gpioDelay(50000);
    }

    deenergize();
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

