#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

#define LOG_FILE "solar_tracker.log"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int log_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    int retries = 3;
    while (retries-- > 0) {
        if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) == 0) return 0;
        usleep(10000);
    }
    return -1;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    if (i2c_read_reg16(fd, ACCEL_XOUT_H, ax) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_YOUT_H, ay) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_ZOUT_H, az) < 0) return -1;
    return 0;
}

static int read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    if (i2c_read_reg16(fd, GYRO_XOUT_H, gx) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_YOUT_H, gy) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_ZOUT_H, gz) < 0) return -1;
    return 0;
}

static float calculate_pitch(int16_t ax, int16_t ay, int16_t az) {
    float x = (float)ax / 16384.0f;
    float y = (float)ay / 16384.0f;
    float z = (float)az / 16384.0f;
    return atan2f(y, sqrtf(x * x + z * z)) * 180.0f / M_PI;
}

static float calculate_roll(int16_t ax, int16_t ay, int16_t az) {
    float x = (float)ax / 16384.0f;
    float y = (float)ay / 16384.0f;
    float z = (float)az / 16384.0f;
    return atan2f(-x, sqrtf(y * y + z * z)) * 180.0f / M_PI;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    int pulse = SERVO_MIN_PULSE + (int)((float)angle / 180.0f * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    char buf[64];
    snprintf(buf, sizeof(buf), "%d", pulse);
    FILE *f = fopen("/sys/class/pwm/pwmchip2/pwm0/duty_cycle", "w");
    if (!f) return -1;
    fprintf(f, "%s", buf);
    fclose(f);
    return 0;
}

static int log_data(float pitch, float roll, int servo_pos) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    char line[256];
    snprintf(line, sizeof(line), "%s,%.2f,%.2f,%d\n", ts, pitch, roll, servo_pos);
    if (write(log_fd, line, strlen(line)) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to init MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    FILE *pwm_ex = fopen("/sys/class/pwm/pwmchip2/export", "w");
    if (!pwm_ex) { perror("export pwm"); close(i2c_fd); return 1; }
    fprintf(pwm_ex, "%d", PWM_CHANNEL);
    fclose(pwm_ex);
    usleep(100000);

    char period_path[128];
    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/pwmchip2/pwm%d/period", PWM_CHANNEL);
    FILE *period_f = fopen(period_path, "w");
    if (!period_f) { perror("set period"); close(i2c_fd); return 1; }
    fprintf(period_f, "20000");
    fclose(period_f);

    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/pwmchip2/pwm%d/enable", PWM_CHANNEL);
    FILE *enable_f = fopen(period_path, "w");
    if (!enable_f) { perror("enable pwm"); close(i2c_fd); return 1; }
    fprintf(enable_f, "1");
    fclose(enable_f);

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open log");
        close(i2c_fd);
        return 1;
    }

    int16_t ax, ay, az, gx, gy, gz;
    float pitch, roll;
    int servo_pos = 90;
    int retry_count = 0;

    while (running) {
        if (read_accel(i2c_fd, &ax, &ay, &az) == 0 && read_gyro(i2c_fd, &gx, &gy, &gz) == 0) {
            pitch = calculate_pitch(ax, ay, az);
            roll = calculate_roll(ax, ay, az);
            if (pitch > 10.0f) servo_pos++;
            else if (pitch < -10.0f) servo_pos--;
            if (set_servo_angle(servo_pos) < 0) fprintf(stderr, "PWM write failed\n");
            if (log_data(pitch, roll, servo_pos) < 0) fprintf(stderr, "Log write failed\n");
            retry_count = 0;
        } else {
            fprintf(stderr, "Read error: %s\n", strerror(errno));
            retry_count++;
            if (retry_count > 10) {
                fprintf(stderr, "Sensor absent or bus error. Exiting.\n");
                break;
            }
            usleep(100000);
            continue;
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    FILE *disable_f = fopen("/sys/class/pwm/pwmchip2/pwm0/enable", "w");
    if (disable_f) { fprintf(disable_f, "0"); fclose(disable_f); }
    fclose(log_fd);
    close(i2c_fd);
    return 0;
}

