} ScheduleEntry;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_schedule(const char *filename, ScheduleEntry **schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;
        count++;
    }
    if (count == 0) {
        fprintf(stderr, "Error: No valid entries found in schedule file.\n");
        fclose(fp);
        return -1;
    }

    *schedule = (ScheduleEntry *)malloc(count * sizeof(ScheduleEntry));
    if (!*schedule) {
        perror("Error allocating memory for schedule");
        fclose(fp);
        return -1;
    }

    rewind(fp);
    count = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;
        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &(*schedule)[count].hour,
                   &(*schedule)[count].minute,
                   &(*schedule)[count].second,
                   &(*schedule)[count].relay_number,
                   &(*schedule)[count].on_off) != 5) {
            fprintf(stderr, "Error parsing schedule entry: %s", line);
            free(*schedule);
            *schedule = NULL;
            fclose(fp);
            return -1;
        }
        count++;
    }

    *num_entries = count;
    fclose(fp);
    return 0;
}

static int get_current_time(int *hour, int *minute, int *second) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("Error getting local time");
        return -1;
    }

    *hour = timeinfo->tm_hour;
    *minute = timeinfo->tm_min;
    *second = timeinfo->tm_sec;
    return 0;
}

static int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int target_state, int duration) {
    int current_state = gpioRead(pin);
    if (current_state < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }

    if (current_state == target_state) return 0;

    int steps = PWM_RANGE;
    int step_delay_us = (duration * 1000000) / steps;

    for (int i = 0; i <= steps; i++) {
        if (!program_running) return -1;

        int duty = (target_state == 1) ? i : (steps - i);
        if (gpioPWM(pin, duty) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
            return -1;
        }
        usleep(step_delay_us);
    }

    if (gpioPWM(pin, target_state) != 0) {
        fprintf(stderr, "Error setting final PWM on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int apply_schedule_entry(const ScheduleEntry *entry) {
    if (entry->relay_number < 1 || entry->relay_number > NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", entry->relay_number);
        return -1;
    }
    if (entry->on_off != 0 && entry->on_off != 1) {
        fprintf(stderr, "Invalid on/off value: %d\n", entry->on_off);
        return -1;
    }

    int pin = relay_pins[entry->relay_number - 1];
    return fade_lamp(pin, entry->on_off, FADE_DURATION);
}

static int check_schedule(const ScheduleEntry *schedule, int num_entries,
                          int current_hour, int current_minute, int current_second) {
    for (int i = 0; i < num_entries; i++) {
        if (schedule[i].hour == current_hour &&
            schedule[i].minute == current_minute &&
            schedule[i].second == current_second) {
            return i;
        }
    }
    return -1;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    ScheduleEntry *schedule = NULL;
    int num_entries = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", relay_pins[i]);
            cleanup_gpio();
            return 1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", relay_pins[i]);
            cleanup_gpio();
            return 1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error setting PWM range on GPIO %d\n", relay_pins[i]);
            cleanup_gpio();
            return 1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error initializing PWM on GPIO %d\n", relay_pins[i]);
            cleanup_gpio();
            return 1;
        }
    }

    if (read_schedule(SCHEDULE_FILE, &schedule, &num_entries) != 0) {
        cleanup_gpio();
        return 1;
    }

    printf("Smart Home Lighting System started.\n");
    printf("Schedule loaded: %d entries.\n", num_entries);

    int last_applied_index = -1;

    while (program_running) {
        int current_hour, current_minute, current_second;
        if (get_current_time(&current_hour, &current_minute, &current_second) != 0) {
            sleep(1);
            continue;
        }

        int match_index = check_schedule(schedule, num_entries,
                                         current_hour, current_minute, current_second);

        if (match_index != -1 && match_index != last_applied_index) {
            if (apply_schedule_entry(&schedule[match_index]) == 0) {
                printf("Applied schedule entry: %02d:%02d:%02d, Relay %d, %s\n",
                       schedule[match_index].hour,
                       schedule[match_index].minute,
                       schedule[match_index].second,
                       schedule[match_index].relay_number,
                       schedule[match_index].on_off ? "ON" : "OFF");
                last_applied_index = match_index;
            } else {
                fprintf(stderr, "Failed to apply schedule entry.\n");
            }
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    free(schedule);
    printf("Smart Home Lighting System stopped.\n");
    return 0;
}

