#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  30.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    60000  /* 60 ms between measurements */
#define ECHO_TIMEOUT_US  30000  /* 30 ms max echo wait */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in centimetres using the HC-SR04.
 * Returns distance on success, or -1.0 on timeout / error.
 */
static float get_distance(void) {
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger pin low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger pin high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger pin low\n");
        return -1.0f;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_start = gpioTick();

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;

    /* Speed of sound ~343 m/s => 0.0343 cm/us */
    return (float)pulse_width * 0.0343f;
}

static int set_buzzer_frequency(int freq) {
    if (freq < 0) {
        fprintf(stderr, "Error: invalid frequency %d\n", freq);
        return -1;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, freq) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency %d\n", freq);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {  /* 50 % duty cycle */
        fprintf(stderr, "Error: failed to start PWM on buzzer\n");
        return -1;
    }
    return 0;
}

static void silence_buzzer(void) {
    gpioPWM(BUZZER_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);  /* 100 ms settle */

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        silence_buzzer();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = get_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: distance read failed, silencing buzzer\n");
            silence_buzzer();
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Clamp distance to valid range */
        if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
        if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

        /* Linear mapping: 2 cm -> 200 Hz, 30 cm -> 2000 Hz */
        float freq = MIN_FREQUENCY_HZ +
                     (distance - MIN_DISTANCE_CM) *
                     (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                     (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

        int freq_int = (int)(freq + 0.5f);
        if (freq_int < MIN_FREQUENCY_HZ) freq_int = MIN_FREQUENCY_HZ;
        if (freq_int > MAX_FREQUENCY_HZ) freq_int = MAX_FREQUENCY_HZ;

        if (set_buzzer_frequency(freq_int) < 0) {
            fprintf(stderr, "Warning: failed to set buzzer frequency\n");
        }

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, freq_int);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    silence_buzzer();
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

