#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, red) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on RED_PIN\n");
    if (gpioPWM(GREEN_PIN, green) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on GREEN_PIN\n");
    if (gpioPWM(BLUE_PIN, blue) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on BLUE_PIN\n");
}

static void proximity_alert(float proximity) {
    if (proximity < 0.0f) proximity = 0.0f;
    if (proximity > 1.0f) proximity = 1.0f;

    int red, green, blue;

    if (proximity < 0.33f) {
        red   = (int)(proximity * 3.0f * 255.0f);
        green = 0;
        blue  = (int)((1.0f - proximity) * 3.0f * 255.0f);
    } else if (proximity < 0.66f) {
        red   = (int)((1.0f - proximity) * 3.0f * 255.0f);
        green = (int)((proximity - 0.33f) * 3.0f * 255.0f);
        blue  = 0;
    } else {
        red   = 0;
        green = (int)((1.0f - proximity) * 3.0f * 255.0f);
        blue  = (int)((proximity - 0.66f) * 3.0f * 255.0f);
    }

    set_led_color(red, green, blue);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    set_led_color(0, 0, 0);

    while (running) {
        float proximity = 0.5f + 0.5f * sinf(time_time());
        proximity_alert(proximity);
        time_sleep(0.05);
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

