/*
 * Musical doorbell for Raspberry Pi 4 Model B
 * Library: pigpio
 *
 * Wiring:
 *   Button  -> GPIO17 (BCM), internal pull-up, active-low
 *   Piezo   -> GPIO18 (hardware PWM0)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o doorbell doorbell.c -lpigpio -lrt
 *   sudo ./doorbell
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define BUTTON_PIN      17
#define BUZZER_PIN      18
#define DEBOUNCE_US     50000   /* 50 ms */
#define PWM_DUTY        500000  /* 50% of 1,000,000 range */

/* Musical doorbell melody stored in flash-safe const memory */
static const unsigned int melody[] = {
    262, 294, 330, 349, 392, 440, 494, 523,
    262, 294, 330, 349, 392, 440, 494, 523
};
static const int melody_length = (int)(sizeof(melody) / sizeof(melody[0]));

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_play_melody = 0;
static volatile sig_atomic_t g_stop_melody = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Button ISR — only set flag, no blocking work here                   */
/* ------------------------------------------------------------------ */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 0) {                       /* falling edge = press */
        static uint32_t last_tick = 0;
        uint32_t elapsed = tick - last_tick; /* pigpio tick wraps every ~72 min */
        if (elapsed > DEBOUNCE_US) {
            last_tick = tick;
            g_play_melody = 1;
            g_stop_melody = 0;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Play the melody on the buzzer                                       */
/* ------------------------------------------------------------------ */
static void play_melody(void)
{
    for (int i = 0; i < melody_length && g_running; i++) {
        if (gpioHardwarePWM(BUZZER_PIN, melody[i], PWM_DUTY) != 0) {
            fprintf(stderr, "Warning: gpioHardwarePWM failed at index %d\n", i);
        }
        gpioDelay(100000);                 /* 100 ms per note */
        if (g_stop_melody) {
            gpioHardwarePWM(BUZZER_PIN, 0, 0);
            return;
        }
    }
    gpioHardwarePWM(BUZZER_PIN, 0, 0);     /* ensure buzzer off */
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with buzzer off */
    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM initial off failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ISR registration ---- */
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Musical doorbell ready. Press the button (GPIO17) to play.\n");
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        if (g_play_melody) {
            g_play_melody = 0;
            play_melody();
        }
        gpioDelay(10000);                   /* 10 ms idle sleep */
    }

    /* ---- graceful shutdown ---- */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);      /* ensure buzzer off */
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL); /* unregister ISR */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

