#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/poll.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define GPIO_PIN          17
#define LOG_FILE          "vibration_events.log"
#define WINDOW_SIZE       5
#define EARTHQUAKE_THRESHOLD 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *fp, const char *event_type, int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - %s - Value: %d\n", timestamp, event_type, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int check_earthquake(const int *window, int size)
{
    int high_count = 0;
    for (int i = 0; i < size; i++) {
        if (window[i] == 1)
            high_count++;
    }
    return (high_count >= EARTHQUAKE_THRESHOLD) ? 1 : 0;
}

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int poll_timeout_ms = 1000;
    int window[WINDOW_SIZE] = {0};
    int window_index = 0;
    int window_count = 0;
    int ret = EXIT_FAILURE;

    if (argc > 1) {
        char *endptr = NULL;
        errno = 0;
        long val = strtol(argv[1], &endptr, 10);
        if (errno != 0 || endptr == argv[1] || *endptr != '\0' || val < 0 || val > 2147483647L) {
            fprintf(stderr, "Invalid poll timeout: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
        poll_timeout_ms = (int)val;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

