#include <fcntl.h>
#include <sys/poll.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define GPIO_PIN          17
#define LOG_FILE          "vibration_events.log"
#define WINDOW_SIZE       5
#define EARTHQUAKE_THRESHOLD 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *fp, const char *event_type, int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - %s - Value: %d\n", timestamp, event_type, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int check_earthquake(const int *window, int size)
{
    int high_count = 0;
    for (int i = 0; i < size; i++) {
        if (window[i] == 1)
            high_count++;
    }
    return (high_count >= EARTHQUAKE_THRESHOLD) ? 1 : 0;
}

