        return -1;

    /* MR_REG_M: continuous-conversion mode */
    if (i2c_write_reg8(fd, LSM303_MAG_MR_REG_M, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw X/Y/Z magnetic-field data (6 bytes, little-endian).       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, LSM303_MAG_OUT_X_H_M, raw, sizeof(raw)) != 0)
        return -1;

    /* LSM303DLHC magnetometer data order: X_MSB, X_LSB, Z_MSB, Z_LSB, Y_MSB, Y_LSB */
    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *z = (int16_t)((raw[2] << 8) | raw[3]);
    *y = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           float *cal_x, float *cal_y, float *cal_z)
{
    *cal_x = (float)raw_x - X_OFFSET;
    *cal_y = (float)raw_y - Y_OFFSET;
    *cal_z = (float)raw_z - Z_OFFSET;
}

/* ------------------------------------------------------------------ */
static float calculate_heading(float cal_x, float cal_y)
{
    float heading = atan2f(cal_y, cal_x) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
static const char *map_heading_to_direction(float heading)
{
    if (heading < 22.5f)   return "N";
    if (heading < 67.5f)   return "NE";
    if (heading < 112.5f)  return "E";
    if (heading < 157.5f)  return "SE";
    if (heading < 202.5f)  return "S";
    if (heading < 247.5f)  return "SW";
    if (heading < 292.5f)  return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z,
                    float heading, const char *dir)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n",
                ts, cal_x, cal_y, cal_z, heading, dir) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the LSM303DLHC slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize magnetometer */
    if (init_magnetometer(g_i2c_fd) != 0) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file (append mode) */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
        fflush(g_csv);
    }

    printf("LSM303DLHC Magnetometer Logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "I2C read error; skipping sample.\n");
            sleep(SAMPLE_PERIOD_SEC);
            continue;
        }

        float cal_x, cal_y, cal_z;
        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);

        float heading = calculate_heading(cal_x, cal_y);
        const char *dir = map_heading_to_direction(heading);

        if (log_data(g_csv, cal_x, cal_y, cal_z, heading, dir) != 0) {
            fprintf(stderr, "CSV logging failed; continuing.\n");
        }

        printf("Heading: %.2f deg (%s)\n", heading, dir);

        sleep(SAMPLE_PERIOD_SEC);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

