#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_US 200000  /* 200 ms */
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_relay_state = 0;
static volatile uint32_t g_last_touch_tick = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (!localtime_r(&rawtime, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
            timestamp, state ? "ON" : "OFF");
    fclose(fp);
}

static void touch_isr(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 1) {
        return;  /* only act on rising edge (touch detected) */
    }

    uint32_t elapsed = tick - g_last_touch_tick;
    if (elapsed < DEBOUNCE_US) {
        return;  /* debounce: ignore touches within 200 ms */
    }
    g_last_touch_tick = tick;

    g_relay_state = !g_relay_state;
    if (gpioWrite(RELAY_PIN, g_relay_state) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN) failed\n");
        return;
    }

    log_relay_state(g_relay_state);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_isr) != 0) {
        fprintf(stderr, "gpioSetISRFunc(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO%d to toggle relay on GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed during shutdown\n");
    }

    log_relay_state(0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

