#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define RELAY_INTERVAL 1
#define SAMPLE_INTERVAL 10
#define LOG_FILE "irrigation_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            perror("gpiod_line_request_output");
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static void log_irrigation(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        perror("localtime_r");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_fp, "%s - Relay %d activated, Moisture: %d\n",
                timestamp, relay_number, moisture_level) < 0) {
        perror("fprintf");
    } else {
        fflush(log_fp);
    }
}

static void irrigate_relay(int relay_number, int moisture_level) {
    int idx = relay_number - 1;
    if (idx < 0 || idx >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return;
    }

    if (gpiod_line_set_value(relay_lines[idx], 0) < 0) {
        perror("gpiod_line_set_value (activate)");
        return;
    }

    log_irrigation(relay_number, moisture_level);

    for (int i = 0; i < IRRIGATION_DURATION && running; i++) {
        sleep(1);
    }

    if (gpiod_line_set_value(relay_lines[idx], 1) < 0) {
        perror("gpiod_line_set_value (deactivate)");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    srand((unsigned int)time(NULL));

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    while (running) {
        int moisture = read_moisture_sensor();

        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS && running && moisture < MOISTURE_THRESHOLD; i++) {
                irrigate_relay(i + 1, moisture);
                if (i < NUM_RELAYS - 1 && running) {
                    sleep(RELAY_INTERVAL);
                }
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

