/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 * Library : pigpio (C API)
 * Servos  : SG90 on GPIO17 (valve), GPIO18 (nozzle)
 *
 * Simulated soil-moisture readings (20, 40, 60, 80, 100) cycle every
 * second.  Below 50 %, valve opens to 90 degrees, nozzle sweeps through
 * 0, 45, 90, 135, 180 degrees at 2 s/step, holds 5 s, then closes to
 * 0 degrees.  Aborts on valve-open failure, warns on valve-close
 * failure, and logs nozzle-position errors.
 *
 * Build  : gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run    : sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / hardware constants ------------------------------------------ */
#define VALVE_PIN        17          /* GPIO17 — physical pin 11 */
#define NOZZLE_PIN       18          /* GPIO18 — physical pin 12 */

#define SERVO_MIN_US     500         /* SG90 safe lower  limit ( ~0°   ) */
#define SERVO_MAX_US     2500        /* SG90 safe upper  limit ( 180°  ) */
#define SERVO_MID_US     1500        /* SG90 midway pulse width        */

/* ---- Watering thresholds / timing ------------------------------------- */
#define MOISTURE_THRESHOLD  50       /* % — below this: water plant */
#define WATERING_HOLD_S     5        /* seconds to keep valve open */
#define NOZZLE_STEP_S       2        /* seconds per nozzle sweep step */
#define CYCLE_DELAY_S       5        /* seconds between cycles */
#define READ_DELAY_S        1        /* seconds between moisture reads */

/* ---- GPIO / pigpio constants ------------------------------------------- */
#define SERVO_RETRIES      3
#define SERVO_RETRY_DELAY  0.1       /* seconds between retries */

/* ---- Simulated moisture readings (20, 40, 60, 80, 100) ---------------- */
static const int moisture_levels[] = {20, 40, 60, 80, 100};
static int       moisture_index = 0;

/* ---- Volatile sig_atomic_t flags for graceful shutdown ------------------ */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------------ */
/* Retry wrapper for gpioServo().  Returns 0 on success, -1 on persistent
 * failure.                                                                 */
static int servo_set(unsigned pin, unsigned pulse_us)
{
    for (int attempt = 0; attempt < SERVO_RETRIES; ++attempt) {
        int rc = gpioServo(pin, pulse_us);
        if (rc == 0)
            return 0;
        fprintf(stderr,
                "[WARN] gpioServo(pin=%u, pulse=%u) failed (rc=%d), "
                "attempt %d/%d\n",
                pin, pulse_us, rc, attempt + 1, SERVO_RETRIES);
        if (attempt < SERVO_RETRIES - 1)
            time_sleep(SERVO_RETRY_DELAY);
    }
    return -1;
}

/* ------------------------------------------------------------------------ */
/* Map a 0–100 moisture percentage to a servo pulse width.                  */
static unsigned moisture_to_pulse(int moisture)
{
    if (moisture < 0)   moisture = 0;
    if (moisture > 100) moisture = 100;
    return (unsigned)((long)moisture * (SERVO_MAX_US - SERVO_MIN_US) / 100 +
                      SERVO_MIN_US);
}

/* ------------------------------------------------------------------------ */
/* Open the valve to 90 degrees.  Returns 0 on success, -1 on failure.       */
static int open_valve(void)
{
    if (servo_set(VALVE_PIN, SERVO_MAX_US) != 0) {
        fprintf(stderr, "[ERROR] Valve failed to open (pulse %u us)\n",
                SERVO_MAX_US);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
/* Close the valve to 0 degrees.  Returns 0 on success, -1 on warning.       */
static int close_valve(void)
{
    if (servo_set(VALVE_PIN, SERVO_MIN_US) != 0) {
        fprintf(stderr,
                "[WARN] Valve failed to close (pulse %u us) — continuing\n",
                SERVO_MIN_US);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
/* Sweep the nozzle through 0, 45, 90, 135, 180 degrees.                     */
static void sweep_nozzle(void)
{
    static const int angles[] = {0, 45, 90, 135, 180};
    const int n = (int)(sizeof(angles) / sizeof(angles[0]));

    for (int i = 0; i < n && g_running; ++i) {
        unsigned pulse = (unsigned)(angles[i] * 2000 / 180 + 500);
        if (servo_set(NOZZLE_PIN, pulse) != 0) {
            fprintf(stderr,
                    "[ERROR] Nozzle failed to reach %d° (pulse %u us)\n",
                    angles[i], pulse);
        }
        time_sleep(NOZZLE_STEP_S);
    }
}

/* ------------------------------------------------------------------------ */
/* Water the plant for WATERING_HOLD_S seconds.                              */
static void water_plant(void)
{
    printf("[INFO] Watering plant for %d s...\n", WATERING_HOLD_S);
    sweep_nozzle();
    time_sleep(WATERING_HOLD_S);
}

/* ------------------------------------------------------------------------ */
/* Advance to the next simulated moisture reading.                          */
static void advance_moisture(void)
{
    moisture_index = (moisture_index + 1) %
                     (int)(sizeof(moisture_levels) / sizeof(moisture_levels[0]));
}

/* ------------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers --------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio --------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Main loop ------------------------------------------------------ */
    while (g_running) {
        int moisture = moisture_levels[moisture_index];
        printf("[INFO] Moisture: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("[INFO] Moisture below threshold (%d%%) — watering\n",
                   MOISTURE_THRESHOLD);

            if (open_valve() != 0) {
                fprintf(stderr,
                        "[ERROR] Aborting watering cycle due to valve-open "
                        "failure\n");
            } else {
                water_plant();
                if (close_valve() != 0) {
                    fprintf(stderr,
                            "[WARN] Valve-close warning — continuing\n");
                }
            }
        } else {
            printf("[INFO] Moisture above threshold (%d%%) — skipping watering\n",
                   MOISTURE_THRESHOLD);
        }

        advance_moisture();

        /* Sleep in 1 s increments so signals are caught promptly. */
        for (int s = 0; s < CYCLE_DELAY_S && g_running; ++s)
            time_sleep(1);
    }

    /* ---- Graceful shutdown --------------------------------------------- */
    printf("\n[INFO] Shutting down — stopping servos and releasing pigpio\n");
    gpioServo(VALVE_PIN, 0);
    gpioServo(NOZZLE_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

