        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", pin);
        return -1;
    }
    return 0;
}

static int deenergize(void) {
    for (int i = 0; i < 4; i++) {
        if (safe_write(coil_pins[i], 0) != 0)
