/*
 * HC-SR04 ultrasonic distance logger for Raspberry Pi 4 Model B
 * Uses libgpiod v2.x API (gpiod.h) — no wiringPi.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5 V (Pin 2 or 4)
 *   HC-SR04 GND  -> GND (Pin 6)
 *   HC-SR04 TRIG -> BCM GPIO17 (Pin 11)
 *   HC-SR04 ECHO -> BCM GPIO18 (Pin 12) via voltage divider to 3.3 V
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04_log hcsr04_log.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define LOG_FILE         "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000   /* 50 ms */
#define MEASURE_CYCLE_MS 1000
#define MIN_GAP_MS       60      /* HC-SR04 guard time */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Busy-wait for a line to reach the requested value with a timeout.
 * Returns 0 on success, -1 on timeout or error.
 */
static int wait_for_value(struct gpiod_line *line, int value, uint64_t timeout_us)
{
    struct timespec deadline;
    clock_gettime(CLOCK_MONOTONIC, &deadline);
    deadline.tv_sec  += timeout_us / 1000000ULL;
    deadline.tv_nsec += (long)((timeout_us % 1000000ULL) * 1000ULL);
    if (deadline.tv_nsec >= 1000000000L) {
        deadline.tv_sec  += 1;
        deadline.tv_nsec -= 1000000000L;
    }

    for (;;) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (v == value)
            return 0;

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec > deadline.tv_sec ||
            (now.tv_sec == deadline.tv_sec && now.tv_nsec >= deadline.tv_nsec)) {
            return -1;  /* timeout */
        }
    }
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or error.
 */
static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    struct timespec ts = {0, 1000000};  /* 1 ms */
    nanosleep(&ts, NULL);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    ts.tv_nsec = TRIGGER_PULSE_US * 1000;
    nanosleep(&ts, NULL);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo rising edge */
    if (wait_for_value(echo, 1, ECHO_TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1.0f;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Wait for echo falling edge */
    if (wait_for_value(echo, 0, ECHO_TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1.0f;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    uint64_t elapsed_us =
        (uint64_t)(end.tv_sec - start.tv_sec) * 1000000ULL +
        (uint64_t)(end.tv_nsec - start.tv_nsec) / 1000ULL;

    /* distance = (time * speed_of_sound) / 2 */
    return (float)elapsed_us * 0.01715f;
}

static void log_distance(FILE *fp, float distance)
{
    if (distance < 0.0f) {
        fprintf(fp, "-1\n");
    } else {
        fprintf(fp, "%.2f\n", distance);
    }
    fflush(fp);
}

int main(void)
{
    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to the first chip if the main chip is unavailable */
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get trigger line (BCM %d): %s\n",
                TRIGGER_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line (BCM %d): %s\n",
                ECHO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n",
                strerror(errno));
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float distance = measure_distance(trig, echo);
        log_distance(fp, distance);

        /* Sleep for the remainder of the 1 s cycle, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            struct timespec ts = {0, 100000000};  /* 100 ms */
            nanosleep(&ts, NULL);
        }
    }

    /* Cleanup */
    gpiod_line_set_value(trig, 0);
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    fclose(fp);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

