/*
 * Proximity-based automated door system using VL53L1X ToF sensor.
 *
 * Hardware:
 *   - Raspberry Pi 4 Model B
 *   - VL53L1X on I2C bus 1, default address 0x29
 *   - Relay on BCM GPIO18 (simulates door opening)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o door_system door_system.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for I2C/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define RELAY_GPIO           18
#define DISTANCE_THRESHOLD   50          /* cm */
#define POLL_DELAY_US        100000      /* 100 ms */
#define MAX_CONSECUTIVE_ERR  10

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET          0x0000
#define VL53L1X_REG_SYSTEM_MODE_START   0x0080
#define VL53L1X_REG_INTERRUPT_STATUS    0x0044
#define VL53L1X_REG_RESULT_DISTANCE_MSB 0x0096
#define VL53L1X_REG_RESULT_DISTANCE_LSB 0x0097

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  write_reg16(int handle, uint16_t reg, uint8_t value);
static int  read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  init_vl53l1x(int handle);
static int  read_distance(int handle, uint16_t *distance_cm);
static void control_relay(int gpio, int state);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
/* Write a single byte to a 16-bit register address. */
static int write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* Read `len` bytes from a 16-bit register address. */
static int read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr_buf[2];
    addr_buf[0] = (char)(reg >> 8);
    addr_buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X) failed (write addr)\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%04X, len=%u) failed\n",
                reg, len);
        return -1;
    }
    return 0;
}

/* ----------------------------- VL53L1X init ------------------------------ */
static int init_vl53l1x(int handle)
{
    /* Software reset: write 0x00 to register 0x0000 */
    if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "[ERROR] VL53L1X software reset failed (sensor absent or bus error)\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Start continuous ranging: write 0x01 to register 0x0080 */
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "[ERROR] VL53L1X start continuous ranging failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement to be ready */

    return 0;
}

/* ----------------------------- Read distance ----------------------------- */
static int read_distance(int handle, uint16_t *distance_cm)
{
    uint8_t status = 0;
    uint8_t msb = 0, lsb = 0;

    /* Check interrupt status: bit 0 = data ready */
    if (read_reg16(handle, VL53L1X_REG_INTERRUPT_STATUS, &status, 1) != 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data yet — not an error, just skip this cycle */
        return 1; /* not an error, just no data */
    }

    /* Read 16-bit distance: MSB from 0x0096, LSB from 0x0097 */
    if (read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE_MSB, &msb, 1) != 0)
        return -1;
    if (read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE_LSB, &lsb, 1) != 0)
        return -1;

    *distance_cm = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* ----------------------------- Relay control ----------------------------- */
static void control_relay(int gpio, int state)
{
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, %d) failed\n", gpio, state);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    /* Ensure relay is OFF before terminating pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X default address 0x29 */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output and start with relay OFF */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_relay(RELAY_GPIO, 0);

    /* Initialize VL53L1X sensor */
    if (init_vl53l1x(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Automated door system started. Press Ctrl+C to exit.\n");
    printf("Threshold: %d cm | Relay GPIO: %d\n", DISTANCE_THRESHOLD, RELAY_GPIO);

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t distance = 0;
        int rc = read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            consecutive_errors = 0;
            printf("Distance: %u cm\n", distance);

            if (distance <= DISTANCE_THRESHOLD) {
                control_relay(RELAY_GPIO, 1);
                printf("Door opened (distance <= %d cm)\n", DISTANCE_THRESHOLD);
            } else {
                control_relay(RELAY_GPIO, 0);
            }
        } else if (rc < 0) {
            consecutive_errors++;
            fprintf(stderr, "[ERROR] read_distance failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                fprintf(stderr, "[FATAL] Too many consecutive I2C errors, aborting.\n");
                break;
            }
        }
        /* rc == 1 means no new data — just skip this cycle */

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

