/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Uses Linux i2c-dev ioctl interface (no libgpiod or wiringPi).
 *
 * Wiring:
 *   MPU-6050 VCC -> 3.3V (Pin 1)
 *   MPU-6050 GND -> GND  (Pin 9)
 *   MPU-6050 SCL -> GPIO3 / SCL (Pin 5)
 *   MPU-6050 SDA -> GPIO2 / SDA (Pin 3)
 *
 * Build: gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

/* MPU-6050 Registers */
#define PWR_MGMT_1     0x6B
#define GYRO_CONFIG    0x1B
#define GYRO_XOUT_H    0x43

/* Sensitivity scale factor for ±250 dps range (LSB/dps) */
#define GYRO_SENSITIVITY 131.0f

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes starting from an 8-bit register */
static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg ptr 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read the data bytes */
    ssize_t ret = read(fd, buf, len);
    if (ret != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, ret, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* 100 ms settle time after waking */

    /* Set gyroscope full-scale range to ±250 dps */
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_regs(fd, GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a register read to confirm sensor presence */
    uint8_t probe;
    if (i2c_read_regs(g_fd, PWR_MGMT_1, &probe, 1) < 0) {
        fprintf(stderr, "MPU-6050 not detected at address 0x%02X on %s\n",
                MPU6050_ADDR, I2C_BUS);
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyroscope data (Ctrl+C to exit)...\n");

    while (g_running) {
        float x, y, z;
        if (read_gyro_data(g_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyro read error, continuing...\n");
            usleep(100000);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%ld.%09ld] Gyro X: %7.2f dps, Y: %7.2f dps, Z: %7.2f dps\n",
               (long)ts.tv_sec, ts.tv_nsec, x, y, z);

        usleep(100000); /* 100 ms */
    }

    printf("\nExiting gracefully...\n");
    if (g_fd >= 0)
        close(g_fd);

    return EXIT_SUCCESS;
}

