    /* Read the data bytes */
    ssize_t ret = read(fd, buf, len);
    if (ret != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, ret, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* 100 ms settle time after waking */

    /* Set gyroscope full-scale range to ±250 dps */
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_regs(fd, GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a register read to confirm sensor presence */
    uint8_t probe;
    if (i2c_read_regs(g_fd, PWR_MGMT_1, &probe, 1) < 0) {
        fprintf(stderr, "MPU-6050 not detected at address 0x%02X on %s\n",
                MPU6050_ADDR, I2C_BUS);
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyroscope data (Ctrl+C to exit)...\n");

    while (g_running) {
        float x, y, z;
        if (read_gyro_data(g_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyro read error, continuing...\n");
            usleep(100000);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%ld.%09ld] Gyro X: %7.2f dps, Y: %7.2f dps, Z: %7.2f dps\n",
               (long)ts.tv_sec, ts.tv_nsec, x, y, z);

        usleep(100000); /* 100 ms */
    }

    printf("\nExiting gracefully...\n");
    if (g_fd >= 0)
        close(g_fd);

    return EXIT_SUCCESS;
}

