/*
 * Automated Plant Watering System - Raspberry Pi 4 Model B
 * Uses libgpiod v1 API (modern GPIO character-device interface).
 *
 * Relays (active-low):
 *   Relay 1 -> BCM GPIO17 (physical pin 11)
 *   Relay 2 -> BCM GPIO18 (physical pin 12)
 *   Relay 3 -> BCM GPIO27 (physical pin 13)
 *   Relay 4 -> BCM GPIO22 (physical pin 15)
 *
 * Compile: gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define NUM_RELAYS       4
#define WATERING_DURATION 5          /* seconds per relay */
#define CYCLE_INTERVAL   86400       /* seconds between full cycles */
#define POLL_INTERVAL    60          /* main-loop poll interval */
#define LOG_FILE         "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int log_watering_event(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Watering cycle started\n", timestamp) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int lines_requested = 0;
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* ---- Install signal handlers ---------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    /* ---- Get and request all four relay lines as outputs (inactive) --- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        /* Request output, default value LOW (relay inactive) */
        if (gpiod_line_request_output(lines[i], "watering-system", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_requested++;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        if (log_watering_event() != 0) {
            fprintf(stderr, "Warning: failed to log watering event.\n");
        }

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            /* Activate relay (HIGH = active, active-low semantics) */
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, HIGH) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("Relay %d (BCM %u) activated for %d seconds.\n",
                   i + 1, relay_pins[i], WATERING_DURATION);

            /* Sleep in 1-second increments so signals are caught promptly */
            for (int s = 0; s < WATERING_DURATION && g_running; s++) {
                sleep(1);
            }

            /* Deactivate relay (LOW = inactive) */
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, LOW) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("Relay %d (BCM %u) deactivated.\n", i + 1, relay_pins[i]);
        }

        /* Wait for next full cycle (interruptible by signals) */
        for (int s = 0; s < CYCLE_INTERVAL && g_running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release all lines and close chip -------------------------- */
    for (int i = 0; i < lines_requested; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Plant watering system stopped.\n");
    return ret;
}

