#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION_SECONDS 1800
#define STEP_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to set initial PWM duty cycle on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    log_event("GPIO initialized successfully");
    return 0;
}

static void cleanup_gpio(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    log_event("GPIO cleaned up");
}

static void simulate_sunrise(int duration_seconds) {
    int steps = duration_seconds;
    int duty_increment = PWM_RANGE / steps;
    int current_duty = 0;

    for (int i = 0; i < steps && running; i++) {
        int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
        for (size_t j = 0; j < sizeof(pins) / sizeof(pins[0]); j++) {
            if (gpioPWM(pins[j], current_duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[j]);
                log_event("PWM write error during sunrise simulation");
                return;
            }
        }
        current_duty += duty_increment;
        if (current_duty > PWM_RANGE) {
            current_duty = PWM_RANGE;
        }
        usleep(STEP_DELAY_US);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        return 1;
    }

    log_event("Sunrise simulation started");
    simulate_sunrise(SUNRISE_DURATION_SECONDS);

    if (!running) {
        log_event("Sunrise simulation interrupted by signal");
    } else {
        log_event("Sunrise simulation complete");
    }

    cleanup_gpio();
    return 0;
}

