 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (pin 3)
 *   MPU-6050 SCL -> GPIO3 (pin 5)
 *   MPU-6050 VCC -> 3.3 V
 *   MPU-6050 GND -> GND
 *   LED anode   -> GPIO17 (pin 11) via 330 ohm resistor -> GND
 *
 * Build:  gcc -O2 -Wall -o gyro_led gyro_led.c -lpigpio -lrt
 * Run:    sudo ./gyro_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_SMPLRT_DIV  0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

/* ±250 deg/s full-scale range: sensitivity = 131 LSB/deg/s */
#define GYRO_SENSITIVITY    131.0f
#define GYRO_THRESHOLD_DEG  250.0f
#define LED_GPIO            17
#define I2C_BUS             1
#define BUFFER_SIZE         100
#define SAMPLE_PERIOD_US    50000   /* 20 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* ---- Data structures ---- */
typedef struct {
    float   x;
    float   y;
    float   z;
    uint32_t timestamp_us;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Prototypes ---- */
static int  mpu6050_init(int handle);
static int  mpu6050_read_gyro(int handle, float *x, float *y, float *z);
static void buffer_add(circular_buffer_t *buf, float x, float y, float z,
                        uint32_t ts);
static void buffer_print(const circular_buffer_t *buf);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    circular_buffer_t gyro_buffer = {0};
    float gyro_x, gyro_y, gyro_z;
    uint32_t last_sample_us = 0;
    int reinit_attempts = 0;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (mpu6050_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- Signals ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 gyroscope reading started (20 Hz). Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint32_t now = gpioTick();
        if (now - last_sample_us < SAMPLE_PERIOD_US) {
            gpioDelay(1000);  /* 1 ms sleep */
            continue;
        }
        last_sample_us = now;

        if (mpu6050_read_gyro(g_i2c_handle, &gyro_x, &gyro_y, &gyro_z) != 0) {
            reinit_attempts++;
            fprintf(stderr, "Warning: read failed (attempt %d/%d).\n",
                    reinit_attempts, MAX_REINIT_ATTEMPTS);
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Error: max re-init attempts reached. Exiting.\n");
                break;
            }
            /* Attempt I2C re-open */
            i2cClose(g_i2c_handle);
            g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: i2cOpen re-init failed (code %d).\n",
                        g_i2c_handle);
                break;
            }
            if (mpu6050_init(g_i2c_handle) != 0) {
                fprintf(stderr, "Error: MPU-6050 re-init failed.\n");
                break;
            }
            continue;
        }
        reinit_attempts = 0;

        buffer_add(&gyro_buffer, gyro_x, gyro_y, gyro_z, now);

        /* LED threshold: any axis exceeds 250 deg/s */
        if (fabsf(gyro_x) > GYRO_THRESHOLD_DEG ||
            fabsf(gyro_y) > GYRO_THRESHOLD_DEG ||
            fabsf(gyro_z) > GYRO_THRESHOLD_DEG) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static int mpu6050_init(int handle)
{
    /* Wake up: clear SLEEP bit (bit 6) in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: writing PWR_MGMT_1 failed.\n");
        return -1;
    }
    gpioDelay(100000);  /* 100 ms settle */

    /* Sample rate divider = 9 -> 1 kHz / (1 + 9) = 100 Hz internal */
    if (i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 0x09) < 0) {
        fprintf(stderr, "Error: writing SMPLRT_DIV failed.\n");
        return -1;
    }

    /* Gyro full-scale range: ±250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: writing GYRO_CONFIG failed.\n");
        return -1;
    }

    /* Verify device identity */
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: reading WHO_AM_I failed.\n");
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6050_read_gyro(int handle, float *x, float *y, float *z)
{
    char raw[6];

    if (i2cReadI2CBlockData(handle, MPU6050_GYRO_XOUT_H, raw, 6) != 6) {
        fprintf(stderr, "Error: reading gyro data block failed.\n");
        return -1;
    }

    int16_t x_raw = (int16_t)((raw[0] << 8) | (uint8_t)raw[1]);
    int16_t y_raw = (int16_t)((raw[2] << 8) | (uint8_t)raw[3]);
    int16_t z_raw = (int16_t)((raw[4] << 8) | (uint8_t)raw[5]);

    *x = (float)x_raw / GYRO_SENSITIVITY;
    *y = (float)y_raw / GYRO_SENSITIVITY;
    *z = (float)z_raw / GYRO_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
static void buffer_add(circular_buffer_t *buf, float x, float y, float z,
                        uint32_t ts)
{
    buf->data[buf->head].x = x;
    buf->data[buf->head].y = y;
    buf->data[buf->head].z = z;
    buf->data[buf->head].timestamp_us = ts;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

/* ------------------------------------------------------------------ */
static void buffer_print(const circular_buffer_t *buf)
{
    printf("\n--- Circular Buffer Contents (%d entries) ---\n", buf->count);
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%3d] ts=%u  x=%+.2f  y=%+.2f  z=%+.2f\n",
               i, buf->data[idx].timestamp_us,
               buf->data[idx].x, buf->data[idx].y, buf->data[idx].z);
    }
    printf("----------------------------------------------\n");
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

