#define SPI_BITS        8
#define SPI_MODE        0
#define GYRO_SCALE      131.0f
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_DELAY_MS 10
#define MAX_RETRIES     3

#define MPU9250_GYRO_XOUT_H 0x43
#define MPU9250_GYRO_XOUT_L 0x44
#define MPU9250_GYRO_YOUT_H 0x45
#define MPU9250_GYRO_YOUT_L 0x46
#define MPU9250_GYRO_ZOUT_H 0x47
#define MPU9250_GYRO_ZOUT_L 0x48

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t tx[7] = {0x80 | MPU9250_GYRO_XOUT_H, 0, 0, 0, 0, 0, 0};
    uint8_t rx[7] = {0};
    int16_t raw_x, raw_y, raw_z;

    if (spi_transfer(tx, rx, sizeof(tx)) < 0) {
        return -1;
    }

    raw_x = (int16_t)((rx[1] << 8) | rx[2]);
    raw_y = (int16_t)((rx[3] << 8) | rx[4]);
    raw_z = (int16_t)((rx[5] << 8) | rx[6]);

    *x = (float)raw_x / GYRO_SCALE;
