#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 3900000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_ZOUT_H 0x47

#define GYRO_SENSITIVITY 131.0f
#define GYRO_THRESHOLD 200.0f

#define CS_GPIO_LINE 8
#define LED_GPIO_LINE 17

#define BUFFER_SIZE 64

typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;
static circular_buffer_t gyro_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Failed to get CS GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu6050_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, "mpu6050_led", 0) < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    return 0;
}

static int mpu6050_write_reg(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };
    return spi_transfer(tx, rx, 2);
}

static int mpu6050_read_reg(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_transfer(tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int mpu6050_read_gyro(float *x, float *y, float *z) {
    uint8_t tx[7] = { 0 };
    uint8_t rx[7] = { 0 };

    tx[0] = (uint8_t)(MPU6050_GYRO_XOUT_H | 0x80);
    if (spi_transfer(tx, rx, 7) < 0) return -1;

    int16_t raw_x = (int16_t)((rx[1] << 8) | rx[2]);
    int16_t raw_y = (int16_t)((rx[3] << 8) | rx[4]);
    int16_t raw_z = (int16_t)((rx[5] << 8) | rx[6]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, gyro_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void buffer_print_csv(const circular_buffer_t *buf) {
    printf("Timestamp,X,Y,Z\n");
    int start = (buf->count == BUFFER_SIZE) ? buf->head : 0;
    for (int i = 0; i < buf->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("%ld,%.2f,%.2f,%.2f\n",
               (long)buf->data[idx].timestamp,
               buf->data[idx].x,
               buf->data[idx].y,
               buf->data[idx].z);
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        close(spi_fd);
        return 1;
    }

    if (mpu6050_write_reg(MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050.\n");
        cleanup();
        return 1;
    }
    usleep(100000);

    buffer_init(&gyro_buffer);

    printf("MPU-6050 stability monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (mpu6050_read_gyro(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data.\n");
            usleep(100000);
            continue;
        }

        if (x == 0.0f && y == 0.0f && z == 0.0f) {
            fprintf(stderr, "Invalid gyroscope data (zero).\n");
            usleep(100000);
            continue;
        }

        gyro_data_t data;
        data.timestamp = time(NULL);
        data.x = x;
        data.y = y;
        data.z = z;
        buffer_add(&gyro_buffer, data);

        if (fabsf(x) > GYRO_THRESHOLD || fabsf(y) > GYRO_THRESHOLD || fabsf(z) > GYRO_THRESHOLD) {
            printf("Threshold exceeded! X=%.2f Y=%.2f Z=%.2f\n", x, y, z);
            while (running) {
                if (gpiod_line_set_value(led_line, 1) < 0) break;
                usleep(500000);
                if (!running) break;
                if (gpiod_line_set_value(led_line, 0) < 0) break;
                usleep(500000);
            }
        }

        usleep(10000);
    }

    printf("\nExiting...\n");
    buffer_print_csv(&gyro_buffer);
    cleanup();
    return 0;
}

