#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt threshold (degrees) */
#define TILT_THRESHOLD 45.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an MPU-6050 register                         */
/* ------------------------------------------------------------------ */
static int mpu6050_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from two consecutive registers       */
/* ------------------------------------------------------------------ */
static int mpu6050_read_word(int handle, uint8_t reg_high, int16_t *out)
{
    int hi = i2cReadByteData(handle, reg_high);
    if (hi < 0) {
        fprintf(stderr, "Error reading high byte of register 0x%02X (rc=%d)\n",
                reg_high, hi);
        return -1;
    }
    int lo = i2cReadByteData(handle, reg_high + 1);
    if (lo < 0) {
        fprintf(stderr, "Error reading low byte of register 0x%02X (rc=%d)\n",
                reg_high + 1, lo);
        return -1;
    }
    *out = (int16_t)((hi << 8) | (lo & 0xFF));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise MPU-6050: wake, set ±2g accelerometer range              */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int handle)
{
    /* Wake the device: clear SLEEP bit in PWR_MGMT_1 */
    if (mpu6050_write_reg(handle, PWR_MGMT_1, 0x00) < 0)
        return -1;

    /* Allow time for oscillator to stabilise */
    gpioDelay(100000); /* 100 ms */

    /* Set accelerometer full-scale range to ±2g (AFS_SEL = 0) */
    if (mpu6050_write_reg(handle, ACCEL_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data and compute roll/pitch                     */
/* ------------------------------------------------------------------ */
static int read_tilt(int handle, double *roll, double *pitch)
{
    int16_t raw_x, raw_y, raw_z;

    if (mpu6050_read_word(handle, ACCEL_XOUT_H, &raw_x) < 0)
        return -1;
    if (mpu6050_read_word(handle, ACCEL_YOUT_H, &raw_y) < 0)
        return -1;
    if (mpu6050_read_word(handle, ACCEL_ZOUT_H, &raw_z) < 0)
        return -1;

    /* Convert raw values to g-force (sensitivity ±2g → 16384 LSB/g) */
    double x = (double)raw_x / 16384.0;
    double y = (double)raw_y / 16384.0;
    double z = (double)raw_z / 16384.0;

    /* Tilt angles in degrees */
    *roll  = atan2(y, z) * 180.0 / M_PI;
    *pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to tilt_log.txt                                       */
/* ------------------------------------------------------------------ */
static void log_data(double roll, double pitch)
{
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening tilt_log.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    } else {
        fprintf(fp, "<time-error>,%.2f,%.2f\n", roll, pitch);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 at MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (rc=%d)\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (mpu6050_init(g_i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 tilt monitor running. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        double roll, pitch;

        if (read_tilt(g_i2c_handle, &roll, &pitch) == 0) {
            printf("Roll: %7.2f  Pitch: %7.2f\n", roll, pitch);
            log_data(roll, pitch);

            int tilt_exceeded = (fabs(roll) > TILT_THRESHOLD) ||
                                (fabs(pitch) > TILT_THRESHOLD);
            gpioWrite(LED_PIN, tilt_exceeded ? 1 : 0);
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

