#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SI1145_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LED 17
#define AMBIENT_REG 0x20
#define PROXIMITY_REG 0x22
#define PROXIMITY_THRESHOLD 100
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %s\n", reg, attempt + 1, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d): %s\n", reg, attempt + 1, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t ambient, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient, proximity) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LED, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "si1145-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LED, strerror(errno));
        gpiod_line_release(led_line);
