        close(i2c_fd);
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open biometric_log.txt: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("Si1145 biometric sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t ambient = 0, proximity = 0;
        if (i2c_read_reg16(i2c_fd, AMBIENT_REG, &ambient) == 0 &&
            i2c_read_reg16(i2c_fd, PROXIMITY_REG, &proximity) == 0) {
            if (log_data(log_file, ambient, proximity) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
            int led_state = (proximity > PROXIMITY_THRESHOLD) ? 1 : 0;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                fprintf(stderr, "Failed to set LED GPIO value: %s\n", strerror(errno));
