#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 SPI configuration */
#define SPI_CHANNEL    0          /* CE0 / GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

/* ADXRS290 register addresses (read bit = 0x80) */
#define REG_XGYRO_OUT  0x82
#define REG_YGYRO_OUT  0x84

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY    200.0f

/* Sampling */
#define SAMPLE_DELAY_US 10000     /* 10 ms -> ~100 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x;
    int16_t y;
} gyro_data_t;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit two's-complement register from the ADXRS290.
 * SPI transfer: send [reg | 0x80, 0x00], capture the second byte.
 * Returns 0 on success, -1 on SPI error.
 */
static int read_gyro_register(int handle, uint8_t reg, int16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro_data(int handle, gyro_data_t *data)
{
    if (read_gyro_register(handle, REG_XGYRO_OUT, &data->x) != 0)
        return -1;
    if (read_gyro_register(handle, REG_YGYRO_OUT, &data->y) != 0)
        return -1;
    return 0;
}

static int log_data(FILE *fp, const gyro_data_t *data)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    if (fprintf(fp, "%.6f,%d,%d\n", timestamp, data->x, data->y) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static int reinit_spi(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioDelay(100000); /* 100 ms settle */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_data.csv", "w");
    if (log_file == NULL) {
        perror("fopen gyro_data.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "timestamp,X_rate,Y_rate\n") < 0) {
        perror("fprintf header");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    int reinit_attempts = 0;

    while (!terminate) {
        gyro_data_t gyro_data;

        if (read_gyro_data(spi_handle, &gyro_data) != 0) {
            fprintf(stderr, "Read error, reinitialising SPI...\n");
            if (reinit_spi() != 0) {
                reinit_attempts++;
                if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Max reinit attempts reached, exiting.\n");
                    break;
                }
                gpioDelay(1000000); /* 1 s backoff */
                continue;
            }
            reinit_attempts = 0;
            continue;
        }

        if (log_data(log_file, &gyro_data) != 0) {
            fprintf(stderr, "Logging error, exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

