        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set alert pin HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set alert pin LOW\n");
    }
}

static void seismic_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)userdata;
    static uint32_t last_tick = 0;
    static int last_level = 0;
    static int both_high = 0;
    static uint32_t high_start_tick = 0;

    if (level == 1) {
        if (last_level == 0) {
            high_start_tick = tick;
        }
    } else if (level == 0) {
        if (last_level == 1) {
            if (both_high) {
                both_high = 0;
                uint32_t elapsed = tick - high_start_tick;
                if (elapsed >= (uint32_t)(SEISMIC_THRESHOLD_MS * 1000)) {
                    log_event("Seismic event detected!");
                    trigger_alert();
                }
            }
        }
    }
    last_level = level;
    last_tick = tick;

    if (level == 1) {
        if (gpio == SENSOR_1_PIN || gpio == SENSOR_2_PIN) {
            both_high = 1;
        }
    } else if (level == 0) {
        if (gpio == SENSOR_1_PIN || gpio == SENSOR_2_PIN) {
            both_high = 0;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise alert pin LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, seismic_callback, NULL) < 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, seismic_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

