#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

/* ADXRS290 register addresses (8-bit, MSB=0 for write, MSB=1 for read) */
#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

/* SPI configuration */
#define SPI_CHANNEL 0          /* CE0 on GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */

/* GPIO pins */
#define LED_PIN 17

/* Threshold for angular velocity (degrees per second) */
#define THRESHOLD 20.0

/* Sensitivity: 200 LSB per degree per second */
#define SENSITIVITY 200.0

/* Circular buffer capacity */
#define BUFFER_SIZE 100

/* Structure for gyroscope data */
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

/* Global variables */
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int spi_read_register(int handle, uint8_t reg, uint8_t *value);
static int read_gyro_data(int handle, float *angular_velocity);
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Read a single byte from an ADXRS290 register.
 * Returns 0 on success, -1 on error.
 */
static int spi_read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80;  /* Set MSB for read */
    tx_buf[1] = 0x00;        /* Dummy byte to clock out data */

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

/*
 * Read angular velocity from the ADXRS290.
 * Returns 0 on success, -1 on error.
 */
static int read_gyro_data(int handle, float *angular_velocity) {
    uint8_t rate_xl, rate_xh;
    int16_t raw_rate;

    if (spi_read_register(handle, ADXRS290_REG_RATE_XL, &rate_xl) != 0) {
        return -1;
    }
    if (spi_read_register(handle, ADXRS290_REG_RATE_XH, &rate_xh) != 0) {
        return -1;
    }

    raw_rate = (int16_t)((rate_xh << 8) | rate_xl);
    *angular_velocity = (float)raw_rate / SENSITIVITY;
    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

int main(void) {
    float angular_velocity;
    gyro_data_t gyro_data;
    struct timespec ts;
    bool led_on = false;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Initialize circular buffer mutex */
    if (pthread_mutex_init(&gyro_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (running) {
        if (read_gyro_data(spi_handle, &angular_velocity) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
                gyro_data.timestamp = ts;
                gyro_data.angular_velocity = angular_velocity;
                add_to_buffer(&gyro_buffer, gyro_data);

                if (fabsf(angular_velocity) > THRESHOLD) {
                    if (!led_on) {
                        gpioWrite(LED_PIN, 1);
                        led_on = true;
                    }
                } else {
                    if (led_on) {
                        gpioWrite(LED_PIN, 0);
                        led_on = false;
                    }
                }

                printf("Angular Velocity: %.2f deg/s\n", angular_velocity);
            } else {
                perror("clock_gettime");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Cleanup */
    cleanup();
    return EXIT_SUCCESS;
}

