#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

#define PWM_RANGE 255
#define PWM_FREQ 100

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static int safe_gpio_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_gpio_pwm(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int safe_gpio_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pwm_range(unsigned gpio, unsigned range) {
    if (gpioSetPWMrange(gpio, range) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", gpio, range);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pwm_frequency(unsigned gpio, unsigned freq) {
    if (gpioSetPWMfrequency(gpio, freq) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", gpio, freq);
        return -1;
    }
    return 0;
}

static int initialize_lamp(unsigned gpio) {
    if (safe_gpio_set_mode(gpio, PI_OUTPUT) != 0) return -1;
    if (safe_gpio_set_pwm_range(gpio, PWM_RANGE) != 0) return -1;
    if (safe_gpio_set_pwm_frequency(gpio, PWM_FREQ) != 0) return -1;
    if (safe_gpio_pwm(gpio, 0) != 0) return -1;
    return 0;
}

static int fade_lamp(unsigned gpio, unsigned duration_sec) {
    if (duration_sec < 1 || duration_sec > 3600) {
        fprintf(stderr, "Error: duration %u out of range (1-3600)\n", duration_sec);
        return -1;
    }

    unsigned steps = PWM_RANGE;
    unsigned step_delay_us = (unsigned)((double)duration_sec * 1000000.0 / (double)steps);

    printf("Fading GPIO%u to 0%% over %u seconds...\n", gpio, duration_sec);
    fflush(stdout);

    for (unsigned i = 0; i <= steps && !g_terminate; i++) {
        unsigned duty = PWM_RANGE - i;
        if (safe_gpio_pwm(gpio, duty) != 0) return -1;
        gpioDelay(step_delay_us);
    }

    if (g_terminate) {
        safe_gpio_pwm(gpio, 0);
        return -1;
    }

    printf("GPIO%u faded to 0%%.\n", gpio);
    fflush(stdout);
    return 0;
}

static void cleanup_all(void) {
    safe_gpio_pwm(LAMP1_GPIO, 0);
    safe_gpio_pwm(LAMP2_GPIO, 0);
    safe_gpio_pwm(LAMP3_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: duration must be an integer between 1 and 3600\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        cleanup_all();
        return EXIT_FAILURE;
    }

    if (initialize_lamp(LAMP1_GPIO) != 0 ||
        initialize_lamp(LAMP2_GPIO) != 0 ||
        initialize_lamp(LAMP3_GPIO) != 0) {
        cleanup_all();
        return EXIT_FAILURE;
    }

    printf("Smart sunset simulator started. Fade duration: %ld seconds.\n", duration);
    printf("Lamps: GPIO%d, GPIO%d, GPIO%d\n", LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO);
    printf("Press Ctrl+C to stop prematurely.\n");
    fflush(stdout);

    int rc = 0;
    if (fade_lamp(LAMP1_GPIO, (unsigned)duration) != 0) rc = EXIT_FAILURE;
    if (rc == 0 && !g_terminate) {
        if (fade_lamp(LAMP2_GPIO, (unsigned)duration) != 0) rc = EXIT_FAILURE;
    }
    if (rc == 0 && !g_terminate) {
        if (fade_lamp(LAMP3_GPIO, (unsigned)duration) != 0) rc = EXIT_FAILURE;
    }

    if (g_terminate) {
        printf("\nSignal received. Shutting down gracefully...\n");
        fflush(stdout);
        rc = EXIT_FAILURE;
    } else {
        printf("Sunset simulation complete. All lamps off.\n");
        fflush(stdout);
    }

    cleanup_all();
    return rc;
}

