        if (!running) break;

        /* Green */
        if (gpiod_line_set_value(lines[0], 1) < 0) {
            perror("gpiod_line_set_value RED");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[1], 1) < 0) {
            perror("gpiod_line_set_value YELLOW");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[2], 0) < 0) {
            perror("gpiod_line_set_value GREEN");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[3], 1) < 0) {
            perror("gpiod_line_set_value BLUE");
            goto cleanup;
        }
        printf("Green\n");
        fflush(stdout);
        for (int i = 0; i < GREEN_DURATION && running; i++) {
            sleep(1);
        }
        if (!running) break;

        /* Yellow */
        if (gpiod_line_set_value(lines[0], 1) < 0) {
            perror("gpiod_line_set_value RED");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[1], 0) < 0) {
            perror("gpiod_line_set_value YELLOW");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[2], 1) < 0) {
            perror("gpiod_line_set_value GREEN");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[3], 1) < 0) {
            perror("gpiod_line_set_value BLUE");
            goto cleanup;
        }
        printf("Yellow\n");
        fflush(stdout);
        for (int i = 0; i < YELLOW_DURATION && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

