#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_MS 100
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X val=0x%02X rc=%d", reg, value, rc);
        log_message(msg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(0x80, 0x63) < 0) return -1;
    gpioDelay(10000);
    if (mpr121_write_reg(0x5E, 0x00) < 0) return -1;
    if (mpr121_write_reg(0x5D, 0x01) < 0) return -1;
    if (mpr121_write_reg(0x41, TOUCH_THRESHOLD) < 0) return -1;
    if (mpr121_write_reg(0x42, RELEASE_THRESHOLD) < 0) return -1;
    if (mpr121_write_reg(0x5B, 0x21) < 0) return -1;
    if (mpr121_write_reg(0x5C, 0x0D) < 0) return -1;
    if (mpr121_write_reg(0x5E, 0x0D) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (rc != 2) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: rc=%d", rc);
        log_message(msg);
        return -1;
    }
    *status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "i2cOpen failed: handle=%d", i2c_handle);
        log_message(msg);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialisation failed");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started.");

    int relay_state = 0;
    uint16_t last_touch = 0;
    uint16_t last_debounced = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t electrode0 = touch_status & 0x0001;

        if (electrode0 && !last_touch) {
            gpioDelay(DEBOUNCE_MS * 1000);
            if (read_touch_status(&touch_status) == 0 && (touch_status & 0x0001)) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                char msg[128];
                snprintf(msg, sizeof(msg), "Relay toggled to %d", relay_state);
                log_message(msg);
            }
        }

        last_touch = touch_status;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

