#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

/* L298N motor A control pins */
#define MOTOR_A_FORWARD  17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE   24

/* L298N motor B control pins */
#define MOTOR_B_FORWARD  22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE   25

/* PID gains */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Threshold for obstacle avoidance (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* Control loop period (ms) */
#define LOOP_PERIOD_MS 50

/* Global state */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */

static void motor_set_speed(int forward_pin, int backward_pin, int enable_pin, int speed)
{
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(enable_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, 0);
    }
}

static void motor_stop(int forward_pin, int backward_pin, int enable_pin)
{
    gpioWrite(forward_pin, 0);
    gpioWrite(backward_pin, 0);
    gpioPWM(enable_pin, 0);
}

/* ------------------------------------------------------------------ */
/* PID controller                                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    double kp, ki, kd;
    double integral;
    double prev_error;
} PIDController;

static void pid_init(PIDController *pid, double kp, double ki, double kd)
{
    pid->kp       = kp;
    pid->ki       = ki;
    pid->kd       = kd;
    pid->integral = 0.0;
    pid->prev_error = 0.0;
}

static double pid_compute(PIDController *pid, double error, double dt)
{
    pid->integral += error * dt;

    /* Anti-windup clamp */
    if (pid->integral > 255.0) pid->integral = 255.0;
    if (pid->integral < -255.0) pid->integral = -255.0;

    double derivative = (error - pid->prev_error) / dt;
    double output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;

    pid->prev_error = error;
    return output;
}

/* ------------------------------------------------------------------ */
/* Sensor simulation                                                   */
/* ------------------------------------------------------------------ */

static double simulate_tilt_error(void)
{
    return ((double)rand() / RAND_MAX) * 20.0 - 10.0;
}

static double simulate_distance(void)
{
    return ((double)rand() / RAND_MAX) * 398.0 + 2.0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Configure motor control pins */
    gpioSetMode(MOTOR_A_FORWARD,  PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE,   PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD,  PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE,   PI_OUTPUT);

    /* Ensure motors are stopped at startup */
    motor_stop(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, MOTOR_A_ENABLE);
    motor_stop(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, MOTOR_B_ENABLE);

    /* Open log file */
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open balance_log.txt for appending.\n");
        gpioTerminate();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n");
        fflush(log_file);
    }

    /* Initialize PID controller */
    PIDController pid;
    pid_init(&pid, KP, KI, KD);

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Self-balancing robot running. Press Ctrl+C to stop.\n");

    /* Main control loop */
    while (running) {
        double tilt_error = simulate_tilt_error();
        double distance   = simulate_distance();

        double pid_output = pid_compute(&pid, tilt_error, (double)LOOP_PERIOD_MS / 1000.0);

        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        /* Obstacle avoidance: reverse at 50% speed */
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -127;
            motor_b_speed = -127;
        }

        /* Apply motor commands */
        motor_set_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, MOTOR_A_ENABLE, motor_a_speed);
        motor_set_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, MOTOR_B_ENABLE, motor_b_speed);

        /* Log data */
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        /* Wait for next cycle */
        gpioDelay(LOOP_PERIOD_MS * 1000); /* gpioDelay takes microseconds */
    }

