    snd_pcm_t *handle = NULL;
    snd_pcm_hw_params_t *params = NULL;
    bool alsa_ok = false;

#ifdef ALSA_AVAILABLE
    if (init_alsa(&handle, &params) == 0) {
        alsa_ok = true;
        printf("ALSA audio capture initialised (default device)\n");
    } else {
        fprintf(stderr, "Warning: ALSA not available; falling back to simulated audio\n");
    }
#else
    fprintf(stderr, "Warning: libasound not available; falling back to simulated audio\n");
#endif

    /* --- signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    int16_t *audio_buffer = malloc((size_t)PERIOD_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "malloc failed\n");
        goto cleanup;
    }

    while (g_running) {
        if (alsa_ok) {
            if (read_audio_frame(handle, params, audio_buffer, PERIOD_SIZE) != 0) {
                fprintf(stderr, "Audio read error; continuing\n");
                usleep(UPDATE_DELAY_US);
                continue;
            }
        } else {
            simulate_audio_frame(audio_buffer, PERIOD_SIZE);
        }

        /* Compute RMS of the period */
        double sum_sq = 0.0;
        for (int i = 0; i < PERIOD_SIZE; i++) {
            double s = (double)audio_buffer[i];
            sum_sq += s * s;
        }
        double rms = sqrt(sum_sq / (double)PERIOD_SIZE);
        float rms_norm = (float)(rms / 32767.0);

        /* Apply sensitivity scaling */
        float scaled = rms_norm * sensitivity;
        if (scaled > 1.0f) scaled = 1.0f;
        if (scaled < 0.0f) scaled = 0.0f;

        /* Map to RGB */
        float r, g, b;
        map_rms_to_rgb(scaled, &r, &g, &b);

        /* Apply PWM */
        if (safe_set_pwm(RED_PIN, r) < 0 ||
            safe_set_pwm(GREEN_PIN, g) < 0 ||
            safe_set_pwm(BLUE_PIN, b) < 0) {
            fprintf(stderr, "PWM update failed\n");
        }

        usleep(UPDATE_DELAY_US);
    }

cleanup:
    /* --- release resources --- */
    if (audio_buffer) free(audio_buffer);
    if (alsa_ok) {
        snd_pcm_drain(handle);
        snd_pcm_close(handle);
        snd_pcm_hw_params_free(params);
    }
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

