/*
 * mood_light.c — Ambient-noise-driven RGB mood light for Raspberry Pi 3 B+
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound -lm
 *   (Uncomment ALSA_AVAILABLE below if libasound is installed.)
 *
 * Run:
 *   sudo ./mood_light [sensitivity_scale]
 *
 * Wiring (common-cathode RGB LED):
 *   Red   -> GPIO17 (with 330 Ω resistor)
 *   Green -> GPIO18 (with 330 Ω resistor)
 *   Blue  -> GPIO27 (with 330 Ω resistor)
 *   Common -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define SAMPLE_RATE    8000
#define BITS_PER_SAMPLE 16
#define CHANNELS       1
#define PERIOD_SIZE    1024
#define UPDATE_DELAY_US 10000  /* 10 ms */

#define ALSA_AVAILABLE

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#else
#define snd_pcm_t void
#define snd_pcm_hw_params_t void
#define snd_pcm_open(...) (-1)
#define snd_pcm_hw_params_malloc(...) (-1)
#define snd_pcm_hw_params_free(...)
#define snd_pcm_hw_params_any(...) (-1)
#define snd_pcm_hw_params_set_access(...) (-1)
#define snd_pcm_hw_params_set_format(...) (-1)
#define snd_pcm_hw_params_set_channels(...) (-1)
#define snd_pcm_hw_params_set_rate(...) (-1)
#define snd_pcm_hw_params(...) (-1)
#define snd_pcm_prepare(...) (-1)
#define snd_pcm_start(...) (-1)
#define snd_pcm_readi(...) (-1)
#define snd_pcm_drain(...) (-1)
#define snd_pcm_close(...)
#endif

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* RGB color mapping                                                   */
/* ------------------------------------------------------------------ */

/*
 * Map ambient-noise RMS to RGB values.
 *   rms < 0.05  -> cool (blue)
 *   rms < 0.1   -> light blue
 *   rms < 0.2   -> light green
 *   rms < 0.3   -> light yellow
 *   rms < 0.4   -> light orange
 *   rms >= 0.4  -> warm (red)
 */
static void map_rms_to_rgb(float rms, float *r, float *g, float *b)
{
    if (rms < 0.05f) {
        *r = 0.0f; *g = 0.0f; *b = 1.0f; /* blue */
    } else if (rms < 0.1f) {
        *r = 0.0f; *g = 0.5f; *b = 0.5f; /* light blue */
    } else if (rms < 0.2f) {
        *r = 0.0f; *g = 1.0f; *b = 0.0f; /* light green */
    } else if (rms < 0.3f) {
        *r = 1.0f; *g = 1.0f; *b = 0.0f; /* light yellow */
    } else if (rms < 0.4f) {
        *r = 1.0f; *g = 0.5f; *b = 0.0f; /* light orange */
    } else {
        *r = 1.0f; *g = 0.0f; *b = 0.0f; /* red */
    }
}

/* ------------------------------------------------------------------ */
/* pigpio helpers                                                      */
/* ------------------------------------------------------------------ */

static int set_pwm(int pin, float value)
{
    if (value < 0.0f) value = 0.0f;
    if (value > 1.0f) value = 1.0f;
    return gpioPWM(pin, (int)(value * 255.0f));
}

static int safe_set_pwm(int pin, float value)
{
    if (set_pwm(pin, value) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ALSA audio capture                                                  */
/* ------------------------------------------------------------------ */

static int init_alsa(snd_pcm_t **handle, snd_pcm_hw_params_t **params)
{
    int err;

    err = snd_pcm_open(handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_malloc(params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_malloc failed: %s\n", snd_strerror(err));
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_any(*handle, *params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_access(*handle, *params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_format(*handle, *params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_channels(*handle, *params, CHANNELS);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(err));
        goto fail;
    }

    unsigned int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(*handle, *params, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        goto fail;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: rate %u requested, got %u\n", SAMPLE_RATE, rate);
    }

    err = snd_pcm_hw_params(*handle, *params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_prepare(*handle);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_start(*handle);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_start failed: %s\n", snd_strerror(err));
        goto fail;
    }

    return 0;

fail:
    snd_pcm_hw_params_free(*params);
    *params = NULL;
    snd_pcm_close(*handle);
    *handle = NULL;
    return -1;
}

static int read_audio_frame(snd_pcm_t *handle, snd_pcm_hw_params_t *params,
                            int16_t *buffer, int frames)
{
    int err;

    err = snd_pcm_readi(handle, buffer, frames);
    if (err == -EPIPE) {
        fprintf(stderr, "Overrun occurred\n");
        err = snd_pcm_prepare(handle);
        if (err < 0) {
            fprintf(stderr, "snd_pcm_prepare after overrun failed: %s\n", snd_strerror(err));
            return -1;
        }
        return 0;
    }
    if (err == -ESTRPIPE) {
        fprintf(stderr, "Stream was suspended\n");
        while ((err = snd_pcm_resume(handle)) == -EAGAIN) {
            usleep(1000);
        }
        if (err < 0) {
            fprintf(stderr, "snd_pcm_resume failed: %s\n", snd_strerror(err));
            err = snd_pcm_prepare(handle);
            if (err < 0) {
                fprintf(stderr, "snd_pcm_prepare after resume failed: %s\n", snd_strerror(err));
                return -1;
            }
        }
        return 0;
    }
    if (err < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        return -1;
    }
    if (err != frames) {
        fprintf(stderr, "Short read: got %d frames, expected %d\n", err, frames);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Simulated audio (sine wave) for ALSA-less mode                      */
/* ------------------------------------------------------------------ */

static void simulate_audio_frame(int16_t *buffer, int frames)
{
    const double two_pi = 2.0 * M_PI;
