    for (int i = 0; i < frames; i++) {
        buffer[i] = (int16_t)(32767.0 * sin(phase));
        phase += two_pi / (double)frames;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    float sensitivity = 1.0f;
    if (argc > 1) {
        sensitivity = (float)atof(argv[1]);
        if (sensitivity <= 0.0f) {
            fprintf(stderr, "Sensitivity must be positive; using 1.0\n");
            sensitivity = 1.0f;
        }
    }

