    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    /* --- ALSA init (or fallback to simulation) --- */
    snd_pcm_t *handle = NULL;
    snd_pcm_hw_params_t *params = NULL;
    bool alsa_ok = false;

#ifdef ALSA_AVAILABLE
    if (init_alsa(&handle, &params) == 0) {
        alsa_ok = true;
        printf("ALSA audio capture initialised (default device)\n");
    } else {
        fprintf(stderr, "Warning: ALSA not available; falling back to simulated audio\n");
    }
#else
    fprintf(stderr, "Warning: libasound not available; falling back to simulated audio\n");
#endif

    /* --- signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    int16_t *audio_buffer = malloc((size_t)PERIOD_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "malloc failed\n");
        goto cleanup;
    }

    while (g_running) {
        if (alsa_ok) {
            if (read_audio_frame(handle, params, audio_buffer, PERIOD_SIZE) != 0) {
