#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TCS34725_ADDR 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int tcs34725_init(void) {
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to power on TCS34725 (ENABLE write)\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error: Failed to set integration time (ATIME write)\n");
        return -1;
    }
    return 0;
}

static int tcs34725_read_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int c_lo = i2cReadByteData(i2c_handle, TCS34725_CDATA);
    int c_hi = i2cReadByteData(i2c_handle, TCS34725_CDATA + 1);
    int r_lo = i2cReadByteData(i2c_handle, TCS34725_RDATA);
    int r_hi = i2cReadByteData(i2c_handle, TCS34725_RDATA + 1);
    int g_lo = i2cReadByteData(i2c_handle, TCS34725_GDATA);
    int g_hi = i2cReadByteData(i2c_handle, TCS34725_GDATA + 1);
    int b_lo = i2cReadByteData(i2c_handle, TCS34725_BDATA);
    int b_hi = i2cReadByteData(i2c_handle, TCS34725_BDATA + 1);

    if (c_lo < 0 || c_hi < 0 || r_lo < 0 || r_hi < 0 ||
        g_lo < 0 || g_hi < 0 || b_lo < 0 || b_hi < 0) {
        return -1;
    }

    *clear = (uint16_t)((c_hi << 8) | c_lo);
    *red   = (uint16_t)((r_hi << 8) | r_lo);
    *green = (uint16_t)((g_hi << 8) | g_lo);
    *blue  = (uint16_t)((b_hi << 8) | b_lo);
    return 0;
}

static void log_data(time_t timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)timestamp, clear, red, green, blue);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", TCS34725_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open color_data.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(fp);
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        time_t current_time = time(NULL);
        uint16_t clear = 0, red = 0, green = 0, blue = 0;

        if (tcs34725_read_data(&clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        log_data(current_time, clear, red, green, blue);
        gpioDelay(500000);
    }

    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

