#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 57600
#define PWM_STEPS 100
#define STEP_DELAY_US 100000

static const int relay_pins[NUM_RELAYS] = {17, 27, 22, 23};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
