            fprintf(stderr, "Failed to get GPIO line %d\n", relay_pins[i]);
            cleanup();
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "sunrise_sim", 1) < 0) {
            perror("Failed to request output for GPIO line");
            cleanup();
            return -1;
        }
    }
    return 0;
}

static void set_relay_state(int relay_index, int state) {
    if (relay_index < 0 || relay_index >= NUM_RELAYS) return;
    gpiod_line_set_value(relay_lines[relay_index], state ? 0 : 1);
}

static void all_relays_off(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(i, 0);
    }
}

static void all_relays_on(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(i, 1);
    }
}

static void simulate_sunrise(void) {
    printf("Sunrise phase: gradually increasing brightness...\n");
    for (int step = 0; step <= PWM_STEPS && program_running; step++) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            set_relay_state(i, (step * 2) > i);
        }
        usleep(STEP_DELAY_US);
    }
}

static void simulate_daytime(void) {
    printf("Daytime phase: full brightness...\n");
    all_relays_on();
    for (int i = 0; i < DAYTIME_DURATION && program_running; i++) {
        sleep(1);
    }
}

static void simulate_sunset(void) {
    printf("Sunset phase: gradually decreasing brightness...\n");
    for (int step = PWM_STEPS; step >= 0 && program_running; step--) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            set_relay_state(i, (step * 2) > i);
        }
        usleep(STEP_DELAY_US);
    }
}

static void simulate_nighttime(void) {
    printf("Nighttime phase: all off...\n");
    all_relays_off();
    for (int i = 0; i < NIGHTTIME_DURATION && program_running; i++) {
        sleep(1);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Sunrise/Sunset Lighting Simulator started. Press Ctrl+C to exit.\n");

    while (program_running) {
        simulate_sunrise();
        if (!program_running) break;
        simulate_daytime();
        if (!program_running) break;
        simulate_sunset();
        if (!program_running) break;
        simulate_nighttime();
    }

    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

