#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MOTION_SENSOR_GPIO 17
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

static int open_log_file(void) {
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static void log_event(const char *message) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_fp, "%s: %s\n", timestamp, message);
    fflush(log_fp);
}

static int record_video(void) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[256];
    char command[512];
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", tm_info);
    snprintf(command, sizeof(command), "raspivid -o %s%s -t 5000 -w 640 -h 480", VIDEO_DIR, filename);
    int ret = system(command);
    if (ret == 0) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Video recorded: %s%s", VIDEO_DIR, filename);
        log_event(msg);
        printf("Video recorded: %s%s\n", VIDEO_DIR, filename);
        return 0;
    } else {
        fprintf(stderr, "Error: raspivid failed with return code %d\n", ret);
        log_event("Error: raspivid failed");
        return -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (init_gpio() != 0) return EXIT_FAILURE;
    if (open_log_file() != 0) { gpioTerminate(); return EXIT_FAILURE; }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);
    log_event("Motion detection started");

    uint32_t last_trigger_tick = 0;

    while (running) {
        if (gpioRead(MOTION_SENSOR_GPIO) == 0) {
            uint32_t now_tick = gpioTick();
            if (now_tick - last_trigger_tick > DEBOUNCE_DELAY_MS * 1000) {
                printf("Motion detected!\n");
                log_event("Motion detected");
                record_video();
                last_trigger_tick = now_tick;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("Motion detection stopped");
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

