#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_GYRO_XOUT_L  0x44
#define MPU6050_GYRO_YOUT_H  0x45
#define MPU6050_GYRO_YOUT_L  0x46
#define MPU6050_GYRO_ZOUT_H  0x47
#define MPU6050_GYRO_ZOUT_L  0x48

/* Sensitivity scale factor for ±250°/s range (LSB per °/s) */
#define GYRO_SENSITIVITY 131.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Re-initialization retry count */
#define INIT_RETRIES 3

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int initialize_mpu6050(int handle);
static int read_gyro_data(int handle, float *x, float *y, float *z);
static void log_data(FILE *fp, float x, float y, float z);
static void signal_handler(int sig);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Initialize the MPU-6050: wake up, set sample rate, set gyro range */
static int initialize_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle time */

    /* Set sample rate divider to 125 Hz (1 kHz / (1 + 125) = 8 Hz) */
    if (i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 0x78) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV: %s\n", strerror(errno));
        return -1;
    }

    /* Set gyroscope full-scale range to ±250°/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read raw gyroscope data and convert to degrees per second */
static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at GYRO_XOUT_H (0x43) in one I2C block read */
    if (i2cReadI2CBlockData(handle, MPU6050_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* Log a timestamped gyroscope reading to the CSV file */
static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%.2f,%.2f,%.2f\n",
            timestamp, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

int main(void) {
    float x, y, z;
    int retries;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address 0x68 */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 with retries */
    retries = INIT_RETRIES;
    while (initialize_mpu6050(i2c_handle) != 0 && retries > 0) {
        fprintf(stderr, "MPU-6050 initialization failed, retrying (%d left)...\n", retries - 1);
        gpioDelay(100000); /* 100 ms delay before retry */
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "MPU-6050 initialization failed after %d attempts.\n", INIT_RETRIES);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    /* Register signal handlers for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main sampling loop */
    while (program_running) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            /* Attempt re-initialization on read failure */
            retries = INIT_RETRIES;
            while (retries > 0) {
                fprintf(stderr, "Read failed, re-initializing (%d left)...\n", retries - 1);
                if (initialize_mpu6050(i2c_handle) == 0) {
                    break;
                }
                gpioDelay(100000); /* 100 ms before next retry */
                retries--;
            }
            if (retries == 0) {
                fprintf(stderr, "Re-initialization failed after %d attempts.\n", INIT_RETRIES);
                program_running = 0;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

