#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define ZONE1_PIN 4
#define ZONE2_PIN 17
#define ZONE3_PIN 27
#define ZONE4_PIN 22

#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define SLEEP_SECONDS 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {ZONE1_PIN, ZONE2_PIN, ZONE3_PIN, ZONE4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        /* SainSmart relays are active-low: LOW = ON, HIGH = OFF */
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Failed to write HIGH to GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    int pins[] = {ZONE1_PIN, ZONE2_PIN, ZONE3_PIN, ZONE4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioWrite(pins[i], 1); /* HIGH = OFF */
    }
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static void control_relay(int zone_pin, int moisture_level) {
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(zone_pin, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", zone_pin);
    }
}

static void log_data(int moisture1, int moisture2, int moisture3, int moisture4,
                     int relay1, int relay2, int relay3, int relay4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Moisture: %d, %d, %d, %d, Relay: %d, %d, %d, %d\n",
                timestamp, moisture1, moisture2, moisture3, moisture4,
                relay1, relay2, relay3, relay4) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        deactivate_all_relays();
        gpioTerminate();
        return 1;
    }

    while (running) {
        int moisture1 = read_moisture_sensor();
        int moisture2 = read_moisture_sensor();
        int moisture3 = read_moisture_sensor();
        int moisture4 = read_moisture_sensor();

        control_relay(ZONE1_PIN, moisture1);
        control_relay(ZONE2_PIN, moisture2);
        control_relay(ZONE3_PIN, moisture3);
        control_relay(ZONE4_PIN, moisture4);

        int relay1 = gpioRead(ZONE1_PIN);
        int relay2 = gpioRead(ZONE2_PIN);
        int relay3 = gpioRead(ZONE3_PIN);
        int relay4 = gpioRead(ZONE4_PIN);

        log_data(moisture1, moisture2, moisture3, moisture4,
                 relay1, relay2, relay3, relay4);

        gpioDelay(SLEEP_SECONDS * 1000000);
    }

    deactivate_all_relays();

    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

