#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Freefall detection parameters */
#define FREEFALL_THRESHOLD_G  0.2f
#define FREEFALL_DURATION_MS  500
#define SAMPLE_INTERVAL_MS    100
#define ALARM_GPIO            27
#define ALARM_DURATION_MS     5000

/* Scale factor: ±2g, full resolution -> 256 LSB/g */
#define SCALE_FACTOR 256.0f

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(int handle) {
    /* Standby first to allow configuration changes */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 to standby.\n");
        return -1;
    }

    /* DATA_FORMAT: 0x0B = full resolution, ±2g range, right-justified */
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to write DATA_FORMAT register.\n");
        return -1;
    }

    /* POWER_CTL: 0x08 = measurement mode */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 to measurement mode.\n");
        return -1;
    }

    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data.\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;

    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD_G &&
            fabsf(y) < FREEFALL_THRESHOLD_G &&
            fabsf(z) < FREEFALL_THRESHOLD_G);
}

static void trigger_alarm(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d high.\n", gpio_pin);
        return;
    }
    gpioDelay(ALARM_DURATION_MS * 1000);
    if (gpioWrite(gpio_pin, 0) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d low.\n", gpio_pin);
    }
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open freefall.log for appending.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", ADXL345_ADDRESS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", ALARM_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float x, y, z;

        if (read_accelerometer(i2c_handle, &x, &y, &z) < 0) {
            gpioDelay(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (detect_freefall(x, y, z)) {
            gpioDelay(FREEFALL_DURATION_MS * 1000);

            if (read_accelerometer(i2c_handle, &x, &y, &z) < 0) {
                gpioDelay(SAMPLE_INTERVAL_MS * 1000);
                continue;
            }

            if (detect_freefall(x, y, z)) {
                printf("Freefall detected!\n");
                trigger_alarm(ALARM_GPIO);
                log_freefall(x, y, z);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    /* Cleanup */
    gpioWrite(ALARM_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

