#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400.0
#define SOUND_SPEED_CM_PER_US 0.0343
#define TIMEOUT_US 100000
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_US 200000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int measurement_active = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pthread_mutex_lock(&mutex);
        start_tick = tick;
        pthread_mutex_unlock(&mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&mutex);
        end_tick = tick;
        echo_received = 1;
        pthread_mutex_unlock(&mutex);
    }
}

static void trigger_pulse(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance_cm(uint32_t pulse_width_us) {
    return (double)pulse_width_us * SOUND_SPEED_CM_PER_US / 2.0;
}

static void log_distance(double distance_cm) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (long)ts.tv_sec * 1000000000L + ts.tv_nsec;
    fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance_cm);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set echo callback\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        pthread_mutex_lock(&mutex);
        echo_received = 0;
        measurement_active = 1;
        pthread_mutex_unlock(&mutex);

        trigger_pulse();

        uint32_t start_time = gpioTick();
        int timed_out = 0;

        while (!echo_received && !timed_out && running) {
            if ((int32_t)(gpioTick() - start_time) > TIMEOUT_US) {
                timed_out = 1;
            }
            gpioDelay(100);
        }

        pthread_mutex_lock(&mutex);
        measurement_active = 0;
        uint32_t local_start = start_tick;
        uint32_t local_end = end_tick;
        int local_echo_received = echo_received;
        pthread_mutex_unlock(&mutex);

        if (!local_echo_received || timed_out) {
            fprintf(stderr, "Timeout or no echo received\n");
            continue;
        }

        uint32_t pulse_width = local_end - local_start;
        if (pulse_width > 23200) {
            fprintf(stderr, "Pulse width %u us exceeds max range\n", pulse_width);
            continue;
        }

        double distance_cm = calculate_distance_cm(pulse_width);
        if (distance_cm > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance %.2f cm exceeds max range\n", distance_cm);
            continue;
        }

        log_distance(distance_cm);
        printf("Distance: %.2f cm\n", distance_cm);

        uint32_t remaining = MEASUREMENT_INTERVAL_US;
        while (remaining > 0 && running) {
            uint32_t chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

