#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define BUZZER_GPIO 17

#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

#define SENSITIVITY 16384.0f
#define DEFAULT_FF_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define BUZZER_DURATION_MS 1000
#define I2C_RETRIES 3
#define SAMPLE_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lis3dh(void) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = I2C_RETRIES;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) == 6) {
            int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

            *x = (float)raw_x / SENSITIVITY;
            *y = (float)raw_y / SENSITIVITY;
            *z = (float)raw_z / SENSITIVITY;
            return 0;
        }
        fprintf(stderr, "I2C read failed, retries left: %d\n", retries - 1);
        retries--;
        if (retries > 0) gpioDelay(10000);
    }
    return -1;
}

static int detect_fall(float x, float y, float z, float ff_thresh, float imp_thresh) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag < ff_thresh) {
        printf("Freefall detected! Magnitude: %.2f g\n", mag);
        return 1;
    }
    if (mag > imp_thresh) {
        printf("Impact detected! Magnitude: %.2f g\n", mag);
        return 2;
    }
    return 0;
}

static void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(BUZZER_GPIO, 0);
}

int main(int argc, char *argv[]) {
    float ff_thresh = DEFAULT_FF_THRESHOLD;
    float imp_thresh = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) ff_thresh = atof(argv[1]);
    if (argc > 2) imp_thresh = atof(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh() < 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    signal(SIGINT, signal_handler);

    float x, y, z;
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            int res = detect_fall(x, y, z, ff_thresh, imp_thresh);
            if (res == 2) activate_buzzer(BUZZER_DURATION_MS);
        } else {
            fprintf(stderr, "Failed to read acceleration after retries\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

