typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static volatile sig_atomic_t program_running = 1;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line  = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line  = NULL;
static struct gpiod_line *alert_line  = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
    }
    if (left_line)  gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip)       gpiod_chip_close(chip);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    left_line  = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line  = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line  = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(left_line, "line_follower") < 0 ||
        gpiod_line_request_input(center_line, "line_follower") < 0 ||
        gpiod_line_request_input(right_line, "line_follower") < 0) {
        fprintf(stderr, "Failed to request sensor lines as input: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(alert_line, "line_follower", 0) < 0) {
        fprintf(stderr, "Failed to request alert line as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Sensor read error: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static void log_sensor_data(int left, int center, int right) {
    sensor_buffer[buffer_index].left   = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right  = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int check_line_crossing(void) {
    int count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (sensor_buffer[i].center == NO_LINE) count++;
    }
    return (count >= 5) ? 1 : 0;
}

static void activate_alert(void) {
    printf("Line crossing detected! Activating alert.\n");
    if (gpiod_line_set_value(alert_line, 1) < 0) {
        fprintf(stderr, "Failed to set alert HIGH: %s\n", strerror(errno));
        return;
    }
    sleep(ALERT_DURATION_S);
    if (gpiod_line_set_value(alert_line, 0) < 0) {
        fprintf(stderr, "Failed to set alert LOW: %s\n", strerror(errno));
    }
    printf("Alert deactivated.\n");
}

static void control_motors(int left, int center, int right) {
    if (center == LINE_DETECTED) {
        printf("Moving forward.\n");
    } else if (left == LINE_DETECTED) {
        printf("Turning left.\n");
    } else if (right == LINE_DETECTED) {
        printf("Turning right.\n");
    } else {
        printf("Stopping.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int left   = read_sensor(left_line);
        int center = read_sensor(center_line);
        int right  = read_sensor(right_line);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            break;
        }

        log_sensor_data(left, center, right);

        if (check_line_crossing()) {
            activate_alert();
        }

        control_motors(left, center, right);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

