#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x30
#define REG_FIELD_X    0xC0
#define REG_CTRL       0xC1
#define CTRL_ONE_SHOT  0x01
#define RELAY_GPIO     17
#define THRESHOLD_MT   5.0f
#define SAMPLE_US      100000
#define POLL_TIMEOUT   50
#define LOG_FILE       "magnetic_events.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, msg);
    } else {
        fprintf(fp, "(unknown-time) %s\n", msg);
    }
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_field_raw(int16_t *raw_out) {
    if (i2cWriteByteData(g_i2c_handle, REG_CTRL, CTRL_ONE_SHOT) < 0) {
        log_event("ERROR: i2cWriteByteData (one-shot) failed");
        return -1;
    }

    for (int i = 0; i < POLL_TIMEOUT; i++) {
        int ctrl = i2cReadByteData(g_i2c_handle, REG_CTRL);
        if (ctrl < 0) {
            log_event("ERROR: i2cReadByteData (poll) failed");
            return -1;
        }
        if (ctrl == 0x00) break;
        gpioDelay(1000);
        if (i == POLL_TIMEOUT - 1) {
            log_event("ERROR: one-shot conversion timeout");
            return -1;
        }
    }

    int lsb = i2cReadByteData(g_i2c_handle, REG_FIELD_X);
    if (lsb < 0) {
        log_event("ERROR: i2cReadByteData (LSB) failed");
        return -1;
    }
    int msb = i2cReadByteData(g_i2c_handle, REG_FIELD_X + 1);
    if (msb < 0) {
        log_event("ERROR: i2cReadByteData (MSB) failed");
        return -1;
    }

    *raw_out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static float raw_to_milliTesla(int16_t raw) {
    return (float)raw * 25.0f / 1000.0f;
}

static void set_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event("ERROR: gpioWrite(relay) failed");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_relay(0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("INFO: Si7210 monitor started");

    while (g_running) {
        int16_t raw;
        if (read_field_raw(&raw) != 0) {
            set_relay(0);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float field_mt = raw_to_milliTesla(raw);
        int above = (field_mt > THRESHOLD_MT);
        int cur = gpioRead(RELAY_GPIO);

        if (above && !cur) {
            set_relay(1);
            log_event("INFO: Field above threshold, relay ON");
        } else if (!above && cur) {
            set_relay(0);
            log_event("INFO: Field below threshold, relay OFF");
        }

        char buf[128];
        snprintf(buf, sizeof(buf),
                 "INFO: raw=%d field=%.2f mT threshold=%.1f mT relay=%d",
                 raw, field_mt, THRESHOLD_MT, cur);
        log_event(buf);

        gpioDelay(SAMPLE_US);
    }

    log_event("INFO: Shutting down");
    set_relay(0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

