#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

static int handle_command(const char *command) {
    char cmd[16];
    strncpy(cmd, command, sizeof(cmd) - 1);
    cmd[sizeof(cmd) - 1] = '\0';
    char *end = cmd + strlen(cmd);
    while (end > cmd && (*end == '\n' || *end == '\r' || *end == ' ' || *end == '\t')) {
        *end = '\0';
        end--;
    }
    if (strcasecmp(cmd, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1);
        log_event("Relay turned ON");
        return 0;
    } else if (strcasecmp(cmd, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0);
        log_event("Relay turned OFF");
        return 0;
    } else {
        log_event("Invalid command received");
        return -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    if (init_gpio() != 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        log_event("Socket creation failed");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        log_event("setsockopt failed");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Bind failed");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        log_event("Listen failed");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            log_event("Accept failed");
            continue;
        }

        char buffer[BUFFER_SIZE];
        ssize_t bytes_received = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_received < 0) {
            perror("read failed");
            log_event("Read failed");
        } else if (bytes_received == 0) {
            log_event("Client disconnected");
        } else {
            buffer[bytes_received] = '\0';
            printf("Received command: %s\n", buffer);
            handle_command(buffer);
        }

        close(client_fd);
        client_fd = -1;
    }

    printf("Shutting down...\n");
    log_event("Server shutting down");
    cleanup();
    return 0;
}

