    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Bind failed");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        log_event("Listen failed");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            log_event("Accept failed");
            continue;
        }

        char buffer[BUFFER_SIZE];
        ssize_t bytes_received = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_received < 0) {
            perror("read failed");
            log_event("Read failed");
        } else if (bytes_received == 0) {
            log_event("Client disconnected");
        } else {
            buffer[bytes_received] = '\0';
            printf("Received command: %s\n", buffer);
            handle_command(buffer);
        }

        close(client_fd);
        client_fd = -1;
    }

    printf("Shutting down...\n");
    log_event("Server shutting down");
    cleanup();
    return 0;
}

