/*
 * Raspberry Pi Zero W – dual SLF3S-1300F liquid flow sensor monitor.
 *
 * Wiring:
 *   Sensor 1  I2C bus 1, address 0x08
 *   Sensor 2  I2C bus 1, address 0x09
 *   Relay     GPIO 18 (BCM), active-high
 *
 * Build:  gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define SENSOR1_ADDR         0x08
#define SENSOR2_ADDR         0x09
#define RELAY_GPIO           18
#define FLOW_THRESHOLD       5.0f          /* ml/min */
#define SCALE_FACTOR         (1.0f / 1500.0f) /* SLF3S-1300F: raw / 1500 = ml/min */
#define POLL_DELAY_US        100000        /* 100 ms */
#define LOG_FILE             "flow_log.txt"

/* SLF3S start-measurement command (no clock stretching, mass flow) */
static const uint8_t CMD_START[2] = { 0x36, 0x08 };

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;
static int  g_i2c_h2 = -1;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static uint8_t crc8(const uint8_t *data, int len);
static int  init_sensor(int bus, int addr);
static int  read_flow_rate(int handle, float *out);
static void control_relay(float f1, float f2);
static void log_flow_data(float f1, float f2);
static void cleanup(void);

/* ------------------------------- CRC-8 ----------------------------------- */

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Sensor helpers ------------------------------ */

/*
 * Open an I2C handle and send the SLF3S start-measurement command.
 * Returns 0 on success, -1 on failure (handle is left closed).
 */
static int init_sensor(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                bus, addr, h);
        return -1;
    }

    if (i2cWriteDevice(h, (char *)CMD_START, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to send start-measurement command "
                        "to sensor at 0x%02X\n", addr);
        i2cClose(h);
        return -1;
    }

    return h;
}

/*
 * Read one 3-byte measurement frame from the sensor.
 * Returns 0 on success and stores ml/min in *out; -1 on I/O error,
 * -2 on CRC mismatch.
 */
static int read_flow_rate(int handle, float *out)
{
    uint8_t buf[3];

    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[WARN] I2C read returned %d bytes (expected 3)\n", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on sensor data\n");
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out = (float)raw * SCALE_FACTOR;
    return 0;
}

/* --------------------------- Relay control ------------------------------- */

static void control_relay(float f1, float f2)
{
    int level = (f1 < FLOW_THRESHOLD && f2 < FLOW_THRESHOLD) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, level) != 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", RELAY_GPIO, level);
    }
}

/* --------------------------- Data logging -------------------------------- */

static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[WARN] Cannot open %s for append\n", LOG_FILE);
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "[WARN] clock_gettime failed\n");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------ Cleanup ---------------------------------- */

static void cleanup(void)
{
    /* De-energize relay before tearing down pigpio */
    if (g_i2c_h1 >= 0 || g_i2c_h2 >= 0) {
        gpioWrite(RELAY_GPIO, 0);
    }

    if (g_i2c_h1 >= 0) {
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
    }
    if (g_i2c_h2 >= 0) {
        i2cClose(g_i2c_h2);
        g_i2c_h2 = -1;
    }

    gpioTerminate();
    printf("\nShutdown complete.\n");
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure relay GPIO --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n",
                RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "[FATAL] gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C handles for both sensors --- */
    g_i2c_h1 = init_sensor(I2C_BUS, SENSOR1_ADDR);
    if (g_i2c_h1 < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_h2 = init_sensor(I2C_BUS, SENSOR2_ADDR);
    if (g_i2c_h2 < 0) {
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started.  Sensor1=0x%02X  Sensor2=0x%02X  "
           "Relay=GPIO%d  Threshold=%.1f ml/min\n",
           SENSOR1_ADDR, SENSOR2_ADDR, RELAY_GPIO, FLOW_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int r1 = read_flow_rate(g_i2c_h1, &f1);
        int r2 = read_flow_rate(g_i2c_h2, &f2);

        if (r1 == 0 && r2 == 0) {
            control_relay(f1, f2);
            log_flow_data(f1, f2);
        } else {
            /* On read failure, keep relay in its current state */
            if (r1 != 0)
                fprintf(stderr, "[WARN] Sensor1 read failed (code %d)\n", r1);
            if (r2 != 0)
                fprintf(stderr, "[WARN] Sensor2 read failed (code %d)\n", r2);
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

