    gpioDelay(MOTOR_RUN_US);

    motor_stop();
    syslog(LOG_INFO, "Window closed (motor OFF)");
    return 0;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(rain) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(rain) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(motor) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    motor_stop();
    syslog(LOG_INFO, "Rain window controller started (poll=%d ms, motor=%d s)",
           POLL_INTERVAL_US / 1000, MOTOR_RUN_US / 1000000);

    int dry_count = 0;
    bool rain_active = false;

    while (g_running) {
        int level = gpioRead(RAIN_SENSOR_PIN);
        if (level < 0) {
            syslog(LOG_WARNING, "gpioRead(rain) failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        bool wet = (level == 0);

        if (wet && !rain_active) {
            syslog(LOG_INFO, "Rain detected (sensor LOW)");
            rain_active = true;
            dry_count = 0;
            if (motor_close_window() != 0)
                syslog(LOG_ERR, "Motor close sequence failed");
        } else if (!wet) {
            if (rain_active) {
                syslog(LOG_INFO, "Rain stopped (sensor HIGH)");
                rain_active = false;
            }
            dry_count++;
            if (dry_count >= DRY_RETRIGGER_COUNT) {
                syslog(LOG_INFO, "Dry for %d polls, re-triggerable", dry_count);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

