#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define LOCKED_PULSE_US  2000
#define UNLOCKED_PULSE_US 1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    /* Start with door locked (servo at locked pulse) */
    if (set_servo_pulse(LOCKED_PULSE_US) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Door lock system started. Locked.\n");
    printf("Press button on GPIO %d to lock, GPIO %d to unlock.\n",
           LOCK_BUTTON_PIN, UNLOCK_BUTTON_PIN);
    fflush(stdout);

    int last_lock_state = 1;   /* 1 = locked (pull-up high) */
    int last_unlock_state = 1; /* 1 = locked (pull-up high) */

    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON_PIN);
        int unlock_state = gpioRead(UNLOCK_BUTTON_PIN);

        if (lock_state == 0 && last_lock_state == 1) {
            /* Button pressed (pull-down to ground): lock */
            if (set_servo_pulse(LOCKED_PULSE_US) == 0) {
                printf("Door locked.\n");
                fflush(stdout);
            }
            gpioDelay(50000); /* 50 ms debounce */
        }
        last_lock_state = lock_state;

        if (unlock_state == 0 && last_unlock_state == 1) {
            /* Button pressed: unlock */
            if (set_servo_pulse(UNLOCKED_PULSE_US) == 0) {
                printf("Door unlocked.\n");
                fflush(stdout);
            }
            gpioDelay(50000); /* 50 ms debounce */
        }
        last_unlock_state = unlock_state;

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown: stop servo pulses and terminate pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

