#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN      4
#define RELAY_PIN    17
#define LOG_FILE     "security_log.txt"
#define POLL_US      100000   /* 100 ms */
#define FLOODLIGHT_ON_SEC 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event, float duration)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (duration >= 0.0f) {
        if (fprintf(fp, "%s - %s, Duration: %.2f seconds\n",
                    timestamp, event, duration) < 0) {
            fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    } else {
        if (fprintf(fp, "%s - %s\n", timestamp, event) < 0) {
            fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int safe_write(int pin, int level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Ensure floodlight is off before releasing pigpio */
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to turn off floodlight during cleanup\n");
    }
    gpioTerminate();
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PIR pin as input */
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_write(RELAY_PIN, 0) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started.\n");
    printf("PIR sensor on GPIO %d, Relay on GPIO %d.\n", PIR_PIN, RELAY_PIN);
    printf("Floodlight active for %d seconds on motion. Press Ctrl+C to exit.\n",
           FLOODLIGHT_ON_SEC);

    int last_pir = gpioRead(PIR_PIN);
    if (last_pir < 0) {
        fprintf(stderr, "Initial gpioRead(%d) failed\n", PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", PIR_PIN);
            break;
        }

        /* Detect rising edge: motion starts */
        if (pir == 1 && last_pir == 0) {
            printf("Motion detected! Activating floodlight.\n");

            if (log_event("Motion Detected - Floodlight Activated", -1.0f) < 0) {
                break;
            }

            if (safe_write(RELAY_PIN, 1) < 0) {
                break;
            }

            /* Keep floodlight on for the configured duration */
            for (int i = 0; i < FLOODLIGHT_ON_SEC * 10 && g_running; i++) {
                gpioDelay(POLL_US);
            }

            if (safe_write(RELAY_PIN, 0) < 0) {
                break;
            }

            float duration = (float)FLOODLIGHT_ON_SEC;
            if (log_event("Floodlight Deactivated", duration) < 0) {
                break;
            }
        }

        last_pir = pir;
        gpioDelay(POLL_US);
    }

    /* Clean shutdown */
    cleanup();
    printf("Smart Security Light System stopped.\n");
    return EXIT_SUCCESS;
}

