/*
 * Raspberry Pi 5 - MPR121 Capacitive Touch Relay Controller
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on I2C bus 1, address 0x5A
 *   - 5V relay on GPIO17 (active-high)
 *
 * Behavior:
 *   - Toggle the relay only on a fresh touch of electrode 0 (rising-edge).
 *   - 200 ms debounce between toggles.
 *   - Relay is OFF on startup and shutdown (clean state).
 *   - Robust error handling for pigpio/I2C calls.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:
 *   sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MPR121_ADDR    0x5A
#define RELAY_GPIO     17
#define DEBOUNCE_MS    200
#define POLL_DELAY_US  50000   /* 50 ms */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR            0x5E
#define MPR121_SOFTRESET      0x80

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MPR121 helpers                                                      */
/* ------------------------------------------------------------------ */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/*
 * Initialize the MPR121 for 12-electrode touch sensing.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_init(void)
{
    /* 1. Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(2000);  /* 2 ms settle after reset */

    /* 2. Baseline filtering (MHD/NHD/NCL/FDL) */
    if (mpr121_write_reg(0x2B, 0x01) < 0) return -1;  /* MHD_R */
    if (mpr121_write_reg(0x2C, 0x01) < 0) return -1;  /* NHD_R */
    if (mpr121_write_reg(0x2D, 0x00) < 0) return -1;  /* NCL_R */
    if (mpr121_write_reg(0x2E, 0x00) < 0) return -1;  /* FDL_R */
    if (mpr121_write_reg(0x2F, 0x01) < 0) return -1;  /* MHD_F */
    if (mpr121_write_reg(0x30, 0x01) < 0) return -1;  /* NHD_F */
    if (mpr121_write_reg(0x31, 0x00) < 0) return -1;  /* NCL_F */
    if (mpr121_write_reg(0x32, 0x00) < 0) return -1;  /* FDL_F */

    /* 3. Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(0x5B, 0x33) < 0) return -1;

    /* 4. FFI=6 samples, CDC=16 µA, CDT=0.5 µs */
    if (mpr121_write_reg(0x2C, 0x10) < 0) return -1;  /* FFI=6, CDC=16 µA */
    if (mpr121_write_reg(0x2D, 0x20) < 0) return -1;  /* CDT=0.5 µs */

    /* 5. Auto-config (register 0x7B-0x7D) */
    if (mpr121_write_reg(0x7B, 0x0B) < 0) return -1;  /* USL */
    if (mpr121_write_reg(0x7C, 0x01) < 0) return -1;  /* LSL */
    if (mpr121_write_reg(0x7D, 0x24) < 0) return -1;  /* TL */

    /* 6. Enable 12 electrodes (EC=0x0C) */
    if (mpr121_write_reg(MPR121_ECR, 0x0C) < 0) return -1;

    return 0;
}

/*
 * Read the 16-bit touch status from register 0x00.
 * Returns 0 on success and stores the 12-bit electrode mask in *touch_mask.
 * Returns -1 on I2C error.
 */
static int mpr121_read_touch(uint16_t *touch_mask)
{
    uint8_t lo, hi;

    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;

    *touch_mask = ((uint16_t)hi << 8) | (uint16_t)lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static int relay_set(int state)
{
    int rc = gpioWrite(RELAY_GPIO, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(%d) failed: %d\n", RELAY_GPIO, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put MPR121 into stop mode before closing the bus */
        (void)i2cWriteByteData(g_i2c_handle, MPR121_ECR, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Ensure relay is OFF */
    (void)relay_set(0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (relay_set(0) < 0) {  /* Start with relay OFF */
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus to MPR121 */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Press Ctrl+C to exit.\n");

    bool relay_state = false;
    uint32_t last_toggle_tick = 0;

    while (g_running) {
        uint16_t touch_mask;
        if (mpr121_read_touch(&touch_mask) < 0) {
            fprintf(stderr, "Touch read error; retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Electrode 0 touch state (bit 0) */
        bool touched = (touch_mask & 0x0001) != 0;

        /* Rising-edge detection with debounce */
        uint32_t now = gpioTick();
        if (touched && !relay_state) {
            if (now - last_toggle_tick >= DEBOUNCE_MS * 1000) {
                relay_state = !relay_state;
                if (relay_set(relay_state ? 1 : 0) < 0) {
                    fprintf(stderr, "Relay write failed; aborting.\n");
                    break;
                }
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                last_toggle_tick = now;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

