/* ------------------------------------------------------------------ */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
