    if (mpr121_write_reg(0x2B, 0x01) < 0) return -1;  /* MHD_R */
    if (mpr121_write_reg(0x2C, 0x01) < 0) return -1;  /* NHD_R */
    if (mpr121_write_reg(0x2D, 0x00) < 0) return -1;  /* NCL_R */
    if (mpr121_write_reg(0x2E, 0x00) < 0) return -1;  /* FDL_R */
    if (mpr121_write_reg(0x2F, 0x01) < 0) return -1;  /* MHD_F */
