#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <stdarg.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define PORT 5000
#define SERVO_PIN 17
#define PIR_PIN 4
#define SERVO_FREQ_HZ 50
#define SERVO_RANGE_US 2000
#define SERVO_MIN_US 1000
#define SERVO_MAX_US 2000
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t servo_thread;
static volatile int servo_angle = 0;
static volatile int servo_running = 0;

static void log_event(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    char buf[512];
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    int len = snprintf(buf, sizeof(buf), "%s ", ts);
    vsnprintf(buf + len, sizeof(buf) - len, fmt, args);
    va_end(args);
    syslog(LOG_INFO, "%s", buf);
    if (log_file) {
        fprintf(log_file, "%s\n", buf);
        fflush(log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void *servo_pwm_thread(void *arg) {
    (void)arg;
    while (servo_running) {
        int angle = servo_angle;
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;
        int pulse_us = SERVO_MIN_US + (angle * (SERVO_MAX_US - SERVO_MIN_US)) / 180;
        int period_us = 1000000 / SERVO_FREQ_HZ;
        int high_us = pulse_us;
        int low_us = period_us - pulse_us;
        if (gpiod_line_set_value(servo_line, 1) < 0) {
            log_event("Servo PWM set high failed: %s", strerror(errno));
            break;
        }
        usleep(high_us);
        if (gpiod_line_set_value(servo_line, 0) < 0) {
            log_event("Servo PWM set low failed: %s", strerror(errno));
            break;
        }
        usleep(low_us);
    }
    return NULL;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_event("Invalid servo angle: %d", angle);
        return -1;
    }
    servo_angle = angle;
    if (!servo_running) {
        servo_running = 1;
        if (pthread_create(&servo_thread, NULL, servo_pwm_thread, NULL) != 0) {
            log_event("Failed to create servo thread: %s", strerror(errno));
            servo_running = 0;
            return -1;
        }
    }
    return 0;
}

static int read_pir_sensor(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        log_event("PIR read failed: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes <= 0) {
        if (bytes < 0) log_event("recv failed: %s", strerror(errno));
        close(client_fd);
        return;
    }
    buffer[bytes] = '\0';
    char *newline = strpbrk(buffer, "\r\n");
    if (newline) *newline = '\0';
    char *token = strtok(buffer, " ");
    if (token) {
        if (strcmp(token, "SERVO") == 0) {
            char *arg = strtok(NULL, " ");
            if (arg) {
                int angle = atoi(arg);
                if (set_servo_angle(angle) == 0) {
                    char resp[64];
                    snprintf(resp, sizeof(resp), "SERVO: %d\n", angle);
                    send(client_fd, resp, strlen(resp), 0);
                } else {
                    send(client_fd, "ERROR: Invalid servo angle\n", 26, 0);
                }
            } else {
                send(client_fd, "ERROR: Missing servo angle\n", 25, 0);
            }
        } else if (strcmp(token, "PIR") == 0) {
            int pir = read_pir_sensor();
            if (pir >= 0) {
                char resp[32];
                snprintf(resp, sizeof(resp), "PIR: %d\n", pir);
                send(client_fd, resp, strlen(resp), 0);
            } else {
                send(client_fd, "ERROR: PIR read failed\n", 20, 0);
            }
        } else {
            send(client_fd, "ERROR: Unknown command\n", 20, 0);
        }
    } else {
        send(client_fd, "ERROR: Empty command\n", 18, 0);
    }
    close(client_fd);
}

static void cleanup(void) {
    if (servo_running) {
        servo_running = 0;
        pthread_join(servo_thread, NULL);
    }
    if (servo_line) gpiod_line_release(servo_line);
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    if (server_fd >= 0) close(server_fd);
    if (log_file) fclose(log_file);
    closelog();
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        closelog();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event("sigaction failed: %s", strerror(errno));
        fclose(log_file);
        closelog();
        return 1;
    }
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_event("Failed to open gpiochip4: %s", strerror(errno));
        fclose(log_file);
        closelog();
        return 1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_event("Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_event("Failed to request servo line as output: %s", strerror(errno));
        cleanup();
        return 1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_event("Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_event("Failed to request PIR line as input: %s", strerror(errno));
        cleanup();
        return 1;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_event("Socket creation failed: %s", strerror(errno));
        cleanup();
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event("setsockopt failed: %s", strerror(errno));
        cleanup();
        return 1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_event("Bind failed: %s", strerror(errno));
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        log_event("Listen failed: %s", strerror(errno));
        cleanup();
        return 1;
    }
    log_event("Security system started on port %d", PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            log_event("Accept failed: %s", strerror(errno));
            break;
        }
        handle_client(client_fd);
    }
    log_event("Shutting down");
    cleanup();
    return 0;
}

