#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 120000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux_out) {
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle invalid\n");
        return -1;
    }

    /* Send One-Time High-Resolution mode command (0x20) */
    if (i2cWriteByte(i2c_handle, 0x20) < 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from BH1750 (got %d bytes)\n", bytes_read);
        return -1;
    }

    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

static void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    if (init_bh1750() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Grow light controller started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(&lux) == 0) {
            log_data(lux);
            if (lux < LUX_THRESHOLD) {
                control_relay(1);
                printf("Lux: %.2f, Relay ON\n", lux);
            } else {
                control_relay(0);
                printf("Lux: %.2f, Relay OFF\n", lux);
            }
        } else {
            fprintf(stderr, "Error reading lux value. Retrying...\n");
            control_relay(0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

