#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <errno.h>
#include <gpiod.h>

#define HX711_DOUT_LINE  23
#define HX711_SCK_LINE   24
#define SOLENOID_LINE    25

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE     100.0
#define DEFAULT_DURATION  200
#define DEFAULT_POLL_MS   500
#define DEFAULT_READ_RETRIES 3
#define DEFAULT_READ_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void sleep_ms(unsigned int ms) {
    usleep(ms * 1000);
}

static int read_hx711(struct gpiod_line *dout, struct gpiod_line *sck,
                      int32_t *raw_out) {
    int retries = 0;
    while (retries < DEFAULT_READ_RETRIES) {
        int val = gpiod_line_get_value(dout);
        if (val < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(DOUT) failed: %s", strerror(errno));
            retries++;
            sleep_ms(100);
            continue;
        }
        if (val == 1) {
            syslog(LOG_ERR, "HX711 DOUT is HIGH (data not ready), retrying...");
            retries++;
            sleep_ms(100);
            continue;
        }
        break;
    }
    if (retries >= DEFAULT_READ_RETRIES) {
        syslog(LOG_ERR, "HX711 DOUT did not go LOW after %d retries", DEFAULT_READ_RETRIES);
        return -1;
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value(SCK, 1) failed: %s", strerror(errno));
            return -1;
        }
        sleep_ms(1);
        data <<= 1;
        int bit = gpiod_line_get_value(dout);
        if (bit < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(DOUT) failed: %s", strerror(errno));
            return -1;
        }
        if (bit) data |= 1;
        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value(SCK, 0) failed: %s", strerror(errno));
            return -1;
        }
        sleep_ms(1);
    }

    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "gpiod_line_set_value(SCK, 1) failed: %s", strerror(errno));
        return -1;
    }
    sleep_ms(1);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_set_value(SCK, 0) failed: %s", strerror(errno));
        return -1;
    }
    sleep_ms(1);

    if (data & 0x800000) data |= 0xFF000000;
    *raw_out = (int32_t)data;
    return 0;
}

static int read_hx711_average(struct gpiod_line *dout, struct gpiod_line *sck,
                              int32_t *raw_out) {
    int32_t sum = 0;
    int valid = 0;
    for (int i = 0; i < 5; i++) {
        int32_t r;
        if (read_hx711(dout, sck, &r) == 0) {
            sum += r;
            valid++;
        }
        sleep_ms(10);
    }
    if (valid == 0) return -1;
    *raw_out = sum / valid;
    return 0;
}

static int tare_hx711(struct gpiod_line *dout, struct gpiod_line *sck,
                      int32_t *offset) {
    int32_t sum = 0;
    int valid = 0;
    for (int i = 0; i < 10; i++) {
        int32_t r;
        if (read_hx711(dout, sck, &r) == 0) {
            sum += r;
            valid++;
        }
        sleep_ms(100);
    }
    if (valid == 0) return -1;
    *offset = sum / valid;
    syslog(LOG_INFO, "Tare complete, offset = %d", *offset);
    return 0;
}

static void solenoid_pulse(struct gpiod_line *sol, int duration_ms) {
    if (gpiod_line_set_value(sol, 1) < 0) {
        syslog(LOG_ERR, "gpiod_line_set_value(SOLENOID, 1) failed: %s", strerror(errno));
        return;
    }
    sleep_ms(duration_ms);
    if (gpiod_line_set_value(sol, 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_set_value(SOLENOID, 0) failed: %s", strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    openlog("load_cell_monitor", LOG_PID | LOG_CONS, LOG_USER);

    double threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int solenoid_duration = DEFAULT_DURATION;
    int poll_interval = DEFAULT_POLL_MS;

    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:p:")) != -1) {
        switch (opt) {
            case 't': threshold = atof(optarg); break;
            case 's': scale = atof(optarg); break;
            case 'd': solenoid_duration = atoi(optarg); break;
            case 'p': poll_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_grams] [-s scale_factor] [-d solenoid_ms] [-p poll_ms]\n", argv[0]);
                closelog();
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_LINE);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_LINE);
    struct gpiod_line *sol = gpiod_chip_get_line(chip, SOLENOID_LINE);
    if (!dout || !sck || !sol) {
        syslog(LOG_ERR, "gpiod_chip_get_line failed: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "gpiod_line_request_input(DOUT) failed: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output(SCK) failed: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output(SOLENOID) failed: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    int32_t tare_offset = 0;
    if (tare_hx711(dout, sck, &tare_offset) < 0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        gpiod_line_set_value(sol, 0);
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_line_release(sol);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Starting load cell monitoring (threshold=%.1f g, scale=%.1f, solenoid=%d ms, poll=%d ms)",
           threshold, scale, solenoid_duration, poll_interval);

    while (program_running) {
        int32_t raw;
        if (read_hx711_average(dout, sck, &raw) < 0) {
            syslog(LOG_ERR, "HX711 read failed, retrying next cycle");
            sleep_ms(poll_interval);
            continue;
        }

        double weight = (double)(raw - tare_offset) / scale;
        syslog(LOG_INFO, "Raw=%d, Weight=%.2f g", raw, weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Weight %.2f g exceeds threshold %.1f g, activating solenoid", weight, threshold);
            solenoid_pulse(sol, solenoid_duration);
        }

        sleep_ms(poll_interval);
    }

    syslog(LOG_INFO, "Shutting down");
    gpiod_line_set_value(sol, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(sol);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

