/*
 * MQTT Relay Controller for Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control on localhost:1883 and drives a
 * relay module on GPIO17 (BCM 17, physical pin 11) HIGH/LOW.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *       -lmosquitto -lpigpio -lrt
 *
 * Run:
 *   sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_TOPIC     "home/lights/control"
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_KEEPALIVE 60
#define GPIO_PIN       17
#define RETRY_DELAY_S  5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_msg(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

static void log_err(const char *msg)
{
    syslog(LOG_ERR, "%s", msg);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_err("pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_err("Failed to set GPIO17 as output");
        gpioTerminate();
        return -1;
    }

    /* Relay OFF at startup */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_err("Failed to initialise GPIO17 LOW");
        gpioTerminate();
        return -1;
    }

    log_msg(LOG_INFO, "GPIO17 initialised: relay OFF");
    return 0;
}

static void gpio_cleanup(void)
{
    /* Ensure relay is OFF before terminating pigpio */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_err("Warning: failed to turn off relay during cleanup");
    }
    gpioTerminate();
    log_msg(LOG_INFO, "pigpio terminated");
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                     */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata,
                       int     rc,
                       int     flags)
{
    (void)userdata;
    (void)flags;

    if (rc == MOSQ_ERR_SUCCESS) {
        log_msg(LOG_INFO, "Connected to MQTT broker");

        rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc == MOSQ_ERR_SUCCESS) {
            log_msg(LOG_INFO, "Subscribed to topic: " MQTT_TOPIC);
        } else {
            log_err("Failed to subscribe");
        }
    } else {
        log_err(mosquitto_connack_string(rc));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc == MOSQ_ERR_SUCCESS) {
        log_msg(LOG_INFO, "Disconnected cleanly from MQTT broker");
    } else {
        log_err("Unexpected MQTT disconnect (rc = %d)", rc);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_err("Received empty payload on topic " MQTT_TOPIC);
        return;
    }

    /* NUL-terminate the payload safely */
    char payload[16];
    int copy_len = message->payloadlen < (int)sizeof(payload) - 1
                 ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, copy_len);
    payload[copy_len] = '\0';

    log_msg(LOG_INFO, "Received message on topic " MQTT_TOPIC ": %s", payload);

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) == 0) {
            log_msg(LOG_INFO, "Relay energized (GPIO17 HIGH)");
        } else {
            log_err("Failed to set GPIO17 HIGH");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) == 0) {
            log_msg(LOG_INFO, "Relay de-energized (GPIO17 LOW)");
        } else {
            log_err("Failed to set GPIO17 LOW");
        }
    } else {
        log_err("Invalid payload received: %s", payload);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT connection                                                    */
/* ------------------------------------------------------------------ */
static int mqtt_connect(struct mosquitto **mosq)
{
    int rc;

    rc = mosquitto_lib_init();
    if (rc != MOSQ_ERR_SUCCESS) {
        log_err("mosquitto_lib_init failed: %s", mosquitto_strerror(rc));
        return -1;
    }

    *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!*mosq) {
        log_err("mosquitto_new failed (out of memory)");
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(*mosq, on_connect);
    mosquitto_disconnect_callback_set(*mosq, on_disconnect);
    mosquitto_message_callback_set(*mosq, on_message);

    rc = mosquitto_connect(*mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_err("mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(*mosq);
        *mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

static void mqtt_disconnect(struct mosquitto **mosq)
{
    if (*mosq) {
        mosquitto_disconnect(*mosq);
        mosquitto_destroy(*mosq);
        *mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        log_err("Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_connect(&g_mosq) != 0) {
        log_err("Initial MQTT connection failed; will retry...");
    }

    while (g_running) {
        if (g_mosq) {
            int rc = mosquitto_loop(g_mosq, 100, 1);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_err("mosquitto_loop error: %s", mosquitto_strerror(rc));
                mqtt_disconnect(&g_mosq);
                log_msg(LOG_INFO, "MQTT client destroyed");
            }
        } else {
            /* No connection — attempt to reconnect */
            sleep(RETRY_DELAY_S);
            if (mqtt_connect(&g_mosq) != 0) {
                log_err("Reconnect failed; will retry in %d s", RETRY_DELAY_S);
            }
        }
    }

    /* Graceful shutdown */
    log_msg(LOG_INFO, "Shutting down...");
    mqtt_disconnect(&g_mosq);
    gpio_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

