#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_US 1000
#define SERVO2_US 1500
#define SERVO3_US 2000
#define SERVO4_US 500
#define SERVO5_US 2500

int main(void) {
    int rc;

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    /*
     * pigpio drives servos via hardware PWM on GPIO pins.
     * For a standard 50 Hz servo (20 ms period), the pulse width
     * must be between 500 and 2500 microseconds.
     *
     * gpioSetPWMfrequency sets the PWM frequency in Hz.  A negative
     * return indicates an error.
     *
     * gpioSetPWMrange sets the number of steps per PWM cycle.
     * A value of 255 gives a 0-255 duty cycle (0% - 100%).
     */
    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int us[]   = {SERVO1_US,  SERVO2_US,  SERVO3_US,  SERVO4_US,  SERVO5_US};

    for (int i = 0; i < 5; i++) {
        int freq = gpioSetPWMfrequency(pins[i], 50);
        if (freq < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d: %d\n",
                    pins[i], freq);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], 255) < 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        /*
         * gpioServo takes (gpio, pulsewidth_us).  A pulse width of 0
         * disables the servo signal on that pin.
         */
        if (gpioServo(pins[i], us[i]) < 0) {
            fprintf(stderr, "Failed to set servo pulse on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servos moving to positions...\n");
    sleep(3);

    /* Stop PWM on all servo pins */
    for (int i = 0; i < 5; i++) {
        gpioServo(pins[i], 0);
    }

    gpioTerminate();
    printf("Servos stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

