#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>

/* Motor A */
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

/* Motor B */
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

/* Encoder A */
#define ENCODER_A_A 4
#define ENCODER_A_B 5

/* Encoder B */
#define ENCODER_B_A 6
#define ENCODER_B_B 12

#define TICKS_PER_REV 64
#define TARGET_RPM 50.0
#define KP 0.5
#define KI 0.05
#define CONTROL_PERIOD_US 100000
#define PWM_FREQ 10000
#define PWM_RANGE 255
#define STALL_TIMEOUT_US 2000000

static atomic_int encoder_a_count = 0;
static atomic_int encoder_b_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    int32_t c = atomic_load(&encoder_a_count);
    atomic_store(&encoder_a_count, c + 1);
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    int32_t c = atomic_load(&encoder_b_count);
    atomic_store(&encoder_b_count, c + 1);
}

static void motor_forward(int in1, int in2, int pwm) {
    gpioWrite(in1, 1);
    gpioPWM(in2, pwm);
}

static void motor_stop(int in1, int in2) {
    gpioWrite(in1, 0);
    gpioPWM(in2, 0);
}

static void set_motor_pwm(int in1, int in2, int pwm) {
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    motor_forward(in1, in2, pwm);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Motor A */
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set Motor A pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQ);
    gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE);
    motor_stop(MOTOR_A_IN1, MOTOR_A_IN2);

    /* Motor B */
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set Motor B pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQ);
    gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE);
    motor_stop(MOTOR_B_IN3, MOTOR_B_IN4);

    /* Encoder A */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set Encoder A pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A A\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A B\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Encoder B */
    if (gpioSetMode(ENCODER_B_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set Encoder B pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B A\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B B\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double integral = 0.0;
    uint32_t last_tick = gpioTick();
    uint32_t last_stall_tick = gpioTick();

    while (running) {
        uint32_t now = gpioTick();
        uint32_t dt_us = now - last_tick;
        last_tick = now;

        int32_t a_ticks = atomic_exchange(&encoder_a_count, 0);
        int32_t b_ticks = atomic_exchange(&encoder_b_count, 0);

        double a_rpm = (double)a_ticks * 60.0 / (double)TICKS_PER_REV / ((double)dt_us / 1000000.0);
        double b_rpm = (double)b_ticks * 60.0 / (double)TICKS_PER_REV / ((double)dt_us / 1000000.0);

        double a_error = TARGET_RPM - a_rpm;
        double b_error = TARGET_RPM - b_rpm;

        integral += (a_error + b_error) * ((double)dt_us / 1000000.0);
        if (integral > PWM_RANGE) integral = PWM_RANGE;
        if (integral < -PWM_RANGE) integral = -PWM_RANGE;

        double a_pwm = KP * a_error + KI * integral;
        double b_pwm = KP * b_error + KI * integral;

        if (a_pwm < 0) a_pwm = 0;
        if (a_pwm > PWM_RANGE) a_pwm = PWM_RANGE;
        if (b_pwm < 0) b_pwm = 0;
        if (b_pwm > PWM_RANGE) b_pwm = PWM_RANGE;

        set_motor_pwm(MOTOR_A_IN1, MOTOR_A_IN2, (int)a_pwm);
        set_motor_pwm(MOTOR_B_IN3, MOTOR_B_IN4, (int)b_pwm);

        printf("Motor A RPM: %.2f, PWM: %.0f | Motor B RPM: %.2f, PWM: %.0f\n",
               a_rpm, a_pwm, b_rpm, b_pwm);

        if ((now - last_stall_tick) > STALL_TIMEOUT_US) {
            if (a_ticks == 0 && b_ticks == 0) {
                fprintf(stderr, "Warning: Motor stall detected (no encoder ticks for >2s)\n");
            }
            last_stall_tick = now;
        }

        gpioDelay(CONTROL_PERIOD_US);
    }

    motor_stop(MOTOR_A_IN1, MOTOR_A_IN2);
    motor_stop(MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();
    return EXIT_SUCCESS;
}

