#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define RELAY_GPIO 17
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 200.0
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASUREMENT_DELAY_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int init_bh1750(void) {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux_out) {
    if (i2c_handle < 0) return -1;

    if (i2cWriteByte(i2c_handle, BH1750_ONE_TIME_HIGH_RES_MODE_2) < 0) {
        fprintf(stderr, "Error writing measurement command to BH1750\n");
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_DELAY_US);

    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from BH1750 (read %d bytes)\n", bytes_read);
        return -1;
    }

    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    log_file = fopen("chicken_coop_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_bh1750() != 0) {
        log_message("BH1750 initialization failed. Exiting.");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    control_relay(relay_state);
    log_message("System started. Relay OFF.");

    while (running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            char log_buf[128];
            snprintf(log_buf, sizeof(log_buf), "Lux = %.2f, Relay = %s", lux, relay_state ? "ON" : "OFF");
            log_message(log_buf);

