#include <time.h>
#include <signal.h>
#include <unistd.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define LOOP_DELAY_US 10000       /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void)
{
    int ret;
    int relay_state = 0;
    int last_touch = 0;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(touch) failed (code %d).\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(relay) failed (code %d).\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioWrite(relay, 0) failed (code %d).\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO %d toggles relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Warning: gpioRead(touch) failed (code %d).\n", touch);
            usleep(LOOP_DELAY_US);
            continue;
        }

        /* Detect a valid touch (rising edge: HIGH after debounce) */
        if (touch == 1 && last_touch == 0) {
            usleep(DEBOUNCE_DELAY_US);

            /* Re-read after debounce to confirm still HIGH */
            touch = gpioRead(TOUCH_SENSOR_PIN);
            if (touch < 0) {
                fprintf(stderr, "Warning: gpioRead(touch) failed (code %d).\n", touch);
                usleep(LOOP_DELAY_US);
                continue;
            }

            if (touch == 1) {
                relay_state = !relay_state;

                ret = gpioWrite(RELAY_PIN, relay_state);
                if (ret != 0) {
                    fprintf(stderr, "Error: gpioWrite(relay) failed (code %d).\n", ret);
                } else {
                    log_relay_state(relay_state);
                }

                /* Wait for touch release to avoid repeated toggles */
                while (running) {
                    touch = gpioRead(TOUCH_SENSOR_PIN);
                    if (touch < 0) {
                        fprintf(stderr, "Warning: gpioRead(touch) failed (code %d).\n", touch);
                        usleep(LOOP_DELAY_US);
                        continue;
                    }
                    if (touch == 0) {
                        break;
                    }
                    usleep(LOOP_DELAY_US);
                }
            }
        }

        last_touch = touch;
        usleep(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Warning: gpioWrite(relay, 0) failed during shutdown (code %d).\n", ret);
    }
    gpioTerminate();
    printf("Relay control stopped.\n");

    return EXIT_SUCCESS;
}

