#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 0.5
#define DEBOUNCE_US 1000000
#define SAMPLE_INTERVAL_US 1000000

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_lpm(int pulses) {
    return ((double)pulses / PULSES_PER_LITER) * 60.0;
}

static int control_solenoid(int state) {
    if (gpioWrite(SOLENOID_PIN, state) != 0) {
        log_message("Error: Failed to write solenoid pin");
        return -1;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Solenoid set to %s", state ? "OPEN" : "CLOSED");
    log_message(msg);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file) {
        log_message("Shutting down...");
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to initialize solenoid to OPEN state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_US, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for flow sensor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioWrite(SOLENOID_PIN, 1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Water flow monitoring started");

    int solenoid_state = 1;

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(pulses);
        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM", lpm);
        log_message(msg);

        if (lpm > LPM_THRESHOLD && solenoid_state == 1) {
            if (control_solenoid(0) == 0) {
                solenoid_state = 0;
            }
        } else if (lpm < (LPM_THRESHOLD - LPM_HYSTERESIS) && solenoid_state == 0) {
            if (control_solenoid(1) == 0) {
                solenoid_state = 1;
            }
        }
    }

    control_solenoid(1);
    cleanup();
    return EXIT_SUCCESS;
}

