#define DISPENSE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;

typedef struct {
    double calibration_factor;
    char server_ip[20];
    int server_port;
} Config;

static Config config = {
    .calibration_factor = DEFAULT_CALIBRATION_FACTOR,
    .server_ip = DEFAULT_SERVER_IP,
    .server_port = DEFAULT_SERVER_PORT
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s. Using defaults.\n", filename);
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = line;
        char *val = eq + 1;
        while (*key == ' ') key++;
        char *ke = key + strlen(key) - 1;
        while (ke >= key && *ke == ' ') *ke-- = '\0';
        while (*val == ' ') val++;
        char *ve = val + strlen(val) - 1;
        while (ve >= val && *ve == ' ') *ve-- = '\0';
        if (strcmp(key, "calibration_factor") == 0) {
            config.calibration_factor = atof(val);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(config.server_ip, val, sizeof(config.server_ip) - 1);
            config.server_ip[sizeof(config.server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) {
            config.server_port = atoi(val);
        }
    }
    fclose(fp);
    return 0;
}

static int read_hx711(void) {
    int data = 0;
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (timeout++ > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 not ready (timeout).\n");
            return -1;
        }
        gpioDelay(1);
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data = (data << 1) | gpioRead(HX711_DATA_PIN);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }
    return data;
}

static double read_weight(void) {
    int raw = read_hx711();
    if (raw < 0) return -1.0;
    return (double)raw / config.calibration_factor;
}

static int dispense_ingredient(double target_weight) {
    int pulse_width = (int)((target_weight / 100.0) * (SERVO_CLOSE_US - SERVO_OPEN_US) + SERVO_OPEN_US);
    if (pulse_width < SERVO_OPEN_US) pulse_width = SERVO_OPEN_US;
    if (pulse_width > SERVO_CLOSE_US) pulse_width = SERVO_CLOSE_US;
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width.\n");
        return -1;
    }
    gpioDelay(DISPENSE_DELAY_US);
    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to stop servo PWM.\n");
        return -1;
    }
    return 0;
}

static void log_dispensing_event(double target_weight, double actual_weight, const char *error_msg) {
    FILE *fp = fopen("dispensing_log.json", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_msg ? error_msg : "");
    fclose(fp);
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received <= 0) {
        fprintf(stderr, "Error: Client disconnected.\n");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';
    double target_weight = atof(buffer);
    if (target_weight <= 0.0) {
        const char *err = "Invalid target weight";
        send(client_socket, err, strlen(err), 0);
        log_dispensing_event(target_weight, -1.0, err);
        close(client_socket);
        return;
    }
    if (dispense_ingredient(target_weight) != 0) {
        const char *err = "Dispensing failed";
        send(client_socket, err, strlen(err), 0);
        log_dispensing_event(target_weight, -1.0, err);
        close(client_socket);
        return;
    }
    double actual_weight = read_weight();
    if (actual_weight < 0) {
        const char *err = "Sensor read error";
        send(client_socket, err, strlen(err), 0);
        log_dispensing_event(target_weight, -1.0, err);
        close(client_socket);
        return;
    }
    char response[128];
    snprintf(response, sizeof(response), "%.2f", actual_weight);
    send(client_socket, response, strlen(response), 0);
    log_dispensing_event(target_weight, actual_weight, NULL);
    close(client_socket);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    read_config("config.ini");

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Error: Socket creation failed");
        cleanup();
        return 1;
    }
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(config.server_ip);
    server_addr.sin_port = htons(config.server_port);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error: Bind failed");
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("Error: Listen failed");
        cleanup();
        return 1;
    }
    printf("Server listening on %s:%d\n", config.server_ip, config.server_port);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (!running) break;
            perror("Error: Accept failed");
            continue;
        }
        handle_client(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

