#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define INITIAL_ANGLE  90
#define STEP_DEG       10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int set_raw_terminal(void) {
    struct termios tty;
    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }
    tty.c_lflag &= ~(ICANON | ECHO);
    tty.c_cc[VMIN] = 1;
    tty.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(const struct termios *orig) {
    if (orig) {
        tcsetattr(STDIN_FILENO, TCSANOW, orig);
    }
}

static int angle_to_pulse_us(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US + (int)((long)(angle - MIN_ANGLE) *
                                (MAX_PULSE_US - MIN_PULSE_US) /
                                (MAX_ANGLE - MIN_ANGLE));
}

static int set_servo_angle(int angle) {
    int pulse = angle_to_pulse_us(angle);
    if (pulse < MIN_PULSE_US || pulse > MAX_PULSE_US) {
        fprintf(stderr, "Pulse %d µs out of range [%d, %d]\n",
                pulse, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    struct termios orig_tty = {0};
    int angle = INITIAL_ANGLE;
    int rc = 0;

    if (tcgetattr(STDIN_FILENO, &orig_tty) != 0) {
        perror("tcgetattr (save)");
        return EXIT_FAILURE;
    }

    if (set_raw_terminal() != 0) {
        restore_terminal(&orig_tty);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        restore_terminal(&orig_tty);
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        gpioTerminate();
        restore_terminal(&orig_tty);
        return EXIT_FAILURE;
    }

    if (set_servo_angle(angle) != 0) {
        gpioTerminate();
        restore_terminal(&orig_tty);
        return EXIT_FAILURE;
    }

    printf("Servo on GPIO%d.  Angle: %d°  (+/- to change, q to quit)\n",
           SERVO_PIN, angle);
    fflush(stdout);

    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            break;
        }
        if (c == '+') {
            angle += STEP_DEG;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
        } else if (c == '-') {
            angle -= STEP_DEG;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
        } else if (c == 'q') {
            break;
        } else {
            continue;
        }
        if (set_servo_angle(angle) == 0) {
            printf("Angle: %d°\n", angle);
            fflush(stdout);
        }
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    restore_terminal(&orig_tty);
    return rc;
}

