/*
 * motor_rpm_monitor.c
 *
 * Monitors a conveyor-belt motor via an A3144 Hall-effect sensor on GPIO 17
 * (BCM 17, physical pin 11) using libgpiod.  A two-pole magnet on the motor
 * shaft produces one rising-edge pulse per revolution.  RPM is computed over
 * a 5-second window and appended to motor_rpm.log every 5 seconds.
 *
 * Build:  gcc -O2 -Wall -Wextra -o motor_rpm_monitor motor_rpm_monitor.c -lgpiod
 *
 * Requires libgpiod-dev installed (apt install libgpiod-dev).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define LOG_FILE         "motor_rpm.log"
#define SAMPLE_PERIOD_S  5           /* seconds between log entries */
#define DEBOUNCE_MS      2           /* debounce window in milliseconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return elapsed milliseconds between two timespec values.           */
static long elapsed_ms(const struct timespec *start,
                       const struct timespec *end)
{
    long sec_diff  = (long)(end->tv_sec)  - (long)(start->tv_sec);
    long nsec_diff = (long)(end->tv_nsec) - (long)(start->tv_nsec);
    return sec_diff * 1000L + nsec_diff / 1000000L;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line: "YYYY-MM-DDTHH:MM:SS,RPM" to the log file.     */
static int log_rpm(FILE *fp, double rpm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, rpm) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* ---- Open log file --------------------------------------------- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    /* ---- Open GPIO chip -------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    /* ---- Get GPIO line --------------------------------------------- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /*
     * Request the line as input with rising-edge event detection.
     * The A3144 has an open-collector output; enable the internal
     * pull-up so the line is never floating when the magnet is
     * absent.
     */
    if (gpiod_line_request_rising_edge_events_flags(line,
            "motor_rpm_monitor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_rising_edge_events_flags");
        goto cleanup;
    }

    printf("Monitoring motor RPM on GPIO %d (BCM).  Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* ---- Main sampling loop ---------------------------------------- */
    while (g_running) {
        unsigned long pulse_count = 0;
        struct timespec window_start;
        struct timespec last_event;
        int first = 1;

        if (clock_gettime(CLOCK_MONOTONIC, &window_start) != 0) {
            perror("clock_gettime(start)");
            goto cleanup;
        }
        last_event = window_start;

        /*
         * Wait for rising-edge events until the sample window elapses.
         * gpiod_line_event_wait returns 1 on event, 0 on timeout,
         * -1 on error.
         */
        while (g_running) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
                perror("clock_gettime(loop)");
                goto cleanup;
            }

            long elapsed = elapsed_ms(&window_start, &now);
            if (elapsed >= SAMPLE_PERIOD_S * 1000L) {
                break;                       /* window expired */
            }

            /*
             * Wait up to 100 ms for an event.  This keeps the loop
             * responsive to signals and keeps CPU usage low.
             */
            struct timespec wait_ts;
            wait_ts.tv_sec  = 0;
            wait_ts.tv_nsec = 100 * 1000000L; /* 100 ms */

            int rc = gpiod_line_event_wait(line, &wait_ts);
            if (rc < 0) {
                if (errno == EINTR) {
                    continue;               /* signal interrupted wait */
                }
                perror("gpiod_line_event_wait");
                goto cleanup;
            }
            if (rc == 0) {
                continue;                   /* timeout, loop to check window */
            }

            /* Event detected — read it to clear the event queue. */
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) != 0) {
                if (errno == EINTR) {
                    continue;
                }
                perror("gpiod_line_event_read");
                goto cleanup;
            }

            if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
                continue;
            }

            /*
             * Debounce: ignore events that arrive too soon after the
             * last accepted event.
             */
            if (first) {
                last_event = event.ts;
                first = 0;
                pulse_count++;
            } else {
                long since_last = elapsed_ms(&last_event, &event.ts);
                if (since_last > DEBOUNCE_MS) {
                    last_event = event.ts;
                    pulse_count++;
                }
            }
        }

        /* ---- Compute and log RPM ----------------------------------- */
        double rpm = ((double)pulse_count / (double)SAMPLE_PERIOD_S) * 60.0;

        if (log_rpm(log_fp, rpm) != 0) {
            fprintf(stderr, "Warning: failed to log RPM data.\n");
        }

        printf("RPM: %.2f\n", rpm);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            perror("fclose");
        }
    }
    return ret;
}

