#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define YF_S201_PULSES_PER_LITER 450.0
#define KP                 1.0

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_file = NULL;
static double g_target_flow_rate = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

static double calculate_flow_rate(int pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return (double)pulses / YF_S201_PULSES_PER_LITER / interval_sec;
}

static int set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > PWM_RANGE) position = PWM_RANGE;
    if (gpioPWM(VALVE_PWM_PIN, position) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for position %d\n", position);
        return -1;
    }
    return 0;
}

static int control_valve(double flow_rate, double target_flow_rate) {
    double error = target_flow_rate - flow_rate;
    int position = (int)(KP * error);
    if (position < 0) position = 0;
    if (position > PWM_RANGE) position = PWM_RANGE;
    return set_valve_position(position);
}

static int log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    long timestamp_ms = (long)(ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    if (fprintf(g_log_file, "%ld,%.4f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf to log file");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush log file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_target_flow_rate = atof(optarg);
                if (g_target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: target flow rate must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (g_target_flow_rate == 0.0) {
        fprintf(stderr, "Error: target flow rate must be specified with -t\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO %d\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to enable valve on GPIO %d\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error opening flow_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "# timestamp_ms,flow_rate_L_min,valve_position\n");
    fflush(g_log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target: %.2f L/min. Press Ctrl+C to exit.\n", g_target_flow_rate);

    while (g_running) {
        int pulses = g_pulse_count;
        g_pulse_count = 0;

        double flow_rate = calculate_flow_rate(pulses, (double)SAMPLE_INTERVAL_US / 1000000.0);

        if (control_valve(flow_rate, g_target_flow_rate) < 0) {
            fprintf(stderr, "Warning: valve control failed\n");
        }

        int valve_position = gpioGetPWMdutycycle(VALVE_PWM_PIN);
        if (valve_position < 0) {
            fprintf(stderr, "Warning: failed to read valve position\n");
            valve_position = 0;
        }

        if (log_data(flow_rate, valve_position) < 0) {
            fprintf(stderr, "Warning: failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

