/*
 * Two-factor authentication door access control for Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - YM-180 electromagnetic lock actuators on GPIO 17 and GPIO 27.
 *     Normally engaged (HIGH).  Disengage = LOW for 5 s, then re-engage.
 *   - YL-180 RFID reader on SPI channel 0, 100 kHz.
 *   - Button on GPIO 22 (active-low, internal pull-up, 50 ms debounce).
 *
 * Build:  gcc -O2 -Wall -o door_access door_access.c -lpigpio -lrt
 * Run:    sudo ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define LOCK_PIN_1          17
#define LOCK_PIN_2          27
#define BUTTON_PIN          22

#define SPI_CHANNEL         0
#define SPI_SPEED           100000          /* 100 kHz */
#define SPI_FLAGS           0               /* mode 0, active-low CS handled by pigpio */

#define VALID_TAG_LEN       10
static const uint8_t VALID_TAG[VALID_TAG_LEN] = {
    0x01, 0x02, 0x03, 0x04, 0x05,
    0x06, 0x07, 0x08, 0x09, 0x0A
};

#define LOG_FILE            "/var/log/door_access.log"
#define DEBOUNCE_US         50000           /* 50 ms */
#define UNLOCK_DURATION_US  5000000         /* 5 s  */
#define POLL_DELAY_US       10000           /* 10 ms */
#define SPI_READ_RETRIES    3
#define SPI_READ_DELAY_US   100000          /* 100 ms between retries */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;
static int                   g_spi_h   = -1;

/* --------------------------- Function prototypes -------------------------- */

static void  log_event(const char *msg);
static void  cleanup(void);
static void  signal_handler(int sig);
static int   init_gpio(void);
static int   init_spi(void);
static int   read_rfid_tag(uint8_t *tag, size_t len);
static int   is_button_pressed(void);
static void  disengage_lock(int pin);
static void  engage_lock(int pin);
static int   authenticate(void);

/* ------------------------------- Logging --------------------------------- */

static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_fp, "%s %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------ Cleanup ---------------------------------- */

static void cleanup(void)
{
    /* Release both locks to the engaged (HIGH) state. */
    if (g_spi_h >= 0) {
        engage_lock(LOCK_PIN_1);
        engage_lock(LOCK_PIN_2);
        spiClose(g_spi_h);
        g_spi_h = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ GPIO init -------------------------------- */

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LOCK_PIN_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output.\n", LOCK_PIN_1);
        return -1;
    }
    if (gpioSetMode(LOCK_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output.\n", LOCK_PIN_2);
        return -1;
    }
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as input.\n", BUTTON_PIN);
        return -1;
    }

    /* Locks start engaged (HIGH). */
    if (gpioWrite(LOCK_PIN_1, 1) < 0 || gpioWrite(LOCK_PIN_2, 1) < 0) {
        fprintf(stderr, "Error: cannot initialise lock pins HIGH.\n");
        return -1;
    }

    /* Button with internal pull-up so it reads HIGH when released. */
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: cannot set pull-up on GPIO %d.\n", BUTTON_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------ SPI init --------------------------------- */

static int init_spi(void)
{
    g_spi_h = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_h < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_h);
        return -1;
    }
    return 0;
}

/* ---------------------------- RFID read ---------------------------------- */

/*
 * YL-180 returns 10 bytes on a valid tag, or a 10-byte all-zero frame
 * when no tag is present.  We treat any read that returns a non-zero
 * frame as a valid tag.
 */
static int read_rfid_tag(uint8_t *tag, size_t len)
{
    if (!tag || len < VALID_TAG_LEN)
        return -1;

    uint8_t rx[VALID_TAG_LEN];
    memset(rx, 0, sizeof(rx));

    for (int attempt = 0; attempt < SPI_READ_RETRIES; ++attempt) {
        int n = spiXfer(g_spi_h, (char *)rx, (char *)rx, VALID_TAG_LEN);
        if (n == VALID_TAG_LEN) {
            memcpy(tag, rx, VALID_TAG_LEN);
            return 0;                       /* success */
        }
        if (n < 0) {
            log_event("SPI transfer error.");
            return -1;
        }
        if (attempt < SPI_READ_RETRIES - 1)
            gpioDelay(SPI_READ_DELAY_US);
    }

    log_event("RFID read failed after retries (no tag present).");
    return -1;
}

/* --------------------------- Button press -------------------------------- */

static int is_button_pressed(void)
{
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();

    if (gpioRead(BUTTON_PIN) == 0) {          /* active-low */
        if (now - last_tick > DEBOUNCE_US) {
            last_tick = now;
            return 1;
        }
    } else {
        last_tick = now;                       /* reset on release */
    }
    return 0;
}

/* --------------------------- Lock control -------------------------------- */

static void disengage_lock(int pin)
{
    if (gpioWrite(pin, 0) < 0)
        log_event("Warning: failed to drive lock LOW.");
}

static void engage_lock(int pin)
{
    if (gpioWrite(pin, 1) < 0)
        log_event("Warning: failed to drive lock HIGH.");
}

/* --------------------------- Authentication ------------------------------ */

static int authenticate(void)
{
    uint8_t tag[VALID_TAG_LEN];

    log_event("Authenticating...");

    /* --- Phase 1: RFID tag --- */
    if (read_rfid_tag(tag, sizeof(tag)) != 0) {
        log_event("Authentication failed: invalid RFID tag.");
        return -1;
    }

    /* Compare the 10-byte tag against the valid sequence. */
    if (memcmp(tag, VALID_TAG, VALID_TAG_LEN) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Authentication failed: tag mismatch (got 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X).",
                 tag[0], tag[1], tag[2], tag[3], tag[4],
                 tag[5], tag[6], tag[7], tag[8], tag[9]);
        log_event(msg);
        return -1;
    }

    log_event("RFID tag accepted.");

    /* --- Phase 2: button press --- */
    log_event("Waiting for button press...");

    while (g_running && !is_button_pressed())
        gpioDelay(POLL_DELAY_US);

    if (!g_running) {
        log_event("Authentication interrupted by signal.");
        return -1;
    }

    log_event("Button pressed.");
    return 0;
}

/* --------------------------------- main ---------------------------------- */

int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open log file. */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio and GPIO. */
    if (init_gpio() != 0) {
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Initialise SPI. */
    if (init_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Door access control system started.");

    /* Main loop. */
    while (g_running) {
        if (authenticate() == 0) {
            log_event("Access granted.");
            disengage_lock(LOCK_PIN_1);
            disengage_lock(LOCK_PIN_2);
            gpioDelay(UNLOCK_DURATION_US);
            engage_lock(LOCK_PIN_1);
            engage_lock(LOCK_PIN_2);
            log_event("Access revoked.");
        } else if (g_running) {
            /* If not interrupted, wait briefly before retrying. */
            gpioDelay(POLL_DELAY_US);
        }
    }

    log_event("Shutting down.");
    cleanup();
    return EXIT_SUCCESS;
}

