#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define SAMPLE_TIME_MS 100
#define PPM 600

#define KP 1.0
#define KI 0.1
#define KD 0.01

#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static pthread_mutex_t enc1_mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t enc2_mtx = PTHREAD_MUTEX_INITIALIZER;
static long enc1_count = 0;
static long enc2_count = 0;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ena_line = NULL;
static struct gpiod_line *in1_line = NULL;
static struct gpiod_line *in2_line = NULL;
static struct gpiod_line *enb_line = NULL;
static struct gpiod_line *in3_line = NULL;
static struct gpiod_line *in4_line = NULL;
static struct gpiod_line *enc1_a_line = NULL;
static struct gpiod_line *enc1_b_line = NULL;
static struct gpiod_line *enc2_a_line = NULL;
static struct gpiod_line *enc2_b_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_motor_speed(struct gpiod_line *en, struct gpiod_line *in1, struct gpiod_line *in2, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int on_us = (PWM_PERIOD_US * duty_percent) / 100;
    int off_us = PWM_PERIOD_US - on_us;
    if (on_us > 0) {
        gpiod_line_set_value(in1, 1);
        gpiod_line_set_value(in2, 0);
        gpiod_line_set_value(en, 1);
        usleep(on_us);
    }
    if (off_us > 0) {
        gpiod_line_set_value(en, 0);
        usleep(off_us);
    }
}

static void *encoder1_thread(void *arg) {
    (void)arg;
    struct gpiod_line_event event;
    while (running) {
        int ret = gpiod_line_event_wait(enc1_a_line, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Encoder1 event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        if (gpiod_line_event_read(enc1_a_line, &event) < 0) {
            fprintf(stderr, "Encoder1 event read error: %s\n", strerror(errno));
            continue;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int b = gpiod_line_get_value(enc1_b_line);
            if (b < 0) continue;
            pthread_mutex_lock(&enc1_mtx);
            if (b == 0) enc1_count++;
            else enc1_count--;
            pthread_mutex_unlock(&enc1_mtx);
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            int b = gpiod_line_get_value(enc1_b_line);
            if (b < 0) continue;
            pthread_mutex_lock(&enc1_mtx);
            if (b == 1) enc1_count++;
            else enc1_count--;
            pthread_mutex_unlock(&enc1_mtx);
        }
    }
    return NULL;
}

static void *encoder2_thread(void *arg) {
    (void)arg;
    struct gpiod_line_event event;
    while (running) {
        int ret = gpiod_line_event_wait(enc2_a_line, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Encoder2 event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        if (gpiod_line_event_read(enc2_a_line, &event) < 0) {
            fprintf(stderr, "Encoder2 event read error: %s\n", strerror(errno));
            continue;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int b = gpiod_line_get_value(enc2_b_line);
            if (b < 0) continue;
            pthread_mutex_lock(&enc2_mtx);
            if (b == 0) enc2_count++;
            else enc2_count--;
            pthread_mutex_unlock(&enc2_mtx);
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            int b = gpiod_line_get_value(enc2_b_line);
            if (b < 0) continue;
            pthread_mutex_lock(&enc2_mtx);
            if (b == 1) enc2_count++;
            else enc2_count--;
            pthread_mutex_unlock(&enc2_mtx);
        }
    }
    return NULL;
}

static double calculate_pid(double target, double current, double *integral, double *prev_error, double kp, double ki, double kd) {
    double error = target - current;
    *integral += error;
    double derivative = error - *prev_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    return output;
}

static void log_data(double rpm1, double rpm2, double pid1, double pid2, double p1, double i1, double d1, double p2, double i2, double d2) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            rpm1, rpm2, pid1, pid2, p1, i1, d1, p2, i2, d2);
    fflush(log_file);
}

static void cleanup(void) {
    if (ena_line) gpiod_line_set_value(ena_line, 0);
    if (in1_line) gpiod_line_set_value(in1_line, 0);
    if (in2_line) gpiod_line_set_value(in2_line, 0);
    if (enb_line) gpiod_line_set_value(enb_line, 0);
    if (in3_line) gpiod_line_set_value(in3_line, 0);
    if (in4_line) gpiod_line_set_value(in4_line, 0);
    if (ena_line) gpiod_line_release(ena_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (enb_line) gpiod_line_release(enb_line);
    if (in3_line) gpiod_line_release(in3_line);
    if (in4_line) gpiod_line_release(in4_line);
    if (enc1_a_line) gpiod_line_release(enc1_a_line);
    if (enc1_b_line) gpiod_line_release(enc1_b_line);
    if (enc2_a_line) gpiod_line_release(enc2_a_line);
    if (enc2_b_line) gpiod_line_release(enc2_b_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
