#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_TOUCHTH_0 + 2 * i, 0x0F) < 0) return -1;
        if (mpr121_write_reg(MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0) return -1;
    }

    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int mpr121_read_touch_status(uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading touch status: %d\n", rc);
        return -1;
    }
    *status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (!fp) {
        perror("Error opening relay_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Relay GPIO %d: %s\n", s, RELAY_GPIO, state ? "ACTIVATED" : "DEACTIVATED");
    fclose(fp);
}

static void cleanup(void) {
    if (relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("MPR121 relay control running. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch_status & 0x0FFF) {
            if (!relay_state) {
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
                log_relay_state(1);
            }
        } else {
            if (relay_state) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                log_relay_state(0);
            }
        }

        gpioDelay(50000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

