#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE1_PIN 17
#define VALVE2_PIN 18
#define GPIO_CHIP_NAME "gpiochip0"
#define LOG_FILE "valve_log.txt"
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_SEC 5
#define VALVE2_PAUSE_SEC 10

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        perror("Error writing to log file");
    }
    fflush(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    valve1_line = gpiod_chip_get_line(chip, VALVE1_PIN);
    if (!valve1_line) {
        perror("Failed to get GPIO line for Valve 1");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    valve2_line = gpiod_chip_get_line(chip, VALVE2_PIN);
    if (!valve2_line) {
        perror("Failed to get GPIO line for Valve 2");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(valve1_line, "valve_control", 0) < 0) {
        perror("Failed to request Valve 1 line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(valve2_line, "valve_control", 0) < 0) {
        perror("Failed to request Valve 2 line as output");
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void activate_valve(struct gpiod_line *line, int duration_ms, const char *valve_name) {
    char log_message[128];
    snprintf(log_message, sizeof(log_message), "%s activated for %d ms", valve_name, duration_ms);
    log_event(log_message);
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to activate valve");
        return;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to deactivate valve");
    }
    snprintf(log_message, sizeof(log_message), "%s deactivated", valve_name);
    log_event(log_message);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }
    log_event("Program started");
    while (program_running) {
        activate_valve(valve1_line, VALVE1_DURATION_MS, "Valve 1");
        if (!program_running) break;
        sleep(VALVE1_PAUSE_SEC);
        if (!program_running) break;
        activate_valve(valve2_line, VALVE2_DURATION_MS, "Valve 2");
        if (!program_running) break;
        sleep(VALVE2_PAUSE_SEC);
    }
    log_event("Program stopped");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    return 0;
}

