    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

int mpr121_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

int mpr121_init(void) {
    if (mpr121_write_reg(0x80, 0x00) < 0) return -1; // Stop mode
    if (mpr121_write_reg(0x2B, 0x01) < 0) return -1; // Electrode config
    if (mpr121_write_reg(0x2C, 0x01) < 0) return -1; // Filter config
    if (mpr121_write_reg(0x5B, 0x01) < 0) return -1; // Debounce
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(0x41 + 2*i, 0x10) < 0) return -1; // Touch threshold
        if (mpr121_write_reg(0x42 + 2*i, 0x0A) < 0) return -1; // Release threshold
    }
    if (mpr121_write_reg(0x5E, 0x20) < 0) return -1; // Run mode, ELE_EN=1
    gpioDelay(100000); // 100 ms stabilization
    return 0;
}

int read_touch_status(void) {
    int lo = mpr121_read_reg(0x00);
    if (lo < 0) return -1;
    int hi = mpr121_read_reg(0x01);
    if (hi < 0) return -1;
    return (hi << 8) | lo;
}

