#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ms, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        log_event("Program exiting, cleaning up.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR GPIO %d as input\n", PIR_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on PIR GPIO %d\n", PIR_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO %d as output\n", RELAY_GPIO);
