#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200

typedef struct {
    int duty_cycle;
    int duration_ms;
} MotorStep;

typedef struct {
    MotorStep *steps;
    int num_steps;
} HapticPattern;

static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

static int generate_random_number(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

static HapticPattern *generate_haptic_pattern(int num_steps) {
    HapticPattern *pattern = malloc(sizeof(HapticPattern));
    if (pattern == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for HapticPattern\n");
        return NULL;
    }
    pattern->steps = malloc(num_steps * sizeof(MotorStep));
    if (pattern->steps == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for MotorSteps\n");
        free(pattern);
        return NULL;
    }
    pattern->num_steps = num_steps;
    for (int i = 0; i < num_steps; i++) {
        pattern->steps[i].duty_cycle = generate_random_number(MIN_DUTY, MAX_DUTY);
        pattern->steps[i].duration_ms = generate_random_number(MIN_DURATION_MS, MAX_DURATION_MS);
    }
    return pattern;
}

