    if (pattern == NULL || pattern->steps == NULL) {
        fprintf(stderr, "Error: Invalid HapticPattern\n");
        return -1;
    }
    for (int i = 0; i < pattern->num_steps; i++) {
        if (shutdown_requested) {
            return 0;
        }
        if (gpioPWM(MOTOR1_PIN, pattern->steps[i].duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", MOTOR1_PIN);
            return -1;
        }
        if (gpioPWM(MOTOR2_PIN, pattern->steps[i].duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", MOTOR2_PIN);
            return -1;
        }
        gpioDelay(pattern->steps[i].duration_ms * 1000);
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
}

