#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN    4
#define HX711_CLOCK_PIN   17
#define SOLENOID_PIN      27

#define CALIBRATION_FILE  "calibration.txt"
#define LOG_FILE          "weight_log.txt"

#define NUM_CAL_READINGS  100
#define WEIGHT_THRESHOLD  10.0
#define HX711_TIMEOUT_US  500000
#define LOOP_DELAY_US     500000

static volatile sig_atomic_t running = 1;

static double scale_factor = 1.0;
static double offset       = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *raw_value) {
    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;

    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    uint32_t start = gpioTick();
    while (gpioRead(data_pin) == 1) {
        if ((gpioTick() - start) > HX711_TIMEOUT_US) {
            return -2;
        }
        gpioDelay(100);
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = (value << 1) | gpioRead(data_pin);
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    *raw_value = value;
    return 0;
}

static double convert_to_weight(long raw_value, double scale, double off) {
    return (double)raw_value * scale - off;
}

static int load_calibration(const char *filename, double *scale, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open calibration file '%s'. Using defaults.\n", filename);
        return -1;
    }
    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration file format. Using defaults.\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int save_calibration(const char *filename, double scale, double offset) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1;
    }
    fprintf(fp, "%.6f %.6f\n", scale, offset);
    fclose(fp);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *scale, double *offset) {
    long sum = 0;
    int valid = 0;
    for (int i = 0; i < NUM_CAL_READINGS; i++) {
        long raw;
        if (read_hx711(data_pin, clock_pin, &raw) == 0) {
            sum += raw;
            valid++;
        }
        gpioDelay(10000);
    }
    if (valid == 0) {
        fprintf(stderr, "Error: No valid HX711 readings during calibration.\n");
        return -1;
    }
    *offset = (double)sum / valid;
    return 0;
}

static int log_weight(const char *filename, double weight) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", filename);
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Weight: %.2f kg\n", ts, weight);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (load_calibration(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) == 0) {
            save_calibration(CALIBRATION_FILE, scale_factor, offset);
            printf("Calibration complete. Offset: %.6f\n", offset);
        } else {
            fprintf(stderr, "Error: Calibration failed.\n");
            gpioTerminate();
            return 1;
        }
    } else {
        printf("Calibration loaded. Scale: %.6f, Offset: %.6f\n", scale_factor, offset);
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("System started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw) != 0) {
            fprintf(stderr, "Warning: HX711 read failed (timeout or error).\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = convert_to_weight(raw, scale_factor, offset);
        printf("Raw: %ld, Weight: %.2f kg\n", raw, weight);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Threshold exceeded. Lock engaged.\n");
        } else {
            gpioWrite(SOLENOID_PIN, 0);
            printf("Weight below threshold. Lock released.\n");
        }

        log_weight(LOG_FILE, weight);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

