        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) == 0) {
            save_calibration(CALIBRATION_FILE, scale_factor, offset);
            printf("Calibration complete. Offset: %.6f\n", offset);
        } else {
            fprintf(stderr, "Error: Calibration failed.\n");
            gpioTerminate();
            return 1;
        }
    } else {
        printf("Calibration loaded. Scale: %.6f, Offset: %.6f\n", scale_factor, offset);
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("System started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw) != 0) {
            fprintf(stderr, "Warning: HX711 read failed (timeout or error).\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = convert_to_weight(raw, scale_factor, offset);
        printf("Raw: %ld, Weight: %.2f kg\n", raw, weight);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Threshold exceeded. Lock engaged.\n");
        } else {
            gpioWrite(SOLENOID_PIN, 0);
            printf("Weight below threshold. Lock released.\n");
        }

        log_weight(LOG_FILE, weight);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

