        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

static int read_hx711(int dt_pin, int sck_pin, int32_t *raw_value) {
    if (gpioSetMode(dt_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(sck_pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(sck_pin, 0) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(dt_pin) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: DT stuck high\n");
            return -1;
        }
        gpioDelay(100);
    }

