        if (gpioWrite(sck_pin, 0) < 0) return -1;
        gpioDelay(1);
        if (gpioRead(dt_pin) == 1) {
            value |= 1;
        }
    }

    if (gpioWrite(sck_pin, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(sck_pin, 0) < 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }
    *raw_value = value;
    return 0;
}

static double calculate_weight(int32_t raw_value, double scale_factor) {
    return (double)raw_value / scale_factor;
}

