#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN    4
#define HX711_CLOCK_PIN   17
#define SOLENOID_PIN      27

#define CALIBRATION_FILE  "calibration.txt"
#define SECURITY_LOG_FILE "security.log"

#define WEIGHT_THRESHOLD  5.0
#define LOCK_DURATION_US  5000000  /* 5 seconds in microseconds */
#define HX711_TIMEOUT_US  100000   /* 100 ms timeout for data ready */
#define CLOCK_HIGH_US     1
#define CLOCK_LOW_US      1

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read a 24-bit signed value from the HX711.
 * Returns 0 on success, -1 on timeout.
 */
static int hx711_read(int data_pin, int clock_pin, long *out_value) {
    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;

    /* Ensure clock is low before starting */
    if (gpioWrite(clock_pin, 0) < 0) return -1;

    /* Wait for data line to go low (data ready), with timeout */
    uint32_t start = gpioTick();
    while (gpioRead(data_pin) == 1) {
        if ((gpioTick() - start) > HX711_TIMEOUT_US) {
            return -1;  /* Timeout: sensor not responding */
        }
        gpioDelay(10);
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(clock_pin, 1) < 0) return -1;
        gpioDelay(CLOCK_HIGH_US);

        value <<= 1;
        if (gpioRead(data_pin) == 1) {
            value |= 1;
        }

        if (gpioWrite(clock_pin, 0) < 0) return -1;
        gpioDelay(CLOCK_LOW_US);
    }

    /* 25th pulse for gain 128 */
    if (gpioWrite(clock_pin, 1) < 0) return -1;
    gpioDelay(CLOCK_HIGH_US);
    if (gpioWrite(clock_pin, 0) < 0) return -1;
    gpioDelay(CLOCK_LOW_US);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    *out_value = value;
    return 0;
}

static double hx711_get_weight(long raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

static int load_calibration_factor(const char *filename, double *calibration_factor) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening calibration file for reading");
        return -1;
    }

    if (fscanf(fp, "%lf", calibration_factor) != 1) {
        fprintf(stderr, "Error: calibration file does not contain a valid number.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int save_calibration_factor(const char *filename, double calibration_factor) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening calibration file for writing");
        return -1;
    }

    if (fprintf(fp, "%lf", calibration_factor) < 0) {
        perror("Error writing to calibration file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int calibrate_load_cell(const char *filename, double *calibration_factor) {
    printf("Calibrating load cell...\n");
    printf("Place a known weight on the load cell and enter the weight in kg: ");
    fflush(stdout);

    double known_weight;
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Calibration failed.\n");
        return -1;
    }

    printf("Reading raw value from HX711...\n");
    long raw_value;
    if (hx711_read(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
        fprintf(stderr, "Error: HX711 read failed during calibration.\n");
        return -1;
    }

    *calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %lf\n", *calibration_factor);

    if (save_calibration_factor(filename, *calibration_factor) != 0) {
        fprintf(stderr, "Warning: Failed to save calibration factor to file.\n");
        return -1;
    }

    printf("Calibration complete. Calibration factor saved to %s\n", filename);
    return 0;
}

static int log_security_event(const char *filename, double weight) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening security log file");
        return -1;
    }

    if (fprintf(fp, "%s - Weight exceeded threshold: %.2f kg\n", timestamp, weight) < 0) {
        perror("Error writing to security log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing security log file");
        return -1;
    }

    return 0;
}

static int control_solenoid_lock(int pin, int duration_us) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting solenoid pin mode\n");
        return -1;
    }

    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error activating solenoid\n");
        return -1;
    }

    printf("Solenoid lock activated for %d seconds...\n", duration_us / 1000000);
    gpioDelay(duration_us);

    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid\n");
        return -1;
    }

    printf("Solenoid lock deactivated.\n");
    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* Ensure solenoid is deactivated */
    gpioWrite(SOLENOID_PIN, 0);

    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

