#include <gpiod.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_MS 2000
#define LOG_FILE "motion_log.txt"

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_fp = NULL;

static void cleanup_and_exit(int exit_code) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    exit(exit_code);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_fp, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line (PIR)");
        cleanup_and_exit(1);
    }
    if (gpiod_line_request_input(pir_line, "pir-sensor") < 0) {
        perror("gpiod_line_request_input (PIR)");
        cleanup_and_exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line (buzzer)");
        cleanup_and_exit(1);
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output (buzzer)");
        cleanup_and_exit(1);
