    while (running) {
        int val = gpiod_line_get_value(pir_line);
        if (val < 0) {
            perror("gpiod_line_get_value (PIR)");
            cleanup_and_exit(1);
        }

        if (val == 1) {
            printf("Motion detected!\n");
            if (log_motion_event() < 0) {
                cleanup_and_exit(1);
            }

            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                perror("gpiod_line_set_value (buzzer on)");
                cleanup_and_exit(1);
            }

            usleep(BUZZER_DURATION_MS * 1000);

            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                perror("gpiod_line_set_value (buzzer off)");
                cleanup_and_exit(1);
            }
        }

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup_and_exit(0);
    return 0;
}

