    if (!timeinfo) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_fp, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line (PIR)");
        cleanup_and_exit(1);
    }
    if (gpiod_line_request_input(pir_line, "pir-sensor") < 0) {
        perror("gpiod_line_request_input (PIR)");
        cleanup_and_exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line (buzzer)");
        cleanup_and_exit(1);
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output (buzzer)");
        cleanup_and_exit(1);
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        cleanup_and_exit(1);
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(pir_line);
        if (val < 0) {
            perror("gpiod_line_get_value (PIR)");
            cleanup_and_exit(1);
        }

        if (val == 1) {
            printf("Motion detected!\n");
            if (log_motion_event() < 0) {
                cleanup_and_exit(1);
            }

            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                perror("gpiod_line_set_value (buzzer on)");
                cleanup_and_exit(1);
            }

            usleep(BUZZER_DURATION_MS * 1000);

            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                perror("gpiod_line_set_value (buzzer off)");
                cleanup_and_exit(1);
            }
        }

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup_and_exit(0);
    return 0;
}

