/*
 * Timed watering system for Raspberry Pi 3 Model B+
 * Uses libgpiod to drive a Parker Hannifin Series 9 solenoid valve
 * through a relay module connected to GPIO18 (BCM).
 *
 * Build: gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:   ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define VALVE_LINE_OFFSET 18          /* BCM 18 */
#define CONFIG_FILE      "watering.conf"
#define MAX_DURATION     3600         /* seconds */
#define MIN_DURATION     1

static volatile sig_atomic_t g_stop = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configuration                                                       */
/* ------------------------------------------------------------------ */
static int read_duration(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (ferror(fp))
            fprintf(stderr, "Error reading config file: %s\n",
                    strerror(errno));
        else
            fprintf(stderr, "Config file is empty\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing newline */
    line[strcspn(line, "\r\n")] = '\0';

    /* Expected format: duration=<integer> */
    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Config file format error: expected 'duration=<integer>', got '%s'\n",
                line);
        return -1;
    }

    char *val = eq + 1;
    char *endptr = NULL;
    errno = 0;
    long v = strtol(val, &endptr, 10);
    if (errno == ERANGE || endptr == val) {
        fprintf(stderr, "Config file value is not an integer: '%s'\n", val);
        return -1;
    }
    if (v < MIN_DURATION || v > MAX_DURATION) {
        fprintf(stderr, "Duration %ld out of range [%d, %d]\n",
                v, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_valve(struct gpiod_line *line, int on)
{
    int ret = gpiod_line_set_value(line, on ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set valve %s: %s\n",
                on ? "ON" : "OFF", strerror(errno));
        return -1;
    }
    printf("Valve %s\n", on ? "ON" : "OFF");
    return 0;
}

/*
 * Sleep that is interruptible by signals.
 * Returns 0 if the full duration elapsed, non-zero if interrupted.
 */
static int sleep_interruptible(unsigned int seconds)
{
    unsigned int remaining = seconds;
    while (remaining > 0 && !g_stop) {
        remaining = sleep(remaining);
    }
    return (remaining > 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = 0;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    if (read_duration(CONFIG_FILE, &duration) != 0)
        goto cleanup;

    printf("Watering duration: %d seconds\n", duration);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, VALVE_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                VALVE_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request output, default value 0 (valve off), no pull, no consumer */
    if (gpiod_line_request_output(line, "watering", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                VALVE_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Valve OFF (initial state)\n");

    if (set_valve(line, 1) != 0)
        goto cleanup;

    if (sleep_interruptible(duration) != 0) {
        fprintf(stderr, "Interrupted during watering — turning valve off\n");
    }

    if (set_valve(line, 0) != 0)
        goto cleanup;

    printf("Watering complete\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

