#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR_LEFT   4
#define SENSOR_MID    17
#define SENSOR_RIGHT  27

#define MOTOR_LEFT_PWM  22
#define MOTOR_LEFT_DIR  23
#define MOTOR_RIGHT_PWM 24
#define MOTOR_RIGHT_DIR 25

/* ---- Control parameters ---- */
#define BASE_SPEED      150   /* 0..255 */
#define TURN_FACTOR     0.5f  /* 0..1  */
#define PWM_FREQ_HZ     1000  /* 1 kHz */
#define PWM_RANGE       255
#define LOOP_DELAY_US   10000 /* 10 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Read a sensor (active-low: 0 = object detected) ---- */
static int read_sensor(int gpio) {
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n", gpio, pigpio_error(v));
        return -1;
    }
    return (v == 0) ? 1 : 0;
}

/* ---- Drive one motor: speed in [0, 255], direction 0=forward, 1=backward ---- */
static int drive_motor(int pwm_pin, int dir_pin, int speed, int direction) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (gpioWrite(dir_pin, direction) < 0) {
        fprintf(stderr, "gpioWrite failed on dir GPIO %d\n", dir_pin);
        return -1;
    }
    if (gpioPWM(pwm_pin, speed) < 0) {
        fprintf(stderr, "gpioPWM failed on PWM GPIO %d\n", pwm_pin);
        return -1;
    }
    return 0;
}

/* ---- Stop both motors ---- */
static int stop_motors(void) {
    int rc = 0;
    rc |= drive_motor(MOTOR_LEFT_PWM,  MOTOR_LEFT_DIR,  0, 0);
    rc |= drive_motor(MOTOR_RIGHT_PWM, MOTOR_RIGHT_DIR, 0, 0);
    return rc;
}

/* ---- Log one control cycle ---- */
static void log_cycle(int sl, int sm, int sr, int ls, int rs) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t == NULL) {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }
    fprintf(g_log, "%s, SensorLeft=%d, SensorMid=%d, SensorRight=%d, LeftSpeed=%d, RightSpeed=%d\n",
            ts, sl, sm, sr, ls, rs);
    fflush(g_log);
}

/* ---- Initialize pigpio and configure pins ---- */
static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Sensor pins: input with pull-up (active-low) */
    int sensor_pins[] = {SENSOR_LEFT, SENSOR_MID, SENSOR_RIGHT};
    for (size_t i = 0; i < sizeof(sensor_pins)/sizeof(sensor_pins[0]); i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed on GPIO %d\n", sensor_pins[i]);
            return -1;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "gpioSetPullUpDown failed on GPIO %d\n", sensor_pins[i]);
            return -1;
        }
    }

    /* Motor PWM pins: output, 1 kHz, 255 range */
    int pwm_pins[] = {MOTOR_LEFT_PWM, MOTOR_RIGHT_PWM};
    for (size_t i = 0; i < sizeof(pwm_pins)/sizeof(pwm_pins[0]); i++) {
        if (gpioSetMode(pwm_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed on GPIO %d\n", pwm_pins[i]);
            return -1;
        }
        if (gpioSetPWMfrequency(pwm_pins[i], PWM_FREQ_HZ) < 0) {
            fprintf(stderr, "gpioSetPWMfrequency failed on GPIO %d\n", pwm_pins[i]);
            return -1;
        }
        if (gpioSetPWMrange(pwm_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "gpioSetPWMrange failed on GPIO %d\n", pwm_pins[i]);
            return -1;
        }
    }

    /* Motor direction pins: output, initially low */
    int dir_pins[] = {MOTOR_LEFT_DIR, MOTOR_RIGHT_DIR};
    for (size_t i = 0; i < sizeof(dir_pins)/sizeof(dir_pins[0]); i++) {
        if (gpioSetMode(dir_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed on GPIO %d\n", dir_pins[i]);
            return -1;
        }
        if (gpioWrite(dir_pins[i], 0) < 0) {
            fprintf(stderr, "gpioWrite failed on GPIO %d\n", dir_pins[i]);
            return -1;
        }
    }

    return 0;
}

/* ---- Cleanup: stop motors, close log, terminate pigpio ---- */
static void cleanup(void) {
    stop_motors();
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    /* Initialize GPIO */
    if (init_gpio() < 0) {
        return 1;
    }

    /* Open log file */
    g_log = fopen("trace_log.txt", "a");
    if (!g_log) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    fprintf(g_log, "--- Line-following session started ---\n");
    fflush(g_log);

    /* Main control loop */
    while (g_running) {
        int sl = read_sensor(SENSOR_LEFT);
        int sm = read_sensor(SENSOR_MID);
        int sr = read_sensor(SENSOR_RIGHT);

        if (sl < 0 || sm < 0 || sr < 0) {
            fprintf(stderr, "Sensor read error, stopping motors\n");
            stop_motors();
            log_cycle(-1, -1, -1, 0, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int left_speed, right_speed;

        if (sm == 1) {
            /* Middle sensor: straight */
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (sl == 1 && sr == 0) {
            /* Left sensor, right clear: turn right */
            left_speed  = (int)(BASE_SPEED * TURN_FACTOR);
            right_speed = BASE_SPEED;
        } else if (sr == 1 && sl == 0) {
            /* Right sensor, left clear: turn left */
            left_speed  = BASE_SPEED;
            right_speed = (int)(BASE_SPEED * TURN_FACTOR);
        } else {
            /* No sensor: stop */
            left_speed  = 0;
            right_speed = 0;
        }

        /* Drive motors */
        if (drive_motor(MOTOR_LEFT_PWM,  MOTOR_LEFT_DIR,  left_speed,  0) < 0) {
            fprintf(stderr, "Failed to drive left motor\n");
        }
        if (drive_motor(MOTOR_RIGHT_PWM, MOTOR_RIGHT_DIR, right_speed, 0) < 0) {
            fprintf(stderr, "Failed to drive right motor\n");
        }

        /* Log */
        log_cycle(sl, sm, sr, left_speed, right_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    fprintf(g_log, "--- Line-following session stopped ---\n");
    fflush(g_log);
    cleanup();
    return 0;
}

