#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define POLL_INTERVAL_MS 1000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", message);
    }
    fclose(fp);
}

static int read_lux(int handle, int *lux_out) {
    char cmd = 0x10;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        log_event("Error writing to BH1750 (command 0x10)");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000);

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_event("Error reading from BH1750");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *lux_out = (int)(raw / 1.2);
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        log_event("Error writing to relay GPIO");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    log_event("Program started");

    while (running) {
        int lux = 0;
        if (read_lux(i2c_handle, &lux) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux: %d", lux);
            log_event(msg);

            if (lux < LUX_THRESHOLD && !relay_state) {
                control_relay(1);
                relay_state = 1;
            } else if (lux >= LUX_THRESHOLD && relay_state) {
                control_relay(0);
                relay_state = 0;
            }
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    control_relay(0);
    i2cClose(i2c_handle);
    gpioTerminate();
    log_event("Program terminated");
    return EXIT_SUCCESS;
}

