#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22

#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

#define DEBOUNCE_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d\n", pulse_width);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not register SIGINT handler\n");
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set LOCK_BUTTON %d as input\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set UNLOCK_BUTTON %d as input\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on LOCK_BUTTON %d\n", LOCK_BUTTON);
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on UNLOCK_BUTTON %d\n", UNLOCK_BUTTON);
    }

    if (set_servo_pulse(UNLOCKED_PULSE_WIDTH) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Door lock initialized. Unlocked. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Lock button pressed. Locking...\n");
            if (set_servo_pulse(LOCKED_PULSE_WIDTH) == 0) {
                printf("Door locked.\n");
            }
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlock button pressed. Unlocking...\n");
            if (set_servo_pulse(UNLOCKED_PULSE_WIDTH) == 0) {
                printf("Door unlocked.\n");
            }
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

