/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 * Uses libgpiod to pulse two Precision Microdrives 310-101 vibration motors.
 *
 * Wiring:
 *   Motor 1 driver gate -> GPIO17 (BCM)
 *   Motor 2 driver gate -> GPIO27 (BCM)
 *   Driver base (emitter/base) -> 3 V supply
 *   Driver collector -> GND
 *   Motor leads -> driver gate inputs
 *
 * Build: gcc -O2 -Wall -Wextra -o haptic haptic.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_PULSE_MS 200
#define MOTOR2_PULSE_MS 300

#define CONSUMER "haptic-feedback"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    while (ms > 0 && g_running) {
        unsigned int chunk = (ms > 100) ? 100 : ms;
        usleep(chunk * 1000U);
        ms -= chunk;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(MOTOR1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(MOTOR2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(MOTOR1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(MOTOR2)");
        goto cleanup;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(MOTOR1 ON)");
            break;
        }
        sleep_ms(MOTOR1_PULSE_MS);
        if (!g_running) break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(MOTOR1 OFF)");
            break;
        }

        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(MOTOR2 ON)");
            break;
        }
        sleep_ms(MOTOR2_PULSE_MS);
        if (!g_running) break;

        if (gpiod_line_set_value(line2, 0) < 0) {
