#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void publish_alert(void *zmq_ctx, const char *message) {
    void *socket = zmq_socket(zmq_ctx, ZMQ_PUB);
    if (!socket) {
        fprintf(stderr, "Error creating ZMQ socket: %s\n", zmq_strerror(errno));
        return;
    }
    if (zmq_bind(socket, ZMQ_ENDPOINT) != 0) {
        fprintf(stderr, "Error binding ZMQ socket: %s\n", zmq_strerror(errno));
        zmq_close(socket);
        return;
    }
    char topic[16] = "SOUND_ALERTS";
    if (zmq_send_multipart(socket, 2, (void *[]){ topic, (void *)message },
                           (const size_t[]){ strlen(topic), strlen(message) },
                           (const int[]){ 0, 0 }) != 0) {
        fprintf(stderr, "Error sending alert: %s\n", zmq_strerror(errno));
    }
    zmq_close(socket);
}

static void trigger_alarm(void *zmq_ctx, struct gpiod_line *led_line) {
    if (gpiod_line_set_value(led_line, 1) < 0) {
        fprintf(stderr, "Error setting LED on: %s\n", strerror(errno));
    }
    publish_alert(zmq_ctx, "ALERT: Sound detected!");
    sleep_ms(ALARM_DURATION_MS);
    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error setting LED off: %s\n", strerror(errno));
    }
}

static void sound_sensor_mode(void *zmq_ctx, struct gpiod_line *sound_line,
                              struct gpiod_line *led_line) {
    while (running) {
        int val = gpiod_line_get_value(sound_line);
        if (val < 0) {
            fprintf(stderr, "Error reading sound sensor: %s\n", strerror(errno));
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }
        if (val == 0) {
            trigger_alarm(zmq_ctx, led_line);
        }
        sleep_ms(POLL_INTERVAL_MS);
    }
}

static void alarm_node_mode(void *zmq_ctx) {
    void *socket = zmq_socket(zmq_ctx, ZMQ_SUB);
    if (!socket) {
        fprintf(stderr, "Error creating ZMQ socket: %s\n", zmq_strerror(errno));
        return;
    }
    if (zmq_setsockopt(socket, ZMQ_SUBSCRIBE, "SOUND_ALERTS", 13) != 0) {
        fprintf(stderr, "Error subscribing: %s\n", zmq_strerror(errno));
        zmq_close(socket);
        return;
    }
    if (zmq_connect(socket, "tcp://localhost:5555") != 0) {
        fprintf(stderr, "Error connecting to ZMQ: %s\n", zmq_strerror(errno));
        zmq_close(socket);
        return;
    }
    while (running) {
        char buffer[256];
        ssize_t n = zmq_recv(socket, buffer, sizeof(buffer) - 1, ZMQ_DONTWAIT);
        if (n > 0) {
            buffer[n] = '\0';
            printf("Received: %s\n", buffer);
        } else if (n < 0 && errno != EAGAIN) {
            fprintf(stderr, "Error receiving message: %s\n", zmq_strerror(errno));
        }
        sleep_ms(10);
    }
    zmq_close(socket);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!sound_line || !led_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
        fprintf(stderr, "Error requesting sound line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "alarm_led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line: %s\n", strerror(errno));
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    void *zmq_ctx = zmq_ctx_new();
    if (!zmq_ctx) {
        fprintf(stderr, "Error creating ZMQ context: %s\n", zmq_strerror(errno));
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        sound_sensor_mode(zmq_ctx, sound_line, led_line);
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        alarm_node_mode(zmq_ctx);
    } else {
        fprintf(stderr, "Invalid mode. Use sound_sensor or alarm_node.\n");
    }

    gpiod_line_release(sound_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    zmq_ctx_destroy(zmq_ctx);
    return EXIT_SUCCESS;
}

