#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define PULSE_BUFFER_SIZE 64
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "ir_decoder"
#define MQTT_TOPIC "ir/decoded"

#define NEC_HDR_MARK     9000
#define NEC_HDR_SPACE    4500
#define NEC_BIT_MARK     562
#define NEC_ONE_SPACE    1687
#define NEC_ZERO_SPACE   562
#define NEC_RPT_SPACE    2250
#define NEC_TOLERANCE    200

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_buffer[PULSE_BUFFER_SIZE];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static MQTTClient mqtt_client = NULL;
static MQTTClient_connectOptions mqtt_connect_opts = MQTTClient_connectOptions_initializer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int in_range(uint32_t val, uint32_t target, uint32_t tol) {
    return (val > target - tol) && (val < target + tol);
}

static int decode_nec(uint32_t *pulses, int count, uint32_t *address, uint32_t *command) {
    if (count < 34) return -1;

    if (!in_range(pulses[0], NEC_HDR_MARK, NEC_TOLERANCE) ||
        !in_range(pulses[1], NEC_HDR_SPACE, NEC_TOLERANCE)) {
        return -1;
    }

    uint32_t addr = 0, cmd = 0;
    for (int i = 0; i < 32; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= count) return -1;
        if (!in_range(pulses[idx], NEC_BIT_MARK, NEC_TOLERANCE)) return -1;

        uint32_t space = pulses[idx + 1];
        if (in_range(space, NEC_ONE_SPACE, NEC_TOLERANCE)) {
            addr <<= 1;
            cmd <<= 1;
            addr |= 1;
        } else if (in_range(space, NEC_ZERO_SPACE, NEC_TOLERANCE)) {
            addr <<= 1;
            cmd <<= 1;
        } else {
            return -1;
        }
    }

    uint8_t addr_low  = addr & 0xFF;
    uint8_t addr_high = (addr >> 8) & 0xFF;
    uint8_t cmd_low   = cmd & 0xFF;
    uint8_t cmd_high  = (cmd >> 8) & 0xFF;

    if ((uint8_t)(~addr_low) != cmd_low || (uint8_t)(~addr_high) != cmd_high) {
        return -1;
    }

    *address = addr;
    *command = cmd;
    return 0;
}

static void send_mqtt_message(uint32_t address, uint32_t command) {
    if (mqtt_client == NULL) return;

    char payload[128];
    snprintf(payload, sizeof(payload),
             "{\"ir_address\": %u, \"ir_command\": %u}", address, command);

    MQTTClient_message message = MQTTClient_message_initializer;
    message.payload = payload;
    message.payloadlen = (int)strlen(payload);
    message.qos = 0;
    message.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &message, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
    } else {
        syslog(LOG_INFO, "Sent MQTT message: %s", payload);
    }
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 0) return;

    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (pulse_count < PULSE_BUFFER_SIZE) {
        pulse_buffer[pulse_count++] = diff;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow, resetting");
        pulse_count = 0;
    }

    if (pulse_count >= 34) {
        uint32_t address, command;
        if (decode_nec((uint32_t *)pulse_buffer, pulse_count, &address, &command) == 0) {
            syslog(LOG_INFO, "Decoded NEC: address=0x%04X, command=0x%02X", address, command);
            send_mqtt_message(address, command);
        } else {
            syslog(LOG_ERR, "Invalid NEC frame");
        }
        pulse_count = 0;
    }
}

static int initialize_mqtt(void) {
    int rc = MQTTClient_create(&mqtt_client, MQTT_BROKER_ADDRESS,
                               MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT create failed: %s", MQTTClient_strerror(rc));
        return -1;
    }

    mqtt_connect_opts.keepAliveInterval = 20;
    mqtt_connect_opts.cleansession = 1;

    rc = MQTTClient_connect(mqtt_client, &mqtt_connect_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        mqtt_client = NULL;
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_mqtt() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    while (running) {
        sleep(1);
        MQTTClient_loop(mqtt_client, 20, 1);
    }

    syslog(LOG_INFO, "Shutting down...");
    gpioSetAlertFunc(IR_GPIO, NULL);
    gpioTerminate();

    if (mqtt_client != NULL) {
        MQTTClient_disconnect(mqtt_client, 1000);
        MQTTClient_destroy(&mqtt_client);
    }

    closelog();
    return EXIT_SUCCESS;
}

