#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS      4
#define I2C_BUS          "/dev/i2c-1"
#define BH1750_ADDR_BASE 0x23
#define BH1750_CMD_OT_H  0x20
#define CONV_TIME_MS     180
#define MULTICAST_ADDR   "239.255.255.250"
#define MULTICAST_PORT   5005

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int open_i2c_sensor(uint8_t addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed for 0x%02X: %s\n", I2C_BUS, addr, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static float read_lux(int fd, uint8_t addr) {
    uint8_t cmd = BH1750_CMD_OT_H;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(0x%02X) failed: %s\n", addr, strerror(errno));
        return NAN;
    }
    usleep(CONV_TIME_MS * 1000);
    uint8_t data[2];
    ssize_t r = read(fd, data, 2);
    if (r != 2) {
        fprintf(stderr, "read(0x%02X) failed: %s\n", addr, strerror(errno));
        return NAN;
    }
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    return (float)raw / 1.2f;
}

static int send_udp_multicast(const char *data) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }
    int ttl = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL)");
        close(sock);
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton(%s) failed\n", MULTICAST_ADDR);
        close(sock);
        return -1;
    }
    if (sendto(sock, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sock);
        return -1;
    }
    close(sock);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        fds[i] = -1;
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            uint8_t addr = BH1750_ADDR_BASE + i;
            if (fds[i] < 0) {
                fds[i] = open_i2c_sensor(addr);
                if (fds[i] < 0) {
                    fprintf(stderr, "Sensor %d (0x%02X) init failed; will retry next cycle\n", i + 1, addr);
                }
            }
        }

        char line[256];
        line[0] = '\0';
        for (int i = 0; i < NUM_SENSORS; i++) {
            uint8_t addr = BH1750_ADDR_BASE + i;
            float lux = NAN;
            if (fds[i] >= 0) {
                lux = read_lux(fds[i], addr);
                if (isnan(lux)) {
                    fds[i] = -1;
                }
            }
            char buf[64];
            if (isnan(lux)) {
                snprintf(buf, sizeof(buf), "%d,NaN", i + 1);
            } else {
                snprintf(buf, sizeof(buf), "%d,%.1f", i + 1, lux);
            }
            strncat(line, buf, sizeof(line) - strlen(line) - 1);
            if (i < NUM_SENSORS - 1) {
                strncat(line, ";", sizeof(line) - strlen(line) - 1);
            }
        }

        if (send_udp_multicast(line) < 0) {
            fprintf(stderr, "Failed to send multicast packet\n");
        }

        sleep(1);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (fds[i] >= 0) {
            close(fds[i]);
        }
    }
    return EXIT_SUCCESS;
}

