#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_zero(int fd)
{
    /* Zero-length write triggers a start condition only; no data payload. */
    if (write(fd, NULL, 0) < 0)
        return -1;
    return 0;
}

static int i2c_read_flow(int fd, uint16_t *raw)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf))
        return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_to_slpm(uint16_t raw)
{
    return ((float)raw - 3277.0f) * 0.1f;
}

static int log_flow(FILE *fp, float flow)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return -1;
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0)
        return -1;
    if (fprintf(fp, "%s, %.2f SLPM\n", ts, flow) < 0)
        return -1;
    if (fflush(fp) != 0)
        return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        uint16_t raw = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (i2c_write_zero(g_i2c_fd) < 0) {
                if (errno == ENXIO) {
                    fprintf(stderr, "Sensor absent (ENXIO) on attempt %d\n", attempt + 1);
                    break;
                }
                if (errno == EIO) {
                    fprintf(stderr, "I2C bus error (EIO) on attempt %d\n", attempt + 1);
                    break;
                }
                fprintf(stderr, "I2C write error (attempt %d): %s\n", attempt + 1, strerror(errno));
                msleep(RETRY_DELAY_MS);
                continue;
            }
            if (i2c_read_flow(g_i2c_fd, &raw) < 0) {
                if (errno == ENXIO) {
                    fprintf(stderr, "Sensor absent (ENXIO) on attempt %d\n", attempt + 1);
                    break;
                }
                if (errno == EIO) {
                    fprintf(stderr, "I2C bus error (EIO) on attempt %d\n", attempt + 1);
                    break;
                }
                fprintf(stderr, "I2C read error (attempt %d): %s\n", attempt + 1, strerror(errno));
                msleep(RETRY_DELAY_MS);
                continue;
            }
            ok = 1;
            break;
        }

        if (!ok) {
            fprintf(stderr, "Failed to read flow after %d attempts.\n", MAX_RETRIES);
            msleep(SAMPLE_PERIOD * 1000);
            continue;
        }

        raw &= 0x3FFF;
        float flow = convert_to_slpm(raw);

        if (log_flow(fp, flow) < 0) {
            perror("log_flow");
        }

        msleep(SAMPLE_PERIOD * 1000);
    }

    printf("\nShutting down...\n");
    if (fp) {
        fflush(fp);
        fclose(fp);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Airflow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

