    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return -1;
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0)
        return -1;
    if (fprintf(fp, "%s, %.2f SLPM\n", ts, flow) < 0)
        return -1;
    if (fflush(fp) != 0)
        return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        uint16_t raw = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (i2c_write_zero(g_i2c_fd) < 0) {
                if (errno == ENXIO) {
                    fprintf(stderr, "Sensor absent (ENXIO) on attempt %d\n", attempt + 1);
                    break;
                }
                if (errno == EIO) {
                    fprintf(stderr, "I2C bus error (EIO) on attempt %d\n", attempt + 1);
                    break;
                }
                fprintf(stderr, "I2C write error (attempt %d): %s\n", attempt + 1, strerror(errno));
                msleep(RETRY_DELAY_MS);
                continue;
            }
            if (i2c_read_flow(g_i2c_fd, &raw) < 0) {
                if (errno == ENXIO) {
                    fprintf(stderr, "Sensor absent (ENXIO) on attempt %d\n", attempt + 1);
                    break;
                }
                if (errno == EIO) {
                    fprintf(stderr, "I2C bus error (EIO) on attempt %d\n", attempt + 1);
                    break;
                }
                fprintf(stderr, "I2C read error (attempt %d): %s\n", attempt + 1, strerror(errno));
                msleep(RETRY_DELAY_MS);
                continue;
            }
            ok = 1;
            break;
        }

        if (!ok) {
            fprintf(stderr, "Failed to read flow after %d attempts.\n", MAX_RETRIES);
            msleep(SAMPLE_PERIOD * 1000);
            continue;
        }

        raw &= 0x3FFF;
        float flow = convert_to_slpm(raw);

        if (log_flow(fp, flow) < 0) {
            perror("log_flow");
        }

        msleep(SAMPLE_PERIOD * 1000);
    }

    printf("\nShutting down...\n");
    if (fp) {
        fflush(fp);
        fclose(fp);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Airflow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

