/*
 * AS7341 10-Channel Light/Color Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/i2c-1  (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Adafruit AS7341 (I2C addr 0x39)
 *
 * Build:  gcc -O2 -Wall -o spectral_logger spectral_logger.c
 * Run:    ./spectral_logger   (Ctrl-C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 register map (16-bit addresses, big-endian on bus) ---- */
#define AS7341_ADDR            0x39
#define AS7341_WHO_AM_I        0x24
#define AS7341_WHO_AM_I_VAL    0x19
#define AS7341_ENABLE          0x80
#define AS7341_CFG6            0xAF
#define AS7341_SP_EN           0x01
#define AS7341_PON             0x01
#define AS7341_F1_DATA0        0x60
#define AS7341_F1_DATA1        0x61
#define AS7341_F2_DATA0        0x62
#define AS7341_F2_DATA1        0x63
#define AS7341_F3_DATA0        0x64
#define AS7341_F3_DATA1        0x65
#define AS7341_F4_DATA0        0x66
#define AS7341_F4_DATA1        0x67
#define AS7341_F5_DATA0        0x68
#define AS7341_F5_DATA1        0x69
#define AS7341_F6_DATA0        0x6A
#define AS7341_F6_DATA1        0x6B
#define AS7341_F7_DATA0        0x6C
#define AS7341_F7_DATA1        0x6D
#define AS7341_F8_DATA0        0x6E
#define AS7341_F8_DATA1        0x6F
#define AS7341_CLEAR_DATA0     0x70
#define AS7341_CLEAR_DATA1     0x71
#define AS7341_NIR_DATA0       0x72
#define AS7341_NIR_DATA1       0x73

#define I2C_BUS                "/dev/i2c-1"
#define LOG_FILE               "spectral_log.csv"
#define SAMPLE_PERIOD_SEC      5

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register address.                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int reg_write8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "reg_write8(0x%02X, 0x%02X) failed: %s (wrote %zd)\n",
                reg, val, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register address.                       */
/* Returns 0 on success and stores value in *out; -1 on error.         */
/* ------------------------------------------------------------------ */
static int reg_read8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "reg_read8 write(0x%02X) failed: %s (wrote %zd)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "reg_read8 read(0x%02X) failed: %s (read %zd)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair (low at reg, high at reg+1).*/
/* Returns 0 on success and stores value in *out; -1 on error.         */
/* ------------------------------------------------------------------ */
static int reg_read16_le(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (reg_read8(fd, reg, &lo) < 0) return -1;
    if (reg_read8(fd, reg + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    uint8_t id;
    if (reg_read8(fd, AS7341_WHO_AM_I, &id) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (id != AS7341_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                id, AS7341_WHO_AM_I_VAL);
        return -1;
    }

    /* Power on */
    if (reg_write8(fd, AS7341_ENABLE, AS7341_PON) < 0) return -1;
    usleep(10000);  /* 10 ms settle */

    /* Configure SMUX for spectral readings (F1..F8, Clear, NIR) */
    if (reg_write8(fd, AS7341_CFG6, 0x00) < 0) return -1;
    usleep(10000);

    /* Enable spectral measurement */
    if (reg_write8(fd, AS7341_ENABLE, AS7341_PON | AS7341_SP_EN) < 0) return -1;
    usleep(10000);

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_all_channels(int fd, uint16_t ch[10])
{
    if (reg_read16_le(fd, AS7341_F1_DATA0, &ch[0]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_F2_DATA0, &ch[1]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_F3_DATA0, &ch[2]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_F4_DATA0, &ch[3]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_F5_DATA0, &ch[4]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_F6_DATA0, &ch[5]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_F7_DATA0, &ch[6]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_F8_DATA0, &ch[7]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_CLEAR_DATA0, &ch[8]) < 0) return -1;
    if (reg_read16_le(fd, AS7341_NIR_DATA0, &ch[9]) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Simplified lux approximation: sum of all 10 channels.               */
/* ------------------------------------------------------------------ */
static float calculate_lux(const uint16_t ch[10])
{
    float sum = 0.0f;
    for (int i = 0; i < 10; i++)
        sum += (float)ch[i];
    return sum;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const uint16_t ch[10], float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            ts,
            ch[0], ch[1], ch[2], ch[3], ch[4], ch[5], ch[6], ch[7], ch[8], ch[9],
            lux);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AS7341_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_init(g_i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp,
                "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
        fflush(g_log_fp);
    }

    printf("AS7341 logging to %s every %d s. Press Ctrl-C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_SEC);

    while (g_running) {
        uint16_t ch[10];
        if (read_all_channels(g_i2c_fd, ch) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
        } else {
            float lux = calculate_lux(ch);
            log_data(g_log_fp, ch, lux);
            printf("Lux: %.2f  (F1=%u F2=%u F3=%u F4=%u F5=%u F6=%u F7=%u F8=%u Clear=%u NIR=%u)\n",
                   lux, ch[0], ch[1], ch[2], ch[3], ch[4], ch[5], ch[6], ch[7], ch[8], ch[9]);
        }
        sleep(SAMPLE_PERIOD_SEC);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

