 * an Omron D7S over I2C using the Linux i2c-dev kernel interface and logs
 * timestamped g-values to seismic_data.csv at 1-second intervals.
 *
 * Build:  gcc -O2 -Wall -Wextra -o seismic_logger seismic_logger.c
 * Run:    ./seismic_logger [-a i2c_addr] [-i interval_sec] [-f filename]
 *
 * Defaults: address 0x37, interval 1 s, filename seismic_data.csv
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <getopt.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define D7S_DEFAULT_ADDR   0x37
#define D7S_REG_ACCEL_X_L  0x28
#define D7S_REG_ACCEL_X_H  0x29
#define D7S_REG_ACCEL_Y_L  0x2A
#define D7S_REG_ACCEL_Y_H  0x2B
#define D7S_REG_ACCEL_Z_L  0x2C
#define D7S_REG_ACCEL_Z_H  0x2D
#define D7S_REG_WHO_AM_I   0x0F
#define D7S_WHO_AM_I_VAL   0xD7
#define D7S_SCALE_FACTOR   0.000244f   /* g per LSB, ±8 g range */
#define I2C_BUS            "/dev/i2c-1"
#define MAX_RETRIES        3
#define RETRY_DELAY_MS     10
#define ERROR_LOG_FILE     "seismic_error.log"
#define DEFAULT_FILENAME   "seismic_data.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */

static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
        fclose(fp);
    }
    fprintf(stderr, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
}

static void log_data(float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_csv, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(g_csv);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */

/* Write a single byte to a register with retry. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &(uint8_t[2]) {reg, val}, 2) == 2)
            return 0;
        log_error("I2C write_reg8 failed");
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* Read N bytes starting at a register with retry. */
static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            log_error("I2C write (reg select) failed");
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len)
            return 0;
        log_error("I2C read failed");
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor                                                               */
/* ------------------------------------------------------------------ */

static int d7s_init(int fd)
{
    uint8_t who = 0;
    if (i2c_read_regs(fd, D7S_REG_WHO_AM_I, &who, 1) != 0) {
        log_error("Cannot read WHO_AM_I — sensor absent or bus error");
        return -1;
    }
    if (who != D7S_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, D7S_WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

static int d7s_read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_regs(fd, D7S_REG_ACCEL_X_L, buf, sizeof buf) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * D7S_SCALE_FACTOR;
    *y = (float)raw_y * D7S_SCALE_FACTOR;
    *z = (float)raw_z * D7S_SCALE_FACTOR;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                      */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int i2c_addr = D7S_DEFAULT_ADDR;
    int interval = 1;
    const char *filename = DEFAULT_FILENAME;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
        case 'a':
            i2c_addr = (int)strtol(optarg, NULL, 0);
            if (i2c_addr < 0x03 || i2c_addr > 0x77) {
                fprintf(stderr, "Invalid I2C address 0x%02X\n", i2c_addr);
                return EXIT_FAILURE;
            }
            break;
        case 'i':
            interval = atoi(optarg);
            if (interval <= 0) {
                fprintf(stderr, "Interval must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 'f':
            filename = optarg;
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-a i2c_addr] [-i interval_sec] [-f filename]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Open CSV header */
    g_csv = fopen(filename, "w");
    if (!g_csv) {
        log_error("Cannot open CSV file");
        return EXIT_FAILURE;
    }
    fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_error("Cannot open I2C bus");
        fclose(g_csv);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        log_error("Cannot set I2C slave address");
        close(g_i2c_fd);
        fclose(g_csv);
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (d7s_init(g_i2c_fd) != 0) {
        log_error("D7S initialization failed — sensor not present");
        close(g_i2c_fd);
        fclose(g_csv);
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic logger started: addr=0x%02X interval=%ds file=%s\n",
           i2c_addr, interval, filename);

    while (g_running) {
        float x, y, z;
        if (d7s_read_accel(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            log_error("Failed to read acceleration data");
        }
        sleep(interval);
    }

    /* Graceful cleanup */
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    if (g_csv)
        fclose(g_csv);

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

