#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define BH1750_ADDR     0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONT_HRES 0x10
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5000
#define READ_INTERVAL   1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_cmd(fd, BH1750_POWER_ON) < 0) return -1;
    if (i2c_write_cmd(fd, BH1750_CONT_HRES) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt IP_MULTICAST_TTL");
        close(sockfd);
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        close(sockfd);
        return -1;
    }
    if (sendto(sockfd, buffer, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_DEVICE);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (send_multicast(lux) < 0) {
                fprintf(stderr, "Failed to send multicast\n");
            }
        } else {
            fprintf(stderr, "Sensor read error, retrying in %d second(s)\n", READ_INTERVAL);
        }
        sleep(READ_INTERVAL);
    }

    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

