    }
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt IP_MULTICAST_TTL");
        close(sockfd);
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        close(sockfd);
        return -1;
    }
    if (sendto(sockfd, buffer, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_DEVICE);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (send_multicast(lux) < 0) {
                fprintf(stderr, "Failed to send multicast\n");
            }
        } else {
            fprintf(stderr, "Sensor read error, retrying in %d second(s)\n", READ_INTERVAL);
        }
        sleep(READ_INTERVAL);
    }

    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

