#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define BUFFER_SIZE 4096

/* TI mmWave SDK magic word: 0x0204 0x0306 0x0805 0x0709 (little-endian) */
static const uint8_t MAGIC_WORD[8] = {0x04,0x02,0x06,0x03,0x05,0x08,0x09,0x07};

/* TLV types for detected objects */
#define TLV_DETECTED_OBJECTS 1

/* Detected object structure (32 bytes, little-endian) */
typedef struct {
    uint16_t rangeIdx;
    uint16_t dopplerIdx;
    uint16_t peakVal;
    int16_t x;
    int16_t y;
    int16_t z;
} __attribute__((packed)) DetectedObject;

static int uart_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        return -1;
    }
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    fflush(csv_file);
    return 0;
}

static void log_data(int object_index, float range, float velocity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, object_index, range, velocity);
    fflush(csv_file);
}

/*
 * Synchronize on the 8-byte magic word.
 * Returns 0 on success, -1 on read error, -2 on timeout.
 */
static int sync_magic_word(uint8_t *buffer, int *index, int *bytes_read) {
    int magic_idx = 0;
    int timeout = 0;

    while (!terminate) {
        if (bytes_read[0] == 0) {
            int n = serRead(uart_handle, (char *)(buffer + *index), BUFFER_SIZE - *index);
            if (n < 0) {
                fprintf(stderr, "UART read error during sync\n");
                return -1;
            }
            if (n == 0) {
                if (++timeout > 100) {
                    fprintf(stderr, "Timeout waiting for magic word\n");
                    return -2;
                }
                gpioDelay(1000);
                continue;
            }
            bytes_read[0] = n;
            *index += n;
        }

        if (*index >= 8) {
            int i;
            for (i = 0; i < 8; i++) {
                if (buffer[i] != MAGIC_WORD[i]) break;
            }
            if (i == 8) {
                /* Magic word found: discard the 8 bytes and return */
                int remaining = *index - 8;
                memmove(buffer, buffer + 8, remaining);
                *index = remaining;
                return 0;
            }
            /* Shift by one byte and continue searching */
            memmove(buffer, buffer + 1, *index - 1);
            (*index)--;
            bytes_read[0] = 0;
        }
    }
    return -1;
}

/*
 * Process a complete frame after the magic word.
 * Frame layout (little-endian):
 *   uint32_t version
 *   uint32_t total_packet_len
 *   uint32_t platform
 *   uint32_t frame_number
 *   uint32_t time_subframe
 *   uint32_t chirp_profile
 *   uint32_t num_detected_obj
 *   uint32_t num_tlvs
 *   TLVs follow
 */
static void process_frame(uint8_t *buffer, int index) {
    if (index < 40) {
        fprintf(stderr, "Frame header too short\n");
        return;
    }

    uint32_t num_detected_obj = *(uint32_t *)(buffer + 32);
    uint32_t num_tlvs = *(uint32_t *)(buffer + 36);

    int offset = 40;
    int obj_count = 0;

    for (uint32_t i = 0; i < num_tlvs && !terminate; i++) {
        if (offset + 8 > index) {
            fprintf(stderr, "TLV header out of bounds\n");
            break;
        }

        uint32_t tlv_type = *(uint32_t *)(buffer + offset);
        uint32_t tlv_len = *(uint32_t *)(buffer + offset + 4);
        offset += 8;

        if (offset + tlv_len > index) {
            fprintf(stderr, "TLV payload out of bounds\n");
            break;
        }

        if (tlv_type == TLV_DETECTED_OBJECTS) {
            uint32_t num_obj = tlv_len / sizeof(DetectedObject);
            if (num_obj > num_detected_obj) num_obj = num_detected_obj;

            for (uint32_t j = 0; j < num_obj; j++) {
                DetectedObject *obj = (DetectedObject *)(buffer + offset + j * sizeof(DetectedObject));
                float range = obj->rangeIdx * 0.0436f;   /* approx meters */
                float velocity = obj->dopplerIdx * 0.0508f; /* approx m/s */
                log_data(obj_count++, range, velocity);
            }
        }
        offset += tlv_len;
    }
}

int main(void) {
    uint8_t buffer[BUFFER_SIZE];
    int index = 0;
    int bytes_read = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_csv() != 0) {
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "Radar data acquisition started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ret = sync_magic_word(buffer, &index, &bytes_read);
        if (ret == -1) {
            /* Read error or signal received during sync */
            break;
        } else if (ret == -2) {
            /* Timeout: resync by clearing buffer */
            index = 0;
            bytes_read = 0;
            continue;
        }

        /* Read the rest of the frame */
        uint32_t total_packet_len = *(uint32_t *)(buffer + 4);
        if (total_packet_len < 40 || total_packet_len > BUFFER_SIZE) {
            fprintf(stderr, "Invalid frame length %u, resyncing\n", total_packet_len);
            index = 0;
            bytes_read = 0;
            continue;
        }

        while (index < (int)total_packet_len && !terminate) {
            int n = serRead(uart_handle, (char *)(buffer + index), total_packet_len - index);
            if (n < 0) {
                fprintf(stderr, "UART read error during frame\n");
                index = 0;
                bytes_read = 0;
                break;
            }
            if (n == 0) {
                gpioDelay(1000);
                continue;
            }
            index += n;
        }

        if (index == (int)total_packet_len) {
            process_frame(buffer, index);
            index = 0;
            bytes_read = 0;
        }
    }

    cleanup();
    fprintf(stderr, "Radar data acquisition stopped.\n");
    return 0;
}

