/*
 * AWR1642 mmWave radar UART reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   AWR1642 UART_TX  -> Pi GPIO15 (RXD, /dev/serial0)
 *   AWR1642 UART_RX  -> Pi GPIO14 (TXD, /dev/serial0)
 *   AWR1642 GND      -> Pi GND
 *   AWR1642 3V3      -> Pi 3V3 (or 5V if your radar supports it)
 *
 * The AWR1642 must be configured to stream ASCII lines:
 *   <unix_timestamp_seconds>,<range_meters>\n
 * at 115200 baud, 8N1.
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar_reader radar_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B115200
#define READ_TIMEOUT_SEC 2
#define LINE_BUF_SIZE    256
#define POLL_INTERVAL_US 100000   /* 100 ms between select() calls */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Configure the UART for 115200 8N1, non-canonical mode.              */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int configure_uart(int fd)
{
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        return -1;
    }

    /* 115200 baud, 8N1, no flow control */
    if (cfsetispeed(&tty, BAUD_RATE) != 0 ||
        cfsetospeed(&tty, BAUD_RATE) != 0) {
        fprintf(stderr, "cfsetspeed failed: %s\n", strerror(errno));
        return -1;
    }

    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    tty.c_cflag |=  (CS8 | CLOCAL | CREAD);

    /* Raw input: no echo, no canonical, no special handling */
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    /* Raw output: no CR/LF translation */
    tty.c_oflag &= ~(OPOST | ONLCR);

    /* Raw control: no software flow control */
    tty.c_cflag &= ~CRTSCTS;

    /*
     * VMIN=0, VTIME=05 -> inter-byte timeout: 0.5 s.
     * VMIN=0 means "return immediately with whatever data is available".
     * VTIME=5 means "wait 0.5 s after the first byte arrives before
     * returning".  We use VMIN=0 so read() returns as soon as any data
     * arrives, then we use VTIME to enforce a 0.5 s inter-byte gap.
     */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse a complete line: <unix_timestamp>,<range_meters>\n            */
/* Returns 0 on success, -1 on parse error.                           */
/* ------------------------------------------------------------------ */
static int parse_line(const char *line, time_t *timestamp, float *range)
{
    char *endptr = NULL;
    long ts = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != ',') {
        fprintf(stderr, "Parse error: timestamp token missing or invalid\n");
        return -1;
    }
    *timestamp = (time_t)ts;

    char *range_str = endptr + 1;
    errno = 0;
    float r = strtof(range_str, &endptr);
    if (endptr == range_str || errno != 0 || *endptr != '\n') {
        fprintf(stderr, "Parse error: range token missing or invalid\n");
        return -1;
    }
    *range = r;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a valid detection with a human-readable timestamp.              */
/* ------------------------------------------------------------------ */
static void log_detection(time_t timestamp, float range)
{
    struct tm tm_info;
    char ts_buf[32];

    if (localtime_r(&timestamp, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("Timestamp: %s, Range: %.2f meters\n", ts_buf, range);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[128];

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open UART ---- */
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", UART_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Clear O_NONBLOCK so select() can block */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "fcntl F_SETFL failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (configure_uart(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("AWR1642 UART reader started on %s at 115200 8N1.\n", UART_DEVICE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        fd_set rfds;
        struct timeval tv;

        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        tv.tv_sec  = READ_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int sel = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;   /* Signal received — check g_running */
            }
            fprintf(stderr, "select() failed: %s\n", strerror(errno));
            break;
        }
        if (sel == 0) {
            /* Timeout — no data within the 2-second window */
            continue;
        }

        ssize_t n = read(fd, read_buf, sizeof(read_buf));
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;   /* No data right now — loop and re-select */
            }
            fprintf(stderr, "read() failed: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            /* Device was closed by the other end */
            fprintf(stderr, "UART closed by peer.\n");
            break;
        }

        /* Accumulate bytes into line_buf until newline */
        for (ssize_t i = 0; i < n && g_running; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                if (line_len > 0) {
                    time_t ts;
                    float  range;
                    if (parse_line(line_buf, &ts, &range) == 0) {
                        log_detection(ts, range);
                    }
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    /* Line too long — discard and reset */
                    fprintf(stderr, "Line exceeded %d bytes, discarding.\n",
                            LINE_BUF_SIZE - 1);
                    line_len = 0;
                }
            }
        }
    }

    /* ---- Cleanup ---- */
    if (fd >= 0) {
        close(fd);
    }
    printf("\nUART closed. Exiting.\n");
    return EXIT_SUCCESS;
}

