#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27

#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE    115200

static volatile sig_atomic_t g_running = 1;
static int g_serial_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_serial_handle >= 0) {
        serClose(g_serial_handle);
        g_serial_handle = -1;
    }
    gpioTerminate();
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static int send_emergency_stop(void) {
    if (g_serial_handle < 0) {
        fprintf(stderr, "Serial port not open\n");
        return -1;
    }
    if (serWrite(g_serial_handle, "EMERGENCY STOP!\n", 17) != 17) {
        fprintf(stderr, "Error writing to serial port\n");
        return -1;
    }
    return 0;
}

int main(void) {
    int left, middle, right;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    g_serial_handle = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (g_serial_handle < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", SERIAL_PORT, pigpio_error(g_serial_handle));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        left = read_sensor(LEFT_SENSOR_PIN);
        middle = read_sensor(MIDDLE_SENSOR_PIN);
        right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            log_sensor_data(left, middle, right);
            if (left == 0 && middle == 0 && right == 0) {
                send_emergency_stop();
            }
        }

        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return 0;
}

